import (
	"context"
	"fmt"
	"log"
	"os"
	"strings"

	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/gratefulagents/gratefulagents/internal/store/contentblob"
	pgstore "github.com/gratefulagents/gratefulagents/internal/store/postgres"
	"github.com/gratefulagents/gratefulagents/internal/store/sessionclient"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

// initSessionClient creates a Postgres-backed session client for the agent.
// Postgres is required — returns an error if DATABASE_URL is not set.
func initSessionClient(ctx context.Context, crdClient client.Client, runName, namespace, phase, currentStep string) (*sessionclient.Client, error) {
	dsn := strings.TrimSpace(os.Getenv("DATABASE_URL"))
	if dsn == "" {
		return nil, fmt.Errorf("DATABASE_URL is required but not set")
	}

	pool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		return nil, fmt.Errorf("connecting to Postgres: %w", err)
	}

	stateStore := pgstore.NewFromPool(pool)
	contentBlobs, err := contentblob.NewS3FromEnv()
	if err != nil {
		stateStore.Close()
		return nil, fmt.Errorf("configuring S3 project asset storage: %w", err)
	}
	stateStore.SetProjectContentBlobStore(contentBlobs)
	sc, err := sessionclient.New(ctx, stateStore, crdClient, runName, namespace, phase, currentStep)
	if err != nil {
		stateStore.Close()
		return nil, fmt.Errorf("creating session client: %w", err)
	}
	// Live session wake-up hints: optional and lossy; the message loop and
	// interrupt watcher poll faster while it is down. LISTEN only on this
	// session's channel so every agent pod is not woken by every session.
	stateStore.StartSessionChangeListenerFor(ctx, sc.SessionID())

	log.Printf("Postgres session client initialized (session=%s)", sc.SessionID())
	return sc, nil
}

package main

import (
	"strings"

	"github.com/gratefulagents/gratefulagents/internal/store"
	"github.com/gratefulagents/gratefulagents/internal/store/sessionclient"
	agent "github.com/gratefulagents/sdk/pkg/agentsdk"
)

const recentConversationMessageLimit = agent.DefaultRecentConversationLimit

func buildConversationTail(messages []store.Message, state sessionclient.WorkingState, excludeMessageID int64, limit int) []agent.RunItem {
	return agent.BuildConversationTail(toSDKConversationMessages(messages), toSDKWorkingState(state), excludeMessageID, limit)
}

// buildTurnInput selects the base conversation context for a turn: when the
// in-memory session transcript is non-empty it is replayed verbatim
// (full-transcript replay) so tool calls, outputs,
// and mid-run compaction summaries survive turn boundaries; otherwise (pod
// restart, external context clear, interrupted run) it falls back to the
// durable conversation tail. Durable messages recorded out-of-band since the
// transcript was captured are folded into the transcript by the loop before
// this replay — see outOfBandMessageItems.
func buildTurnInput(transcript []agent.RunItem, messages []store.Message, state sessionclient.WorkingState, excludeMessageID int64, limit int) []agent.RunItem {
	if len(transcript) > 0 {
		return append([]agent.RunItem(nil), transcript...)
	}
	if len(messages) == 0 {
		return nil
	}
	return buildConversationTail(messages, state, excludeMessageID, limit)
}

// transcriptAfterRun returns the in-memory session transcript to carry into
// the next turn: the runner's post-run conversation state (the input as last
// used after any mid-run compaction, plus every generated item). Interrupted
// runs end with an unresolved tool approval — an unpaired tool_use providers
// reject on replay — so they reset the transcript to the durable-tail
// fallback.
func transcriptAfterRun(result *agent.RunResult) []agent.RunItem {
	if result == nil || result.IsInterrupted() {
		return nil
	}
	return result.FinalHistory
}

// outOfBandMessageItems converts durable messages recorded after the
// in-memory transcript was last captured (ID > seenThroughID) into run
// items for transcript replay. Some UI actions record context only as
// durable messages without starting a turn — rejecting a plan appends a
// system "Plan rejected…" message, a mode switch appends an assistant
// note — so they appear in neither FinalHistory nor the current user item.
// Skipped:
//   - user messages: each is consumed by the reply queue as a turn prompt
//     or an immediate mid-run injection, so folding would duplicate it;
//   - selfAssistantMessageID: the loop's own durable append of the previous
//     turn's reply, whose content is already in FinalHistory.
func outOfBandMessageItems(messages []store.Message, seenThroughID, selfAssistantMessageID int64, state sessionclient.WorkingState) []agent.RunItem {
	newer := make([]store.Message, 0, len(messages))
	for _, msg := range messages {
		if msg.ID <= seenThroughID || msg.ID == selfAssistantMessageID || msg.Role == "user" {
			continue
		}
		newer = append(newer, msg)
	}
	if len(newer) == 0 {
		return nil
	}
	return buildConversationTail(newer, state, 0, len(newer))
}

// maxSeenMessageID advances the transcript watermark over every durable
// message visible this turn: after the input is built they are all
// represented in the model's context (transcript fold, durable tail, or the
// current user item), so future turns must not fold them again.
func maxSeenMessageID(current int64, messages []store.Message) int64 {
	for _, msg := range messages {
		if msg.ID > current {
			current = msg.ID
		}
	}
	return current
}

func buildWorkingStateContext(state sessionclient.WorkingState) string {
	return agent.BuildWorkingStateContext(toSDKWorkingState(state))
}

func deriveWorkingStateGoal(rawReply, effectivePrompt string) string {
	return agent.DeriveWorkingStateGoal(rawReply, effectivePrompt)
}

func buildAssistantTurnSummary(items []agent.RunItem) string {
	return agent.BuildAssistantTurnSummary(items)
}

func toSDKConversationMessages(messages []store.Message) []agent.ConversationMessage {
	out := make([]agent.ConversationMessage, 0, len(messages))
	for _, msg := range messages {
		out = append(out, agent.ConversationMessage{
			ID:      msg.ID,
			Role:    msg.Role,
			Content: msg.Content,
		})
	}
	return out
}

func toSDKWorkingState(state sessionclient.WorkingState) agent.WorkingState {
	return agent.WorkingState{
		Goal:                  state.Goal,
		CurrentMode:           state.CurrentMode,
		LastUserMessage:       state.LastUserMessage,
		LastAssistantSummary:  state.LastAssistantSummary,
		RecentTurnSummaries:   append([]string(nil), state.RecentTurnSummaries...),
		HistoryFloorMessageID: state.HistoryFloorMessageID,
		LastResponseID:        state.LastResponseID,
	}
}

func dedupeNonEmptyStrings(values []string) []string {
	seen := map[string]struct{}{}
	out := make([]string, 0, len(values))
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value == "" {
			continue
		}
		if _, ok := seen[value]; ok {
			continue
		}
		seen[value] = struct{}{}
		out = append(out, value)
	}
	return out
}

package main

import (
	"strings"

	"github.com/gratefulagents/gratefulagents/internal/store/sessionclient"
	agent "github.com/gratefulagents/sdk/pkg/agentsdk"
)

func nextPendingUserMessage(messages []sessionclient.UserMessage, consumedImmediate map[int64]struct{}) (sessionclient.UserMessage, bool, int64, bool) {
	msg, ok, skipCursor, immediate := agent.SelectNextUserMessage(toSDKUserMessages(messages), consumedImmediate)
	if !ok {
		return sessionclient.UserMessage{}, false, skipCursor, immediate
	}
	for _, original := range messages {
		if original.ID == msg.ID {
			return original, true, skipCursor, immediate
		}
	}
	return sessionclient.UserMessage{}, false, skipCursor, immediate
}

// nextTurnStartingUserMessage selects the message that opens a new turn when
// no turn is running: the oldest pending message with content, in creation
// order. Unlike nextPendingUserMessage it gives immediate (steering) messages
// no priority — steering only means "interrupt the work in progress", and at a
// turn boundary there is nothing to interrupt. Letting an immediate message
// jump ahead here inverts the conversation at startup: a steer typed while the
// sandbox was still provisioning would become the turn prompt, leaving the
// seeded kickoff request pending until the agent finished and then re-running
// it as a second turn. Any immediate message queued behind the selected prompt
// is left untouched; the runner's ImmediateInputPoller folds it into the same
// turn before the first model call.
//
// Immediate messages already folded into a previous turn (handledImmediate)
// are skipped. The returned bool reports whether the selection is immediate so
// callers can record it in handledImmediate once the claim succeeds.
func nextTurnStartingUserMessage(messages []sessionclient.UserMessage, handledImmediate map[int64]struct{}) (sessionclient.UserMessage, bool, bool) {
	for _, msg := range messages {
		if strings.TrimSpace(msg.Content) == "" && len(msg.Images) == 0 {
			continue
		}
		immediate := msg.Mode == sessionclient.UserMessageModeImmediate
		if immediate {
			if _, seen := handledImmediate[msg.ID]; seen {
				continue
			}
		}
		return msg, true, immediate
	}
	return sessionclient.UserMessage{}, false, false
}

// withoutStoppedMessage drops the prompt the user explicitly stopped
// (WorkingState.LastStoppedUserMessageID) from a queue snapshot. Every stop
// path completes that message's claim, but if the completion was lost the
// replacement pod's RecoverClaimedUserMessages hands the prompt back as
// pending — and re-running a stopped prompt is exactly what the user asked
// not to happen. Only that one ID is removed: an earlier queued message can
// legitimately still be pending (a later immediate steer is selected ahead
// of it), so this is deliberately not an ID floor.
func withoutStoppedMessage(messages []sessionclient.UserMessage, stoppedMessageID int64) []sessionclient.UserMessage {
	if stoppedMessageID == 0 {
		return messages
	}
	out := make([]sessionclient.UserMessage, 0, len(messages))
	for _, msg := range messages {
		if msg.ID == stoppedMessageID {
			continue
		}
		out = append(out, msg)
	}
	return out
}

// collectImmediateRunItems converts unconsumed immediate user messages into run
// items. Alongside the SDK result it reports which message IDs were newly
// consumed so the caller can record their delivery.
func collectImmediateRunItems(messages []sessionclient.UserMessage, consumedImmediate map[int64]struct{}) ([]agent.RunItem, []int64, int64) {
	probe := make(map[int64]struct{}, len(consumedImmediate))
	for id := range consumedImmediate {
		probe[id] = struct{}{}
	}
	items, cursor := agent.CollectImmediateRunItems(toSDKUserMessages(messages), probe)
	var consumedIDs []int64
	for _, msg := range messages {
		if _, already := consumedImmediate[msg.ID]; already {
			continue
		}
		if _, selected := probe[msg.ID]; selected {
			consumedIDs = append(consumedIDs, msg.ID)
		}
	}
	return items, consumedIDs, cursor
}

func toSDKUserMessages(messages []sessionclient.UserMessage) []agent.UserMessage {
	out := make([]agent.UserMessage, 0, len(messages))
	for _, msg := range messages {
		out = append(out, agent.UserMessage{
			ID:      msg.ID,
			Content: msg.Content,
			Mode:    string(msg.Mode),
			Images:  toSDKImageAttachments(msg.Images),
		})
	}
	return out
}

// toSDKImageAttachments converts stored message images into SDK image
// attachments for delivery to vision-capable models.
func toSDKImageAttachments(images []sessionclient.MessageImage) []agent.ImageAttachment {
	if len(images) == 0 {
		return nil
	}
	out := make([]agent.ImageAttachment, 0, len(images))
	for _, img := range images {
		if img.Data == "" {
			continue
		}
		out = append(out, agent.ImageAttachment{
			MediaType: img.MediaType,
			Data:      img.Data,
		})
	}
	return out
}

package main

import (
	"reflect"
	"strings"

	agent "github.com/gratefulagents/sdk/pkg/agentsdk"
)

type loadedSkillInstructionSource interface {
	LoadedInstructions() string
}

func isNilLoadedSkillInstructionSource(source loadedSkillInstructionSource) bool {
	if source == nil {
		return true
	}
	value := reflect.ValueOf(source)
	switch value.Kind() {
	case reflect.Chan, reflect.Func, reflect.Interface, reflect.Map, reflect.Pointer, reflect.Slice:
		return value.IsNil()
	default:
		return false
	}
}

// attachLoadedSkillInstructions keeps skill guidance out of the base prompt
// until load_skill has selected it. InstructionsFn is evaluated for every SDK
// model turn, including the turn immediately after the tool call.
func attachLoadedSkillInstructions(target *agent.Agent, source loadedSkillInstructionSource) {
	if target == nil || isNilLoadedSkillInstructionSource(source) {
		return
	}
	baseInstructions, baseInstructionsFn := target.Instructions, target.InstructionsFn
	target.InstructionsFn = func(runCtx *agent.RunContext, current *agent.Agent) string {
		instructions := baseInstructions
		if baseInstructionsFn != nil {
			instructions = baseInstructionsFn(runCtx, current)
		}
		if loaded := source.LoadedInstructions(); loaded != "" {
			instructions = strings.TrimSpace(instructions + "\n\n" + loaded)
		}
		return instructions
	}
}

package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"strings"
	"sync/atomic"
	"syscall"
	"time"

	slackgo "github.com/slack-go/slack"
	"github.com/slack-go/slack/slackevents"
	"github.com/slack-go/slack/socketmode"

	internalslack "github.com/gratefulagents/gratefulagents/internal/slack"
)

// slackConnectorConfig is resolved from the connector pod's environment. The
// SlackAgent controller injects these (tokens from the referenced Secret, name
// + namespace identifying the owning CR).
type slackConnectorConfig struct {
	AgentName   string
	Namespace   string
	BotToken    string
	UserToken   string
	AppToken    string
	HealthAddr  string
	SlackUserID string
	TeamID      string
	Commanders  []string
	SessionIdle time.Duration
	BatchWindow time.Duration
}

// defaultSlackSessionIdle is the fallback conversation idle window: after this
// much inactivity a new incoming message starts a fresh AgentRun instead of
// resuming the previous one, bounding a conversation's context and cost.
const defaultSlackSessionIdle = 12 * time.Hour

// defaultSlackBatchWindow is how long the connector waits for more messages in a
// conversation before answering, so a rapid burst ("what's the time in japan" /
// "and in usa") is handled as one turn with one reply instead of racing.
const defaultSlackBatchWindow = 4 * time.Second

// slackAppContextChangedEvent bridges the Agent messaging experience event
// until slack-go exposes a typed equivalent. Registering it keeps Socket Mode
// from rejecting the otherwise unknown event before the connector can ACK it.
type slackAppContextChangedEvent struct {
	Type string `json:"type"`
}

// slackSessionStoppedEvent is the agent_session_stopped Events API payload: a
// user clicked the native stop button on an agent session while the app had
// it in the processing state. slack-go has no typed equivalent yet.
type slackSessionStoppedEvent struct {
	Type      string   `json:"type"`
	Channel   string   `json:"channel"`
	ThreadTS  string   `json:"thread_ts"`
	User      string   `json:"user"`
	EventTS   string   `json:"event_ts"`
	StreamTSs []string `json:"streaming_message_ts"`
}

// slackSessionStoppedEventType is the Events API type name of the stop event.
const slackSessionStoppedEventType = "agent_session_stopped"

func init() {
	eventType := slackevents.EventsAPIType("app_context_changed")
	if _, supported := slackevents.EventsAPIInnerEventMapping[eventType]; !supported {
		slackevents.EventsAPIInnerEventMapping[eventType] = slackAppContextChangedEvent{}
	}
	stopType := slackevents.EventsAPIType(slackSessionStoppedEventType)
	if _, supported := slackevents.EventsAPIInnerEventMapping[stopType]; !supported {
		slackevents.EventsAPIInnerEventMapping[stopType] = slackSessionStoppedEvent{}
	}
}

func loadSlackConnectorConfig() (slackConnectorConfig, error) {
	cfg := slackConnectorConfig{
		AgentName:   strings.TrimSpace(os.Getenv("SLACK_AGENT_NAME")),
		Namespace:   strings.TrimSpace(os.Getenv("POD_NAMESPACE")),
		BotToken:    strings.TrimSpace(os.Getenv("SLACK_BOT_TOKEN")),
		UserToken:   strings.TrimSpace(os.Getenv("SLACK_USER_TOKEN")),
		AppToken:    strings.TrimSpace(os.Getenv("SLACK_APP_TOKEN")),
		SlackUserID: strings.TrimSpace(os.Getenv("SLACK_USER_ID")),
		TeamID:      strings.TrimSpace(os.Getenv("SLACK_TEAM_ID")),
		HealthAddr:  strings.TrimSpace(os.Getenv("SLACK_HEALTH_ADDR")),
		Commanders:  slackEnvList("SLACK_COMMANDERS"),
		SessionIdle: slackSessionIdle("SLACK_SESSION_IDLE_MINUTES"),
		BatchWindow: slackBatchWindow("SLACK_BATCH_WINDOW_MS"),
	}
	if cfg.HealthAddr == "" {
		cfg.HealthAddr = ":8080"
	}
	if cfg.AppToken == "" {
		return cfg, errors.New("SLACK_APP_TOKEN (xapp-) is required for Socket Mode")
	}
	if cfg.BotToken == "" {
		return cfg, errors.New("SLACK_BOT_TOKEN (xoxb-) is required")
	}
	return cfg, nil
}

// slackSessionIdle parses a minutes env var into a duration, falling back to
// defaultSlackSessionIdle when unset or non-positive.
func slackSessionIdle(name string) time.Duration {
	if v, err := strconv.Atoi(strings.TrimSpace(os.Getenv(name))); err == nil && v > 0 {
		return time.Duration(v) * time.Minute
	}
	return defaultSlackSessionIdle
}

// slackBatchWindow parses a milliseconds env var into a duration, falling back to
// defaultSlackBatchWindow when unset or non-positive.
func slackBatchWindow(name string) time.Duration {
	if v, err := strconv.Atoi(strings.TrimSpace(os.Getenv(name))); err == nil && v > 0 {
		return time.Duration(v) * time.Millisecond
	}
	return defaultSlackBatchWindow
}

// slackEnvList parses a comma-separated env var into a trimmed, non-empty slice.
func slackEnvList(name string) []string {
	raw := strings.TrimSpace(os.Getenv(name))
	if raw == "" {
		return nil
	}
	var out []string
	for part := range strings.SplitSeq(raw, ",") {
		if p := strings.TrimSpace(part); p != "" {
			out = append(out, p)
		}
	}
	return out
}

// runSlack is the entrypoint for `agent slack`. It serves two modes: the
// dedicated per-user connector (one Slack app per SlackAgent) and, when
// SLACK_WORKSPACE_NAME is set, the shared workspace connector (one Slack app
// serving every member SlackAgent). Socket Mode load-balances events across an
// app's open sockets, so each app's events must be consumed by exactly one
// process — which is why a shared app gets one connector that routes per user.
func runSlack() error {
	if strings.TrimSpace(os.Getenv("SLACK_WORKSPACE_NAME")) != "" {
		return runSlackWorkspace()
	}
	cfg, err := loadSlackConnectorConfig()
	if err != nil {
		log.Printf("ERROR: slack connector config: %v", err)
		return err
	}

	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGTERM, os.Interrupt)
	defer stop()

	webClient, err := internalslack.New(internalslack.Tokens{
		BotToken:  cfg.BotToken,
		UserToken: cfg.UserToken,
		AppToken:  cfg.AppToken,
	})
	if err != nil {
		log.Printf("ERROR: building slack client: %v", err)
		return err
	}

	botIdentity, err := webClient.AuthTestBot(ctx)
	if err != nil {
		log.Printf("ERROR: validating bot token: %v", err)
		return err
	}
	if botIdentity.TeamID == "" {
		return fmt.Errorf("slack bot auth.test returned no team ID")
	}
	if cfg.TeamID != "" && botIdentity.TeamID != cfg.TeamID {
		return fmt.Errorf(
			"slack connector is pinned to team %s but bot token belongs to team %s",
			cfg.TeamID,
			botIdentity.TeamID,
		)
	}
	log.Printf("slack connector %s/%s authenticated as bot user=%s team=%s",
		cfg.Namespace, cfg.AgentName, botIdentity.UserID, botIdentity.TeamID)

	backend := &dedicatedSlackBackend{
		cfg: cfg, web: webClient, botUserID: botIdentity.UserID,
		ownerUserID: cfg.SlackUserID, teamID: botIdentity.TeamID,
	}

	// A user token is optional (it powers slack_search and owner resolution).
	// When supplied it must identify the same workspace and, when explicitly
	// configured, the same owner; mixed credentials fail closed at startup.
	if webClient.HasUser() {
		userIdentity, uerr := webClient.AuthTestUser(ctx)
		if uerr != nil {
			return fmt.Errorf("validating slack user token: %w", uerr)
		}
		if userIdentity.TeamID != backend.teamID {
			return fmt.Errorf(
				"slack bot token belongs to team %s but user token belongs to team %s",
				backend.teamID,
				userIdentity.TeamID,
			)
		}
		if backend.ownerUserID != "" && userIdentity.UserID != backend.ownerUserID {
			return fmt.Errorf(
				"slack user token belongs to %s but configured owner is %s",
				userIdentity.UserID,
				backend.ownerUserID,
			)
		}
		backend.ownerUserID = userIdentity.UserID
		log.Printf("slack connector owner user=%s", backend.ownerUserID)
	}

	// Resolve the owner<->bot control DM so the router can tell owner commands
	// apart from other conversations. Best-effort: command routing still gates
	// on the sender being the owner without it.
	if backend.ownerUserID != "" {
		if dm, derr := webClient.OpenIMWithUser(ctx, backend.ownerUserID); derr != nil {
			log.Printf("WARN: slack connector %s: could not resolve bot DM channel: %v", cfg.AgentName, derr)
		} else {
			backend.botDMChannelID = dm
		}
	}

	// The orchestrator turns owner commands into AgentRuns and streams replies
	// back. It needs Postgres + the CRD client; if unavailable, the connector
	// still runs (events are logged) so the socket and health stay up.
	if orch, oerr := newSlackOrchestrator(ctx, cfg, webClient); oerr != nil {
		log.Printf("WARN: slack connector %s: command handling disabled: %v", cfg.AgentName, oerr)
	} else {
		orch.ownerUserID = backend.ownerUserID
		orch.teamID = backend.teamID
		orch.setBotDMChannelID(backend.botDMChannelID)
		backend.orch = orch
		startSlackEventPruner(ctx, orch.queries)
		defer func() { _ = orch.store.Close() }()
	}

	conn := &slackConnector{
		name:       cfg.AgentName,
		healthAddr: cfg.HealthAddr,
		botToken:   cfg.BotToken,
		appToken:   cfg.AppToken,
		backend:    backend,
	}

	healthSrv := conn.startHealthServer()
	defer func() {
		shutdownCtx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
		defer cancel()
		_ = healthSrv.Shutdown(shutdownCtx)
	}()

	conn.run(ctx)
	return nil
}

// slackBackend routes decoded Slack events to the owning orchestrator(s). The
// dedicated backend serves a single SlackAgent; the workspace backend serves
// every member of a shared SlackWorkspace app.
type slackBackend interface {
	// handleMessage classifies and acts on a normalized inbound message.
	handleMessage(ctx context.Context, msg internalslack.InboundMessage)
	// handleInteraction dispatches a Block Kit interaction to its owner.
	handleInteraction(ctx context.Context, callback slackgo.InteractionCallback)
	// handleAssistantStarted greets a user who opened the assistant pane.
	handleAssistantStarted(ctx context.Context, e *slackevents.AssistantThreadStartedEvent)
	// handleAssistantContextChanged tracks the channel a user is viewing.
	handleAssistantContextChanged(thread slackevents.AssistantThread)
	// handleSessionStopped stops the work behind an agent session after the
	// user clicked Slack's native stop button.
	handleSessionStopped(ctx context.Context, e *slackSessionStoppedEvent)
	// handleAppHome refreshes the App Home tab for the given user.
	handleAppHome(ctx context.Context, userID string)
	// allowTeam reports whether events from this Slack team may be processed.
	allowTeam(teamID string) bool
}

// slackConnector owns the Socket Mode connection lifecycle for one Slack app
// and forwards decoded events to its backend.
type slackConnector struct {
	name       string
	healthAddr string
	botToken   string
	appToken   string
	connected  atomic.Bool
	backend    slackBackend
	eventSlots chan struct{}
}

// startHealthServer exposes /healthz (always 200 once the process is up) and
// /readyz (200 only while the Socket Mode connection is live) so the connector
// Deployment can use them as liveness/readiness probes.
func (c *slackConnector) startHealthServer() *http.Server {
	mux := http.NewServeMux()
	mux.HandleFunc("/healthz", func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusOK)
	})
	mux.HandleFunc("/readyz", func(w http.ResponseWriter, _ *http.Request) {
		if c.connected.Load() {
			w.WriteHeader(http.StatusOK)
			return
		}
		http.Error(w, "socket not connected", http.StatusServiceUnavailable)
	})
	srv := &http.Server{Addr: c.healthAddr, Handler: mux, ReadHeaderTimeout: 5 * time.Second}
	go func() {
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Printf("WARN: slack connector health server: %v", err)
		}
	}()
	return srv
}

// run connects via Socket Mode and consumes events until the context is
// cancelled. socketmode.RunContext reconnects internally with backoff; if it
// returns due to a fatal error we retry with our own backoff unless shutting
// down.
func (c *slackConnector) run(ctx context.Context) {
	api := slackgo.New(c.botToken, slackgo.OptionAppLevelToken(c.appToken))
	sm := socketmode.New(api)

	go c.consume(ctx, sm)

	backoff := time.Second
	for {
		if ctx.Err() != nil {
			return
		}
		err := sm.RunContext(ctx)
		if ctx.Err() != nil {
			return
		}
		c.connected.Store(false)
		log.Printf("WARN: slack socket mode loop exited (%v); reconnecting in %s", err, backoff)
		select {
		case <-ctx.Done():
			return
		case <-time.After(backoff):
		}
		if backoff < 30*time.Second {
			backoff *= 2
		}
	}
}

// consume drains the Socket Mode event channel, tracking connection state and
// acking inbound requests. Phase 0 acks and logs; later phases dispatch
// events_api / interactive / slash_commands to handlers.
func (c *slackConnector) consume(ctx context.Context, sm *socketmode.Client) {
	for {
		select {
		case <-ctx.Done():
			return
		case evt, ok := <-sm.Events:
			if !ok {
				return
			}
			c.handleSocketEvent(ctx, sm, evt)
		}
	}
}

const slackEventConcurrency = 64

func (c *slackConnector) dispatchAsync(ctx context.Context, fn func()) {
	if c.eventSlots == nil {
		c.eventSlots = make(chan struct{}, slackEventConcurrency)
	}
	select {
	case c.eventSlots <- struct{}{}:
	case <-ctx.Done():
		return
	}
	go func() {
		defer func() { <-c.eventSlots }()
		fn()
	}()
}

func (c *slackConnector) handleSocketEvent(ctx context.Context, sm *socketmode.Client, evt socketmode.Event) {
	switch evt.Type {
	case socketmode.EventTypeConnecting:
		log.Printf("slack connector %s connecting…", c.name)
	case socketmode.EventTypeConnected:
		c.connected.Store(true)
		log.Printf("slack connector %s connected", c.name)
	case socketmode.EventTypeHello:
		// Connection handshake completed.
	case socketmode.EventTypeDisconnect:
		c.connected.Store(false)
		log.Printf("slack connector %s disconnected", c.name)
	case socketmode.EventTypeInvalidAuth:
		c.connected.Store(false)
		log.Printf("ERROR: slack connector %s invalid auth (check app/bot tokens)", c.name)
	case socketmode.EventTypeConnectionError, socketmode.EventTypeIncomingError, socketmode.EventTypeErrorWriteFailed, socketmode.EventTypeErrorBadMessage:
		log.Printf("WARN: slack connector %s transport event: %s", c.name, evt.Type)
	case socketmode.EventTypeEventsAPI:
		// Ack first so Slack does not retry; then process off the consume loop so
		// run creation / streaming never blocks event intake.
		if evt.Request != nil {
			if err := sm.Ack(*evt.Request); err != nil {
				log.Printf("WARN: ack %s envelope=%s: %v", evt.Type, evt.Request.EnvelopeID, err)
			}
		}
		c.dispatchAsync(ctx, func() { c.handleEventsAPI(ctx, evt) })
	case socketmode.EventTypeInteractive:
		if evt.Request != nil {
			if err := sm.Ack(*evt.Request); err != nil {
				log.Printf("WARN: ack %s envelope=%s: %v", evt.Type, evt.Request.EnvelopeID, err)
			}
		}
		c.dispatchAsync(ctx, func() { c.handleInteractive(ctx, evt) })
	case socketmode.EventTypeSlashCommand:
		if evt.Request != nil {
			if err := sm.Ack(*evt.Request); err != nil {
				log.Printf("WARN: ack %s envelope=%s: %v", evt.Type, evt.Request.EnvelopeID, err)
			}
		}
		// TODO(phase1-refine): slash-command entrypoint.
		log.Printf("slack connector %s received %s event (handler pending)", c.name, evt.Type)
	default:
		// Ignore other internal event types.
	}
}

// handleInteractive dispatches Block Kit interactions (draft approve/dismiss).
func (c *slackConnector) handleInteractive(ctx context.Context, evt socketmode.Event) {
	callback, ok := evt.Data.(slackgo.InteractionCallback)
	if !ok {
		log.Printf("WARN: slack connector %s: unexpected interactive payload type %T", c.name, evt.Data)
		return
	}
	if !c.backend.allowTeam(callback.Team.ID) {
		log.Printf("WARN: slack connector %s: dropping interaction from foreign team %s", c.name, callback.Team.ID)
		return
	}
	c.backend.handleInteraction(ctx, callback)
}

// handleEventsAPI decodes a Slack Events API envelope and dispatches it. Agent
// view apps use app_home_opened plus message.im/app_context_changed; legacy
// assistant lifecycle events remain supported while existing apps migrate.
func (c *slackConnector) handleEventsAPI(ctx context.Context, evt socketmode.Event) {
	apiEvent, ok := evt.Data.(slackevents.EventsAPIEvent)
	if !ok {
		log.Printf("WARN: slack connector %s: unexpected events_api payload type %T", c.name, evt.Data)
		return
	}
	if !c.backend.allowTeam(apiEvent.TeamID) {
		log.Printf("WARN: slack connector %s: dropping event from foreign team %s", c.name, apiEvent.TeamID)
		return
	}
	switch inner := apiEvent.InnerEvent.Data.(type) {
	case *slackevents.AssistantThreadStartedEvent:
		c.backend.handleAssistantContextChanged(inner.AssistantThread)
		c.backend.handleAssistantStarted(ctx, inner)
		return
	case *slackevents.AssistantThreadContextChangedEvent:
		// Track the channel the user is viewing so "this channel" style requests
		// resolve to it.
		c.backend.handleAssistantContextChanged(inner.AssistantThread)
		return
	case *slackevents.AppHomeOpenedEvent:
		switch inner.Tab {
		case "home":
			c.backend.handleAppHome(ctx, inner.User)
		case "messages":
			// This is the Agent view signal that the user opened the app DM.
			// Suggested prompts are pinned globally by the app manifest, so no
			// per-open Web API call or repetitive greeting is needed.
		}
		return
	case *slackAppContextChangedEvent:
		// Subscribing enables app_context on message.im events. We consume that
		// point-in-time context below instead of retaining these ambient updates.
		return
	case *slackSessionStoppedEvent:
		c.backend.handleSessionStopped(ctx, inner)
		return
	}
	msg, ok := inboundFromInnerEvent(apiEvent.InnerEvent.Data)
	if !ok {
		return // not a message-like event we route
	}
	// Fail closed when the envelope is unavailable: bot-DM gating (owner only)
	// is the conservative default; events from a legacy user-token subscription
	// always carry an authorizations array identifying their subscription.
	msg.ViaBotEvent = true
	if evt.Request != nil {
		msg.ViaBotEvent = slackEventViaBot(evt.Request.Payload)
	}
	if evt.Request != nil {
		msg.ContextChannelID = slackEventContextChannel(evt.Request.Payload)
		if len(msg.Files) == 0 {
			// slack-go's MessageEvent drops the files array (only app_mention carries
			// it), so re-parse the raw envelope for attachments.
			msg.Files = slackEventFiles(evt.Request.Payload)
		}
	}
	c.backend.handleMessage(ctx, msg)
}

// inboundFromInnerEvent normalizes a slack-go inner event into the
// transport-agnostic InboundMessage the router understands. It returns false for
// event types the connector does not route.
func inboundFromInnerEvent(inner any) (internalslack.InboundMessage, bool) {
	switch e := inner.(type) {
	case *slackevents.MessageEvent:
		return internalslack.InboundMessage{
			ChannelType: e.ChannelType,
			ChannelID:   e.Channel,
			UserID:      e.User,
			BotID:       e.BotID,
			Text:        e.Text,
			TS:          e.TimeStamp,
			ThreadTS:    e.ThreadTimeStamp,
			SubType:     e.SubType,
		}, true
	case *slackevents.AppMentionEvent:
		return internalslack.InboundMessage{
			ChannelType:  "channel",
			ChannelID:    e.Channel,
			UserID:       e.User,
			BotID:        e.BotID,
			Text:         e.Text,
			TS:           e.TimeStamp,
			ThreadTS:     e.ThreadTimeStamp,
			IsAppMention: true,
			Files:        filesFromSlack(e.Files),
		}, true
	default:
		return internalslack.InboundMessage{}, false
	}
}

// slackEventViaBot reports whether a raw Events API envelope includes the bot's
// own event subscription (any authorizations[].is_bot) rather than only
// user-token subscriptions a legacy app manifest may still carry. Slack includes
// the authorizations array in every Events API delivery; if it is ever absent
// or unparseable this reports true so DMs with the bot stay gated on the owner
// (fail closed) while legacy user-token events are ignored by the router.
func slackEventViaBot(payload json.RawMessage) bool {
	if len(payload) == 0 {
		return true
	}
	var envelope struct {
		Authorizations []struct {
			IsBot bool `json:"is_bot"`
		} `json:"authorizations"`
	}
	if err := json.Unmarshal(payload, &envelope); err != nil || len(envelope.Authorizations) == 0 {
		return true
	}
	for _, authorization := range envelope.Authorizations {
		if authorization.IsBot {
			return true
		}
	}
	return false
}

// slackEventFiles extracts file attachments from a raw Events API envelope
// payload (the `event.files` array), used for message events where slack-go's
// typed struct drops them.
func slackEventFiles(payload json.RawMessage) []internalslack.File {
	if len(payload) == 0 {
		return nil
	}
	var envelope struct {
		Event struct {
			Files []slackgo.File `json:"files"`
		} `json:"event"`
	}
	if err := json.Unmarshal(payload, &envelope); err != nil {
		return nil
	}
	return filesFromSlack(envelope.Event.Files)
}

// slackEventContextChannel returns the most relevant channel from the
// app_context attached to an Agent view message. Slack orders entities by
// relevance and may represent a channel either directly or through a message
// context. Other entity types are intentionally ignored.
func slackEventContextChannel(payload json.RawMessage) string {
	if len(payload) == 0 {
		return ""
	}
	var envelope struct {
		Event struct {
			AppContext struct {
				Entities []struct {
					Type  string          `json:"type"`
					Value json.RawMessage `json:"value"`
				} `json:"entities"`
			} `json:"app_context"`
		} `json:"event"`
	}
	if err := json.Unmarshal(payload, &envelope); err != nil {
		return ""
	}
	for _, entity := range envelope.Event.AppContext.Entities {
		switch entity.Type {
		case "slack#/types/channel_id":
			var channelID string
			if json.Unmarshal(entity.Value, &channelID) == nil && channelID != "" {
				return channelID
			}
		case "slack#/types/message_context":
			var message struct {
				ChannelID string `json:"channel_id"`
			}
			if json.Unmarshal(entity.Value, &message) == nil && message.ChannelID != "" {
				return message.ChannelID
			}
		}
	}
	return ""
}

// filesFromSlack converts slack-go file records to the transport-agnostic view.
func filesFromSlack(files []slackgo.File) []internalslack.File {
	if len(files) == 0 {
		return nil
	}
	out := make([]internalslack.File, 0, len(files))
	for _, f := range files {
		out = append(out, internalslack.File{
			ID:         f.ID,
			Name:       f.Name,
			Mimetype:   f.Mimetype,
			Filetype:   f.Filetype,
			Size:       f.Size,
			URLPrivate: f.URLPrivate,
		})
	}
	return out
}

package main

import (
	"context"
	"log"

	internalslack "github.com/gratefulagents/gratefulagents/internal/slack"
	slackgo "github.com/slack-go/slack"
	"github.com/slack-go/slack/slackevents"
)

// dedicatedSlackBackend serves a single SlackAgent with its own dedicated Slack
// app: every event on the socket belongs to this one owner.
type dedicatedSlackBackend struct {
	cfg         slackConnectorConfig
	web         *internalslack.Client
	botUserID   string
	ownerUserID string
	teamID      string
	// botDMChannelID is the owner<->bot control DM, resolved at startup.
	botDMChannelID string
	// orch handles owner commands (create/wake AgentRuns, stream replies). It is
	// nil when its dependencies (Postgres/CRD client) are unavailable.
	orch *slackOrchestrator
}

// allowTeam rejects events and interactions that do not match the workspace
// authenticated by the bot token. This also fails closed if an app-level token
// from another Slack app is accidentally combined with the connection.
func (b *dedicatedSlackBackend) allowTeam(teamID string) bool {
	return b.teamID != "" && teamID == b.teamID
}

// routerConfig snapshots the identities the router needs for the current event.
func (b *dedicatedSlackBackend) routerConfig() internalslack.RouterConfig {
	return internalslack.RouterConfig{
		OwnerUserID:    b.ownerUserID,
		BotUserID:      b.botUserID,
		BotDMChannelID: b.botDMChannelID,
		Commanders:     b.cfg.Commanders,
	}
}

func (b *dedicatedSlackBackend) handleMessage(ctx context.Context, msg internalslack.InboundMessage) {
	dispatchSlackDecision(ctx, b.web, b.cfg.AgentName, b.orch, internalslack.Route(msg, b.routerConfig()))
}

func (b *dedicatedSlackBackend) handleInteraction(ctx context.Context, callback slackgo.InteractionCallback) {
	if b.orch == nil {
		return
	}
	b.orch.handleInteraction(ctx, callback)
}

// handleAssistantContextChanged remembers which channel the user is viewing
// alongside an assistant-pane thread so the orchestrator can inject it into run
// context.
func (b *dedicatedSlackBackend) handleAssistantContextChanged(thread slackevents.AssistantThread) {
	if b.orch == nil || thread.ChannelID == "" || thread.ThreadTimeStamp == "" {
		return
	}
	b.orch.setAssistantContext(thread.ChannelID, thread.ThreadTimeStamp, thread.Context.ChannelID)
}

// handleAssistantStarted greets the user when they open the assistant pane and
// offers suggested prompts.
func (b *dedicatedSlackBackend) handleAssistantStarted(
	ctx context.Context, e *slackevents.AssistantThreadStartedEvent,
) {
	const greeting = "Hi! I'm your agent. Ask me to do something, or pick a prompt below."
	postAssistantGreeting(ctx, b.web, b.cfg.AgentName, e, greeting)
}

// handleSessionStopped forwards Slack's stop button to the orchestrator, which
// interrupts the thread's run.
func (b *dedicatedSlackBackend) handleSessionStopped(ctx context.Context, e *slackSessionStoppedEvent) {
	if b.orch == nil {
		return
	}
	b.orch.handleSessionStopped(ctx, e)
}

func (b *dedicatedSlackBackend) handleAppHome(ctx context.Context, userID string) {
	if b.orch == nil {
		return
	}
	b.orch.handleAppHome(ctx, userID)
}

// dispatchSlackDecision acts on a routing decision by enqueuing it to the
// owning orchestrator's conversation worker, which serializes and coalesces the
// conversation's turns. Shared by the dedicated and workspace backends.
func dispatchSlackDecision(
	ctx context.Context, web *internalslack.Client, name string, orch *slackOrchestrator, d internalslack.Decision,
) {
	switch d.Kind {
	case internalslack.RouteCommand:
		if orch == nil {
			log.Printf("slack connector %s: %s in %s ignored (handling disabled)", name, d.Kind, d.ChannelID)
			return
		}
		// Dedupe Slack redeliveries of the same message so a retry doesn't spawn
		// a second run.
		if !orch.claimEvent(ctx, d.ChannelID, d.MessageTS) {
			log.Printf("slack connector %s: skipping already-handled message %s/%s", name, d.ChannelID, d.MessageTS)
			return
		}
		orch.enqueueConversation(ctx, d)
	case internalslack.RouteDecline:
		// Explicit invocation by someone not allowed to command this agent.
		// Stay completely silent — no reply, no ephemeral — so the agent never
		// reveals itself or its policy to unauthorized senders. The decline is
		// only logged (including ReasonOwnerUnknown, which means the connector
		// has no owner Slack user ID configured and declines everyone).
		log.Printf("slack connector %s: silently declined message from %s in %s (%s)",
			name, d.UserID, d.ChannelID, d.Reason)
	default:
		log.Printf("slack connector %s: ignored message in %s (%s)", name, d.ChannelID, d.Reason)
	}
}

// postAssistantGreeting posts the assistant-pane greeting plus suggested
// prompts. Shared by both backends.
func postAssistantGreeting(
	ctx context.Context, web *internalslack.Client, name string,
	e *slackevents.AssistantThreadStartedEvent, greeting string,
) {
	channelID := e.AssistantThread.ChannelID
	threadTS := e.AssistantThread.ThreadTimeStamp
	if channelID == "" || threadTS == "" {
		return
	}
	if _, err := web.PostMessageAsBot(ctx, channelID, greeting, threadTS); err != nil {
		log.Printf("slack connector %s: assistant greeting: %v", name, err)
	}
	prompts := []internalslack.AssistantPrompt{
		{Title: "What needs my attention?", Message: "What in my Slack needs my attention right now?"},
		{Title: "Draft a reply", Message: "Help me draft a reply to my most recent DM."},
		{Title: "Summarize a channel", Message: "Summarize the recent activity in the channel I'm viewing."},
	}
	if err := web.SetAssistantSuggestedPrompts(ctx, channelID, threadTS, "Try one of these", prompts); err != nil {
		log.Printf("slack connector %s: set suggested prompts: %v", name, err)
	}
}

