const workspaceScratchDir = "/workspace/scratch"

// skipReadOnlyCheckpointRestore reports whether the pod should keep its fresh
// base-branch clone instead of rewinding to the previous pod's checkpoint. Only
// runs that are read-only by configuration qualify; a degraded read-only
// fallback of a write-capable run may still hold WIP worth restoring.
func skipReadOnlyCheckpointRestore(cfg *runConfig) bool {
	return cfg != nil && cfg.WorkspaceCheckpoint != nil &&
		!cfg.PermissionMode.AllowsWriteTools() && !cfg.PermissionModeDegraded
}

// setupWorkspace clones the repo and builds the task context.
func setupWorkspace(cfg *runConfig) error {
	log.Println("Setting up workspace...")

	if err := agentinfra.SetupGHAuth(cfg.GithubToken); err != nil {
		return fmt.Errorf("setting up gh auth: %w", err)
	}

	if cfg.Repoless {
		return setupRepolessWorkspace(cfg)
	}

	log.Printf("Cloning %s...", cfg.RepoURL)
	if err := agentinfra.GitExec("", "clone", "--branch", cfg.BaseBranch, cfg.RepoURL, cfg.RepoDir); err != nil {
		return fmt.Errorf("cloning repo: %w", err)
	}

	if cfg.RepoRevision != "" {
		if err := checkoutPinnedRevision(cfg.RepoDir, cfg.RepoURL, cfg.RepoRevision); err != nil {
			return err
		}
	}

	// Create or resume the working branch named after the AgentRun so PRs have a clean source branch.
	branchName := cfg.TaskName
	remoteExists := remoteBranchExists(cfg.RepoDir, branchName)
	if remoteExists {
		log.Printf("Checking out existing remote branch %s...", branchName)
	} else {
		log.Printf("Checking out new branch %s...", branchName)
	}
	for _, command := range checkoutBranchCommands(branchName, remoteExists) {
		if err := agentinfra.GitExec(cfg.RepoDir, command.args...); err != nil {
			return fmt.Errorf("%s branch %s: %w", command.action, branchName, err)
		}
	}

	// Re-apply any tracked WIP and local commits from the last object-storage checkpoint.
	if skipReadOnlyCheckpointRestore(cfg) {
		// A run whose mode is read-only by configuration never produced WIP;
		// its checkpoint only pins the tree to the base-branch tip of an
		// earlier pod. Keeping the fresh clone is what a standing maintainer
		// resumed hours later actually needs.
		log.Printf("Skipping workspace checkpoint restore for read-only run; keeping fresh %s checkout", cfg.BaseBranch)
	} else if err := restorePrimaryWorkspaceCheckpoint(*cfg, remoteExists); err != nil {
		return fmt.Errorf("restoring workspace checkpoint: %w", err)
	}
	initializeSubmodules(cfg.RepoDir)

	sessionModeNotes := "Session mode: interactive chat"
	if cfg.AutoMode {
		sessionModeNotes = "Session mode: autonomous"
	}

	parentRefJSON := fmt.Sprintf(`{"namespace":"%s","name":"%s"}`, cfg.Namespace, cfg.TaskName)

	mode := "chat"
	if cfg.AutoMode {
		mode = "auto"
	}
	cfg.TaskContext = fmt.Sprintf(`## Environment
- Base branch: %s
- Working branch: %s
- %s
- Workflow mode: %s
- Parent AgentRun: %s
- Working directory: %s%s
- Ephemeral scratch directory: %s
- %s

## Workspace Rules
All tools (bash, file read/write/edit, grep, glob) execute inside the workspace at %s.
Keep project work inside this directory and use relative file paths. The sole exception is
%s, a separately mounted, writable, non-checkpointed directory for large disposable
toolchains, dependency caches, downloaded archives, and build outputs. Its contents are
cleared when the pod is recreated. Never place source code or required deliverables there.

Repositories: the workspace holds a list of repositories, all equal peers.
The repository this run was launched with is checked out at the workspace
root; every other repository lives under repos/<alias>. Every git/GitHub
tool (git_commit, git_push, git_status, git_pull, git_merge, git_merge_abort,
create_pull_request, update_pull_request, create_github_issue,
get_github_issue, update_github_issue, close_github_issue,
update_github_issue_labels, add_github_issue_comment,
get_pull_request, get_pull_request_checks, get_github_check_logs, list_review_threads,
submit_pull_request_review, reply_to_review_thread, resolve_review_thread,
request_re_review) accepts
repo_path to select the repository it acts on; repo_path defaults to the
workspace root. Use attach_repository to add another repository to the list.

You are on branch %q at the workspace root. Push to this branch when creating PRs.
Do NOT use the gh CLI, and do not push, commit, pull, or merge through raw git
in bash for GitHub work — use the built-in git/GitHub tools above. They enforce
the configured commit-attribution policy and prevent pushes to
main/master/default branches.
If your PR branch is behind origin, use git_pull; if it has merge conflicts
with its base branch, use git_merge with the base branch, resolve the conflict
markers in the reported files, then git_commit and git_push (git_merge_abort
abandons a conflicted merge; git_status shows sync/conflict state).%s%s`,
		cfg.BaseBranch, branchName, sessionModeNotes, mode, parentRefJSON, cfg.RepoDir,
		additionalRepoContextLine(cfg.AdditionalRepoURLs), workspaceScratchDir, parallelToolCallingOneLiner,
		cfg.RepoDir,
		workspaceScratchDir,
		branchName,
		gitRemoteWritePromptSection(cfg.GitRemoteWrites),
		kubernetesAdminPromptSection(cfg.KubernetesAdmin),
	)

	log.Println("Setup complete.")
	return nil
}

func gitRemoteWritePromptSection(mode agentpolicy.GitRemoteWrites) string {
	if agentpolicy.NormalizeGitRemoteWrites(mode) != agentpolicy.GitRemoteWritesDisabled {
		return ""
	}
	return `

Git remote writes are disabled by runtime policy. Do not attempt to push or create a pull request.
The git_push and create_pull_request tools are unavailable, and shell git push commands are blocked.
Workspace edits, local commits, fetches, and pulls remain available.`
}

// checkoutPinnedRevision detaches a fresh clone at the run's pinned revision
// so the working branch created afterwards starts from it instead of the base
// branch head. The clone only has the base branch's history, so revisions
// outside it (tags, other branches, unreached commits) are fetched from
// origin before failing the run.
func checkoutPinnedRevision(repoDir, repoURL, revision string) error {
	log.Printf("Checking out pinned revision %s...", revision)
	if err := agentinfra.GitExec(repoDir, "checkout", "--detach", revision); err == nil {
		return nil
	}
	if err := agentinfra.GitExec(repoDir, "fetch", "origin", revision); err != nil {
		return fmt.Errorf("pinned revision %q does not exist in %s: %w", revision, repoURL, err)
	}
	if err := agentinfra.GitExec(repoDir, "checkout", "--detach", "FETCH_HEAD"); err != nil {
		return fmt.Errorf("checking out pinned revision %q: %w", revision, err)
	}
	return nil
}

// submoduleInitTimeout bounds the best-effort submodule initialization so a
// huge or unreachable nested repository cannot stall workspace setup.
const submoduleInitTimeout = 15 * time.Minute

// initializeSubmodules populates the submodules a checkout declares in
// .gitmodules while the process still owns the repository metadata. The
// subprocess sandbox later pins .git/config read-only (it is a hook and
// fsmonitor injection vector), and `git submodule update --init` must register
// each submodule URL in that file, so an agent cannot initialize submodules
// itself: research tasks against Besu, sei-chain, and similar targets reported
// "Failed to register url; .git/config write failed" and stayed unbuildable.
//
// Initialization is best effort: a repository whose submodules cannot be
// fetched (private, removed, or not reachable without credentials) still
// yields a usable primary checkout, and the failure is logged for the run.
func initializeSubmodules(repoDir string) {
	if _, err := os.Stat(filepath.Join(repoDir, ".gitmodules")); err != nil {
		return
	}
	log.Printf("Initializing submodules declared in %s...", filepath.Join(repoDir, ".gitmodules"))
	ctx, cancel := context.WithTimeout(context.Background(), submoduleInitTimeout)
	defer cancel()
	cmd := exec.CommandContext(ctx, "git", "submodule", "update", "--init", "--recursive")
	cmd.Dir = repoDir
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		if ctx.Err() != nil {
			log.Printf("Warning: submodule initialization in %s timed out after %s; continuing with the primary checkout only", repoDir, submoduleInitTimeout)
			return
		}
		log.Printf("Warning: submodule initialization in %s failed: %v; continuing with the primary checkout only", repoDir, err)
	}
}

func remoteBranchExists(repoDir, branchName string) bool {
	branchName = strings.TrimSpace(branchName)
	if branchName == "" {
		return false
	}
	cmd := exec.Command("git", "ls-remote", "--exit-code", "--heads", "origin", branchName)
	cmd.Dir = repoDir
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run() == nil
}

func checkoutExistingRemoteBranchArgs(branchName string) []string {
	return []string{"checkout", "--track", "-b", branchName, "origin/" + branchName}
}

type workspaceGitCommand struct {
	action string
	args   []string
}

func checkoutBranchCommands(branchName string, remoteExists bool) []workspaceGitCommand {
	if remoteExists {
		return []workspaceGitCommand{
			{action: "fetching", args: []string{"fetch", "origin", "refs/heads/" + branchName + ":refs/remotes/origin/" + branchName}},
			{action: "checking out", args: checkoutExistingRemoteBranchArgs(branchName)},
			{action: "pulling", args: []string{"pull", "--ff-only", "origin", branchName}},
		}
	}
	return []workspaceGitCommand{
		{action: "creating", args: []string{"checkout", "-b", branchName}},
	}
}

// setupRepolessWorkspace prepares an empty sandbox for a plain chat that has no
// repository attached. File/shell/code tools still operate inside a real working
