// additionalRepoContextLine renders the Environment bullet describing the
// run's pre-attached extra repositories; empty when the run has none.
func additionalRepoContextLine(urls []string) string {
	entries := make([]string, 0, len(urls))
	for _, repoURL := range urls {
		name, err := agentinfra.DeriveRepoDirName(repoURL)
		if err != nil {
			continue
		}
		entries = append(entries, fmt.Sprintf("repos/%s (%s)", name, repoURL))
	}
	if len(entries) == 0 {
		return ""
	}
	return "\n- Repository list (pre-cloned alongside the root checkout): " + strings.Join(entries, ", ")
}

// cloneAdditionalRepos clones the run's spec-declared extra repositories into
// the attach_repository store (repos/<name> under the primary repo dir) and
// checks each out to the run's working branch so every repository works on
// the same branch as the primary repo. It must run after restoreExtraRepos so
// snapshot-restored clones are kept: existing directories are skipped.
func cloneAdditionalRepos(cfg *runConfig) error {
	if len(cfg.AdditionalRepoURLs) == 0 {
		return nil
	}
	storeDir := filepath.Join(cfg.RepoDir, extraRepoStoreDirName)
	if err := os.MkdirAll(storeDir, 0o755); err != nil {
		return fmt.Errorf("creating repo store %s: %w", storeDir, err)
	}
	for _, repoURL := range cfg.AdditionalRepoURLs {
		name, err := agentinfra.DeriveRepoDirName(repoURL)
		if err != nil {
			return fmt.Errorf("additional repo %q: %w", repoURL, err)
		}
		dest := filepath.Join(storeDir, name)
		exists, err := validateOrRemoveExtraRepoDest(context.Background(), dest, repoURL)
		if err != nil {
			return fmt.Errorf("additional repo %s: %w", name, err)
		}
		if exists {
			if err := checkoutWorkBranch(dest, cfg.TaskName); err != nil {
				return fmt.Errorf("additional repo %s: %w", name, err)
			}
			continue
		}
		log.Printf("Cloning additional repo %s into repos/%s...", repoURL, name)
		if err := agentinfra.GitExec("", "clone", repoURL, dest); err != nil {
			return fmt.Errorf("cloning additional repo %s: %w", repoURL, err)
		}
		if err := checkoutWorkBranch(dest, cfg.TaskName); err != nil {
			return fmt.Errorf("additional repo %s: %w", name, err)
		}
		initializeSubmodules(dest)
	}
	if !cfg.Repoless {
		// Keep the store out of the primary repository's status output,
		// mirroring the SDK's attach_repository behavior.
		ensureExtraRepoExclude(cfg.RepoDir)
	}
	return nil
}

// checkoutWorkBranch checks out the run's working branch in an extra
// repository so it matches the primary repo, resuming the remote branch when
// a previous pod of this run already pushed it. No-op without a branch name.
func checkoutWorkBranch(repoDir, branchName string) error {
	branchName = strings.TrimSpace(branchName)
	if branchName == "" {
		return nil
	}
	if current, err := gitOutput(context.Background(), repoDir, nil, "symbolic-ref", "--quiet", "--short", "HEAD"); err == nil && current == branchName {
		return nil
	}
	remoteExists := remoteBranchExists(repoDir, branchName)
	if remoteExists {
		log.Printf("Checking out existing remote branch %s in %s...", branchName, repoDir)
	} else {
		log.Printf("Checking out new branch %s in %s...", branchName, repoDir)
	}
	for _, command := range checkoutWorkBranchCommands(branchName, remoteExists) {
		if err := agentinfra.GitExec(repoDir, command.args...); err != nil {
			return fmt.Errorf("%s branch %s: %w", command.action, branchName, err)
		}
	}
	return nil
}

// checkoutWorkBranchCommands returns the git commands that put an extra
// repository on the run's working branch. Unlike the primary repo's
// checkoutBranchCommands, resuming an existing remote branch must not make it
// the local branch's upstream: extra repositories are diffed against
// @{upstream} (falling back to origin/HEAD, see the dashboard's
// extraRepoDiffScript), so tracking the run branch itself would make every
// run diff empty.
func checkoutWorkBranchCommands(branchName string, remoteExists bool) []workspaceGitCommand {
	if remoteExists {
		return []workspaceGitCommand{
			{action: "fetching", args: []string{"fetch", "origin", "refs/heads/" + branchName + ":refs/remotes/origin/" + branchName}},
			{action: "checking out", args: []string{"checkout", "--no-track", "-b", branchName, "origin/" + branchName}},
		}
	}
	return []workspaceGitCommand{
		{action: "creating", args: []string{"checkout", "-b", branchName}},
	}
}

package main

import (
	"context"
	"log"
	"math/rand"
	"os"
	"strings"
	"time"
)

// Checkpoint work has two very different cost profiles: local Git preparation
// (staging, bundling, packing the anchor tree) scales with repository size and
// can take minutes on a large monorepo, while an object-store upload should
// complete in seconds. Sharing one short deadline across both meant that a slow
// pack either got killed mid-flight or handed the upload an almost-expired
// context, which surfaced as S3 "context deadline exceeded". Each stage now
// carries its own budget.
const (
	defaultWorkspaceCheckpointPrepareTimeout = 5 * time.Minute
	defaultWorkspaceCheckpointUploadTimeout  = 60 * time.Second

	// Shutdown runs inside the pod's 60s termination grace period, shared with
	// meta-harness trace finalization (15s), so the final checkpoint keeps a
	// tight budget: at most 20s of Git preparation plus 10s of upload.
	shutdownWorkspaceCheckpointPrepareTimeout = 20 * time.Second
	shutdownWorkspaceCheckpointUploadTimeout  = 10 * time.Second

	workspaceCheckpointPrepareTimeoutEnv = "WORKSPACE_CHECKPOINT_PREPARE_TIMEOUT"
	workspaceCheckpointUploadTimeoutEnv  = "WORKSPACE_CHECKPOINT_UPLOAD_TIMEOUT"

	// Stages faster than this are not worth a log line; slower ones are the
	// ones operators need to correlate with checkpoint gaps.
	workspaceCheckpointStageLogThreshold = 5 * time.Second
)

// checkpointBudget carries the independent per-stage deadlines of one
// checkpoint attempt.
type checkpointBudget struct {
	prepare time.Duration
	upload  time.Duration
	// hardDeadline, when set, is an absolute end-to-end bound that no stage may
	// extend. The shutdown path sets it so a sequence of detached upload
	// contexts cannot push the final checkpoint past the pod termination grace
	// period.
	hardDeadline time.Time
}

func defaultCheckpointBudget() checkpointBudget {
	return checkpointBudget{
		prepare: envDurationOrDefault(workspaceCheckpointPrepareTimeoutEnv, defaultWorkspaceCheckpointPrepareTimeout),
		upload:  envDurationOrDefault(workspaceCheckpointUploadTimeoutEnv, defaultWorkspaceCheckpointUploadTimeout),
	}
}

// shutdownCheckpointBudget caps the configured budgets and pins an absolute
// deadline so the final checkpoint always fits inside the pod termination
// grace period, however many payloads it has to upload.
func shutdownCheckpointBudget(hardDeadline time.Time) checkpointBudget {
	budget := defaultCheckpointBudget()
	if budget.prepare > shutdownWorkspaceCheckpointPrepareTimeout {
		budget.prepare = shutdownWorkspaceCheckpointPrepareTimeout
	}
	if budget.upload > shutdownWorkspaceCheckpointUploadTimeout {
		budget.upload = shutdownWorkspaceCheckpointUploadTimeout
	}
	budget.hardDeadline = hardDeadline
	return budget
}

// prepareContext bounds local Git work. It never extends the caller's deadline.
func (b checkpointBudget) prepareContext(ctx context.Context) (context.Context, context.CancelFunc) {
	return context.WithDeadline(ctx, b.stageDeadline(b.prepare))
}

// uploadContext gives an object-store upload its own budget. When Git
// preparation consumed most of the caller's deadline the remaining time is
// detached, because starting a PutObject with a few milliseconds left only
// produces a guaranteed "context deadline exceeded". Explicit cancellation of
// the caller is preserved when there is still budget to inherit, and a hard
// deadline (shutdown) always wins over the detached budget.
func (b checkpointBudget) uploadContext(ctx context.Context) (context.Context, context.CancelFunc) {
	deadline := b.stageDeadline(b.upload)
	if parent, ok := ctx.Deadline(); ok && parent.Before(deadline) {
		return context.WithDeadline(context.WithoutCancel(ctx), deadline)
	}
	return context.WithDeadline(ctx, deadline)
}

// stageDeadline clamps one stage budget to the absolute end-to-end deadline,
// when the budget carries one. Once that deadline has passed the stage context
// is already expired, which is the correct outcome: no stage may buy another
// budget beyond the shutdown bound.
func (b checkpointBudget) stageDeadline(stage time.Duration) time.Time {
	deadline := time.Now().Add(stage)
	if !b.hardDeadline.IsZero() && b.hardDeadline.Before(deadline) {
		return b.hardDeadline
	}
	return deadline
}

// logCheckpointStage records how long a checkpoint stage took and how much of
// the surrounding budget was left, so timeouts can be attributed to Git
// preparation or to the object store instead of to "the checkpoint".
func logCheckpointStage(ctx context.Context, stage, id string, started time.Time, err error) {
	elapsed := time.Since(started).Truncate(time.Millisecond)
	if err == nil && elapsed < workspaceCheckpointStageLogThreshold {
		return
	}
	remaining := "unbounded"
	if deadline, ok := ctx.Deadline(); ok {
		remaining = time.Until(deadline).Truncate(time.Millisecond).String()
	}
	if err != nil {
		log.Printf("WARN: workspace checkpoint stage %s (%s) failed after %s with %s of budget left: %v",
			stage, id, elapsed, remaining, err)
		return
	}
	log.Printf("Workspace checkpoint stage %s (%s) took %s with %s of budget left", stage, id, elapsed, remaining)
}

// nextCheckpointDelay jitters the periodic checkpoint schedule and backs off
// exponentially after consecutive failures. Security-scan fan-out starts many
// workers on the same repository at nearly the same moment; without jitter they
// repack and re-upload in lockstep and keep retrying on the same cadence.
func nextCheckpointDelay(consecutiveFailures int) time.Duration {
	base := workspaceCheckpointInterval
	for i := 0; i < consecutiveFailures && base < maxWorkspaceCheckpointInterval; i++ {
		base *= 2
	}
	if base > maxWorkspaceCheckpointInterval {
		base = maxWorkspaceCheckpointInterval
	}
	// Uniform +/-25% jitter around the (possibly backed-off) interval.
	spread := int64(base / 2)
	if spread <= 0 {
		return base
	}
	return base - base/4 + time.Duration(rand.Int63n(spread+1))
}

func envDurationOrDefault(name string, fallback time.Duration) time.Duration {
	raw := strings.TrimSpace(os.Getenv(name))
	if raw == "" {
		return fallback
	}
	value, err := time.ParseDuration(raw)
	if err != nil || value <= 0 {
		log.Printf("WARN: ignoring invalid %s=%q: using %s", name, raw, fallback)
		return fallback
	}
	return value
}

package main

import (
	"bytes"
	"context"
	"encoding/base64"
	"errors"
	"fmt"
	"hash/crc32"
	"io"
	"net/url"
	"os"
	"strings"

	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/credentials"
	"github.com/aws/aws-sdk-go-v2/service/s3"
)

const (
	workspaceCheckpointStorePrefix = "workspace-checkpoints/v1"
	maxWorkspaceObjectBytes        = int64(512 << 20)
)

type workspaceObjectStore interface {
	Put(context.Context, string, []byte) error
	Get(context.Context, string) ([]byte, bool, error)
	Delete(context.Context, string) error
}

type workspaceS3Client interface {
	PutObject(context.Context, *s3.PutObjectInput, ...func(*s3.Options)) (*s3.PutObjectOutput, error)
	GetObject(context.Context, *s3.GetObjectInput, ...func(*s3.Options)) (*s3.GetObjectOutput, error)
	DeleteObject(context.Context, *s3.DeleteObjectInput, ...func(*s3.Options)) (*s3.DeleteObjectOutput, error)
}

type s3WorkspaceObjectStore struct {
	client workspaceS3Client
	bucket string
}

func newWorkspaceObjectStoreFromEnv() (workspaceObjectStore, string, error) {
	bucket := strings.TrimSpace(os.Getenv("S3_BUCKET"))
	if bucket == "" {
		return nil, "", fmt.Errorf("S3_BUCKET is required for workspace checkpoints")
	}

	region := strings.TrimSpace(os.Getenv("S3_REGION"))
	if region == "" {
		region = "us-east-1"
	}
	cfg := aws.Config{Region: region}

	accessKeyID := strings.TrimSpace(os.Getenv("AWS_ACCESS_KEY_ID"))
	secretAccessKey := strings.TrimSpace(os.Getenv("AWS_SECRET_ACCESS_KEY"))
	if (accessKeyID == "") != (secretAccessKey == "") {
		return nil, "", fmt.Errorf("AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY must be set together for workspace checkpoints")
	}
	if accessKeyID != "" {
		cfg.Credentials = credentials.NewStaticCredentialsProvider(accessKeyID, secretAccessKey, "")
	}

	endpoint := strings.TrimSpace(os.Getenv("S3_ENDPOINT"))
	client := s3.NewFromConfig(cfg, func(options *s3.Options) {
		if endpoint == "" {
			return
		}
		options.BaseEndpoint = aws.String(endpoint)
		options.UsePathStyle = true
	})
	if endpoint != "" {
		parsed, err := url.ParseRequestURI(endpoint)
		if err != nil || parsed.Scheme == "" || parsed.Host == "" {
			return nil, "", fmt.Errorf("S3_ENDPOINT must be an absolute URL")
		}
	}

	return &s3WorkspaceObjectStore{client: client, bucket: bucket}, workspaceCheckpointStorePrefix, nil
}

func (s *s3WorkspaceObjectStore) Put(ctx context.Context, key string, body []byte) error {
	checksum := crc32.ChecksumIEEE(body)
	_, err := s.client.PutObject(ctx, &s3.PutObjectInput{
		Bucket:        aws.String(s.bucket),
		Key:           aws.String(key),
		Body:          bytes.NewReader(body),
		ContentLength: aws.Int64(int64(len(body))),
		ChecksumCRC32: aws.String(base64.StdEncoding.EncodeToString([]byte{byte(checksum >> 24), byte(checksum >> 16), byte(checksum >> 8), byte(checksum)})),
	})
	if err != nil {
		return fmt.Errorf("putting workspace checkpoint object %q in S3 bucket %q: %w", key, s.bucket, err)
	}
	return nil
}

func (s *s3WorkspaceObjectStore) Get(ctx context.Context, key string) ([]byte, bool, error) {
	output, err := s.client.GetObject(ctx, &s3.GetObjectInput{
		Bucket: aws.String(s.bucket),
		Key:    aws.String(key),
	})
	if err != nil {
		if isWorkspaceObjectNotFound(err) {
			return nil, false, nil
		}
		return nil, false, fmt.Errorf("getting workspace checkpoint object %q from S3 bucket %q: %w", key, s.bucket, err)
	}
	if output.ContentLength != nil && *output.ContentLength > maxWorkspaceObjectBytes {
		_ = output.Body.Close()
		return nil, true, fmt.Errorf("workspace checkpoint object %q in S3 bucket %q is larger than the %d-byte limit", key, s.bucket, maxWorkspaceObjectBytes)
	}

	body, readErr := io.ReadAll(io.LimitReader(output.Body, maxWorkspaceObjectBytes+1))
	closeErr := output.Body.Close()
	if readErr != nil {
		return nil, true, fmt.Errorf("reading workspace checkpoint object %q from S3 bucket %q: %w", key, s.bucket, readErr)
	}
	if closeErr != nil {
		return nil, true, fmt.Errorf("closing workspace checkpoint object %q from S3 bucket %q: %w", key, s.bucket, closeErr)
	}
	if int64(len(body)) > maxWorkspaceObjectBytes {
		return nil, true, fmt.Errorf("workspace checkpoint object %q in S3 bucket %q is larger than the %d-byte limit", key, s.bucket, maxWorkspaceObjectBytes)
	}
	return body, true, nil
}

func (s *s3WorkspaceObjectStore) Delete(ctx context.Context, key string) error {
	_, err := s.client.DeleteObject(ctx, &s3.DeleteObjectInput{
		Bucket: aws.String(s.bucket),
		Key:    aws.String(key),
	})
	if err != nil {
		return fmt.Errorf("deleting workspace checkpoint object %q from S3 bucket %q: %w", key, s.bucket, err)
	}
	return nil
}

type workspaceS3APIError interface {
	error
	ErrorCode() string
}

func isWorkspaceObjectNotFound(err error) bool {
	var apiErr workspaceS3APIError
	return errors.As(err, &apiErr) && (apiErr.ErrorCode() == "NoSuchKey" || apiErr.ErrorCode() == "NotFound")
}

package main

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"net/url"
	"os"
	"os/exec"
	"path"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/gratefulagents/gratefulagents/internal/store/sessionclient"
	agent "github.com/gratefulagents/sdk/pkg/agentsdk"
)

// Workspace checkpoints protect work in the pod's ephemeral /workspace.
// Repository payloads are immutable encrypted Git bundles in object storage;
// one encrypted latest manifest is published only after every repository
// payload succeeds. Git is used locally as a compact delta encoder, but no
// checkpoint refs or objects are ever written to repository remotes.
const (
	workspaceCheckpointVersion  = 1
	workspaceCheckpointInterval = 10 * time.Second
	// maxWorkspaceCheckpointInterval caps the exponential backoff applied after
	// consecutive checkpoint failures.
	maxWorkspaceCheckpointInterval = 5 * time.Minute
	// workspaceCheckpointTimeout bounds one complete checkpoint attempt on the
	// shutdown path, where the pod termination grace period applies. Per-stage
	// budgets (checkpointBudget) bound Git preparation and object-store uploads
	// independently.
	workspaceCheckpointTimeout = 30 * time.Second
	workspaceBundleRef         = "refs/gratefulagents-checkpoint/snapshot"
	workspaceAnchorMagic       = "GAANCH\x01"
	workspaceLatestObject      = "latest.json.enc"
	maxWorkspaceBundleBytes    = maxEncryptedWorkspaceArchiveBytes - (1 << 20)
)

var activeWorkspaceSnapshotter atomic.Pointer[workspaceSnapshotter]

type workspaceCheckpointHooks struct {
	agent.NoOpRunHooks
	snapshotter *workspaceSnapshotter
}

func (h *workspaceCheckpointHooks) OnToolEnd(_ *agent.RunContext, _ *agent.Agent, _ agent.Tool, _ agent.ToolCallData, _ agent.ToolResult) {
}

func (h *workspaceCheckpointHooks) OnToolEndError(_ *agent.RunContext, _ *agent.Agent, tool agent.Tool, _ agent.ToolCallData, _ agent.ToolResult) error {
	if h == nil || h.snapshotter == nil || tool == nil || !toolMayMutateWorkspace(tool.Name()) {
		return nil
	}
	// Do not acknowledge a mutating tool boundary until its encrypted S3
	// checkpoint manifest is durably published. Each stage of the checkpoint is
	// bounded by its own budget, so no shared end-to-end deadline is imposed
	// here: a large repository must be allowed to finish packing and then
	// upload with a fresh budget.
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	if err := h.snapshotter.snapshotSync(ctx, "tool:"+tool.Name()); err != nil {
		return fmt.Errorf("publishing encrypted workspace checkpoint after %s: %w", tool.Name(), err)
	}
	return nil
}

func toolMayMutateWorkspace(name string) bool {
	switch strings.ToLower(strings.TrimSpace(name)) {
	case "bash", "bashstart", "bash_start", "bashpoll", "bash_poll",
		"terminal", "write", "edit", "apply_patch",
		"git_commit", "git_merge", "git_merge_abort", "git_pull",
		"attach_repository", "create_pull_request", "subagent",
		"multi_tool_use.parallel":
		return true
	default:
		return false
	}
}

type workspaceCheckpointManifest struct {
	Version      int                             `json:"version"`
	Generation   string                          `json:"generation"`
	CreatedAt    time.Time                       `json:"createdAt"`
	Repositories []workspaceCheckpointRepository `json:"repositories"`
}

type workspaceCheckpointRepository struct {
	ID              string `json:"id"`
	Alias           string `json:"alias,omitempty"`
	URL             string `json:"url"`
	Branch          string `json:"branch,omitempty"`
	Upstream        string `json:"upstream,omitempty"`
	Location        string `json:"location,omitempty"`
	Primary         bool   `json:"primary,omitempty"`
	SemanticKey     string `json:"semanticKey"`
	ObjectKey       string `json:"objectKey"`
	Snapshot        string `json:"snapshot"`
	Parent          string `json:"parent"`
	Anchor          string `json:"anchor,omitempty"`
	AnchorObjectKey string `json:"anchorObjectKey,omitempty"`
}

func workspaceCheckpointRunPrefix(root, namespace, taskUID string) string {
	return path.Join(strings.Trim(root, "/"), namespace, taskUID)
}

func workspaceCheckpointLatestKey(prefix string) string {
	return path.Join(prefix, workspaceLatestObject)
}

func loadWorkspaceCheckpoint(ctx context.Context, store workspaceObjectStore, prefix string, key []byte) (*workspaceCheckpointManifest, error) {
	if store == nil {
		return nil, fmt.Errorf("workspace checkpoint object store is unavailable")
	}
	data, found, err := store.Get(ctx, workspaceCheckpointLatestKey(prefix))
	if err != nil {
		return nil, fmt.Errorf("loading workspace checkpoint manifest: %w", err)
	}
	if !found {
		return nil, nil
	}
	plaintext, err := decryptWorkspaceArchive(key, data)
	if err != nil {
		return nil, fmt.Errorf("decrypting workspace checkpoint manifest: %w", err)
	}
	var manifest workspaceCheckpointManifest
	if err := json.Unmarshal(plaintext, &manifest); err != nil {
		return nil, fmt.Errorf("decoding workspace checkpoint manifest: %w", err)
	}
	if manifest.Version != workspaceCheckpointVersion {
		return nil, fmt.Errorf("unsupported workspace checkpoint version %d", manifest.Version)
	}
	seen := make(map[string]struct{}, len(manifest.Repositories))
	primary := 0
	for _, repo := range manifest.Repositories {
		if repo.ID == "" || repo.ObjectKey == "" || repo.Snapshot == "" || repo.Parent == "" {
			return nil, fmt.Errorf("workspace checkpoint contains an incomplete repository entry")
		}
		if _, ok := seen[repo.ID]; ok {
			return nil, fmt.Errorf("workspace checkpoint contains duplicate repository %q", repo.ID)
		}
		seen[repo.ID] = struct{}{}
		if repo.Primary {
			primary++
		}
		if !strings.HasPrefix(repo.ObjectKey, prefix+"/objects/") {
			return nil, fmt.Errorf("workspace checkpoint object %q is outside the run prefix", repo.ObjectKey)
		}
		if repo.Anchor != "" && !strings.HasPrefix(repo.AnchorObjectKey, prefix+"/anchors/") {
			return nil, fmt.Errorf("workspace checkpoint anchor object %q is outside the run prefix", repo.AnchorObjectKey)
		}
	}
	if primary > 1 {
		return nil, fmt.Errorf("workspace checkpoint contains multiple primary repositories")
	}
	return &manifest, nil
}

func saveWorkspaceCheckpoint(ctx context.Context, store workspaceObjectStore, prefix string, key []byte, manifest workspaceCheckpointManifest) error {
	data, err := json.Marshal(manifest)
	if err != nil {
		return fmt.Errorf("encoding workspace checkpoint manifest: %w", err)
	}
	encrypted, err := encryptWorkspaceArchive(key, data)
	if err != nil {
		return fmt.Errorf("encrypting workspace checkpoint manifest: %w", err)
	}
	if err := store.Put(ctx, workspaceCheckpointLatestKey(prefix), encrypted); err != nil {
		return fmt.Errorf("publishing workspace checkpoint manifest: %w", err)
	}
	return nil
}

// Extra-repo locations recorded in a checkpoint. The empty store location is
// kept as the natural zero value of the new format.
const (
	extraRepoStoreDirName      = "repos"
	extraRepoLocationStore     = ""
	extraRepoLocationWorkspace = "workspace"
)

type workspaceSnapshotter struct {
	repoDir     string
	repoless    bool
	namespace   string
	runName     string
	prefix      string
	store       workspaceObjectStore
	sc          *sessionclient.Client
	snapshotKey []byte

	budget atomic.Pointer[checkpointBudget]
	// failures counts consecutive checkpoint failures and drives the periodic
	// backoff.
	failures atomic.Int64

	mu          sync.Mutex
	asyncMu     sync.Mutex
	asyncCancel context.CancelFunc
	pending     atomic.Bool
	lastKeys    map[string]string
	lastEntries map[string]workspaceCheckpointRepository
	// anchorObjects caches published anchor object keys by anchor commit so a
	// worker never repacks an anchor tree it has already uploaded.
	anchorObjects  map[string]string
	lastGeneration string
}

func newWorkspaceSnapshotter(cfg runConfig, sc *sessionclient.Client) *workspaceSnapshotter {
	s := &workspaceSnapshotter{
		repoDir: cfg.RepoDir, repoless: cfg.Repoless, namespace: cfg.Namespace,
		runName: cfg.TaskName, prefix: cfg.WorkspaceCheckpointPrefix,
		store: cfg.WorkspaceCheckpointStore, sc: sc,
		snapshotKey: append([]byte(nil), cfg.WorkspaceSnapshotKey...),
		lastKeys:    make(map[string]string), lastEntries: make(map[string]workspaceCheckpointRepository),
		anchorObjects: make(map[string]string),
	}
	budget := defaultCheckpointBudget()
	s.budget.Store(&budget)
	if cfg.WorkspaceCheckpoint != nil {
		s.lastGeneration = cfg.WorkspaceCheckpoint.Generation
		for _, entry := range cfg.WorkspaceCheckpoint.Repositories {
			s.lastKeys[entry.ID] = entry.SemanticKey
			s.lastEntries[entry.ID] = entry
			if entry.Anchor != "" && entry.AnchorObjectKey != "" {
				s.anchorObjects[entry.Anchor] = entry.AnchorObjectKey
			}
		}
	}
	return s
}

// currentBudget returns the per-stage deadlines in force for the next attempt.
func (s *workspaceSnapshotter) currentBudget() checkpointBudget {
	if budget := s.budget.Load(); budget != nil {
		return *budget
	}
	return defaultCheckpointBudget()
}

func (s *workspaceSnapshotter) setBudget(budget checkpointBudget) {
	if s == nil {
		return
	}
	s.budget.Store(&budget)
}

// recordAttempt tracks consecutive failures so the periodic loop can back off
// instead of retrying an expensive checkpoint every interval.
func (s *workspaceSnapshotter) recordAttempt(err error) {
	if err == nil {
		s.failures.Store(0)
		return
	}
	s.failures.Add(1)
}

func (s *workspaceSnapshotter) SnapshotAsync(reason string) {
	if s == nil {
		return
	}
	s.pending.Store(true)
	if !s.mu.TryLock() {
		return
	}
	// Stage budgets bound Git preparation and uploads separately; an
	// end-to-end deadline here would starve the upload of a large repository.
	ctx, cancel := context.WithCancel(context.Background())
	s.asyncMu.Lock()
	s.asyncCancel = cancel
	s.asyncMu.Unlock()
	go func() {
		defer s.mu.Unlock()
		defer func() {
			s.asyncMu.Lock()
			s.asyncCancel = nil
			s.asyncMu.Unlock()
			cancel()
		}()
		for s.pending.Swap(false) {
			err := s.snapshotLocked(ctx, reason)
			if errors.Is(err, context.Canceled) {
				return
			}
			s.recordAttempt(err)
			if err != nil {
				log.Printf("WARN: workspace checkpoint (%s) failed: %v", reason, err)
				return
			}
		}
	}()
}

func (s *workspaceSnapshotter) StartPeriodic(parent context.Context) context.CancelFunc {
	ctx, cancel := context.WithCancel(parent)
	if s == nil {
		return cancel
	}
	go func() {
		timer := time.NewTimer(nextCheckpointDelay(0))
		defer timer.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-timer.C:
				s.SnapshotAsync("periodic")
				timer.Reset(nextCheckpointDelay(int(s.failures.Load())))
			}
		}
	}()
	return cancel
}

func (s *workspaceSnapshotter) Snapshot(ctx context.Context, reason string) {
	if err := s.snapshotSync(ctx, reason); err != nil {
		log.Printf("WARN: workspace checkpoint (%s) failed: %v", reason, err)
	}
}

func (s *workspaceSnapshotter) snapshotSync(ctx context.Context, reason string) error {
	if s == nil {
		return nil
	}
	s.cancelAsyncSnapshot()
	s.mu.Lock()
	defer s.mu.Unlock()
	s.pending.Store(false)
	err := s.snapshotLocked(ctx, reason)
	if !errors.Is(err, context.Canceled) {
		s.recordAttempt(err)
	}
	return err
}

func (s *workspaceSnapshotter) cancelAsyncSnapshot() {
	s.asyncMu.Lock()
	defer s.asyncMu.Unlock()
	if s.asyncCancel != nil {
		s.asyncCancel()
	}
}

func (s *workspaceSnapshotter) Cleanup(ctx context.Context) error {
	if s == nil {
		return nil
	}
	s.cancelAsyncSnapshot()
	s.mu.Lock()
	defer s.mu.Unlock()

	var repos []string
	if !s.repoless {
		repos = append(repos, s.repoDir)
	}
	extras, err := discoverExtraReposStrict(s.repoDir)
	if err != nil {
		log.Printf("WARN: retaining workspace checkpoint: repository discovery failed: %v", err)
		if snapshotErr := s.snapshotLocked(ctx, "successful shutdown"); snapshotErr != nil {
			return fmt.Errorf("repository discovery failed (%v) and final checkpoint failed: %w", err, snapshotErr)
		}
		return fmt.Errorf("repository discovery failed during final checkpoint: %w", err)
	}
	for _, extra := range extras {
		repos = append(repos, extra.dir)
	}
	for _, dir := range repos {
		opCtx, cancel := s.currentBudget().prepareContext(ctx)
		safe, err := repoSafeForSnapshotCleanup(opCtx, dir)
		cancel()
		if err != nil || !safe {
			if err != nil {
				log.Printf("WARN: retaining workspace checkpoint: cannot verify %s: %v", dir, err)
			} else {
				log.Printf("Workspace checkpoint retained: %s has tracked, untracked, or unpushed work", dir)
			}
			if err := s.snapshotLocked(ctx, "successful shutdown"); err != nil {
				return fmt.Errorf("persisting final dirty workspace checkpoint: %w", err)
			}
			return nil
		}
	}
	if err := s.store.Delete(ctx, workspaceCheckpointLatestKey(s.prefix)); err != nil {
		log.Printf("WARN: failed to retire workspace checkpoint: %v", err)
		return nil
	}
	deleted := make(map[string]struct{}, len(s.lastEntries)*2)
	for _, entry := range s.lastEntries {
		for _, objectKey := range []string{entry.ObjectKey, entry.AnchorObjectKey} {
			if objectKey == "" {
				continue
			}
			if _, ok := deleted[objectKey]; ok {
				continue
			}
			deleted[objectKey] = struct{}{}
			if err := s.store.Delete(ctx, objectKey); err != nil {
				log.Printf("WARN: failed to delete retired workspace checkpoint payload %s: %v", objectKey, err)
			}
		}
	}
	log.Printf("Workspace checkpoint retired: %s", s.prefix)
	return nil
}

// repoHasCommit reports whether HEAD in dir resolves to a commit. It is false
// for repositories left behind by an interrupted clone, where .git exists but
// no refs were ever written.
func repoHasCommit(ctx context.Context, dir string) bool {
	_, err := gitOutput(ctx, dir, nil, "rev-parse", "--verify", "--quiet", "HEAD^{commit}")
	return err == nil
}

func repoSafeForSnapshotCleanup(ctx context.Context, dir string) (bool, error) {
	status, err := gitOutput(ctx, dir, nil, "status", "--porcelain", "--untracked-files=all")
	if err != nil {
		return false, err
	}
	if status != "" {
		return false, nil
	}
	branch, err := gitOutput(ctx, dir, nil, "symbolic-ref", "--quiet", "--short", "HEAD")
	if err != nil {
		return false, fmt.Errorf("resolving current branch: %w", err)
	}
	remoteRef := "refs/heads/" + branch
	exists, err := remoteRefExists(ctx, dir, remoteRef)
	if err != nil {
		return false, err
	}
	if !exists {
		return false, nil
	}
	if _, err := gitOutput(ctx, dir, nil, "fetch", "--quiet", "origin", remoteRef); err != nil {
		return false, fmt.Errorf("fetching origin branch: %w", err)
	}
	remoteTip, err := gitOutput(ctx, dir, nil, "rev-parse", "FETCH_HEAD")
	if err != nil {
		return false, err
	}
	head, err := gitOutput(ctx, dir, nil, "rev-parse", "HEAD")
	if err != nil {
		return false, err
	}
	return isGitAncestor(ctx, dir, head, remoteTip), nil
}

func (s *workspaceSnapshotter) snapshotLocked(ctx context.Context, reason string) error {
	if s.store == nil {
		return fmt.Errorf("workspace checkpoint object store is unavailable")
	}
	entries := make([]workspaceCheckpointRepository, 0, 1)
	keys := make(map[string]string)
	entryMap := make(map[string]workspaceCheckpointRepository)

	if !s.repoless {
		entry, err := s.snapshotRepo(ctx, extraRepo{dir: s.repoDir}, true, reason)
		if err != nil {
			return fmt.Errorf("checkpointing primary repository: %w", err)
		}
		entries = append(entries, entry)
		keys[entry.ID], entryMap[entry.ID] = entry.SemanticKey, entry
	}
	extras, err := discoverExtraReposStrict(s.repoDir)
	if err != nil {
		return fmt.Errorf("discovering attached repositories: %w", err)
	}
	for _, extra := range extras {
		// An attach_repository clone that was killed or timed out leaves a
		// .git directory with no commits behind. There is nothing to
		// checkpoint in it, and failing the whole hook would strand the run
		// on a directory the agent never got to use.
		if !repoHasCommit(ctx, extra.dir) {
			log.Printf("WARN: skipping attached repository %q at %s in workspace checkpoint: HEAD does not resolve to a commit (incomplete clone?)", extra.alias, extra.dir)
			continue
		}
		entry, err := s.snapshotRepo(ctx, extra, false, reason)
		if err != nil {
			return fmt.Errorf("checkpointing attached repository %q: %w", extra.alias, err)
		}
		entries = append(entries, entry)
		keys[entry.ID], entryMap[entry.ID] = entry.SemanticKey, entry
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].ID < entries[j].ID })

	generationHash := sha256.New()
	for _, entry := range entries {
		encoded, _ := json.Marshal(entry)
		_, _ = generationHash.Write(encoded)
		_, _ = generationHash.Write([]byte{0})
	}
	generation := hex.EncodeToString(generationHash.Sum(nil))
	if generation == s.lastGeneration {
		return nil
	}
	manifest := workspaceCheckpointManifest{
		Version: workspaceCheckpointVersion, Generation: generation,
		CreatedAt: time.Now().UTC(), Repositories: entries,
	}
	uploadCtx, cancelUpload := s.currentBudget().uploadContext(ctx)
	manifestStart := time.Now()
	err = saveWorkspaceCheckpoint(uploadCtx, s.store, s.prefix, s.snapshotKey, manifest)
	logCheckpointStage(uploadCtx, "manifest upload", "latest", manifestStart, err)
	cancelUpload()
	if err != nil {
		return err
	}
	s.lastKeys, s.lastEntries, s.lastGeneration = keys, entryMap, generation
	if s.sc != nil {
		detail, _ := json.Marshal(map[string]any{"generation": generation, "reason": reason, "repositories": len(entries)})
		writeCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		_ = s.sc.WriteActivity(writeCtx, "workspace_snapshot", "Workspace checkpoint saved", detail)
		cancel()
	}
	log.Printf("Workspace checkpoint published (%s): %s (%d repositories)", reason, generation[:12], len(entries))
	return nil
}

func (s *workspaceSnapshotter) snapshotRepo(ctx context.Context, repo extraRepo, primary bool, reason string) (workspaceCheckpointRepository, error) {
	dir := repo.dir
	budget := s.currentBudget()
	// Local Git work (staging, archiving, bundling, packing) runs under the
	// preparation budget. Uploads below get their own budget so a slow pack
	// never hands an exhausted context to the object store.
	prepCtx, cancelPrep := budget.prepareContext(ctx)
	defer cancelPrep()
	prepStart := time.Now()

	head, err := gitOutput(prepCtx, dir, nil, "rev-parse", "HEAD")
	if err != nil {
		return workspaceCheckpointRepository{}, fmt.Errorf("resolving HEAD: %w", err)
	}
	tree, err := writeWorkingTree(prepCtx, dir, head)
	if err != nil {
		return workspaceCheckpointRepository{}, err
	}
	archive, archiveHash, archiveFiles, err := buildUntrackedWorkspaceArchive(prepCtx, dir)
	if err != nil {
		return workspaceCheckpointRepository{}, fmt.Errorf("building untracked-file checkpoint: %w", err)
	}
	if len(archive) > 0 && len(s.snapshotKey) != workspaceSnapshotKeyBytes {
		return workspaceCheckpointRepository{}, fmt.Errorf("workspace checkpoint encryption key is unavailable; refusing to omit %d untracked files", archiveFiles)
	}

	id := workspaceRepoID(repo, primary)
	urlValue, err := gitOutput(prepCtx, dir, nil, "remote", "get-url", "origin")
	if err != nil {
		return workspaceCheckpointRepository{}, fmt.Errorf("resolving origin URL: %w", err)
	}
	branch, _ := gitOutput(prepCtx, dir, nil, "rev-parse", "--abbrev-ref", "HEAD")
	upstream, _ := gitOutput(prepCtx, dir, nil, "rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{upstream}")
	semanticKey := tree + "|" + head + "|" + archiveHash
	if semanticKey == s.lastKeys[id] {
		if entry, ok := s.lastEntries[id]; ok {
			entry.URL, entry.Branch, entry.Upstream = urlValue, branch, upstream
			entry.Alias, entry.Location, entry.Primary = repo.alias, repo.location, primary
			return entry, nil
		}
	}

	ident := []string{
		"GIT_AUTHOR_NAME=gratefulagents", "GIT_AUTHOR_EMAIL=agent@gratefulagents.local",
		"GIT_COMMITTER_NAME=gratefulagents", "GIT_COMMITTER_EMAIL=agent@gratefulagents.local",
	}
	commitArgs := []string{"commit-tree", tree, "-p", head}
	if len(archive) > 0 {
		archiveCommit, err := createEncryptedWorkspaceArchiveCommit(prepCtx, dir, s.snapshotKey, archive, ident)
		if err != nil {
			return workspaceCheckpointRepository{}, fmt.Errorf("creating untracked-file checkpoint: %w", err)
		}
		commitArgs = append(commitArgs, "-p", archiveCommit)
	}
	commitArgs = append(commitArgs, "-m", fmt.Sprintf("gratefulagents: object-store workspace checkpoint (%s)", reason))
	snap, err := gitOutput(prepCtx, dir, ident, commitArgs...)
	if err != nil {
		return workspaceCheckpointRepository{}, fmt.Errorf("creating checkpoint commit: %w", err)
	}

	bundle, anchor, err := createWorkspaceBundle(prepCtx, dir, head, snap)
	if err != nil {
		return workspaceCheckpointRepository{}, err
	}
	anchorObjectKey := s.cachedAnchorObject(anchor)
	if anchor != "" && anchorObjectKey == "" {
		packStart := time.Now()
		anchorPayload, err := createWorkspaceAnchorPayload(prepCtx, dir, anchor)
		logCheckpointStage(prepCtx, "anchor pack", id, packStart, err)
		if err != nil {
			return workspaceCheckpointRepository{}, err
		}
		encryptedAnchor, err := encryptWorkspaceArchive(s.snapshotKey, anchorPayload)
		if err != nil {
			return workspaceCheckpointRepository{}, fmt.Errorf("encrypting repository checkpoint anchor: %w", err)
		}
		anchorDigest := sha256.Sum256(anchorPayload)
		anchorObjectKey = path.Join(s.prefix, "anchors", hex.EncodeToString(anchorDigest[:])+".pack.enc")
		if err := s.putCheckpointObject(ctx, budget, "anchor upload", id, anchorObjectKey, encryptedAnchor); err != nil {
			return workspaceCheckpointRepository{}, fmt.Errorf("uploading repository checkpoint anchor: %w", err)
		}
		s.rememberAnchorObject(anchor, anchorObjectKey)
	}
	encrypted, err := encryptWorkspaceArchive(s.snapshotKey, bundle)
	if err != nil {
		return workspaceCheckpointRepository{}, fmt.Errorf("encrypting repository checkpoint: %w", err)
	}
	digest := sha256.Sum256(bundle)
	objectKey := path.Join(s.prefix, "objects", id, hex.EncodeToString(digest[:])+".bundle.enc")
	if err := s.putCheckpointObject(ctx, budget, "bundle upload", id, objectKey, encrypted); err != nil {
		return workspaceCheckpointRepository{}, fmt.Errorf("uploading repository checkpoint: %w", err)
	}
	logCheckpointStage(prepCtx, "repository checkpoint", id, prepStart, nil)

	entry := workspaceCheckpointRepository{
		ID: id, Alias: repo.alias, URL: urlValue, Branch: branch, Upstream: upstream,
		Location: repo.location, Primary: primary, SemanticKey: semanticKey,
		ObjectKey: objectKey, Snapshot: snap, Parent: head, Anchor: anchor, AnchorObjectKey: anchorObjectKey,
	}
	log.Printf("Workspace repository checkpoint uploaded (%s): %s (%d encrypted untracked files)", id, shortSHA(snap), archiveFiles)
	return entry, nil
}

// putCheckpointObject uploads one payload under the upload budget, which is
// independent of whatever the Git preparation stages already consumed.
func (s *workspaceSnapshotter) putCheckpointObject(
	ctx context.Context, budget checkpointBudget, stage, id, key string, body []byte,
) error {
	uploadCtx, cancel := budget.uploadContext(ctx)
	defer cancel()
	start := time.Now()
	err := s.store.Put(uploadCtx, key, body)
	logCheckpointStage(uploadCtx, stage, id, start, err)
	return err
}

func workspaceRepoID(repo extraRepo, primary bool) string {
	if primary {
		return "primary"
	}
	if repo.location == extraRepoLocationWorkspace {
		return "workspace-" + repo.alias
	}
	return "store-" + repo.alias
}

// rememberAnchorObject records a published anchor payload so later checkpoints
// in this run reuse it instead of repacking the same tree. Anchor payloads are
// content-addressed, so the mapping stays valid for the life of the run.
func (s *workspaceSnapshotter) rememberAnchorObject(anchor, objectKey string) {
	if anchor == "" || objectKey == "" {
		return
	}
	if s.anchorObjects == nil {
		s.anchorObjects = make(map[string]string)
	}
	s.anchorObjects[anchor] = objectKey
}

func (s *workspaceSnapshotter) cachedAnchorObject(anchor string) string {
	if anchor == "" {
		return ""
	}
	if key, ok := s.anchorObjects[anchor]; ok && key != "" {
		return key
	}
	for _, entry := range s.lastEntries {
		if entry.Anchor == anchor && entry.AnchorObjectKey != "" {
			return entry.AnchorObjectKey
		}
	}
	return ""
}

// createWorkspaceAnchorPayload preserves the excluded bundle prerequisite and
// every tree/blob reachable from it without copying the prerequisite's full
// history. Restore can recreate a shallow boundary even if origin later stops
// advertising or retaining the anchor commit.
func createWorkspaceAnchorPayload(ctx context.Context, dir, anchor string) ([]byte, error) {
	commit, err := gitOutputRaw(ctx, dir, nil, nil, "cat-file", "commit", anchor)
	if err != nil {
		return nil, fmt.Errorf("reading checkpoint anchor commit: %w", err)
	}
	pack, err := gitOutputRaw(ctx, dir, nil, []byte(anchor+"^{tree}\n"), "pack-objects", "--stdout", "--revs")
	if err != nil {
		return nil, fmt.Errorf("packing checkpoint anchor tree: %w", err)
	}
	if len(commit) > int(^uint32(0)) {
		return nil, fmt.Errorf("checkpoint anchor commit is unexpectedly large")
	}
	payload := make([]byte, 0, len(workspaceAnchorMagic)+4+len(commit)+len(pack))
	payload = append(payload, workspaceAnchorMagic...)
	var size [4]byte
	binary.BigEndian.PutUint32(size[:], uint32(len(commit)))
	payload = append(payload, size[:]...)
	payload = append(payload, commit...)
	payload = append(payload, pack...)
	if len(payload) > maxWorkspaceBundleBytes {
		return nil, fmt.Errorf("repository checkpoint anchor payload is %d bytes; maximum is %d", len(payload), maxWorkspaceBundleBytes)
	}
	return payload, nil
}

func restoreWorkspaceAnchorPayload(ctx context.Context, dir, wantAnchor string, payload []byte) error {
	magic := []byte(workspaceAnchorMagic)
	if len(payload) < len(magic)+4 || !bytes.Equal(payload[:len(magic)], magic) {
		return fmt.Errorf("unsupported repository checkpoint anchor format")
	}
	commitSize := int(binary.BigEndian.Uint32(payload[len(magic) : len(magic)+4]))
	commitStart := len(magic) + 4
	commitEnd := commitStart + commitSize
	if commitSize == 0 || commitEnd > len(payload) {
		return fmt.Errorf("repository checkpoint anchor payload is truncated")
	}
	commit, pack := payload[commitStart:commitEnd], payload[commitEnd:]
	if len(pack) == 0 {
		return fmt.Errorf("repository checkpoint anchor pack is empty")
	}
	if _, err := gitOutputRaw(ctx, dir, nil, pack, "index-pack", "--stdin"); err != nil {
		return fmt.Errorf("importing checkpoint anchor tree: %w", err)
	}
	written, err := gitOutputRaw(ctx, dir, nil, commit, "hash-object", "-t", "commit", "-w", "--stdin")
	if err != nil {
		return fmt.Errorf("importing checkpoint anchor commit: %w", err)
	}
	if strings.TrimSpace(string(written)) != wantAnchor {
		return fmt.Errorf("checkpoint anchor commit resolved to %s, want %s", strings.TrimSpace(string(written)), wantAnchor)
	}
	return markGitShallowBoundary(ctx, dir, wantAnchor)
}

// markGitShallowBoundary tells Git that the restored anchor intentionally has
// no locally available parents. Without this, bundle prerequisite validation
// rejects a non-root anchor after its original history was pruned by origin.
func markGitShallowBoundary(ctx context.Context, dir, anchor string) error {
	decoded, err := hex.DecodeString(anchor)
	if err != nil || (len(decoded) != 20 && len(decoded) != 32) {
		return fmt.Errorf("invalid checkpoint anchor object ID %q", anchor)
	}
	shallowPath, err := gitOutput(ctx, dir, nil, "rev-parse", "--git-path", "shallow")
	if err != nil {
		return fmt.Errorf("resolving Git shallow-boundary file: %w", err)
	}
	if !filepath.IsAbs(shallowPath) {
		shallowPath = filepath.Join(dir, shallowPath)
	}
	existing, err := os.ReadFile(shallowPath)
	if err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("reading Git shallow-boundary file: %w", err)
	}
	if strings.Contains("\n"+string(existing)+"\n", "\n"+anchor+"\n") {
		return nil
	}
	if err := os.MkdirAll(filepath.Dir(shallowPath), 0o755); err != nil {
		return fmt.Errorf("creating Git shallow-boundary directory: %w", err)
	}
	f, err := os.OpenFile(shallowPath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
	if err != nil {
		return fmt.Errorf("opening Git shallow-boundary file: %w", err)
	}
	defer func() { _ = f.Close() }()
	if len(existing) > 0 && !bytes.HasSuffix(existing, []byte("\n")) {
		if _, err := f.WriteString("\n"); err != nil {
			return err
		}
	}
	if _, err := f.WriteString(anchor + "\n"); err != nil {
		return fmt.Errorf("writing Git shallow boundary: %w", err)
	}
	return nil
}

func createWorkspaceBundle(ctx context.Context, dir, head, snap string) ([]byte, string, error) {
	anchor := bestRemoteAncestor(ctx, dir, head)
	bundle, err := os.CreateTemp("", "gratefulagents-checkpoint-*.bundle")
	if err != nil {
		return nil, "", fmt.Errorf("creating checkpoint bundle file: %w", err)
	}
	bundlePath := bundle.Name()
	_ = bundle.Close()
	_ = os.Remove(bundlePath)
	defer func() { _ = os.Remove(bundlePath) }()

	if _, err := gitOutput(ctx, dir, nil, "update-ref", workspaceBundleRef, snap); err != nil {
		return nil, "", fmt.Errorf("creating local checkpoint ref: %w", err)
	}
	defer func() { _, _ = gitOutput(context.Background(), dir, nil, "update-ref", "-d", workspaceBundleRef) }()
	args := []string{"bundle", "create", bundlePath, workspaceBundleRef}
	if anchor != "" {
		args = append(args, "^"+anchor)
	}
	if _, err := gitOutput(ctx, dir, nil, args...); err != nil {
		return nil, "", fmt.Errorf("creating repository checkpoint bundle: %w", err)
	}
	info, err := os.Stat(bundlePath)
	if err != nil {
		return nil, "", err
	}
	if info.Size() > maxWorkspaceBundleBytes {
		return nil, "", fmt.Errorf("repository checkpoint bundle is %d bytes; maximum is %d", info.Size(), maxWorkspaceBundleBytes)
	}
	data, err := os.ReadFile(bundlePath)
	if err != nil {
		return nil, "", fmt.Errorf("reading repository checkpoint bundle: %w", err)
	}
	return data, anchor, nil
}

func bestRemoteAncestor(ctx context.Context, dir, head string) string {
	out, err := gitOutput(ctx, dir, nil, "for-each-ref", "--format=%(objectname)", "refs/remotes/origin")
	if err != nil || out == "" {
		return ""
	}
	candidates := strings.Fields(out)
	for _, candidate := range candidates {
		if candidate == head {
			return head
		}
	}
	best, bestDistance := "", int64(^uint64(0)>>1)
	seen := map[string]struct{}{}
	for _, candidate := range candidates {
		if _, ok := seen[candidate]; ok || !isGitAncestor(ctx, dir, candidate, head) {
			continue
		}
		seen[candidate] = struct{}{}
		distanceText, err := gitOutput(ctx, dir, nil, "rev-list", "--count", candidate+".."+head)
		if err != nil {
			continue
		}
		var distance int64
		if _, err := fmt.Sscan(distanceText, &distance); err == nil && distance < bestDistance {
			best, bestDistance = candidate, distance
		}
	}
	return best
}

func restorePrimaryWorkspaceCheckpoint(cfg runConfig, branchWasPushed bool) error {
	if cfg.WorkspaceCheckpoint == nil {
		log.Printf("No workspace checkpoint to restore")
		return nil
	}
	for _, entry := range cfg.WorkspaceCheckpoint.Repositories {
		if entry.Primary {
			return restoreWorkspaceCheckpointRepo(context.Background(), cfg, cfg.RepoDir, entry, branchWasPushed)
		}
	}
	return nil
}

func restoreWorkspaceCheckpointRepo(ctx context.Context, cfg runConfig, dest string, entry workspaceCheckpointRepository, branchWasPushed bool) error {
	// Restoring a large repository unbundles locally after downloading, so the
	// two stages get the same independent budgets used when publishing.
	budget := defaultCheckpointBudget()
	ctx, cancel := context.WithTimeout(ctx, budget.prepare+2*budget.upload)
	defer cancel()
	downloadCtx, cancelDownload := budget.uploadContext(ctx)
	payload, found, err := cfg.WorkspaceCheckpointStore.Get(downloadCtx, entry.ObjectKey)
	cancelDownload()
	if err != nil {
		return fmt.Errorf("downloading repository checkpoint: %w", err)
	}
	if !found {
		return fmt.Errorf("published repository checkpoint object %q is missing", entry.ObjectKey)
	}
	bundleData, err := decryptWorkspaceArchive(cfg.WorkspaceSnapshotKey, payload)
	if err != nil {
		return fmt.Errorf("decrypting repository checkpoint: %w", err)
	}
	bundle, err := os.CreateTemp("", "gratefulagents-restore-*.bundle")
	if err != nil {
		return err
	}
	bundlePath := bundle.Name()
	defer func() { _ = os.Remove(bundlePath) }()
	if _, err := bundle.Write(bundleData); err != nil {
		_ = bundle.Close()
		return err
	}
	if err := bundle.Close(); err != nil {
		return err
	}

	if entry.Anchor != "" && !gitObjectExists(ctx, dest, entry.Anchor) {
		anchorEnvelope, found, err := cfg.WorkspaceCheckpointStore.Get(ctx, entry.AnchorObjectKey)
		if err != nil {
			return fmt.Errorf("downloading repository checkpoint anchor: %w", err)
		}
		if !found {
			return fmt.Errorf("published repository checkpoint anchor object %q is missing", entry.AnchorObjectKey)
		}
		anchorPayload, err := decryptWorkspaceArchive(cfg.WorkspaceSnapshotKey, anchorEnvelope)
		if err != nil {
			return fmt.Errorf("decrypting repository checkpoint anchor: %w", err)
		}
		if err := restoreWorkspaceAnchorPayload(ctx, dest, entry.Anchor, anchorPayload); err != nil {
			return err
		}
	}
	if _, err := gitOutput(ctx, dest, nil, "fetch", "--quiet", bundlePath, workspaceBundleRef); err != nil {
		return fmt.Errorf("importing repository checkpoint bundle: %w", err)
	}
	snap, err := gitOutput(ctx, dest, nil, "rev-parse", "FETCH_HEAD")
	if err != nil {
		return err
	}
	if snap != entry.Snapshot {
		return fmt.Errorf("repository checkpoint resolved to %s, want %s", snap, entry.Snapshot)
	}
	parent, err := gitOutput(ctx, dest, nil, "rev-parse", snap+"^1")
	if err != nil {
		return fmt.Errorf("resolving repository checkpoint parent: %w", err)
	}
	if parent != entry.Parent {
		return fmt.Errorf("repository checkpoint parent is %s, want %s", parent, entry.Parent)
	}

	tip, err := gitOutput(ctx, dest, nil, "rev-parse", "HEAD")
	if err != nil {
		return err
	}
	switch {
	case parent == tip:
	case isGitAncestor(ctx, dest, tip, parent):
	case !branchWasPushed && isGitAncestor(ctx, dest, parent, tip):
	default:
		log.Printf("WARN: workspace checkpoint %s diverged from branch tip %s; keeping fresh checkout", shortSHA(snap), shortSHA(tip))
		return nil
	}

	if _, err := gitOutput(ctx, dest, nil, "reset", "--hard", snap); err != nil {
		return fmt.Errorf("applying repository checkpoint tree: %w", err)
	}
	if _, err := gitOutput(ctx, dest, nil, "reset", "--quiet", parent); err != nil {
		return fmt.Errorf("unwrapping repository checkpoint: %w", err)
	}
	encryptedArchive, found, err := encryptedWorkspaceArchiveFromSnapshot(ctx, dest, snap)
	if err != nil {
		return err
	}
	untrackedFiles := 0
	if found {
		untrackedFiles, err = restoreEncryptedWorkspaceArchive(dest, cfg.WorkspaceSnapshotKey, encryptedArchive)
		if err != nil {
			return fmt.Errorf("restoring encrypted untracked files: %w", err)
		}
	}
	log.Printf("Workspace repository checkpoint restored: %s (HEAD at %s, encrypted untracked files: %d)", shortSHA(snap), shortSHA(parent), untrackedFiles)
	return nil
}

func gitObjectExists(ctx context.Context, dir, object string) bool {
	cmd := exec.CommandContext(ctx, "git", "cat-file", "-e", object+"^{commit}")
	cmd.Dir = dir
	return cmd.Run() == nil
}

// restoreExtraRepos re-clones every attached repository represented in the
// atomically published workspace checkpoint.
func restoreExtraRepos(ctx context.Context, cfg runConfig, _ *sessionclient.Client) error {
	if cfg.WorkspaceCheckpoint == nil {
		return nil
	}
	for _, entry := range cfg.WorkspaceCheckpoint.Repositories {
		if entry.Primary {
			continue
		}
		if err := restoreExtraRepo(ctx, cfg, entry); err != nil {
			return fmt.Errorf("restoring attached repo %q: %w", entry.Alias, err)
		}
	}
	if !cfg.Repoless {
		ensureExtraRepoExclude(cfg.RepoDir)
	}
	return nil
}

func extraRepoRestoreDest(cfg runConfig, entry workspaceCheckpointRepository) (string, error) {
	alias := strings.TrimSpace(entry.Alias)
	if alias == "" || alias == "." || alias == ".." || alias != filepath.Base(alias) {
		return "", fmt.Errorf("invalid checkpoint repository alias %q", entry.Alias)
	}
	switch entry.Location {
	case extraRepoLocationStore:
		return filepath.Join(cfg.RepoDir, extraRepoStoreDirName, alias), nil
	case extraRepoLocationWorkspace:
		if alias == filepath.Base(cfg.RepoDir) {
			return "", fmt.Errorf("workspace clone alias %q collides with the primary repository", alias)
		}
		return filepath.Join(filepath.Dir(cfg.RepoDir), alias), nil
	default:
		return "", fmt.Errorf("unknown repository location %q", entry.Location)
	}
}

func restoreExtraRepo(ctx context.Context, cfg runConfig, entry workspaceCheckpointRepository) error {
	if strings.TrimSpace(entry.URL) == "" {
		return fmt.Errorf("checkpoint repository %q is missing its URL", entry.Alias)
	}
	dest, err := extraRepoRestoreDest(cfg, entry)
	if err != nil {
		return err
	}
	exists, err := validateOrRemoveExtraRepoDest(ctx, dest, entry.URL)
	if err != nil {
		return err
	}
	if !exists {
		if err := os.MkdirAll(filepath.Dir(dest), 0o755); err != nil {
			return err
		}
		if _, err := gitOutput(ctx, "", nil, "clone", "--quiet", "--depth", "1", "--single-branch", "--no-tags", entry.URL, dest); err != nil {
			return fmt.Errorf("cloning: %w", err)
		}
	}
	branch := strings.TrimSpace(entry.Branch)
	branchWasPushed := false
	if branch != "" && branch != "HEAD" {
		remoteRef := "refs/heads/" + branch
		branchWasPushed, err = remoteRefExists(ctx, dest, remoteRef)
		if err != nil {
			return fmt.Errorf("probing attached repository work branch: %w", err)
		}
		if branchWasPushed {
			if _, err := gitOutput(ctx, dest, nil, "fetch", "--quiet", "origin", remoteRef+":refs/remotes/origin/"+branch); err != nil {
				return fmt.Errorf("fetching attached repository work branch: %w", err)
			}
			if _, err := gitOutput(ctx, dest, nil, "checkout", "--quiet", "--no-track", "-B", branch, "origin/"+branch); err != nil {
				return fmt.Errorf("checking out attached repository work branch: %w", err)
			}
		} else if _, err := gitOutput(ctx, dest, nil, "checkout", "--quiet", "-B", branch); err != nil {
			return fmt.Errorf("creating attached repository work branch: %w", err)
		}
	}
	if err := restoreWorkspaceCheckpointRepo(ctx, cfg, dest, entry, branchWasPushed); err != nil {
		return err
	}
	if branch != "" && branch != "HEAD" {
		restoreExtraRepoUpstream(ctx, dest, entry.Alias, branch, entry.Upstream)
	}
	return nil
}

func restoreExtraRepoUpstream(ctx context.Context, dest, alias, branch, upstream string) {
	upstream = strings.TrimSpace(upstream)
	if upstream == "" {
		return
	}
	if _, err := gitOutput(ctx, dest, nil, "branch", "--quiet", "--set-upstream-to", upstream, branch); err != nil {
		log.Printf("WARN: attached repo %q: restoring upstream %s: %v", alias, upstream, err)
	}
}

// writeWorkingTree creates a synthetic tree for tracked modifications and
// deletions without changing the user's index.
func writeWorkingTree(ctx context.Context, dir, head string) (string, error) {
	idx, err := os.CreateTemp("", "gratefulagents-checkpoint-index-*")
	if err != nil {
		return "", fmt.Errorf("creating temporary index: %w", err)
	}
	idxPath := idx.Name()
	_ = idx.Close()
	_ = os.Remove(idxPath)
	defer func() { _ = os.Remove(idxPath) }()
	env := []string{"GIT_INDEX_FILE=" + idxPath}
	if _, err := gitOutput(ctx, dir, env, "read-tree", head); err != nil {
		return "", fmt.Errorf("seeding temporary index: %w", err)
	}
	if _, err := gitOutput(ctx, dir, env, "add", "-u", "--", "."); err != nil {
		return "", fmt.Errorf("staging tracked workspace: %w", err)
	}
	tree, err := gitOutput(ctx, dir, env, "write-tree")
	if err != nil {
		return "", fmt.Errorf("writing checkpoint tree: %w", err)
	}
	return tree, nil
}

type extraRepo struct {
	alias    string
	dir      string
	location string
}

func discoverExtraRepos(repoDir string) []extraRepo {
	repos, _ := discoverExtraReposStrict(repoDir)
	return repos
}

func discoverExtraReposStrict(repoDir string) ([]extraRepo, error) {
	storeRepos, err := discoverStoreReposStrict(repoDir)
	if err != nil {
		return nil, err
	}
	workspaceRepos, err := discoverWorkspaceRootReposStrict(repoDir)
	if err != nil {
		return nil, err
	}
	return append(storeRepos, workspaceRepos...), nil
}

func discoverStoreRepos(repoDir string) []extraRepo {
	repos, _ := discoverStoreReposStrict(repoDir)
	return repos
}

func discoverStoreReposStrict(repoDir string) ([]extraRepo, error) {
	storeDir := filepath.Join(repoDir, extraRepoStoreDirName)
	entries, err := os.ReadDir(storeDir)
	if os.IsNotExist(err) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("reading attached-repository store %s: %w", storeDir, err)
	}
	var repos []extraRepo
	for _, entry := range entries {
		dir := filepath.Join(storeDir, entry.Name())
		if !entry.IsDir() {
			continue
		}
		info, err := os.Stat(filepath.Join(dir, ".git"))
		if os.IsNotExist(err) {
			continue
		}
		if err != nil {
			return nil, fmt.Errorf("inspecting attached repository %s: %w", dir, err)
		}
		if info.IsDir() {
			repos = append(repos, extraRepo{alias: entry.Name(), dir: dir})
		}
	}
	return repos, nil
}

func discoverWorkspaceRootRepos(repoDir string) []extraRepo {
	repos, _ := discoverWorkspaceRootReposStrict(repoDir)
	return repos
}

func discoverWorkspaceRootReposStrict(repoDir string) ([]extraRepo, error) {
	root, self := filepath.Dir(repoDir), filepath.Base(repoDir)
	entries, err := os.ReadDir(root)
	if err != nil {
		return nil, fmt.Errorf("reading workspace root %s: %w", root, err)
	}
	var repos []extraRepo
	for _, entry := range entries {
		name := entry.Name()
		if !entry.IsDir() || name == self || strings.HasPrefix(name, ".") {
			continue
		}
		// Scratch may contain disposable Git checkouts, but it is an EmptyDir
		// rather than an attached repository and must never enter checkpoints.
		if name == filepath.Base(workspaceScratchDir) {
			continue
		}
		dir := filepath.Join(root, name)
		info, err := os.Stat(filepath.Join(dir, ".git"))
		if os.IsNotExist(err) {
			continue
		}
		if err != nil {
			return nil, fmt.Errorf("inspecting workspace repository %s: %w", dir, err)
		}
		if info.IsDir() {
			repos = append(repos, extraRepo{alias: name, dir: dir, location: extraRepoLocationWorkspace})
		}
	}
	return repos, nil
}

func finalizeWorkspaceSnapshot(result runResult, s *workspaceSnapshotter) error {
	if s == nil {
		return nil
	}
	// The shutdown checkpoint runs inside the pod termination grace period, so
	// it swaps in the capped stage budgets before taking the last snapshot. The
	// absolute deadline lets one in-flight upload outlive the caller context by
	// at most a single upload budget; a sequence of uploads can never extend
	// the shutdown beyond it.
	hardDeadline := time.Now().Add(workspaceCheckpointTimeout + shutdownWorkspaceCheckpointUploadTimeout)
	s.setBudget(shutdownCheckpointBudget(hardDeadline))
	ctx, cancel := context.WithTimeout(context.Background(), workspaceCheckpointTimeout)
	defer cancel()
	if result.Status == "succeeded" {
		return s.Cleanup(ctx)
	}
	return s.snapshotSync(ctx, "shutdown")
}

func validateOrRemoveExtraRepoDest(ctx context.Context, dest, expectedURL string) (bool, error) {
	if _, err := os.Lstat(dest); os.IsNotExist(err) {
		return false, nil
	} else if err != nil {
		return false, err
	}
	if _, err := gitOutput(ctx, dest, nil, "rev-parse", "--is-inside-work-tree"); err != nil {
		if err := os.RemoveAll(dest); err != nil {
			return false, fmt.Errorf("removing incomplete destination: %w", err)
		}
		return false, nil
	}
	actualURL, err := gitOutput(ctx, dest, nil, "remote", "get-url", "origin")
	if err != nil {
		return false, fmt.Errorf("validating existing origin: %w", err)
	}
	if canonicalGitURL(actualURL) != canonicalGitURL(expectedURL) {
		return false, fmt.Errorf("existing destination origin %q does not match expected %q", actualURL, expectedURL)
	}
	return true, nil
}

func canonicalGitURL(raw string) string {
	raw = strings.TrimSpace(strings.TrimSuffix(raw, "/"))
	if strings.HasPrefix(raw, "git@github.com:") {
		raw = "https://github.com/" + strings.TrimPrefix(raw, "git@github.com:")
	}
	if parsed, err := url.Parse(raw); err == nil && parsed.Host != "" {
		parsed.Scheme = strings.ToLower(parsed.Scheme)
		parsed.Host = strings.ToLower(parsed.Host)
		parsed.User = nil
		parsed.Path = strings.TrimSuffix(parsed.Path, ".git")
		return parsed.String()
	}
	if absolute, err := filepath.Abs(raw); err == nil {
		return filepath.Clean(absolute)
	}
	return strings.TrimSuffix(raw, ".git")
}

func ensureExtraRepoExclude(repoDir string) {
	pattern := extraRepoStoreDirName + "/"
	file := filepath.Join(repoDir, ".git", "info", "exclude")
	if err := os.MkdirAll(filepath.Dir(file), 0o755); err != nil {
		return
	}
	existing, err := os.ReadFile(file)
	if err != nil && !os.IsNotExist(err) {
		return
	}
	if strings.Contains("\n"+string(existing)+"\n", "\n"+pattern+"\n") {
		return
	}
	f, err := os.OpenFile(file, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
	if err != nil {
		return
	}
	defer func() { _ = f.Close() }()
	if len(existing) > 0 && !bytes.HasSuffix(existing, []byte("\n")) {
		_, _ = f.WriteString("\n")
	}
	_, _ = f.WriteString(pattern + "\n")
}

func remoteRefExists(ctx context.Context, dir, ref string) (bool, error) {
	cmd := exec.CommandContext(ctx, "git", "ls-remote", "--exit-code", "origin", ref)
	cmd.Dir = dir
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	err := cmd.Run()
	if err == nil {
		return true, nil
	}
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) && exitErr.ExitCode() == 2 {
		return false, nil
	}
	return false, fmt.Errorf("git ls-remote origin %s: %w (%s)", ref, err, strings.TrimSpace(stderr.String()))
}

func gitOutput(ctx context.Context, dir string, extraEnv []string, args ...string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", args...)
	cmd.Dir = dir
	if len(extraEnv) > 0 {
		cmd.Env = append(os.Environ(), extraEnv...)
	}
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	if err := cmd.Run(); err != nil {
		return "", fmt.Errorf("git %s: %w (%s)", strings.Join(args, " "), err, strings.TrimSpace(stderr.String()))
	}
	return strings.TrimSpace(stdout.String()), nil
}

func isGitAncestor(ctx context.Context, repoDir, ancestor, descendant string) bool {
	cmd := exec.CommandContext(ctx, "git", "merge-base", "--is-ancestor", ancestor, descendant)
	cmd.Dir = repoDir
	return cmd.Run() == nil
}

func shortSHA(sha string) string {
	if len(sha) > 12 {
		return sha[:12]
	}
	return sha
}

package main

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"context"
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"os/exec"
	pathpkg "path"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/gratefulagents/gratefulagents/internal/store/sessionclient"
)

const (
	workspaceSnapshotKeyMetadataKey = "workspace_snapshot_encryption_key"
	workspaceSnapshotKeyVersion     = 1
	workspaceSnapshotKeyBytes       = 32

	encryptedWorkspaceArchiveSubject = "gratefulagents: encrypted untracked workspace snapshot v1"
	encryptedWorkspaceArchivePath    = "payload"
	encryptedWorkspaceArchiveMagic   = "GAWS\x01"

	// Bound in-memory authenticated payloads and S3 object downloads. A
	// checkpoint that exceeds this limit fails before publishing its manifest,
	// leaving the previous complete generation intact.
	maxEncryptedWorkspaceArchiveBytes = 512 << 20
	maxWorkspaceArchiveInputBytes     = 256 << 20
)

type workspaceSnapshotKeyRecord struct {
	Version int    `json:"version"`
	Key     string `json:"key"`
}

// loadOrCreateWorkspaceSnapshotKey returns the stable per-run key used for
// encrypted untracked-file payloads. The key is private platform state in
// Postgres, separate from the repository that carries ciphertext. It is
// persisted before use so every remotely reachable payload is decryptable by
// a replacement pod.
func loadOrCreateWorkspaceSnapshotKey(ctx context.Context, sc *sessionclient.Client) ([]byte, error) {
	if sc == nil {
		return nil, fmt.Errorf("session client is required for workspace snapshot encryption")
	}
	session, err := sc.Session(ctx)
	if err != nil {
		return nil, fmt.Errorf("loading workspace snapshot encryption key: %w", err)
	}
	if session != nil && len(session.Metadata) > 0 {
		var metadata map[string]json.RawMessage
		if err := json.Unmarshal(session.Metadata, &metadata); err != nil {
			return nil, fmt.Errorf("decoding session metadata for workspace snapshot encryption: %w", err)
		}
		if raw := metadata[workspaceSnapshotKeyMetadataKey]; len(raw) > 0 && string(raw) != "null" {
			var record workspaceSnapshotKeyRecord
			if err := json.Unmarshal(raw, &record); err != nil {
				return nil, fmt.Errorf("decoding workspace snapshot encryption key: %w", err)
			}
			return decodeWorkspaceSnapshotKey(record)
		}
	}

	key := make([]byte, workspaceSnapshotKeyBytes)
	if _, err := rand.Read(key); err != nil {
		return nil, fmt.Errorf("generating workspace snapshot encryption key: %w", err)
	}
	record := workspaceSnapshotKeyRecord{
		Version: workspaceSnapshotKeyVersion,
		Key:     base64.RawStdEncoding.EncodeToString(key),
	}
	encoded, err := json.Marshal(record)
	if err != nil {
		return nil, fmt.Errorf("encoding workspace snapshot encryption key: %w", err)
	}
	if err := sc.StateStore().MergeSessionMetadata(ctx, sc.SessionID(), workspaceSnapshotKeyMetadataKey, encoded); err != nil {
		return nil, fmt.Errorf("persisting workspace snapshot encryption key: %w", err)
	}
	return key, nil
}

func decodeWorkspaceSnapshotKey(record workspaceSnapshotKeyRecord) ([]byte, error) {
	if record.Version != workspaceSnapshotKeyVersion {
		return nil, fmt.Errorf("unsupported workspace snapshot encryption key version %d", record.Version)
	}
	key, err := base64.RawStdEncoding.DecodeString(record.Key)
	if err != nil {
		return nil, fmt.Errorf("decoding workspace snapshot encryption key bytes: %w", err)
	}
	if len(key) != workspaceSnapshotKeyBytes {
		return nil, fmt.Errorf("workspace snapshot encryption key is %d bytes, want %d", len(key), workspaceSnapshotKeyBytes)
	}
	return key, nil
}

func encryptWorkspaceArchive(key, plaintext []byte) ([]byte, error) {
	if len(key) != workspaceSnapshotKeyBytes {
		return nil, fmt.Errorf("workspace snapshot encryption key is %d bytes, want %d", len(key), workspaceSnapshotKeyBytes)
	}
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := rand.Read(nonce); err != nil {
		return nil, fmt.Errorf("generating workspace archive nonce: %w", err)
	}
	aad := []byte(encryptedWorkspaceArchiveMagic)
	out := make([]byte, 0, len(aad)+len(nonce)+len(plaintext)+gcm.Overhead())
	out = append(out, aad...)
	out = append(out, nonce...)
	out = gcm.Seal(out, nonce, plaintext, aad)
	if len(out) > maxEncryptedWorkspaceArchiveBytes {
		return nil, fmt.Errorf("encrypted workspace checkpoint payload is %d bytes; maximum object size is %d", len(out), maxEncryptedWorkspaceArchiveBytes)
	}
	return out, nil
}

func decryptWorkspaceArchive(key, envelope []byte) ([]byte, error) {
	if len(key) != workspaceSnapshotKeyBytes {
		return nil, fmt.Errorf("workspace snapshot encryption key is unavailable or invalid")
	}
	magic := []byte(encryptedWorkspaceArchiveMagic)
	if !bytes.HasPrefix(envelope, magic) {
		return nil, fmt.Errorf("unsupported encrypted workspace archive format")
	}
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	if len(envelope) < len(magic)+gcm.NonceSize()+gcm.Overhead() {
		return nil, fmt.Errorf("encrypted workspace archive is truncated")
	}
	nonceStart := len(magic)
	nonceEnd := nonceStart + gcm.NonceSize()
	nonce := envelope[nonceStart:nonceEnd]
	plaintext, err := gcm.Open(nil, nonce, envelope[nonceEnd:], magic)
	if err != nil {
		return nil, fmt.Errorf("authenticating encrypted workspace archive: %w", err)
	}
	return plaintext, nil
}

// buildUntrackedWorkspaceArchive returns a deterministic gzip+tar payload for
// every non-ignored path that is absent from HEAD. This includes ordinary
// untracked files, staged new files, and rename destinations. Ignored files
// remain local by policy. Returning an error instead of selectively skipping a
// path prevents a checkpoint from appearing successful while losing data.
func buildUntrackedWorkspaceArchive(ctx context.Context, dir string) (archive []byte, contentHash string, fileCount int, err error) {
	paths, err := snapshotNewPaths(ctx, dir)
	if err != nil {
		return nil, "", 0, err
	}
	if len(paths) == 0 {
		return nil, "", 0, nil
	}

	var compressed bytes.Buffer
	zw, err := gzip.NewWriterLevel(&compressed, gzip.BestSpeed)
	if err != nil {
		return nil, "", 0, err
	}
	zw.Header.ModTime = time.Unix(0, 0)
	zw.Header.OS = 255
	tw := tar.NewWriter(zw)
	closeWriters := func() error {
		if err := tw.Close(); err != nil {
			_ = zw.Close()
			return err
		}
		return zw.Close()
	}

	var inputBytes int64
	for _, rel := range paths {
		if err := validateWorkspaceArchivePath(rel); err != nil {
			_ = closeWriters()
			return nil, "", 0, err
		}
		full := filepath.Join(dir, filepath.FromSlash(rel))
		info, err := os.Lstat(full)
		if err != nil {
			_ = closeWriters()
			return nil, "", 0, fmt.Errorf("reading untracked workspace path %q: %w", rel, err)
		}

		header := &tar.Header{
			Name:       rel,
			Mode:       int64(info.Mode().Perm()),
			ModTime:    time.Unix(0, 0),
			AccessTime: time.Time{},
			ChangeTime: time.Time{},
			Uid:        0,
			Gid:        0,
		}
		switch {
		case info.Mode().IsRegular():
			header.Typeflag = tar.TypeReg
			header.Size = info.Size()
			inputBytes += info.Size()
			if inputBytes > maxWorkspaceArchiveInputBytes {
				_ = closeWriters()
				return nil, "", 0, fmt.Errorf("untracked workspace files total more than %d bytes; checkpoint not advanced", maxWorkspaceArchiveInputBytes)
			}
			if err := tw.WriteHeader(header); err != nil {
				_ = closeWriters()
				return nil, "", 0, fmt.Errorf("archiving untracked workspace path %q: %w", rel, err)
			}
			f, err := os.Open(full)
			if err != nil {
				_ = closeWriters()
				return nil, "", 0, fmt.Errorf("opening untracked workspace path %q: %w", rel, err)
			}
			written, copyErr := io.Copy(tw, f)
			closeErr := f.Close()
			if copyErr != nil {
				_ = closeWriters()
				return nil, "", 0, fmt.Errorf("archiving untracked workspace path %q: %w", rel, copyErr)
			}
			if closeErr != nil {
				_ = closeWriters()
				return nil, "", 0, fmt.Errorf("closing untracked workspace path %q: %w", rel, closeErr)
			}
			if written != info.Size() {
				_ = closeWriters()
				return nil, "", 0, fmt.Errorf("untracked workspace path %q changed size during checkpoint", rel)
			}
		case info.Mode()&os.ModeSymlink != 0:
			target, err := os.Readlink(full)
			if err != nil {
				_ = closeWriters()
				return nil, "", 0, fmt.Errorf("reading untracked symlink %q: %w", rel, err)
			}
			header.Typeflag = tar.TypeSymlink
			header.Linkname = target
			if err := tw.WriteHeader(header); err != nil {
				_ = closeWriters()
				return nil, "", 0, fmt.Errorf("archiving untracked symlink %q: %w", rel, err)
			}
		default:
			_ = closeWriters()
			return nil, "", 0, fmt.Errorf("untracked workspace path %q has unsupported file type %s; checkpoint not advanced", rel, info.Mode().Type())
		}
		fileCount++
	}
	if err := closeWriters(); err != nil {
		return nil, "", 0, fmt.Errorf("finalizing untracked workspace archive: %w", err)
	}
	if compressed.Len() > maxEncryptedWorkspaceArchiveBytes-aes.BlockSize-64 {
		return nil, "", 0, fmt.Errorf("compressed untracked workspace archive is %d bytes; maximum is %d", compressed.Len(), maxEncryptedWorkspaceArchiveBytes-aes.BlockSize-64)
	}
	sum := sha256.Sum256(compressed.Bytes())
	return compressed.Bytes(), hex.EncodeToString(sum[:]), fileCount, nil
}

func snapshotNewPaths(ctx context.Context, dir string) ([]string, error) {
	commands := [][]string{
		{"ls-files", "-z", "--others", "--exclude-standard"},
		// Compare the complete worktree to HEAD with rename detection disabled:
		// rename destinations and staged/intent-to-add files are additions that
		// the tracked-only temporary index cannot otherwise represent.
		{"diff", "--no-renames", "--name-only", "--diff-filter=A", "-z", "HEAD", "--"},
	}
	seen := make(map[string]struct{})
	for _, args := range commands {
		out, err := gitOutputRaw(ctx, dir, nil, nil, args...)
		if err != nil {
			return nil, fmt.Errorf("listing untracked workspace paths: %w", err)
		}
		for _, raw := range bytes.Split(out, []byte{0}) {
			if len(raw) == 0 {
				continue
			}
			rel := filepath.ToSlash(string(raw))
			if err := validateWorkspaceArchivePath(rel); err != nil {
				return nil, err
			}
			seen[rel] = struct{}{}
		}
	}
	paths := make([]string, 0, len(seen))
	for rel := range seen {
		paths = append(paths, rel)
	}
	sort.Strings(paths)
	return paths, nil
}

func validateWorkspaceArchivePath(rel string) error {
	if rel == "" || strings.ContainsRune(rel, '\x00') || strings.ContainsRune(rel, '\\') {
		return fmt.Errorf("invalid untracked workspace path %q", rel)
	}
	clean := pathpkg.Clean(rel)
	if clean != rel || clean == "." || pathpkg.IsAbs(clean) || clean == ".." || strings.HasPrefix(clean, "../") {
		return fmt.Errorf("unsafe untracked workspace path %q", rel)
	}
	for _, component := range strings.Split(clean, "/") {
		if strings.EqualFold(component, ".git") {
			return fmt.Errorf("refusing to archive Git metadata path %q", rel)
		}
	}
	return nil
}

func createEncryptedWorkspaceArchiveCommit(ctx context.Context, dir string, key, plaintext []byte, ident []string) (string, error) {
	envelope, err := encryptWorkspaceArchive(key, plaintext)
	if err != nil {
		return "", err
	}
	blobOut, err := gitOutputRaw(ctx, dir, nil, envelope, "hash-object", "-w", "--stdin")
	if err != nil {
		return "", fmt.Errorf("writing encrypted workspace archive blob: %w", err)
	}
	blob := strings.TrimSpace(string(blobOut))
	if blob == "" {
		return "", fmt.Errorf("writing encrypted workspace archive blob returned no object ID")
	}

	idx, err := os.CreateTemp("", "gratefulagents-archive-index-*")
	if err != nil {
		return "", fmt.Errorf("creating encrypted archive index: %w", err)
	}
	idxPath := idx.Name()
	_ = idx.Close()
	_ = os.Remove(idxPath)
	defer func() { _ = os.Remove(idxPath) }()
	env := []string{"GIT_INDEX_FILE=" + idxPath}
	if _, err := gitOutput(ctx, dir, env, "read-tree", "--empty"); err != nil {
		return "", fmt.Errorf("initializing encrypted archive tree: %w", err)
	}
	if _, err := gitOutput(ctx, dir, env, "update-index", "--add", "--cacheinfo", "100644", blob, encryptedWorkspaceArchivePath); err != nil {
		return "", fmt.Errorf("indexing encrypted workspace archive: %w", err)
	}
	tree, err := gitOutput(ctx, dir, env, "write-tree")
	if err != nil {
		return "", fmt.Errorf("writing encrypted workspace archive tree: %w", err)
	}
	commit, err := gitOutput(ctx, dir, ident, "commit-tree", tree, "-m", encryptedWorkspaceArchiveSubject)
	if err != nil {
		return "", fmt.Errorf("creating encrypted workspace archive commit: %w", err)
	}
	return commit, nil
}

func encryptedWorkspaceArchiveFromSnapshot(ctx context.Context, dir, snapshot string) ([]byte, bool, error) {
	parents, err := gitOutput(ctx, dir, nil, "rev-list", "--parents", "-n", "1", snapshot)
	if err != nil {
		return nil, false, fmt.Errorf("resolving workspace snapshot parents: %w", err)
	}
	fields := strings.Fields(parents)
	if len(fields) < 3 {
		return nil, false, nil
	}
	if len(fields) != 3 {
		return nil, false, fmt.Errorf("workspace snapshot has %d parents; expected at most two", len(fields)-1)
	}
	archiveCommit := fields[2]
	subject, err := gitOutput(ctx, dir, nil, "log", "-1", "--format=%s", archiveCommit)
	if err != nil {
		return nil, false, fmt.Errorf("reading encrypted workspace archive commit: %w", err)
	}
	if subject != encryptedWorkspaceArchiveSubject {
		return nil, false, fmt.Errorf("workspace snapshot second parent has unrecognized format %q", subject)
	}
	payload, err := gitOutputRaw(ctx, dir, nil, nil, "cat-file", "blob", archiveCommit+":"+encryptedWorkspaceArchivePath)
	if err != nil {
		return nil, false, fmt.Errorf("reading encrypted workspace archive payload: %w", err)
	}
	return payload, true, nil
}

func restoreEncryptedWorkspaceArchive(repoDir string, key, envelope []byte) (int, error) {
	plaintext, err := decryptWorkspaceArchive(key, envelope)
	if err != nil {
		return 0, err
	}
	if _, err := walkWorkspaceArchive(repoDir, plaintext, false); err != nil {
		return 0, err
	}
	return walkWorkspaceArchive(repoDir, plaintext, true)
}

// walkWorkspaceArchive validates, then optionally extracts, an archive. The
// validation pass rejects traversal, duplicate paths, special files, and paths
// nested below archive symlinks before the filesystem is modified.
func walkWorkspaceArchive(repoDir string, archive []byte, extract bool) (int, error) {
	zr, err := gzip.NewReader(bytes.NewReader(archive))
	if err != nil {
		return 0, fmt.Errorf("opening untracked workspace archive: %w", err)
	}
	tr := tar.NewReader(zr)
	seen := make(map[string]byte)
	count := 0
	var total int64
	for {
		header, err := tr.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			_ = zr.Close()
			return 0, fmt.Errorf("reading untracked workspace archive: %w", err)
		}
		if err := validateWorkspaceArchivePath(header.Name); err != nil {
			_ = zr.Close()
			return 0, err
		}
		if _, duplicate := seen[header.Name]; duplicate {
			_ = zr.Close()
			return 0, fmt.Errorf("untracked workspace archive repeats path %q", header.Name)
		}
		for parent := pathpkg.Dir(header.Name); parent != "."; parent = pathpkg.Dir(parent) {
			if seen[parent] == tar.TypeSymlink {
				_ = zr.Close()
				return 0, fmt.Errorf("untracked workspace archive path %q is nested below symlink %q", header.Name, parent)
			}
		}
		seen[header.Name] = header.Typeflag
		switch header.Typeflag {
		case tar.TypeReg, tar.TypeRegA:
			if header.Size < 0 {
				_ = zr.Close()
				return 0, fmt.Errorf("untracked workspace archive path %q has negative size", header.Name)
			}
			total += header.Size
			if total > maxWorkspaceArchiveInputBytes {
				_ = zr.Close()
				return 0, fmt.Errorf("untracked workspace archive expands beyond %d bytes", maxWorkspaceArchiveInputBytes)
			}
		case tar.TypeSymlink:
			if strings.ContainsRune(header.Linkname, '\x00') {
				_ = zr.Close()
				return 0, fmt.Errorf("untracked workspace symlink %q has invalid target", header.Name)
			}
		default:
			_ = zr.Close()
			return 0, fmt.Errorf("untracked workspace archive path %q has unsupported type %d", header.Name, header.Typeflag)
		}
		if extract {
			if err := extractWorkspaceArchiveEntry(repoDir, header, tr); err != nil {
				_ = zr.Close()
				return 0, err
			}
		}
		count++
	}
	// Check parent symlinks again after the complete path set is known so a
	// malicious archive cannot evade validation by ordering a child first.
	for name := range seen {
		for parent := pathpkg.Dir(name); parent != "."; parent = pathpkg.Dir(parent) {
			if seen[parent] == tar.TypeSymlink {
				_ = zr.Close()
				return 0, fmt.Errorf("untracked workspace archive path %q is nested below symlink %q", name, parent)
			}
		}
	}
	if err := zr.Close(); err != nil {
		return 0, fmt.Errorf("closing untracked workspace archive: %w", err)
	}
	return count, nil
}

func extractWorkspaceArchiveEntry(repoDir string, header *tar.Header, r io.Reader) error {
	dest, err := safeWorkspaceArchiveDestination(repoDir, header.Name)
	if err != nil {
		return err
	}
	if _, err := os.Lstat(dest); err == nil {
		return fmt.Errorf("refusing to overwrite existing path %q while restoring workspace snapshot", header.Name)
	} else if !os.IsNotExist(err) {
		return fmt.Errorf("checking workspace restore path %q: %w", header.Name, err)
	}

	switch header.Typeflag {
	case tar.TypeReg, tar.TypeRegA:
		f, err := os.OpenFile(dest, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600)
		if err != nil {
			return fmt.Errorf("creating restored workspace path %q: %w", header.Name, err)
		}
		written, copyErr := io.CopyN(f, r, header.Size)
		if copyErr == nil && written != header.Size {
			copyErr = io.ErrUnexpectedEOF
		}
		if copyErr == nil {
			copyErr = f.Chmod(os.FileMode(header.Mode) & os.ModePerm)
		}
		closeErr := f.Close()
		if copyErr != nil {
			_ = os.Remove(dest)
			return fmt.Errorf("restoring workspace path %q: %w", header.Name, copyErr)
		}
		if closeErr != nil {
			_ = os.Remove(dest)
			return fmt.Errorf("closing restored workspace path %q: %w", header.Name, closeErr)
		}
	case tar.TypeSymlink:
		if err := os.Symlink(header.Linkname, dest); err != nil {
			return fmt.Errorf("restoring workspace symlink %q: %w", header.Name, err)
		}
	}
	return nil
}

func safeWorkspaceArchiveDestination(root, rel string) (string, error) {
	if err := validateWorkspaceArchivePath(rel); err != nil {
		return "", err
	}
	rootAbs, err := filepath.Abs(root)
	if err != nil {
		return "", err
	}
	parts := strings.Split(rel, "/")
	current := rootAbs
	for _, component := range parts[:len(parts)-1] {
		current = filepath.Join(current, component)
		info, err := os.Lstat(current)
		if os.IsNotExist(err) {
			if err := os.Mkdir(current, 0o755); err != nil && !os.IsExist(err) {
				return "", fmt.Errorf("creating workspace restore directory %q: %w", component, err)
			}
			continue
		}
		if err != nil {
			return "", fmt.Errorf("checking workspace restore directory %q: %w", component, err)
		}
		if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
			return "", fmt.Errorf("workspace restore path %q traverses a non-directory or symlink", rel)
		}
	}
	dest := filepath.Join(rootAbs, filepath.FromSlash(rel))
	if dest == rootAbs || !strings.HasPrefix(dest, rootAbs+string(os.PathSeparator)) {
		return "", fmt.Errorf("workspace restore path %q escapes repository", rel)
	}
	return dest, nil
}

func gitOutputRaw(ctx context.Context, dir string, extraEnv []string, stdin []byte, args ...string) ([]byte, error) {
	cmd := exec.CommandContext(ctx, "git", args...)
	cmd.Dir = dir
	if len(extraEnv) > 0 {
		cmd.Env = append(os.Environ(), extraEnv...)
	}
	if stdin != nil {
		cmd.Stdin = bytes.NewReader(stdin)
	}
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return nil, fmt.Errorf("git %s: %w (%s)", strings.Join(args, " "), err, strings.TrimSpace(stderr.String()))
	}
	return stdout.Bytes(), nil
}

package agentinfra

import (
	"fmt"
	"os"
	"regexp"
	"strings"
	"text/template"
)

// MustEnv returns the value of the given environment variable, or an error if it is not set.
func MustEnv(key string) (string, error) {
	val := os.Getenv(key)
	if val == "" {
		return "", fmt.Errorf("required env var %s is not set", key)
	}
	return val, nil
}

// EnvOrDefault returns the value of the given environment variable, or def if it is not set.
func EnvOrDefault(key, def string) string {
	if val := os.Getenv(key); val != "" {
		return val
	}
	return def
}

// RenderPrompt executes a text/template against the provided data map.
func RenderPrompt(tmplStr string, data map[string]string) (string, error) {
	t := template.Must(template.New("prompt").Option("missingkey=error").Parse(tmplStr))
	var buf strings.Builder
	if err := t.Execute(&buf, data); err != nil {
		return "", fmt.Errorf("failed to render prompt template: %w", err)
	}
	return buf.String(), nil
}

// ParseRepoURL extracts owner/name from a GitHub URL.
// Supports: https://github.com/owner/repo.git, https://github.com/owner/repo, git@github.com:owner/repo.git
func ParseRepoURL(url string) (string, string, error) {
	url = strings.TrimSuffix(url, ".git")

	if strings.Contains(url, "github.com/") {
		parts := strings.Split(url, "github.com/")
		if len(parts) == 2 {
			segments := strings.SplitN(parts[1], "/", 2)
			if len(segments) == 2 {
				return segments[0], segments[1], nil
			}
		}
	}

	if strings.Contains(url, "github.com:") {
		parts := strings.Split(url, "github.com:")
		if len(parts) == 2 {
			segments := strings.SplitN(parts[1], "/", 2)
			if len(segments) == 2 {
				return segments[0], segments[1], nil
			}
		}
	}

	return "", "", fmt.Errorf("cannot parse owner/repo from URL: %s", url)
}

// repoDirNamePattern restricts derived clone directory names to a single safe
// path segment.
var repoDirNamePattern = regexp.MustCompile(`^[A-Za-z0-9._-]+$`)

// DeriveRepoDirName extracts a safe single-segment directory name from a git URL
// (e.g. https://github.com/owner/my-repo.git -> "my-repo").
func DeriveRepoDirName(repoURL string) (string, error) {
	name := strings.TrimSpace(repoURL)
	name = strings.TrimSuffix(name, ".git")
	name = strings.TrimRight(name, "/")
	if i := strings.LastIndexAny(name, "/:"); i >= 0 {
		name = name[i+1:]
	}
	if name == "" || name == "." || name == ".." || !repoDirNamePattern.MatchString(name) {
		return "", fmt.Errorf("could not derive a valid directory name from %q", repoURL)
	}
	return name, nil
}

package agentinfra

import (
	"fmt"
	"log"
	"os"
	"os/exec"
	"strings"
)

// SetupGHAuth configures gh CLI auth and sets it as the git credential helper.
func SetupGHAuth(token string) error {
	token = strings.TrimSpace(token)
	if token == "" {
		log.Println("WARN: no GitHub token provided; skipping gh auth setup")
		return nil
	}

	cmd := exec.Command("gh", "auth", "login", "--with-token")
	cmd.Stdin = strings.NewReader(token)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("gh auth login: %w", err)
	}

	cmd = exec.Command("gh", "auth", "setup-git")
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("gh auth setup-git: %w", err)
	}

	log.Println("gh auth configured.")
	return nil
}

// GitExec runs a git command, optionally in a specific directory.
func GitExec(dir string, args ...string) error {
	cmd := exec.Command("git", args...)
	if dir != "" {
		cmd.Dir = dir
	}
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

package agentplatform

import (
	"context"
	"fmt"
	"log"
	"time"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/apimachinery/pkg/types"
	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/rest"
	agentsandboxv1alpha1 "sigs.k8s.io/agent-sandbox/api/v1alpha1"
	agentsandboxextensionsv1alpha1 "sigs.k8s.io/agent-sandbox/extensions/api/v1alpha1"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

// BuildCRDClient creates a controller-runtime client that can read/write AgentRun status.
func BuildCRDClient() (client.WithWatch, error) {
	c, _, err := BuildCRDClientWithScheme()
	return c, err
}

// BuildCRDClientWithScheme creates a controller-runtime client plus the runtime scheme it uses.
func BuildCRDClientWithScheme() (client.WithWatch, *runtime.Scheme, error) {
	cfg, err := rest.InClusterConfig()
	if err != nil {
		return nil, nil, fmt.Errorf("getting in-cluster config: %w", err)
	}

	scheme, err := NewCRDScheme()
	if err != nil {
		return nil, nil, err
	}

	c, err := client.NewWithWatch(cfg, client.Options{Scheme: scheme})
	if err != nil {
		return nil, nil, fmt.Errorf("creating client: %w", err)
	}
	return c, scheme, nil
}

// NewCRDScheme builds the runtime scheme used by agent pods. It registers
// every API group agent-side tools read or write: platform CRDs, trigger CRDs
// (e.g. the GitHubRepository that maintainer tools consult for caps and the
// merge opt-in), agent-sandbox CRDs, and core types.
func NewCRDScheme() (*runtime.Scheme, error) {
	scheme := runtime.NewScheme()
	if err := platformv1alpha1.AddToScheme(scheme); err != nil {
		return nil, fmt.Errorf("adding platform scheme: %w", err)
	}
	if err := triggersv1alpha1.AddToScheme(scheme); err != nil {
		return nil, fmt.Errorf("adding triggers scheme: %w", err)
	}
	if err := agentsandboxv1alpha1.AddToScheme(scheme); err != nil {
		return nil, fmt.Errorf("adding agent-sandbox scheme: %w", err)
	}
	if err := agentsandboxextensionsv1alpha1.AddToScheme(scheme); err != nil {
		return nil, fmt.Errorf("adding agent-sandbox extensions scheme: %w", err)
	}
	if err := corev1.AddToScheme(scheme); err != nil {
		return nil, fmt.Errorf("adding core scheme: %w", err)
	}
	return scheme, nil
}

// BuildK8sClient creates a kubernetes client using in-cluster config.
func BuildK8sClient() (*kubernetes.Clientset, error) {
	config, err := rest.InClusterConfig()
	if err != nil {
		return nil, fmt.Errorf("getting in-cluster config: %w", err)
	}
	return kubernetes.NewForConfig(config)
}

// EmitEvent creates a Kubernetes Event associated with the given CRD object.
func EmitEvent(ctx context.Context, k8sClient *kubernetes.Clientset, taskName, taskNamespace, taskUID, crdKind, reportingController string, eventType, reason, message string) {
	event := &corev1.Event{
		ObjectMeta: metav1.ObjectMeta{
			GenerateName: fmt.Sprintf("%s-", taskName),
			Namespace:    taskNamespace,
		},
		InvolvedObject: corev1.ObjectReference{
			APIVersion: platformv1alpha1.GroupVersion.String(),
			Kind:       crdKind,
			Name:       taskName,
			Namespace:  taskNamespace,
			UID:        types.UID(taskUID),
		},
		Reason:              reason,
		Message:             message,
		Type:                eventType,
		EventTime:           metav1.NewMicroTime(time.Now()),
		ReportingController: reportingController,
		ReportingInstance:   taskName,
		Action:              reason,
	}

	if _, err := k8sClient.CoreV1().Events(taskNamespace).Create(ctx, event, metav1.CreateOptions{}); err != nil {
		log.Printf("WARN: failed to emit event: %v", err)
	}
}

package auth

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"strings"
)

// Claims represents the JWT claims for an authenticated user.
type Claims struct {
	Sub      string `json:"sub"`
	Username string `json:"username"`
	Email    string `json:"email,omitempty"`
	Name     string `json:"name"`
	Picture  string `json:"picture,omitempty"`
	Role     string `json:"role"`
}

type claimsContextKey struct{}

// WithClaims stores claims in the context.
func WithClaims(ctx context.Context, c *Claims) context.Context {
	return context.WithValue(ctx, claimsContextKey{}, c)
}

// ClaimsFromContext retrieves claims from the context.
func ClaimsFromContext(ctx context.Context) *Claims {
	c, _ := ctx.Value(claimsContextKey{}).(*Claims)
	return c
}

// ParseUnverifiedClaims extracts claims from a JWT without verifying the signature.
// Use only after the signature has been verified by the middleware.
func ParseUnverifiedClaims(token string) (*Claims, error) {
	parts := strings.SplitN(token, ".", 3)
	if len(parts) != 3 {
		return nil, fmt.Errorf("malformed JWT: expected 3 parts, got %d", len(parts))
	}

	payload, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return nil, fmt.Errorf("decode payload: %w", err)
	}

	var c Claims
	if err := json.Unmarshal(payload, &c); err != nil {
		return nil, fmt.Errorf("unmarshal claims: %w", err)
	}

	return &c, nil
}

package auth

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"time"
)

// GoogleClaims holds the verified claims from a Google ID token.
type GoogleClaims struct {
	Sub           string // Google user ID
	Email         string
	Name          string
	Picture       string
	HD            string // Hosted domain (Google Workspace)
	EmailVerified bool
}

// GoogleVerifier verifies Google OAuth ID tokens.
type GoogleVerifier struct {
	clientID   string
	httpClient *http.Client
}

// NewGoogleVerifier creates a verifier that checks tokens against the given client ID.
func NewGoogleVerifier(clientID string) *GoogleVerifier {
	return &GoogleVerifier{
		clientID:   clientID,
		httpClient: &http.Client{Timeout: 10 * time.Second},
	}
}

// Verify validates a Google ID token and returns the claims.
func (g *GoogleVerifier) Verify(ctx context.Context, idToken string) (*GoogleClaims, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet,
		"https://oauth2.googleapis.com/tokeninfo?id_token="+idToken, nil)
	if err != nil {
		return nil, fmt.Errorf("create request: %w", err)
	}

	resp, err := g.httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("verify token: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("invalid token: status %d", resp.StatusCode)
	}

	var payload struct {
		Sub           string `json:"sub"`
		Email         string `json:"email"`
		EmailVerified string `json:"email_verified"`
		Name          string `json:"name"`
		Picture       string `json:"picture"`
		HD            string `json:"hd"`
		Aud           string `json:"aud"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&payload); err != nil {
		return nil, fmt.Errorf("decode token: %w", err)
	}

	if payload.Aud != g.clientID {
		return nil, fmt.Errorf("token audience %q does not match client ID %q", payload.Aud, g.clientID)
	}

	return &GoogleClaims{
		Sub:           payload.Sub,
		Email:         payload.Email,
		Name:          payload.Name,
		Picture:       payload.Picture,
		HD:            payload.HD,
		EmailVerified: payload.EmailVerified == "true",
	}, nil
}

package auth

import (
	"crypto"
	"crypto/rsa"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"math/big"
	"strings"
	"time"
)

// JWKSCache holds public keys for JWT verification. In integrated mode,
// keys are loaded directly from the JWTIssuer's JWKS JSON output.
type JWKSCache struct {
	keys map[string]*rsa.PublicKey
}

// NewJWKSCacheFromIssuer creates a JWKS cache pre-loaded from a local JWTIssuer.
func NewJWKSCacheFromIssuer(issuer *JWTIssuer) (*JWKSCache, error) {
	jwksJSON, err := issuer.JWKSJSON()
	if err != nil {
		return nil, fmt.Errorf("get JWKS from issuer: %w", err)
	}
	keys, err := parseJWKS(jwksJSON)
	if err != nil {
		return nil, err
	}
	return &JWKSCache{keys: keys}, nil
}

// GetKey returns the public key for the given key ID.
func (c *JWKSCache) GetKey(kid string) (*rsa.PublicKey, error) {
	key, ok := c.keys[kid]
	if !ok {
		return nil, fmt.Errorf("key %q not found in JWKS", kid)
	}
	return key, nil
}

// VerifyToken verifies a JWT token signature using cached JWKS keys.
func (c *JWKSCache) VerifyToken(token string) (*Claims, error) {
	parts := splitJWT(token)
	if parts == nil {
		return nil, fmt.Errorf("malformed JWT")
	}

	headerJSON, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		return nil, fmt.Errorf("decode header: %w", err)
	}

	var header struct {
		Kid string `json:"kid"`
		Alg string `json:"alg"`
	}
	if err := json.Unmarshal(headerJSON, &header); err != nil {
		return nil, fmt.Errorf("parse header: %w", err)
	}

	if header.Alg != "RS256" {
		return nil, fmt.Errorf("unsupported algorithm: %s", header.Alg)
	}

	key, err := c.GetKey(header.Kid)
	if err != nil {
		return nil, err
	}

	// Verify signature
	signingInput := parts[0] + "." + parts[1]
	sig, err := base64.RawURLEncoding.DecodeString(parts[2])
	if err != nil {
		return nil, fmt.Errorf("decode signature: %w", err)
	}

	hash := sha256.Sum256([]byte(signingInput))
	if err := rsa.VerifyPKCS1v15(key, crypto.SHA256, hash[:], sig); err != nil {
		return nil, fmt.Errorf("invalid signature: %w", err)
	}

	// Check payload claims: expiration, issuer, audience, and token type.
	payloadJSON, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return nil, fmt.Errorf("decode payload: %w", err)
	}
	var payloadCheck struct {
		Exp  int64  `json:"exp"`
		Iss  string `json:"iss"`
		Aud  string `json:"aud"`
		Type string `json:"type"`
	}
	if err := json.Unmarshal(payloadJSON, &payloadCheck); err != nil {
		return nil, fmt.Errorf("parse payload: %w", err)
	}
	if time.Now().Unix() > payloadCheck.Exp {
		return nil, fmt.Errorf("token expired")
	}
	if payloadCheck.Iss != TokenIssuer {
		return nil, fmt.Errorf("unexpected token issuer")
	}
	if payloadCheck.Type == "refresh" {
		return nil, fmt.Errorf("refresh token cannot be used for authentication")
	}
	if payloadCheck.Aud != AccessTokenAudience {
		return nil, fmt.Errorf("unexpected token audience")
	}

	return ParseUnverifiedClaims(token)
}

func parseJWKS(jwksJSON string) (map[string]*rsa.PublicKey, error) {
	var jwks struct {
		Keys []struct {
			Kty string `json:"kty"`
			Kid string `json:"kid"`
			N   string `json:"n"`
			E   string `json:"e"`
		} `json:"keys"`
	}
	if err := json.Unmarshal([]byte(jwksJSON), &jwks); err != nil {
		return nil, fmt.Errorf("parse JWKS: %w", err)
	}

	keys := make(map[string]*rsa.PublicKey, len(jwks.Keys))
	for _, k := range jwks.Keys {
		if k.Kty != "RSA" {
			continue
		}
		nBytes, err := base64.RawURLEncoding.DecodeString(k.N)
		if err != nil {
			continue
		}
		eBytes, err := base64.RawURLEncoding.DecodeString(k.E)
		if err != nil {
			continue
		}
		keys[k.Kid] = &rsa.PublicKey{
			N: new(big.Int).SetBytes(nBytes),
			E: int(new(big.Int).SetBytes(eBytes).Int64()),
		}
	}
	return keys, nil
}

func splitJWT(token string) []string {
	parts := strings.SplitN(token, ".", 3)
	if len(parts) != 3 {
		return nil
	}
	return parts
}

package auth

import (
	"crypto"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/base64"
	"encoding/json"
	"encoding/pem"
	"fmt"
	"math/big"
	"os"
	"time"
)

// JWTIssuer signs access and refresh tokens using RS256.
type JWTIssuer struct {
	privateKey *rsa.PrivateKey
	keyID      string
}

const (
	// TokenIssuer is the iss claim stamped on and required from all tokens.
	TokenIssuer = "gratefulagents-auth"
	// AccessTokenAudience is the aud claim required on access tokens.
	AccessTokenAudience = "gratefulagents-dashboard"
)

// NewJWTIssuer creates an issuer. If keyPath is empty, generates an ephemeral key pair.
func NewJWTIssuer(keyPath string) (*JWTIssuer, error) {
	var pk *rsa.PrivateKey
	var err error

	if keyPath != "" {
		pk, err = loadPrivateKey(keyPath)
		if err != nil {
			return nil, fmt.Errorf("load private key: %w", err)
		}
	} else {
		pk, err = rsa.GenerateKey(rand.Reader, 2048)
		if err != nil {
			return nil, fmt.Errorf("generate key: %w", err)
		}
	}

	return newJWTIssuerFromKey(pk)
}

func newJWTIssuerFromKey(pk *rsa.PrivateKey) (*JWTIssuer, error) {
	pubDER, err := x509.MarshalPKIXPublicKey(&pk.PublicKey)
	if err != nil {
		return nil, fmt.Errorf("marshal public key: %w", err)
	}
	hash := sha256.Sum256(pubDER)
	kid := base64.RawURLEncoding.EncodeToString(hash[:8])

	return &JWTIssuer{privateKey: pk, keyID: kid}, nil
}

// AccessTokenClaims are the claims embedded in an access JWT.
type AccessTokenClaims struct {
	Sub      string `json:"sub"`
	Username string `json:"username"`
	Email    string `json:"email,omitempty"`
	Name     string `json:"name"`
	Picture  string `json:"picture,omitempty"`
	Role     string `json:"role"`
}

// IssueAccessToken creates a signed JWT access token valid for the given duration.
func (j *JWTIssuer) IssueAccessToken(claims AccessTokenClaims, ttl time.Duration) (string, int64, error) {
	now := time.Now()
	exp := now.Add(ttl)

	header := map[string]string{
		"alg": "RS256",
		"typ": "JWT",
		"kid": j.keyID,
	}

	payload := map[string]interface{}{
		"sub":      claims.Sub,
		"username": claims.Username,
		"email":    claims.Email,
		"name":     claims.Name,
		"picture":  claims.Picture,
		"role":     claims.Role,
		"iat":      now.Unix(),
		"exp":      exp.Unix(),
		"iss":      TokenIssuer,
		"aud":      AccessTokenAudience,
	}

	token, err := signJWT(header, payload, j.privateKey)
	if err != nil {
		return "", 0, err
	}
	return token, exp.Unix(), nil
}

// IssueRefreshToken creates a signed JWT refresh token valid for the given duration.
func (j *JWTIssuer) IssueRefreshToken(userID string, ttl time.Duration) (string, int64, error) {
	now := time.Now()
	exp := now.Add(ttl)

	header := map[string]string{
		"alg": "RS256",
		"typ": "JWT",
		"kid": j.keyID,
	}

	payload := map[string]interface{}{
		"sub":  userID,
		"type": "refresh",
		"iat":  now.Unix(),
		"exp":  exp.Unix(),
		"iss":  TokenIssuer,
	}

	token, err := signJWT(header, payload, j.privateKey)
	if err != nil {
		return "", 0, err
	}
	return token, exp.Unix(), nil
}

// JWKSJSON returns the JSON-encoded JWKS containing the public key.
func (j *JWTIssuer) JWKSJSON() (string, error) {
	pub := &j.privateKey.PublicKey

	jwks := map[string]interface{}{
		"keys": []map[string]string{
			{
				"kty": "RSA",
				"alg": "RS256",
				"use": "sig",
				"kid": j.keyID,
				"n":   base64.RawURLEncoding.EncodeToString(pub.N.Bytes()),
				"e":   base64.RawURLEncoding.EncodeToString(big.NewInt(int64(pub.E)).Bytes()),
			},
		},
	}

	data, err := json.Marshal(jwks)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func signJWT(header map[string]string, payload map[string]interface{}, key *rsa.PrivateKey) (string, error) {
	headerJSON, err := json.Marshal(header)
	if err != nil {
		return "", err
	}
	payloadJSON, err := json.Marshal(payload)
	if err != nil {
		return "", err
	}

	headerB64 := base64.RawURLEncoding.EncodeToString(headerJSON)
	payloadB64 := base64.RawURLEncoding.EncodeToString(payloadJSON)
	signingInput := headerB64 + "." + payloadB64

	hash := sha256.Sum256([]byte(signingInput))
	sig, err := rsa.SignPKCS1v15(rand.Reader, key, crypto.SHA256, hash[:])
	if err != nil {
		return "", err
	}

	return signingInput + "." + base64.RawURLEncoding.EncodeToString(sig), nil
}

func loadPrivateKey(path string) (*rsa.PrivateKey, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	return parsePrivateKeyPEM(data)
}

func parsePrivateKeyPEM(data []byte) (*rsa.PrivateKey, error) {
	block, _ := pem.Decode(data)
	if block == nil {
		return nil, fmt.Errorf("no PEM block found")
	}
	key, err := x509.ParsePKCS8PrivateKey(block.Bytes)
	if err != nil {
		return x509.ParsePKCS1PrivateKey(block.Bytes)
	}
	rsaKey, ok := key.(*rsa.PrivateKey)
	if !ok {
		return nil, fmt.Errorf("key is not RSA")
	}
	return rsaKey, nil
}

package auth

import (
	"context"
	"crypto/rand"
	"crypto/rsa"
	"crypto/x509"
	"encoding/pem"
	"fmt"
	"log"
	"os"

	corev1 "k8s.io/api/core/v1"
	k8serrors "k8s.io/apimachinery/pkg/api/errors"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/client-go/kubernetes"
)

const (
	jwtKeySecretName = "gratefulagents-jwt-signing-key"
	jwtKeySecretKey  = "private.pem"
)

// EnsureSigningKeyPEM returns a persistent PEM-encoded RSA signing key backed
// by a Kubernetes Secret, generating and storing one on first use. This keeps
// JWTs valid across manager restarts and consistent across replicas, unlike
// the previous ephemeral in-memory key.
func EnsureSigningKeyPEM(ctx context.Context, clientset kubernetes.Interface) ([]byte, error) {
	namespace := os.Getenv("POD_NAMESPACE")
	if namespace == "" {
		namespace = "default"
	}
	secrets := clientset.CoreV1().Secrets(namespace)

	existing, err := secrets.Get(ctx, jwtKeySecretName, metav1.GetOptions{})
	if err == nil {
		if pemBytes := existing.Data[jwtKeySecretKey]; len(pemBytes) > 0 {
			return pemBytes, nil
		}
		return nil, fmt.Errorf("secret %s/%s exists but has no %q key", namespace, jwtKeySecretName, jwtKeySecretKey)
	}
	if !k8serrors.IsNotFound(err) {
		return nil, fmt.Errorf("checking JWT signing key secret: %w", err)
	}

	pk, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		return nil, fmt.Errorf("generating JWT signing key: %w", err)
	}
	der, err := x509.MarshalPKCS8PrivateKey(pk)
	if err != nil {
		return nil, fmt.Errorf("marshaling JWT signing key: %w", err)
	}
	pemBytes := pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: der})

	secret := &corev1.Secret{
		ObjectMeta: metav1.ObjectMeta{
			Name:      jwtKeySecretName,
			Namespace: namespace,
		},
		Data: map[string][]byte{jwtKeySecretKey: pemBytes},
	}
	if _, err := secrets.Create(ctx, secret, metav1.CreateOptions{}); err != nil {
		// Another replica may have created it concurrently — re-read and use it.
		if k8serrors.IsAlreadyExists(err) {
			created, getErr := secrets.Get(ctx, jwtKeySecretName, metav1.GetOptions{})
			if getErr != nil {
				return nil, fmt.Errorf("reading concurrently created JWT signing key secret: %w", getErr)
			}
			if pemBytes := created.Data[jwtKeySecretKey]; len(pemBytes) > 0 {
				return pemBytes, nil
			}
			return nil, fmt.Errorf("concurrently created secret %s/%s has no %q key", namespace, jwtKeySecretName, jwtKeySecretKey)
		}
		return nil, fmt.Errorf("creating JWT signing key secret: %w", err)
	}
	log.Printf("JWT signing key generated and persisted in secret %s/%s", namespace, jwtKeySecretName)
	return pemBytes, nil
}

// NewJWTIssuerFromPEM creates an issuer from a PEM-encoded RSA private key.
func NewJWTIssuerFromPEM(pemBytes []byte) (*JWTIssuer, error) {
	pk, err := parsePrivateKeyPEM(pemBytes)
	if err != nil {
		return nil, fmt.Errorf("parse private key: %w", err)
	}
	return newJWTIssuerFromKey(pk)
}

package auth

import (
	"context"
	"errors"
	"net/http"
	"strings"
)

// currentClaims replaces identity fields embedded in an access token with the
// current stored user values. Access tokens live for several minutes, while
// role promotions and demotions are expected to take effect immediately.
func currentClaims(ctx context.Context, claims *Claims, store Store) (*Claims, error) {
	if claims == nil || store == nil {
		return nil, errors.New("auth store unavailable")
	}
	user, err := store.GetUserByID(ctx, claims.Sub)
	if err != nil {
		return nil, err
	}
	resolved := *claims
	resolved.Username = user.Username
	resolved.Email = user.Email
	resolved.Name = user.Name
	resolved.Picture = user.Picture
	resolved.Role = user.Role
	return &resolved, nil
}

// JWTMiddleware returns a chi middleware that validates JWT Bearer tokens.
// The current stored role overrides the role embedded in the token so
// promotions and demotions apply without waiting for expiry. Requests fail
// closed when the store cannot resolve the user.
func JWTMiddleware(jwks *JWKSCache, store Store) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			authHeader := r.Header.Get("Authorization")
			if authHeader == "" {
				http.Error(w, "missing authorization header", http.StatusUnauthorized)
				return
			}

			if !strings.HasPrefix(authHeader, "Bearer ") {
				http.Error(w, "invalid authorization header", http.StatusUnauthorized)
				return
			}

			token := strings.TrimPrefix(authHeader, "Bearer ")
			claims, err := jwks.VerifyToken(token)
			if err != nil {
				http.Error(w, "invalid token: "+err.Error(), http.StatusUnauthorized)
				return
			}
			claims, err = currentClaims(r.Context(), claims, store)
			if err != nil {
				http.Error(w, "unable to resolve current user", http.StatusServiceUnavailable)
				return
			}

			ctx := WithClaims(r.Context(), claims)
			next.ServeHTTP(w, r.WithContext(ctx))
		})
	}
}

// OptionalJWTMiddleware validates a Bearer token when one is provided and
// injects the claims, but never rejects the request. It lets mixed routes
// (e.g. the auth service, where Login must stay public) serve handlers that
// need the caller identity, such as GetCurrentUser and SearchUsers.
func OptionalJWTMiddleware(jwks *JWKSCache, store Store) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			authHeader := r.Header.Get("Authorization")
			if strings.HasPrefix(authHeader, "Bearer ") {
				token := strings.TrimPrefix(authHeader, "Bearer ")
				if claims, err := jwks.VerifyToken(token); err == nil {
					if claims, err = currentClaims(r.Context(), claims, store); err == nil {
						r = r.WithContext(WithClaims(r.Context(), claims))
					}
				}
			}
			next.ServeHTTP(w, r)
		})
	}
}

package auth

import (
	"os"
	"strings"
)

// RoleAdmin has full access to everything.
const RoleAdmin = "admin"

// RoleMember can create/modify own resources and view shared resources.
const RoleMember = "member"

// RoleViewer has read-only access to all resources.
const RoleViewer = "viewer"

// RoleResolver determines what role a Google OAuth user should get.
type RoleResolver struct {
	adminEmails      map[string]bool
	ssoDefaultViewer bool
}

// NewRoleResolver creates a role resolver from environment configuration.
// ADMIN_EMAILS: comma-separated emails that get admin role.
// SSO_DEFAULT_READONLY: if "true", non-admin SSO users get viewer role instead of member.
func NewRoleResolver() *RoleResolver {
	adminEmails := make(map[string]bool)
	if raw := os.Getenv("ADMIN_EMAILS"); raw != "" {
		for _, email := range strings.Split(raw, ",") {
			email = strings.TrimSpace(strings.ToLower(email))
			if email != "" {
				adminEmails[email] = true
			}
		}
	}

	ssoDefault := strings.EqualFold(os.Getenv("SSO_DEFAULT_READONLY"), "true")

	return &RoleResolver{
		adminEmails:      adminEmails,
		ssoDefaultViewer: ssoDefault,
	}
}

// ResolveRole determines the role for a Google OAuth user based on their email.
func (r *RoleResolver) ResolveRole(email string) string {
	if r.adminEmails[strings.ToLower(email)] {
		return RoleAdmin
	}
	if r.ssoDefaultViewer {
		return RoleViewer
	}
	return RoleMember
}

package auth

import (
	"context"
	"crypto/rand"
	"encoding/base64"
	"fmt"
	"log"
	"os"
	"time"

	"golang.org/x/crypto/bcrypt"
	corev1 "k8s.io/api/core/v1"
	k8serrors "k8s.io/apimachinery/pkg/api/errors"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/client-go/kubernetes"
)

const (
	adminSecretName     = "gratefulagents-admin-credentials"
	adminUsername       = "admin"
	passwordLength      = 24
	setupTokenKey       = "setup-token"
	setupTokenExpiryKey = "setup-token-expiry"
	setupTokenTTL       = 7 * 24 * time.Hour
)

// podNamespace returns the namespace this controller runs in, defaulting to
// "default" outside a cluster.
func podNamespace() string {
	if ns := os.Getenv("POD_NAMESPACE"); ns != "" {
		return ns
	}
	return "default"
}

// SeedAdmin ensures a local admin user exists. It reads or creates a Kubernetes
// secret containing the admin credentials, then upserts the admin user in the
// auth store.
func SeedAdmin(ctx context.Context, clientset kubernetes.Interface, store Store) error {
	namespace := podNamespace()

	secrets := clientset.CoreV1().Secrets(namespace)

	var password string

	existing, err := secrets.Get(ctx, adminSecretName, metav1.GetOptions{})
	if err != nil {
		if !k8serrors.IsNotFound(err) {
			return fmt.Errorf("checking admin secret: %w", err)
		}
		// Secret doesn't exist — generate new password and create it.
		password, err = generatePassword(passwordLength)
		if err != nil {
			return fmt.Errorf("generating admin password: %w", err)
		}
		setupToken, err := generateSetupToken()
		if err != nil {
			return fmt.Errorf("generating setup token: %w", err)
		}
		secret := &corev1.Secret{
			ObjectMeta: metav1.ObjectMeta{
				Name:      adminSecretName,
				Namespace: namespace,
			},
			Data: map[string][]byte{
				"username":          []byte(adminUsername),
				"password":          []byte(password),
				setupTokenKey:       []byte(setupToken),
				setupTokenExpiryKey: []byte(time.Now().Add(setupTokenTTL).Format(time.RFC3339)),
			},
		}
		if _, err := secrets.Create(ctx, secret, metav1.CreateOptions{}); err != nil {
			return fmt.Errorf("creating admin secret: %w", err)
		}
		log.Printf("Admin credentials created — sign in via the one-time setup link (<dashboard-url>/login?setup_token=<token>, token in the %q key of secret %s/%s), or retrieve the password with: kubectl get secret %s -n %s -o jsonpath='{.data.password}' | base64 -d",
			setupTokenKey, namespace, adminSecretName, adminSecretName, namespace)
	} else {
		password = string(existing.Data["password"])
		if password == "" {
			return fmt.Errorf("admin secret exists but has no password")
		}
	}

	// If the admin user already exists, leave it untouched: re-seeding would
	// overwrite a manually adjusted role and needlessly re-hash the password.
	if existingUser, err := store.GetUserByUsername(ctx, adminUsername); err == nil && existingUser != nil {
		return nil
	}

	hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		return fmt.Errorf("hashing admin password: %w", err)
	}

	_, err = store.UpsertUser(ctx, &User{
		Username:     adminUsername,
		Name:         "Admin",
		PasswordHash: string(hash),
		Role:         RoleAdmin,
	})
	if err != nil {
		return fmt.Errorf("seeding admin user: %w", err)
	}

	log.Printf("Admin user seeded (username: %s)", adminUsername)
	return nil
}

func generatePassword(n int) (string, error) {
	b := make([]byte, n)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(b)[:n], nil
}

func generateSetupToken() (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(b), nil
}

package auth

import (
	"context"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"fmt"
	"time"

	"connectrpc.com/connect"
	"golang.org/x/crypto/bcrypt"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/client-go/kubernetes"

	authpb "github.com/gratefulagents/gratefulagents/rpc/auth"
)

const (
	accessTokenTTL  = 15 * time.Minute
	refreshTokenTTL = 30 * 24 * time.Hour
)

// Server implements the AuthService RPC handlers.
type Server struct {
	store     Store
	google    *GoogleVerifier // nil if Google OAuth is not configured
	jwt       *JWTIssuer
	resolver  *RoleResolver
	clientset kubernetes.Interface // nil when setup-token redemption is unavailable
}

// NewServer creates a new integrated auth server.
func NewServer(store Store, google *GoogleVerifier, jwt *JWTIssuer, resolver *RoleResolver, clientset kubernetes.Interface) *Server {
	return &Server{
		store:     store,
		google:    google,
		jwt:       jwt,
		resolver:  resolver,
		clientset: clientset,
	}
}

func (s *Server) Login(ctx context.Context, req *connect.Request[authpb.LoginRequest]) (*connect.Response[authpb.LoginResponse], error) {
	var user *User

	if req.Msg.GoogleIdToken != "" {
		// Google OAuth login
		u, err := s.loginGoogle(ctx, req.Msg.GoogleIdToken)
		if err != nil {
			return nil, err
		}
		user = u
	} else if req.Msg.Username != "" && req.Msg.Password != "" {
		// Username/password login
		u, err := s.loginPassword(ctx, req.Msg.Username, req.Msg.Password)
		if err != nil {
			return nil, err
		}
		user = u
	} else {
		return nil, connect.NewError(connect.CodeInvalidArgument, fmt.Errorf("provide google_id_token or username+password"))
	}

	return s.issueLoginResponse(ctx, user)
}

// issueLoginResponse records the login and mints the access/refresh token pair
// shared by password, Google, and setup-token logins.
func (s *Server) issueLoginResponse(ctx context.Context, user *User) (*connect.Response[authpb.LoginResponse], error) {
	// Record the login time for the admin user view; best-effort.
	if err := s.store.TouchUserLastLogin(ctx, user.ID); err == nil {
		now := time.Now()
		user.LastLoginAt = &now
	}

	// Issue tokens
	accessToken, expiresAt, err := s.jwt.IssueAccessToken(AccessTokenClaims{
		Sub:      user.ID,
		Username: user.Username,
		Email:    user.Email,
		Name:     user.Name,
		Picture:  user.Picture,
		Role:     user.Role,
	}, accessTokenTTL)
	if err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("issue access token: %w", err))
	}

	refreshToken, refreshExp, err := s.jwt.IssueRefreshToken(user.ID, refreshTokenTTL)
	if err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("issue refresh token: %w", err))
	}

	if err := s.store.CreateSession(ctx, &Session{
		UserID:           user.ID,
		RefreshTokenHash: hashToken(refreshToken),
		ExpiresAt:        time.Unix(refreshExp, 0),
	}); err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("create session: %w", err))
	}

	return connect.NewResponse(&authpb.LoginResponse{
		AccessToken:  accessToken,
		RefreshToken: refreshToken,
		ExpiresAt:    expiresAt,
		User:         userToProto(user),
	}), nil
}

func (s *Server) loginGoogle(ctx context.Context, idToken string) (*User, error) {
	if s.google == nil {
		return nil, connect.NewError(connect.CodeUnavailable, fmt.Errorf("Google OAuth is not configured"))
	}

	claims, err := s.google.Verify(ctx, idToken)
	if err != nil {
		return nil, connect.NewError(connect.CodeUnauthenticated, fmt.Errorf("google token: %w", err))
	}
	if !claims.EmailVerified {
		return nil, connect.NewError(connect.CodePermissionDenied, fmt.Errorf("email not verified"))
	}

	role := s.resolver.ResolveRole(claims.Email)

	// Use email prefix as username for Google users
	username := claims.Email
	user, err := s.store.UpsertUser(ctx, &User{
		Username: username,
		Email:    claims.Email,
		Name:     claims.Name,
		Picture:  claims.Picture,
		GoogleID: claims.Sub,
		Role:     role,
	})
	if err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("upsert user: %w", err))
	}

	return user, nil
}

func (s *Server) loginPassword(ctx context.Context, username, password string) (*User, error) {
	user, err := s.store.GetUserByUsername(ctx, username)
	if err != nil {
		return nil, connect.NewError(connect.CodeUnauthenticated, fmt.Errorf("invalid credentials"))
	}
	if user.PasswordHash == "" {
		return nil, connect.NewError(connect.CodeUnauthenticated, fmt.Errorf("invalid credentials"))
	}

	if err := bcrypt.CompareHashAndPassword([]byte(user.PasswordHash), []byte(password)); err != nil {
		return nil, connect.NewError(connect.CodeUnauthenticated, fmt.Errorf("invalid credentials"))
	}

	return user, nil
}

// errInvalidSetupLink is the single generic failure returned for every
// redemption reject cause so the endpoint leaks nothing about token state.
func errInvalidSetupLink() *connect.Error {
	return connect.NewError(connect.CodeUnauthenticated, fmt.Errorf("invalid or expired setup link"))
}

func (s *Server) RedeemSetupToken(ctx context.Context, req *connect.Request[authpb.RedeemSetupTokenRequest]) (*connect.Response[authpb.LoginResponse], error) {
	presented := req.Msg.Token
	if s.clientset == nil || presented == "" {
		return nil, errInvalidSetupLink()
	}

	secrets := s.clientset.CoreV1().Secrets(podNamespace())
	secret, err := secrets.Get(ctx, adminSecretName, metav1.GetOptions{})
	if err != nil {
		return nil, errInvalidSetupLink()
	}
	stored := secret.Data[setupTokenKey]
	if len(stored) == 0 {
		return nil, errInvalidSetupLink()
	}
	expiry, err := time.Parse(time.RFC3339, string(secret.Data[setupTokenExpiryKey]))
	if err != nil || time.Now().After(expiry) {
		return nil, errInvalidSetupLink()
	}
	if subtle.ConstantTimeCompare([]byte(presented), stored) != 1 {
		return nil, errInvalidSetupLink()
	}

	user, err := s.store.GetUserByUsername(ctx, adminUsername)
	if err != nil {
		return nil, errInvalidSetupLink()
	}

	// Invalidate the token before issuing a session; a failed invalidation
	// must fail the redemption so the link cannot be replayed.
	delete(secret.Data, setupTokenKey)
	delete(secret.Data, setupTokenExpiryKey)
	if _, err := secrets.Update(ctx, secret, metav1.UpdateOptions{}); err != nil {
		return nil, errInvalidSetupLink()
	}

	return s.issueLoginResponse(ctx, user)
}

func (s *Server) RefreshToken(ctx context.Context, req *connect.Request[authpb.RefreshTokenRequest]) (*connect.Response[authpb.RefreshTokenResponse], error) {
	tokenHash := hashToken(req.Msg.RefreshToken)
	session, err := s.store.GetSessionByTokenHash(ctx, tokenHash)
	if err != nil {
		return nil, connect.NewError(connect.CodeUnauthenticated, fmt.Errorf("invalid refresh token"))
	}
	if time.Now().After(session.ExpiresAt) {
		_ = s.store.DeleteSession(ctx, session.ID)
		return nil, connect.NewError(connect.CodeUnauthenticated, fmt.Errorf("refresh token expired"))
	}

	user, err := s.store.GetUserByID(ctx, session.UserID)
	if err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("get user: %w", err))
	}

	accessToken, expiresAt, err := s.jwt.IssueAccessToken(AccessTokenClaims{
		Sub:      user.ID,
		Username: user.Username,
		Email:    user.Email,
		Name:     user.Name,
		Picture:  user.Picture,
		Role:     user.Role,
	}, accessTokenTTL)
	if err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("issue access token: %w", err))
	}

	newRefreshToken, refreshExp, err := s.jwt.IssueRefreshToken(user.ID, refreshTokenTTL)
	if err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("issue refresh token: %w", err))
	}
	// Atomically consume the old session and create the replacement so a
	// concurrently replayed refresh token cannot mint a second session.
	if err := s.store.RotateSession(ctx, session.ID, &Session{
		UserID:           user.ID,
		RefreshTokenHash: hashToken(newRefreshToken),
		ExpiresAt:        time.Unix(refreshExp, 0),
	}); err != nil {
		return nil, connect.NewError(connect.CodeUnauthenticated, fmt.Errorf("refresh token no longer valid"))
	}

	return connect.NewResponse(&authpb.RefreshTokenResponse{
		AccessToken:  accessToken,
		RefreshToken: newRefreshToken,
		ExpiresAt:    expiresAt,
	}), nil
}

func (s *Server) Logout(ctx context.Context, req *connect.Request[authpb.LogoutRequest]) (*connect.Response[authpb.LogoutResponse], error) {
	tokenHash := hashToken(req.Msg.RefreshToken)
	session, err := s.store.GetSessionByTokenHash(ctx, tokenHash)
	if err == nil {
		_ = s.store.DeleteSession(ctx, session.ID)
	}
	return connect.NewResponse(&authpb.LogoutResponse{}), nil
}

func (s *Server) GetCurrentUser(ctx context.Context, _ *connect.Request[authpb.GetCurrentUserRequest]) (*connect.Response[authpb.User], error) {
	claims := ClaimsFromContext(ctx)
	if claims == nil {
		return nil, connect.NewError(connect.CodeUnauthenticated, fmt.Errorf("not authenticated"))
	}

	user, err := s.store.GetUserByID(ctx, claims.Sub)
	if err != nil {
		return nil, connect.NewError(connect.CodeNotFound, fmt.Errorf("user not found"))
	}

	return connect.NewResponse(userToProto(user)), nil
}

func (s *Server) SearchUsers(ctx context.Context, req *connect.Request[authpb.SearchUsersRequest]) (*connect.Response[authpb.SearchUsersResponse], error) {
	if ClaimsFromContext(ctx) == nil {
		return nil, connect.NewError(connect.CodeUnauthenticated, fmt.Errorf("authentication required"))
	}
	if req.Msg.Query == "" {
		return connect.NewResponse(&authpb.SearchUsersResponse{}), nil
	}

	limit := req.Msg.Limit
	if limit <= 0 {
		limit = 10
	}

	users, err := s.store.SearchUsers(ctx, req.Msg.Query, limit)
	if err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("search users: %w", err))
	}

	var pbUsers []*authpb.UserSummary
	for _, u := range users {
		pbUsers = append(pbUsers, &authpb.UserSummary{
			Id:       u.ID,
			Email:    u.Email,
			Name:     u.Name,
			Picture:  u.Picture,
			Username: u.Username,
		})
	}

	return connect.NewResponse(&authpb.SearchUsersResponse{
		Users: pbUsers,
	}), nil
}

// --- Admin user management ---

// requireAdmin returns the caller's claims when they are an authenticated
// admin, or a connect error otherwise.
func requireAdmin(ctx context.Context) (*Claims, error) {
	claims := ClaimsFromContext(ctx)
	if claims == nil {
		return nil, connect.NewError(connect.CodeUnauthenticated, fmt.Errorf("authentication required"))
	}
	if claims.Role != RoleAdmin {
		return nil, connect.NewError(connect.CodePermissionDenied, fmt.Errorf("admin role required"))
	}
	return claims, nil
}

func (s *Server) ListUsers(ctx context.Context, _ *connect.Request[authpb.ListUsersRequest]) (*connect.Response[authpb.ListUsersResponse], error) {
	if _, err := requireAdmin(ctx); err != nil {
		return nil, err
	}
	users, err := s.store.ListUsers(ctx)
	if err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("list users: %w", err))
	}
	resp := &authpb.ListUsersResponse{}
	for _, u := range users {
		resp.Users = append(resp.Users, userToProto(u))
	}
	return connect.NewResponse(resp), nil
}

func (s *Server) UpdateUserRole(ctx context.Context, req *connect.Request[authpb.UpdateUserRoleRequest]) (*connect.Response[authpb.User], error) {
	claims, err := requireAdmin(ctx)
	if err != nil {
		return nil, err
	}
	role := req.Msg.Role
	if role != RoleAdmin && role != RoleMember && role != RoleViewer {
		return nil, connect.NewError(connect.CodeInvalidArgument, fmt.Errorf("invalid role %q: must be admin, member, or viewer", role))
	}
	if req.Msg.UserId == "" {
		return nil, connect.NewError(connect.CodeInvalidArgument, fmt.Errorf("user_id is required"))
	}
	if req.Msg.UserId == claims.Sub && role != RoleAdmin {
		return nil, connect.NewError(connect.CodeFailedPrecondition, fmt.Errorf("you cannot demote your own admin account"))
	}
	if _, err := s.store.GetUserByID(ctx, req.Msg.UserId); err != nil {
		return nil, connect.NewError(connect.CodeNotFound, fmt.Errorf("user not found"))
	}
	if err := s.store.SetUserRole(ctx, req.Msg.UserId, role); err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("set user role: %w", err))
	}
	user, err := s.store.GetUserByID(ctx, req.Msg.UserId)
	if err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("get user: %w", err))
	}
	return connect.NewResponse(userToProto(user)), nil
}

func (s *Server) DeleteUser(ctx context.Context, req *connect.Request[authpb.DeleteUserRequest]) (*connect.Response[authpb.DeleteUserResponse], error) {
	claims, err := requireAdmin(ctx)
	if err != nil {
		return nil, err
	}
	if req.Msg.UserId == "" {
		return nil, connect.NewError(connect.CodeInvalidArgument, fmt.Errorf("user_id is required"))
	}
	if req.Msg.UserId == claims.Sub {
		return nil, connect.NewError(connect.CodeFailedPrecondition, fmt.Errorf("you cannot delete your own account"))
	}
	if err := s.store.DeleteUser(ctx, req.Msg.UserId); err != nil {
		return nil, connect.NewError(connect.CodeNotFound, fmt.Errorf("user not found"))
	}
	return connect.NewResponse(&authpb.DeleteUserResponse{}), nil
}

func (s *Server) GetJWKS(_ context.Context, _ *connect.Request[authpb.GetJWKSRequest]) (*connect.Response[authpb.GetJWKSResponse], error) {
	jwks, err := s.jwt.JWKSJSON()
	if err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("generate JWKS: %w", err))
	}
	return connect.NewResponse(&authpb.GetJWKSResponse{
		KeysJson: jwks,
	}), nil
}

func hashToken(token string) string {
	h := sha256.Sum256([]byte(token))
	return hex.EncodeToString(h[:])
}

// userToProto converts a stored user into its RPC representation.
func userToProto(u *User) *authpb.User {
	pb := &authpb.User{
		Id:        u.ID,
		Email:     u.Email,
		Name:      u.Name,
		Picture:   u.Picture,
		Username:  u.Username,
		Role:      u.Role,
		CreatedAt: u.CreatedAt.Unix(),
	}
	if u.LastLoginAt != nil {
		pb.LastLoginAt = u.LastLoginAt.Unix()
	}
	return pb
}

package auth

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// User represents a registered user with a flat role model.
type User struct {
	ID           string
	Username     string
	Email        string // populated from Google OAuth; empty for local accounts
	Name         string
	Picture      string
	PasswordHash string // bcrypt hash; empty for OAuth-only accounts
	GoogleID     string // empty for local accounts
	Role         string // "admin", "member", or "viewer"
	CreatedAt    time.Time
	UpdatedAt    time.Time
	LastLoginAt  *time.Time // nil if the user never logged in
}

// Session represents a refresh token session.
type Session struct {
	ID               string
	UserID           string
	RefreshTokenHash string
	ExpiresAt        time.Time
	CreatedAt        time.Time
}

// UserSummary is a lightweight user representation for search results.
type UserSummary struct {
	ID       string
	Username string
	Email    string
	Name     string
	Picture  string
}

// UserNamespace maps a user to their personal Kubernetes namespace, where their
// saved credential secrets and projects live. It is persisted so the namespace
// stays stable across display-name changes.
type UserNamespace struct {
	UserID    string
	Namespace string
	CreatedAt time.Time
}

// UserSoul is a user's personal SOUL: a role/persona definition they edit for
// their own agent. Other users' agents can consult it (via the ask_teammate
// tool) to get that teammate's likely perspective.
type UserSoul struct {
	UserID    string
	Content   string
	UpdatedAt time.Time
}

// UserGitIdentity contains a user's git commit settings. When name and email
// are set, AgentRuns the user creates author commits with that identity.
type UserGitIdentity struct {
	UserID    string
	Name      string
	Email     string
	UpdatedAt time.Time
}

// UserRoleModelPreference is one personal specialist-model setting. A
// UseParentModel entry is role-wide and bypasses provider/platform mappings.
type UserRoleModelPreference struct {
	UserID         string
	RoleName       string
	Provider       string
	Model          string
	UseParentModel bool
	UpdatedAt      time.Time
}

// UserModelDefaults is a user's personal default provider/auth mode/model/
// reasoning level. Disabled keeps the saved values but tells clients not to
// auto-apply them.
type UserModelDefaults struct {
	UserID         string
	Provider       string
	AuthMode       string
	Model          string
	ReasoningLevel string
	Disabled       bool
	UpdatedAt      time.Time
}

// UserModelDefaultsStore is an optional extension implemented by auth stores
// that persist personal model defaults. Keeping it separate from Store lets
// lightweight auth fakes and alternate auth backends remain source-compatible.
type UserModelDefaultsStore interface {
	GetUserModelDefaults(ctx context.Context, userID string) (*UserModelDefaults, error)
	UpsertUserModelDefaults(ctx context.Context, defaults *UserModelDefaults) (*UserModelDefaults, error)
	DeleteUserModelDefaults(ctx context.Context, userID string) error
}

// UserRoleModelStore is an optional extension implemented by auth stores that
// persist personal role-model preferences. Keeping it separate from Store lets
// lightweight auth fakes and alternate auth backends remain source-compatible.
type UserRoleModelStore interface {
	ListUserRoleModelPreferences(ctx context.Context, userID string) ([]*UserRoleModelPreference, error)
	ReplaceUserRoleModelPreferences(ctx context.Context, userID string, preferences []*UserRoleModelPreference) ([]*UserRoleModelPreference, error)
}

// Store defines the persistence interface for integrated auth.
type Store interface {
	UpsertUser(ctx context.Context, u *User) (*User, error)
	GetUserByID(ctx context.Context, id string) (*User, error)
	GetUserByUsername(ctx context.Context, username string) (*User, error)
	GetUserByGoogleID(ctx context.Context, googleID string) (*User, error)
	SearchUsers(ctx context.Context, query string, limit int32) ([]*User, error)
	SetUserRole(ctx context.Context, userID, role string) error
	// ListUsers returns all registered users ordered by creation time.
	ListUsers(ctx context.Context) ([]*User, error)
	// DeleteUser permanently removes a user and their sessions.
	DeleteUser(ctx context.Context, userID string) error
	// TouchUserLastLogin records that the user just logged in.
	TouchUserLastLogin(ctx context.Context, userID string) error

	// GetUserNamespace returns the user's persisted personal namespace, or empty
	// string when none has been assigned yet.
	GetUserNamespace(ctx context.Context, userID string) (string, error)
	// SetUserNamespace persists the user's personal namespace. It is a no-op if a
	// namespace is already assigned (the first assignment wins).
	SetUserNamespace(ctx context.Context, userID, namespace string) error

	// GetUserSoul returns the user's personal SOUL, or nil if none is saved.
	GetUserSoul(ctx context.Context, userID string) (*UserSoul, error)
	// UpsertUserSoul creates or updates the user's personal SOUL.
	UpsertUserSoul(ctx context.Context, soul *UserSoul) (*UserSoul, error)

	// GetUserGitIdentity returns the user's git commit identity, or nil if none
	// is saved.
	GetUserGitIdentity(ctx context.Context, userID string) (*UserGitIdentity, error)
	// UpsertUserGitIdentity creates or updates the user's git commit identity.
	UpsertUserGitIdentity(ctx context.Context, identity *UserGitIdentity) (*UserGitIdentity, error)

	CreateSession(ctx context.Context, s *Session) error
	GetSessionByTokenHash(ctx context.Context, hash string) (*Session, error)
	DeleteSession(ctx context.Context, id string) error
	DeleteExpiredSessions(ctx context.Context) error
	// RotateSession atomically consumes the old session and creates its
	// replacement. It fails when the old session was already consumed,
	// enforcing one-time use of refresh tokens under concurrency.
	RotateSession(ctx context.Context, oldSessionID string, replacement *Session) error
}

// PGStore implements Store backed by Postgres via pgx.
type PGStore struct {
	pool *pgxpool.Pool
}

// NewPGStore creates a new Postgres-backed auth store from an existing pool.
func NewPGStore(pool *pgxpool.Pool) *PGStore {
	return &PGStore{pool: pool}
}

func (s *PGStore) UpsertUser(ctx context.Context, u *User) (*User, error) {
	row := s.pool.QueryRow(ctx, `
		INSERT INTO auth_users (username, email, name, picture, password_hash, google_id, role)
		VALUES ($1, $2, $3, $4, $5, $6, $7)
		ON CONFLICT (username) DO UPDATE SET
			email = COALESCE(NULLIF(EXCLUDED.email, ''), auth_users.email),
			name = COALESCE(NULLIF(EXCLUDED.name, ''), auth_users.name),
			picture = COALESCE(NULLIF(EXCLUDED.picture, ''), auth_users.picture),
			password_hash = COALESCE(NULLIF(EXCLUDED.password_hash, ''), auth_users.password_hash),
			google_id = COALESCE(NULLIF(EXCLUDED.google_id, ''), auth_users.google_id),
			-- Existing roles are managed explicitly by SetUserRole. Preserving the
			-- stored value prevents an SSO profile refresh from undoing a manual
			-- promotion or demotion with the resolver's default role.
			role = auth_users.role,
			updated_at = now()
		RETURNING id, username, COALESCE(email, ''), name, picture,
			COALESCE(password_hash, ''), COALESCE(google_id, ''), role,
			created_at, updated_at, last_login_at`,
		u.Username, nullableString(u.Email), u.Name, u.Picture,
		nullableString(u.PasswordHash), nullableString(u.GoogleID), u.Role)
	return scanUser(row)
}

func (s *PGStore) GetUserByID(ctx context.Context, id string) (*User, error) {
	row := s.pool.QueryRow(ctx, `
		SELECT id, username, COALESCE(email, ''), name, picture,
			COALESCE(password_hash, ''), COALESCE(google_id, ''), role,
			created_at, updated_at, last_login_at
		FROM auth_users WHERE id = $1`, id)
	return scanUser(row)
}

func (s *PGStore) GetUserByUsername(ctx context.Context, username string) (*User, error) {
	row := s.pool.QueryRow(ctx, `
		SELECT id, username, COALESCE(email, ''), name, picture,
			COALESCE(password_hash, ''), COALESCE(google_id, ''), role,
			created_at, updated_at, last_login_at
		FROM auth_users WHERE username = $1`, username)
	return scanUser(row)
}

func (s *PGStore) GetUserByGoogleID(ctx context.Context, googleID string) (*User, error) {
	row := s.pool.QueryRow(ctx, `
		SELECT id, username, COALESCE(email, ''), name, picture,
			COALESCE(password_hash, ''), COALESCE(google_id, ''), role,
			created_at, updated_at, last_login_at
		FROM auth_users WHERE google_id = $1`, googleID)
	return scanUser(row)
}

func (s *PGStore) SearchUsers(ctx context.Context, query string, limit int32) ([]*User, error) {
	if limit <= 0 || limit > 50 {
		limit = 10
	}
	pattern := "%" + escapeLikePattern(query) + "%"
	rows, err := s.pool.Query(ctx, `
		SELECT id, username, COALESCE(email, ''), name, picture,
			COALESCE(password_hash, ''), COALESCE(google_id, ''), role,
			created_at, updated_at, last_login_at
		FROM auth_users
		WHERE username ILIKE $1 OR name ILIKE $1 OR email ILIKE $1
		ORDER BY name
		LIMIT $2`, pattern, limit)
	if err != nil {
		return nil, fmt.Errorf("searching users: %w", err)
	}
	defer rows.Close()
	var users []*User
	for rows.Next() {
		u, err := scanUserRow(rows)
		if err != nil {
			return nil, err
		}
		users = append(users, u)
	}
	return users, rows.Err()
}

func (s *PGStore) SetUserRole(ctx context.Context, userID, role string) error {
	_, err := s.pool.Exec(ctx, `
		UPDATE auth_users SET role = $1, updated_at = now() WHERE id = $2`,
		role, userID)
	if err != nil {
		return fmt.Errorf("setting user role: %w", err)
	}
	return nil
}

func (s *PGStore) ListUsers(ctx context.Context) ([]*User, error) {
	rows, err := s.pool.Query(ctx, `
		SELECT id, username, COALESCE(email, ''), name, picture,
			COALESCE(password_hash, ''), COALESCE(google_id, ''), role,
			created_at, updated_at, last_login_at
		FROM auth_users
		ORDER BY created_at`)
	if err != nil {
		return nil, fmt.Errorf("listing users: %w", err)
	}
	defer rows.Close()
	var users []*User
	for rows.Next() {
		u, err := scanUserRow(rows)
		if err != nil {
			return nil, err
		}
		users = append(users, u)
	}
	return users, rows.Err()
}

func (s *PGStore) DeleteUser(ctx context.Context, userID string) error {
	// Sessions (and other per-user auth rows) cascade via foreign keys.
	tag, err := s.pool.Exec(ctx, `DELETE FROM auth_users WHERE id = $1`, userID)
	if err != nil {
		return fmt.Errorf("deleting user: %w", err)
	}
	if tag.RowsAffected() == 0 {
		return pgx.ErrNoRows
	}
	return nil
}

func (s *PGStore) TouchUserLastLogin(ctx context.Context, userID string) error {
	_, err := s.pool.Exec(ctx, `
		UPDATE auth_users SET last_login_at = now() WHERE id = $1`, userID)
	if err != nil {
		return fmt.Errorf("touching user last login: %w", err)
	}
	return nil
}

// --- User namespaces ---

func (s *PGStore) GetUserNamespace(ctx context.Context, userID string) (string, error) {
	var namespace string
	err := s.pool.QueryRow(ctx, `
		SELECT namespace FROM auth_user_namespaces WHERE user_id = $1`, userID).
		Scan(&namespace)
	if err != nil {
		if err == pgx.ErrNoRows {
			return "", nil
		}
		return "", fmt.Errorf("getting user namespace: %w", err)
	}
	return namespace, nil
}

func (s *PGStore) SetUserNamespace(ctx context.Context, userID, namespace string) error {
	// First assignment wins: a user's namespace must remain stable once chosen.
	if _, err := s.pool.Exec(ctx, `
		INSERT INTO auth_user_namespaces (user_id, namespace)
		VALUES ($1, $2)
		ON CONFLICT (user_id) DO NOTHING`, userID, namespace); err != nil {
		return fmt.Errorf("setting user namespace: %w", err)
	}
	return nil
}

// --- SOUL (personal persona) ---

func (s *PGStore) GetUserSoul(ctx context.Context, userID string) (*UserSoul, error) {
	var soul UserSoul
	err := s.pool.QueryRow(ctx, `
		SELECT user_id, content, updated_at
		FROM auth_user_souls WHERE user_id = $1`, userID).
		Scan(&soul.UserID, &soul.Content, &soul.UpdatedAt)
	if err != nil {
