func nullableString(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}

// escapeLikePattern escapes LIKE/ILIKE metacharacters so a search query
// matches literally instead of acting as a wildcard pattern.
func escapeLikePattern(s string) string {
	s = strings.ReplaceAll(s, `\`, `\\`)
	s = strings.ReplaceAll(s, `%`, `\%`)
	s = strings.ReplaceAll(s, `_`, `\_`)
	return s
}

package computeruse

import (
	"context"
	"sync"
	"time"

	"github.com/google/uuid"
)

type delivery struct {
	outcome Outcome
	err     error
}
type pending struct {
	request  Request
	ctx      context.Context
	deadline time.Time
	claimed  bool
	result   chan delivery
}

type Broker struct {
	mode                           string
	targetRevision                 uint64
	target                         *WindowTarget
	windows                        map[string]WindowTarget
	frameID                        string
	mu                             sync.Mutex
	namespace, run, owner, session string
	leaseUntil                     time.Time
	sessionContext                 context.Context
	sessionCancel                  context.CancelFunc
	pending                        *pending
	closed                         bool
	done                           chan struct{}
	vision                         func() bool
}

func New(namespace, run string) *Broker {
	b := &Broker{namespace: namespace, run: run, done: make(chan struct{})}
	go func() {
		ticker := time.NewTicker(50 * time.Millisecond)
		defer ticker.Stop()
		for {
			select {
			case <-b.done:
				return
			case <-ticker.C:
				b.mu.Lock()
				b.expire()
				b.mu.Unlock()
			}
		}
	}()
	return b
}

func (b *Broker) SetVisionAvailable(fn func() bool) { b.mu.Lock(); defer b.mu.Unlock(); b.vision = fn }

func (b *Broker) cancel() {
	if b.pending != nil {
		b.pending.result <- delivery{err: ErrRejected}
		b.pending = nil
	}
}

func (b *Broker) drop() {
	b.cancel()
	if b.sessionCancel != nil {
		b.sessionCancel()
	}
	b.sessionContext = nil
	b.sessionCancel = nil
	b.mode = ""
	b.targetRevision = 0
	b.target = nil
	b.windows = nil
	b.frameID = ""
	b.owner = ""
	b.session = ""
}

func (b *Broker) rejectPending() {
	if b.pending != nil && b.pending.claimed {
		b.drop()
	} else {
		b.cancel()
	}
}

type sessionContextKey struct{}

// SessionContext pins work to this attachment, even after its capture request resolves.
func (b *Broker) SessionContext(ctx context.Context) (context.Context, context.CancelFunc, error) {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.expire()
	if b.closed || b.session == "" || ctx.Err() != nil {
		return nil, nil, ErrRejected
	}
	ctx, cancel := context.WithCancel(context.WithValue(ctx, sessionContextKey{}, b.sessionContext))
	stop := context.AfterFunc(b.sessionContext, cancel)
	return ctx, func() { stop(); cancel() }, nil
}

func (b *Broker) sessionValid(ctx context.Context) bool {
	return !b.closed && b.session != "" && ctx.Err() == nil && ctx.Value(sessionContextKey{}) == b.sessionContext
}

func (b *Broker) SessionValid(ctx context.Context) bool {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.expire()
	return b.sessionValid(ctx)
}

func (b *Broker) expire() {
	now := time.Now()
	if b.session != "" && !now.Before(b.leaseUntil) {
		b.drop()
	}
	if b.pending != nil && (b.pending.ctx.Err() != nil || !now.Before(b.pending.deadline)) {
		b.rejectPending()
	}
}

func (b *Broker) Close() error {
	b.mu.Lock()
	defer b.mu.Unlock()
	if !b.closed {
		b.closed = true
		b.drop()
		close(b.done)
	}
	return nil
}

func (b *Broker) Active() bool {
	if b == nil {
		return false
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	b.expire()
	return !b.closed && b.session != ""
}

func (b *Broker) Exchange(e Exchange) (Response, error) {
	if err := e.Validate(); err != nil {
		return Response{}, err
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	b.expire()
	if b.closed || e.Namespace != b.namespace || e.Run != b.run {
		return Response{}, ErrRejected
	}
	if b.session != "" && (b.owner != e.Owner || b.session != e.SessionID) {
		return Response{}, ErrRejected
	}
	mode := "selected_window"
	if e.Operation == "attach_agent" {
		mode = "agent_choice"
	}
	if b.session != "" && (e.Operation == "attach" || e.Operation == "attach_agent") && b.mode != mode {
		return Response{}, ErrRejected
	}
	if (e.Operation == "attach" || e.Operation == "attach_agent") && b.session == "" {
		b.mode = mode
		b.owner = e.Owner
		b.session = e.SessionID
		b.sessionContext, b.sessionCancel = context.WithCancel(context.Background())
	}
	available := b.vision != nil && b.vision()
	if b.session == "" {
		if e.Operation == "claim" || e.Operation == "resolve" {
			return Response{}, ErrRejected
		}
		return Response{Reason: "session inactive", VisionAvailable: available}, nil
	}
	switch e.Operation {
	case "attach", "attach_agent", "poll":
		b.leaseUntil = time.Now().Add(Lease)
	case "stop":
		b.drop()
		return Response{Reason: "session stopped", VisionAvailable: available}, nil
	case "claim":
		p := b.pending
		if p == nil || p.request.RequestID != e.RequestID || p.claimed {
			return Response{}, ErrRejected
		}
		p.claimed = true
		p.deadline = minTime(p.deadline, time.Now().Add(ClaimTimeoutFor(p.request.Action)))
	case "resolve":
		p := b.pending
		if p == nil || p.request.RequestID != e.RequestID || !p.claimed {
			return Response{}, ErrRejected
		}
		if e.Outcome.Capture != nil && p.request.Action.Kind != "observe" {
			return Response{}, ErrRejected
		}
		if p.request.Action.Kind == "observe" && e.Outcome.Status == "completed" && e.Outcome.Capture == nil {
			return Response{}, ErrRejected
		}
		o := e.Outcome
		kind := p.request.Action.Kind
		if (kind != "list_windows" && len(o.Windows) != 0) || (kind != "select_window" && o.Target != nil) {
			return Response{}, ErrRejected
		}
		if b.mode == "agent_choice" {
			expected := b.targetRevision
			if kind == "select_window" && o.Status == "completed" {
				expected++
			}
			if o.TargetRevision != expected {
				return Response{}, ErrRejected
			}
			if o.Status == "completed" {
				switch kind {
				case "list_windows":
					b.windows = map[string]WindowTarget{}
					for _, w := range o.Windows {
						b.windows[w.Ref] = w
					}
				case "select_window":
					w, ok := b.windows[p.request.Action.TargetRef]
					if !ok || o.Target == nil || *o.Target != w {
						return Response{}, ErrRejected
					}
					b.target = o.Target
					b.targetRevision = expected
					b.frameID = ""
					b.windows = nil
				case "observe":
					b.frameID = o.Capture.FrameID
				default:
					b.frameID = ""
				}
			}
		} else if o.TargetRevision != 0 || o.Target != nil || len(o.Windows) != 0 {
			return Response{}, ErrRejected
		}
		p.result <- delivery{outcome: *e.Outcome}
		b.pending = nil
	}
	r := Response{Active: true, VisionAvailable: available}
	if b.mode == "agent_choice" {
		r.Mode = b.mode
	}
	if b.pending != nil && !b.pending.claimed {
		copy := b.pending.request
		r.Pending = &copy
	}
	return r, nil
}

func minTime(a, b time.Time) time.Time {
	if a.Before(b) {
		return a
	}
	return b
}

func (b *Broker) Request(ctx context.Context, action Action, frameID string) (Outcome, error) {
	// wait is an agent-side pause, never a desktop request.
	if action.Kind == "wait" || action.Validate() != nil || (frameID != "" && !identifier.MatchString(frameID)) {
		return Outcome{}, ErrRejected
	}
	if ctx.Value(sessionContextKey{}) == nil {
		var cancel context.CancelFunc
		var err error
		ctx, cancel, err = b.SessionContext(ctx)
		if err != nil {
			return Outcome{}, err
		}
		defer cancel()
	}
	b.mu.Lock()
	b.expire()
	if !b.sessionValid(ctx) {
		b.mu.Unlock()
		return Outcome{}, ErrRejected
	}
	if b.pending != nil {
		b.mu.Unlock()
		return Outcome{}, ErrBusy
	}
	discovery := action.Kind == "list_windows" || action.Kind == "select_window"
	if discovery && (b.mode != "agent_choice" || frameID != "") {
		b.mu.Unlock()
		return Outcome{}, ErrDiscoveryUnavailable
	}
	if b.mode == "agent_choice" {
		if action.Kind == "select_window" {
			if _, ok := b.windows[action.TargetRef]; !ok {
				b.mu.Unlock()
				return Outcome{}, ErrUnknownTarget
			}
		}
		if !discovery && b.target == nil {
			b.mu.Unlock()
			return Outcome{}, ErrNoTarget
		}
		if action.Kind == "open_url" {
			b.mu.Unlock()
			return Outcome{}, ErrOpenURLUnavailable
		}
		if action.IsInput() && (frameID == "" || frameID != b.frameID) {
			b.mu.Unlock()
			return Outcome{}, ErrStaleFrame
		}
	}
	p := &pending{request: Request{TargetRevision: b.targetRevision, RequestID: uuid.NewString(), FrameID: frameID, Action: action}, ctx: ctx, deadline: time.Now().Add(RequestTimeout), result: make(chan delivery, 1)}
	b.pending = p
	b.mu.Unlock()
	select {
	case d := <-p.result:
		if !b.SessionValid(ctx) {
			return Outcome{}, ErrRejected
		}
		return d.outcome, d.err
	case <-ctx.Done():
		b.mu.Lock()
		if b.pending == p {
			b.rejectPending()
		}
		b.mu.Unlock()
		return Outcome{}, ErrRejected
	}
}

type contextKey struct{}

func WithBroker(ctx context.Context, b *Broker) context.Context {
	return context.WithValue(ctx, contextKey{}, b)
}
func FromContext(ctx context.Context) *Broker { b, _ := ctx.Value(contextKey{}).(*Broker); return b }

package computeruse

import (
	"bytes"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"image/png"
	"io"
	"math"
	"net/url"
	"regexp"
	"strings"
	"time"
	"unicode"
	"unicode/utf16"
	"unicode/utf8"
)

const (
	MaxWire        = 12 << 20
	MaxScreenshot  = 8 << 20
	Lease          = 10 * time.Second
	RequestTimeout = 120 * time.Second
	// ClaimTimeout bounds the time between a desktop claiming a request and
	// resolving it. Observation must fit a native capture plus the PNG upload;
	// typing must fit per-character native delivery; other input is quick.
	ClaimTimeout        = 15 * time.Second
	ObserveClaimTimeout = 30 * time.Second
	TypeClaimTimeout    = 60 * time.Second
)

var ErrRejected = errors.New("computer use request rejected")

// Precondition rejections: Request refused the action before anything reached
// the desktop, so no OS events were generated. They wrap ErrRejected so
// existing callers still match, while the tool can give the agent the exact
// next step instead of a generic "canceled" message.
var (
	// ErrNoTarget: agent-choice session without a selected window; the agent
	// must list_windows and select_window before observing or acting.
	ErrNoTarget = fmt.Errorf("%w: no window selected", ErrRejected)
	// ErrDiscoveryUnavailable: list_windows/select_window in a selected-window
	// session, or with a frameId attached.
	ErrDiscoveryUnavailable = fmt.Errorf("%w: window discovery unavailable", ErrRejected)
	// ErrUnknownTarget: select_window with a targetRef that is not in the
	// latest list_windows result.
	ErrUnknownTarget = fmt.Errorf("%w: unknown target reference", ErrRejected)
	// ErrStaleFrame: input in an agent-choice session whose frameId does not
	// match the latest observation of the current target.
	ErrStaleFrame = fmt.Errorf("%w: stale frame", ErrRejected)
	// ErrOpenURLUnavailable: open_url is application-wide and not permitted in
	// agent-choice sessions.
	ErrOpenURLUnavailable = fmt.Errorf("%w: open_url unavailable in agent-choice sessions", ErrRejected)
	// ErrBusy: another request is still pending on this session.
	ErrBusy = fmt.Errorf("%w: another request is pending", ErrRejected)
)
var targetReference = regexp.MustCompile(`^[a-f0-9]{64}$`)
var identifier = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$`)

// ClaimTimeoutFor returns how long a claimed request of this kind may stay unresolved.
func ClaimTimeoutFor(a Action) time.Duration {
	switch a.Kind {
	case "observe":
		return ObserveClaimTimeout
	case "type":
		return TypeClaimTimeout
	}
	return ClaimTimeout
}

// visibleText reports whether every rune is printable so the supervisor
// approves exactly the text that will be typed: control, format (zero-width
// space, BOM, bidi overrides and isolates), line/paragraph separators,
// private-use, and unassigned code points are rejected. Zero-width joiner and
// non-joiner stay allowed because emoji sequences and several scripts need them.
func visibleText(s string) bool {
	return utf8.ValidString(s) && !strings.ContainsFunc(s, func(r rune) bool {
		return !unicode.IsGraphic(r) && r != '\u200c' && r != '\u200d'
	})
}

type WindowTarget struct {
	Ref         string `json:"ref"`
	Application string `json:"application"`
	Title       string `json:"title"`
}

func (w WindowTarget) Validate() error {
	if !targetReference.MatchString(w.Ref) || w.Application == "" || len(w.Application) > 256 || len(w.Title) > 512 {
		return ErrRejected
	}
	return nil
}

type Action struct {
	TargetRef string `json:"targetRef,omitempty"`
	Kind      string `json:"kind"`
	// X/Y are frame pixels for click, move, drag start, and optional scroll position.
	X *float64 `json:"x,omitempty"`
	Y *float64 `json:"y,omitempty"`
	// ToX/ToY are the drag destination in frame pixels.
	ToX    *float64 `json:"toX,omitempty"`
	ToY    *float64 `json:"toY,omitempty"`
	DeltaX *float64 `json:"deltaX,omitempty"`
	DeltaY *float64 `json:"deltaY,omitempty"`
	// Button is left (default), right, or middle; Count is 1 (default), 2, or 3.
	Button string `json:"button,omitempty"`
	Count  *int   `json:"count,omitempty"`
	// Seconds is the agent-side wait before a fresh observation; never sent to the desktop.
	Seconds *int   `json:"seconds,omitempty"`
	Key     string `json:"key,omitempty"`
	Text    string `json:"text,omitempty"`
	// URL is an absolute http(s) address for open_url, loaded by the approved
	// browser in the background.
	URL      string `json:"url,omitempty"`
	Question string `json:"question,omitempty"`
}

// NeedsFrame reports whether the action targets coordinates or focus from a
// prior observation and therefore requires its frameId.
func (a Action) NeedsFrame() bool {
	switch a.Kind {
	case "observe", "wait", "open_url", "list_windows", "select_window":
		return false
	}
	return true
}

// WebURL accepts absolute http(s) URLs with a host and without credentials.
func WebURL(raw string) (*url.URL, error) {
	if raw == "" || len(raw) > 2048 || strings.ContainsFunc(raw, func(r rune) bool { return unicode.IsControl(r) || unicode.IsSpace(r) }) {
		return nil, ErrRejected
	}
	u, err := url.Parse(raw)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Hostname() == "" || u.User != nil {
		return nil, ErrRejected
	}
	return u, nil
}

// IsInput reports whether the action delivers OS events to the approved window.
func (a Action) IsInput() bool {
	switch a.Kind {
	case "observe", "wait", "list_windows", "select_window":
		return false
	}
	return true
}

// Hotkey is a parsed key action: a base key plus modifier set.
type Hotkey struct {
	Control, Option, Shift, Cmd bool
	Key                         string
}

// Modifiers returns the canonical modifier prefix, e.g. "Control+Option+Shift+Cmd+".
func (h Hotkey) String() string {
	var b strings.Builder
	for _, m := range []struct {
		on   bool
		name string
	}{{h.Control, "Control"}, {h.Option, "Option"}, {h.Shift, "Shift"}, {h.Cmd, "Cmd"}} {
		if m.on {
			b.WriteString(m.name)
			b.WriteByte('+')
		}
	}
	b.WriteString(h.Key)
	return b.String()
}

var namedKeys = map[string]bool{"Enter": true, "Tab": true, "Escape": true, "Backspace": true, "Delete": true, "ArrowUp": true, "ArrowDown": true, "ArrowLeft": true, "ArrowRight": true, "Home": true, "End": true, "PageUp": true, "PageDown": true, "Space": true}

// ParseHotkey accepts "Mod+...+Key" in any modifier order. Base keys are the
// named navigation/editing keys, Space, A-Z, and 0-9. Letters and digits need
// Control, Option, or Cmd so this action cannot become a text input channel
// that bypasses proposed-text review. Combinations that leave the approved
// window or the session (quit, close, hide, minimize, app/space switching,
// Spotlight, screenshots, force quit, the emergency stop, fullscreen, Dock)
// are rejected here and again natively.
func ParseHotkey(key string) (Hotkey, error) {
	var h Hotkey
	if len(key) == 0 || len(key) > 40 {
		return h, ErrRejected
	}
	parts := strings.Split(key, "+")
	for i, part := range parts {
		last := i == len(parts)-1
		switch {
		case !last && part == "Control" || !last && part == "Ctrl":
			if h.Control {
				return h, ErrRejected
			}
			h.Control = true
		case !last && part == "Option" || !last && part == "Alt":
			if h.Option {
				return h, ErrRejected
			}
			h.Option = true
		case !last && part == "Shift":
			if h.Shift {
				return h, ErrRejected
			}
			h.Shift = true
		case !last && part == "Cmd" || !last && part == "Command" || !last && part == "Meta":
			if h.Cmd {
				return h, ErrRejected
			}
			h.Cmd = true
		case last && namedKeys[part]:
			h.Key = part
		case last && len(part) == 1 && (part[0] >= 'A' && part[0] <= 'Z' || part[0] >= 'a' && part[0] <= 'z' || part[0] >= '0' && part[0] <= '9'):
			h.Key = strings.ToUpper(part)
			if !h.Control && !h.Option && !h.Cmd {
				return h, ErrRejected
			}
		default:
			return h, ErrRejected
		}
	}
	if h.denied() {
		return h, ErrRejected
	}
	return h, nil
}

func (h Hotkey) denied() bool {
	arrow := strings.HasPrefix(h.Key, "Arrow")
	switch {
	case h.Cmd && (h.Key == "Q" || h.Key == "W" || h.Key == "H" || h.Key == "M" || h.Key == "Tab" || h.Key == "Space" || h.Key == "Escape"):
		return true
	case h.Cmd && h.Shift && (h.Key == "3" || h.Key == "4" || h.Key == "5" || h.Key == "6"):
		return true
	case h.Cmd && h.Option && h.Key == "D", h.Cmd && h.Control && h.Key == "F":
		return true
	case h.Control && arrow, h.Control && h.Key == "Space":
		return true
	}
	return false
}

type Request struct {
	TargetRevision uint64 `json:"targetRevision,omitempty"`
	RequestID      string `json:"requestId"`
	FrameID        string `json:"frameId,omitempty"`
	Action         Action `json:"action"`
}

type Geometry struct {
	X      float64 `json:"x"`
	Y      float64 `json:"y"`
	Width  float64 `json:"width"`
	Height float64 `json:"height"`
}

type Capture struct {
	FrameID     string   `json:"frameId"`
	DataURL     string   `json:"dataUrl"`
	PixelWidth  int      `json:"pixelWidth"`
	PixelHeight int      `json:"pixelHeight"`
	Geometry    Geometry `json:"geometry"`
}

type Outcome struct {
	TargetRevision uint64         `json:"targetRevision,omitempty"`
	Windows        []WindowTarget `json:"windows,omitempty"`
	Target         *WindowTarget  `json:"target,omitempty"`
	RequestID      string         `json:"requestId"`
	Status         string         `json:"status"`
	Message        string         `json:"message"`
	Capture        *Capture       `json:"capture,omitempty"`
}

// Exchange identity is supplied by the authenticated dashboard, never by the desktop.
type Exchange struct {
	Namespace string   `json:"namespace"`
	Run       string   `json:"run"`
	Owner     string   `json:"owner"`
	SessionID string   `json:"sessionId"`
	Operation string   `json:"operation"`
	RequestID string   `json:"requestId,omitempty"`
	Outcome   *Outcome `json:"outcome,omitempty"`
}

type Response struct {
	Mode            string   `json:"mode,omitempty"`
	Active          bool     `json:"active"`
	Pending         *Request `json:"pending,omitempty"`
	Reason          string   `json:"reason,omitempty"`
	VisionAvailable bool     `json:"visionAvailable"`
}

func Decode(r io.Reader, out any) error {
	b, err := io.ReadAll(io.LimitReader(r, MaxWire+1))
	if err != nil || len(b) > MaxWire {
		return ErrRejected
	}
	d := json.NewDecoder(bytes.NewReader(b))
	d.DisallowUnknownFields()
	if d.Decode(out) != nil || d.Decode(new(any)) != io.EOF {
		return ErrRejected
	}
	return nil
}

func (r Response) Validate() error {
	if r.Mode != "" && r.Mode != "selected_window" && r.Mode != "agent_choice" {
		return ErrRejected
	}
	switch r.Reason {
	case "", "session inactive", "session stopped", "computer use request rejected":
	default:
		return ErrRejected
	}
	if r.Pending != nil {
		p := r.Pending
		if r.Mode != "agent_choice" && (p.TargetRevision != 0 || p.Action.Kind == "list_windows" || p.Action.Kind == "select_window") {
			return ErrRejected
		}
		if !r.Active || p.Action.Kind == "wait" || !identifier.MatchString(p.RequestID) || (p.FrameID != "" && !identifier.MatchString(p.FrameID)) || p.Action.Validate() != nil {
			return ErrRejected
		}
	}
	return nil
}

func (a Action) Validate() error {
	if (a.Kind == "select_window" && !targetReference.MatchString(a.TargetRef)) || (a.Kind != "select_window" && a.TargetRef != "") {
		return ErrRejected
	}
	// Question belongs to observation only; the tool keeps any verification
	// question for its follow-up observation and never sends it with input.
	if len(a.Question) > 2048 || len(a.Key) > 40 || (a.Kind != "type" && a.Text != "") || (a.Kind != "observe" && a.Question != "") {
		return ErrRejected
	}
	for _, n := range []*float64{a.X, a.Y, a.ToX, a.ToY, a.DeltaX, a.DeltaY} {
		if n != nil && (math.IsNaN(*n) || math.IsInf(*n, 0) || math.Abs(*n) > 100000) {
			return ErrRejected
		}
	}
	// Fields that belong to exactly one kind.
	if (a.Kind != "click" && (a.Button != "" || a.Count != nil)) || (a.Kind != "drag" && (a.ToX != nil || a.ToY != nil)) ||
		(a.Kind != "wait" && a.Seconds != nil) || (a.Kind != "key" && a.Key != "") || (a.Kind != "scroll" && (a.DeltaX != nil || a.DeltaY != nil)) ||
		(a.Kind != "open_url" && a.URL != "") {
		return ErrRejected
	}
	point := a.X != nil && a.Y != nil
	if a.X == nil != (a.Y == nil) || a.ToX == nil != (a.ToY == nil) {
		return ErrRejected
	}
	switch a.Kind {
	case "observe", "list_windows", "select_window":
		if point {
			return ErrRejected
		}
	case "wait":
		if point || a.Seconds == nil || *a.Seconds < 1 || *a.Seconds > 10 {
			return ErrRejected
		}
	case "click":
		if !point {
			return ErrRejected
		}
		switch a.Button {
		case "", "left", "right", "middle":
		default:
			return ErrRejected
		}
		if a.Count != nil && (*a.Count < 1 || *a.Count > 3) {
			return ErrRejected
		}
	case "move":
		if !point {
			return ErrRejected
		}
	case "drag":
		if !point || a.ToX == nil || (*a.X == *a.ToX && *a.Y == *a.ToY) {
			return ErrRejected
		}
	case "scroll":
		if a.DeltaX == nil || a.DeltaY == nil {
			return ErrRejected
		}
		if math.Abs(*a.DeltaX) > 1000 || math.Abs(*a.DeltaY) > 1000 || math.Trunc(*a.DeltaX) != *a.DeltaX || math.Trunc(*a.DeltaY) != *a.DeltaY || (*a.DeltaX == 0 && *a.DeltaY == 0) {
			return ErrRejected
		}
	case "key":
		if point {
			return ErrRejected
		}
		if _, err := ParseHotkey(a.Key); err != nil {
			return err
		}
	case "type":
		if point || a.Text == "" || len(a.Text) > 4000 || !visibleText(a.Text) || len(utf16.Encode([]rune(a.Text))) > 1000 {
			return ErrRejected
		}
	case "activate":
		if point {
			return ErrRejected
		}
	case "open_url":
		if point {
			return ErrRejected
		}
		if _, err := WebURL(a.URL); err != nil {
			return err
		}
	default:
		return ErrRejected
	}
	return nil
}

func (e Exchange) Validate() error {
	if !identifier.MatchString(e.Namespace) || !identifier.MatchString(e.Run) || !identifier.MatchString(e.SessionID) || len(e.Owner) == 0 || len(e.Owner) > 256 {
		return ErrRejected
	}
	switch e.Operation {
	case "attach", "attach_agent", "poll", "stop":
		if e.RequestID != "" || e.Outcome != nil {
			return ErrRejected
		}
	case "claim":
		if !identifier.MatchString(e.RequestID) || e.Outcome != nil {
			return ErrRejected
		}
	case "resolve":
		if !identifier.MatchString(e.RequestID) || e.Outcome == nil || e.Outcome.RequestID != e.RequestID {
			return ErrRejected
		}
		if err := e.Outcome.Validate(); err != nil {
			return err
		}
	default:
		return ErrRejected
	}
	return nil
}

func (o Outcome) Validate() error {
	if len(o.Windows) > 32 || (o.Status != "completed" && (o.Target != nil || len(o.Windows) != 0)) {
		return ErrRejected
	}
	seen := map[string]bool{}
	for _, w := range o.Windows {
		if w.Validate() != nil || seen[w.Ref] {
			return ErrRejected
		}
		seen[w.Ref] = true
	}
	if o.Target != nil && o.Target.Validate() != nil {
		return ErrRejected
	}
	if len(o.Message) > 2048 {
		return ErrRejected
	}
	switch o.Status {
	case "completed", "failed", "denied":
	default:
		return ErrRejected
	}
	if o.Capture != nil {
		if o.Status != "completed" {
			return ErrRejected
		}
		_, err := o.Capture.PNG()
		return err
	}
	return nil
}

func (c Capture) PNG() ([]byte, error) {
	const prefix = "data:image/png;base64,"
	if !identifier.MatchString(c.FrameID) || !strings.HasPrefix(c.DataURL, prefix) || len(c.DataURL) > len(prefix)+base64.StdEncoding.EncodedLen(MaxScreenshot) {
		return nil, ErrRejected
	}
	g := c.Geometry
	for _, n := range []float64{g.X, g.Y, g.Width, g.Height} {
		if math.IsNaN(n) || math.IsInf(n, 0) || math.Abs(n) > 100000 {
			return nil, ErrRejected
		}
	}
	if g.Width <= 0 || g.Height <= 0 {
		return nil, ErrRejected
	}
	b, err := base64.StdEncoding.Strict().DecodeString(strings.TrimPrefix(c.DataURL, prefix))
	if err != nil || len(b) > MaxScreenshot {
		return nil, ErrRejected
	}
	config, err := png.DecodeConfig(bytes.NewReader(b))
	if err != nil || config.Width != c.PixelWidth || config.Height != c.PixelHeight || config.Width > 16384 || config.Height > 16384 || int64(config.Width)*int64(config.Height) > 64<<20 {
		return nil, ErrRejected
	}
	return b, nil
}

package computeruse

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"net"
	"os"
	"path/filepath"
	"syscall"
	"time"
)

func SocketPath(uid string) (string, error) {
	if uid == "" || len(uid) > 256 {
		return "", ErrRejected
	}
	hash := sha256.Sum256([]byte(uid))
	return filepath.Join("/tmp", "gratefulagents-desktop-"+hex.EncodeToString(hash[:16]), "relay.sock"), nil
}

func Listen(ctx context.Context, b *Broker, uid string) (io.Closer, error) {
	path, err := SocketPath(uid)
	if err != nil {
		return nil, err
	}
	dir := filepath.Dir(path)
	if err := os.Mkdir(dir, 0700); err != nil && !os.IsExist(err) {
		return nil, ErrRejected
	}
	info, err := os.Lstat(dir)
	if err != nil || !info.IsDir() || info.Mode().Perm() != 0700 {
		return nil, ErrRejected
	}
	if info, err := os.Lstat(path); err == nil {
		if info.Mode()&os.ModeSocket == 0 {
			return nil, ErrRejected
		}
		conn, dialErr := net.DialTimeout("unix", path, 100*time.Millisecond)
		if dialErr == nil {
			conn.Close()
			return nil, ErrRejected
		}
		if !errors.Is(dialErr, syscall.ECONNREFUSED) {
			return nil, ErrRejected
		}
		if os.Remove(path) != nil {
			return nil, ErrRejected
		}
	}
	l, err := net.ListenUnix("unix", &net.UnixAddr{Name: path, Net: "unix"})
	if err != nil {
		return nil, ErrRejected
	}
	if err := os.Chmod(path, 0600); err != nil {
		l.Close()
		return nil, ErrRejected
	}
	go func() {
		select {
		case <-ctx.Done():
			l.Close()
			b.Close()
		case <-b.done:
			l.Close()
		}
	}()
	go func() {
		slots := make(chan struct{}, 4)
		for {
			c, err := l.AcceptUnix()
			if err != nil {
				return
			}
			select {
			case slots <- struct{}{}:
			default:
				c.Close()
				continue
			}
			go func() {
				defer func() { c.Close(); <-slots }()
				_ = c.SetDeadline(time.Now().Add(3 * time.Second))
				var exchange Exchange
				response := Response{Reason: "computer use request rejected"}
				if Decode(c, &exchange) == nil {
					if result, err := b.Exchange(exchange); err == nil {
						response = result
					}
				}
				_ = json.NewEncoder(c).Encode(response)
			}()
		}
	}()
	return l, nil
}

func Bridge(ctx context.Context, uid string, stdin io.Reader, stdout io.Writer) error {
	var exchange Exchange
	if Decode(stdin, &exchange) != nil || exchange.Validate() != nil {
		return ErrRejected
	}
	input, err := json.Marshal(exchange)
	if err != nil || len(input) > MaxWire {
		return ErrRejected
	}
	path, err := SocketPath(uid)
	if err != nil {
		return err
	}
	conn, err := (&net.Dialer{}).DialContext(ctx, "unix", path)
	if err != nil {
		return ErrRejected
	}
	defer conn.Close()
	deadline := time.Now().Add(3 * time.Second)
	if d, ok := ctx.Deadline(); ok && d.Before(deadline) {
		deadline = d
	}
	_ = conn.SetDeadline(deadline)
	stop := context.AfterFunc(ctx, func() { conn.Close() })
	defer stop()
	if _, err := conn.Write(input); err != nil {
		return ErrRejected
	}
	if err := conn.(*net.UnixConn).CloseWrite(); err != nil {
		return ErrRejected
	}
	var response Response
	if Decode(conn, &response) != nil || response.Validate() != nil {
		return ErrRejected
	}
	output, err := json.Marshal(response)
	if err != nil || len(output) > MaxWire {
		return ErrRejected
	}
	if _, err := stdout.Write(output); err != nil {
		return ErrRejected
	}
	return nil
}

