	"github.com/gratefulagents/gratefulagents/internal/store"
)

// bugReportFixActor attributes automated status transitions made by this
// controller on agent bug reports.
const bugReportFixActor = "bug-squasher"

// BugReportFixReconciler tracks auto-fix AgentRuns launched for agent bug
// reports (runs labeled with platformv1alpha1.BugReportIDLabel). It records
// the fix pull request on the report as soon as the run opens one, resolves
// the report once every fix PR reached a terminal state with at least one
// merge (observed through the run's PullRequestMonitors), and reopens the
// report when the fix attempt ends without a mergeable result — including
// when the fix run itself is deleted mid-flight.
type BugReportFixReconciler struct {
	client.Client
	Scheme *runtime.Scheme
	// Reports is the durable agent bug report store (Postgres-backed).
	Reports store.AgentBugReportStore
}

// +kubebuilder:rbac:groups=platform.gratefulagents.dev,resources=agentruns,verbs=get;list;watch
// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=pullrequestmonitors,verbs=get;list;watch

func (r *BugReportFixReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
	log := logf.FromContext(ctx)
	reports := r.Reports
	if reports == nil {
		return ctrl.Result{}, nil
	}

	run := &platformv1alpha1.AgentRun{}
	if err := r.Get(ctx, req.NamespacedName, run); err != nil {
		if apierrors.IsNotFound(err) {
			// A deleted fix run also garbage-collects its owned
			// PullRequestMonitors, so nothing is tracking or executing the
			// fix anymore: reopen the report instead of leaving it stuck in
			// in_progress.
			return ctrl.Result{}, r.reopenAfterFixRunDeleted(ctx, req.Namespace, req.Name)
		}
		return ctrl.Result{}, err
	}
	rawID := run.Labels[platformv1alpha1.BugReportIDLabel]
	if rawID == "" {
		return ctrl.Result{}, nil
	}
	reportID, err := uuid.Parse(rawID)
	if err != nil {
		log.Info("ignoring AgentRun with invalid bug-report-id label", "run", run.Name, "value", rawID)
		return ctrl.Result{}, nil
	}
	rec, err := reports.GetAgentBugReport(ctx, run.Namespace, reportID)
	if err != nil {
		return ctrl.Result{}, fmt.Errorf("getting bug report %s: %w", reportID, err)
	}
	// Only the report's current fix run drives its lifecycle; superseded runs
	// (a human re-triggered the fix) are ignored.
	if rec == nil || rec.FixRunName != run.Name {
		return ctrl.Result{}, nil
	}

	prs := artifactPullRequests(run)
	outcome, err := r.assessFixPullRequests(ctx, run, prs)
	if err != nil {
		return ctrl.Result{}, err
	}

	// Keep the recorded fix PR fresh: a merged PR wins, otherwise the run's
	// most recently opened PR (a later PR may replace an earlier abandoned
	// one).
	if want := recordablePRURL(run, prs, outcome.mergedURLs); want != "" && want != rec.FixPRURL {
		if err := reports.SetAgentBugReportFix(ctx, run.Namespace, reportID, store.AgentBugReportFixUpdate{
			FixPRURL: &want,
		}); err != nil {
			return ctrl.Result{}, fmt.Errorf("recording fix PR on bug report %s: %w", reportID, err)
		}
		rec.FixPRURL = want
		log.Info("recorded bug report fix PR", "report", reportID, "run", run.Name, "pr", want)
	}

	// Reports the fix already finished with (or a human re-triaged) need no
	// further lifecycle transitions.
	if rec.Status != store.AgentBugReportStatusInProgress {
		return ctrl.Result{}, nil
	}

	if len(prs) > 0 {
		switch {
		case outcome.pending:
			// At least one fix PR is still open or not yet observed: wait.
			return ctrl.Result{}, nil
		case len(outcome.mergedURLs) > 0:
			note := "auto-fixed by " + strings.Join(outcome.mergedURLs, ", ") + " (merged)"
			if !outcome.mergedAt.IsZero() {
				note = fmt.Sprintf("auto-fixed by %s (merged %s)", strings.Join(outcome.mergedURLs, ", "), outcome.mergedAt.UTC().Format("2006-01-02 15:04 UTC"))
			}
			if err := reports.SetAgentBugReportFix(ctx, run.Namespace, reportID, store.AgentBugReportFixUpdate{
				Status:      store.AgentBugReportStatusResolved,
				StatusActor: bugReportFixActor,
				StatusNote:  note,
			}); err != nil {
				return ctrl.Result{}, fmt.Errorf("resolving bug report %s: %w", reportID, err)
			}
			log.Info("resolved bug report after fix PR merge", "report", reportID, "prs", outcome.mergedURLs)
		default:
			// Every fix PR closed without merging.
			if err := reports.SetAgentBugReportFix(ctx, run.Namespace, reportID, store.AgentBugReportFixUpdate{
				Status:      store.AgentBugReportStatusOpen,
				StatusActor: bugReportFixActor,
				StatusNote:  fmt.Sprintf("fix run %s's pull requests were closed without merging", run.Name),
			}); err != nil {
				return ctrl.Result{}, fmt.Errorf("reopening bug report %s: %w", reportID, err)
			}
			log.Info("reopened bug report after fix PRs closed unmerged", "report", reportID, "run", run.Name)
		}
		return ctrl.Result{}, nil
	}

	// No PR: reopen the report once the fix run reaches a terminal phase, so
	// it never sticks in in_progress with nothing working on it.
	if isCronRunTerminal(run.Status.Phase) {
		note := fmt.Sprintf("auto-fix run %s finished without opening a pull request", run.Name)
		if run.Status.Phase != platformv1alpha1.AgentRunPhaseSucceeded {
			note = fmt.Sprintf("auto-fix run %s ended with phase %s without opening a pull request", run.Name, run.Status.Phase)
			if run.Status.LastError != "" {
				note += ": " + run.Status.LastError
			}
		}
		if err := reports.SetAgentBugReportFix(ctx, run.Namespace, reportID, store.AgentBugReportFixUpdate{
			Status:      store.AgentBugReportStatusOpen,
			StatusActor: bugReportFixActor,
			StatusNote:  note,
		}); err != nil {
			return ctrl.Result{}, fmt.Errorf("reopening bug report %s: %w", reportID, err)
		}
		log.Info("reopened bug report after fix run ended without a PR", "report", reportID, "run", run.Name, "phase", run.Status.Phase)
	}
	return ctrl.Result{}, nil
}

// fixPullRequestOutcome aggregates the lifecycle of every fix PR the run
// opened. pending is true while any PR is still open, drafted, or not yet
// observed by its monitor.
type fixPullRequestOutcome struct {
	mergedURLs []string
	mergedAt   metav1.Time
	pending    bool
}

// assessFixPullRequests inspects the PullRequestMonitor of every PR the run
// recorded. Monitors are keyed deterministically by (run UID, PR URL), the
// same scheme the artifact reconciler uses to create them.
func (r *BugReportFixReconciler) assessFixPullRequests(ctx context.Context, run *platformv1alpha1.AgentRun, prs []artifactPullRequest) (fixPullRequestOutcome, error) {
	var out fixPullRequestOutcome
	for _, pr := range prs {
		monitor := &triggersv1alpha1.PullRequestMonitor{}
		key := client.ObjectKey{Namespace: run.Namespace, Name: pullRequestMonitorName(run.UID, pr.URL)}
		if err := r.Get(ctx, key, monitor); err != nil {
			if apierrors.IsNotFound(err) {
				// The artifact reconciler has not created (or GitHub has not
				// been polled for) this monitor yet.
				out.pending = true
				continue
			}
			return out, err
		}
		switch monitor.Status.Lifecycle {
		case triggersv1alpha1.PullRequestLifecycleMerged:
			out.mergedURLs = append(out.mergedURLs, pr.URL)
			if out.mergedAt.IsZero() || monitor.Status.MergedAt.Before(&out.mergedAt) {
				out.mergedAt = monitor.Status.MergedAt
			}
		case triggersv1alpha1.PullRequestLifecycleClosed:
			// Terminal without merge.
		default:
			// open, draft, or not yet observed.
			out.pending = true
		}
	}
	return out, nil
}

// recordablePRURL picks the PR URL worth storing on the report: a merged PR
// wins, otherwise the run's most recently opened PR, falling back to the
// first canonical artifact PR.
func recordablePRURL(run *platformv1alpha1.AgentRun, prs []artifactPullRequest, mergedURLs []string) string {
	if len(mergedURLs) > 0 {
		return mergedURLs[0]
	}
	if len(prs) == 0 {
		return ""
	}
	if run.Status.Artifacts != nil {
		if latest, ok := parseArtifactPullRequestURL(run.Status.Artifacts.PullRequestURL); ok {
			return latest.URL
		}
	}
	return prs[0].URL
}

// reopenAfterFixRunDeleted reopens the in_progress report whose current fix
// run was deleted before finishing.
func (r *BugReportFixReconciler) reopenAfterFixRunDeleted(ctx context.Context, namespace, runName string) error {
	rec, err := r.Reports.GetAgentBugReportByFixRun(ctx, namespace, runName)
	if err != nil {
		return fmt.Errorf("looking up bug report for deleted fix run %s/%s: %w", namespace, runName, err)
	}
	if rec == nil || rec.Status != store.AgentBugReportStatusInProgress {
		return nil
	}
	if err := r.Reports.SetAgentBugReportFix(ctx, namespace, rec.ID, store.AgentBugReportFixUpdate{
		Status:      store.AgentBugReportStatusOpen,
		StatusActor: bugReportFixActor,
		StatusNote:  fmt.Sprintf("auto-fix run %s was deleted before finishing", runName),
	}); err != nil {
		return fmt.Errorf("reopening bug report %s after fix run deletion: %w", rec.ID, err)
	}
	logf.FromContext(ctx).Info("reopened bug report after fix run deletion", "report", rec.ID, "run", runName)
	return nil
}

// mapMonitorToImplementerRun requeues the implementer AgentRun whenever one of
// its pull-request monitors changes, so merge/close transitions propagate to
// the linked bug report promptly.
func mapMonitorToImplementerRun(_ context.Context, obj client.Object) []reconcile.Request {
	monitor, ok := obj.(*triggersv1alpha1.PullRequestMonitor)
	if !ok || monitor.Spec.ImplementerRef.Name == "" {
		return nil
	}
	return []reconcile.Request{{
		NamespacedName: client.ObjectKey{Namespace: monitor.Namespace, Name: monitor.Spec.ImplementerRef.Name},
	}}
}

// bugReportRunPredicate keeps this controller quiet for the overwhelming
// majority of AgentRuns, which carry no bug-report linkage. Delete events pass
// so a removed fix run reopens its report.
func bugReportRunPredicate() predicate.Predicate {
	return predicate.NewPredicateFuncs(func(obj client.Object) bool {
		return obj.GetLabels()[platformv1alpha1.BugReportIDLabel] != ""
	})
}

func (r *BugReportFixReconciler) SetupWithManager(mgr ctrl.Manager) error {
	return ctrl.NewControllerManagedBy(mgr).
		For(&platformv1alpha1.AgentRun{}, builder.WithPredicates(bugReportRunPredicate())).
		Watches(&triggersv1alpha1.PullRequestMonitor{}, handler.EnqueueRequestsFromMapFunc(mapMonitorToImplementerRun)).
		Named("bug-report-fix").
		Complete(r)
}

package triggers

import (
	"context"
	"crypto/sha1"
	"encoding/hex"
	"fmt"
	"regexp"
	"strings"
	"time"

	"github.com/robfig/cron/v3"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
	"github.com/gratefulagents/gratefulagents/internal/store"
	corev1 "k8s.io/api/core/v1"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	"k8s.io/apimachinery/pkg/api/meta"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	ctrl "sigs.k8s.io/controller-runtime"
	"sigs.k8s.io/controller-runtime/pkg/client"
	"sigs.k8s.io/controller-runtime/pkg/controller"
	logf "sigs.k8s.io/controller-runtime/pkg/log"
)

const (
	defaultCronTimeZone = "UTC"
	cronKind            = "Cron"
)

var cronNonAlphaNum = regexp.MustCompile(`[^a-z0-9-]`)

type CronReconciler struct {
	client.Client
	Scheme     *runtime.Scheme
	StateStore store.StateStore
	Now        func() time.Time
}

// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=crons,verbs=get;list;watch;update;patch
// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=crons/status,verbs=get;update;patch
// +kubebuilder:rbac:groups=platform.gratefulagents.dev,resources=agentruns,verbs=get;list;watch;create;update;patch
// +kubebuilder:rbac:groups="",resources=configmaps,verbs=get;list;watch;create;update;patch
// +kubebuilder:rbac:groups="",resources=secrets,verbs=get;list;watch

func (r *CronReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
	log := logf.FromContext(ctx)

	cr := &triggersv1alpha1.Cron{}
	if err := r.Get(ctx, req.NamespacedName, cr); err != nil {
		return ctrl.Result{}, client.IgnoreNotFound(err)
	}

	if cr.Spec.Suspend {
		if err := retryCronStatusUpdate(ctx, r.Client, client.ObjectKeyFromObject(cr), func(fresh *triggersv1alpha1.Cron) {
			fresh.Status.NextScheduleTime = nil
			fresh.Status.LastError = ""
			setCronCondition(fresh, metav1.ConditionFalse, "Suspended", "Cron trigger is suspended")
		}); err != nil && !apierrors.IsNotFound(err) {
			return ctrl.Result{}, fmt.Errorf("updating Cron status: %w", err)
		}
		return ctrl.Result{}, nil
	}

	schedule, observedTimeZone, err := parseCronSchedule(cr.Spec.Schedule, cr.Spec.TimeZone)
	observedSchedule := strings.TrimSpace(cr.Spec.Schedule)
	if err != nil {
		if statusErr := retryCronStatusUpdate(ctx, r.Client, client.ObjectKeyFromObject(cr), func(fresh *triggersv1alpha1.Cron) {
			fresh.Status.LastError = err.Error()
			setCronCondition(fresh, metav1.ConditionFalse, "InvalidSchedule", err.Error())
		}); statusErr != nil && !apierrors.IsNotFound(statusErr) {
			return ctrl.Result{}, fmt.Errorf("updating Cron status: %w", statusErr)
		}
		return ctrl.Result{RequeueAfter: time.Minute}, nil
	}

	now := r.now()
	scheduledTime := nextCronScheduleTime(cr, schedule, observedSchedule, observedTimeZone, now)
	if scheduledTime.IsZero() {
		err := fmt.Errorf("failed to compute next schedule time")
		if statusErr := retryCronStatusUpdate(ctx, r.Client, client.ObjectKeyFromObject(cr), func(fresh *triggersv1alpha1.Cron) {
			fresh.Status.LastError = err.Error()
			setCronCondition(fresh, metav1.ConditionFalse, "ScheduleError", err.Error())
		}); statusErr != nil && !apierrors.IsNotFound(statusErr) {
			return ctrl.Result{}, fmt.Errorf("updating Cron status: %w", statusErr)
		}
		return ctrl.Result{RequeueAfter: time.Minute}, nil
	}

	if scheduledTime.After(now) {
		next := metav1.NewTime(scheduledTime)
		if err := retryCronStatusUpdate(ctx, r.Client, client.ObjectKeyFromObject(cr), func(fresh *triggersv1alpha1.Cron) {
			fresh.Status.NextScheduleTime = &next
			fresh.Status.ObservedSchedule = observedSchedule
			fresh.Status.ObservedTimeZone = observedTimeZone
			fresh.Status.LastError = ""
			setCronCondition(fresh, metav1.ConditionTrue, "Scheduled", "Cron schedule is valid")
		}); err != nil && !apierrors.IsNotFound(err) {
			return ctrl.Result{}, fmt.Errorf("updating Cron status: %w", err)
		}
		return ctrl.Result{RequeueAfter: requeueAfter(scheduledTime.Sub(now))}, nil
	}

	if cr.Spec.ConcurrencyPolicy == "" || cr.Spec.ConcurrencyPolicy == triggersv1alpha1.CronConcurrencyForbid {
		activeRun, err := r.activeCronRun(ctx, cr, scheduledTime)
		if err != nil {
			return ctrl.Result{}, err
		}
		if activeRun != nil {
			nextScheduledTime := schedule.Next(now)
			last := metav1.NewTime(scheduledTime)
			next := metav1.NewTime(nextScheduledTime)
			msg := fmt.Sprintf("skipped tick %s: previous run %s still active", scheduledTime.UTC().Format(time.RFC3339), activeRun.Name)
			log.Info("skipping scheduled AgentRun because previous cron run is still active", "scheduledTime", scheduledTime, "activeRun", activeRun.Name)
			if err := retryCronStatusUpdate(ctx, r.Client, client.ObjectKeyFromObject(cr), func(fresh *triggersv1alpha1.Cron) {
				fresh.Status.LastScheduleTime = &last
				fresh.Status.NextScheduleTime = &next
				fresh.Status.ObservedSchedule = observedSchedule
				fresh.Status.ObservedTimeZone = observedTimeZone
				fresh.Status.LastError = msg
				setCronCondition(fresh, metav1.ConditionFalse, "ConcurrencyBlocked", msg)
			}); err != nil && !apierrors.IsNotFound(err) {
				return ctrl.Result{}, fmt.Errorf("updating Cron status: %w", err)
			}
			return ctrl.Result{RequeueAfter: requeueAfter(nextScheduledTime.Sub(now))}, nil
		}
	}

	created, runName, err := r.createAgentRun(ctx, cr, scheduledTime)
	if err != nil {
		log.Error(err, "failed to create scheduled AgentRun", "scheduledTime", scheduledTime)
		if statusErr := retryCronStatusUpdate(ctx, r.Client, client.ObjectKeyFromObject(cr), func(fresh *triggersv1alpha1.Cron) {
			fresh.Status.LastError = err.Error()
			setCronCondition(fresh, metav1.ConditionFalse, "CreateRunFailed", err.Error())
		}); statusErr != nil && !apierrors.IsNotFound(statusErr) {
			return ctrl.Result{}, fmt.Errorf("updating Cron status: %w", statusErr)
		}
		return ctrl.Result{RequeueAfter: time.Minute}, nil
	}

	nextScheduledTime := schedule.Next(now)
	last := metav1.NewTime(scheduledTime)
	next := metav1.NewTime(nextScheduledTime)
	if err := retryCronStatusUpdate(ctx, r.Client, client.ObjectKeyFromObject(cr), func(fresh *triggersv1alpha1.Cron) {
		fresh.Status.LastScheduleTime = &last
		fresh.Status.NextScheduleTime = &next
		fresh.Status.LastRunName = runName
		fresh.Status.ObservedSchedule = observedSchedule
		fresh.Status.ObservedTimeZone = observedTimeZone
		fresh.Status.LastError = ""
		if created {
			fresh.Status.RunsCreated++
		}
		setCronCondition(fresh, metav1.ConditionTrue, "Scheduled", "Cron schedule is valid")
	}); err != nil && !apierrors.IsNotFound(err) {
		return ctrl.Result{}, fmt.Errorf("updating Cron status: %w", err)
	}

	return ctrl.Result{RequeueAfter: requeueAfter(nextScheduledTime.Sub(now))}, nil
}

func (r *CronReconciler) now() time.Time {
	if r.Now != nil {
		return r.Now().UTC()
	}
	return time.Now().UTC()
}

func parseCronSchedule(expr, timeZone string) (cron.Schedule, string, error) {
	trimmed := strings.TrimSpace(expr)
	if trimmed == "" {
		return nil, "", fmt.Errorf("spec.schedule is required")
	}
	upper := strings.ToUpper(trimmed)
	if strings.HasPrefix(upper, "TZ=") || strings.HasPrefix(upper, "CRON_TZ=") {
		return nil, "", fmt.Errorf("inline cron time zones are not supported; use spec.timeZone")
	}

	zone := strings.TrimSpace(timeZone)
	if zone == "" {
		zone = defaultCronTimeZone
	}
	if _, err := time.LoadLocation(zone); err != nil {
		return nil, "", fmt.Errorf("invalid spec.timeZone %q: %w", zone, err)
	}

	parser := cron.NewParser(cron.Minute | cron.Hour | cron.Dom | cron.Month | cron.Dow | cron.Descriptor)
	schedule, err := parser.Parse("CRON_TZ=" + zone + " " + trimmed)
	if err != nil {
		return nil, "", fmt.Errorf("invalid spec.schedule %q: %w", trimmed, err)
	}
	return schedule, zone, nil
}

// nextCronScheduleTime returns the schedule instant to process next. If a due
// instant is later skipped, such as by a Forbid concurrency policy, the
// reconciler records it as processed and advances to a future schedule; skipped
// ticks are not backfilled.
func nextCronScheduleTime(cr *triggersv1alpha1.Cron, schedule cron.Schedule, observedSchedule, observedTimeZone string, now time.Time) time.Time {
	if cr.Status.ObservedSchedule != observedSchedule || cr.Status.ObservedTimeZone != observedTimeZone {
		return schedule.Next(now)
	}
	if cr.Status.NextScheduleTime != nil && !cr.Status.NextScheduleTime.IsZero() {
		return cr.Status.NextScheduleTime.Time
	}
	if cr.Status.LastScheduleTime != nil && !cr.Status.LastScheduleTime.IsZero() {
		return schedule.Next(cr.Status.LastScheduleTime.Time)
	}
	return schedule.Next(now)
}

func requeueAfter(d time.Duration) time.Duration {
	if d <= 0 {
		return time.Second
	}
	return d
}

func (r *CronReconciler) activeCronRun(ctx context.Context, cr *triggersv1alpha1.Cron, scheduledTime time.Time) (*platformv1alpha1.AgentRun, error) {
	runs := &platformv1alpha1.AgentRunList{}
	if err := r.List(ctx, runs, client.InNamespace(cr.Namespace)); err != nil {
		return nil, fmt.Errorf("listing AgentRuns: %w", err)
	}
	scheduledID := scheduledTime.UTC().Format(time.RFC3339)
	for i := range runs.Items {
		run := &runs.Items[i]
		if !TriggerRunMatches(run, cronKind, cr.Name) {
			continue
		}
		if run.Spec.Trigger.ExternalRef != nil && strings.TrimSpace(run.Spec.Trigger.ExternalRef.ID) == scheduledID {
			continue
		}
		if !isCronRunTerminal(run.Status.Phase) {
			return run, nil
		}
	}
	return nil, nil
}

func isCronRunTerminal(phase platformv1alpha1.AgentRunPhase) bool {
	switch phase {
	case platformv1alpha1.AgentRunPhaseSucceeded, platformv1alpha1.AgentRunPhaseFailed, platformv1alpha1.AgentRunPhaseCancelled:
		return true
	default:
		return false
	}
}

func (r *CronReconciler) createAgentRun(ctx context.Context, cr *triggersv1alpha1.Cron, scheduledTime time.Time) (bool, string, error) {
	runName := cronRunName(cr.Name, scheduledTime)
	d := cr.Spec.Defaults
	provider := triggersv1alpha1.NormalizeProvider(d.Provider)
	if err := validateTriggerRunDefaults(TriggerRunSpec{
		Namespace:   cr.Namespace,
		TriggerKind: cronKind,
		TriggerName: cr.Name,
		Defaults:    d,
	}); err != nil {
		return false, runName, err
	}

	scheduledID := scheduledTime.UTC().Format(time.RFC3339)
	annotations := map[string]string{
		runModeAnnotation: "auto",
		"platform.gratefulagents.dev/scheduled-time": scheduledID,
	}
	if strings.TrimSpace(d.CustomInstructions) != "" {
		instructionsName := runName + "-instructions"
		instructions := &corev1.ConfigMap{ObjectMeta: metav1.ObjectMeta{Name: instructionsName, Namespace: cr.Namespace}, Data: map[string]string{"instructions.md": d.CustomInstructions}}
		if err := ctrl.SetControllerReference(cr, instructions, r.Scheme); err != nil {
			return false, runName, fmt.Errorf("setting owner reference on instructions ConfigMap: %w", err)
		}
		if err := r.Create(ctx, instructions); err != nil && !apierrors.IsAlreadyExists(err) {
			return false, runName, fmt.Errorf("creating instructions ConfigMap: %w", err)
		}
		annotations["platform.gratefulagents.dev/instructions-configmap-ref"] = instructionsName
	}
	if triggersv1alpha1.IsOpenAICompatibleProvider(provider) {
		annotations["platform.gratefulagents.dev/openai-api-mode"] = triggersv1alpha1.NormalizeOpenAIAPIForProvider(provider, d.OpenAIAPI)
	}

	runContext := &platformv1alpha1.AgentRunContext{
		ProjectRef: &platformv1alpha1.ProjectRef{Kind: cronKind, Name: cr.Name},
	}
	created, _, err := CreateTriggerRun(ctx, r.Client, r.StateStore, TriggerRunSpec{
		RunName:            runName,
		Namespace:          cr.Namespace,
		TriggerKind:        cronKind,
		TriggerName:        cr.Name,
		ExternalID:         scheduledID,
		ExternalIdentifier: scheduledTime.Format(time.RFC3339),
		SeedMessage:        cr.Spec.Prompt,
		Defaults:           d,
		OwnerRef:           cr,
		Scheme:             r.Scheme,
		Annotations:        annotations,
		Context:            runContext,
		SeedLogPrefix:      "cron",
	})
	if err != nil {
		return false, runName, err
	}
	return created, runName, nil
}

func cronRunName(sourceName string, scheduledTime time.Time) string {
	suffix := scheduledTime.UTC().Format("20060102150405")
	base := cronNonAlphaNum.ReplaceAllString(strings.ToLower(sourceName), "-")
	base = strings.Trim(base, "-")
	if base == "" {
		base = "run"
	}
	name := "cron-" + base + "-" + suffix
	if len(name) <= 63 {
		return name
	}
	hashBytes := sha1.Sum([]byte(name))
	hash := hex.EncodeToString(hashBytes[:])[:8]
	maxBase := 63 - len("cron-") - len("-") - len(suffix) - len("-") - len(hash)
	if maxBase < 1 {
		maxBase = 1
	}
	if len(base) > maxBase {
		base = strings.TrimRight(base[:maxBase], "-")
	}
	return "cron-" + base + "-" + suffix + "-" + hash
}

func setCronCondition(cr *triggersv1alpha1.Cron, status metav1.ConditionStatus, reason, message string) {
	meta.SetStatusCondition(&cr.Status.Conditions, metav1.Condition{
		Type:               triggersv1alpha1.ConditionCronReady,
		Status:             status,
		ObservedGeneration: cr.Generation,
		Reason:             reason,
		Message:            message,
	})
}

func (r *CronReconciler) SetupWithManager(mgr ctrl.Manager) error {
	return ctrl.NewControllerManagedBy(mgr).
		For(&triggersv1alpha1.Cron{}).
		Owns(&platformv1alpha1.AgentRun{}).
		Named("cron").
		WithOptions(controller.Options{MaxConcurrentReconciles: 1}).
		Complete(r)
}

