const (
	gitHubPollPageLimit = 10
	gitHubRollupSuccess = "success"
	gitHubRollupFailure = "failure"
	gitHubRollupPending = "pending"
	gitHubRollupNone    = "none"
	gitHubOwnerVariable = "owner"
	gitHubRepoVariable  = "repo"
)

var errGitHubPollHistoryLimit = errors.New("github poll history exceeds page limit")

type gitHubPollHistoryLimitError struct {
	collection string
	pages      int
}

func (e *gitHubPollHistoryLimitError) Error() string {
	return fmt.Sprintf("%s: %s history exceeds %d pages", errGitHubPollHistoryLimit, e.collection, e.pages)
}

func (e *gitHubPollHistoryLimitError) Unwrap() error {
	return errGitHubPollHistoryLimit
}

func (e *gitHubPollHistoryLimitError) Retryable() bool {
	return true
}

type polledPullRequest struct {
	Number         int
	Title          string
	URL            string
	State          string
	Draft          bool
	Merged         bool
	MergedAt       time.Time
	MergeableKnown bool
	Mergeable      bool
	MergeableState string
	HeadRef        string
	HeadSHA        string
	BaseRef        string
	AuthorLogin    string
	CreatedAt      time.Time
	UpdatedAt      time.Time
}

type polledHeadRollup struct {
	HeadSHA string
	State   string
	Count   int
}

type polledPullRequestReview struct {
	ID                int64
	CommitSHA         string
	State             string
	Body              string
	AuthorLogin       string
	AuthorAssociation string
	SubmittedAt       time.Time
}

type polledIssueComment struct {
	ID                int64
	Body              string
	AuthorLogin       string
	AuthorAssociation string
	CreatedAt         time.Time
	UpdatedAt         time.Time
}

type gitHubPollResponse struct {
	StatusCode    int
	ETag          string
	NextPage      int
	LastPage      int
	RateLimit     int
	RateRemaining int
	RateReset     time.Time
	RetryAfter    time.Duration
}

type pullRequestGitHubPoller interface {
	GetPullRequest(context.Context, string, string, int, string) (*polledPullRequest, gitHubPollResponse, error)
	ListReviews(context.Context, string, string, int, time.Time) ([]polledPullRequestReview, gitHubPollResponse, error)
	GetReviewDecision(context.Context, string, string, int, string) (triggersv1alpha1.PullRequestReviewDecision, gitHubPollResponse, error)
	ListIssueComments(context.Context, string, string, int, time.Time) ([]polledIssueComment, gitHubPollResponse, error)
	ListCheckRuns(context.Context, string, string, string) (polledHeadRollup, gitHubPollResponse, error)
	GetCommitStatus(context.Context, string, string, string) (polledHeadRollup, gitHubPollResponse, error)
}

type goGitHubPullRequestPoller struct {
	client *github.Client
}

func newPullRequestGitHubPoller(client *github.Client) pullRequestGitHubPoller {
	return &goGitHubPullRequestPoller{client: client}
}

func (p *goGitHubPullRequestPoller) GetPullRequest(ctx context.Context, owner, repo string, number int, etag string) (*polledPullRequest, gitHubPollResponse, error) {
	path := fmt.Sprintf("repos/%s/%s/pulls/%d", url.PathEscape(owner), url.PathEscape(repo), number)
	req, err := p.client.NewRequest(http.MethodGet, path, nil)
	if err != nil {
		return nil, gitHubPollResponse{}, err
	}
	if etag != "" {
		req.Header.Set("If-None-Match", etag)
	}

	var value github.PullRequest
	resp, err := p.client.Do(ctx, req, &value)
	metadata := pollResponseFromGitHub(resp)
	if metadata.StatusCode == http.StatusNotModified {
		return nil, metadata, nil
	}
	if err != nil {
		return nil, metadata, err
	}

	return &polledPullRequest{
		Number:         value.GetNumber(),
		Title:          value.GetTitle(),
		URL:            value.GetHTMLURL(),
		State:          value.GetState(),
		Draft:          value.GetDraft(),
		Merged:         value.GetMerged(),
		MergedAt:       value.GetMergedAt().Time,
		MergeableKnown: value.Mergeable != nil,
		Mergeable:      value.GetMergeable(),
		MergeableState: value.GetMergeableState(),
		HeadRef:        value.GetHead().GetRef(),
		HeadSHA:        value.GetHead().GetSHA(),
		BaseRef:        value.GetBase().GetRef(),
		AuthorLogin:    value.GetUser().GetLogin(),
		CreatedAt:      value.GetCreatedAt().Time,
		UpdatedAt:      value.GetUpdatedAt().Time,
	}, metadata, nil
}

func (p *goGitHubPullRequestPoller) ListReviews(ctx context.Context, owner, repo string, number int, after time.Time) ([]polledPullRequestReview, gitHubPollResponse, error) {
	owner, repo = url.PathEscape(owner), url.PathEscape(repo)
	first, resp, err := p.client.PullRequests.ListReviews(ctx, owner, repo, number, &github.ListOptions{Page: 1, PerPage: 100})
	metadata := pollResponseFromGitHub(resp)
	metadata.ETag = ""
	if err != nil {
		return nil, metadata, err
	}

	lastPage := metadata.LastPage
	if lastPage < 1 {
		lastPage = 1
	}
	page := lastPage
	requestsRead := 1
	var reviews []polledPullRequestReview
	for page >= 1 {
		var values []*github.PullRequestReview
		if page == 1 {
			values = first
		} else {
			if requestsRead == gitHubPollPageLimit {
				return nil, metadata, &gitHubPollHistoryLimitError{collection: "pull request review", pages: gitHubPollPageLimit}
			}
			values, resp, err = p.client.PullRequests.ListReviews(ctx, owner, repo, number, &github.ListOptions{Page: page, PerPage: 100})
			requestsRead++
			metadata = mergeGitHubPollResponse(metadata, pollResponseFromGitHub(resp))
			metadata.ETag = ""
			if err != nil {
				return nil, metadata, err
			}
		}

		reachedCursor := false
		for _, value := range values {
			if value == nil {
				continue
			}
			submittedAt := value.GetSubmittedAt().Time
			if submittedAt.Before(after) {
				reachedCursor = true
				continue
			}
			if submittedAt.Equal(after) {
				reachedCursor = true
			}
			reviews = append(reviews, polledPullRequestReview{
				ID:                value.GetID(),
				CommitSHA:         value.GetCommitID(),
				State:             value.GetState(),
				Body:              value.GetBody(),
				AuthorLogin:       value.GetUser().GetLogin(),
				AuthorAssociation: value.GetAuthorAssociation(),
				SubmittedAt:       value.GetSubmittedAt().Time,
			})
		}
		if reachedCursor || page == 1 {
			break
		}
		page--
	}

	sort.Slice(reviews, func(i, j int) bool {
		if reviews[i].SubmittedAt.Equal(reviews[j].SubmittedAt) {
			return reviews[i].ID < reviews[j].ID
		}
		return reviews[i].SubmittedAt.Before(reviews[j].SubmittedAt)
	})
	metadata.NextPage = 0
	metadata.ETag = ""
	return reviews, metadata, nil
}

func (p *goGitHubPullRequestPoller) GetReviewDecision(ctx context.Context, owner, repo string, number int, expectedHead string) (triggersv1alpha1.PullRequestReviewDecision, gitHubPollResponse, error) {
	body := map[string]any{
		"query":     `query($owner:String!,$repo:String!,$number:Int!){repository(owner:$owner,name:$repo){pullRequest(number:$number){reviewDecision}}}`,
		"variables": map[string]any{gitHubOwnerVariable: owner, gitHubRepoVariable: repo, "number": number},
	}
	req, err := p.client.NewRequest(http.MethodPost, "graphql", body)
	if err != nil {
		return triggersv1alpha1.PullRequestReviewDecisionUnknown, gitHubPollResponse{}, err
	}
	var result struct {
		Data struct {
			Repository struct {
				PullRequest struct {
					ReviewDecision string `json:"reviewDecision"`
				} `json:"pullRequest"`
			} `json:"repository"`
		} `json:"data"`
		Errors []struct {
			Message string `json:"message"`
		} `json:"errors"`
	}
	resp, err := p.client.Do(ctx, req, &result)
	metadata := pollResponseFromGitHub(resp)
	if err != nil {
		return triggersv1alpha1.PullRequestReviewDecisionUnknown, metadata, err
	}
	if len(result.Errors) > 0 {
		return triggersv1alpha1.PullRequestReviewDecisionUnknown, metadata, fmt.Errorf("GitHub GraphQL review decision: %s", result.Errors[0].Message)
	}
	rawDecision := strings.ToUpper(strings.TrimSpace(result.Data.Repository.PullRequest.ReviewDecision))
	switch rawDecision {
	case "APPROVED":
		return triggersv1alpha1.PullRequestReviewDecisionApproved, metadata, nil
	case "CHANGES_REQUESTED":
		return triggersv1alpha1.PullRequestReviewDecisionChangesRequested, metadata, nil
	case "REVIEW_REQUIRED":
		return triggersv1alpha1.PullRequestReviewDecisionReviewRequired, metadata, nil
	case "":
		// GitHub leaves reviewDecision blank when the base branch does not
		// require reviews. Individual reviews remain available through REST and
		// are the approval source for repositories without branch protection.
		reviews, reviewMetadata, err := p.ListReviews(ctx, owner, repo, number, time.Time{})
		metadata = mergeGitHubPollResponse(metadata, reviewMetadata)
		if err != nil {
			return triggersv1alpha1.PullRequestReviewDecisionUnknown, metadata, err
		}
		return individualReviewDecision(reviews, expectedHead), metadata, nil
	default:
		return triggersv1alpha1.PullRequestReviewDecisionUnknown, metadata, nil
	}
}

// individualReviewDecision approximates GitHub's aggregate decision from REST
// reviews by trusted repository actors. Each reviewer's latest decisive state
// wins; changes requests take precedence, and approvals must bind to the head.
func individualReviewDecision(reviews []polledPullRequestReview, expectedHead string) triggersv1alpha1.PullRequestReviewDecision {
	type decisiveReview struct {
		state     string
		commitSHA string
	}
	latest := make(map[string]decisiveReview)
	for _, review := range reviews {
		author := strings.ToLower(strings.TrimSpace(review.AuthorLogin))
		if !(&triggersv1alpha1.TriggerAuth{}).IsGitHubActorAllowed(author, review.AuthorAssociation) {
			continue
		}
		switch state := strings.ToUpper(strings.TrimSpace(review.State)); state {
		case "APPROVED", "CHANGES_REQUESTED":
			latest[author] = decisiveReview{state: state, commitSHA: strings.TrimSpace(review.CommitSHA)}
		case "DISMISSED":
			delete(latest, author)
		}
	}
	decision := triggersv1alpha1.PullRequestReviewDecisionUnknown
	for _, review := range latest {
		if review.state == "CHANGES_REQUESTED" {
			return triggersv1alpha1.PullRequestReviewDecisionChangesRequested
		}
		if review.state == "APPROVED" && expectedHead != "" && review.commitSHA == expectedHead {
			decision = triggersv1alpha1.PullRequestReviewDecisionApproved
		}
	}
	return decision
}

func (p *goGitHubPullRequestPoller) ListIssueComments(ctx context.Context, owner, repo string, number int, after time.Time) ([]polledIssueComment, gitHubPollResponse, error) {
	owner, repo = url.PathEscape(owner), url.PathEscape(repo)
	since := after.Add(-time.Second)
	opts := &github.IssueListCommentsOptions{
		Since: &since,
		ListOptions: github.ListOptions{
			Page:    1,
			PerPage: 100,
		},
	}

	var comments []polledIssueComment
	var metadata gitHubPollResponse
	for pagesRead := 0; ; pagesRead++ {
		values, resp, err := p.client.Issues.ListComments(ctx, owner, repo, number, opts)
		pageMetadata := pollResponseFromGitHub(resp)
		pageMetadata.ETag = ""
		metadata = mergeGitHubPollResponse(metadata, pageMetadata)
		metadata.ETag = ""
		if err != nil {
			return nil, metadata, err
		}
		for _, value := range values {
			if value == nil || value.GetCreatedAt().Time.Before(after) {
				continue
			}
			comments = append(comments, polledIssueComment{
				ID:                value.GetID(),
				Body:              value.GetBody(),
				AuthorLogin:       value.GetUser().GetLogin(),
				AuthorAssociation: value.GetAuthorAssociation(),
				CreatedAt:         value.GetCreatedAt().Time,
				UpdatedAt:         value.GetUpdatedAt().Time,
			})
		}
		if pageMetadata.NextPage == 0 {
			break
		}
		if pagesRead+1 == gitHubPollPageLimit {
			return nil, metadata, &gitHubPollHistoryLimitError{collection: "issue comment", pages: gitHubPollPageLimit}
		}
		opts.Page = pageMetadata.NextPage
	}

	sort.Slice(comments, func(i, j int) bool {
		if comments[i].CreatedAt.Equal(comments[j].CreatedAt) {
			return comments[i].ID < comments[j].ID
		}
		return comments[i].CreatedAt.Before(comments[j].CreatedAt)
	})
	metadata.NextPage = 0
	metadata.ETag = ""
	return comments, metadata, nil
}

func (p *goGitHubPullRequestPoller) ListCheckRuns(ctx context.Context, owner, repo, headSHA string) (polledHeadRollup, gitHubPollResponse, error) {
	owner, repo = url.PathEscape(owner), url.PathEscape(repo)
	opts := &github.ListCheckRunsOptions{Filter: new("latest"), ListOptions: github.ListOptions{Page: 1, PerPage: 100}}
	rollup := polledHeadRollup{HeadSHA: headSHA, State: gitHubRollupSuccess}
	var metadata gitHubPollResponse
	seen := false
	for pagesRead := 0; ; pagesRead++ {
		values, resp, err := p.client.Checks.ListCheckRunsForRef(ctx, owner, repo, headSHA, opts)
		metadata = mergeGitHubPollResponse(metadata, pollResponseFromGitHub(resp))
		if err != nil {
			return polledHeadRollup{HeadSHA: headSHA}, metadata, err
		}
		if values != nil {
			for _, value := range values.CheckRuns {
				if value == nil {
					continue
				}
				seen = true
				rollup.Count++
				if !strings.EqualFold(value.GetStatus(), "completed") {
					if rollup.State != gitHubRollupFailure {
						rollup.State = gitHubRollupPending
					}
					continue
				}
				switch strings.ToLower(value.GetConclusion()) {
				case gitHubRollupSuccess, "neutral", "skipped":
				case gitHubRollupFailure, "cancelled", "timed_out", "action_required", "startup_failure", "stale":
					rollup.State = gitHubRollupFailure
				default:
					if rollup.State != gitHubRollupFailure {
						rollup.State = gitHubRollupPending
					}
				}
			}
			if resp == nil || resp.NextPage == 0 {
				break
			}
			if pagesRead+1 == gitHubPollPageLimit {
				return polledHeadRollup{HeadSHA: headSHA}, metadata, &gitHubPollHistoryLimitError{collection: "check run", pages: gitHubPollPageLimit}
			}
			opts.Page = resp.NextPage
		} else {
			break
		}
	}
	if !seen {
		rollup.State = gitHubRollupNone
	}
	return rollup, metadata, nil
}

func (p *goGitHubPullRequestPoller) GetCommitStatus(ctx context.Context, owner, repo, headSHA string) (polledHeadRollup, gitHubPollResponse, error) {
	owner, repo = url.PathEscape(owner), url.PathEscape(repo)
	value, resp, err := p.client.Repositories.GetCombinedStatus(ctx, owner, repo, headSHA, &github.ListOptions{PerPage: 100})
	metadata := pollResponseFromGitHub(resp)
	if err != nil {
		return polledHeadRollup{HeadSHA: headSHA}, metadata, err
	}
	count := len(value.Statuses)
	state := value.GetState()
	if count == 0 {
		state = gitHubRollupNone
	}
	return polledHeadRollup{HeadSHA: headSHA, State: state, Count: count}, metadata, nil
}

func pollResponseFromGitHub(resp *github.Response) gitHubPollResponse {
	if resp == nil {
		return gitHubPollResponse{}
	}
	result := gitHubPollResponse{
		NextPage:      resp.NextPage,
		LastPage:      resp.LastPage,
		RateLimit:     resp.Rate.Limit,
		RateRemaining: resp.Rate.Remaining,
		RateReset:     resp.Rate.Reset.Time,
	}
	if resp.Response != nil {
		result.StatusCode = resp.StatusCode
		result.ETag = resp.Header.Get("ETag")
		if seconds, err := strconv.ParseInt(resp.Header.Get("Retry-After"), 10, 64); err == nil {
			result.RetryAfter = time.Duration(seconds) * time.Second
		}
	}
	return result
}

func mergeGitHubPollResponse(current, next gitHubPollResponse) gitHubPollResponse {
	if next.StatusCode != 0 {
		current.StatusCode = next.StatusCode
	}
	if next.ETag != "" {
		current.ETag = next.ETag
	}
	current.NextPage = next.NextPage
	if next.LastPage > current.LastPage {
		current.LastPage = next.LastPage
	}
	if next.RateLimit != 0 {
		current.RateLimit = next.RateLimit
	}
	if next.RateRemaining != 0 || next.RateLimit != 0 {
		current.RateRemaining = next.RateRemaining
	}
	if !next.RateReset.IsZero() {
		current.RateReset = next.RateReset
	}
	if next.RetryAfter > current.RetryAfter {
		current.RetryAfter = next.RetryAfter
	}
	return current
}

package triggers

import (
	"context"
	"fmt"
	"strings"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
	"github.com/gratefulagents/gratefulagents/internal/githubapp"
	corev1 "k8s.io/api/core/v1"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	ctrl "sigs.k8s.io/controller-runtime"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

type gitHubAppTokenMinter interface {
	MintInstallationToken(ctx context.Context, appID, installationID int64, privateKeyPEM []byte) (string, error)
}

func defaultGitHubAppMinter(minter gitHubAppTokenMinter) gitHubAppTokenMinter {
	if minter != nil {
		return minter
	}
	return githubapp.NewKeyedMinter()
}

// mintRunInstallationToken mints the per-run installation token. Reviewer
// runs get a downscoped token (read code, write reviews — never push) when
// the minter supports scoping; this boundary holds even if the agent pod is
// compromised.
func mintRunInstallationToken(ctx context.Context, minter gitHubAppTokenMinter, gh *triggersv1alpha1.GitHubRepository, run *platformv1alpha1.AgentRun, privateKeyPEM []byte) (string, error) {
	m := defaultGitHubAppMinter(minter)
	if run != nil && run.Labels[triggersv1alpha1.PRLoopRoleLabelKey] == triggersv1alpha1.PRLoopRoleReviewerValue {
		scoped, ok := m.(githubapp.ScopedInstallationTokenMinter)
		if !ok {
			return "", fmt.Errorf("GitHub App token minter does not support reviewer-scoped tokens")
		}
		return scoped.MintScopedInstallationToken(ctx, gh.Spec.GitHubApp.AppID, gh.Spec.GitHubApp.InstallationID, privateKeyPEM, githubapp.ReviewerInstallationPermissions())
	}
	return m.MintInstallationToken(ctx, gh.Spec.GitHubApp.AppID, gh.Spec.GitHubApp.InstallationID, privateKeyPEM)
}

func resolveGitHubToken(ctx context.Context, c client.Client, gh *triggersv1alpha1.GitHubRepository, minter gitHubAppTokenMinter) (string, error) {
	if gh == nil {
		return "", fmt.Errorf("GitHubRepository is nil")
	}
	if gh.Spec.GitHubApp != nil {
		privateKeyPEM, err := readGitHubAppPrivateKey(ctx, c, gh)
		if err != nil {
			return "", err
		}
		return defaultGitHubAppMinter(minter).MintInstallationToken(ctx, gh.Spec.GitHubApp.AppID, gh.Spec.GitHubApp.InstallationID, privateKeyPEM)
	}
	secretName := strings.TrimSpace(gh.Spec.GitHubTokenSecret)
	if secretName == "" {
		return "", fmt.Errorf("GitHubRepository %s/%s requires exactly one of spec.githubTokenSecret or spec.githubApp", gh.Namespace, gh.Name)
	}
	return ReadSecretValue(ctx, c, gh.Namespace, secretName, githubapp.TokenSecretKey)
}

// resolveGitHubPollingToken returns the least-privilege credential used by the
// control-plane PR monitor. PAT-backed repositories retain their configured
// token; GitHub App credentials are permission-downscoped to read-only PR and
// issue metadata and are never exposed to an AgentRun.
func resolveGitHubPollingToken(ctx context.Context, c client.Client, gh *triggersv1alpha1.GitHubRepository, minter gitHubAppTokenMinter) (string, error) {
	if gh == nil || gh.Spec.GitHubApp == nil {
		return resolveGitHubToken(ctx, c, gh, minter)
	}
	privateKeyPEM, err := readGitHubAppPrivateKey(ctx, c, gh)
	if err != nil {
		return "", err
	}
	scoped, ok := defaultGitHubAppMinter(minter).(githubapp.ScopedInstallationTokenMinter)
	if !ok {
		return "", fmt.Errorf("GitHub App token minter does not support read-only polling tokens")
	}
	return scoped.MintScopedInstallationToken(ctx, gh.Spec.GitHubApp.AppID, gh.Spec.GitHubApp.InstallationID, privateKeyPEM, githubapp.PullRequestPollingInstallationPermissions())
}

func readGitHubAppPrivateKey(ctx context.Context, c client.Client, gh *triggersv1alpha1.GitHubRepository) ([]byte, error) {
	if gh == nil || gh.Spec.GitHubApp == nil {
		return nil, fmt.Errorf("GitHub App auth is not configured")
	}
	secretName := strings.TrimSpace(gh.Spec.GitHubApp.PrivateKeySecret)
	if secretName == "" {
		return nil, fmt.Errorf("GitHubRepository %s/%s spec.githubApp.privateKeySecret is required", gh.Namespace, gh.Name)
	}
	secret := &corev1.Secret{}
	if err := c.Get(ctx, client.ObjectKey{Namespace: gh.Namespace, Name: secretName}, secret); err != nil {
		return nil, fmt.Errorf("getting GitHub App private key secret %s: %w", secretName, err)
	}
	data, ok := secret.Data[githubapp.PrivateKeySecretKey]
	if !ok || len(data) == 0 {
		return nil, fmt.Errorf("GitHub App private key secret %s has no key %q", secretName, githubapp.PrivateKeySecretKey)
	}
	return data, nil
}

func ensureRunGitHubAppTokenSecret(ctx context.Context, c client.Client, scheme *runtime.Scheme, gh *triggersv1alpha1.GitHubRepository, run *platformv1alpha1.AgentRun, minter gitHubAppTokenMinter) error {
	if gh == nil || gh.Spec.GitHubApp == nil || run == nil || run.Spec.Secrets == nil {
		return nil
	}
	secretName := strings.TrimSpace(run.Spec.Secrets.GitHubTokenSecret)
	if secretName == "" {
		return fmt.Errorf("AgentRun %s/%s missing GitHub App token secret reference", run.Namespace, run.Name)
	}
	privateKeyPEM, err := readGitHubAppPrivateKey(ctx, c, gh)
	if err != nil {
		return err
	}
	token, err := mintRunInstallationToken(ctx, minter, gh, run, privateKeyPEM)
	if err != nil {
		return err
	}
	secret := &corev1.Secret{ObjectMeta: metav1.ObjectMeta{Name: secretName, Namespace: run.Namespace}, Type: corev1.SecretTypeOpaque, Data: map[string][]byte{githubapp.TokenSecretKey: []byte(token)}}
	if err := ctrl.SetControllerReference(run, secret, scheme); err != nil {
		return fmt.Errorf("setting owner reference on GitHub token Secret: %w", err)
	}
	if err := c.Create(ctx, secret); err != nil {
		if !apierrors.IsAlreadyExists(err) {
			return fmt.Errorf("creating GitHub token Secret: %w", err)
		}
		existing := &corev1.Secret{}
		if getErr := c.Get(ctx, client.ObjectKey{Namespace: run.Namespace, Name: secretName}, existing); getErr != nil {
			return fmt.Errorf("getting existing GitHub token Secret: %w", getErr)
		}
		if !metav1.IsControlledBy(existing, run) {
			return fmt.Errorf("refusing pre-existing GitHub token Secret %s/%s not controlled by AgentRun UID %s", existing.Namespace, existing.Name, run.UID)
		}
		if existing.Data == nil {
			existing.Data = map[string][]byte{}
		}
		existing.Data[githubapp.TokenSecretKey] = []byte(token)
		existing.Type = corev1.SecretTypeOpaque
		if err := c.Update(ctx, existing); err != nil {
			return fmt.Errorf("updating GitHub token Secret: %w", err)
		}
	}
	return nil
}

