}

func parseMaintainerDecisionAnswer(body, keyword string) (string, string, bool) {
	lowerBody, lowerKeyword := strings.ToLower(body), strings.ToLower(keyword)
	index := strings.Index(lowerBody, lowerKeyword)
	if index < 0 {
		return "", "", false
	}
	remainder := strings.TrimSpace(body[index+len(keyword):])
	const prefix = "answer "
	if !strings.HasPrefix(strings.ToLower(remainder), prefix) {
		return "", "", false
	}
	parts := strings.SplitN(strings.TrimSpace(remainder[len(prefix):]), ":", 2)
	if len(parts) != 2 {
		return "", "", false
	}
	decisionID, answer := strings.TrimSpace(parts[0]), strings.TrimSpace(parts[1])
	return decisionID, answer, decisionID != "" && answer != ""
}

func (r *GitHubRepositoryReconciler) resolveMaintainerDecisionFromGitHubComment(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, issueNumber int, decisionID, answer, subject string, commentID int64) error {
	if issueNumber < 1 || commentID < 1 {
		return nil
	}
	key := client.ObjectKey{Namespace: repository.Namespace, Name: MaintainerWorkItemName(repository.Name, int32(issueNumber))}
	err := r.retryMaintainerWorkItemStatusMutation(ctx, key, func(item *triggersv1alpha1.MaintainerWorkItem) (bool, error) {
		if item.Status.PendingDecision == nil || item.Status.PendingDecision.ID != decisionID {
			return false, nil
		}
		now := metav1.Now()
		item.Status.PendingDecision = nil
		item.Status.ResolvedDecision = &triggersv1alpha1.MaintainerResolvedDecision{ID: decisionID, HumanSubject: subject, Answer: answer, ResolvedAt: now, ResolvedByCommand: corev1.LocalObjectReference{Name: fmt.Sprintf("github-comment-%d", commentID)}}
		item.Status.Phase = triggersv1alpha1.MaintainerWorkItemPhaseTriaged
		item.Status.ProjectionSequence++
		return true, nil
	})
	if apierrors.IsNotFound(err) {
		return nil
	}
	return err
}

func (r *GitHubRepositoryReconciler) maintainerReader() client.Reader {
	if r.APIReader != nil {
		return r.APIReader
	}
	return r.Client
}

func (r *GitHubRepositoryReconciler) reconcileMaintainerWorkItems(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, issues []*github.Issue, issueListComplete bool, githubClient GitHubTriageClient) error {
	items := &triggersv1alpha1.MaintainerWorkItemList{}
	if err := r.List(ctx, items, client.InNamespace(repository.Namespace), client.MatchingLabels{
		triggersv1alpha1.MaintainerWorkItemRepositoryLabelKey: repository.Name,
	}); err != nil {
		return fmt.Errorf("listing maintainer work items: %w", err)
	}

	seen := make(map[string]struct{}, len(issues))
	for _, issue := range issues {
		if issue.IsPullRequest() {
			continue
		}
		issueNumber := int32(issue.GetNumber())
		if issueNumber < 1 {
			continue
		}
		name := MaintainerWorkItemName(repository.Name, issueNumber)
		seen[name] = struct{}{}
		if err := r.ensureMaintainerWorkItem(ctx, repository, name, issueNumber); err != nil {
			return err
		}
		if err := r.observeMaintainerWorkItem(ctx, client.ObjectKey{Namespace: repository.Namespace, Name: name}, issue, "Observed", "Issue observed in open issue list"); err != nil && !apierrors.IsNotFound(err) {
			return err
		}
	}

	if issueListComplete {
		for i := range items.Items {
			item := &items.Items[i]
			if _, ok := seen[item.Name]; ok {
				continue
			}
			// An issue absent from the open list is usually closed (for example
			// auto-closed by a merged pull request). Re-observe it directly so the
			// observation stays fresh and records the real state; otherwise
			// finalize/merge preconditions can never be satisfied again.
			if item.Status.IssueObservation != nil && item.Status.IssueObservation.State == triggersv1alpha1.MaintainerIssueStateClosed && maintainerWorkItemObservationIsFresh(item) {
				continue
			}
			if githubClient != nil {
				issue, _, err := githubClient.GetIssue(ctx, repository.Spec.Owner, repository.Spec.Repo, int(item.Spec.IssueNumber))
				if err == nil && issue != nil {
					if err := r.observeMaintainerWorkItem(ctx, client.ObjectKeyFromObject(item), issue, "ObservedDirectly", "Issue observed directly after leaving the open issue list"); err != nil && !apierrors.IsNotFound(err) {
						return err
					}
					continue
				}
			}
			if err := r.markMaintainerWorkItemObservationStale(ctx, client.ObjectKeyFromObject(item)); err != nil && !apierrors.IsNotFound(err) {
				return err
			}
		}
	}
	return nil
}

func (r *GitHubRepositoryReconciler) ensureMaintainerWorkItem(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, name string, issueNumber int32) error {
	item := &triggersv1alpha1.MaintainerWorkItem{}
	err := r.maintainerReader().Get(ctx, types.NamespacedName{Namespace: repository.Namespace, Name: name}, item)
	if err == nil {
		if item.Spec.RepositoryRef.Name != repository.Name || item.Spec.IssueNumber != issueNumber {
			return fmt.Errorf("maintainer work item %s has a conflicting identity", name)
		}
		if metav1.IsControlledBy(item, repository) && item.Labels[triggersv1alpha1.MaintainerWorkItemRepositoryLabelKey] == repository.Name && item.Labels[triggersv1alpha1.MaintainerWorkItemIssueNumberLabelKey] == strconv.FormatInt(int64(issueNumber), 10) && item.Annotations[triggersv1alpha1.MaintainerWorkItemGraphGateAnnotation] == triggersv1alpha1.MaintainerWorkItemGraphGateVersion {
			return nil
		}
		return retry.RetryOnConflict(retry.DefaultRetry, func() error {
			fresh := &triggersv1alpha1.MaintainerWorkItem{}
			if err := r.maintainerReader().Get(ctx, types.NamespacedName{Namespace: repository.Namespace, Name: name}, fresh); err != nil {
				return err
			}
			if fresh.Spec.RepositoryRef.Name != repository.Name || fresh.Spec.IssueNumber != issueNumber {
				return fmt.Errorf("maintainer work item %s has a conflicting identity", name)
			}
			if fresh.Labels == nil {
				fresh.Labels = map[string]string{}
			}
			fresh.Labels[triggersv1alpha1.MaintainerWorkItemRepositoryLabelKey] = repository.Name
			fresh.Labels[triggersv1alpha1.MaintainerWorkItemIssueNumberLabelKey] = strconv.FormatInt(int64(issueNumber), 10)
			migrateLegacyMaintainerWorkItem(fresh)
			if err := ctrl.SetControllerReference(repository, fresh, r.Scheme); err != nil {
				return fmt.Errorf("setting owner reference on maintainer work item %s: %w", name, err)
			}
			return r.Update(ctx, fresh)
		})
	}
	if !apierrors.IsNotFound(err) {
		return fmt.Errorf("getting maintainer work item %s: %w", name, err)
	}
	item = &triggersv1alpha1.MaintainerWorkItem{
		ObjectMeta: metav1.ObjectMeta{
			Namespace: repository.Namespace,
			Name:      name,
			Labels: map[string]string{
				triggersv1alpha1.MaintainerWorkItemRepositoryLabelKey:  repository.Name,
				triggersv1alpha1.MaintainerWorkItemIssueNumberLabelKey: strconv.FormatInt(int64(issueNumber), 10),
			},
			Annotations: map[string]string{
				triggersv1alpha1.MaintainerWorkItemGraphGateAnnotation: triggersv1alpha1.MaintainerWorkItemGraphGateVersion,
			},
		},
		Spec: triggersv1alpha1.MaintainerWorkItemSpec{
			RepositoryRef: corev1.LocalObjectReference{Name: repository.Name},
			IssueNumber:   issueNumber,
		},
	}
	if err := ctrl.SetControllerReference(repository, item, r.Scheme); err != nil {
		return fmt.Errorf("setting owner reference on maintainer work item %s: %w", name, err)
	}
	if err := r.Create(ctx, item); err != nil && !apierrors.IsAlreadyExists(err) {
		return fmt.Errorf("creating maintainer work item %s: %w", name, err)
	}
	return nil
}

// migrateLegacyMaintainerWorkItem brings a work item created before the current
// contract up to date exactly once, marked by the graph-gate annotation.
//
// An item triaged before the explicit graph-configuration gate existed has no
// GraphConfiguredByCommand, and after an upgrade every such item would become
// undispatchable with "work-item graph has not been explicitly configured"
// until an agent blindly re-submitted a breakdown it had already reviewed. The
// triage command that accepted the scope is treated as that review instead.
//
// Legacy required-pull-request intents are also dropped: they were recorded
// before any pull request existed, can never match a generated monitor name,
// and would otherwise hide merged pull requests behind a phantom projection.
func migrateLegacyMaintainerWorkItem(item *triggersv1alpha1.MaintainerWorkItem) {
	if item.Annotations[triggersv1alpha1.MaintainerWorkItemGraphGateAnnotation] == triggersv1alpha1.MaintainerWorkItemGraphGateVersion {
		return
	}
	if item.Annotations == nil {
		item.Annotations = map[string]string{}
	}
	item.Annotations[triggersv1alpha1.MaintainerWorkItemGraphGateAnnotation] = triggersv1alpha1.MaintainerWorkItemGraphGateVersion
	if item.Spec.GraphConfiguredByCommand == nil && item.Spec.TriagedByCommand != nil {
		item.Spec.GraphConfiguredByCommand = item.Spec.TriagedByCommand.DeepCopy()
	}
	item.Spec.RequiredPullRequests = nil
}

func (r *GitHubRepositoryReconciler) observeMaintainerWorkItem(ctx context.Context, key client.ObjectKey, issue *github.Issue, reason, message string) error {
	now := metav1.Now()
	return retryMaintainerWorkItemStatusUpdate(ctx, r.maintainerReader(), r.Client, key, func(item *triggersv1alpha1.MaintainerWorkItem) bool {
		before := item.Status.DeepCopy()
		observation := maintainerIssueObservation(issue, now)
		if maintainerObservationEqual(item.Status.IssueObservation, &observation) {
			observation.ObservedAt = item.Status.IssueObservation.ObservedAt
			// Non-substantive GitHub activity (comments, cross-references) bumps
			// updatedAt without changing triage-relevant facts; keep the recorded
			// value so the projection sequence only advances on semantic change.
			observation.GitHubUpdatedAt = item.Status.IssueObservation.GitHubUpdatedAt
		}
		item.Status.IssueObservation = &observation
		item.Status.Phase = maintainerWorkItemPhase(item)
		setMaintainerWorkItemCondition(&item.Status.Conditions, metav1.Condition{
			Type:               triggersv1alpha1.ConditionMaintainerWorkItemObservationFresh,
			Status:             metav1.ConditionTrue,
			ObservedGeneration: item.Generation,
			Reason:             reason,
			Message:            message,
		}, now)
		if maintainerWorkItemStatusSemanticallyEqual(before, &item.Status) {
			return false
		}
		item.Status.ProjectionSequence++
		return true
	})
}

func (r *GitHubRepositoryReconciler) markMaintainerWorkItemObservationStale(ctx context.Context, key client.ObjectKey) error {
	return r.markMaintainerWorkItemObservationNotFresh(ctx, key, "NotInOpenIssueList", "Issue was not present in the latest open issue list")
}

func (r *GitHubRepositoryReconciler) markMaintainerWorkItemObservationsUnavailable(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, reason, message string) error {
	items := &triggersv1alpha1.MaintainerWorkItemList{}
	if err := r.List(ctx, items, client.InNamespace(repository.Namespace), client.MatchingLabels{
		triggersv1alpha1.MaintainerWorkItemRepositoryLabelKey: repository.Name,
	}); err != nil {
		return fmt.Errorf("listing maintainer work items to mark observations unavailable: %w", err)
	}
	for i := range items.Items {
		if items.Items[i].Spec.RepositoryRef.Name != repository.Name {
			continue
		}
		if err := r.markMaintainerWorkItemObservationNotFresh(ctx, client.ObjectKeyFromObject(&items.Items[i]), reason, message); err != nil && !apierrors.IsNotFound(err) {
			return err
		}
	}
	return nil
}

func (r *GitHubRepositoryReconciler) markMaintainerWorkItemObservationNotFresh(ctx context.Context, key client.ObjectKey, reason, message string) error {
	now := metav1.Now()
	return retryMaintainerWorkItemStatusUpdate(ctx, r.maintainerReader(), r.Client, key, func(item *triggersv1alpha1.MaintainerWorkItem) bool {
		before := item.Status.DeepCopy()
		setMaintainerWorkItemCondition(&item.Status.Conditions, metav1.Condition{
			Type:               triggersv1alpha1.ConditionMaintainerWorkItemObservationFresh,
			Status:             metav1.ConditionFalse,
			ObservedGeneration: item.Generation,
			Reason:             reason,
			Message:            message,
		}, now)
		if maintainerWorkItemStatusSemanticallyEqual(before, &item.Status) {
			return false
		}
		item.Status.ProjectionSequence++
		return true
	})
}

func maintainerIssueObservation(issue *github.Issue, now metav1.Time) triggersv1alpha1.MaintainerIssueObservation {
	labels := make([]string, 0, len(issue.Labels))
	for _, label := range issue.Labels {
		labels = append(labels, label.GetName())
	}
	sort.Strings(labels)
	bodyHash := sha256.Sum256([]byte(issue.GetBody()))
	state := triggersv1alpha1.MaintainerIssueStateOpen
	if strings.EqualFold(issue.GetState(), string(triggersv1alpha1.MaintainerIssueStateClosed)) {
		state = triggersv1alpha1.MaintainerIssueStateClosed
	}
	return triggersv1alpha1.MaintainerIssueObservation{
		Number:          int32(issue.GetNumber()),
		URL:             issue.GetHTMLURL(),
		Title:           issue.GetTitle(),
		BodyHash:        hex.EncodeToString(bodyHash[:]),
		AuthorLogin:     issue.GetUser().GetLogin(),
		State:           state,
		Labels:          labels,
		GitHubUpdatedAt: metav1.NewTime(issue.GetUpdatedAt().UTC()),
		ObservedAt:      now,
	}
}

func maintainerObservationEqual(left *triggersv1alpha1.MaintainerIssueObservation, right *triggersv1alpha1.MaintainerIssueObservation) bool {
	if left == nil || right == nil {
		return left == right
	}
	leftCopy, rightCopy := *left, *right
	leftCopy.ObservedAt = metav1.Time{}
	rightCopy.ObservedAt = metav1.Time{}
	// updatedAt moves on every comment or timeline event; only substantive
	// fields (title, body hash, labels, state, author) drive change detection.
	leftCopy.GitHubUpdatedAt = metav1.Time{}
	rightCopy.GitHubUpdatedAt = metav1.Time{}
	return equality.Semantic.DeepEqual(leftCopy, rightCopy)
}

func maintainerWorkItemPhase(item *triggersv1alpha1.MaintainerWorkItem) triggersv1alpha1.MaintainerWorkItemPhase {
	if item.Status.Phase != "" && item.Status.Phase != triggersv1alpha1.MaintainerWorkItemPhasePendingTriage && item.Status.Phase != triggersv1alpha1.MaintainerWorkItemPhaseTriaged {
		return item.Status.Phase
	}
	if item.Spec.Disposition != "" {
		return triggersv1alpha1.MaintainerWorkItemPhaseTriaged
	}
	return triggersv1alpha1.MaintainerWorkItemPhasePendingTriage
}

func setMaintainerWorkItemCondition(conditions *[]metav1.Condition, desired metav1.Condition, now metav1.Time) {
	for i := range *conditions {
		current := &(*conditions)[i]
		if current.Type != desired.Type {
			continue
		}
		if current.Status == desired.Status && current.Reason == desired.Reason && current.Message == desired.Message {
			return
		}
		desired.LastTransitionTime = now
		(*conditions)[i] = desired
		return
	}
	desired.LastTransitionTime = now
	*conditions = append(*conditions, desired)
}

func maintainerWorkItemStatusSemanticallyEqual(left, right *triggersv1alpha1.MaintainerWorkItemStatus) bool {
	if left == nil || right == nil {
		return left == right
	}
	leftCopy, rightCopy := left.DeepCopy(), right.DeepCopy()
	normalize := func(status *triggersv1alpha1.MaintainerWorkItemStatus) {
		status.ProjectionSequence = 0
		if status.IssueObservation != nil {
			status.IssueObservation.ObservedAt = metav1.Time{}
			status.IssueObservation.GitHubUpdatedAt = metav1.Time{}
		}
		if status.Readiness != nil {
			status.Readiness.ObservedAt = nil
		}
		for i := range status.Children {
			status.Children[i].ObservedAt = nil
		}
		for i := range status.Dependencies {
			status.Dependencies[i].ObservedAt = nil
		}
		for i := range status.AgentRuns {
			status.AgentRuns[i].ObservedAt = nil
		}
		for i := range status.PullRequests {
			status.PullRequests[i].HeadObservedAt = nil
			status.PullRequests[i].ReviewObservedAt = nil
			status.PullRequests[i].ChecksObservedAt = nil
			status.PullRequests[i].StatusesObservedAt = nil
		}
		for i := range status.Conditions {
			status.Conditions[i].LastTransitionTime = metav1.Time{}
			// Free-form messages (for example error text with embedded rate-limit
			// reset times) must not advance the semantic projection when the
			// condition's type, status, and reason are unchanged.
			status.Conditions[i].Message = ""
		}
		sort.Slice(status.Conditions, func(i, j int) bool { return status.Conditions[i].Type < status.Conditions[j].Type })
		// The remaining collections are +listType=map: their order carries no
		// meaning, and projection passes rebuild them from informer caches whose
		// list order is arbitrary. Entries that tie on the projection sort key
		// (for example two monitors observing the same pull request) would
		// otherwise flip positions between passes and spuriously advance the
		// projection sequence forever, spinning waiter v2.
		sort.Slice(status.Children, func(i, j int) bool { return status.Children[i].Name < status.Children[j].Name })
		sort.Slice(status.Dependencies, func(i, j int) bool { return status.Dependencies[i].Name < status.Dependencies[j].Name })
		sort.Slice(status.AgentRuns, func(i, j int) bool { return status.AgentRuns[i].Name < status.AgentRuns[j].Name })
		sort.Slice(status.AuthorizedAgentRuns, func(i, j int) bool { return status.AuthorizedAgentRuns[i].Name < status.AuthorizedAgentRuns[j].Name })
		sort.Slice(status.PullRequests, func(i, j int) bool { return status.PullRequests[i].IntentName < status.PullRequests[j].IntentName })
		sort.Slice(status.VerifiedMerges, func(i, j int) bool {
			if status.VerifiedMerges[i].Repository != status.VerifiedMerges[j].Repository {
				return status.VerifiedMerges[i].Repository < status.VerifiedMerges[j].Repository
			}
			return status.VerifiedMerges[i].PullRequestNumber < status.VerifiedMerges[j].PullRequestNumber
		})
	}
	normalize(leftCopy)
	normalize(rightCopy)
	return equality.Semantic.DeepEqual(leftCopy, rightCopy)
}

func (r *GitHubRepositoryReconciler) retryMaintainerWorkItemStatusMutation(ctx context.Context, key client.ObjectKey, mutate func(*triggersv1alpha1.MaintainerWorkItem) (bool, error)) error {
	return retry.RetryOnConflict(retry.DefaultRetry, func() error {
		item := &triggersv1alpha1.MaintainerWorkItem{}
		if err := r.maintainerReader().Get(ctx, key, item); err != nil {
			return err
		}
		changed, err := mutate(item)
		if err != nil || !changed {
			return err
		}
		return r.Client.Status().Update(ctx, item)
	})
}

func retryMaintainerWorkItemStatusUpdate(ctx context.Context, reader client.Reader, c client.Client, key client.ObjectKey, mutate func(*triggersv1alpha1.MaintainerWorkItem) bool) error {
	return retry.RetryOnConflict(retry.DefaultRetry, func() error {
		item := &triggersv1alpha1.MaintainerWorkItem{}
		if err := reader.Get(ctx, key, item); err != nil {
			return err
		}
		if !mutate(item) {
			return nil
		}
		return c.Status().Update(ctx, item)
	})
}

func retryMaintainerWorkItemCommandStatusUpdate(ctx context.Context, c client.Client, key client.ObjectKey, mutate func(*triggersv1alpha1.MaintainerWorkItemCommand)) error {
	return retry.RetryOnConflict(retry.DefaultRetry, func() error {
		command := &triggersv1alpha1.MaintainerWorkItemCommand{}
		if err := c.Get(ctx, key, command); err != nil {
			return err
		}
		mutate(command)
		return c.Status().Update(ctx, command)
	})
}

func (r *GitHubRepositoryReconciler) reconcileMaintainerWorkItemCommands(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, githubClient GitHubTriageClient, deliveryClients ...maintainerGitHubDeliveryClient) error {
	var deliveryClient maintainerGitHubDeliveryClient
	if len(deliveryClients) > 0 {
		deliveryClient = deliveryClients[0]
	}
	commands := &triggersv1alpha1.MaintainerWorkItemCommandList{}
	if err := r.List(ctx, commands, client.InNamespace(repository.Namespace)); err != nil {
		return fmt.Errorf("listing maintainer work item commands: %w", err)
	}
	for i := range commands.Items {
		command := &commands.Items[i]
		if command.Spec.RepositoryRef.Name != repository.Name || maintainerCommandTerminal(command.Status.Phase) {
			continue
		}
		if command.Status.Phase == triggersv1alpha1.MaintainerWorkItemCommandPhaseFailed && maintainerCommandFailureCount(command) >= maintainerCommandFailureBudget {
			durable, err := r.maintainerCommandHasDurableSideEffects(ctx, repository, command)
			if err != nil {
				return err
			}
			if !durable {
				message := "retry budget exhausted after repeated failures"
				if command.Status.Result != nil && command.Status.Result.Message != "" {
					message += "; last failure: " + command.Status.Result.Message
				}
				if err := r.rejectMaintainerWorkItemCommand(ctx, repository, command, message); err != nil {
					return err
				}
				continue
			}
		}
		if err := r.processMaintainerWorkItemCommand(ctx, repository, command, githubClient, deliveryClient); err != nil {
			return err
		}
	}
	return nil
}

// maintainerCommandFailureBudget bounds how often a Failed command is
// reprocessed before it is terminally rejected, so persistently failing
// commands cannot burn GitHub quota on every reconcile forever.
const maintainerCommandFailureBudget = 5

func maintainerCommandFailureCount(command *triggersv1alpha1.MaintainerWorkItemCommand) int {
	count, err := strconv.Atoi(command.Annotations[triggersv1alpha1.MaintainerCommandFailureCountAnnotation])
	if err != nil || count < 0 {
		return 0
	}
	return count
}

// maintainerCommandHasDurableSideEffects reports whether a command already
// crossed a durable side-effect boundary (an attempted merge or an issued
// delivery attestation). Such commands must keep reconciling until GitHub
// reports a conclusive outcome; terminally rejecting them would orphan the
// side effect (for example a merge that later becomes visible would never be
// recorded in VerifiedMerges).
func (r *GitHubRepositoryReconciler) maintainerCommandHasDurableSideEffects(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand) (bool, error) {
	if command.Status.Result != nil && command.Status.Result.MergeAttemptedAt != nil {
		return true, nil
	}
	if command.Spec.Type != triggersv1alpha1.MaintainerWorkItemCommandTypeFinalizeWorkItem {
		return false, nil
	}
	item := &triggersv1alpha1.MaintainerWorkItem{}
	if err := r.maintainerReader().Get(ctx, client.ObjectKey{Namespace: repository.Namespace, Name: command.Spec.Preconditions.WorkItemName}, item); err != nil {
		if apierrors.IsNotFound(err) {
			return false, nil
		}
		return false, err
	}
	return item.Status.DeliveryAttestation != nil && item.Status.DeliveryAttestation.FinalizedByCommand.Name == command.Name && item.Status.DeliveryAttestation.CompletedAt == nil, nil
}

func (r *GitHubRepositoryReconciler) incrementMaintainerCommandFailureCount(ctx context.Context, command *triggersv1alpha1.MaintainerWorkItemCommand) error {
	return retry.RetryOnConflict(retry.DefaultRetry, func() error {
		fresh := &triggersv1alpha1.MaintainerWorkItemCommand{}
		if err := r.maintainerReader().Get(ctx, client.ObjectKeyFromObject(command), fresh); err != nil {
			return client.IgnoreNotFound(err)
		}
		patch := client.MergeFromWithOptions(fresh.DeepCopy(), client.MergeFromWithOptimisticLock{})
		if fresh.Annotations == nil {
			fresh.Annotations = map[string]string{}
		}
		fresh.Annotations[triggersv1alpha1.MaintainerCommandFailureCountAnnotation] = strconv.Itoa(maintainerCommandFailureCount(fresh) + 1)
		return r.Patch(ctx, fresh, patch)
	})
}

func maintainerCommandTerminal(phase triggersv1alpha1.MaintainerWorkItemCommandPhase) bool {
	return phase == triggersv1alpha1.MaintainerWorkItemCommandPhaseSucceeded || phase == triggersv1alpha1.MaintainerWorkItemCommandPhaseRejected
}

type maintainerCommandRejectedError struct{ message string }

func (e maintainerCommandRejectedError) Error() string { return e.message }

func rejectMaintainerCommand(message string) error {
	return maintainerCommandRejectedError{message: message}
}

func (r *GitHubRepositoryReconciler) processMaintainerWorkItemCommand(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand, githubClient GitHubTriageClient, deliveryClient maintainerGitHubDeliveryClient) error {
	pending := command.Status.Phase == "" || command.Status.Phase == triggersv1alpha1.MaintainerWorkItemCommandPhasePending
	item, err := r.validateMaintainerWorkItemCommand(ctx, repository, command, pending)
	if err != nil {
		var rejected maintainerCommandRejectedError
		if !asMaintainerCommandRejected(err, &rejected) {
			return err
		}
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, rejected.message)
	}
	if command.Spec.Type != triggersv1alpha1.MaintainerWorkItemCommandTypeTriageIssue {
		return r.processMaintainerExecutionCommand(ctx, repository, command, item, githubClient, deliveryClient, pending)
	}

	if pending {
		item, err = r.applyMaintainerTriageIntent(ctx, repository, command)
		if err != nil {
			var rejected maintainerCommandRejectedError
			if asMaintainerCommandRejected(err, &rejected) {
				return r.rejectMaintainerWorkItemCommand(ctx, repository, command, rejected.message)
			}
			return err
		}
		if err := r.markMaintainerWorkItemTriaged(ctx, client.ObjectKeyFromObject(item), command.Name); err != nil {
			return err
		}
		if err := r.setMaintainerWorkItemCommandAccepted(ctx, command, item); err != nil {
			return err
		}
	} else {
		if err := r.markMaintainerWorkItemTriaged(ctx, client.ObjectKeyFromObject(item), command.Name); err != nil {
			return err
		}
		if err := r.setMaintainerWorkItemCommandAccepted(ctx, command, item); err != nil {
			return err
		}
	}

	if command.Spec.Triage.Disposition != triggersv1alpha1.MaintainerWorkItemDispositionNotActionable {
		return r.completeMaintainerWorkItemCommand(ctx, command, item, "triage intent recorded", "", observedIssueState(item))
	}
	if command.Spec.Triage.CloseReason == nil {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "NotActionable triage requires closeReason")
	}
	if githubClient == nil {
		return r.failMaintainerWorkItemCommand(ctx, command, item, "GitHub triage client is unavailable")
	}
	commentURL, state, err := r.applyNotActionableTriage(ctx, repository, item, command.Spec.Triage, githubClient)
	if err != nil {
		return r.failMaintainerWorkItemCommand(ctx, command, item, err.Error())
	}
	if err := r.markMaintainerWorkItemClosed(ctx, client.ObjectKeyFromObject(item)); err != nil {
		return err
	}
	return r.completeMaintainerWorkItemCommand(ctx, command, item, "issue triaged and closed", commentURL, state)
}

func asMaintainerCommandRejected(err error, target *maintainerCommandRejectedError) bool {
	if err == nil {
		return false
	}
	value, ok := err.(maintainerCommandRejectedError)
	if ok {
		*target = value
	}
	return ok
}

func (r *GitHubRepositoryReconciler) validateMaintainerWorkItemCommand(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand, requirePreconditions bool) (*triggersv1alpha1.MaintainerWorkItem, error) {
	if command.Spec.RepositoryRef.Name != repository.Name || command.Spec.RepositoryRef.Name == "" {
		return nil, rejectMaintainerCommand("repositoryRef does not match GitHubRepository")
	}
	if command.Name != MaintainerWorkItemCommandName(repository.Name, command.Spec.IdempotencyKey) {
		return nil, rejectMaintainerCommand("command name does not match idempotency key")
	}
	if !metav1.IsControlledBy(command, repository) {
		return nil, rejectMaintainerCommand("command is not controller-owned by GitHubRepository")
	}
	issueNumber, err := validateMaintainerCommandPayload(command)
	if err != nil {
		return nil, err
	}
	expectedHash := triggersv1alpha1.MaintainerWorkItemCommandSpecPayloadHash(command.Spec)
	if command.Spec.Type == triggersv1alpha1.MaintainerWorkItemCommandTypeTriageIssue {
		expectedHash = MaintainerWorkItemCommandPayloadHash(command.Spec.Type, command.Spec.Triage, command.Spec.Preconditions)
	}
	if command.Spec.PayloadHash != expectedHash {
		return nil, rejectMaintainerCommand("payloadHash does not match command payload")
	}
	if err := r.authorizeMaintainerCommand(ctx, repository, command); err != nil {
		return nil, err
	}
	name := MaintainerWorkItemName(repository.Name, issueNumber)
	if command.Spec.Preconditions.WorkItemName != name {
		return nil, rejectMaintainerCommand("precondition workItemName does not match command issue")
	}
	item := &triggersv1alpha1.MaintainerWorkItem{}
	if err := r.maintainerReader().Get(ctx, client.ObjectKey{Namespace: repository.Namespace, Name: name}, item); err != nil {
		if apierrors.IsNotFound(err) {
			return nil, rejectMaintainerCommand("work item does not exist")
		}
		return nil, fmt.Errorf("getting maintainer work item: %w", err)
	}
	if item.Spec.RepositoryRef.Name != repository.Name || item.Spec.IssueNumber != issueNumber {
		return nil, rejectMaintainerCommand("work item does not match command issue")
	}
	if command.Spec.Preconditions.WorkItemUID == "" || item.UID != command.Spec.Preconditions.WorkItemUID {
		return nil, rejectMaintainerCommand("target work-item UID does not match command preconditions")
	}
	alreadyApplied := maintainerCommandAlreadyApplied(item, command)
	if !requirePreconditions && command.Spec.Type == triggersv1alpha1.MaintainerWorkItemCommandTypeTriageIssue && !alreadyApplied {
		return nil, rejectMaintainerCommand("command was superseded by newer triage intent; " + currentProjectionMessage(item))
	}
	if requirePreconditions && !alreadyApplied && !maintainerWorkItemObservationIsFresh(item) {
		return nil, rejectMaintainerCommand("work item issue observation is not fresh; " + currentProjectionMessage(item))
	}
	// Preconditions.ResourceVersion is advisory only: the work item's
	// resourceVersion churns on every non-semantic status write (observedAt
	// refreshes, agent-run phase projections), so gating on it rejected
	// otherwise-valid commands. ProjectionSequence is the semantic
	// optimistic-concurrency token and remains the hard gate.
	if requirePreconditions && !alreadyApplied && item.Status.ProjectionSequence != command.Spec.Preconditions.ProjectionSequence {
		return nil, rejectMaintainerCommand(currentProjectionMessage(item))
	}
	return item, nil
}

func validateMaintainerCommandPayload(command *triggersv1alpha1.MaintainerWorkItemCommand) (int32, error) {
	if command == nil {
		return 0, rejectMaintainerCommand("command is nil")
	}
	switch command.Spec.Type {
	case triggersv1alpha1.MaintainerWorkItemCommandTypeTriageIssue:
		if command.Spec.Triage == nil || command.Spec.Triage.IssueNumber < 1 || strings.TrimSpace(command.Spec.Triage.EvidenceSummary) == "" {
			return 0, rejectMaintainerCommand("incomplete triage payload")
		}
		return command.Spec.Triage.IssueNumber, nil
	case triggersv1alpha1.MaintainerWorkItemCommandTypeBreakdownIssue:
		if command.Spec.Breakdown == nil || command.Spec.Breakdown.IssueNumber < 1 {
			return 0, rejectMaintainerCommand("incomplete work-item graph payload")
		}
		return command.Spec.Breakdown.IssueNumber, nil
	case triggersv1alpha1.MaintainerWorkItemCommandTypeRequestDecision:
		if command.Spec.RequestDecision == nil || command.Spec.RequestDecision.IssueNumber < 1 || strings.TrimSpace(command.Spec.RequestDecision.DecisionID) == "" || strings.TrimSpace(command.Spec.RequestDecision.Question) == "" {
			return 0, rejectMaintainerCommand("incomplete requestDecision payload")
		}
		return command.Spec.RequestDecision.IssueNumber, nil
	case triggersv1alpha1.MaintainerWorkItemCommandTypeResolveDecision:
		if command.Spec.HumanIssuer == nil {
			return 0, rejectMaintainerCommand("resolveDecision commands from AgentRuns are not authorized; answer with an authenticated GitHub issue comment")
		}
		resolve := command.Spec.ResolveDecision
		if resolve == nil || resolve.IssueNumber < 1 || strings.TrimSpace(resolve.DecisionID) == "" || strings.TrimSpace(resolve.HumanAnswer.Answer) == "" {
			return 0, rejectMaintainerCommand("incomplete resolveDecision payload")
		}
		if resolve.HumanAnswer.Subject != command.Spec.HumanIssuer.Subject {
			return 0, rejectMaintainerCommand("resolveDecision humanAnswer subject does not match humanIssuer subject")
		}
		return resolve.IssueNumber, nil
	case triggersv1alpha1.MaintainerWorkItemCommandTypeDispatchWorkItem:
		if command.Spec.Dispatch == nil || command.Spec.Dispatch.IssueNumber < 1 || strings.TrimSpace(command.Spec.Dispatch.Mode) == "" {
			return 0, rejectMaintainerCommand("incomplete dispatch payload")
		}
		return command.Spec.Dispatch.IssueNumber, nil
	case triggersv1alpha1.MaintainerWorkItemCommandTypeRequestMerge:
		merge := command.Spec.RequestMerge
		if merge == nil || merge.IssueNumber < 1 || merge.PullRequestNumber < 1 || strings.TrimSpace(merge.Repository) == "" || len(merge.ExpectedHeadSHA) != 40 || (merge.MergeMethod != triggersv1alpha1.MaintainerWorkItemMergeMethodSquash && merge.MergeMethod != triggersv1alpha1.MaintainerWorkItemMergeMethodMerge && merge.MergeMethod != triggersv1alpha1.MaintainerWorkItemMergeMethodRebase) {
			return 0, rejectMaintainerCommand("incomplete requestMerge payload")
		}
		return merge.IssueNumber, nil
	case triggersv1alpha1.MaintainerWorkItemCommandTypeFinalizeWorkItem:
		finalize := command.Spec.Finalize
		if finalize == nil || finalize.IssueNumber < 1 || len(finalize.AcceptedScopeHash) != 64 || strings.TrimSpace(finalize.DeliverySummary) == "" || strings.TrimSpace(finalize.DeliveryEvidence) == "" {
			return 0, rejectMaintainerCommand("incomplete finalize payload")
		}
		return finalize.IssueNumber, nil
	default:
		return 0, rejectMaintainerCommand("unsupported command type")
	}
}

func (r *GitHubRepositoryReconciler) authorizeMaintainerCommand(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand) error {
	if (command.Spec.Issuer == nil) == (command.Spec.HumanIssuer == nil) {
		return rejectMaintainerCommand("exactly one of issuer or humanIssuer is required")
	}
	if command.Spec.HumanIssuer != nil {
		return r.authorizeHumanMaintainerCommand(ctx, repository, command)
	}
	return r.authorizeAgentRunMaintainerCommand(ctx, repository, command)
}

func (r *GitHubRepositoryReconciler) authorizeHumanMaintainerCommand(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand) error {
	humanIssuer := command.Spec.HumanIssuer
	capabilityName := triggersv1alpha1.MaintainerHumanCommandCapabilitySecretName(repository.Name)
	capability := &corev1.Secret{}
	if err := r.Get(ctx, client.ObjectKey{Namespace: repository.Namespace, Name: capabilityName}, capability); err != nil {
		if apierrors.IsNotFound(err) {
			return rejectMaintainerCommand("human command capability does not exist")
		}
		return fmt.Errorf("getting human command capability: %w", err)
	}
	if !metav1.IsControlledBy(capability, repository) {
		return rejectMaintainerCommand("human command capability is not controlled by GitHubRepository")
	}
	if string(capability.Data[triggersv1alpha1.MaintainerCommandCapabilityRepositoryNameKey]) != repository.Name || string(capability.Data[triggersv1alpha1.MaintainerCommandCapabilityRepositoryUIDKey]) != string(repository.UID) {
		return rejectMaintainerCommand("human command capability is bound to a different GitHubRepository")
	}
	key := capability.Data[triggersv1alpha1.MaintainerCommandCapabilitySecretKey]
	if len(key) < 32 {
		return rejectMaintainerCommand("human command capability is invalid")
	}
	expectedProof := triggersv1alpha1.MaintainerHumanCommandProof(key, repository.Name, repository.UID, command.Spec.IdempotencyKey, command.Spec.PayloadHash, humanIssuer.Subject)
	if !hmac.Equal([]byte(expectedProof), []byte(humanIssuer.Proof)) {
		return rejectMaintainerCommand("human command proof is invalid")
	}
	return nil
}

func (r *GitHubRepositoryReconciler) authorizeAgentRunMaintainerCommand(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand) error {
	if command.Spec.Issuer == nil {
		return rejectMaintainerCommand("command has no issuer")
	}
	issuerSpec := command.Spec.Issuer
	issuer := &platformv1alpha1.AgentRun{}
	if err := r.Get(ctx, client.ObjectKey{Namespace: repository.Namespace, Name: issuerSpec.RunName}, issuer); err != nil {
		if apierrors.IsNotFound(err) {
			return rejectMaintainerCommand("issuer AgentRun does not exist")
		}
		return fmt.Errorf("getting issuer AgentRun: %w", err)
	}
	if issuer.UID != issuerSpec.UID {
		return rejectMaintainerCommand("issuer UID does not match AgentRun")
	}
	if issuer.Labels[orchestration.StandingRunRoleLabel] != orchestration.StandingRunRoleMaintainer {
		return rejectMaintainerCommand("issuer is not a standing maintainer")
	}
	if issuer.Labels[orchestration.SupervisedRunLabel] != repository.Name {
		return rejectMaintainerCommand("issuer is not assigned to this repository")
	}
	ownedByRepository := false
	for _, owner := range issuer.OwnerReferences {
		if owner.Controller != nil && *owner.Controller && owner.APIVersion == triggersv1alpha1.GroupVersion.String() && owner.Kind == gitHubRepositoryTriggerKind && owner.Name == repository.Name && owner.UID == repository.UID {
			ownedByRepository = true
			break
		}
	}
	if !ownedByRepository {
		return rejectMaintainerCommand("issuer is not controller-owned by this GitHubRepository")
	}
	capability := &corev1.Secret{}
	capabilityName := triggersv1alpha1.MaintainerCommandCapabilitySecretName(issuer.Name)
	if err := r.Get(ctx, client.ObjectKey{Namespace: issuer.Namespace, Name: capabilityName}, capability); err != nil {
		if apierrors.IsNotFound(err) {
			return rejectMaintainerCommand("issuer command capability does not exist")
		}
		return fmt.Errorf("getting issuer command capability: %w", err)
	}
	if !metav1.IsControlledBy(capability, issuer) {
		return rejectMaintainerCommand("issuer command capability is not owned by issuer AgentRun")
	}
	if string(capability.Data[triggersv1alpha1.MaintainerCommandCapabilityRepositoryNameKey]) != repository.Name || string(capability.Data[triggersv1alpha1.MaintainerCommandCapabilityRepositoryUIDKey]) != string(repository.UID) {
		return rejectMaintainerCommand("issuer command capability is bound to a different GitHubRepository")
	}
	key := capability.Data[triggersv1alpha1.MaintainerCommandCapabilitySecretKey]
	if len(key) < 32 {
		return rejectMaintainerCommand("issuer command capability is invalid")
	}
	expectedProof := triggersv1alpha1.MaintainerWorkItemCommandProof(key, repository.Name, repository.UID, command.Spec.IdempotencyKey, command.Spec.PayloadHash, issuer.Name, issuer.UID)
	if !hmac.Equal([]byte(expectedProof), []byte(issuerSpec.Proof)) {
		return rejectMaintainerCommand("issuer command proof is invalid")
	}
	return nil
}

func (r *GitHubRepositoryReconciler) applyMaintainerTriageIntent(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand) (*triggersv1alpha1.MaintainerWorkItem, error) {
	key := client.ObjectKey{Namespace: repository.Namespace, Name: command.Spec.Preconditions.WorkItemName}
	item := &triggersv1alpha1.MaintainerWorkItem{}
	err := retry.RetryOnConflict(retry.DefaultRetry, func() error {
		fresh := &triggersv1alpha1.MaintainerWorkItem{}
		if err := r.Get(ctx, key, fresh); err != nil {
			if apierrors.IsNotFound(err) {
				return rejectMaintainerCommand("work item does not exist")
			}
			return err
		}
		if fresh.Spec.RepositoryRef.Name != repository.Name || fresh.Spec.IssueNumber != command.Spec.Triage.IssueNumber {
			return rejectMaintainerCommand("work item does not match command issue")
		}
		if maintainerTriageAlreadyApplied(fresh, command) {
			item = fresh
			return nil
		}
		if fresh.Status.ProjectionSequence != command.Spec.Preconditions.ProjectionSequence {
			return rejectMaintainerCommand(currentProjectionMessage(fresh))
		}
		fresh.Spec.Disposition = command.Spec.Triage.Disposition
		fresh.Spec.EvidenceSummary = command.Spec.Triage.EvidenceSummary
		fresh.Spec.AcceptedScope = command.Spec.Triage.AcceptedScope.DeepCopy()
		fresh.Spec.CloseReason = command.Spec.Triage.CloseReason
		fresh.Spec.TriagedByCommand = &corev1.LocalObjectReference{Name: command.Name}
		// A new accepted scope invalidates the previous graph review. The
		// maintainer must explicitly persist the graph again before dispatch.
		fresh.Spec.GraphConfiguredByCommand = nil
		if err := r.Update(ctx, fresh); err != nil {
			return err
		}
		item = fresh
		return nil
	})
	return item, err
}

func maintainerTriageAlreadyApplied(item *triggersv1alpha1.MaintainerWorkItem, command *triggersv1alpha1.MaintainerWorkItemCommand) bool {
	return item.Spec.TriagedByCommand != nil && item.Spec.TriagedByCommand.Name == command.Name && item.Spec.Disposition == command.Spec.Triage.Disposition && item.Spec.EvidenceSummary == command.Spec.Triage.EvidenceSummary && equality.Semantic.DeepEqual(item.Spec.AcceptedScope, &command.Spec.Triage.AcceptedScope) && equality.Semantic.DeepEqual(item.Spec.CloseReason, command.Spec.Triage.CloseReason)
}

func maintainerCommandAlreadyApplied(item *triggersv1alpha1.MaintainerWorkItem, command *triggersv1alpha1.MaintainerWorkItemCommand) bool {
	if item == nil || command == nil {
		return false
	}
	switch command.Spec.Type {
	case triggersv1alpha1.MaintainerWorkItemCommandTypeTriageIssue:
		return command.Spec.Triage != nil && maintainerTriageAlreadyApplied(item, command)
	case triggersv1alpha1.MaintainerWorkItemCommandTypeBreakdownIssue:
		return command.Spec.Breakdown != nil && item.Spec.GraphConfiguredByCommand != nil && item.Spec.GraphConfiguredByCommand.Name == command.Name && equality.Semantic.DeepEqual(item.Spec.Children, command.Spec.Breakdown.Children) && equality.Semantic.DeepEqual(item.Spec.Dependencies, command.Spec.Breakdown.Dependencies)
	case triggersv1alpha1.MaintainerWorkItemCommandTypeRequestDecision:
		return item.Status.PendingDecision != nil && item.Status.PendingDecision.RequestedByCommand != nil && item.Status.PendingDecision.RequestedByCommand.Name == command.Name
	case triggersv1alpha1.MaintainerWorkItemCommandTypeResolveDecision:
		return item.Status.ResolvedDecision != nil && item.Status.ResolvedDecision.ResolvedByCommand.Name == command.Name
	case triggersv1alpha1.MaintainerWorkItemCommandTypeDispatchWorkItem:
		return item.Status.DispatchReservation != nil && item.Status.DispatchReservation.CommandRef.Name == command.Name
	case triggersv1alpha1.MaintainerWorkItemCommandTypeRequestMerge:
		return command.Spec.RequestMerge != nil && verifiedMaintainerMerge(item, command.Spec.RequestMerge.Repository, command.Spec.RequestMerge.PullRequestNumber) != nil
	case triggersv1alpha1.MaintainerWorkItemCommandTypeFinalizeWorkItem:
		return item.Status.DeliveryAttestation != nil && item.Status.DeliveryAttestation.FinalizedByCommand.Name == command.Name
	default:
		return false
	}
}

func (r *GitHubRepositoryReconciler) markMaintainerWorkItemTriaged(ctx context.Context, key client.ObjectKey, commandName string) error {
	now := metav1.Now()
	return retryMaintainerWorkItemStatusUpdate(ctx, r.maintainerReader(), r.Client, key, func(item *triggersv1alpha1.MaintainerWorkItem) bool {
		before := item.Status.DeepCopy()
		item.Status.Phase = triggersv1alpha1.MaintainerWorkItemPhaseTriaged
		setMaintainerWorkItemCondition(&item.Status.Conditions, metav1.Condition{
			Type:               triggersv1alpha1.ConditionMaintainerWorkItemCommandAccepted,
			Status:             metav1.ConditionTrue,
			ObservedGeneration: item.Generation,
			Reason:             "Accepted",
			Message:            "Triage accepted from command " + commandName,
		}, now)
		if maintainerWorkItemStatusSemanticallyEqual(before, &item.Status) {
			return false
		}
		item.Status.ProjectionSequence++
		return true
	})
}

func (r *GitHubRepositoryReconciler) markMaintainerWorkItemClosed(ctx context.Context, key client.ObjectKey) error {
	now := metav1.Now()
	return retryMaintainerWorkItemStatusUpdate(ctx, r.maintainerReader(), r.Client, key, func(item *triggersv1alpha1.MaintainerWorkItem) bool {
		before := item.Status.DeepCopy()
		if item.Status.IssueObservation == nil {
			item.Status.IssueObservation = &triggersv1alpha1.MaintainerIssueObservation{Number: item.Spec.IssueNumber}
		}
		item.Status.IssueObservation.State = triggersv1alpha1.MaintainerIssueStateClosed
		item.Status.IssueObservation.ObservedAt = now
		if maintainerWorkItemStatusSemanticallyEqual(before, &item.Status) {
			return false
		}
		item.Status.ProjectionSequence++
		return true
	})
}

func (r *GitHubRepositoryReconciler) setMaintainerWorkItemCommandAccepted(ctx context.Context, command *triggersv1alpha1.MaintainerWorkItemCommand, item *triggersv1alpha1.MaintainerWorkItem) error {
	message := string(command.Spec.Type) + " command accepted; side effects are not yet verified"
	err := retryMaintainerWorkItemCommandStatusUpdate(ctx, r.Client, client.ObjectKeyFromObject(command), func(fresh *triggersv1alpha1.MaintainerWorkItemCommand) {
		var recoveryRunRef *corev1.LocalObjectReference
		if fresh.Status.Result != nil {
			recoveryRunRef = fresh.Status.Result.AgentRunRef
		}
		fresh.Status.Phase = triggersv1alpha1.MaintainerWorkItemCommandPhaseAccepted
		fresh.Status.ObservedGeneration = fresh.Generation
		fresh.Status.Result = &triggersv1alpha1.MaintainerWorkItemCommandResult{
			WorkItemRef: corev1.LocalObjectReference{Name: item.Name},
			Applied:     false,
			Message:     message,
			IssueState:  observedIssueState(item),
			AgentRunRef: recoveryRunRef,
		}
	})
	return err
}

func (r *GitHubRepositoryReconciler) completeMaintainerWorkItemCommand(ctx context.Context, command *triggersv1alpha1.MaintainerWorkItemCommand, item *triggersv1alpha1.MaintainerWorkItem, message, commentURL string, state triggersv1alpha1.MaintainerIssueState) error {
	now := metav1.Now()
	current := &triggersv1alpha1.MaintainerWorkItem{}
	if err := r.maintainerReader().Get(ctx, client.ObjectKeyFromObject(item), current); err != nil {
		return err
	}
	err := retryMaintainerWorkItemCommandStatusUpdate(ctx, r.Client, client.ObjectKeyFromObject(command), func(fresh *triggersv1alpha1.MaintainerWorkItemCommand) {
		fresh.Status.Phase = triggersv1alpha1.MaintainerWorkItemCommandPhaseSucceeded
		fresh.Status.ObservedGeneration = fresh.Generation
		var mergeAttemptedAt *metav1.Time
		if fresh.Status.Result != nil {
			mergeAttemptedAt = fresh.Status.Result.MergeAttemptedAt
		}
		result := &triggersv1alpha1.MaintainerWorkItemCommandResult{WorkItemRef: corev1.LocalObjectReference{Name: item.Name}, Applied: true, Message: message, CommentURL: commentURL, IssueState: state, MergeAttemptedAt: mergeAttemptedAt, CompletedAt: &now}
		if command.Spec.RequestMerge != nil {
			for i := range current.Status.VerifiedMerges {
				verified := &current.Status.VerifiedMerges[i]
				if verified.Repository == command.Spec.RequestMerge.Repository && verified.PullRequestNumber == command.Spec.RequestMerge.PullRequestNumber {
					result.VerifiedMerge = verified.DeepCopy()
				}
			}
		}
		result.DeliveryAttestation = current.Status.DeliveryAttestation.DeepCopy()
		fresh.Status.Result = result
	})
	if err != nil {
		return err
	}
	return r.projectMaintainerCommandObservation(ctx, item, command, triggersv1alpha1.MaintainerWorkItemCommandPhaseSucceeded, true, message)
}

func (r *GitHubRepositoryReconciler) failMaintainerWorkItemCommand(ctx context.Context, command *triggersv1alpha1.MaintainerWorkItemCommand, item *triggersv1alpha1.MaintainerWorkItem, message string) error {
	if err := r.incrementMaintainerCommandFailureCount(ctx, command); err != nil {
		return err
	}
	err := retryMaintainerWorkItemCommandStatusUpdate(ctx, r.Client, client.ObjectKeyFromObject(command), func(fresh *triggersv1alpha1.MaintainerWorkItemCommand) {
		fresh.Status.Phase = triggersv1alpha1.MaintainerWorkItemCommandPhaseFailed
		fresh.Status.ObservedGeneration = fresh.Generation
		var mergeAttemptedAt *metav1.Time
		if fresh.Status.Result != nil {
			mergeAttemptedAt = fresh.Status.Result.MergeAttemptedAt
		}
		fresh.Status.Result = &triggersv1alpha1.MaintainerWorkItemCommandResult{WorkItemRef: corev1.LocalObjectReference{Name: item.Name}, Applied: false, Message: message, IssueState: observedIssueState(item), MergeAttemptedAt: mergeAttemptedAt}
	})
	if err != nil {
		return err
	}
	return r.projectMaintainerCommandObservation(ctx, item, command, triggersv1alpha1.MaintainerWorkItemCommandPhaseFailed, false, message)
}

func (r *GitHubRepositoryReconciler) rejectMaintainerWorkItemCommand(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand, message string) error {
	message = currentMaintainerProjectionMessage(ctx, r.Client, repository, command, message)
	err := retryMaintainerWorkItemCommandStatusUpdate(ctx, r.Client, client.ObjectKeyFromObject(command), func(fresh *triggersv1alpha1.MaintainerWorkItemCommand) {
		fresh.Status.Phase = triggersv1alpha1.MaintainerWorkItemCommandPhaseRejected
		fresh.Status.ObservedGeneration = fresh.Generation
		fresh.Status.Result = &triggersv1alpha1.MaintainerWorkItemCommandResult{WorkItemRef: corev1.LocalObjectReference{Name: fresh.Spec.Preconditions.WorkItemName}, Applied: false, Message: message}
	})
	if err != nil {
		return err
	}
	item := &triggersv1alpha1.MaintainerWorkItem{}
	if err := r.maintainerReader().Get(ctx, client.ObjectKey{Namespace: repository.Namespace, Name: command.Spec.Preconditions.WorkItemName}, item); err != nil {
		return client.IgnoreNotFound(err)
	}
	return r.projectMaintainerCommandObservation(ctx, item, command, triggersv1alpha1.MaintainerWorkItemCommandPhaseRejected, false, message)
}

func (r *GitHubRepositoryReconciler) projectMaintainerCommandObservation(ctx context.Context, item *triggersv1alpha1.MaintainerWorkItem, command *triggersv1alpha1.MaintainerWorkItemCommand, phase triggersv1alpha1.MaintainerWorkItemCommandPhase, applied bool, message string) error {
	if item == nil || command == nil {
		return nil
	}
	return r.retryMaintainerWorkItemStatusMutation(ctx, client.ObjectKeyFromObject(item), func(fresh *triggersv1alpha1.MaintainerWorkItem) (bool, error) {
		if fresh.UID != command.Spec.Preconditions.WorkItemUID {
			// Never project an old command receipt into a replacement object.
			return false, nil
		}
		now := metav1.Now()
		desired := &triggersv1alpha1.MaintainerWorkItemCommandObservation{Name: command.Name, Type: command.Spec.Type, Phase: phase, Applied: applied, Message: message, ObservedAt: now}
		if fresh.Status.LatestCommand != nil && fresh.Status.LatestCommand.Name == desired.Name && fresh.Status.LatestCommand.Phase == desired.Phase && fresh.Status.LatestCommand.Applied == desired.Applied && fresh.Status.LatestCommand.Message == desired.Message {
			return false, nil
		}
		fresh.Status.LatestCommand = desired
		fresh.Status.ProjectionSequence++
		return true, nil
	})
}

func currentMaintainerProjectionMessage(ctx context.Context, c client.Client, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand, prefix string) string {
	name := command.Spec.Preconditions.WorkItemName
	if command.Spec.Triage != nil && command.Spec.Triage.IssueNumber > 0 {
		name = MaintainerWorkItemName(repository.Name, command.Spec.Triage.IssueNumber)
	}
	item := &triggersv1alpha1.MaintainerWorkItem{}
	if err := c.Get(ctx, client.ObjectKey{Namespace: repository.Namespace, Name: name}, item); err != nil {
		return prefix + "; current projection unavailable"
	}
	return prefix + "; " + currentProjectionMessage(item)
}

func currentProjectionMessage(item *triggersv1alpha1.MaintainerWorkItem) string {
	var message strings.Builder
	fmt.Fprintf(&message, "current projection sequence %d resourceVersion %s", item.Status.ProjectionSequence, item.ResourceVersion)
	for _, condition := range item.Status.Conditions {
		if condition.Type == triggersv1alpha1.ConditionMaintainerWorkItemObservationFresh && condition.Status != metav1.ConditionTrue {
			fmt.Fprintf(&message, "; observation not fresh (%s)", condition.Reason)
			if item.Status.IssueObservation != nil {
				fmt.Fprintf(&message, "; last observation state %s at %s", item.Status.IssueObservation.State, item.Status.IssueObservation.ObservedAt.UTC().Format(time.RFC3339))
			}
		}
	}
	return message.String()
}

func maintainerWorkItemObservationIsFresh(item *triggersv1alpha1.MaintainerWorkItem) bool {
	if item == nil || item.Status.IssueObservation == nil || item.Status.IssueObservation.Number != item.Spec.IssueNumber {
		return false
	}
	for _, condition := range item.Status.Conditions {
		if condition.Type == triggersv1alpha1.ConditionMaintainerWorkItemObservationFresh {
			return condition.Status == metav1.ConditionTrue
		}
	}
	return false
}

func observedIssueState(item *triggersv1alpha1.MaintainerWorkItem) triggersv1alpha1.MaintainerIssueState {
	if item != nil && item.Status.IssueObservation != nil {
		return item.Status.IssueObservation.State
	}
	return triggersv1alpha1.MaintainerIssueStateOpen
}

func (r *GitHubRepositoryReconciler) applyNotActionableTriage(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, item *triggersv1alpha1.MaintainerWorkItem, triage *triggersv1alpha1.MaintainerTriageCommand, githubClient GitHubTriageClient) (string, triggersv1alpha1.MaintainerIssueState, error) {
	body := maintainerDecisionBody(repository, item, triage)
	marker := maintainerDecisionMarkerFor(repository, item)
	comment, err := findMaintainerDecisionComment(ctx, githubClient, repository.Spec.Owner, repository.Spec.Repo, int(item.Spec.IssueNumber), marker)
	if err != nil {
		return "", "", err
	}
	if comment == nil {
		comment, _, err = githubClient.CreateIssueComment(ctx, repository.Spec.Owner, repository.Spec.Repo, int(item.Spec.IssueNumber), &github.IssueComment{Body: new(body)})
		if err != nil {
			return "", "", fmt.Errorf("creating triage comment: %w", err)
		}
	} else if comment.GetBody() != body {
		comment, _, err = githubClient.EditIssueComment(ctx, repository.Spec.Owner, repository.Spec.Repo, comment.GetID(), &github.IssueComment{Body: new(body)})
		if err != nil {
			return "", "", fmt.Errorf("editing triage comment: %w", err)
		}
	}
	issue, _, err := githubClient.GetIssue(ctx, repository.Spec.Owner, repository.Spec.Repo, int(item.Spec.IssueNumber))
	if err != nil {
		return "", "", fmt.Errorf("getting issue for triage close: %w", err)
	}
	closedState := string(triggersv1alpha1.MaintainerIssueStateClosed)
	closeReason := string(*triage.CloseReason)
	if issue.GetState() != closedState || issue.GetStateReason() != closeReason {
		issue, _, err = githubClient.EditIssue(ctx, repository.Spec.Owner, repository.Spec.Repo, int(item.Spec.IssueNumber), &github.IssueRequest{State: new(closedState), StateReason: new(closeReason)})
		if err != nil {
			return "", "", fmt.Errorf("closing triaged issue: %w", err)
		}
	}
	state := triggersv1alpha1.MaintainerIssueState(issue.GetState())
	if state == "" {
		state = triggersv1alpha1.MaintainerIssueStateClosed
	}
	return comment.GetHTMLURL(), state, nil
}

func findMaintainerDecisionComment(ctx context.Context, githubClient GitHubTriageClient, owner, repo string, issueNumber int, marker string) (*github.IssueComment, error) {
	opts := &github.IssueListCommentsOptions{ListOptions: github.ListOptions{PerPage: 100}}
	for {
		comments, response, err := githubClient.ListIssueComments(ctx, owner, repo, issueNumber, opts)
		if err != nil {
			return nil, fmt.Errorf("listing triage comments: %w", err)
		}
		for _, comment := range comments {
			if strings.Contains(comment.GetBody(), marker) {
				return comment, nil
			}
		}
		if response == nil || response.NextPage == 0 {
			return nil, nil
		}
		opts.Page = response.NextPage
	}
}

func maintainerDecisionMarkerFor(repository *triggersv1alpha1.GitHubRepository, item *triggersv1alpha1.MaintainerWorkItem) string {
	sum := sha256.Sum256([]byte(string(repository.UID) + "\x00" + item.Namespace + "/" + item.Name))
	return "<!-- " + maintainerDecisionMarker + ":" + hex.EncodeToString(sum[:16]) + " -->"
}

func maintainerDecisionBody(repository *triggersv1alpha1.GitHubRepository, item *triggersv1alpha1.MaintainerWorkItem, triage *triggersv1alpha1.MaintainerTriageCommand) string {
	var b strings.Builder
	b.WriteString("Maintainer triage decision: Not actionable.\n\nEvidence: ")
	b.WriteString(triage.EvidenceSummary)
	if statement := strings.TrimSpace(triage.AcceptedScope.Statement); statement != "" {
		b.WriteString("\n\nScope: ")
		b.WriteString(statement)
	}
	if len(triage.AcceptedScope.AcceptanceCriteria) > 0 {
		b.WriteString("\n\nAcceptance criteria:")
		for _, criterion := range triage.AcceptedScope.AcceptanceCriteria {
			b.WriteString("\n- ")
			b.WriteString(criterion)
		}
	}
	b.WriteString("\n\nClose reason: ")
	b.WriteString(string(*triage.CloseReason))
	b.WriteString("\n\n")
	b.WriteString(maintainerDecisionMarkerFor(repository, item))
	return b.String()
}

package triggers

import (
	"context"
	"fmt"
	"slices"
	"sort"
	"strings"
	"time"

	"github.com/google/go-github/v68/github"
	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/types"
	"k8s.io/client-go/util/retry"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

const (
	maintainerPromoteSucceededAnnotation = "platform.gratefulagents.dev/promote-succeeded-requested"
	maintainerPromoteSucceededReason     = "platform.gratefulagents.dev/promote-succeeded-reason"
	maintainerGitHubIssueStateClosed     = "closed"
)

func effectiveMaintainerCutover(repository *triggersv1alpha1.GitHubRepository) triggersv1alpha1.MaintainerWorkItemCutoverMode {
	if repository != nil && repository.Spec.Maintainer != nil && repository.Spec.Maintainer.WorkItemCutover != "" {
		return repository.Spec.Maintainer.WorkItemCutover
	}
	return triggersv1alpha1.MaintainerWorkItemCutoverController
}

//nolint:gocyclo // Guard ordering is intentionally centralized around the irreversible merge boundary.
func (r *GitHubRepositoryReconciler) processMaintainerRequestMerge(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand, item *triggersv1alpha1.MaintainerWorkItem, githubClient maintainerGitHubDeliveryClient, pending bool) error {
	request := command.Spec.RequestMerge
	if effectiveMaintainerCutover(repository) != triggersv1alpha1.MaintainerWorkItemCutoverController {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "typed merge authority requires Controller work-item cutover after dual-read parity")
	}
	if githubClient == nil {
		return r.failMaintainerWorkItemCommand(ctx, command, item, "GitHub delivery client is unavailable")
	}
	if repository.Spec.Maintainer == nil || (!repository.Spec.Maintainer.AllowPullRequestMerge && !repository.Spec.Maintainer.FullControl) {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "repository does not grant maintainer merge permission")
	}
	fullControl := repository.Spec.Maintainer.FullControl
	// GitHub owner/repo identities are case-insensitive; observers (for example
	// the pull-request monitor) may record a lowercased form while the request
	// carries the GitHubRepository spec casing.
	if !strings.EqualFold(request.Repository, repository.Spec.Owner+"/"+repository.Spec.Repo) {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "request repository identity does not match GitHubRepository")
	}
	fresh := &triggersv1alpha1.MaintainerWorkItem{}
	if err := r.maintainerReader().Get(ctx, client.ObjectKeyFromObject(item), fresh); err != nil {
		return err
	}
	if fresh.UID != command.Spec.Preconditions.WorkItemUID || !fresh.DeletionTimestamp.IsZero() {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "target work-item UID changed or deletion is in progress")
	}
	if record := verifiedMaintainerMerge(fresh, request.Repository, request.PullRequestNumber); record != nil {
		if record.HeadSHA != request.ExpectedHeadSHA {
			return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "pull request was verified merged at a different head")
		}
		return r.completeMaintainerWorkItemCommand(ctx, command, fresh, "pull request merge was already verified", "", observedIssueState(fresh))
	}
	owner, repo, _ := strings.Cut(request.Repository, "/")
	mergeAttempted, err := r.maintainerMergeWasAttempted(ctx, command)
	if err != nil {
		return err
	}
	if mergeAttempted {
		pull, _, err := githubClient.GetPullRequest(ctx, owner, repo, int(request.PullRequestNumber), "")
		if err != nil {
			return r.failMaintainerWorkItemCommand(ctx, command, fresh, "merge verification GitHub read failed: "+err.Error())
		}
		if pull.Merged {
			return r.verifyAndRecordMaintainerMerge(ctx, repository, command, fresh, request, pull)
		}
		if pull.HeadSHA != request.ExpectedHeadSHA || !strings.EqualFold(pull.State, "open") {
			return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "attempted merge is definitively closed-unmerged or no longer at the expected head")
		}
		return r.failMaintainerWorkItemCommand(ctx, command, fresh, "a merge attempt is durable but GitHub has not reported MERGED with mergedAt; no automatic duplicate merge was submitted")
	}
	projection := projectedMaintainerPullRequest(fresh, request.Repository, request.PullRequestNumber)
	if projection == nil {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, fmt.Sprintf("pull request is not required by this work item (requested %s#%d; projected pull requests: %s)", request.Repository, request.PullRequestNumber, projectedMaintainerPullRequestIdentities(fresh)))
	}
	if projection.HeadSHA != request.ExpectedHeadSHA {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "expected head SHA does not match the current projection")
	}
	projectionReady := projectedPullRequestReady(projection, time.Now(), fullControl, fullControl)
	workItemReady := fresh.Status.Readiness != nil && fresh.Status.Readiness.ReadyToMerge
	if !workItemReady && fullControl {
		workItemReady = projectedPullRequestsReadyForPolicyVerification(fresh.Status.PullRequests, time.Now())
	}
	if !workItemReady || !projectionReady {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "work item and pull request are not merge candidates with fresh observations")
	}
	if pending {
		if err := r.setMaintainerWorkItemCommandAccepted(ctx, command, fresh); err != nil {
			return err
		}
	}
	pull, _, err := githubClient.GetPullRequest(ctx, owner, repo, int(request.PullRequestNumber), "")
	if err != nil {
		return r.failMaintainerWorkItemCommand(ctx, command, fresh, "pre-merge GitHub pull request read failed: "+err.Error())
	}
	if pull.Merged {
		return r.verifyAndRecordMaintainerMerge(ctx, repository, command, fresh, request, pull)
	}
	if !strings.EqualFold(pull.State, "open") || pull.Draft || !pull.MergeableKnown || !pull.Mergeable || pull.HeadSHA != request.ExpectedHeadSHA || strings.TrimSpace(pull.BaseRef) == "" {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "pre-merge GitHub read no longer satisfies open, non-draft, mergeable, expected-head/base gates")
	}
	policy, err := githubClient.GetMergePolicy(ctx, owner, repo, pull.BaseRef)
	if err != nil {
		// A transient read failure is retryable; only a successfully read but
		// unproven policy is a terminal rejection.
		return r.failMaintainerWorkItemCommand(ctx, command, fresh, "pre-merge GitHub merge policy read failed: "+err.Error())
	}
	if !policy.CanMerge {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "repository merge permission could not be proven")
	}
	// A bypass-capable actor (for example a repository owner's admin token)
	// only weakens the merge proof when branch protection or rulesets define
	// gates GitHub would otherwise enforce at merge time. With no required
	// reviews and no required checks configured there is nothing to bypass,
	// and the controller has already re-read every gate itself.
	if policy.ActorCanBypass && (policy.RequiredReviews || policy.RequiredChecks) {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "required review/check gates are configured but the merge actor can bypass them; a non-bypass merge cannot be proven")
	}
	if fullControl && policy.RequiredReviews {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "full control requires branch protection or rulesets without required approving reviews")
	}
	review, _, err := githubClient.GetReviewDecision(ctx, owner, repo, int(request.PullRequestNumber), request.ExpectedHeadSHA)
	if err != nil {
		return r.failMaintainerWorkItemCommand(ctx, command, fresh, "pre-merge GitHub review read failed: "+err.Error())
	}
	if review == triggersv1alpha1.PullRequestReviewDecisionChangesRequested {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "GitHub review decision has unresolved changes requested")
	}
	if !fullControl {
		if review == triggersv1alpha1.PullRequestReviewDecisionUnknown {
			return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "GitHub reported a blank review decision; required approval cannot be proven")
		}
		if review != triggersv1alpha1.PullRequestReviewDecisionApproved {
			return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "GitHub review decision is not approved")
		}
	}
	checks, _, err := githubClient.ListCheckRuns(ctx, owner, repo, request.ExpectedHeadSHA)
	if err != nil {
		return r.failMaintainerWorkItemCommand(ctx, command, fresh, "pre-merge GitHub check read failed: "+err.Error())
	}
	statuses, _, err := githubClient.GetCommitStatus(ctx, owner, repo, request.ExpectedHeadSHA)
	if err != nil {
		return r.failMaintainerWorkItemCommand(ctx, command, fresh, "pre-merge GitHub status read failed: "+err.Error())
	}
	if checks.HeadSHA != request.ExpectedHeadSHA || statuses.HeadSHA != request.ExpectedHeadSHA {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "GitHub checks or statuses are not bound to the expected head")
	}
	observedChecks := checks.Count + statuses.Count
	if policy.RequiredChecks && observedChecks == 0 {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "required checks are configured but none have appeared for the expected head")
	}
	if observedChecks == 0 && (checks.State != gitHubRollupNone || statuses.State != gitHubRollupNone) {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "zero-check merge requires explicit current-head none rollups")
	}
	if checks.State != gitHubRollupSuccess && checks.State != gitHubRollupNone || statuses.State != gitHubRollupSuccess && statuses.State != gitHubRollupNone {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "GitHub checks or commit statuses are pending or failing")
	}
	bound := &triggersv1alpha1.MaintainerWorkItem{}
	if err := r.maintainerReader().Get(ctx, client.ObjectKeyFromObject(fresh), bound); err != nil || bound.UID != command.Spec.Preconditions.WorkItemUID || !bound.DeletionTimestamp.IsZero() {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "target work-item UID changed before merge side effect")
	}
	if err := r.reserveMaintainerMergeAttempt(ctx, command); err != nil {
		return err
	}
	result, err := githubClient.MergePullRequest(ctx, owner, repo, int(request.PullRequestNumber), request.ExpectedHeadSHA, string(request.MergeMethod))
	if err != nil {
		return r.failMaintainerWorkItemCommand(ctx, command, fresh, "GitHub merge attempt outcome is ambiguous and will only be re-read, not resubmitted: "+err.Error())
	}
	post, _, err := githubClient.GetPullRequest(ctx, owner, repo, int(request.PullRequestNumber), "")
	if err != nil {
		return r.failMaintainerWorkItemCommand(ctx, command, fresh, "merge was requested but post-merge verification failed: "+err.Error())
	}
	if !post.Merged || post.MergedAt.IsZero() {
		message := "merge request was accepted but GitHub has not reported MERGED with mergedAt; work item remains active"
		if result != nil && strings.TrimSpace(result.GetMessage()) != "" {
			message += ": " + result.GetMessage()
		}
		return r.failMaintainerWorkItemCommand(ctx, command, fresh, message)
	}
	return r.verifyAndRecordMaintainerMerge(ctx, repository, command, fresh, request, post)
}

func (r *GitHubRepositoryReconciler) maintainerMergeWasAttempted(ctx context.Context, command *triggersv1alpha1.MaintainerWorkItemCommand) (bool, error) {
	fresh := &triggersv1alpha1.MaintainerWorkItemCommand{}
	if err := r.maintainerReader().Get(ctx, client.ObjectKeyFromObject(command), fresh); err != nil {
		return false, err
	}
	return fresh.Status.Result != nil && fresh.Status.Result.MergeAttemptedAt != nil, nil
}

func (r *GitHubRepositoryReconciler) reserveMaintainerMergeAttempt(ctx context.Context, command *triggersv1alpha1.MaintainerWorkItemCommand) error {
	now := metav1.Now()
	return retryMaintainerWorkItemCommandStatusUpdate(ctx, r.Client, client.ObjectKeyFromObject(command), func(fresh *triggersv1alpha1.MaintainerWorkItemCommand) {
		if fresh.Status.Result == nil {
			fresh.Status.Result = &triggersv1alpha1.MaintainerWorkItemCommandResult{}
		}
		if fresh.Status.Result.MergeAttemptedAt == nil {
			fresh.Status.Result.MergeAttemptedAt = &now
		}
	})
}

func projectedMaintainerPullRequest(item *triggersv1alpha1.MaintainerWorkItem, repository string, number int32) *triggersv1alpha1.MaintainerWorkItemPullRequestProjection {
	for i := range item.Status.PullRequests {
		// GitHub repository identities are case-insensitive: projections built
		// from pull-request monitors store a lowercased owner/repo while merge
		// requests carry the GitHubRepository spec casing.
		if strings.EqualFold(item.Status.PullRequests[i].Repository, repository) && item.Status.PullRequests[i].Number == number {
			return &item.Status.PullRequests[i]
		}
	}
	return nil
}

func projectedMaintainerPullRequestIdentities(item *triggersv1alpha1.MaintainerWorkItem) string {
	if len(item.Status.PullRequests) == 0 {
		return "none"
	}
	identities := make([]string, 0, len(item.Status.PullRequests))
	for i := range item.Status.PullRequests {
		identities = append(identities, fmt.Sprintf("%s#%d", item.Status.PullRequests[i].Repository, item.Status.PullRequests[i].Number))
	}
	return strings.Join(identities, ", ")
}

func projectedPullRequestsReadyForPolicyVerification(pullRequests []triggersv1alpha1.MaintainerWorkItemPullRequestProjection, now time.Time) bool {
	candidate := false
	for i := range pullRequests {
		if pullRequests[i].State == triggersv1alpha1.MaintainerWorkItemPullRequestStateMerged {
			continue
		}
		candidate = true
		if !projectedPullRequestReady(&pullRequests[i], now, true, true) {
			return false
		}
	}
	return candidate
}

func projectedPullRequestReady(pr *triggersv1alpha1.MaintainerWorkItemPullRequestProjection, now time.Time, fullControl, allowNoChecksCandidate bool) bool {
	approvalMissing := !fullControl && pr != nil && !strings.EqualFold(pr.ReviewDecision, string(triggersv1alpha1.PullRequestReviewDecisionApproved))
	changesRequested := pr != nil && strings.EqualFold(pr.ReviewDecision, string(triggersv1alpha1.PullRequestReviewDecisionChangesRequested))
	checksSatisfied := pr != nil && (pr.CheckState == triggersv1alpha1.MaintainerWorkItemCheckStatePassing || allowNoChecksCandidate && pr.CheckState == triggersv1alpha1.MaintainerWorkItemCheckStateNone)
	if pr == nil || !pr.Fresh || pr.ObservationError != "" || pr.State != triggersv1alpha1.MaintainerWorkItemPullRequestStateOpen || pr.Draft || pr.Mergeable == nil || !*pr.Mergeable || approvalMissing || changesRequested || !checksSatisfied {
		return false
	}
	for _, observed := range []*metav1.Time{pr.HeadObservedAt, pr.ReviewObservedAt, pr.ChecksObservedAt, pr.StatusesObservedAt} {
		if observed == nil || now.Sub(observed.Time) > maintainerProjectionFreshness {
			return false
		}
	}
	return true
}

func verifiedMaintainerMerge(item *triggersv1alpha1.MaintainerWorkItem, repository string, number int32) *triggersv1alpha1.MaintainerVerifiedPullRequestMerge {
	for i := range item.Status.VerifiedMerges {
		if strings.EqualFold(item.Status.VerifiedMerges[i].Repository, repository) && item.Status.VerifiedMerges[i].PullRequestNumber == number {
			return &item.Status.VerifiedMerges[i]
		}
	}
	return nil
}

func (r *GitHubRepositoryReconciler) verifyAndRecordMaintainerMerge(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand, item *triggersv1alpha1.MaintainerWorkItem, request *triggersv1alpha1.MaintainerRequestMergeCommand, pull *polledPullRequest) error {
	if pull == nil || !pull.Merged || pull.MergedAt.IsZero() || pull.HeadSHA != request.ExpectedHeadSHA {
		return r.failMaintainerWorkItemCommand(ctx, command, item, "post-merge GitHub verification did not confirm MERGED, mergedAt, and the expected head")
	}
	mergedAt := metav1.NewTime(pull.MergedAt)
	firstRecording := false
	err := r.retryMaintainerWorkItemStatusMutation(ctx, client.ObjectKeyFromObject(item), func(fresh *triggersv1alpha1.MaintainerWorkItem) (bool, error) {
		firstRecording = false
		if existing := verifiedMaintainerMerge(fresh, request.Repository, request.PullRequestNumber); existing != nil {
			if existing.HeadSHA != request.ExpectedHeadSHA {
				return false, fmt.Errorf("verified merge head changed")
			}
			return false, nil
		}
		firstRecording = true
		fresh.Status.VerifiedMerges = append(fresh.Status.VerifiedMerges, triggersv1alpha1.MaintainerVerifiedPullRequestMerge{Repository: request.Repository, PullRequestNumber: request.PullRequestNumber, HeadSHA: request.ExpectedHeadSHA, MergedAt: mergedAt, CommandRef: corev1.LocalObjectReference{Name: command.Name}})
		sort.Slice(fresh.Status.VerifiedMerges, func(i, j int) bool {
			if fresh.Status.VerifiedMerges[i].Repository == fresh.Status.VerifiedMerges[j].Repository {
				return fresh.Status.VerifiedMerges[i].PullRequestNumber < fresh.Status.VerifiedMerges[j].PullRequestNumber
			}
			return fresh.Status.VerifiedMerges[i].Repository < fresh.Status.VerifiedMerges[j].Repository
		})
		fresh.Status.ProjectionSequence++
		return true, nil
	})
	if err != nil {
		return err
	}
	if firstRecording {
		r.notifyOpenFleetPullRequestsAfterMerge(ctx, repository, item, request.Repository, request.PullRequestNumber, request.ExpectedHeadSHA, pull.BaseRef)
	}
	return r.completeMaintainerWorkItemCommand(ctx, command, item, "GitHub confirmed pull request MERGED at the expected head", "", observedIssueState(item))
}

//nolint:gocyclo // Finalization keeps structural gates and ordered idempotent side effects in one state machine.
func (r *GitHubRepositoryReconciler) processMaintainerFinalizeWorkItem(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand, item *triggersv1alpha1.MaintainerWorkItem, githubClient GitHubTriageClient, deliveryClient maintainerGitHubDeliveryClient, pending bool) error {
	request := command.Spec.Finalize
	if effectiveMaintainerCutover(repository) != triggersv1alpha1.MaintainerWorkItemCutoverController {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "typed finalization authority requires Controller work-item cutover after dual-read parity")
	}
	fresh := &triggersv1alpha1.MaintainerWorkItem{}
	if err := r.maintainerReader().Get(ctx, client.ObjectKeyFromObject(item), fresh); err != nil {
		return err
	}
	if fresh.UID != command.Spec.Preconditions.WorkItemUID || !fresh.DeletionTimestamp.IsZero() {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "target work-item UID changed or deletion is in progress")
	}
	if fresh.Status.DeliveryAttestation != nil && fresh.Status.DeliveryAttestation.CompletedAt != nil {
		if fresh.Status.DeliveryAttestation.FinalizedByCommand.Name != command.Name {
			return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "work item was finalized by another command")
		}
		return r.completeMaintainerWorkItemCommand(ctx, command, fresh, "work item finalization was already verified", "", triggersv1alpha1.MaintainerIssueStateClosed)
	}
	unmet, err := r.maintainerFinalizationUnmet(ctx, fresh, request)
	if err != nil {
		return r.failMaintainerWorkItemCommand(ctx, command, fresh, "finalization predicate read failed: "+err.Error())
	}
	if len(unmet) > 0 {
		return r.rejectMaintainerWorkItemCommand(ctx, repository, command, "finalization predicates are not met: "+strings.Join(unmet, "; "))
	}
	if githubClient == nil || deliveryClient == nil {
		return r.failMaintainerWorkItemCommand(ctx, command, fresh, "GitHub clients are unavailable for finalization verification")
	}
	// Re-read every required PR so a stale/closed-unmerged projection cannot finalize.
	for i := range fresh.Status.PullRequests {
		pr := &fresh.Status.PullRequests[i]
		owner, repo, _ := strings.Cut(pr.Repository, "/")
		live, _, err := deliveryClient.GetPullRequest(ctx, owner, repo, int(pr.Number), "")
		if err != nil {
			return r.failMaintainerWorkItemCommand(ctx, command, fresh, "finalization pull request verification failed: "+err.Error())
		}
		if live == nil || !live.Merged || live.MergedAt.IsZero() || live.HeadSHA != pr.HeadSHA {
			return r.rejectMaintainerWorkItemCommand(ctx, repository, command, fmt.Sprintf("%s#%d is not confirmed merged at projected head", pr.Repository, pr.Number))
		}
	}
	if pending {
		if err := r.setMaintainerWorkItemCommandAccepted(ctx, command, fresh); err != nil {
			return err
		}
	}
	if err := r.ensureMaintainerDeliveryAttestation(ctx, command, fresh, request); err != nil {
		return err
	}
	if err := r.requestMaintainerRunSuccess(ctx, fresh, request); err != nil {
		return r.failMaintainerWorkItemCommand(ctx, command, fresh, "requesting implementer run success: "+err.Error())
	}
	if err := r.recordMaintainerRunSuccessRequested(ctx, fresh, request.ImplementerRunNames); err != nil {
		return err
	}
	issue, _, err := githubClient.GetIssue(ctx, repository.Spec.Owner, repository.Spec.Repo, int(fresh.Spec.IssueNumber))
	if err != nil {
		return r.failMaintainerWorkItemCommand(ctx, command, fresh, "reading issue before finalization: "+err.Error())
	}
	closedState, completedReason := maintainerGitHubIssueStateClosed, string(triggersv1alpha1.MaintainerWorkItemCloseReasonCompleted)
	if !strings.EqualFold(issue.GetState(), closedState) || !strings.EqualFold(issue.GetStateReason(), completedReason) {
		if _, _, err := githubClient.EditIssue(ctx, repository.Spec.Owner, repository.Spec.Repo, int(fresh.Spec.IssueNumber), &github.IssueRequest{State: &closedState, StateReason: &completedReason}); err != nil {
			return r.failMaintainerWorkItemCommand(ctx, command, fresh, "closing issue after run-success requests: "+err.Error())
		}
	}
	issue, _, err = githubClient.GetIssue(ctx, repository.Spec.Owner, repository.Spec.Repo, int(fresh.Spec.IssueNumber))
	if err != nil || !strings.EqualFold(issue.GetState(), closedState) || !strings.EqualFold(issue.GetStateReason(), completedReason) {
		message := "post-close verification did not confirm closed/completed"
		if err != nil {
			message += ": " + err.Error()
		}
		return r.failMaintainerWorkItemCommand(ctx, command, fresh, message)
	}
	if err := r.completeMaintainerDeliveryAttestation(ctx, fresh); err != nil {
		return err
	}
	return r.completeMaintainerWorkItemCommand(ctx, command, fresh, "all structural predicates, authenticated delivery attestation, run-success requests, and issue closure were verified", "", triggersv1alpha1.MaintainerIssueStateClosed)
}

//nolint:gocyclo // Each fail-closed predicate is reported independently to preserve actionable audit output.
func (r *GitHubRepositoryReconciler) maintainerFinalizationUnmet(ctx context.Context, item *triggersv1alpha1.MaintainerWorkItem, request *triggersv1alpha1.MaintainerFinalizeWorkItemCommand) ([]string, error) {
	var unmet []string
	if item.Spec.AcceptedScope == nil || triggersv1alpha1.MaintainerAcceptedScopeHash(item.Spec.AcceptedScope) != request.AcceptedScopeHash {
		unmet = append(unmet, "accepted scope hash mismatch")
	}
	if item.Status.PendingDecision != nil {
		unmet = append(unmet, "pending decision exists")
	}
	if len(item.Spec.Children) != len(item.Status.Children) || len(item.Spec.Dependencies) != len(item.Status.Dependencies) {
		unmet = append(unmet, "child or dependency projection set is incomplete")
	}
	childProjections := map[string]types.UID{}
	for _, projection := range item.Status.Children {
		childProjections[projection.Name] = projection.UID
	}
	for _, ref := range item.Spec.Children {
		if childProjections[ref.Name] != ref.UID {
			unmet = append(unmet, "child projection "+ref.Name+" does not match its bound UID")
		}
	}
	dependencyProjections := map[string]types.UID{}
	for _, projection := range item.Status.Dependencies {
		dependencyProjections[projection.Name] = projection.UID
	}
	for _, ref := range item.Spec.Dependencies {
		if dependencyProjections[ref.Name] != ref.UID {
			unmet = append(unmet, "dependency projection "+ref.Name+" does not match its bound UID")
		}
	}
	for _, ref := range append(append([]triggersv1alpha1.MaintainerWorkItemReference(nil), item.Spec.Children...), item.Spec.Dependencies...) {
		if ref.UID == "" {
			unmet = append(unmet, ref.Name+" has no immutable UID binding")
			continue
		}
		target := &triggersv1alpha1.MaintainerWorkItem{}
		if err := r.maintainerReader().Get(ctx, client.ObjectKey{Namespace: item.Namespace, Name: ref.Name}, target); err != nil {
			return unmet, err
		}
		if target.UID != ref.UID || target.Status.Phase != triggersv1alpha1.MaintainerWorkItemPhaseDelivered || target.Status.DeliveryAttestation == nil || target.Status.DeliveryAttestation.CompletedAt == nil {
			unmet = append(unmet, ref.Name+" is not finalized at the bound UID")
		}
	}
	merged := 0
	for _, pr := range item.Status.PullRequests {
		// A closed, unmerged pull request was superseded; only open or malformed
		// projections are outstanding delivery obligations.
		if pr.State == triggersv1alpha1.MaintainerWorkItemPullRequestStateClosed {
			continue
		}
		if pr.State != triggersv1alpha1.MaintainerWorkItemPullRequestStateMerged || pr.MergedAt == nil || pr.Repository == "" || pr.Number < 1 || pr.HeadSHA == "" {
			unmet = append(unmet, fmt.Sprintf("%s#%d is not merged", pr.Repository, pr.Number))
			continue
		}
		merged++
	}
	if merged == 0 && len(item.Spec.Children) == 0 {
		unmet = append(unmet, "no merged pull request or finalized children")
	}
	projectedRuns := map[string]triggersv1alpha1.MaintainerWorkItemAgentRunProjection{}
	for _, run := range item.Status.AgentRuns {
		if run.Role == triggersv1alpha1.MaintainerWorkItemAgentRunRoleImplementer {
			projectedRuns[run.Name] = run
		}
	}
	requested := append([]string(nil), request.ImplementerRunNames...)
	sort.Strings(requested)
	actual := make([]string, 0, len(projectedRuns))
	for name := range projectedRuns {
		actual = append(actual, name)
	}
	sort.Strings(actual)
	if !slices.Equal(requested, actual) {
		unmet = append(unmet, "implementer run names do not exactly match the projection")
	}
	for name, run := range projectedRuns {
		if run.UID == "" {
			unmet = append(unmet, "implementer "+name+" has no immutable UID projection")
		}
		if run.Phase == string(platformv1alpha1.AgentRunPhaseFailed) || run.Phase == string(platformv1alpha1.AgentRunPhaseCancelled) {
			unmet = append(unmet, "implementer "+name+" is in invalid phase "+run.Phase)
		}
	}
	return unmet, nil
}

func (r *GitHubRepositoryReconciler) ensureMaintainerDeliveryAttestation(ctx context.Context, command *triggersv1alpha1.MaintainerWorkItemCommand, item *triggersv1alpha1.MaintainerWorkItem, request *triggersv1alpha1.MaintainerFinalizeWorkItemCommand) error {
	return r.retryMaintainerWorkItemStatusMutation(ctx, client.ObjectKeyFromObject(item), func(fresh *triggersv1alpha1.MaintainerWorkItem) (bool, error) {
		if fresh.Generation != item.Generation || fresh.Status.ProjectionSequence != item.Status.ProjectionSequence {
			return false, fmt.Errorf("work-item projection changed after finalization predicates; re-evaluate before attesting")
		}
		if fresh.Status.DeliveryAttestation != nil {
			if fresh.Status.DeliveryAttestation.FinalizedByCommand.Name != command.Name || fresh.Status.DeliveryAttestation.AcceptedScopeHash != request.AcceptedScopeHash {
				return false, rejectMaintainerCommand("a different delivery attestation already exists")
			}
			return false, nil
		}
		attestation := &triggersv1alpha1.MaintainerDeliveryAttestation{AcceptedScopeHash: request.AcceptedScopeHash, DeliverySummary: request.DeliverySummary, DeliveryEvidence: request.DeliveryEvidence, FinalizedByCommand: corev1.LocalObjectReference{Name: command.Name}}
		if command.Spec.Issuer != nil {
			issuer := *command.Spec.Issuer
			attestation.Issuer = &issuer
		} else if command.Spec.HumanIssuer != nil {
			humanIssuer := *command.Spec.HumanIssuer
			attestation.HumanIssuer = &humanIssuer
		}
		fresh.Status.DeliveryAttestation = attestation
		fresh.Status.ProjectionSequence++
		return true, nil
	})
}

func (r *GitHubRepositoryReconciler) requestMaintainerRunSuccess(ctx context.Context, item *triggersv1alpha1.MaintainerWorkItem, request *triggersv1alpha1.MaintainerFinalizeWorkItemCommand) error {
	projectedUIDs := map[string]types.UID{}
	for _, projected := range item.Status.AgentRuns {
		if projected.Role == triggersv1alpha1.MaintainerWorkItemAgentRunRoleImplementer {
			projectedUIDs[projected.Name] = projected.UID
		}
	}
	for _, name := range request.ImplementerRunNames {
		key := client.ObjectKey{Namespace: item.Namespace, Name: name}
		if err := retry.RetryOnConflict(retry.DefaultRetry, func() error {
			run := &platformv1alpha1.AgentRun{}
			if err := r.maintainerReader().Get(ctx, key, run); err != nil {
				return err
			}
			if projectedUIDs[name] == "" || run.UID != projectedUIDs[name] || run.Labels[triggersv1alpha1.MaintainerWorkItemNameLabelKey] != item.Name || run.Labels[triggersv1alpha1.MaintainerWorkItemUIDLabelKey] != string(item.UID) || run.Labels[triggersv1alpha1.PRLoopRoleLabelKey] == triggersv1alpha1.PRLoopRoleReviewerValue {
				return fmt.Errorf("AgentRun %s is not the immutable projected implementer", name)
			}
			if run.Status.Phase == platformv1alpha1.AgentRunPhaseSucceeded {
				return nil
			}
			if run.Status.Phase == platformv1alpha1.AgentRunPhaseFailed || run.Status.Phase == platformv1alpha1.AgentRunPhaseCancelled {
				return fmt.Errorf("AgentRun %s is terminal in phase %s", name, run.Status.Phase)
			}
			if run.Annotations[maintainerPromoteSucceededAnnotation] != "" && run.Annotations[maintainerPromoteSucceededReason] == request.DeliverySummary {
				return nil
			}
			patch := client.MergeFromWithOptions(run.DeepCopy(), client.MergeFromWithOptimisticLock{})
			if run.Annotations == nil {
				run.Annotations = map[string]string{}
			}
			run.Annotations[maintainerPromoteSucceededAnnotation] = time.Now().UTC().Format(time.RFC3339)
			run.Annotations[maintainerPromoteSucceededReason] = request.DeliverySummary
			return r.Patch(ctx, run, patch)
		}); err != nil {
			return err
		}
	}
	return nil
}

func (r *GitHubRepositoryReconciler) recordMaintainerRunSuccessRequested(ctx context.Context, item *triggersv1alpha1.MaintainerWorkItem, names []string) error {
	return r.retryMaintainerWorkItemStatusMutation(ctx, client.ObjectKeyFromObject(item), func(fresh *triggersv1alpha1.MaintainerWorkItem) (bool, error) {
		attestation := fresh.Status.DeliveryAttestation
		if attestation == nil || attestation.RunSuccessRequestedAt != nil {
			return false, nil
		}
		now := metav1.Now()
		attestation.RunSuccessRequestedAt = &now
		projectedUIDs := map[string]types.UID{}
		for _, projected := range fresh.Status.AgentRuns {
			if projected.Role == triggersv1alpha1.MaintainerWorkItemAgentRunRoleImplementer {
				projectedUIDs[projected.Name] = projected.UID
			}
		}
		for _, name := range names {
			attestation.RunSuccessRequestedRefs = append(attestation.RunSuccessRequestedRefs, triggersv1alpha1.MaintainerWorkItemReference{Name: name, UID: projectedUIDs[name]})
		}
		fresh.Status.ProjectionSequence++
		return true, nil
	})
}

func (r *GitHubRepositoryReconciler) completeMaintainerDeliveryAttestation(ctx context.Context, item *triggersv1alpha1.MaintainerWorkItem) error {
	return r.retryMaintainerWorkItemStatusMutation(ctx, client.ObjectKeyFromObject(item), func(fresh *triggersv1alpha1.MaintainerWorkItem) (bool, error) {
		attestation := fresh.Status.DeliveryAttestation
		if attestation == nil || attestation.CompletedAt != nil {
			return false, nil
		}
		now := metav1.Now()
		attestation.IssueClosedAt, attestation.CompletedAt = &now, &now
		if fresh.Status.IssueObservation != nil {
			fresh.Status.IssueObservation.State = triggersv1alpha1.MaintainerIssueStateClosed
			fresh.Status.IssueObservation.ObservedAt = now
		}
		fresh.Status.Phase = triggersv1alpha1.MaintainerWorkItemPhaseDelivered
		fresh.Status.ProjectionSequence++
		return true, nil
	})
}

package triggers

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"strings"

	"github.com/google/go-github/v68/github"
	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
)

// maintainerGitHubDeliveryClient is the narrow, replaceable GitHub surface used
// immediately around irreversible maintainer delivery commands. It deliberately
// re-reads every gate instead of trusting an asynchronous projection.
type maintainerMergePolicy struct {
	RequiredReviews bool
	RequiredChecks  bool
	CanMerge        bool
	ActorCanBypass  bool
}

type maintainerGitHubDeliveryClient interface {
	GetPullRequest(context.Context, string, string, int, string) (*polledPullRequest, gitHubPollResponse, error)
	GetReviewDecision(context.Context, string, string, int, string) (triggersv1alpha1.PullRequestReviewDecision, gitHubPollResponse, error)
	ListCheckRuns(context.Context, string, string, string) (polledHeadRollup, gitHubPollResponse, error)
	GetCommitStatus(context.Context, string, string, string) (polledHeadRollup, gitHubPollResponse, error)
	GetMergePolicy(context.Context, string, string, string) (maintainerMergePolicy, error)
	MergePullRequest(context.Context, string, string, int, string, string) (*github.PullRequestMergeResult, error)
}

type goGitHubMaintainerDeliveryClient struct {
	poller       pullRequestGitHubPoller
	pulls        *github.PullRequestsService
	repositories *github.RepositoriesService
}

func newMaintainerGitHubDeliveryClient(client *github.Client) maintainerGitHubDeliveryClient {
	return &goGitHubMaintainerDeliveryClient{poller: newPullRequestGitHubPoller(client), pulls: client.PullRequests, repositories: client.Repositories}
}

func (c *goGitHubMaintainerDeliveryClient) GetPullRequest(ctx context.Context, owner, repo string, number int, etag string) (*polledPullRequest, gitHubPollResponse, error) {
	return c.poller.GetPullRequest(ctx, owner, repo, number, etag)
}

func (c *goGitHubMaintainerDeliveryClient) GetReviewDecision(ctx context.Context, owner, repo string, number int, expectedHead string) (triggersv1alpha1.PullRequestReviewDecision, gitHubPollResponse, error) {
	return c.poller.GetReviewDecision(ctx, owner, repo, number, expectedHead)
}

func (c *goGitHubMaintainerDeliveryClient) ListCheckRuns(ctx context.Context, owner, repo, head string) (polledHeadRollup, gitHubPollResponse, error) {
	return c.poller.ListCheckRuns(ctx, owner, repo, head)
}

func (c *goGitHubMaintainerDeliveryClient) GetCommitStatus(ctx context.Context, owner, repo, head string) (polledHeadRollup, gitHubPollResponse, error) {
	return c.poller.GetCommitStatus(ctx, owner, repo, head)
}

func (c *goGitHubMaintainerDeliveryClient) GetMergePolicy(ctx context.Context, owner, repo, branch string) (maintainerMergePolicy, error) {
	repository, _, err := c.repositories.Get(ctx, owner, repo)
	if err != nil {
		return maintainerMergePolicy{}, err
	}
	protection, protectionResponse, err := c.repositories.GetBranchProtection(ctx, owner, repo, branch)
	if err != nil && isGitHubBranchProtectionUnavailable(err, protectionResponse) {
		// GitHub returns 403 for private repositories on plans that do not offer
		// branch protection. In that case there is no server policy to inspect;
		// the delivery path still verifies the current PR approval and checks.
		permissions := repository.GetPermissions()
		return maintainerMergePolicy{CanMerge: permissions["push"] || permissions["maintain"] || permissions["admin"]}, nil
	}
	if err != nil && (protectionResponse == nil || protectionResponse.StatusCode != http.StatusNotFound) {
		return maintainerMergePolicy{}, err
	}
	applicableRules, _, err := c.repositories.GetRulesForBranch(ctx, owner, repo, branch)
	if err != nil {
		return maintainerMergePolicy{}, err
	}
	rulesets, _, err := c.repositories.GetAllRulesets(ctx, owner, repo, true)
	if err != nil {
		return maintainerMergePolicy{}, err
	}
	var reviews *github.PullRequestReviewsEnforcement
	var checks *github.RequiredStatusChecks
	if protection != nil {
		reviews = protection.RequiredPullRequestReviews
		checks = protection.RequiredStatusChecks
	}
	rulesetReviews, rulesetChecks, err := maintainerRulesetMergeRequirements(applicableRules)
	if err != nil {
		return maintainerMergePolicy{}, err
	}
	actorCanBypass := repository.GetPermissions()["admin"]
	if reviews != nil && reviews.BypassPullRequestAllowances != nil {
		allowances := reviews.BypassPullRequestAllowances
		actorCanBypass = actorCanBypass || len(allowances.Users) > 0 || len(allowances.Teams) > 0 || len(allowances.Apps) > 0
	}
	for _, ruleset := range rulesets {
		if ruleset != nil && strings.EqualFold(ruleset.Enforcement, "active") && len(ruleset.BypassActors) > 0 {
			// Conservatively reject any active bypass allowance. This avoids
			// assuming an actor identity or custom role is non-bypass.
			actorCanBypass = true
		}
	}
	permissions := repository.GetPermissions()
	return maintainerMergePolicy{
		RequiredReviews: rulesetReviews || reviews != nil && reviews.RequiredApprovingReviewCount > 0,
		RequiredChecks:  rulesetChecks || checks != nil && len(checks.GetContexts())+len(checks.GetChecks()) > 0,
		CanMerge:        permissions["push"] || permissions["maintain"] || permissions["admin"],
		ActorCanBypass:  actorCanBypass,
	}, nil
}

func isGitHubBranchProtectionUnavailable(err error, response *github.Response) bool {
	if response == nil || response.StatusCode != http.StatusForbidden {
		return false
	}
	var responseError *github.ErrorResponse
	return errors.As(err, &responseError) && strings.Contains(strings.ToLower(responseError.Message), "upgrade to github pro or make this repository public")
}

func maintainerRulesetMergeRequirements(rules []*github.RepositoryRule) (requiredReviews, requiredChecks bool, err error) {
	for _, rule := range rules {
		if rule == nil {
			continue
		}
		switch rule.Type {
		case "pull_request":
			if rule.Parameters == nil {
				return false, false, fmt.Errorf("applicable pull-request ruleset has no parameters")
			}
			var parameters github.PullRequestRuleParameters
			if err := json.Unmarshal(*rule.Parameters, &parameters); err != nil {
				return false, false, fmt.Errorf("decoding applicable pull-request ruleset: %w", err)
			}
			requiredReviews = requiredReviews || parameters.RequiredApprovingReviewCount > 0
		case "required_status_checks":
			if rule.Parameters == nil {
				return false, false, fmt.Errorf("applicable required-checks ruleset has no parameters")
			}
			var parameters github.RequiredStatusChecksRuleParameters
			if err := json.Unmarshal(*rule.Parameters, &parameters); err != nil {
				return false, false, fmt.Errorf("decoding applicable required-checks ruleset: %w", err)
			}
			requiredChecks = requiredChecks || len(parameters.RequiredStatusChecks) > 0
		}
	}
	return requiredReviews, requiredChecks, nil
}

func (c *goGitHubMaintainerDeliveryClient) MergePullRequest(ctx context.Context, owner, repo string, number int, head, method string) (*github.PullRequestMergeResult, error) {
	result, _, err := c.pulls.Merge(ctx, owner, repo, number, "", &github.PullRequestOptions{SHA: head, MergeMethod: method})
	return result, err
}

package triggers

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"slices"
	"strconv"
	"strings"
	"time"

	"github.com/google/go-github/v68/github"
	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
	"github.com/gratefulagents/gratefulagents/internal/orchestration"
	corev1 "k8s.io/api/core/v1"
	"k8s.io/apimachinery/pkg/api/equality"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/client-go/util/retry"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

func (r *GitHubRepositoryReconciler) processMaintainerExecutionCommand(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand, item *triggersv1alpha1.MaintainerWorkItem, githubClient GitHubTriageClient, deliveryClient maintainerGitHubDeliveryClient, pending bool) error {
	switch command.Spec.Type {
	case triggersv1alpha1.MaintainerWorkItemCommandTypeRequestMerge:
		return r.processMaintainerRequestMerge(ctx, repository, command, item, deliveryClient, pending)
	case triggersv1alpha1.MaintainerWorkItemCommandTypeFinalizeWorkItem:
		return r.processMaintainerFinalizeWorkItem(ctx, repository, command, item, githubClient, deliveryClient, pending)
	}
	if pending {
		if command.Spec.Type == triggersv1alpha1.MaintainerWorkItemCommandTypeBreakdownIssue {
			if err := r.acquireMaintainerCommandLock(ctx, repository, command.Name); err != nil {
				return err
			}
			defer func() { _ = r.releaseMaintainerCommandLock(context.Background(), repository, command.Name) }()
		}
		if err := r.applyMaintainerExecutionIntent(ctx, repository, command, item); err != nil {
			var rejected maintainerCommandRejectedError
			if asMaintainerCommandRejected(err, &rejected) {
				return r.rejectMaintainerWorkItemCommand(ctx, repository, command, rejected.message)
			}
			return err
		}
		if err := r.setMaintainerWorkItemCommandAccepted(ctx, command, item); err != nil {
			return err
		}
	}
	if command.Spec.Type != triggersv1alpha1.MaintainerWorkItemCommandTypeDispatchWorkItem {
		return r.completeMaintainerWorkItemCommand(ctx, command, item, "work-item command applied", "", observedIssueState(item))
	}
	active, err := r.maintainerDispatchReservationActive(ctx, repository, command, item)
	if err != nil {
		return err
	}
	if !active {
		return r.failAndReleaseMaintainerDispatch(ctx, repository, command, item, "dispatch reservation is no longer active")
	}
	if githubClient == nil {
		return fmt.Errorf("GitHub client unavailable after dispatch capacity reservation")
	}
	issue, _, err := githubClient.GetIssue(ctx, repository.Spec.Owner, repository.Spec.Repo, int(item.Spec.IssueNumber))
	if err != nil {
		if isDefiniteGitHubDispatchError(err) {
			return r.failAndReleaseMaintainerDispatch(ctx, repository, command, item, "getting issue after dispatch reservation: "+err.Error())
		}
		return fmt.Errorf("getting issue after dispatch reservation: %w", err)
	}
	if !strings.EqualFold(issue.GetState(), "open") {
		return r.failAndReleaseMaintainerDispatch(ctx, repository, command, item, fmt.Sprintf("issue #%d is no longer open after dispatch reservation", item.Spec.IssueNumber))
	}
	if err := applyMaintainerDispatchLabel(ctx, repository, command, item, githubClient); err != nil {
		if isDefiniteGitHubDispatchError(err) {
			return r.failAndReleaseMaintainerDispatch(ctx, repository, command, item, "applying trigger label after dispatch reservation: "+err.Error())
		}
		return fmt.Errorf("applying trigger label after dispatch reservation: %w", err)
	}
	if err := r.recreateMaintainerDispatchRun(ctx, repository, command, item, issue); err != nil {
		var rejected maintainerCommandRejectedError
		if asMaintainerCommandRejected(err, &rejected) {
			return r.failAndReleaseMaintainerDispatch(ctx, repository, command, item, rejected.message)
		}
		return err
	}
	return r.completeMaintainerWorkItemCommand(ctx, command, item, "dispatch capacity reserved and trigger label applied", "", observedIssueState(item))
}

func applyMaintainerDispatchLabel(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand, item *triggersv1alpha1.MaintainerWorkItem, githubClient GitHubTriageClient) error {
	owner, repo, mode := repository.Spec.Owner, repository.Spec.Repo, command.Spec.Dispatch.Mode
	if err := ensureMaintainerGitHubLabel(ctx, githubClient, owner, repo, mode); err != nil {
		return fmt.Errorf("ensuring trigger label: %w", err)
	}
	if _, _, err := githubClient.AddLabelsToIssue(ctx, owner, repo, int(item.Spec.IssueNumber), []string{mode}); err != nil {
		return err
	}
	return nil
}

func ensureMaintainerGitHubLabel(ctx context.Context, githubClient GitHubTriageClient, owner, repo, name string) error {
	if _, response, err := githubClient.GetLabel(ctx, owner, repo, name); err == nil {
		return nil
	} else if response == nil || response.StatusCode != http.StatusNotFound {
		return fmt.Errorf("get repository label %q: %w", name, err)
	}

	label := &github.Label{Name: github.Ptr(name), Color: github.Ptr("BFD4F2")}
	if _, _, err := githubClient.CreateLabel(ctx, owner, repo, label); err == nil {
		return nil
	} else {
		// A concurrent creator may win between the lookup and creation.
		if _, _, lookupErr := githubClient.GetLabel(ctx, owner, repo, name); lookupErr == nil {
			return nil
		}
		return fmt.Errorf("create repository label %q: %w", name, err)
	}
}

//nolint:gocyclo // Typed command variants intentionally share one authorization and idempotency entrypoint.
func (r *GitHubRepositoryReconciler) applyMaintainerExecutionIntent(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand, item *triggersv1alpha1.MaintainerWorkItem) error {
	switch command.Spec.Type {
	case triggersv1alpha1.MaintainerWorkItemCommandTypeBreakdownIssue:
		return retry.RetryOnConflict(retry.DefaultRetry, func() error {
			fresh := &triggersv1alpha1.MaintainerWorkItem{}
			if err := r.maintainerReader().Get(ctx, client.ObjectKeyFromObject(item), fresh); err != nil {
				return err
			}
			if equality.Semantic.DeepEqual(fresh.Spec.Children, command.Spec.Breakdown.Children) && equality.Semantic.DeepEqual(fresh.Spec.Dependencies, command.Spec.Breakdown.Dependencies) && fresh.Spec.GraphConfiguredByCommand != nil && fresh.Spec.GraphConfiguredByCommand.Name == command.Name {
				return nil
			}
			if fresh.Status.ProjectionSequence != command.Spec.Preconditions.ProjectionSequence {
				return rejectMaintainerCommand(currentProjectionMessage(fresh))
			}
			if fresh.Spec.TriagedByCommand == nil {
				return rejectMaintainerCommand("work item must be triaged before its graph is configured")
			}
			if err := r.validateBreakdown(ctx, repository, item.Name, command.Spec.Breakdown.Children, command.Spec.Breakdown.Dependencies); err != nil {
				return err
			}
			fresh.Spec.Children = append([]triggersv1alpha1.MaintainerWorkItemReference(nil), command.Spec.Breakdown.Children...)
			fresh.Spec.Dependencies = append([]triggersv1alpha1.MaintainerWorkItemReference(nil), command.Spec.Breakdown.Dependencies...)
			fresh.Spec.GraphConfiguredByCommand = &corev1.LocalObjectReference{Name: command.Name}
			return r.Update(ctx, fresh)
		})
	case triggersv1alpha1.MaintainerWorkItemCommandTypeRequestDecision:
		if item.Status.PendingDecision != nil && (item.Status.PendingDecision.RequestedByCommand == nil || item.Status.PendingDecision.RequestedByCommand.Name != command.Name) {
			return rejectMaintainerCommand("work item already has a pending decision")
		}
		return r.retryMaintainerWorkItemStatusMutation(ctx, client.ObjectKeyFromObject(item), func(fresh *triggersv1alpha1.MaintainerWorkItem) (bool, error) {
			if fresh.Status.PendingDecision != nil {
				if fresh.Status.PendingDecision.RequestedByCommand != nil && fresh.Status.PendingDecision.RequestedByCommand.Name == command.Name {
					return false, nil
				}
				return false, rejectMaintainerCommand("work item already has a pending decision")
			}
			if fresh.Status.ProjectionSequence != command.Spec.Preconditions.ProjectionSequence {
				return false, rejectMaintainerCommand(currentProjectionMessage(fresh))
			}
			now := metav1.Now()
			fresh.Status.PendingDecision = &triggersv1alpha1.MaintainerPendingDecision{ID: command.Spec.RequestDecision.DecisionID, Question: command.Spec.RequestDecision.Question, Options: append([]string(nil), command.Spec.RequestDecision.Options...), RequestedAt: now, RequestedByCommand: &corev1.LocalObjectReference{Name: command.Name}}
			fresh.Status.Phase = triggersv1alpha1.MaintainerWorkItemPhaseAwaitingDecision
			fresh.Status.ProjectionSequence++
			return true, nil
		})
	case triggersv1alpha1.MaintainerWorkItemCommandTypeResolveDecision:
		if command.Spec.HumanIssuer == nil {
			return rejectMaintainerCommand("resolveDecision commands from AgentRuns are not authorized")
		}
		resolve := command.Spec.ResolveDecision
		return r.retryMaintainerWorkItemStatusMutation(ctx, client.ObjectKeyFromObject(item), func(fresh *triggersv1alpha1.MaintainerWorkItem) (bool, error) {
			if fresh.Status.ResolvedDecision != nil && fresh.Status.ResolvedDecision.ResolvedByCommand.Name == command.Name {
				return false, nil
			}
			if fresh.Status.PendingDecision == nil || fresh.Status.PendingDecision.ID != resolve.DecisionID {
				return false, rejectMaintainerCommand("work item does not have a matching pending decision")
			}
			if fresh.Status.ProjectionSequence != command.Spec.Preconditions.ProjectionSequence {
				return false, rejectMaintainerCommand(currentProjectionMessage(fresh))
			}
			now := metav1.Now()
			fresh.Status.PendingDecision = nil
			fresh.Status.ResolvedDecision = &triggersv1alpha1.MaintainerResolvedDecision{
				ID:                resolve.DecisionID,
				HumanSubject:      resolve.HumanAnswer.Subject,
				Answer:            resolve.HumanAnswer.Answer,
				ResolvedAt:        now,
				ResolvedByCommand: corev1.LocalObjectReference{Name: command.Name},
			}
			fresh.Status.Phase = triggersv1alpha1.MaintainerWorkItemPhaseTriaged
			fresh.Status.ProjectionSequence++
			return true, nil
		})
	case triggersv1alpha1.MaintainerWorkItemCommandTypeDispatchWorkItem:
		configuredMode, err := configuredMaintainerDispatchMode(repository)
		if err != nil {
			return rejectMaintainerCommand(err.Error())
		}
		requestedMode := strings.ToLower(strings.TrimSpace(command.Spec.Dispatch.Mode))
		if requestedMode != configuredMode {
			return rejectMaintainerCommand(fmt.Sprintf("dispatch mode %q does not match controller-owned mode %q", requestedMode, configuredMode))
		}
		if !ModeExistsFromK8s(ctx, r.Client)(configuredMode) {
			return rejectMaintainerCommand(fmt.Sprintf("configured dispatch ModeTemplate %q does not exist", configuredMode))
		}
		fresh := &triggersv1alpha1.MaintainerWorkItem{}
		if err := r.maintainerReader().Get(ctx, client.ObjectKeyFromObject(item), fresh); err != nil {
			return err
		}
		replay := fresh.Status.DispatchReservation != nil && fresh.Status.DispatchReservation.CommandRef.Name == command.Name
		if replay {
			// The reservation is the durable application boundary. Replays must
			// proceed to verify or finish side effects even though readiness is
			// intentionally false while that reservation exists.
			return nil
		}
		if fresh.Status.DispatchReservation != nil {
			return r.replaceOrphanedMaintainerDispatch(ctx, repository, command, fresh)
		}
		if fresh.Status.Phase != triggersv1alpha1.MaintainerWorkItemPhaseReadyToDispatch {
			return rejectMaintainerCommand("work item is not in the pre-dispatch phase")
		}
		if fresh.Spec.GraphConfiguredByCommand == nil {
			return rejectMaintainerCommand("work item graph has not been explicitly configured")
		}
		if fresh.Generation > 0 {
			projectionCurrent := false
			for _, condition := range fresh.Status.Conditions {
				if condition.Type == triggersv1alpha1.ConditionMaintainerWorkItemDependenciesReady && condition.ObservedGeneration == fresh.Generation {
					projectionCurrent = true
					break
				}
			}
			if !projectionCurrent {
				return rejectMaintainerCommand("readiness projection has not observed the current work-item graph generation")
			}
		}
		if fresh.Status.PendingDecision != nil {
			return rejectMaintainerCommand("work item has a pending decision")
		}
		if fresh.Status.Readiness == nil || !fresh.Status.Readiness.ReadyToDispatch {
			return rejectMaintainerCommand("dependencies are not delivered")
		}
		if !replay && fresh.Status.ProjectionSequence != command.Spec.Preconditions.ProjectionSequence {
			return rejectMaintainerCommand(currentProjectionMessage(fresh))
		}
		item = fresh
		// Required pull requests are intentionally not persisted: a monitor name
		// is derived from the implementer run UID and the pull request URL, so no
		// caller can name one before dispatch. Delivery evidence comes from the
		// monitors actually bound to this work item's implementer runs.
		return r.reserveMaintainerDispatch(ctx, repository, command, item)
	default:
		return rejectMaintainerCommand("unsupported execution command")
	}
}

// replaceOrphanedMaintainerDispatch permits a fresh authenticated dispatch to
// replace a materialized reservation only after its exact controller-derived
// implementer has disappeared. The existing ledger entry must still own a
// capacity slot, so recovery cannot bypass concurrency accounting.
func (r *GitHubRepositoryReconciler) replaceOrphanedMaintainerDispatch(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand, item *triggersv1alpha1.MaintainerWorkItem) error {
	reservation := item.Status.DispatchReservation
	if reservation == nil || reservation.AgentRunRef == nil || reservation.AgentRunRef.Name == "" {
		return rejectMaintainerCommand("work item was already dispatched")
	}
	if item.Name != MaintainerWorkItemName(repository.Name, item.Spec.IssueNumber) || item.Spec.RepositoryRef.Name != repository.Name || !item.DeletionTimestamp.IsZero() || !runOwnerMatchesRepository(item.OwnerReferences, repository) {
		return rejectMaintainerCommand("existing dispatch does not belong to the current repository work item")
	}
	expectedRunName := ghIssueName(repository.Spec.Owner, repository.Spec.Repo, strconv.Itoa(int(item.Spec.IssueNumber)))
	if reservation.AgentRunRef.Name != expectedRunName {
		return rejectMaintainerCommand("existing dispatch run does not match the controller-derived implementer identity")
	}
	run := &platformv1alpha1.AgentRun{}
	if err := r.maintainerReader().Get(ctx, client.ObjectKey{Namespace: repository.Namespace, Name: expectedRunName}, run); err == nil {
		return rejectMaintainerCommand("work item was already dispatched and its implementer still exists")
	} else if !apierrors.IsNotFound(err) {
		return fmt.Errorf("checking existing dispatch run: %w", err)
	}
	oldCommand := &triggersv1alpha1.MaintainerWorkItemCommand{ObjectMeta: metav1.ObjectMeta{Name: reservation.CommandRef.Name}}
	if item.Spec.GraphConfiguredByCommand == nil {
		return rejectMaintainerCommand("work item graph has not been explicitly configured")
	}
	if item.Generation > 0 {
		projectionCurrent := false
		for _, condition := range item.Status.Conditions {
			if condition.Type == triggersv1alpha1.ConditionMaintainerWorkItemDependenciesReady && condition.ObservedGeneration == item.Generation {
				projectionCurrent = true
				break
			}
		}
		if !projectionCurrent {
			return rejectMaintainerCommand("readiness projection has not observed the current work-item graph generation")
		}
	}
	candidate := item.DeepCopy()
	candidate.Status.DispatchReservation = nil
	evaluateMaintainerReadiness(candidate, time.Now(), repository.Spec.Maintainer != nil && repository.Spec.Maintainer.FullControl)
	if candidate.Status.Readiness == nil || !candidate.Status.Readiness.ReadyToDispatch {
		return rejectMaintainerCommand("work item is not ready for recovery dispatch")
	}
	if err := retryMaintainerWorkItemCommandStatusUpdate(ctx, r.Client, client.ObjectKeyFromObject(command), func(fresh *triggersv1alpha1.MaintainerWorkItemCommand) {
		if fresh.Status.Result == nil {
			fresh.Status.Result = &triggersv1alpha1.MaintainerWorkItemCommandResult{WorkItemRef: corev1.LocalObjectReference{Name: item.Name}}
		}
		fresh.Status.Result.AgentRunRef = &corev1.LocalObjectReference{Name: expectedRunName}
		fresh.Status.Result.Message = "authenticated recovery dispatch validated"
	}); err != nil {
		return fmt.Errorf("recording validated dispatch recovery: %w", err)
	}
	command.Status.Result = &triggersv1alpha1.MaintainerWorkItemCommandResult{WorkItemRef: corev1.LocalObjectReference{Name: item.Name}, AgentRunRef: &corev1.LocalObjectReference{Name: expectedRunName}}
	return r.transferMaintainerDispatchReservation(ctx, repository, oldCommand.Name, command, item)
}

func (r *GitHubRepositoryReconciler) transferMaintainerDispatchReservation(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, oldCommandName string, command *triggersv1alpha1.MaintainerWorkItemCommand, item *triggersv1alpha1.MaintainerWorkItem) error {
	if err := retry.RetryOnConflict(retry.DefaultRetry, func() error {
		fresh := &triggersv1alpha1.GitHubRepository{}
		if err := r.maintainerReader().Get(ctx, client.ObjectKeyFromObject(repository), fresh); err != nil {
			return err
		}
		ledger := maintainerRepositoryDispatchLedger{}
		raw := fresh.Annotations[triggersv1alpha1.MaintainerDispatchReservationsAnnotation]
		if raw == "" {
			return rejectMaintainerCommand("existing dispatch no longer owns a recoverable capacity reservation")
		}
		if err := json.Unmarshal([]byte(raw), &ledger); err != nil {
			return fmt.Errorf("invalid repository dispatch ledger: %w", err)
		}
		entry, ok := ledger.Reservations[item.Name]
		if !ok {
			return rejectMaintainerCommand("existing dispatch no longer owns a recoverable capacity reservation")
		}
		switch entry.CommandName {
		case command.Name:
			return nil
		case oldCommandName:
			entry.CommandName = command.Name
			ledger.Reservations[item.Name] = entry
		default:
			return rejectMaintainerCommand("dispatch capacity reservation changed owners")
		}
		encoded, err := json.Marshal(ledger)
		if err != nil {
			return err
		}
		patch := client.MergeFromWithOptions(fresh.DeepCopy(), client.MergeFromWithOptimisticLock{})
		fresh.Annotations[triggersv1alpha1.MaintainerDispatchReservationsAnnotation] = string(encoded)
		return r.Patch(ctx, fresh, patch)
	}); err != nil {
		return err
	}
	return r.retryMaintainerWorkItemStatusMutation(ctx, client.ObjectKeyFromObject(item), func(fresh *triggersv1alpha1.MaintainerWorkItem) (bool, error) {
		reservation := fresh.Status.DispatchReservation
		if reservation == nil {
			return false, rejectMaintainerCommand("dispatch reservation disappeared during recovery")
		}
		switch reservation.CommandRef.Name {
		case command.Name:
			return false, nil
		case oldCommandName:
			reservation.ID = command.Spec.IdempotencyKey
			reservation.CommandRef.Name = command.Name
			reservation.AgentRunRef = nil
			fresh.Status.Phase = triggersv1alpha1.MaintainerWorkItemPhaseDispatched
			fresh.Status.ProjectionSequence++
			return true, nil
		default:
			return false, rejectMaintainerCommand("dispatch reservation changed owners during recovery")
		}
	})
}

func runOwnerMatchesRepository(owners []metav1.OwnerReference, repository *triggersv1alpha1.GitHubRepository) bool {
	for _, owner := range owners {
		if owner.Controller != nil && *owner.Controller && owner.APIVersion == triggersv1alpha1.GroupVersion.String() && owner.Kind == gitHubRepositoryTriggerKind && owner.Name == repository.Name && owner.UID == repository.UID {
			return true
		}
	}
	return false
}

// recreateMaintainerDispatchRun performs the wake-up side effect for a
// recovery command. Ordinary dispatches continue to use the label/webhook path.
func (r *GitHubRepositoryReconciler) recreateMaintainerDispatchRun(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand, item *triggersv1alpha1.MaintainerWorkItem, issue *github.Issue) error {
	if command.Status.Result == nil || command.Status.Result.AgentRunRef == nil {
		return nil
	}
	recoveryRunName := command.Status.Result.AgentRunRef.Name
	expectedRunName := ghIssueName(repository.Spec.Owner, repository.Spec.Repo, strconv.Itoa(int(item.Spec.IssueNumber)))
	if recoveryRunName != expectedRunName {
		return fmt.Errorf("validated dispatch recovery names unexpected AgentRun %q", recoveryRunName)
	}
	fresh := &triggersv1alpha1.MaintainerWorkItem{}
	if err := r.maintainerReader().Get(ctx, client.ObjectKeyFromObject(item), fresh); err != nil {
		return err
	}
	if fresh.Status.DispatchReservation == nil || fresh.Status.DispatchReservation.CommandRef.Name != command.Name {
		return fmt.Errorf("dispatch recovery reservation is no longer owned by command %s", command.Name)
	}
	if fresh.Spec.GraphConfiguredByCommand == nil || fresh.Status.PendingDecision != nil {
		return rejectMaintainerCommand("work item is no longer ready for recovery dispatch")
	}
	if fresh.Generation > 0 {
		projectionCurrent := false
		for _, condition := range fresh.Status.Conditions {
			if condition.Type == triggersv1alpha1.ConditionMaintainerWorkItemDependenciesReady && condition.ObservedGeneration == fresh.Generation {
				projectionCurrent = true
				break
			}
		}
		if !projectionCurrent {
			return rejectMaintainerCommand("readiness projection has not observed the current work-item graph generation")
		}
	}
	candidate := fresh.DeepCopy()
	candidate.Status.DispatchReservation = nil
	evaluateMaintainerReadiness(candidate, time.Now(), repository.Spec.Maintainer != nil && repository.Spec.Maintainer.FullControl)
	if candidate.Status.Readiness == nil || !candidate.Status.Readiness.ReadyToDispatch {
		return rejectMaintainerCommand("work item is no longer ready for recovery dispatch")
	}
	runs := &platformv1alpha1.AgentRunList{}
	if err := r.maintainerReader().List(ctx, runs, client.InNamespace(repository.Namespace)); err != nil {
		return err
	}
	if hasOtherActiveMaintainerImplementer(repository, fresh, expectedRunName, runs.Items) {
		return rejectMaintainerCommand("another implementer is already active for this work item")
	}
	active, err := r.maintainerDispatchReservationActive(ctx, repository, command, fresh)
	if err != nil {
		return err
	}
	if !active {
		return rejectMaintainerCommand("recovery dispatch no longer owns its capacity reservation")
	}
	issueID := strconv.Itoa(issue.GetNumber())
	request := githubIssueUserRequest(issue.GetNumber(), issue.GetTitle(), issue.GetBody(), false)
	if _, err := r.createAgentRun(ctx, repository, issueID, issue.GetNumber(), issue.GetHTMLURL(), request, issue.GetUser().GetLogin(), &platformv1alpha1.ModeRef{Name: command.Spec.Dispatch.Mode}); err != nil {
		return fmt.Errorf("recreating deleted implementer %s: %w", expectedRunName, err)
	}
	return nil
}

func hasOtherActiveMaintainerImplementer(repository *triggersv1alpha1.GitHubRepository, item *triggersv1alpha1.MaintainerWorkItem, expectedRunName string, runs []platformv1alpha1.AgentRun) bool {
	for i := range runs {
		run := &runs[i]
		if run.Name == expectedRunName || run.Labels[triggersv1alpha1.PRLoopRoleLabelKey] == triggersv1alpha1.PRLoopRoleReviewerValue || isTerminalAgentRunPhase(run.Status.Phase) {
			continue
		}
		correlated := run.Labels[triggersv1alpha1.MaintainerWorkItemNameLabelKey] == item.Name && run.Labels[triggersv1alpha1.MaintainerWorkItemUIDLabelKey] == string(item.UID)
		legacyCorrelated := TriggerRunMatches(run, gitHubRepositoryTriggerKind, repository.Name) && runOwnedByGitHubRepository(run, repository) && maintainerRunWorkItemName(repository, run) == item.Name
		if correlated || legacyCorrelated {
			return true
		}
	}
	return false
}

func (r *GitHubRepositoryReconciler) validateBreakdown(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, itemName string, children, dependencies []triggersv1alpha1.MaintainerWorkItemReference) error {
	items := &triggersv1alpha1.MaintainerWorkItemList{}
	if err := r.maintainerReader().List(ctx, items, client.InNamespace(repository.Namespace), client.MatchingLabels{triggersv1alpha1.MaintainerWorkItemRepositoryLabelKey: repository.Name}); err != nil {
		return err
	}
	byName := make(map[string]*triggersv1alpha1.MaintainerWorkItem, len(items.Items))
	for i := range items.Items {
		byName[items.Items[i].Name] = &items.Items[i]
	}
	for _, ref := range append(append([]triggersv1alpha1.MaintainerWorkItemReference(nil), children...), dependencies...) {
		target := byName[ref.Name]
		if target == nil {
			return rejectMaintainerCommand("referenced work item does not exist: " + ref.Name)
		}
		if ref.UID == "" {
			return rejectMaintainerCommand("referenced work item UID is required: " + ref.Name)
		}
		if ref.UID != target.UID {
			return rejectMaintainerCommand("referenced work item UID mismatch: " + ref.Name)
		}
		if ref.Name == itemName {
			return rejectMaintainerCommand("work item cannot depend on itself")
		}
	}
	graph := map[string][]string{}
	for i := range items.Items {
		for _, ref := range items.Items[i].Spec.Dependencies {
			graph[items.Items[i].Name] = append(graph[items.Items[i].Name], ref.Name)
		}
	}
	graph[itemName] = nil
	for _, ref := range dependencies {
		graph[itemName] = append(graph[itemName], ref.Name)
	}
	visiting, visited := map[string]bool{}, map[string]bool{}
	var visit func(string) bool
	visit = func(name string) bool {
		if visiting[name] {
			return true
		}
		if visited[name] {
			return false
		}
		visiting[name] = true
		if slices.ContainsFunc(graph[name], visit) {
			return true
		}
		visiting[name] = false
		visited[name] = true
		return false
	}
	if visit(itemName) {
		return rejectMaintainerCommand("dependency cycle rejected")
	}
	return nil
}

func isDefiniteGitHubDispatchError(err error) bool {
	var responseError *github.ErrorResponse
	if !errors.As(err, &responseError) || responseError.Response == nil {
		return false
	}
	status := responseError.Response.StatusCode
	return status >= 400 && status < 500 && status != 408 && status != 409 && status != 429
}

func (r *GitHubRepositoryReconciler) maintainerDispatchReservationActive(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand, item *triggersv1alpha1.MaintainerWorkItem) (bool, error) {
	freshItem := &triggersv1alpha1.MaintainerWorkItem{}
	if err := r.maintainerReader().Get(ctx, client.ObjectKeyFromObject(item), freshItem); err != nil {
		return false, err
	}
	if freshItem.Status.DispatchReservation == nil || freshItem.Status.DispatchReservation.CommandRef.Name != command.Name {
		return false, nil
	}
	freshRepository := &triggersv1alpha1.GitHubRepository{}
	if err := r.maintainerReader().Get(ctx, client.ObjectKeyFromObject(repository), freshRepository); err != nil {
		return false, err
	}
	raw := freshRepository.Annotations[triggersv1alpha1.MaintainerDispatchReservationsAnnotation]
	if raw == "" {
		return false, nil
	}
	ledger := maintainerRepositoryDispatchLedger{}
	if err := json.Unmarshal([]byte(raw), &ledger); err != nil {
		return false, err
	}
	reservation, ok := ledger.Reservations[item.Name]
	return ok && reservation.CommandName == command.Name, nil
}

func (r *GitHubRepositoryReconciler) failAndReleaseMaintainerDispatch(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand, item *triggersv1alpha1.MaintainerWorkItem, message string) error {
	if err := r.releaseMaintainerDispatch(ctx, repository, command, item); err != nil {
		return err
	}
	return r.failMaintainerWorkItemCommand(ctx, command, item, message)
}

func (r *GitHubRepositoryReconciler) releaseMaintainerDispatch(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand, item *triggersv1alpha1.MaintainerWorkItem) error {
	if err := retry.RetryOnConflict(retry.DefaultRetry, func() error {
		fresh := &triggersv1alpha1.GitHubRepository{}
		if err := r.maintainerReader().Get(ctx, client.ObjectKeyFromObject(repository), fresh); err != nil {
			return err
		}
		raw := fresh.Annotations[triggersv1alpha1.MaintainerDispatchReservationsAnnotation]
		if raw == "" {
			return nil
		}
		ledger := maintainerRepositoryDispatchLedger{}
		if err := json.Unmarshal([]byte(raw), &ledger); err != nil {
			return err
		}
		reservation, ok := ledger.Reservations[item.Name]
		if !ok || reservation.CommandName != command.Name {
			return nil
		}
		delete(ledger.Reservations, item.Name)
		// Only give back today's budget for reservations made today; a release
		// after midnight must not discount dispatches from a previous day.
		if ledger.Count > 0 && reservation.ReservedAt.Time.UTC().Format("2006-01-02") == ledger.Day {
			ledger.Count--
		}
		encoded, err := json.Marshal(ledger)
		if err != nil {
			return err
		}
		patch := client.MergeFromWithOptions(fresh.DeepCopy(), client.MergeFromWithOptimisticLock{})
		fresh.Annotations[triggersv1alpha1.MaintainerDispatchReservationsAnnotation] = string(encoded)
		return r.Patch(ctx, fresh, patch)
	}); err != nil {
		return err
	}
	return r.retryMaintainerWorkItemStatusMutation(ctx, client.ObjectKeyFromObject(item), func(fresh *triggersv1alpha1.MaintainerWorkItem) (bool, error) {
		if fresh.Status.DispatchReservation == nil || fresh.Status.DispatchReservation.CommandRef.Name != command.Name {
			return false, nil
		}
		fresh.Status.DispatchReservation = nil
		fresh.Status.ProjectionSequence++
		return true, nil
	})
}

type maintainerRepositoryCommandLock struct {
	CommandName string      `json:"commandName"`
	AcquiredAt  metav1.Time `json:"acquiredAt"`
}

func (r *GitHubRepositoryReconciler) acquireMaintainerCommandLock(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, commandName string) error {
	return retry.RetryOnConflict(retry.DefaultRetry, func() error {
		fresh := &triggersv1alpha1.GitHubRepository{}
		if err := r.maintainerReader().Get(ctx, client.ObjectKeyFromObject(repository), fresh); err != nil {
			return err
		}
		var lock maintainerRepositoryCommandLock
		if raw := fresh.Annotations[triggersv1alpha1.MaintainerCommandLockAnnotation]; raw != "" {
			if err := json.Unmarshal([]byte(raw), &lock); err != nil {
				return fmt.Errorf("invalid maintainer command lock: %w", err)
			}
			if lock.CommandName != commandName && time.Since(lock.AcquiredAt.Time) < 5*time.Minute {
				return fmt.Errorf("maintainer graph mutation is serialized behind command %s", lock.CommandName)
			}
		}
		encoded, _ := json.Marshal(maintainerRepositoryCommandLock{CommandName: commandName, AcquiredAt: metav1.Now()})
		patch := client.MergeFromWithOptions(fresh.DeepCopy(), client.MergeFromWithOptimisticLock{})
		if fresh.Annotations == nil {
			fresh.Annotations = map[string]string{}
		}
		fresh.Annotations[triggersv1alpha1.MaintainerCommandLockAnnotation] = string(encoded)
		return r.Patch(ctx, fresh, patch)
	})
}

func (r *GitHubRepositoryReconciler) releaseMaintainerCommandLock(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, commandName string) error {
	return retry.RetryOnConflict(retry.DefaultRetry, func() error {
		fresh := &triggersv1alpha1.GitHubRepository{}
		if err := r.maintainerReader().Get(ctx, client.ObjectKeyFromObject(repository), fresh); err != nil {
			return err
		}
		var lock maintainerRepositoryCommandLock
		raw := fresh.Annotations[triggersv1alpha1.MaintainerCommandLockAnnotation]
		if raw == "" {
			return nil
		}
		if err := json.Unmarshal([]byte(raw), &lock); err != nil {
			return err
		}
		if lock.CommandName != commandName {
			return nil
		}
		patch := client.MergeFromWithOptions(fresh.DeepCopy(), client.MergeFromWithOptimisticLock{})
		delete(fresh.Annotations, triggersv1alpha1.MaintainerCommandLockAnnotation)
		return r.Patch(ctx, fresh, patch)
	})
}

type maintainerRepositoryDispatchLedger struct {
	Day          string                                     `json:"day"`
	Count        int                                        `json:"count"`
	Reservations map[string]maintainerRepositoryReservation `json:"reservations"`
}

type maintainerRepositoryReservation struct {
	CommandName string      `json:"commandName"`
	ReservedAt  metav1.Time `json:"reservedAt"`
}

// maintainerDispatchReservationTTL bounds how long an unmaterialized
// reservation with no correlated active run may hold a capacity slot.
const maintainerDispatchReservationTTL = 24 * time.Hour

// pruneMaintainerDispatchReservations removes ledger entries that can no
// longer legitimately hold capacity: entries whose work item was deleted,
// entries whose bound run already finished, and unmaterialized entries older
// than the TTL with no correlated active run. Without this, orphaned entries
// count against the concurrency cap forever. The entry for protect (the work
// item currently being reserved) is never pruned so an in-flight dispatch
// cannot lose its own reservation.
func pruneMaintainerDispatchReservations(ledger *maintainerRepositoryDispatchLedger, protect string, workItemUIDs map[string]string, materialized, activeItems map[string]bool, now time.Time) bool {
	pruned := false
	for name, reservation := range ledger.Reservations {
		if name == protect {
			continue
		}
		switch {
		case workItemUIDs[name] == "":
			// The work item no longer exists; its reservation is unreleasable.
		case materialized[name] && !activeItems[name]:
			// The reservation was bound to a run that is now terminal or gone.
		case !materialized[name] && !activeItems[name] && now.Sub(reservation.ReservedAt.Time) > maintainerDispatchReservationTTL:
			// The reservation never materialized and has no active run.
		default:
			continue
		}
		delete(ledger.Reservations, name)
		pruned = true
	}
	return pruned
}

// maintainerRunWorkItemName derives the deterministic work-item name for a
// repository-owned run that predates work-item labels, so legacy runs dedupe
// against ledger reservations by identity instead of double-counting.
func maintainerRunWorkItemName(repository *triggersv1alpha1.GitHubRepository, run *platformv1alpha1.AgentRun) string {
	if run.Spec.Trigger.ExternalRef == nil {
		return ""
	}
	raw := strings.TrimPrefix(strings.TrimSpace(run.Spec.Trigger.ExternalRef.Identifier), "#")
	if number, err := strconv.ParseInt(raw, 10, 32); err == nil && number > 0 {
		return MaintainerWorkItemName(repository.Name, int32(number))
	}
	if number, err := strconv.ParseInt(strings.TrimSpace(run.Spec.Trigger.ExternalRef.ID), 10, 32); err == nil && number > 0 {
		return MaintainerWorkItemName(repository.Name, int32(number))
	}
	return ""
}

//nolint:gocyclo // Reservation validates all cap, replay, migration, and ownership invariants atomically.
func (r *GitHubRepositoryReconciler) reserveMaintainerDispatch(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, command *triggersv1alpha1.MaintainerWorkItemCommand, item *triggersv1alpha1.MaintainerWorkItem) error {
	items := &triggersv1alpha1.MaintainerWorkItemList{}
	if err := r.maintainerReader().List(ctx, items, client.InNamespace(repository.Namespace), client.MatchingLabels{triggersv1alpha1.MaintainerWorkItemRepositoryLabelKey: repository.Name}); err != nil {
		return err
	}
	materialized := map[string]bool{}
	workItemUIDs := map[string]string{}
	for i := range items.Items {
		materialized[items.Items[i].Name] = items.Items[i].Status.DispatchReservation != nil && items.Items[i].Status.DispatchReservation.AgentRunRef != nil
		workItemUIDs[items.Items[i].Name] = string(items.Items[i].UID)
	}
	runs := &platformv1alpha1.AgentRunList{}
	if err := r.maintainerReader().List(ctx, runs, client.InNamespace(repository.Namespace)); err != nil {
		return err
	}
	// Deduplicate capacity by work-item identity: a work item must never
	// consume one slot through its active run and a second slot through its
	// not-yet-materialized ledger reservation.
	activeItems := map[string]bool{}
	legacyActive := 0
	for i := range runs.Items {
		run := &runs.Items[i]
		if run.Labels[triggersv1alpha1.PRLoopRoleLabelKey] == triggersv1alpha1.PRLoopRoleReviewerValue || isTerminalAgentRunPhase(run.Status.Phase) {
			continue
		}
		// Standing runs (the maintainer itself) are supervisors, not dispatched
		// work; counting them would permanently consume a capacity slot.
		if run.Labels[orchestration.StandingRunRoleLabel] != "" {
			continue
		}
		workItemName := run.Labels[triggersv1alpha1.MaintainerWorkItemNameLabelKey]
		correlated := workItemUIDs[workItemName] != "" && workItemUIDs[workItemName] == run.Labels[triggersv1alpha1.MaintainerWorkItemUIDLabelKey]
		legacyOwned := TriggerRunMatches(run, gitHubRepositoryTriggerKind, repository.Name) && runOwnedByGitHubRepository(run, repository)
		switch {
		case correlated:
			activeItems[workItemName] = true
		case legacyOwned:
			if name := maintainerRunWorkItemName(repository, run); name != "" {
				activeItems[name] = true
			} else {
				legacyActive++
			}
		}
	}
	maxConcurrent, maxDaily := int32(2), int32(10)
	if repository.Spec.Maintainer != nil {
		if repository.Spec.Maintainer.MaxConcurrentDispatches > 0 {
			maxConcurrent = repository.Spec.Maintainer.MaxConcurrentDispatches
		}
		if repository.Spec.Maintainer.MaxDispatchesPerDay > 0 {
			maxDaily = repository.Spec.Maintainer.MaxDispatchesPerDay
		}
	}
	now := time.Now().UTC()
	if err := retry.RetryOnConflict(retry.DefaultRetry, func() error {
		fresh := &triggersv1alpha1.GitHubRepository{}
		if err := r.maintainerReader().Get(ctx, client.ObjectKeyFromObject(repository), fresh); err != nil {
			return err
		}
		ledger := maintainerRepositoryDispatchLedger{Day: now.Format("2006-01-02"), Reservations: map[string]maintainerRepositoryReservation{}}
		if fresh.Annotations != nil {
			if raw := fresh.Annotations[triggersv1alpha1.MaintainerDispatchReservationsAnnotation]; raw != "" {
				if err := json.Unmarshal([]byte(raw), &ledger); err != nil {
					return fmt.Errorf("invalid repository dispatch ledger: %w", err)
				}
			}
		}
		if ledger.Count < 0 {
			return fmt.Errorf("invalid negative repository dispatch count")
		}
		if ledger.Day != now.Format("2006-01-02") {
			ledger.Day, ledger.Count = now.Format("2006-01-02"), 0
		}
		if ledger.Reservations == nil {
			ledger.Reservations = map[string]maintainerRepositoryReservation{}
		}
		pruned := pruneMaintainerDispatchReservations(&ledger, item.Name, workItemUIDs, materialized, activeItems, now)
		persist := func() error {
			encoded, err := json.Marshal(ledger)
			if err != nil {
				return err
			}
			patch := client.MergeFromWithOptions(fresh.DeepCopy(), client.MergeFromWithOptimisticLock{})
			if fresh.Annotations == nil {
				fresh.Annotations = map[string]string{}
			}
			fresh.Annotations[triggersv1alpha1.MaintainerDispatchReservationsAnnotation] = string(encoded)
			return r.Patch(ctx, fresh, patch)
		}
		if existing, ok := ledger.Reservations[item.Name]; ok {
			if existing.CommandName != command.Name {
				if pruned {
					if err := persist(); err != nil {
						return err
					}
				}
				return rejectMaintainerCommand("work item capacity is reserved by another command")
			}
			if pruned {
				return persist()
			}
			return nil
		}
		pending := 0
		for workItemName := range ledger.Reservations {
			if !materialized[workItemName] && !activeItems[workItemName] {
				pending++
			}
		}
		usage := len(activeItems) + legacyActive + pending
		if int32(usage) >= maxConcurrent {
			if pruned {
				if err := persist(); err != nil {
					return err
				}
			}
			return rejectMaintainerCommand(fmt.Sprintf("dispatch concurrency cap reached (%d/%d)", usage, maxConcurrent))
		}
		if int32(ledger.Count) >= maxDaily {
			if pruned {
				if err := persist(); err != nil {
					return err
				}
			}
			return rejectMaintainerCommand(fmt.Sprintf("daily dispatch cap reached (%d/%d)", ledger.Count, maxDaily))
		}
		ledger.Count++
		ledger.Reservations[item.Name] = maintainerRepositoryReservation{CommandName: command.Name, ReservedAt: metav1.NewTime(now)}
		return persist()
	}); err != nil {
		return err
	}
	return r.retryMaintainerWorkItemStatusMutation(ctx, client.ObjectKeyFromObject(item), func(fresh *triggersv1alpha1.MaintainerWorkItem) (bool, error) {
		if fresh.Status.DispatchReservation != nil {
			if fresh.Status.DispatchReservation.CommandRef.Name == command.Name {
				return false, nil
			}
			return false, rejectMaintainerCommand("dispatch capacity reservation is owned by another command")
		}
		fresh.Status.DispatchReservation = &triggersv1alpha1.MaintainerDispatchReservation{ID: command.Spec.IdempotencyKey, CommandRef: corev1.LocalObjectReference{Name: command.Name}, ReservedAt: metav1.NewTime(now)}
		fresh.Status.Phase = triggersv1alpha1.MaintainerWorkItemPhaseDispatched
		fresh.Status.ProjectionSequence++
		return true, nil
	})
}

package triggers

import (
	"context"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"time"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
	"github.com/gratefulagents/gratefulagents/internal/orchestration"
	corev1 "k8s.io/api/core/v1"
	"k8s.io/apimachinery/pkg/api/equality"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	meta "k8s.io/apimachinery/pkg/api/meta"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

const maintainerProjectionFreshness = 5 * time.Minute

// reconcileMaintainerExecutionProjection derives execution facts exclusively
// from Kubernetes records. External references are used once for migration;
// durable correlation thereafter is by work-item name and immutable UID labels.
func (r *GitHubRepositoryReconciler) reconcileMaintainerExecutionProjection(ctx context.Context, repository *triggersv1alpha1.GitHubRepository) error {
	items := &triggersv1alpha1.MaintainerWorkItemList{}
	if err := r.maintainerReader().List(ctx, items, client.InNamespace(repository.Namespace), client.MatchingLabels{triggersv1alpha1.MaintainerWorkItemRepositoryLabelKey: repository.Name}); err != nil {
		return err
	}
	runs := &platformv1alpha1.AgentRunList{}
	if err := r.List(ctx, runs, client.InNamespace(repository.Namespace)); err != nil {
		return err
	}
	byName := make(map[string]*triggersv1alpha1.MaintainerWorkItem, len(items.Items))
	byIssue := map[int32]*triggersv1alpha1.MaintainerWorkItem{}
	for i := range items.Items {
		byName[items.Items[i].Name] = &items.Items[i]
		byIssue[items.Items[i].Spec.IssueNumber] = &items.Items[i]
	}
	if err := r.migrateMaintainerRunLabels(ctx, repository, runs, byIssue); err != nil {
		return err
	}
	// Reload labels written by migration before projecting.
	if err := r.List(ctx, runs, client.InNamespace(repository.Namespace)); err != nil {
		return err
	}
	monitors := &triggersv1alpha1.PullRequestMonitorList{}
	if err := r.List(ctx, monitors, client.InNamespace(repository.Namespace)); err != nil {
		return err
	}
	now := time.Now()
	for i := range items.Items {
		item := &items.Items[i]
		if err := retryMaintainerWorkItemStatusUpdate(ctx, r.maintainerReader(), r.Client, client.ObjectKeyFromObject(item), func(fresh *triggersv1alpha1.MaintainerWorkItem) bool {
			before := fresh.Status.DeepCopy()
			projectMaintainerDependencies(fresh, byName, now)
			projectMaintainerRunsAndPRs(fresh, runs.Items, monitors.Items, now)
			evaluateMaintainerReadiness(fresh, now, repository.Spec.Maintainer != nil && repository.Spec.Maintainer.FullControl)
			if maintainerWorkItemStatusSemanticallyEqual(before, &fresh.Status) {
				// Persist fresh head-bound observation heartbeats without advancing
				// the semantic cursor. Waiter-v2 ignores same-sequence updates.
				return !equality.Semantic.DeepEqual(before.PullRequests, fresh.Status.PullRequests)
			}
			fresh.Status.ProjectionSequence++
			return true
		}); err != nil {
			// A list snapshot can race garbage collection or another deletion. The
			// vanished item needs no projection, and other items must still be
			// processed in this reconciliation pass.
			if apierrors.IsNotFound(err) {
				continue
			}
			return err
		}
	}
	return nil
}

func (r *GitHubRepositoryReconciler) migrateMaintainerRunLabels(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, runs *platformv1alpha1.AgentRunList, byIssue map[int32]*triggersv1alpha1.MaintainerWorkItem) error {
	for i := range runs.Items {
		run := &runs.Items[i]
		if run.Labels[triggersv1alpha1.MaintainerWorkItemNameLabelKey] != "" {
			continue
		}
		var item *triggersv1alpha1.MaintainerWorkItem
		if run.Labels[triggersv1alpha1.PRLoopRoleLabelKey] == triggersv1alpha1.PRLoopRoleReviewerValue {
			implementerName := run.Annotations[PRLoopImplementerAnnotation]
			for j := range runs.Items {
				if runs.Items[j].Name == implementerName {
					name := runs.Items[j].Labels[triggersv1alpha1.MaintainerWorkItemNameLabelKey]
					item = findWorkItemByName(byIssue, name)
					break
				}
			}
		} else if TriggerRunMatches(run, gitHubRepositoryTriggerKind, repository.Name) && runOwnedByGitHubRepository(run, repository) && run.Spec.Trigger.ExternalRef != nil {
			raw := strings.TrimPrefix(strings.TrimSpace(run.Spec.Trigger.ExternalRef.Identifier), "#")
			if number, err := strconv.ParseInt(raw, 10, 32); err == nil {
				item = byIssue[int32(number)]
			}
			if item == nil {
				if number, err := strconv.ParseInt(strings.TrimSpace(run.Spec.Trigger.ExternalRef.ID), 10, 32); err == nil {
					item = byIssue[int32(number)]
				}
			}
		}
		if item == nil {
			continue
		}
		patch := client.MergeFrom(run.DeepCopy())
		if run.Labels == nil {
			run.Labels = map[string]string{}
		}
		run.Labels[triggersv1alpha1.MaintainerWorkItemNameLabelKey] = item.Name
		run.Labels[triggersv1alpha1.MaintainerWorkItemUIDLabelKey] = string(item.UID)
		if err := r.Patch(ctx, run, patch); err != nil {
			return fmt.Errorf("labeling AgentRun %s with work-item identity: %w", run.Name, err)
		}
	}
	return nil
}

func runOwnedByGitHubRepository(run *platformv1alpha1.AgentRun, repository *triggersv1alpha1.GitHubRepository) bool {
	for _, owner := range run.OwnerReferences {
		if owner.Controller != nil && *owner.Controller && owner.APIVersion == triggersv1alpha1.GroupVersion.String() && owner.Kind == gitHubRepositoryTriggerKind && owner.Name == repository.Name && owner.UID == repository.UID {
			return true
		}
	}
	return false
}

func findWorkItemByName(items map[int32]*triggersv1alpha1.MaintainerWorkItem, name string) *triggersv1alpha1.MaintainerWorkItem {
	for _, item := range items {
		if item.Name == name {
			return item
		}
	}
	return nil
}

func projectMaintainerDependencies(item *triggersv1alpha1.MaintainerWorkItem, byName map[string]*triggersv1alpha1.MaintainerWorkItem, now time.Time) {
	observed := metav1.NewTime(now)
	item.Status.Children = nil
	item.Status.Dependencies = nil
	for _, ref := range item.Spec.Children {
		target := byName[ref.Name]
		projection := triggersv1alpha1.MaintainerWorkItemChildProjection{Name: ref.Name, ObservedAt: &observed}
		if target != nil && (ref.UID == "" || ref.UID == target.UID) {
			projection.UID, projection.Phase, projection.Delivered = target.UID, target.Status.Phase, target.Status.Phase == triggersv1alpha1.MaintainerWorkItemPhaseDelivered
		}
		item.Status.Children = append(item.Status.Children, projection)
	}
	for _, ref := range item.Spec.Dependencies {
		target := byName[ref.Name]
		projection := triggersv1alpha1.MaintainerWorkItemDependencyProjection{Name: ref.Name, ObservedAt: &observed}
		if target != nil && (ref.UID == "" || ref.UID == target.UID) {
			projection.UID, projection.Phase, projection.Delivered = target.UID, target.Status.Phase, target.Status.Phase == triggersv1alpha1.MaintainerWorkItemPhaseDelivered
		}
		item.Status.Dependencies = append(item.Status.Dependencies, projection)
	}
}

func projectMaintainerRunsAndPRs(item *triggersv1alpha1.MaintainerWorkItem, runs []platformv1alpha1.AgentRun, monitors []triggersv1alpha1.PullRequestMonitor, now time.Time) {
	observed := metav1.NewTime(now)
	item.Status.AgentRuns = nil
	item.Status.PullRequests = nil
	runNames := map[string]bool{}
	for i := range runs {
		run := &runs[i]
		if run.Labels[triggersv1alpha1.MaintainerWorkItemNameLabelKey] != item.Name || run.Labels[triggersv1alpha1.MaintainerWorkItemUIDLabelKey] != string(item.UID) {
			continue
		}
		role := triggersv1alpha1.MaintainerWorkItemAgentRunRoleImplementer
		if run.Labels[triggersv1alpha1.PRLoopRoleLabelKey] == triggersv1alpha1.PRLoopRoleReviewerValue {
			role = triggersv1alpha1.MaintainerWorkItemAgentRunRoleReviewer
		}
		episode := triggersv1alpha1.MaintainerWorkItemAgentRunEpisodeActive
		if orchestration.AgentRunEpisodeFinished(run) {
			episode = triggersv1alpha1.MaintainerWorkItemAgentRunEpisodeFinished
		}
		item.Status.AgentRuns = append(item.Status.AgentRuns, triggersv1alpha1.MaintainerWorkItemAgentRunProjection{Name: run.Name, UID: run.UID, Role: role, Phase: string(run.Status.Phase), EpisodeState: episode, PRLoopState: run.Labels[PRLoopStateLabel], ObservedAt: &observed})
		if role == triggersv1alpha1.MaintainerWorkItemAgentRunRoleImplementer {
			runNames[run.Name] = true
			// Bind only runs created for the current reservation (with a small
			// clock-skew grace); a lingering run from an earlier dispatch must
			// not "materialize" a fresh reservation it does not satisfy.
			if item.Status.DispatchReservation != nil && item.Status.DispatchReservation.AgentRunRef == nil &&
				!run.CreationTimestamp.Time.Before(item.Status.DispatchReservation.ReservedAt.Add(-time.Minute)) {
				item.Status.DispatchReservation.AgentRunRef = &corev1.LocalObjectReference{Name: run.Name}
			}
		}
	}
	// Every monitor created by a bound implementer run is delivery evidence.
	// Nothing is filtered by a pre-dispatch intent list: monitor names are
	// derived from the implementer run UID and the pull request URL, so an
	// intent recorded before dispatch can never match a real monitor and would
	// otherwise hide merged pull requests behind an unsatisfiable placeholder.
	for i := range monitors {
		monitor := &monitors[i]
		if !runNames[monitor.Spec.ImplementerRef.Name] {
			continue
		}
		projection := maintainerPRProjection(monitor)
		item.Status.PullRequests = append(item.Status.PullRequests, projection)
	}
	sort.Slice(item.Status.AgentRuns, func(i, j int) bool { return item.Status.AgentRuns[i].Name < item.Status.AgentRuns[j].Name })
	sort.Slice(item.Status.PullRequests, func(i, j int) bool {
		if item.Status.PullRequests[i].Repository != item.Status.PullRequests[j].Repository {
			return item.Status.PullRequests[i].Repository < item.Status.PullRequests[j].Repository
		}
		if item.Status.PullRequests[i].Number != item.Status.PullRequests[j].Number {
			return item.Status.PullRequests[i].Number < item.Status.PullRequests[j].Number
		}
		// Two monitors can observe the same pull request (for example a manual
		// recovery monitor next to the canonical controller-created one). The
		// monitor list is read from the informer cache in arbitrary order, so
		// without a total order the tied entries would flip between passes and
		// spuriously advance the projection sequence.
		return item.Status.PullRequests[i].IntentName < item.Status.PullRequests[j].IntentName
	})
}

func maintainerPRProjection(monitor *triggersv1alpha1.PullRequestMonitor) triggersv1alpha1.MaintainerWorkItemPullRequestProjection {
	p := triggersv1alpha1.MaintainerWorkItemPullRequestProjection{Repository: monitor.Spec.Repository, Number: monitor.Spec.Number, IntentName: monitor.Name, MonitorRef: &corev1.LocalObjectReference{Name: monitor.Name}, URL: monitor.Spec.URL, HeadSHA: monitor.Status.HeadSHA, Draft: monitor.Status.Lifecycle == triggersv1alpha1.PullRequestLifecycleDraft, ReviewDecision: string(monitor.Status.ReviewDecision), HeadObservedAt: timePtr(monitor.Status.PullObservedAt), ReviewObservedAt: timePtr(monitor.Status.ReviewsObservedAt), ChecksObservedAt: timePtr(monitor.Status.Checks.ObservedAt), StatusesObservedAt: timePtr(monitor.Status.Statuses.ObservedAt), ObservationError: monitor.Status.LastError}
	if monitor.Status.LastReviewCursor != nil {
		p.LastReviewID = monitor.Status.LastReviewCursor.ID
	}
	if monitor.Status.LastIssueCommentCursor != nil {
		p.LastCommentID = monitor.Status.LastIssueCommentCursor.ID
	}
	readyCondition := meta.FindStatusCondition(monitor.Status.Conditions, triggersv1alpha1.ConditionPullRequestMonitorReady)
	p.Fresh = readyCondition != nil && readyCondition.Status == metav1.ConditionTrue && monitor.Status.LastError == "" && monitor.Status.HeadSHA != "" && monitor.Status.Checks.HeadSHA == monitor.Status.HeadSHA && monitor.Status.Statuses.HeadSHA == monitor.Status.HeadSHA
	switch monitor.Status.Lifecycle {
	case triggersv1alpha1.PullRequestLifecycleMerged:
		p.State = triggersv1alpha1.MaintainerWorkItemPullRequestStateMerged
		p.MergedAt = timePtr(monitor.Status.MergedAt)
	case triggersv1alpha1.PullRequestLifecycleClosed:
		p.State = triggersv1alpha1.MaintainerWorkItemPullRequestStateClosed
	default:
		p.State = triggersv1alpha1.MaintainerWorkItemPullRequestStateOpen
	}
	switch monitor.Status.Mergeability {
	case triggersv1alpha1.PullRequestMergeabilityMergeable:
		value := true
		p.Mergeable = &value
	case triggersv1alpha1.PullRequestMergeabilityConflicting:
		value := false
		p.Mergeable = &value
	}
	if monitor.Status.Checks.HeadSHA != monitor.Status.HeadSHA || monitor.Status.Statuses.HeadSHA != monitor.Status.HeadSHA {
		p.CheckState = triggersv1alpha1.MaintainerWorkItemCheckStateUnknown
	} else if monitor.Status.Checks.Error != "" || monitor.Status.Statuses.Error != "" || monitor.Status.Checks.State == gitHubRollupFailure || monitor.Status.Statuses.State == gitHubRollupFailure {
		p.CheckState = triggersv1alpha1.MaintainerWorkItemCheckStateFailing
	} else if monitor.Status.Checks.State == gitHubRollupPending || monitor.Status.Statuses.State == gitHubRollupPending {
		p.CheckState = triggersv1alpha1.MaintainerWorkItemCheckStatePending
	} else if monitor.Status.Checks.State == gitHubRollupNone && monitor.Status.Statuses.State == gitHubRollupNone && monitor.Status.Checks.Count+monitor.Status.Statuses.Count == 0 {
		p.CheckState = triggersv1alpha1.MaintainerWorkItemCheckStateNone
	} else if (monitor.Status.Checks.State == gitHubRollupSuccess || monitor.Status.Checks.State == gitHubRollupNone) && (monitor.Status.Statuses.State == gitHubRollupSuccess || monitor.Status.Statuses.State == gitHubRollupNone) && monitor.Status.Checks.Count+monitor.Status.Statuses.Count > 0 {
		p.CheckState = triggersv1alpha1.MaintainerWorkItemCheckStatePassing
	} else {
		p.CheckState = triggersv1alpha1.MaintainerWorkItemCheckStateUnknown
	}
	return p
}
func timePtr(value metav1.Time) *metav1.Time {
	if value.IsZero() {
		return nil
	}
	result := value
	return &result
}

//nolint:gocyclo // Readiness is a fail-closed conjunction over independently projected facts.
func evaluateMaintainerReadiness(item *triggersv1alpha1.MaintainerWorkItem, now time.Time, fullControl bool) {
	requireApproval := !fullControl
	unmet := []string{}
	dependenciesReady := true
	projectedDependencies := make(map[string]struct{}, len(item.Status.Dependencies))
	for _, dep := range item.Status.Dependencies {
		projectedDependencies[dep.Name] = struct{}{}
		if !dep.Delivered {
			dependenciesReady = false
			unmet = append(unmet, "dependency "+dep.Name+" is not delivered")
		}
	}
	if len(item.Spec.Dependencies) != len(item.Status.Dependencies) {
		dependenciesReady = false
		unmet = append(unmet, "dependency projection has not observed the complete graph")
	} else {
		for _, dependency := range item.Spec.Dependencies {
			if _, projected := projectedDependencies[dependency.Name]; !projected {
				dependenciesReady = false
				unmet = append(unmet, "dependency "+dependency.Name+" is not projected")
			}
		}
	}
	childrenReady := true
	for _, child := range item.Status.Children {
		if !child.Delivered {
			childrenReady = false
			unmet = append(unmet, "child "+child.Name+" is not delivered")
		}
	}
	if item.Status.PendingDecision != nil {
		unmet = append(unmet, "pending decision "+item.Status.PendingDecision.ID)
	}
	graphConfigured := item.Spec.GraphConfiguredByCommand != nil
	if !graphConfigured && item.Spec.Disposition != "" && item.Spec.Disposition != triggersv1alpha1.MaintainerWorkItemDispositionNotActionable {
		unmet = append(unmet, "work-item graph has not been explicitly configured")
	}
	readyToDispatch := graphConfigured && dependenciesReady && item.Status.PendingDecision == nil && item.Status.DispatchReservation == nil && item.Spec.Disposition != "" && item.Spec.Disposition != triggersv1alpha1.MaintainerWorkItemDispositionNotActionable
	openCandidate, mergeBlocked := false, false
	for _, pr := range item.Status.PullRequests {
		identity := fmt.Sprintf("%s#%d", pr.Repository, pr.Number)
		if pr.MonitorRef == nil || pr.Repository == "" || pr.Number < 1 {
			mergeBlocked = true
			unmet = append(unmet, "pull request projection "+pr.IntentName+" has no usable monitor")
			continue
		}
		if pr.State == triggersv1alpha1.MaintainerWorkItemPullRequestStateMerged {
			continue
		}
		// A closed, unmerged pull request was superseded or abandoned. It is not
		// merge work and must not permanently block merge or delivery.
		if pr.State == triggersv1alpha1.MaintainerWorkItemPullRequestStateClosed {
			continue
		}
		openCandidate = true
		approvalMissing := requireApproval && !strings.EqualFold(pr.ReviewDecision, string(triggersv1alpha1.PullRequestReviewDecisionApproved))
		changesRequested := strings.EqualFold(pr.ReviewDecision, string(triggersv1alpha1.PullRequestReviewDecisionChangesRequested))
		// A zero-check projection is only a candidate for controller-side policy
		// verification. It must not make asynchronous readiness true on its own.
		checksSatisfied := pr.CheckState == triggersv1alpha1.MaintainerWorkItemCheckStatePassing
		if !pr.Fresh || pr.ObservationError != "" || pr.Draft || pr.Mergeable == nil || !*pr.Mergeable || approvalMissing || changesRequested || !checksSatisfied || pr.HeadObservedAt == nil || pr.ReviewObservedAt == nil || pr.ChecksObservedAt == nil || pr.StatusesObservedAt == nil || now.Sub(pr.HeadObservedAt.Time) > maintainerProjectionFreshness || now.Sub(pr.ReviewObservedAt.Time) > maintainerProjectionFreshness || now.Sub(pr.ChecksObservedAt.Time) > maintainerProjectionFreshness || now.Sub(pr.StatusesObservedAt.Time) > maintainerProjectionFreshness {
			mergeBlocked = true
			unmet = append(unmet, identity+" is incomplete, stale, or not merge-ready")
		}
	}
	readyToMerge := openCandidate && !mergeBlocked
	allMerged := allProjectedPRsMerged(item.Status.PullRequests)
	deliveryReady := item.Status.DeliveryAttestation != nil && item.Status.DeliveryAttestation.CompletedAt != nil && dependenciesReady && childrenReady && (allMerged || len(item.Status.PullRequests) == 0 && len(item.Status.Children) > 0)
	if allMerged {
		readyToMerge = false
	}
	observed := metav1.NewTime(now)
	item.Status.Readiness = &triggersv1alpha1.MaintainerWorkItemReadiness{ReadyToDispatch: readyToDispatch, ReadyToMerge: readyToMerge, UnmetRequirements: unmet, ObservedAt: &observed}
	meta.SetStatusCondition(&item.Status.Conditions, metav1.Condition{Type: triggersv1alpha1.ConditionMaintainerWorkItemDependenciesReady, Status: boolCondition(dependenciesReady), Reason: conditionReason(dependenciesReady, "Delivered", "Blocked"), ObservedGeneration: item.Generation, LastTransitionTime: observed})
	meta.SetStatusCondition(&item.Status.Conditions, metav1.Condition{Type: triggersv1alpha1.ConditionMaintainerWorkItemReadyToMerge, Status: boolCondition(readyToMerge), Reason: conditionReason(readyToMerge, "Ready", "RequirementsNotMet"), ObservedGeneration: item.Generation, LastTransitionTime: observed})
	if item.Status.PendingDecision != nil {
		item.Status.Phase = triggersv1alpha1.MaintainerWorkItemPhaseAwaitingDecision
	} else if deliveryReady {
		item.Status.Phase = triggersv1alpha1.MaintainerWorkItemPhaseDelivered
	} else if readyToMerge {
		item.Status.Phase = triggersv1alpha1.MaintainerWorkItemPhaseReadyToMerge
	} else if hasActiveImplementer(item.Status.AgentRuns) {
		item.Status.Phase = triggersv1alpha1.MaintainerWorkItemPhaseImplementing
	} else if item.Status.DispatchReservation != nil {
		item.Status.Phase = triggersv1alpha1.MaintainerWorkItemPhaseDispatched
	} else if readyToDispatch {
		item.Status.Phase = triggersv1alpha1.MaintainerWorkItemPhaseReadyToDispatch
	} else if item.Spec.Disposition != "" {
		item.Status.Phase = triggersv1alpha1.MaintainerWorkItemPhaseTriaged
	} else {
		item.Status.Phase = triggersv1alpha1.MaintainerWorkItemPhasePendingTriage
	}
}
func boolCondition(value bool) metav1.ConditionStatus {
	if value {
		return metav1.ConditionTrue
	}
	return metav1.ConditionFalse
}
func conditionReason(value bool, yes, no string) string {
	if value {
		return yes
	}
	return no
}

// allProjectedPRsMerged reports whether the work item shipped: at least one
// projected pull request is merged and none is still open. Closed, unmerged
// pull requests were superseded and are not delivery obligations.
func allProjectedPRsMerged(prs []triggersv1alpha1.MaintainerWorkItemPullRequestProjection) bool {
	merged := false
	for _, pr := range prs {
		switch pr.State {
		case triggersv1alpha1.MaintainerWorkItemPullRequestStateMerged:
			merged = true
		case triggersv1alpha1.MaintainerWorkItemPullRequestStateClosed:
		default:
			return false
		}
	}
	return merged
}
func hasActiveImplementer(runs []triggersv1alpha1.MaintainerWorkItemAgentRunProjection) bool {
	for _, run := range runs {
		if run.Role == triggersv1alpha1.MaintainerWorkItemAgentRunRoleImplementer && run.Phase != string(platformv1alpha1.AgentRunPhaseSucceeded) && run.Phase != string(platformv1alpha1.AgentRunPhaseFailed) && run.Phase != string(platformv1alpha1.AgentRunPhaseCancelled) {
			return true
		}
	}
	return false
}

package triggers

import (
	"context"
	"fmt"
	"strings"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
	"github.com/gratefulagents/gratefulagents/internal/orchestration"
	"sigs.k8s.io/controller-runtime/pkg/client"
	logf "sigs.k8s.io/controller-runtime/pkg/log"
)

// notifyOpenFleetPullRequestsAfterMerge tells every sibling work item's active
// implementer that the base branch moved, so it merges the base into its own
// branch instead of waiting for the maintainer LLM to notice a conflict.
// Delivery is idempotent per (merged head, open PR); failures are logged only
// because the merge itself is already durably recorded.
func (r *GitHubRepositoryReconciler) notifyOpenFleetPullRequestsAfterMerge(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, mergedItem *triggersv1alpha1.MaintainerWorkItem, mergedRepository string, mergedNumber int32, mergedHead, baseBranch string) {
	if r.StateStore == nil || repository == nil || mergedItem == nil {
		return
	}
	log := logf.FromContext(ctx).WithValues("repository", repository.Name, "mergedPullRequest", mergedNumber, "mergedHead", mergedHead)
	baseBranch = strings.TrimSpace(baseBranch)
	if baseBranch == "" {
		baseBranch = strings.TrimSpace(repository.Spec.Defaults.BaseBranch)
	}
	if baseBranch == "" {
		baseBranch = "main"
	}
	items := &triggersv1alpha1.MaintainerWorkItemList{}
	if err := r.maintainerReader().List(ctx, items, client.InNamespace(repository.Namespace)); err != nil {
		log.Error(err, "failed to list sibling work items for post-merge rebase notification")
		return
	}
	for i := range items.Items {
		sibling := &items.Items[i]
		if sibling.Name == mergedItem.Name || sibling.Spec.RepositoryRef.Name != repository.Name || !sibling.DeletionTimestamp.IsZero() {
			continue
		}
		for _, run := range sibling.Status.AgentRuns {
			if run.Role != triggersv1alpha1.MaintainerWorkItemAgentRunRoleImplementer || agentRunPhaseTerminal(run.Phase) {
				continue
			}
			for _, pull := range sibling.Status.PullRequests {
				if pull.Number == 0 || pull.State != triggersv1alpha1.MaintainerWorkItemPullRequestStateOpen || pull.MergedAt != nil {
					continue
				}
				if !strings.EqualFold(pull.Repository, mergedRepository) {
					continue
				}
				deliveryID := fmt.Sprintf("maintainer-rebase-%s-%d", shortSHA(mergedHead), pull.Number)
				message := postMergeRebaseMessage(mergedNumber, mergedHead, baseBranch, pull.Number, pull.HeadSHA)
				if err := orchestration.WakeOrNudgeAgentRunOnce(ctx, r.Client, r.StateStore, sibling.Namespace, run.Name, message, deliveryID); err != nil {
					log.Error(err, "failed to deliver post-merge rebase notification", "workItem", sibling.Name, "agentRun", run.Name, "pullRequest", pull.Number)
				}
			}
		}
	}
}

func postMergeRebaseMessage(mergedNumber int32, mergedHead, baseBranch string, openNumber int32, openHead string) string {
	return fmt.Sprintf("[maintainer] %s moved — PR #%d merged at %s into %s. Your PR #%d (head %s) may now conflict with %s or be stale. Merge origin/%s into your branch now: run git_merge with branch %q, resolve any conflicts, re-run the project's verification, then git_push and finish. Do not open a new PR.",
		baseBranch, mergedNumber, shortSHA(mergedHead), baseBranch, openNumber, shortSHA(openHead), baseBranch, baseBranch, baseBranch)
}

func agentRunPhaseTerminal(phase string) bool {
	switch platformv1alpha1.AgentRunPhase(phase) {
	case platformv1alpha1.AgentRunPhaseSucceeded, platformv1alpha1.AgentRunPhaseFailed, platformv1alpha1.AgentRunPhaseCancelled:
		return true
	default:
		return false
	}
}

func shortSHA(sha string) string {
	sha = strings.TrimSpace(sha)
	if len(sha) > 12 {
		return sha[:12]
	}
	if sha == "" {
		return "unknown"
	}
	return sha
}

package triggers

import (
	"context"
	"strings"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

// ModeExistsFunc returns true if a mode template with the given spec.name exists
// in the cluster. Callers build this from a k8s client.Reader.
type ModeExistsFunc func(name string) bool

// ModeExistsFromK8s returns a ModeExistsFunc that checks the cluster for a
// ModeTemplate CRD with the given name. Results are cached within the
// returned function so repeated lookups for the same name are free.
func ModeExistsFromK8s(ctx context.Context, c client.Reader) ModeExistsFunc {
	cache := map[string]bool{}
	return func(name string) bool {
		if hit, ok := cache[name]; ok {
			return hit
		}
		var crd platformv1alpha1.ModeTemplate
		exists := c.Get(ctx, client.ObjectKey{Name: name}, &crd) == nil
		cache[name] = exists
		return exists
	}
}

// ResolveModeFromText parses text for a mode prefix like "mode:NAME" or "/NAME".
// Returns a ModeRef if found, nil otherwise.
func ResolveModeFromText(text string, modeExists ModeExistsFunc) *platformv1alpha1.ModeRef {
	trimmed := strings.TrimSpace(text)
	if trimmed == "" {
		return nil
	}

	// Check for "mode:NAME ..." prefix.
	if strings.HasPrefix(strings.ToLower(trimmed), "mode:") {
		rest := trimmed[5:]
		parts := strings.SplitN(rest, " ", 2)
		name := strings.ToLower(strings.TrimSpace(parts[0]))
		if modeExists(name) {
			return &platformv1alpha1.ModeRef{Name: name}
		}
	}

	// Check for "/NAME ..." prefix.
	if strings.HasPrefix(trimmed, "/") {
		rest := trimmed[1:]
		parts := strings.SplitN(rest, " ", 2)
		name := strings.ToLower(strings.TrimSpace(parts[0]))
		if modeExists(name) {
			return &platformv1alpha1.ModeRef{Name: name}
		}
	}

	return nil
}

// StripModePrefix removes a mode prefix ("mode:NAME " or "/NAME ") from text.
// Returns the original text if no mode prefix is found.
func StripModePrefix(text string, modeExists ModeExistsFunc) string {
	trimmed := strings.TrimSpace(text)
	if trimmed == "" {
		return text
	}

	lower := strings.ToLower(trimmed)
	if strings.HasPrefix(lower, "mode:") {
		rest := trimmed[5:]
		parts := strings.SplitN(rest, " ", 2)
		name := strings.ToLower(strings.TrimSpace(parts[0]))
		if modeExists(name) {
			if len(parts) > 1 {
				return strings.TrimSpace(parts[1])
			}
			return ""
		}
	}

	if strings.HasPrefix(trimmed, "/") {
		rest := trimmed[1:]
		parts := strings.SplitN(rest, " ", 2)
		name := strings.ToLower(strings.TrimSpace(parts[0]))
		if modeExists(name) {
			if len(parts) > 1 {
				return strings.TrimSpace(parts[1])
			}
			return ""
		}
	}

	return text
}

// ResolveModeFromLabels scans a list of labels for a known mode template name.
// Returns the first match as a ModeRef, nil if none found.
func ResolveModeFromLabels(labels []string, modeExists ModeExistsFunc) *platformv1alpha1.ModeRef {
	for _, label := range labels {
		name := strings.ToLower(strings.TrimSpace(label))
		if modeExists(name) {
			return &platformv1alpha1.ModeRef{Name: name}
		}
	}
	return nil
}

// MergeModeRef returns the highest-priority non-nil ModeRef.
// Priority: textMode > labelMode > defaultMode.
func MergeModeRef(textMode, labelMode, defaultMode *platformv1alpha1.ModeRef) *platformv1alpha1.ModeRef {
	if textMode != nil {
		return textMode
	}
	if labelMode != nil {
		return labelMode
	}
	return defaultMode
}

// prefixModelWithProvider normalizes a model name for storage on an AgentRun.
// When the provider is "openai" (the default), the model is stored bare
// (e.g. "gpt-5.4"), stripping any "openai/" prefix the user may have set.
// For non-openai providers the "provider/" prefix is added when absent.
func prefixModelWithProvider(model, provider string) string {
	return triggersv1alpha1.PrefixModelWithProvider(model, provider)
}

package triggers

import (
	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
)

// applyPolicyRefs copies RuntimeProfileRef, MCPPolicyRef, MCPServerRefs,
// SkillRefs, the command-sandbox opt-out, the Kubernetes-admin grant, and the
// run timeout from AgentRunDefaults onto the AgentRunSpec.
func applyPolicyRefs(spec *platformv1alpha1.AgentRunSpec, defaults triggersv1alpha1.AgentRunDefaults) {
	if defaults.RuntimeProfileRef != nil {
		spec.RuntimeProfileRef = defaults.RuntimeProfileRef.DeepCopy()
	}
	if defaults.DisableCommandSandbox {
		spec.DisableCommandSandbox = true
	}
	if defaults.KubernetesAdmin {
		spec.KubernetesAdmin = true
	}
	if defaults.DockerInDocker {
		spec.DockerInDocker = true
	}
	// defaults.timeout documents "the maximum duration for created AgentRuns";
	// map it onto the run's enforced limit unless the caller already set one.
	if defaults.Timeout.Duration > 0 && (spec.Limits == nil || spec.Limits.MaxRuntime.Duration == 0) {
		if spec.Limits == nil {
			spec.Limits = &platformv1alpha1.AgentRunLimits{}
		}
		spec.Limits.MaxRuntime = defaults.Timeout
	}
	if defaults.MCPPolicyRef != nil {
		spec.MCPPolicyRef = defaults.MCPPolicyRef.DeepCopy()
	}
	if defaults.SSHTunnelRef != nil {
		spec.SSHTunnelRef = defaults.SSHTunnelRef.DeepCopy()
	}
	if len(defaults.MCPServerRefs) > 0 {
		refs := make([]platformv1alpha1.NamedRef, len(defaults.MCPServerRefs))
		copy(refs, defaults.MCPServerRefs)
		spec.MCPServerRefs = refs
	}
	if len(defaults.SkillRefs) > 0 {
		refs := make([]platformv1alpha1.NamedRef, len(defaults.SkillRefs))
		copy(refs, defaults.SkillRefs)
		spec.SkillRefs = refs
	}
}

package triggers

import (
	"context"
	"fmt"
	"strings"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
	"github.com/gratefulagents/gratefulagents/internal/orchestration"
	"github.com/gratefulagents/gratefulagents/internal/store"
	corev1 "k8s.io/api/core/v1"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/client-go/tools/record"
	ctrl "sigs.k8s.io/controller-runtime"
	"sigs.k8s.io/controller-runtime/pkg/client"
	logf "sigs.k8s.io/controller-runtime/pkg/log"
)

// Labels and annotations tracking the autonomous PR review loop. The loop
// state machine is derived from these markers — there is no separate store.
const (
	// PRLoopStateLabel marks an implementer AgentRun as participating in the
	// loop. Values: in_review, resolving, approved, blocked.
	PRLoopStateLabel = "triggers.gratefulagents.dev/pr-loop"
	// PRLoopRoleLabel marks reviewer AgentRuns created by the loop.
	PRLoopRoleLabel = triggersv1alpha1.PRLoopRoleLabelKey
	// PRLoopNumberLabel carries the PR number on implementer runs so comment
	// events (which lack the head ref) can find the linked run.
	PRLoopNumberLabel = "triggers.gratefulagents.dev/pr-number"

	// PRLoopURLAnnotation, PRLoopBaseRefAnnotation and PRLoopRoundAnnotation
	// snapshot PR coordinates and progress on the implementer run.
	PRLoopURLAnnotation       = "triggers.gratefulagents.dev/pr-url"
	PRLoopBaseRefAnnotation   = "triggers.gratefulagents.dev/pr-base-ref"
	PRLoopRoundAnnotation     = "triggers.gratefulagents.dev/review-round"
	PRLoopMaxRoundsAnnotation = "triggers.gratefulagents.dev/review-max-rounds"
	// PRLoopOptAnnotation is the trigger-independent, per-run loop policy.
	// The loop is disabled by default; set it to "enabled" before opening a PR
	// to opt that run in. "disabled" remains an explicit opt-out.
	PRLoopOptAnnotation = "triggers.gratefulagents.dev/review-loop"
	PRLoopOptEnabled    = "enabled"
	PRLoopOptDisabled   = "disabled"
	// PRLoopImplementerAnnotation points a reviewer run back at the
	// implementer run it reviews.
	PRLoopImplementerAnnotation = "triggers.gratefulagents.dev/pr-loop-implementer"
	// PRLoopRepositoryAnnotation names the GitHubRepository that owns the loop.
	PRLoopRepositoryAnnotation = "triggers.gratefulagents.dev/pr-loop-repository"
	// PRLoopVerdictHandledAnnotation marks a reviewer run whose verdict has
	// been consumed by the loop reconciler (idempotency guard).
	PRLoopVerdictHandledAnnotation = "triggers.gratefulagents.dev/verdict-handled"
)

// PR loop states stored in PRLoopStateLabel.
const (
	PRLoopStateInReview  = "in_review"
	PRLoopStateResolving = "resolving"
	PRLoopStateApproved  = "approved"
	PRLoopStateBlocked   = "blocked"
)

const (
	// PRLoopRoleReviewer is the PRLoopRoleLabel value for reviewer runs.
	PRLoopRoleReviewer = triggersv1alpha1.PRLoopRoleReviewerValue
	// defaultMaxReviewRounds caps automatic review/resolve cycles per PR.
	defaultMaxReviewRounds = 3
	// defaultReviewerModeName is the ModeTemplate used for reviewer runs when
	// the GitHubRepository does not override it.
	defaultReviewerModeName = "review"
	openAIAPIModeAnnotation = "platform.gratefulagents.dev/openai-api-mode"
)

// PRLoopEngine drives the autonomous loop:
//
//	issue → implementer run → PR opened → reviewer run → verdict
//	  approve          → loop approved (human merges)
//	  request_changes  → wake implementer (resume session) → push fixes →
//	                     implementer finishes → next review round → …
//
// It consumes normalized webhook events (PullRequestEventSink) and is driven
// by run completions via the PRLoopReconciler. Loop-runaway protection:
// reviewer rounds are only spawned from run completions (never from
// synchronize events), self-authored GitHub reviews are ignored, reviewer run
// names are deterministic per round, and rounds are capped.
type PRLoopEngine struct {
	client.Client
	Scheme     *runtime.Scheme
	StateStore store.StateStore
	Recorder   record.EventRecorder
	// GitHubAppMinter mints installation tokens for reviewer runs when the
	// owning GitHubRepository uses App auth. Nil falls back to a fresh minter.
	GitHubAppMinter gitHubAppTokenMinter
}

var _ PullRequestEventSink = (*PRLoopEngine)(nil)

// HandlePullRequestEvent routes normalized webhook events into the loop. gh is
// optional for app deliveries; event.Repository then supplies owner/name.
func (e *PRLoopEngine) HandlePullRequestEvent(ctx context.Context, gh *triggersv1alpha1.GitHubRepository, event PullRequestEvent) (bool, error) {
	if event.Repository == "" && gh != nil {
		event.Repository = strings.TrimSpace(gh.Spec.Owner) + "/" + strings.TrimSpace(gh.Spec.Repo)
	}
	switch event.Type {
	case PREventOpened:
		return e.handlePROpened(ctx, gh, event)
	case PREventReviewSubmitted:
		return e.handleReviewSubmitted(ctx, gh, event)
	case PREventComment:
		return e.handlePRComment(ctx, gh, event)
	default:
		// synchronize / review_comment are intentionally ignored: review
		// rounds are driven by run completions, and inline comments arrive
		// alongside their review submission.
		return false, nil
	}
}

// handlePROpened links an agent-created PR to its implementer run and starts
// review round 1. PRs whose head branch does not match an AgentRun are not
// part of the loop (human PRs).
func (e *PRLoopEngine) handlePROpened(ctx context.Context, gh *triggersv1alpha1.GitHubRepository, event PullRequestEvent) (bool, error) {
	implementer, err := e.implementerForPullRequestEvent(ctx, event, false)
	if err == nil && implementer == nil {
		implementer, err = e.findImplementerByHead(ctx, gh, event.Repository, event.URL, event.HeadRef)
	}
	if err != nil || implementer == nil {
		return false, err
	}
	cfg, err := e.resolveLoopConfig(ctx, gh, implementer, event.Repository, event.BaseRef)
	if err != nil {
		return false, err
	}
	if cfg.Disabled {
		return false, nil
	}

	loop := loopRecordForEvent(event)
	if hasLoopRecord(implementer, loop.Key) {
		return true, nil // already in the loop (redelivery or reopen)
	}
	if err := e.patchLoopMarkers(ctx, implementer, loop.Key, PRLoopStateInReview, func(run *platformv1alpha1.AgentRun) {
		setLoopLabel(run, loop.Key, PRLoopNumberLabel, fmt.Sprintf("%d", event.Number))
		setLoopAnnotation(run, loop.Key, PRLoopURLAnnotation, event.URL)
		setLoopAnnotation(run, loop.Key, PRLoopBaseRefAnnotation, event.BaseRef)
		setLoopAnnotation(run, loop.Key, PRLoopRoundAnnotation, "1")
		setLoopAnnotation(run, loop.Key, PRLoopMaxRoundsAnnotation, fmt.Sprintf("%d", cfg.MaxRounds))
		setLoopAnnotation(run, loop.Key, PRLoopRepositoryAnnotation, cfg.RepositoryName)
	}); err != nil {
		return false, err
	}

	if err := e.createReviewerRun(ctx, cfg, implementer, loop, event.Title, 1); err != nil {
		return false, err
	}
	e.eventf(implementer, "PRLoopReviewStarted", "Started review round 1 for %s", event.URL)
	return true, nil
}

// handleReviewSubmitted reacts to GitHub reviews from OTHER identities
// (humans, or a differently-authenticated reviewer). Reviews posted through
// the run's own token share the PR author's identity and are ignored here —
// those verdicts travel through submit_review_verdict instead.
func (e *PRLoopEngine) handleReviewSubmitted(ctx context.Context, gh *triggersv1alpha1.GitHubRepository, event PullRequestEvent) (bool, error) {
	if event.SenderLogin == "" || event.SenderLogin == event.AuthorLogin {
		return false, nil
	}
	var auth *triggersv1alpha1.TriggerAuth
	if gh != nil {
		auth = gh.Spec.Auth
	}
	if !auth.IsGitHubActorAllowed(event.SenderLogin, event.SenderAuthorAssociation) {
		if gh != nil {
			recordTriggerActorRejected(ctx, e.Client, e.Recorder, gh, event.SenderLogin, event.SenderAuthorAssociation)
		}
		return false, nil
	}
	loopKey := prLoopKey(event.Repository, event.Number)
	implementer, err := e.implementerForPullRequestEvent(ctx, event, true)
	if err == nil && implementer == nil {
		implementer, loopKey, err = e.findImplementerByPR(ctx, gh, event.Repository, event.Number)
	}
	if err != nil || implementer == nil {
		return false, err
	}
	if state := loopState(implementer, loopKey, PRLoopStateLabel); state == PRLoopStateApproved || state == PRLoopStateBlocked {
		return true, nil
	}
	if externalPREventHandled(implementer, loopKey, event) {
		return true, nil
	}

	state := strings.ToLower(strings.TrimSpace(event.ReviewState))
	switch state {
	case "approved":
		if err := e.patchLoopMarkers(ctx, implementer, loopKey, PRLoopStateApproved, func(run *platformv1alpha1.AgentRun) {
			markExternalPREvent(run, loopKey, event)
		}); err != nil {
			return false, err
		}
		e.eventf(implementer, "PRLoopApproved", "PR #%d approved by %s — ready for human merge", event.Number, event.SenderLogin)
		return true, nil
	case "changes_requested", "commented":
		if state == "commented" && strings.TrimSpace(event.Body) == "" {
			return false, nil
		}
		msg := fmt.Sprintf(
			"GitHub review feedback on your pull request #%d (%s) from @%s (%s):\n\n%s\n\n"+
				"Address this feedback on your existing branch: inspect unresolved threads with "+
				"list_review_threads, make the fixes, push, reply to and resolve each thread, "+
				"then finish.",
			event.Number, event.URL, event.SenderLogin, state, event.Body)
		if err := e.wakeImplementerForPREvent(ctx, implementer, loopKey, PRLoopStateResolving, msg, event); err != nil {
			return false, err
		}
		return true, nil
	default:
		return false, nil
	}
}

// handlePRComment wakes the implementer when someone mentions the trigger
// keyword on its PR.
func (e *PRLoopEngine) handlePRComment(ctx context.Context, gh *triggersv1alpha1.GitHubRepository, event PullRequestEvent) (bool, error) {
	keyword := "@agent"
	if gh != nil && strings.TrimSpace(gh.Spec.TriggerKeyword) != "" {
		keyword = gh.Spec.TriggerKeyword
	}
	if !strings.Contains(strings.ToLower(event.Body), strings.ToLower(keyword)) {
		return false, nil
	}
	var auth *triggersv1alpha1.TriggerAuth
	if gh != nil {
		auth = gh.Spec.Auth
	}
	if !auth.IsGitHubActorAllowed(event.SenderLogin, event.SenderAuthorAssociation) {
		if gh != nil {
			recordTriggerActorRejected(ctx, e.Client, e.Recorder, gh, event.SenderLogin, event.SenderAuthorAssociation)
		}
		return false, nil
	}
	loopKey := prLoopKey(event.Repository, event.Number)
	implementer, err := e.implementerForPullRequestEvent(ctx, event, true)
	if err == nil && implementer == nil {
		implementer, loopKey, err = e.findImplementerByPR(ctx, gh, event.Repository, event.Number)
	}
	if err != nil || implementer == nil {
		return false, err
	}
	if state := loopState(implementer, loopKey, PRLoopStateLabel); state == PRLoopStateApproved || state == PRLoopStateBlocked {
		return true, nil
	}
	if externalPREventHandled(implementer, loopKey, event) {
		return true, nil
	}
	body := strings.TrimSpace(strings.Replace(event.Body, keyword, "", 1))
	if body == "" {
		body = "Please review the latest feedback on the pull request and address it."
	}
	msg := fmt.Sprintf("Comment from @%s on your pull request #%d (%s):\n\n%s",
		event.SenderLogin, event.Number, event.URL, body)
	if err := e.wakeImplementerForPREvent(ctx, implementer, loopKey, PRLoopStateResolving, msg, event); err != nil {
		return false, err
	}
	return true, nil
}

// OnReviewerRunCompleted consumes a finished reviewer run's verdict and either
// approves the loop or wakes the implementer for the next resolve cycle.
func (e *PRLoopEngine) OnReviewerRunCompleted(ctx context.Context, reviewer *platformv1alpha1.AgentRun) error {
	log := logf.FromContext(ctx)
	if reviewer.Annotations[PRLoopVerdictHandledAnnotation] == "true" {
		return nil
	}
	implementerName := reviewer.Annotations[PRLoopImplementerAnnotation]
	if implementerName == "" {
		return nil
	}
	implementer := &platformv1alpha1.AgentRun{}
	if err := e.Get(ctx, client.ObjectKey{Namespace: reviewer.Namespace, Name: implementerName}, implementer); err != nil {
		if apierrors.IsNotFound(err) {
			return e.markVerdictHandled(ctx, reviewer)
		}
		return err
	}
	loopKey := strings.TrimSpace(reviewer.Annotations[PRLoopKeyAnnotation])
	loop := loopRecordFromRun(implementer, loopKey)
	currentState := loopState(implementer, loop.Key, PRLoopStateLabel)
	if currentState == PRLoopStateApproved || currentState == PRLoopStateBlocked {
		return e.markVerdictHandled(ctx, reviewer)
	}

	verdict := reviewer.Annotations[platformv1alpha1.ReviewVerdictAnnotation]
	summary := strings.TrimSpace(reviewer.Annotations[platformv1alpha1.ReviewSummaryAnnotation])

	if reviewer.Status.Phase == platformv1alpha1.AgentRunPhaseFailed {
		// A crashed reviewer must not block the loop silently; surface it.
		if err := e.patchLoopMarkers(ctx, implementer, loop.Key, PRLoopStateBlocked, nil); err != nil {
			return err
		}
		e.eventf(implementer, "PRLoopBlocked", "Reviewer run %s failed; human attention required", reviewer.Name)
		e.escalateBlocked(ctx, implementer, fmt.Sprintf("The PR review loop is blocked: reviewer run %s failed. Review the PR manually or send guidance to continue.", reviewer.Name))
		return e.markVerdictHandled(ctx, reviewer)
	}

	switch verdict {
	case platformv1alpha1.ReviewVerdictApprove:
		if err := e.patchLoopMarkers(ctx, implementer, loop.Key, PRLoopStateApproved, nil); err != nil {
			return err
		}
		e.eventf(implementer, "PRLoopApproved", "Reviewer approved PR %s — ready for human merge", loop.URL)
	case platformv1alpha1.ReviewVerdictRequestChanges, "":
		if verdict == "" {
			log.Info("reviewer run completed without a verdict; treating as request_changes", "reviewer", reviewer.Name)
			summary = "The reviewer left feedback on the pull request but did not record a structured verdict."
		}
		round := annotationInt(loopAnnotation(implementer, loop.Key, PRLoopRoundAnnotation), 1)
		maxRounds := annotationInt(loopAnnotation(implementer, loop.Key, PRLoopMaxRoundsAnnotation), reviewLoopMaxRounds(e.lookupRepositoryForLoop(ctx, implementer, loop.Repository)))
		if round >= maxRounds {
			if err := e.patchLoopMarkers(ctx, implementer, loop.Key, PRLoopStateBlocked, nil); err != nil {
				return err
			}
			e.eventf(implementer, "PRLoopBlocked", "Review round cap (%d) reached without approval; human attention required", maxRounds)
			e.escalateBlocked(ctx, implementer, fmt.Sprintf(
				"The PR review loop is blocked after %d review rounds without approval on %s. Last reviewer summary: %s",
				maxRounds, loop.URL, summary))
		} else {
			msg := fmt.Sprintf(
				"Your pull request #%d (%s) was reviewed — changes requested (round %d of %d).\n\n"+
					"Reviewer summary:\n%s\n\n"+
					"Work on your existing branch: inspect every unresolved thread with "+
					"list_review_threads, address each finding, push your fixes, reply to and "+
					"resolve each thread with reply_to_review_thread/resolve_review_thread, then "+
					"finish. Another review round starts automatically.",
				loop.Number, loop.URL, round, maxRounds, summary)
			if err := e.wakeImplementer(ctx, implementer, loop.Key, PRLoopStateResolving, msg); err != nil {
				return err
			}
			e.eventf(implementer, "PRLoopChangesRequested", "Reviewer requested changes (round %d/%d); implementer woken", round, maxRounds)
		}
	}
	return e.markVerdictHandled(ctx, reviewer)
}

// OnImplementerRunCompleted starts the next review round after the implementer
// finishes a resolve cycle.
func (e *PRLoopEngine) OnImplementerRunCompleted(ctx context.Context, implementer *platformv1alpha1.AgentRun) error {
	for _, loop := range loopRecords(implementer) {
		if loopState(implementer, loop.Key, PRLoopStateLabel) != PRLoopStateResolving || loop.Number == 0 {
			continue
		}
		gh := e.lookupRepositoryForLoop(ctx, implementer, loop.Repository)
		cfg, err := e.resolveLoopConfig(ctx, gh, implementer, loop.Repository, loop.BaseRef)
		if err != nil {
			return err
		}
		if cfg.Disabled {
			continue
		}
		round := annotationInt(loopAnnotation(implementer, loop.Key, PRLoopRoundAnnotation), 1) + 1
		if err := e.patchLoopMarkers(ctx, implementer, loop.Key, PRLoopStateInReview, func(run *platformv1alpha1.AgentRun) {
			setLoopAnnotation(run, loop.Key, PRLoopRoundAnnotation, fmt.Sprintf("%d", round))
		}); err != nil {
			return err
		}
		if err := e.createReviewerRun(ctx, cfg, implementer, loop, "", round); err != nil {
			return err
		}
		e.eventf(implementer, "PRLoopReviewStarted", "Started review round %d for %s", round, loop.URL)
	}
	return nil
}

// wakeImplementer delivers context to the implementer run. Wakeable inactive
// runs are woken (fresh pod resumes the persisted session); active runs just
// receive the message, which the live pod picks up.
func (e *PRLoopEngine) wakeImplementer(ctx context.Context, implementer *platformv1alpha1.AgentRun, loopKey, newState, message string) error {
	if err := e.patchLoopMarkers(ctx, implementer, loopKey, newState, nil); err != nil {
		return err
	}
	switch implementer.Status.Phase {
	case platformv1alpha1.AgentRunPhaseSucceeded, platformv1alpha1.AgentRunPhaseFailed, platformv1alpha1.AgentRunPhasePaused:
		if err := orchestration.WakeAgentRun(ctx, e.Client, e.StateStore, implementer.Namespace, implementer.Name, message); err != nil {
			e.escalateBlocked(ctx, implementer, fmt.Sprintf("The PR review loop is blocked: failed to wake implementer run %s: %v", implementer.Name, err))
			return err
		}
		return nil
	case platformv1alpha1.AgentRunPhaseCancelled:
		e.escalateBlocked(ctx, implementer, fmt.Sprintf("The PR review loop is blocked: implementer run %s is cancelled and cannot be woken. Review the PR manually or start a new implementer run.", implementer.Name))
		return nil
	}
	if e.StateStore == nil {
		return fmt.Errorf("state store is required to message AgentRun %s/%s", implementer.Namespace, implementer.Name)
	}
	sess, err := e.StateStore.GetSessionByRun(ctx, implementer.Name, implementer.Namespace)
	if err != nil {
		return fmt.Errorf("getting session for AgentRun %s/%s: %w", implementer.Namespace, implementer.Name, err)
	}
	if _, err := e.StateStore.AppendMessage(ctx, sess.ID, "user", message, nil); err != nil {
		return fmt.Errorf("appending message for AgentRun %s/%s: %w", implementer.Namespace, implementer.Name, err)
	}
	return nil
}

// createReviewerRun provisions an autonomous, review-mode AgentRun for one
// review round. Names are deterministic per (implementer, PR, round), so one
// multi-repo run can review several PRs independently without collisions.
func (e *PRLoopEngine) createReviewerRun(ctx context.Context, cfg *prLoopConfig, implementer *platformv1alpha1.AgentRun, loop prLoopRecord, prTitle string, round int) error {
	runName := reviewerRunName(implementer.Name, loop.Key, round)
	annotations := copyStringMap(cfg.Annotations)
	if annotations == nil {
		annotations = map[string]string{}
	}
	annotations[PRLoopImplementerAnnotation] = implementer.Name
	annotations[PRLoopURLAnnotation] = loop.URL
	annotations[PRLoopRoundAnnotation] = fmt.Sprintf("%d", round)
	annotations[PRLoopRepositoryAnnotation] = cfg.RepositoryName
	annotations[PRLoopKeyAnnotation] = loop.Key
	if strings.TrimSpace(cfg.CustomInstructions) != "" {
		annotations["platform.gratefulagents.dev/instructions-configmap-ref"] = runName + "-instructions"
	}

	run := &platformv1alpha1.AgentRun{ObjectMeta: metav1.ObjectMeta{
		Name:            runName,
		Namespace:       implementer.Namespace,
		Finalizers:      []string{platformv1alpha1.AgentRunCleanupFinalizer},
		OwnerReferences: reviewerOwnerReferences(implementer),
		Labels: map[string]string{
			PRLoopRoleLabel:   PRLoopRoleReviewer,
			PRLoopNumberLabel: fmt.Sprintf("%d", loop.Number),
			triggersv1alpha1.MaintainerWorkItemNameLabelKey: implementer.Labels[triggersv1alpha1.MaintainerWorkItemNameLabelKey],
			triggersv1alpha1.MaintainerWorkItemUIDLabelKey:  implementer.Labels[triggersv1alpha1.MaintainerWorkItemUIDLabelKey],
		},
		Annotations: annotations,
	}}
	if cfg.Repository != nil {
		// GitHubRepository-sourced reviewers retain the existing lifecycle.
		// Fallback reviewers instead share the implementer's trigger owner;
		// owning them by the implementer would classify them as team children.
		run.OwnerReferences = nil
		if err := ctrl.SetControllerReference(cfg.Repository, run, e.Scheme); err != nil {
			return fmt.Errorf("setting repository owner reference on reviewer AgentRun: %w", err)
		}
	}
	var instructions *corev1.ConfigMap
	instructionsCreated := false
	if strings.TrimSpace(cfg.CustomInstructions) != "" {
		instructions = &corev1.ConfigMap{}
		key := client.ObjectKey{Namespace: run.Namespace, Name: runName + "-instructions"}
		if err := e.Get(ctx, key, instructions); apierrors.IsNotFound(err) {
			instructions = &corev1.ConfigMap{
				ObjectMeta: metav1.ObjectMeta{
					Name:            key.Name,
					Namespace:       key.Namespace,
					OwnerReferences: append([]metav1.OwnerReference(nil), run.OwnerReferences...),
				},
				Data: map[string]string{"instructions.md": cfg.CustomInstructions},
			}
			if err := e.Create(ctx, instructions); err != nil {
				return fmt.Errorf("creating reviewer instructions ConfigMap: %w", err)
			}
			instructionsCreated = true
		} else if err != nil {
			return fmt.Errorf("getting reviewer instructions ConfigMap: %w", err)
		} else {
			instructions.Data = map[string]string{"instructions.md": cfg.CustomInstructions}
			if err := e.Update(ctx, instructions); err != nil {
				return fmt.Errorf("updating reviewer instructions ConfigMap: %w", err)
			}
		}
	}

	run.Spec = *cfg.ReviewerSpec.DeepCopy()
	triggerKind, triggerName := "PRReviewLoop", implementer.Name
	if cfg.Repository != nil {
		// Preserve GitHubRepository identity so App-token refresh keeps working
		// for repository-configured reviewers.
		triggerKind, triggerName = gitHubRepositoryTriggerKind, cfg.Repository.Name
	}
	run.Spec.Trigger = platformv1alpha1.TriggerRef{
		Kind: triggerKind,
		Name: triggerName,
		ExternalRef: &platformv1alpha1.ExternalRef{
			ID:         fmt.Sprintf("%s-review-%d", loop.Key, round),
			Identifier: fmt.Sprintf("PR #%d review round %d", loop.Number, round),
			URL:        loop.URL,
		},
	}
	run.Spec.Context = &platformv1alpha1.AgentRunContext{ProjectRef: &platformv1alpha1.ProjectRef{Kind: "AgentRun", Name: implementer.Name}}
	run.Spec.ModeRef = cfg.ReviewerModeRef
	// For an additional-repository PR, make that repository the reviewer's
	// primary checkout so repo_path defaults remain intuitive.
	if repoURL := declaredRepositoryURL(implementer, loop.Repository); repoURL != "" {
		configuredAdditional := append([]string(nil), run.Spec.Repository.AdditionalRepos...)
		run.Spec.Repository.URL = repoURL
		run.Spec.Repository.AdditionalRepos = reviewerAdditionalRepositories(implementer, repoURL, configuredAdditional)
		run.Spec.Repository.BaseBranch = firstNonEmptyString(loop.BaseRef, run.Spec.Repository.BaseBranch)
	}
	if cfg.Repository != nil && cfg.Repository.Spec.GitHubApp != nil {
		if run.Spec.Secrets == nil {
			run.Spec.Secrets = &platformv1alpha1.AgentRunSecrets{}
		}
		run.Spec.Secrets.GitHubTokenSecret = runName + "-gh-token"
	}

	alreadyExists := false
	if err := e.Create(ctx, run); err != nil {
		if !apierrors.IsAlreadyExists(err) {
			if instructionsCreated {
				_ = e.Delete(ctx, instructions)
			}
			return fmt.Errorf("creating reviewer AgentRun: %w", err)
		}
		alreadyExists = true
		if err := e.Get(ctx, client.ObjectKeyFromObject(run), run); err != nil {
			return fmt.Errorf("getting existing reviewer AgentRun: %w", err)
		}
	}
	if instructions != nil {
		instructions.OwnerReferences = nil
		if err := ctrl.SetControllerReference(run, instructions, e.Scheme); err != nil {
			return fmt.Errorf("setting reviewer instructions owner reference: %w", err)
		}
		if err := e.Update(ctx, instructions); err != nil {
			return fmt.Errorf("updating reviewer instructions owner reference: %w", err)
		}
	}
	if cfg.Repository != nil && cfg.Repository.Spec.GitHubApp != nil {
		if err := ensureRunGitHubAppTokenSecret(ctx, e.Client, e.Scheme, cfg.Repository, run, e.GitHubAppMinter); err != nil {
			return fmt.Errorf("minting reviewer GitHub App token: %w", err)
		}
	}
	if alreadyExists {
		return nil
	}

	if e.StateStore != nil {
		task := reviewerTaskMessage(loop.Number, loop.URL, prTitle, implementer.Name, round)
		sess, err := e.StateStore.CreateSession(ctx, run.Name, run.Namespace, "pending", "setup")
		if err != nil {
			logf.FromContext(ctx).Error(err, "failed to create reviewer session", "run", run.Name)
		} else if _, err := e.StateStore.AppendMessage(ctx, sess.ID, "user", task, nil); err != nil {
			logf.FromContext(ctx).Error(err, "failed to seed reviewer task", "run", run.Name)
		}
	}
	return nil
}

func reviewerTaskMessage(prNumber int, prURL, prTitle, implementerName string, round int) string {
	title := strings.TrimSpace(prTitle)
	if title != "" {
		title = fmt.Sprintf(" (%q)", title)
	}
	return fmt.Sprintf(
		"You are the PR reviewer for review round %d of pull request #%d%s: %s\n\n"+
			"The PR was produced autonomously by agent run %q. Review it rigorously:\n"+
			"1. get_pull_request to read the description, changed files, and full diff.\n"+
			"2. Inspect the repository checkout for context around every changed area; "+
			"verify correctness, tests, security, and that the change actually fulfils its task.\n"+
			"3. list_review_threads to see earlier feedback; confirm prior findings were addressed.\n"+
			"4. Post your findings on GitHub with submit_pull_request_review "+
			"(event=COMMENT, inline comments on the exact lines; do not use APPROVE/REQUEST_CHANGES — "+
			"GitHub rejects self-reviews on same-identity PRs).\n"+
			"5. Record your structured verdict with submit_review_verdict: approve only when there "+
			"are no blocking findings; otherwise request_changes with a crisp summary.\n"+
			"6. finish.\n\n"+
			"Do not push commits or edit files — you are a reviewer, not the author.",
		round, prNumber, title, prURL, implementerName)
}

// prReviewerRunName is retained for compatibility with pre-multi-PR reviewer
// names. New reviewers include a PR-key hash via reviewerRunName.
func prReviewerRunName(implementerName string, round int) string {
	return ghIssueName("rev", implementerName, fmt.Sprintf("r%d", round))
}

// patchLoopMarkers updates the loop label plus any extra markers with
// optimistic-concurrency retry, mutating the caller's copy on success.
func (e *PRLoopEngine) patchLoopMarkers(ctx context.Context, run *platformv1alpha1.AgentRun, loopKey, state string, mutate func(*platformv1alpha1.AgentRun)) error {
	fresh := &platformv1alpha1.AgentRun{}
	if err := e.Get(ctx, client.ObjectKeyFromObject(run), fresh); err != nil {
		return err
	}
	patch := client.MergeFrom(fresh.DeepCopy())
	if fresh.Labels == nil {
		fresh.Labels = map[string]string{}
	}
	if fresh.Annotations == nil {
		fresh.Annotations = map[string]string{}
	}
	setLoopLabel(fresh, loopKey, PRLoopStateLabel, state)
	if loopKey != "" {
		setLoopAnnotation(fresh, loopKey, PRLoopKeyAnnotation, loopKey)
	}
	if mutate != nil {
		mutate(fresh)
	}
	if err := e.Patch(ctx, fresh, patch); err != nil {
		return fmt.Errorf("patching PR loop markers on %s/%s: %w", run.Namespace, run.Name, err)
	}
	*run = *fresh
	return nil
}

func (e *PRLoopEngine) markVerdictHandled(ctx context.Context, reviewer *platformv1alpha1.AgentRun) error {
	fresh := &platformv1alpha1.AgentRun{}
	if err := e.Get(ctx, client.ObjectKeyFromObject(reviewer), fresh); err != nil {
		return client.IgnoreNotFound(err)
	}
	patch := client.MergeFrom(fresh.DeepCopy())
	if fresh.Annotations == nil {
		fresh.Annotations = map[string]string{}
	}
	fresh.Annotations[PRLoopVerdictHandledAnnotation] = "true"
	return e.Patch(ctx, fresh, patch)
}

// escalateBlocked surfaces a blocked loop as a pending question on the
// implementer's session so the dashboard requests human input. Best effort:
// the loop label and events remain the source of truth.
func (e *PRLoopEngine) escalateBlocked(ctx context.Context, implementer *platformv1alpha1.AgentRun, reason string) {
	if e.StateStore == nil {
		return
	}
	sess, err := e.StateStore.GetSessionByRun(ctx, implementer.Name, implementer.Namespace)
	if err != nil {
		logf.FromContext(ctx).Error(err, "pr loop: failed to load session for blocked escalation", "run", implementer.Name)
		return
	}
	if err := e.StateStore.SetPendingQuestion(ctx, sess.ID, "blocked", reason, "question"); err != nil {
		logf.FromContext(ctx).Error(err, "pr loop: failed to set blocked question", "run", implementer.Name)
	}
}

func (e *PRLoopEngine) eventf(run *platformv1alpha1.AgentRun, reason, format string, args ...any) {
	if e.Recorder == nil {
		return
	}
	e.Recorder.Eventf(run, corev1.EventTypeNormal, reason, format, args...)
}

func reviewLoopDisabled(gh *triggersv1alpha1.GitHubRepository) bool {
	// An omitted policy is an opt-out. A present policy explicitly enables the
	// loop unless disabled is set, preserving a simple CRD opt-in shape:
	// reviewLoop: {}.
	return gh == nil || gh.Spec.ReviewLoop == nil || gh.Spec.ReviewLoop.Disabled
}

func reviewLoopMaxRounds(gh *triggersv1alpha1.GitHubRepository) int {
	if gh != nil && gh.Spec.ReviewLoop != nil && gh.Spec.ReviewLoop.MaxRounds > 0 {
		return int(gh.Spec.ReviewLoop.MaxRounds)
	}
	return defaultMaxReviewRounds
}

func annotationInt(s string, fallback int) int {
	n := 0
	for _, r := range s {
		if r < '0' || r > '9' {
			return fallback
		}
		n = n*10 + int(r-'0')
		if n > 1<<30 {
			return fallback
		}
	}
	if s == "" {
		return fallback
	}
	return n
}

func firstNonEmptyString(values ...string) string {
	for _, v := range values {
		if strings.TrimSpace(v) != "" {
			return v
		}
	}
	return ""
}

package triggers

import (
	"context"
	"fmt"
	"strings"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
)

// prLoopConfig is the trigger-independent input used to create reviewer runs.
// A matching GitHubRepository contributes repository policy and GitHub App
// auth; otherwise the implementer's already-resolved AgentRunSpec is used.
type prLoopConfig struct {
	Disabled           bool
	MaxRounds          int
	ReviewerModeRef    *platformv1alpha1.ModeRef
	ReviewerSpec       platformv1alpha1.AgentRunSpec
	CustomInstructions string
	Annotations        map[string]string
	Repository         *triggersv1alpha1.GitHubRepository
	RepositoryName     string
}

func (e *PRLoopEngine) resolveLoopConfig(ctx context.Context, gh *triggersv1alpha1.GitHubRepository, implementer *platformv1alpha1.AgentRun, repository, baseRef string) (*prLoopConfig, error) {
	if implementer == nil {
		return nil, fmt.Errorf("implementer AgentRun is required")
	}
	repository = normalizeRepositoryName(repository)
	// Only repository configuration beside the implementer and matching this
	// PR's repository may contribute defaults, secrets, auth, or loop policy.
	// In particular, do not fall back to the implementer's trigger repository:
	// a multi-repo run may be opening this PR from an unconfigured additional
	// repository.
	if !gitHubRepositoryMatches(gh, implementer.Namespace, repository) {
		gh = e.lookupRepositoryForLoop(ctx, implementer, repository)
		if !gitHubRepositoryMatches(gh, implementer.Namespace, repository) {
			gh = nil
		}
	}
	policyRepo := gh
	defaultsRepo := gh

	cfg := &prLoopConfig{
		Disabled:       reviewLoopDisabledForRun(implementer, policyRepo),
		MaxRounds:      reviewLoopMaxRounds(policyRepo),
		ReviewerSpec:   reviewerSpecFromImplementer(implementer, baseRef),
		Annotations:    reviewerAnnotationsFromImplementer(implementer),
		Repository:     defaultsRepo,
		RepositoryName: repositoryName(defaultsRepo),
	}
	if defaultsRepo != nil {
		cfg.ReviewerSpec, cfg.Annotations, cfg.CustomInstructions = reviewerSpecFromRepository(defaultsRepo, baseRef)
		cfg.ReviewerModeRef = configuredReviewerModeRef(defaultsRepo)
	}
	if cfg.ReviewerModeRef == nil && ModeExistsFromK8s(ctx, e.Client)(defaultReviewerModeName) {
		cfg.ReviewerModeRef = &platformv1alpha1.ModeRef{Name: defaultReviewerModeName}
	}
	if cfg.RepositoryName == "" && policyRepo != nil && policyRepo.Namespace == implementer.Namespace {
		cfg.RepositoryName = policyRepo.Name
	}
	if cfg.Disabled {
		return cfg, nil
	}
	if strings.TrimSpace(cfg.ReviewerSpec.Model) == "" {
		return nil, fmt.Errorf("AgentRun %s/%s spec.model is required for reviewer runs", implementer.Namespace, implementer.Name)
	}
	return cfg, nil
}

func reviewerSpecFromImplementer(implementer *platformv1alpha1.AgentRun, baseRef string) platformv1alpha1.AgentRunSpec {
	spec := *implementer.Spec.DeepCopy()
	spec.Trigger = platformv1alpha1.TriggerRef{}
	spec.Context = nil
	spec.Repository.BaseBranch = firstNonEmptyString(baseRef, spec.Repository.BaseBranch)
	spec.Repository.BranchName = ""
	spec.Repository.Revision = ""
	spec.ExecutionMode = platformv1alpha1.ExecutionModeLinear
	spec.WorkflowMode = platformv1alpha1.WorkflowModeAuto
	spec.Team = nil
	// Standing supervision runs and PR reviewers are orchestration roles, not
	// ordinary implementers. A reviewer must never inherit the implementer's
	// overseer or recursively create another supervisor.
	spec.Overseer = nil
	spec.ModeRef = nil
	spec.SpecArtifactRef = nil
	spec.WakeRequests = 0
	spec.RestartRequests = 0
	if strings.TrimSpace(spec.Model) == "" {
		spec.Model = triggersv1alpha1.DefaultMainModelForProvider(triggersv1alpha1.ProviderOpenAI)
	}
	if spec.ReasoningLevel == "" {
		spec.ReasoningLevel = platformv1alpha1.ReasoningMax
	}
	return spec
}

func reviewerAnnotationsFromImplementer(implementer *platformv1alpha1.AgentRun) map[string]string {
	annotations := map[string]string{}
	if value := strings.TrimSpace(implementer.Annotations[openAIAPIModeAnnotation]); value != "" {
		annotations[openAIAPIModeAnnotation] = value
	}
	return annotations
}

func reviewerSpecFromRepository(gh *triggersv1alpha1.GitHubRepository, baseRef string) (platformv1alpha1.AgentRunSpec, map[string]string, string) {
	d := gh.Spec.Defaults
	if gh.Spec.ReviewLoop != nil && gh.Spec.ReviewLoop.ReviewerDefaults != nil {
		d = *gh.Spec.ReviewLoop.ReviewerDefaults.DeepCopy()
		// Reviewer overrides cannot redirect repository identity or GitHub auth.
		d.RepoURL = gh.Spec.Defaults.RepoURL
		d.Secrets.GithubToken = gh.Spec.Defaults.Secrets.GithubToken
	}
	provider := triggersv1alpha1.NormalizeProvider(d.Provider)
	authMode := triggersv1alpha1.NormalizeAuthMode(string(d.AuthMode))
	model := strings.TrimSpace(d.Model)
	if model == "" {
		model = triggersv1alpha1.DefaultMainModelForProvider(provider)
	}
	reasoningLevel := d.ReasoningLevel
	if reasoningLevel == "" {
		reasoningLevel = platformv1alpha1.ReasoningMax
	}
	annotations := map[string]string{}
	if triggersv1alpha1.IsOpenAICompatibleProvider(provider) {
		annotations[openAIAPIModeAnnotation] = triggersv1alpha1.NormalizeOpenAIAPIForProvider(provider, d.OpenAIAPI)
	}

	gitHubTokenSecret := d.Secrets.GithubToken
	if gh.Spec.GitHubApp != nil {
		// The deterministic reviewer run name is filled in by createReviewerRun.
		gitHubTokenSecret = ""
	}
	spec := platformv1alpha1.AgentRunSpec{
		Repository: platformv1alpha1.RepositoryContext{
			URL:             d.RepoURL,
			BaseBranch:      firstNonEmptyString(baseRef, d.BaseBranch),
			AdditionalRepos: append([]string(nil), d.AdditionalRepos...),
		},
		ExecutionMode:  platformv1alpha1.ExecutionModeLinear,
		WorkflowMode:   platformv1alpha1.WorkflowModeAuto,
		Model:          prefixModelWithProvider(model, provider),
		AuthMode:       authMode,
		ReasoningLevel: reasoningLevel,
		OpenAIBaseURL:  triggersv1alpha1.ResolveOpenAIBaseURLWithAuth(provider, d.OpenAIBaseURL, authMode),
		Image:          d.Image,
		Secrets: &platformv1alpha1.AgentRunSecrets{
			ClaudeAPIKeySecret: d.Secrets.ClaudeApiKey,
			OpenAIOAuthSecret:  d.Secrets.OpenAIOAuthSecret,
			GitHubTokenSecret:  gitHubTokenSecret,
			ProviderKeys:       append([]platformv1alpha1.ProviderKeyRef(nil), d.Secrets.ProviderKeys...),
		},
	}
	applyPolicyRefs(&spec, d)
	return spec, annotations, d.CustomInstructions
}

func gitHubRepositoryMatches(gh *triggersv1alpha1.GitHubRepository, namespace, repository string) bool {
	return gh != nil && gh.Namespace == namespace &&
		normalizeRepositoryName(gh.Spec.Owner+"/"+gh.Spec.Repo) == normalizeRepositoryName(repository)
}

func repositoryName(gh *triggersv1alpha1.GitHubRepository) string {
	if gh == nil {
		return ""
	}
	return gh.Name
}

func configuredReviewerModeRef(gh *triggersv1alpha1.GitHubRepository) *platformv1alpha1.ModeRef {
	if gh != nil && gh.Spec.ReviewLoop != nil && gh.Spec.ReviewLoop.ReviewerModeRef != nil {
		return gh.Spec.ReviewLoop.ReviewerModeRef.DeepCopy()
	}
	return nil
}

func reviewLoopDisabledForRun(run *platformv1alpha1.AgentRun, gh *triggersv1alpha1.GitHubRepository) bool {
	if run != nil {
		switch strings.ToLower(strings.TrimSpace(run.Annotations[PRLoopOptAnnotation])) {
		case PRLoopOptEnabled:
			return false
		case PRLoopOptDisabled:
			return true
		}
	}
	return reviewLoopDisabled(gh)
}

package triggers

import (
	"context"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	ctrl "sigs.k8s.io/controller-runtime"
	"sigs.k8s.io/controller-runtime/pkg/client"
	"sigs.k8s.io/controller-runtime/pkg/controller"
	"sigs.k8s.io/controller-runtime/pkg/event"
	"sigs.k8s.io/controller-runtime/pkg/predicate"
)

// PRLoopReconciler advances the autonomous PR review loop on run completions:
// finished reviewer runs deliver their verdict, finished implementer runs in
// the resolving state trigger the next review round.
type PRLoopReconciler struct {
	client.Client
	Engine *PRLoopEngine
}

// +kubebuilder:rbac:groups=platform.gratefulagents.dev,resources=agentruns,verbs=get;list;watch;create;update;patch

func (r *PRLoopReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
	run := &platformv1alpha1.AgentRun{}
	if err := r.Get(ctx, req.NamespacedName, run); err != nil {
		return ctrl.Result{}, client.IgnoreNotFound(err)
	}
	if r.Engine == nil || !prLoopRunCompleted(run) {
		return ctrl.Result{}, nil
	}

	if run.Labels[PRLoopRoleLabel] == PRLoopRoleReviewer {
		return ctrl.Result{}, r.Engine.OnReviewerRunCompleted(ctx, run)
	}
	return ctrl.Result{}, r.Engine.OnImplementerRunCompleted(ctx, run)
}

// prLoopRunCompleted reports whether the run both participates in the loop and
// has reached a phase the loop reacts to.
func prLoopRunCompleted(run *platformv1alpha1.AgentRun) bool {
	if run == nil {
		return false
	}
	inLoop := run.Labels[PRLoopRoleLabel] == PRLoopRoleReviewer || run.Labels[PRLoopStateLabel] != ""
	if !inLoop {
		return false
	}
	switch run.Status.Phase {
	case platformv1alpha1.AgentRunPhaseSucceeded, platformv1alpha1.AgentRunPhaseFailed:
		return true
	default:
		return false
	}
}

// prLoopPredicate filters watch events down to loop-labeled runs so the
// reconciler does not churn on every AgentRun in the cluster.
func prLoopPredicate() predicate.Predicate {
	isLoopRun := func(obj client.Object) bool {
		labels := obj.GetLabels()
		return labels[PRLoopRoleLabel] != "" || labels[PRLoopStateLabel] != ""
	}
	return predicate.Funcs{
		CreateFunc:  func(e event.CreateEvent) bool { return isLoopRun(e.Object) },
		UpdateFunc:  func(e event.UpdateEvent) bool { return isLoopRun(e.ObjectNew) },
		DeleteFunc:  func(event.DeleteEvent) bool { return false },
		GenericFunc: func(e event.GenericEvent) bool { return isLoopRun(e.Object) },
	}
}

func (r *PRLoopReconciler) SetupWithManager(mgr ctrl.Manager) error {
	return ctrl.NewControllerManagedBy(mgr).
		For(&platformv1alpha1.AgentRun{}).
		Named("prloop").
		WithEventFilter(prLoopPredicate()).
		WithOptions(controller.Options{MaxConcurrentReconciles: 1}).
		Complete(r)
}

package triggers

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strconv"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	"github.com/gratefulagents/gratefulagents/internal/store"
	"k8s.io/client-go/util/retry"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

const (
	externalPRReviewIDsAnnotation  = "triggers.gratefulagents.dev/github-review-ids"
	externalPRCommentIDsAnnotation = "triggers.gratefulagents.dev/github-comment-ids"
	githubEventMetadataKey         = "github_event_key"
	maxExternalPREventIDs          = 64
)

func externalPREventHandled(run *platformv1alpha1.AgentRun, loopKey string, event PullRequestEvent) bool {
	if event.SourceID == 0 {
		return false
	}
	for _, id := range externalPREventIDs(run, loopKey, event.Type) {
		if id == event.SourceID {
			return true
		}
	}
	return false
}

func markExternalPREvent(run *platformv1alpha1.AgentRun, loopKey string, event PullRequestEvent) {
	if event.SourceID == 0 || externalPREventHandled(run, loopKey, event) {
		return
	}
	ids := append(externalPREventIDs(run, loopKey, event.Type), event.SourceID)
	if len(ids) > maxExternalPREventIDs {
		ids = ids[len(ids)-maxExternalPREventIDs:]
	}
	encoded, _ := json.Marshal(ids)
	setLoopAnnotation(run, loopKey, externalPREventIDsAnnotation(event.Type), string(encoded))
}

func externalPREventIDs(run *platformv1alpha1.AgentRun, loopKey string, eventType PullRequestEventType) []int64 {
	var ids []int64
	_ = json.Unmarshal([]byte(loopAnnotation(run, loopKey, externalPREventIDsAnnotation(eventType))), &ids)
	return ids
}

func externalPREventIDsAnnotation(eventType PullRequestEventType) string {
	if eventType == PREventReviewSubmitted {
		return externalPRReviewIDsAnnotation
	}
	return externalPRCommentIDsAnnotation
}

func externalPREventID(event PullRequestEvent) string {
	return string(event.Type) + ":" + strconv.FormatInt(event.SourceID, 10)
}

func externalPREventKey(loopKey string, event PullRequestEvent) string {
	return loopKey + ":" + externalPREventID(event)
}

func (e *PRLoopEngine) wakeImplementerForPREvent(ctx context.Context, implementer *platformv1alpha1.AgentRun, loopKey, newState, message string, event PullRequestEvent) error {
	if event.SourceID == 0 {
		return e.wakeImplementer(ctx, implementer, loopKey, newState, message)
	}
	cancelled := implementer.Status.Phase == platformv1alpha1.AgentRunPhaseCancelled
	if !cancelled {
		if e.StateStore == nil {
			return fmt.Errorf("state store is required to message AgentRun %s/%s", implementer.Namespace, implementer.Name)
		}
		sess, err := e.StateStore.GetSessionByRun(ctx, implementer.Name, implementer.Namespace)
		if err != nil {
			return fmt.Errorf("getting session for AgentRun %s/%s: %w", implementer.Namespace, implementer.Name, err)
		}
		eventKey := externalPREventKey(loopKey, event)
		metadata, _ := json.Marshal(map[string]string{githubEventMetadataKey: eventKey})
		if _, err := e.StateStore.AppendMessage(ctx, sess.ID, "user", message, metadata); err != nil && !errors.Is(err, store.ErrMessageAlreadyExists) {
			return fmt.Errorf("appending message for AgentRun %s/%s: %w", implementer.Namespace, implementer.Name, err)
		}
	}

	key := client.ObjectKeyFromObject(implementer)
	err := retry.RetryOnConflict(retry.DefaultRetry, func() error {
		fresh := &platformv1alpha1.AgentRun{}
		if err := e.Get(ctx, key, fresh); err != nil {
			return err
		}
		if externalPREventHandled(fresh, loopKey, event) {
			*implementer = *fresh
			return nil
		}
		patch := client.MergeFrom(fresh.DeepCopy())
		setLoopLabel(fresh, loopKey, PRLoopStateLabel, newState)
		setLoopAnnotation(fresh, loopKey, PRLoopKeyAnnotation, loopKey)
		markExternalPREvent(fresh, loopKey, event)
		switch fresh.Status.Phase {
		case platformv1alpha1.AgentRunPhaseSucceeded, platformv1alpha1.AgentRunPhaseFailed, platformv1alpha1.AgentRunPhasePaused:
			fresh.Spec.WakeRequests++
		}
		if err := e.Patch(ctx, fresh, patch); err != nil {
			return err
		}
		*implementer = *fresh
		return nil
	})
	if err != nil {
		return fmt.Errorf("patching external PR event on %s/%s: %w", implementer.Namespace, implementer.Name, err)
	}
	if implementer.Status.Phase == platformv1alpha1.AgentRunPhaseCancelled {
		e.escalateBlocked(ctx, implementer, fmt.Sprintf("The PR review loop is blocked: implementer run %s is cancelled and cannot be woken. Review the PR manually or start a new implementer run.", implementer.Name))
	}
	return nil
}

package triggers

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"net/url"
	"strconv"
	"strings"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

const PRLoopKeyAnnotation = "triggers.gratefulagents.dev/pr-loop-key"

type prLoopRecord struct {
	Key        string
	Repository string
	Number     int
	URL        string
	BaseRef    string
}

func loopRecordForEvent(event PullRequestEvent) prLoopRecord {
	repository := normalizeRepositoryName(event.Repository)
	if repository == "" {
		repository = repositoryFromPullRequestURL(event.URL)
	}
	return prLoopRecord{
		Key:        prLoopKey(repository, event.Number),
		Repository: repository,
		Number:     event.Number,
		URL:        event.URL,
		BaseRef:    event.BaseRef,
	}
}

func prLoopKey(repository string, number int) string {
	return fmt.Sprintf("%s#%d", normalizeRepositoryName(repository), number)
}

func loopMarkerKey(base, loopKey string) string {
	if loopKey == "" {
		return base
	}
	sum := sha256.Sum256([]byte(strings.ToLower(loopKey)))
	return base + "-" + hex.EncodeToString(sum[:6])
}

func setLoopLabel(run *platformv1alpha1.AgentRun, loopKey, base, value string) {
	if run.Labels == nil {
		run.Labels = map[string]string{}
	}
	run.Labels[base] = value // compatibility/current-loop view
	if loopKey != "" {
		run.Labels[loopMarkerKey(base, loopKey)] = value
	}
}

func setLoopAnnotation(run *platformv1alpha1.AgentRun, loopKey, base, value string) {
	if run.Annotations == nil {
		run.Annotations = map[string]string{}
	}
	run.Annotations[base] = value // compatibility/current-loop view
	if loopKey != "" {
		run.Annotations[loopMarkerKey(base, loopKey)] = value
	}
}

func loopState(run *platformv1alpha1.AgentRun, loopKey, base string) string {
	if run == nil {
		return ""
	}
	if loopKey != "" {
		if value := run.Labels[loopMarkerKey(base, loopKey)]; value != "" {
			return value
		}
		if value := run.Annotations[loopMarkerKey(base, loopKey)]; value != "" {
			return value
		}
		// Only the current loop may fall back to compatibility markers.
		current := strings.TrimSpace(run.Annotations[PRLoopKeyAnnotation])
		if current != "" && current != loopKey {
			return ""
		}
	}
	if value := run.Labels[base]; value != "" {
		return value
	}
	return run.Annotations[base]
}

func loopAnnotation(run *platformv1alpha1.AgentRun, loopKey, base string) string {
	if run == nil {
		return ""
	}
	if loopKey != "" {
		if value := run.Annotations[loopMarkerKey(base, loopKey)]; value != "" {
			return value
		}
	}
	return run.Annotations[base]
}

func loopRecordFromRun(run *platformv1alpha1.AgentRun, loopKey string) prLoopRecord {
	getAnnotation := func(base string) string {
		if loopKey != "" {
			if value := run.Annotations[loopMarkerKey(base, loopKey)]; value != "" {
				return value
			}
		}
		return run.Annotations[base]
	}
	getLabel := func(base string) string {
		if loopKey != "" {
			if value := run.Labels[loopMarkerKey(base, loopKey)]; value != "" {
				return value
			}
		}
		return run.Labels[base]
	}
	record := prLoopRecord{
		Key:     loopKey,
		Number:  annotationInt(getLabel(PRLoopNumberLabel), 0),
		URL:     getAnnotation(PRLoopURLAnnotation),
		BaseRef: getAnnotation(PRLoopBaseRefAnnotation),
	}
	record.Repository = repositoryFromPullRequestURL(record.URL)
	if record.Key == "" && record.Number > 0 {
		record.Key = prLoopKey(record.Repository, record.Number)
	}
	return record
}

func hasLoopRecord(run *platformv1alpha1.AgentRun, loopKey string) bool {
	for _, record := range loopRecords(run) {
		if record.Key == loopKey {
			return true
		}
	}
	return false
}

func loopRecords(run *platformv1alpha1.AgentRun) []prLoopRecord {
	if run == nil {
		return nil
	}
	seen := map[string]bool{}
	var records []prLoopRecord
	prefix := PRLoopKeyAnnotation + "-"
	for marker, key := range run.Annotations {
		if !strings.HasPrefix(marker, prefix) || strings.TrimSpace(key) == "" || seen[key] {
			continue
		}
		seen[key] = true
		records = append(records, loopRecordFromRun(run, key))
	}
	currentKey := strings.TrimSpace(run.Annotations[PRLoopKeyAnnotation])
	if currentKey != "" && !seen[currentKey] {
		seen[currentKey] = true
		records = append(records, loopRecordFromRun(run, currentKey))
	}
	// Upgrade legacy single-PR markers lazily. The URL supplies repository
	// identity, avoiding collisions where two repos both have PR #42.
	if len(records) == 0 {
		legacy := loopRecordFromRun(run, "")
		if legacy.Number > 0 {
			records = append(records, legacy)
		}
	}
	return records
}

func normalizeRepositoryName(value string) string {
	value = strings.Trim(strings.TrimSpace(value), "/")
	value = strings.TrimSuffix(value, ".git")
	parts := strings.Split(value, "/")
	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
		return ""
	}
	return strings.ToLower(parts[0] + "/" + parts[1])
}

func repositoryFromPullRequestURL(raw string) string {
	u, err := url.Parse(strings.TrimSpace(raw))
	if err != nil || !strings.EqualFold(u.Hostname(), "github.com") {
		return ""
	}
	parts := strings.Split(strings.Trim(u.Path, "/"), "/")
	if len(parts) < 2 {
		return ""
	}
	return normalizeRepositoryName(parts[0] + "/" + parts[1])
}

func repositoryFromCloneURL(raw string) string {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return ""
	}
	if strings.HasPrefix(raw, "git@github.com:") {
		return normalizeRepositoryName(strings.TrimPrefix(raw, "git@github.com:"))
	}
	u, err := url.Parse(raw)
	if err != nil || !strings.EqualFold(u.Hostname(), "github.com") {
		return ""
	}
	return normalizeRepositoryName(u.Path)
}

func runDeclaresRepository(run *platformv1alpha1.AgentRun, repository string) bool {
	repository = normalizeRepositoryName(repository)
	if run == nil || repository == "" {
		return false
	}
	urls := append([]string{run.Spec.Repository.URL}, run.Spec.Repository.AdditionalRepos...)
	for _, raw := range urls {
		if repositoryFromCloneURL(raw) == repository {
			return true
		}
	}
	return false
}

func declaredRepositoryURL(run *platformv1alpha1.AgentRun, repository string) string {
	if run == nil {
		return ""
	}
	urls := append([]string{run.Spec.Repository.URL}, run.Spec.Repository.AdditionalRepos...)
	for _, raw := range urls {
		if repositoryFromCloneURL(raw) == normalizeRepositoryName(repository) {
			return raw
		}
	}
	return ""
}

func reviewerOwnerReferences(implementer *platformv1alpha1.AgentRun) []metav1.OwnerReference {
	if implementer == nil {
		return nil
	}
	owners := make([]metav1.OwnerReference, 0, len(implementer.OwnerReferences))
	for _, owner := range implementer.OwnerReferences {
		// AgentRun ownership has orchestration semantics: the platform treats
		// the owned run as a delegated team child. Reviewers are independent.
		if owner.APIVersion == platformv1alpha1.GroupVersion.String() && owner.Kind == "AgentRun" {
			continue
		}
		owners = append(owners, owner)
	}
	return owners
}

func reviewerAdditionalRepositories(run *platformv1alpha1.AgentRun, primaryURL string, configured []string) []string {
	primaryRepository := repositoryFromCloneURL(primaryURL)
	declared := append([]string(nil), configured...)
	if run != nil {
		declared = append(declared, run.Spec.Repository.URL)
		declared = append(declared, run.Spec.Repository.AdditionalRepos...)
	}
	seen := map[string]bool{primaryRepository: true}
	var additional []string
	for _, raw := range declared {
		repository := repositoryFromCloneURL(raw)
		if repository == "" || seen[repository] {
			continue
		}
		seen[repository] = true
		additional = append(additional, raw)
	}
	return additional
}

func runHasPullRequestURL(run *platformv1alpha1.AgentRun, prURL string) bool {
	if run == nil || run.Status.Artifacts == nil || strings.TrimSpace(prURL) == "" {
		return false
	}
	for _, value := range append(append([]string(nil), run.Status.Artifacts.PullRequestURLs...), run.Status.Artifacts.PullRequestURL) {
		if strings.EqualFold(strings.TrimSpace(value), strings.TrimSpace(prURL)) {
			return true
		}
	}
	return false
}

func (e *PRLoopEngine) implementerForPullRequestEvent(ctx context.Context, event PullRequestEvent, requireLoop bool) (*platformv1alpha1.AgentRun, error) {
	namespace := strings.TrimSpace(event.TargetImplementerNamespace)
	name := strings.TrimSpace(event.TargetImplementerName)
	if namespace == "" && name == "" {
		return nil, nil
	}
	if namespace == "" || name == "" {
		return nil, fmt.Errorf("target implementer namespace and name must both be set")
	}
	run := &platformv1alpha1.AgentRun{}
	if err := e.Get(ctx, client.ObjectKey{Namespace: namespace, Name: name}, run); err != nil {
		return nil, err
	}
	repository := normalizeRepositoryName(event.Repository)
	if run.Labels[PRLoopRoleLabel] == PRLoopRoleReviewer || !runDeclaresRepository(run, repository) || !runRecordsPullRequestURL(run, event.URL) {
		return nil, fmt.Errorf("target implementer %s/%s does not own %s", namespace, name, event.URL)
	}
	if requireLoop && !hasLoopRecord(run, prLoopKey(repository, event.Number)) {
		return nil, fmt.Errorf("target implementer %s/%s has no loop record for %s#%d", namespace, name, repository, event.Number)
	}
	return run, nil
}

func (e *PRLoopEngine) findImplementerByHead(ctx context.Context, gh *triggersv1alpha1.GitHubRepository, repository, prURL, headRef string) (*platformv1alpha1.AgentRun, error) {
	repository = normalizeRepositoryName(repository)
	if repository == "" && gh != nil {
		repository = normalizeRepositoryName(gh.Spec.Owner + "/" + gh.Spec.Repo)
	}
	if strings.TrimSpace(headRef) == "" || repository == "" {
		return nil, nil
	}
	list := &platformv1alpha1.AgentRunList{}
	if err := e.List(ctx, list); err != nil {
		return nil, fmt.Errorf("listing AgentRuns for PR head %q: %w", headRef, err)
	}
	var matches []*platformv1alpha1.AgentRun
	for i := range list.Items {
		run := &list.Items[i]
		if run.Name == headRef && run.Labels[PRLoopRoleLabel] != PRLoopRoleReviewer && runDeclaresRepository(run, repository) {
			matches = append(matches, run)
		}
	}
	if len(matches) > 1 && strings.TrimSpace(prURL) != "" {
		var artifactMatches []*platformv1alpha1.AgentRun
		for _, run := range matches {
			if runHasPullRequestURL(run, prURL) {
				artifactMatches = append(artifactMatches, run)
			}
		}
		if len(artifactMatches) == 1 {
			return artifactMatches[0], nil
		}
	}
	if len(matches) == 1 {
		return matches[0], nil
	}
	if len(matches) > 1 {
		return nil, fmt.Errorf("PR head %q in repository %s matches AgentRuns in multiple namespaces", headRef, repository)
	}
	return nil, nil
}

func (e *PRLoopEngine) findImplementerByPR(ctx context.Context, gh *triggersv1alpha1.GitHubRepository, repository string, prNumber int) (*platformv1alpha1.AgentRun, string, error) {
	if prNumber <= 0 {
		return nil, "", nil
	}
	repository = normalizeRepositoryName(repository)
	if repository == "" && gh != nil {
		repository = normalizeRepositoryName(gh.Spec.Owner + "/" + gh.Spec.Repo)
	}
	key := prLoopKey(repository, prNumber)
	list := &platformv1alpha1.AgentRunList{}
	if err := e.List(ctx, list); err != nil {
		return nil, key, fmt.Errorf("listing AgentRuns for PR %s: %w", key, err)
	}
	var matches []*platformv1alpha1.AgentRun
	for i := range list.Items {
		run := &list.Items[i]
		if run.Labels[PRLoopRoleLabel] == PRLoopRoleReviewer || !runDeclaresRepository(run, repository) {
			continue
		}
		for _, record := range loopRecords(run) {
			if record.Key == key || (record.Number == prNumber && record.Repository == repository) {
				matches = append(matches, run)
				break
			}
		}
	}
	if len(matches) == 1 {
		return matches[0], key, nil
	}
	if len(matches) > 1 {
		return nil, key, fmt.Errorf("PR %s is linked to AgentRuns in multiple namespaces", key)
	}
	return nil, key, nil
}

func (e *PRLoopEngine) lookupRepositoryForLoop(ctx context.Context, implementer *platformv1alpha1.AgentRun, repository string) *triggersv1alpha1.GitHubRepository {
	repository = normalizeRepositoryName(repository)
	list := &triggersv1alpha1.GitHubRepositoryList{}
	if err := e.List(ctx, list); err != nil {
		return nil
	}
	var fallback *triggersv1alpha1.GitHubRepository
	for i := range list.Items {
		gh := &list.Items[i]
		if normalizeRepositoryName(gh.Spec.Owner+"/"+gh.Spec.Repo) != repository {
			continue
		}
		if implementer != nil && gh.Namespace == implementer.Namespace {
			return gh
		}
		if fallback == nil {
			fallback = gh
		}
	}
	return fallback
}

func reviewerRunName(implementerName, loopKey string, round int) string {
	sum := sha256.Sum256([]byte(strings.ToLower(loopKey)))
	return ghIssueName("rev", implementerName, hex.EncodeToString(sum[:4])+"-r"+strconv.Itoa(round))
}

package triggers

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"reflect"
	"sort"
	"strings"

	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	"k8s.io/apimachinery/pkg/api/meta"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/apimachinery/pkg/types"
	"k8s.io/client-go/util/retry"
	ctrl "sigs.k8s.io/controller-runtime"
	"sigs.k8s.io/controller-runtime/pkg/client"
	"sigs.k8s.io/controller-runtime/pkg/controller"
	"sigs.k8s.io/controller-runtime/pkg/handler"
	"sigs.k8s.io/controller-runtime/pkg/reconcile"
)

const (
	projectGeneratedRuntimeLabel  = "triggers.gratefulagents.dev/generated-runtime"
	projectNameLabel              = "triggers.gratefulagents.dev/project-name"
	projectUIDLabel               = "triggers.gratefulagents.dev/project-uid"
	projectTriggerNameLabel       = "triggers.gratefulagents.dev/project-trigger-name"
	projectTriggerTypeLabel       = "triggers.gratefulagents.dev/project-trigger-type"
	projectNameAnnotation         = "triggers.gratefulagents.dev/project-name"
	projectUIDAnnotation          = "triggers.gratefulagents.dev/project-uid"
	projectTriggerNameAnnotation  = "triggers.gratefulagents.dev/project-trigger-name"
	projectTriggerTypeAnnotation  = "triggers.gratefulagents.dev/project-trigger-type"
	projectSlackChannelAnnotation = "triggers.gratefulagents.dev/project-trigger-channel"
	projectSlackTeamIDAnnotation  = "triggers.gratefulagents.dev/project-slack-team-id"
)

// ProjectReconciler compiles Project trigger declarations into standalone
// runtime trigger CRs. The runtime controllers remain responsible for their
// own source-specific work and status.
type ProjectReconciler struct {
	client.Client
	Scheme *runtime.Scheme
}

// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=projects,verbs=get;list;watch;update;patch
// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=projects/status,verbs=get;update;patch
// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=connections,verbs=get;list;watch
// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=crons;githubrepositories;linearprojects;slackagents,verbs=get;list;watch;create;update;patch;delete

func (r *ProjectReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
	project := &triggersv1alpha1.Project{}
	if err := r.Get(ctx, req.NamespacedName, project); err != nil {
		return ctrl.Result{}, client.IgnoreNotFound(err)
	}

	desired := map[string]client.Object{}
	statuses := make([]triggersv1alpha1.ProjectTriggerStatus, 0, len(project.Spec.Triggers))
	ready := true

	for _, trigger := range project.Spec.Triggers {
		if !projectTriggerEnabled(trigger) {
			statuses = append(statuses, projectDisabledTriggerStatus(project, trigger))
			continue
		}

		child, err := r.compileTrigger(ctx, project, trigger)
		if err != nil {
			ready = false
			statuses = append(statuses, projectCompileErrorStatus(project, trigger, err))
			continue
		}
		desired[projectGeneratedChildKey(child)] = child
	}

	if err := r.cleanupGeneratedChildren(ctx, project, desired); err != nil {
		return ctrl.Result{}, err
	}
	for _, child := range desired {
		if err := r.upsertGeneratedChild(ctx, child); err != nil {
			return ctrl.Result{}, err
		}
	}

	for _, trigger := range project.Spec.Triggers {
		if !projectTriggerEnabled(trigger) {
			continue
		}
		child, ok := desired[projectGeneratedChildKeyForTrigger(project, trigger)]
		if !ok {
			continue
		}
		status, triggerReady, err := r.normalizedChildStatus(ctx, project, trigger, child)
		if err != nil {
			return ctrl.Result{}, err
		}
		if !triggerReady {
			ready = false
		}
		statuses = append(statuses, status)
	}

	sort.Slice(statuses, func(i, j int) bool { return statuses[i].Name < statuses[j].Name })
	if err := r.updateProjectStatus(ctx, client.ObjectKeyFromObject(project), statuses, ready); err != nil && !apierrors.IsNotFound(err) {
		return ctrl.Result{}, fmt.Errorf("updating Project status: %w", err)
	}
	return ctrl.Result{}, nil
}

func projectTriggerEnabled(trigger triggersv1alpha1.ProjectTrigger) bool {
	return trigger.Enabled == nil || *trigger.Enabled
}

func (r *ProjectReconciler) ensureSlackConnectionExclusive(ctx context.Context, owner *triggersv1alpha1.Project, trigger triggersv1alpha1.ProjectTrigger) error {
	projects := &triggersv1alpha1.ProjectList{}
	if err := r.List(ctx, projects, client.InNamespace(owner.Namespace)); err != nil {
		return fmt.Errorf("listing Projects for Slack connection exclusivity: %w", err)
	}
	for i := range projects.Items {
		project := &projects.Items[i]
		for _, other := range project.Spec.Triggers {
			if project.Name == owner.Name && other.Name == trigger.Name {
				continue
			}
			if projectTriggerEnabled(other) && other.Type == triggersv1alpha1.ProjectTriggerTypeSlack && other.Slack != nil && other.Slack.ConnectionRef.Name == trigger.Slack.ConnectionRef.Name {
				return fmt.Errorf("slack connection %q is also used by enabled trigger %s/%s; Socket Mode connections cannot be shared", trigger.Slack.ConnectionRef.Name, project.Name, other.Name)
			}
		}
	}
	return nil
}

func (r *ProjectReconciler) compileTrigger(ctx context.Context, project *triggersv1alpha1.Project, trigger triggersv1alpha1.ProjectTrigger) (client.Object, error) {
	metadata := r.generatedMetadata(project, trigger)
	defaults := projectDefaults(project)

	switch trigger.Type {
	case triggersv1alpha1.ProjectTriggerTypeGitHub:
		if trigger.GitHub == nil {
			return nil, fmt.Errorf("github configuration is required")
		}
		connection, err := r.connection(ctx, project.Namespace, trigger.GitHub.ConnectionRef.Name, triggersv1alpha1.ConnectionTypeGitHub)
		if err != nil {
			return nil, err
		}
		child := &triggersv1alpha1.GitHubRepository{
			ObjectMeta: metadata,
			Spec: triggersv1alpha1.GitHubRepositorySpec{
				Owner:          trigger.GitHub.Owner,
				Repo:           trigger.GitHub.Repo,
				PollInterval:   trigger.GitHub.PollInterval,
				TriggerKeyword: trigger.GitHub.TriggerKeyword,
				Auth:           projectGitHubAuth(project.Spec.Auth, trigger.GitHub.Auth),
				Maintainer:     trigger.GitHub.Maintainer.DeepCopy(),
				Defaults:       defaults,
			},
		}
		if project.Spec.ReviewLoop != nil {
			child.Spec.ReviewLoop = &triggersv1alpha1.ReviewLoopSpec{Disabled: project.Spec.ReviewLoop.Disabled}
		}
		child.Annotations["triggers.gratefulagents.dev/project-trigger-issues"] = fmt.Sprintf("%t", trigger.GitHub.Issues)
		child.Annotations["triggers.gratefulagents.dev/project-trigger-comments"] = fmt.Sprintf("%t", trigger.GitHub.Comments)
		if connection.Spec.GitHub.TokenSecret != "" {
			child.Spec.GitHubTokenSecret = connection.Spec.GitHub.TokenSecret
		} else if connection.Spec.GitHub.AppID > 0 && connection.Spec.GitHub.InstallationID > 0 && connection.Spec.GitHub.PrivateKeySecret != "" {
			child.Spec.GitHubApp = &triggersv1alpha1.GitHubAppAuth{
				AppID:            connection.Spec.GitHub.AppID,
				InstallationID:   connection.Spec.GitHub.InstallationID,
				PrivateKeySecret: connection.Spec.GitHub.PrivateKeySecret,
			}
		} else {
			return nil, fmt.Errorf("Connection %q must specify github.tokenSecret or complete github app configuration", connection.Name)
		}
		return child, r.setProjectControllerReference(project, child)

	case triggersv1alpha1.ProjectTriggerTypeSlack:
		if trigger.Slack == nil {
			return nil, fmt.Errorf("slack configuration is required")
		}
		if err := r.ensureSlackConnectionExclusive(ctx, project, trigger); err != nil {
			return nil, err
		}
		connection, err := r.connection(ctx, project.Namespace, trigger.Slack.ConnectionRef.Name, triggersv1alpha1.ConnectionTypeSlack)
		if err != nil {
			return nil, err
		}
		if connection.Spec.Slack.TokensSecret == "" {
			return nil, fmt.Errorf("Connection %q must specify slack.tokensSecret", connection.Name)
		}
		child := &triggersv1alpha1.SlackAgent{
			ObjectMeta: metadata,
			Spec: triggersv1alpha1.SlackAgentSpec{
				TokensSecret:       connection.Spec.Slack.TokensSecret,
				SlackUserID:        connection.Spec.Slack.SlackUserID,
				ChannelReplyMode:   trigger.Slack.ChannelReplyMode,
				Commanders:         append([]string(nil), trigger.Slack.Commanders...),
				SessionIdleMinutes: trigger.Slack.SessionIdleMinutes,
				Defaults:           defaults,
			},
		}
		child.Annotations[projectSlackChannelAnnotation] = trigger.Slack.Channel
		if teamID := strings.TrimSpace(connection.Spec.Slack.TeamID); teamID != "" {
			child.Annotations[projectSlackTeamIDAnnotation] = teamID
		}
		return child, r.setProjectControllerReference(project, child)

	case triggersv1alpha1.ProjectTriggerTypeCron:
		if trigger.Cron == nil {
			return nil, fmt.Errorf("cron configuration is required")
		}
		child := &triggersv1alpha1.Cron{
			ObjectMeta: metadata,
			Spec: triggersv1alpha1.CronSpec{
				Schedule:          trigger.Cron.Schedule,
				TimeZone:          trigger.Cron.TimeZone,
				ConcurrencyPolicy: trigger.Cron.ConcurrencyPolicy,
				Prompt:            trigger.Cron.Prompt,
				Defaults:          defaults,
			},
		}
		return child, r.setProjectControllerReference(project, child)

	case triggersv1alpha1.ProjectTriggerTypeLinear:
		if trigger.Linear == nil {
			return nil, fmt.Errorf("linear configuration is required")
		}
		connection, err := r.connection(ctx, project.Namespace, trigger.Linear.ConnectionRef.Name, triggersv1alpha1.ConnectionTypeLinear)
		if err != nil {
			return nil, err
		}
		if connection.Spec.Linear.APIKeySecret == "" {
			return nil, fmt.Errorf("Connection %q must specify linear.apiKeySecret", connection.Name)
		}
		child := &triggersv1alpha1.LinearProject{
			ObjectMeta: metadata,
			Spec: triggersv1alpha1.LinearProjectSpec{
				LinearAPIKeySecret: connection.Spec.Linear.APIKeySecret,
				ProjectID:          trigger.Linear.ProjectID,
				TeamID:             trigger.Linear.TeamID,
				PollInterval:       trigger.Linear.PollInterval,
				ApprovedLabel:      trigger.Linear.ApprovedLabel,
				AutoCreateTasks:    trigger.Linear.AutoCreate,
				Defaults:           defaults,
			},
		}
		return child, r.setProjectControllerReference(project, child)
	default:
		return nil, fmt.Errorf("unsupported trigger type %q", trigger.Type)
	}
}

func (r *ProjectReconciler) connection(ctx context.Context, namespace, name string, wantType triggersv1alpha1.ConnectionType) (*triggersv1alpha1.Connection, error) {
	connection := &triggersv1alpha1.Connection{}
	if err := r.Get(ctx, types.NamespacedName{Namespace: namespace, Name: name}, connection); err != nil {
		if apierrors.IsNotFound(err) {
			return nil, fmt.Errorf("Connection %q not found", name)
		}
		return nil, err
	}
	if connection.Spec.Type != wantType {
		return nil, fmt.Errorf("Connection %q has type %q, want %q", name, connection.Spec.Type, wantType)
	}
	return connection, nil
}

func projectDefaults(project *triggersv1alpha1.Project) triggersv1alpha1.AgentRunDefaults {
	var defaults triggersv1alpha1.AgentRunDefaults
	project.Spec.Defaults.DeepCopyInto(&defaults)
	if project.Spec.KubernetesAdmin {
		defaults.KubernetesAdmin = true
	}
	if project.Spec.DockerInDocker {
		defaults.DockerInDocker = true
	}
	return defaults
}

func projectGitHubAuth(projectAuth, triggerAuth *triggersv1alpha1.TriggerAuth) *triggersv1alpha1.TriggerAuth {
	if projectAuth == nil && triggerAuth == nil {
		return nil
	}
	if projectAuth == nil {
		return triggerAuth.DeepCopy()
	}
	if triggerAuth == nil {
		return projectAuth.DeepCopy()
	}

	auth := &triggersv1alpha1.TriggerAuth{DenyUsers: append([]string(nil), projectAuth.DenyUsers...)}
	for _, user := range triggerAuth.DenyUsers {
		if !containsProjectUser(auth.DenyUsers, user) {
			auth.DenyUsers = append(auth.DenyUsers, user)
		}
	}
	switch {
	case len(projectAuth.AllowedUsers) == 0:
		auth.AllowedUsers = append([]string(nil), triggerAuth.AllowedUsers...)
	case len(triggerAuth.AllowedUsers) == 0:
		auth.AllowedUsers = append([]string(nil), projectAuth.AllowedUsers...)
	default:
		for _, user := range projectAuth.AllowedUsers {
			if containsProjectUser(triggerAuth.AllowedUsers, user) {
				auth.AllowedUsers = append(auth.AllowedUsers, user)
			}
		}
	}
	return auth
}

func containsProjectUser(users []string, user string) bool {
	for _, candidate := range users {
		if candidate == user {
			return true
		}
	}
	return false
}

func (r *ProjectReconciler) generatedMetadata(project *triggersv1alpha1.Project, trigger triggersv1alpha1.ProjectTrigger) metav1.ObjectMeta {
	return metav1.ObjectMeta{
		Name:      projectGeneratedChildName(project.Name, trigger.Name),
		Namespace: project.Namespace,
		Labels: map[string]string{
			projectGeneratedRuntimeLabel: "true",
			projectNameLabel:             projectLabelValue(project.Name),
			projectUIDLabel:              projectLabelValue(string(project.UID)),
			projectTriggerNameLabel:      projectLabelValue(trigger.Name),
			projectTriggerTypeLabel:      projectLabelValue(string(trigger.Type)),
		},
		Annotations: map[string]string{
			projectGeneratedRuntimeLabel: "true",
			projectNameAnnotation:        project.Name,
			projectUIDAnnotation:         string(project.UID),
			projectTriggerNameAnnotation: trigger.Name,
			projectTriggerTypeAnnotation: string(trigger.Type),
		},
	}
}

func projectGeneratedChildName(projectName, triggerName string) string {
	return triggersv1alpha1.ProjectGeneratedChildName(projectName, triggerName)
}

func projectLabelValue(value string) string {
	return projectDNSName(value)
}

func projectDNSName(value string) string {
	var b strings.Builder
	lastDash := false
	for _, r := range strings.ToLower(value) {
		switch {
		case r >= 'a' && r <= 'z', r >= '0' && r <= '9':
			b.WriteRune(r)
			lastDash = false
		default:
			if !lastDash {
				b.WriteByte('-')
				lastDash = true
			}
		}
	}
	name := strings.Trim(b.String(), "-")
	if name == "" {
		name = "project"
	}
	if len(name) <= 63 {
		return name
	}
	sum := sha256.Sum256([]byte(value))
	suffix := hex.EncodeToString(sum[:])[:8]
	return strings.TrimRight(name[:63-len(suffix)-1], "-") + "-" + suffix
}

func (r *ProjectReconciler) setProjectControllerReference(project *triggersv1alpha1.Project, child client.Object) error {
	if err := ctrl.SetControllerReference(project, child, r.Scheme); err != nil {
		return fmt.Errorf("setting Project controller reference: %w", err)
	}
	return nil
}

func projectGeneratedChildKeyForTrigger(project *triggersv1alpha1.Project, trigger triggersv1alpha1.ProjectTrigger) string {
	return string(trigger.Type) + "/" + projectGeneratedChildName(project.Name, trigger.Name)
}

func projectGeneratedChildKey(child client.Object) string {
	switch child.(type) {
	case *triggersv1alpha1.GitHubRepository:
		return string(triggersv1alpha1.ProjectTriggerTypeGitHub) + "/" + child.GetName()
	case *triggersv1alpha1.SlackAgent:
		return string(triggersv1alpha1.ProjectTriggerTypeSlack) + "/" + child.GetName()
	case *triggersv1alpha1.Cron:
		return string(triggersv1alpha1.ProjectTriggerTypeCron) + "/" + child.GetName()
	case *triggersv1alpha1.LinearProject:
		return string(triggersv1alpha1.ProjectTriggerTypeLinear) + "/" + child.GetName()
	default:
		panic(fmt.Sprintf("unsupported generated child type %T", child))
	}
}

func (r *ProjectReconciler) upsertGeneratedChild(ctx context.Context, desired client.Object) error {
	current := desired.DeepCopyObject().(client.Object)
	current.SetResourceVersion("")
	if err := r.Get(ctx, client.ObjectKeyFromObject(desired), current); err != nil {
		if !apierrors.IsNotFound(err) {
			return err
		}
		if err := r.Create(ctx, desired); err != nil && !apierrors.IsAlreadyExists(err) {
			return fmt.Errorf("creating generated %T %s: %w", desired, desired.GetName(), err)
		}
		return nil
	}
	if current.GetLabels()[projectGeneratedRuntimeLabel] != "true" || current.GetLabels()[projectUIDLabel] != desired.GetLabels()[projectUIDLabel] {
		return fmt.Errorf("generated %T %s conflicts with an existing resource", desired, desired.GetName())
	}

	if generatedChildEqual(current, desired) {
		return nil
	}
	current.SetLabels(desired.GetLabels())
	current.SetAnnotations(mergeGeneratedAnnotations(current.GetAnnotations(), desired.GetAnnotations()))
	current.SetOwnerReferences(desired.GetOwnerReferences())
	switch current := current.(type) {
	case *triggersv1alpha1.GitHubRepository:
		current.Spec = desired.(*triggersv1alpha1.GitHubRepository).Spec
	case *triggersv1alpha1.SlackAgent:
		current.Spec = desired.(*triggersv1alpha1.SlackAgent).Spec
	case *triggersv1alpha1.Cron:
		current.Spec = desired.(*triggersv1alpha1.Cron).Spec
	case *triggersv1alpha1.LinearProject:
		current.Spec = desired.(*triggersv1alpha1.LinearProject).Spec
	default:
		panic(fmt.Sprintf("unsupported generated child type %T", current))
	}
	if err := r.Update(ctx, current); err != nil {
		return fmt.Errorf("updating generated %T %s: %w", desired, desired.GetName(), err)
	}
	return nil
}

func generatedChildEqual(current, desired client.Object) bool {
	if !reflect.DeepEqual(current.GetLabels(), desired.GetLabels()) || !generatedAnnotationsCurrent(current.GetAnnotations(), desired.GetAnnotations()) || !reflect.DeepEqual(current.GetOwnerReferences(), desired.GetOwnerReferences()) {
		return false
	}
	switch current := current.(type) {
	case *triggersv1alpha1.GitHubRepository:
		return reflect.DeepEqual(current.Spec, desired.(*triggersv1alpha1.GitHubRepository).Spec)
	case *triggersv1alpha1.SlackAgent:
		return reflect.DeepEqual(current.Spec, desired.(*triggersv1alpha1.SlackAgent).Spec)
	case *triggersv1alpha1.Cron:
		return reflect.DeepEqual(current.Spec, desired.(*triggersv1alpha1.Cron).Spec)
	case *triggersv1alpha1.LinearProject:
		return reflect.DeepEqual(current.Spec, desired.(*triggersv1alpha1.LinearProject).Spec)
	default:
		panic(fmt.Sprintf("unsupported generated child type %T", current))
	}
}

// generatedAnnotationsCurrent reports whether every project-managed annotation
// on the desired child is already present with the same value. Annotations the
// project controller does not manage (for example the maintainer dispatch
// reservation ledger written at runtime) are ignored so drift detection does
// not fight runtime state.
func generatedAnnotationsCurrent(current, desired map[string]string) bool {
	for key, value := range desired {
		if current[key] != value {
			return false
		}
	}
	return true
}

// mergeGeneratedAnnotations overlays the project-managed annotations onto the
// child's existing annotations. Runtime-owned annotations (such as the
// maintainer dispatch reservation ledger) must survive regeneration: wiping
// them cancels in-flight dispatch reservations and hard-blocks the maintainer.
func mergeGeneratedAnnotations(current, desired map[string]string) map[string]string {
	merged := make(map[string]string, len(current)+len(desired))
	for key, value := range current {
		merged[key] = value
	}
	for key, value := range desired {
		merged[key] = value
	}
	return merged
}

func (r *ProjectReconciler) cleanupGeneratedChildren(ctx context.Context, project *triggersv1alpha1.Project, desired map[string]client.Object) error {
	github := &triggersv1alpha1.GitHubRepositoryList{}
	if err := r.List(ctx, github, client.InNamespace(project.Namespace)); err != nil {
		return err
	}
	children := make([]client.Object, 0, len(github.Items))
	for i := range github.Items {
		children = append(children, &github.Items[i])
	}
	if err := r.deleteStaleGeneratedChildren(ctx, project, desired, children); err != nil {
		return err
	}

	slack := &triggersv1alpha1.SlackAgentList{}
	if err := r.List(ctx, slack, client.InNamespace(project.Namespace)); err != nil {
		return err
	}
	children = children[:0]
	for i := range slack.Items {
		children = append(children, &slack.Items[i])
	}
	if err := r.deleteStaleGeneratedChildren(ctx, project, desired, children); err != nil {
		return err
	}

	cron := &triggersv1alpha1.CronList{}
	if err := r.List(ctx, cron, client.InNamespace(project.Namespace)); err != nil {
		return err
	}
	children = children[:0]
	for i := range cron.Items {
		children = append(children, &cron.Items[i])
	}
	if err := r.deleteStaleGeneratedChildren(ctx, project, desired, children); err != nil {
		return err
	}

	linear := &triggersv1alpha1.LinearProjectList{}
	if err := r.List(ctx, linear, client.InNamespace(project.Namespace)); err != nil {
		return err
	}
	children = children[:0]
	for i := range linear.Items {
		children = append(children, &linear.Items[i])
	}
	return r.deleteStaleGeneratedChildren(ctx, project, desired, children)
}

func (r *ProjectReconciler) deleteStaleGeneratedChildren(ctx context.Context, project *triggersv1alpha1.Project, desired map[string]client.Object, children []client.Object) error {
	for _, child := range children {
		if !projectOwnsGeneratedChild(project, child) {
			continue
		}
		if _, ok := desired[projectGeneratedChildKey(child)]; ok {
			continue
		}
		if err := r.Delete(ctx, child); err != nil && !apierrors.IsNotFound(err) {
			return fmt.Errorf("deleting stale generated %T %s: %w", child, child.GetName(), err)
		}
	}
	return nil
}

func projectOwnsGeneratedChild(project *triggersv1alpha1.Project, child client.Object) bool {
	labels := child.GetLabels()
	if labels[projectGeneratedRuntimeLabel] != "true" || labels[projectUIDLabel] != projectLabelValue(string(project.UID)) {
		return false
	}
	owner := metav1.GetControllerOf(child)
	return owner != nil && owner.APIVersion == triggersv1alpha1.GroupVersion.String() && owner.Kind == "Project" && owner.Name == project.Name && owner.UID == project.UID
}

func projectDisabledTriggerStatus(project *triggersv1alpha1.Project, trigger triggersv1alpha1.ProjectTrigger) triggersv1alpha1.ProjectTriggerStatus {
	return projectTriggerStatus(project, trigger, nil, "Disabled", "trigger is disabled")
}

func projectCompileErrorStatus(project *triggersv1alpha1.Project, trigger triggersv1alpha1.ProjectTrigger, err error) triggersv1alpha1.ProjectTriggerStatus {
	return projectTriggerStatus(project, trigger, err, "CompilationFailed", err.Error())
}

func projectTriggerStatus(project *triggersv1alpha1.Project, trigger triggersv1alpha1.ProjectTrigger, err error, reason, message string) triggersv1alpha1.ProjectTriggerStatus {
	status := triggersv1alpha1.ProjectTriggerStatus{
		Name:               trigger.Name,
		Type:               trigger.Type,
		ObservedGeneration: project.Generation,
	}
	if err != nil {
		status.LastError = err.Error()
	}
	status.Conditions = []metav1.Condition{{
		Type:               "Ready",
		Status:             metav1.ConditionFalse,
		ObservedGeneration: project.Generation,
		Reason:             reason,
		Message:            message,
		LastTransitionTime: metav1.Now(),
	}}
	return status
}

func (r *ProjectReconciler) normalizedChildStatus(ctx context.Context, project *triggersv1alpha1.Project, trigger triggersv1alpha1.ProjectTrigger, desired client.Object) (triggersv1alpha1.ProjectTriggerStatus, bool, error) {
	child := desired.DeepCopyObject().(client.Object)
	if err := r.Get(ctx, client.ObjectKeyFromObject(desired), child); err != nil {
		if apierrors.IsNotFound(err) {
			return projectTriggerStatus(project, trigger, nil, "RuntimeMissing", "generated runtime is not present"), false, nil
		}
		return triggersv1alpha1.ProjectTriggerStatus{}, false, err
	}

	status := triggersv1alpha1.ProjectTriggerStatus{Name: trigger.Name, Type: trigger.Type, ObservedGeneration: child.GetGeneration()}
	switch child := child.(type) {
	case *triggersv1alpha1.GitHubRepository:
		status.Conditions = append([]metav1.Condition(nil), child.Status.Conditions...)
		status.LastActivityTime = child.Status.LastPollTime
		status.LastError = child.Status.LastError
		status.Maintainer = child.Status.Maintainer.DeepCopy()
	case *triggersv1alpha1.SlackAgent:
		status.Conditions = append([]metav1.Condition(nil), child.Status.Conditions...)
		status.LastActivityTime = child.Status.LastEventTime
		status.LastError = child.Status.LastError
	case *triggersv1alpha1.Cron:
		status.Conditions = append([]metav1.Condition(nil), child.Status.Conditions...)
		status.LastActivityTime = child.Status.LastScheduleTime
		status.NextActivityTime = child.Status.NextScheduleTime
		status.LastError = child.Status.LastError
	case *triggersv1alpha1.LinearProject:
		status.Conditions = append([]metav1.Condition(nil), child.Status.Conditions...)
		status.LastActivityTime = child.Status.LastPollTime
		status.LastError = child.Status.LastError
	default:
		panic(fmt.Sprintf("unsupported generated child type %T", child))
	}

	if status.LastError != "" {
		meta.SetStatusCondition(&status.Conditions, metav1.Condition{
			Type:               "Ready",
			Status:             metav1.ConditionFalse,
			ObservedGeneration: child.GetGeneration(),
			Reason:             "RuntimeError",
			Message:            status.LastError,
		})
		return status, false, nil
	}
	if condition := meta.FindStatusCondition(status.Conditions, "Ready"); condition != nil {
		return status, condition.Status == metav1.ConditionTrue, nil
	}
	if status.LastActivityTime != nil || status.NextActivityTime != nil {
		meta.SetStatusCondition(&status.Conditions, metav1.Condition{
			Type:               "Ready",
			Status:             metav1.ConditionTrue,
			ObservedGeneration: child.GetGeneration(),
			Reason:             "RuntimeActive",
			Message:            "generated runtime is active",
		})
		return status, true, nil
	}
	meta.SetStatusCondition(&status.Conditions, metav1.Condition{
		Type:               "Ready",
		Status:             metav1.ConditionUnknown,
		ObservedGeneration: child.GetGeneration(),
		Reason:             "RuntimePending",
		Message:            "generated runtime has not reported activity",
	})
	return status, false, nil
}

func (r *ProjectReconciler) updateProjectStatus(ctx context.Context, key client.ObjectKey, statuses []triggersv1alpha1.ProjectTriggerStatus, ready bool) error {
	return retry.RetryOnConflict(retry.DefaultRetry, func() error {
		project := &triggersv1alpha1.Project{}
		if err := r.Get(ctx, key, project); err != nil {
			return err
		}
		before := project.DeepCopy().Status
		preserveProjectTriggerTransitionTimes(before.Triggers, statuses)
		project.Status.ObservedGeneration = project.Generation
		project.Status.Triggers = statuses
		setProjectReadyCondition(project, ready)
		if reflect.DeepEqual(before, project.Status) {
			return nil
		}
		base := project.DeepCopy()
		base.Status = before
		return r.Status().Patch(ctx, project, client.MergeFrom(base))
	})
}

func preserveProjectTriggerTransitionTimes(current, desired []triggersv1alpha1.ProjectTriggerStatus) {
	for i := range desired {
		for _, oldStatus := range current {
			if oldStatus.Name != desired[i].Name || oldStatus.Type != desired[i].Type {
				continue
			}
			for j := range desired[i].Conditions {
				for _, oldCondition := range oldStatus.Conditions {
					if desired[i].Conditions[j].Type == oldCondition.Type && desired[i].Conditions[j].Status == oldCondition.Status && desired[i].Conditions[j].Reason == oldCondition.Reason && desired[i].Conditions[j].Message == oldCondition.Message {
						desired[i].Conditions[j].LastTransitionTime = oldCondition.LastTransitionTime
						break
					}
				}
			}
			break
		}
	}
}

func setProjectReadyCondition(project *triggersv1alpha1.Project, ready bool) {
	status := metav1.ConditionFalse
	reason := "TriggersNotReady"
	message := "one or more enabled triggers are not ready"
	if ready {
		status = metav1.ConditionTrue
		reason = "TriggersReady"
		message = "all enabled triggers are ready"
	}
	meta.SetStatusCondition(&project.Status.Conditions, metav1.Condition{
		Type:               "Ready",
		Status:             status,
		ObservedGeneration: project.Generation,
		Reason:             reason,
		Message:            message,
	})
}

func (r *ProjectReconciler) SetupWithManager(mgr ctrl.Manager) error {
	return ctrl.NewControllerManagedBy(mgr).
		For(&triggersv1alpha1.Project{}).
		Owns(&triggersv1alpha1.GitHubRepository{}).
		Owns(&triggersv1alpha1.SlackAgent{}).
		Owns(&triggersv1alpha1.Cron{}).
		Owns(&triggersv1alpha1.LinearProject{}).
		Watches(&triggersv1alpha1.Connection{}, handler.EnqueueRequestsFromMapFunc(r.mapConnectionToProjects)).
		Named("project").
		WithOptions(controller.Options{MaxConcurrentReconciles: 1}).
		Complete(r)
}

func (r *ProjectReconciler) mapConnectionToProjects(ctx context.Context, obj client.Object) []reconcile.Request {
	connection, ok := obj.(*triggersv1alpha1.Connection)
	if !ok {
		return nil
	}
	projects := &triggersv1alpha1.ProjectList{}
	if err := r.List(ctx, projects, client.InNamespace(connection.Namespace)); err != nil {
		return nil
	}
	requests := make([]reconcile.Request, 0)
	for _, project := range projects.Items {
		if projectReferencesConnection(&project, connection.Name) {
			requests = append(requests, reconcile.Request{NamespacedName: client.ObjectKeyFromObject(&project)})
		}
	}
	return requests
}

func projectReferencesConnection(project *triggersv1alpha1.Project, connectionName string) bool {
	for _, trigger := range project.Spec.Triggers {
		switch trigger.Type {
		case triggersv1alpha1.ProjectTriggerTypeGitHub:
			if trigger.GitHub != nil && trigger.GitHub.ConnectionRef.Name == connectionName {
				return true
			}
		case triggersv1alpha1.ProjectTriggerTypeSlack:
			if trigger.Slack != nil && trigger.Slack.ConnectionRef.Name == connectionName {
				return true
			}
		case triggersv1alpha1.ProjectTriggerTypeLinear:
			if trigger.Linear != nil && trigger.Linear.ConnectionRef.Name == connectionName {
				return true
			}
		}
	}
	return false
}

