)

const (
	monitorOpenInterval      = 45 * time.Second
	monitorResolvingInterval = 90 * time.Second
	monitorPendingInterval   = 30 * time.Second
	monitorClosedInterval    = 15 * time.Minute
	monitorMaxBackoff        = 15 * time.Minute
)

type PullRequestMonitorReconciler struct {
	client.Client
	Scheme          *runtime.Scheme
	Engine          *PRLoopEngine
	GitHubAppMinter gitHubAppTokenMinter
	Recorder        record.EventRecorder
	Poller          pullRequestGitHubPoller
	Now             func() time.Time
}

// +kubebuilder:rbac:groups=platform.gratefulagents.dev,resources=agentruns,verbs=get;list;watch
// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=githubrepositories,verbs=get;list;watch
// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=pullrequestmonitors,verbs=get;list;watch;update;patch
// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=pullrequestmonitors/status,verbs=get;update;patch
// +kubebuilder:rbac:groups="",resources=secrets,verbs=get
// +kubebuilder:rbac:groups="",resources=events,verbs=create;patch

func (r *PullRequestMonitorReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
	monitor := &triggersv1alpha1.PullRequestMonitor{}
	if err := r.Get(ctx, req.NamespacedName, monitor); err != nil {
		observeMonitorStopped(req.String())
		return ctrl.Result{}, client.IgnoreNotFound(err)
	}
	observeMonitorStarted(req.String())
	now := time.Now()
	if r.Now != nil {
		now = r.Now()
	}
	if monitor.Status.State == "" {
		if err := r.updateStatus(ctx, client.ObjectKeyFromObject(monitor), func(status *triggersv1alpha1.PullRequestMonitorStatus) {
			if status.State == "" {
				status.State = triggersv1alpha1.PullRequestMonitorStatePending
			}
		}); err != nil {
			return ctrl.Result{}, err
		}
		monitor.Status.State = triggersv1alpha1.PullRequestMonitorStatePending
		if r.Recorder != nil {
			r.Recorder.Event(monitor, corev1.EventTypeNormal, "MonitoringStarted", "Started pull request monitoring")
		}
	}
	if monitor.Status.RetryAfter != nil && now.Before(monitor.Status.RetryAfter.Time) {
		return ctrl.Result{RequeueAfter: monitor.Status.RetryAfter.Sub(now)}, nil
	}
	if monitor.Status.RateLimitRemaining == 0 && monitor.Status.RateLimitReset != nil && now.Before(monitor.Status.RateLimitReset.Time) {
		return ctrl.Result{RequeueAfter: monitor.Status.RateLimitReset.Sub(now)}, nil
	}

	run, err := r.validatedImplementer(ctx, monitor)
	if err != nil {
		return r.fail(ctx, monitor, "ValidationFailed", err, now)
	}
	repository, token, err := r.resolveAuth(ctx, monitor, run)
	if err != nil {
		return r.fail(ctx, monitor, "AuthenticationFailed", err, now)
	}
	owner, repo, ok := strings.Cut(normalizeRepositoryName(monitor.Spec.Repository), "/")
	if !ok || owner == "" || repo == "" {
		return r.fail(ctx, monitor, "InvalidRepository", fmt.Errorf("invalid repository %q", monitor.Spec.Repository), now)
	}
	poller := r.Poller
	if poller == nil {
		poller = newPullRequestGitHubPoller(github.NewClient(nil).WithAuthToken(token))
	}

	pullETag := monitor.Status.ETags.Pull
	if monitor.Status.Lifecycle == "" || (!monitor.Status.OpenedDispatched && feedbackDispatchEnabled(run, repository)) {
		// Opened delivery must be retryable. Force a body until its dispatch
		// cursor is durable instead of allowing a 304 to suppress the event.
		pullETag = ""
	}
	started := time.Now()
	pull, response, err := poller.GetPullRequest(ctx, owner, repo, int(monitor.Spec.Number), pullETag)
	observePoll("pull", pollResult(response, err), time.Since(started))
	r.observeResponse("pull", response)
	if err != nil {
		if statusErr := r.updateStatus(ctx, client.ObjectKeyFromObject(monitor), func(status *triggersv1alpha1.PullRequestMonitorStatus) {
			status.PullObservedAt, status.PullError = metav1.NewTime(now), err.Error()
		}); statusErr != nil {
			return ctrl.Result{}, statusErr
		}
		return r.failPoll(ctx, monitor, "PullRequest", err, response, now)
	}
	if response.StatusCode == http.StatusNotModified {
		observeNotModified("pull")
		if err := r.updateStatus(ctx, client.ObjectKeyFromObject(monitor), func(status *triggersv1alpha1.PullRequestMonitorStatus) {
			status.PullObservedAt, status.PullError = metav1.NewTime(now), ""
		}); err != nil {
			return ctrl.Result{}, err
		}
		monitor.Status.PullObservedAt, monitor.Status.PullError = metav1.NewTime(now), ""
	}
	if pull != nil && !strings.EqualFold(pull.URL, monitor.Spec.URL) {
		return r.fail(ctx, monitor, "IdentityMismatch", fmt.Errorf("GitHub returned pull request URL %q, expected %q", pull.URL, monitor.Spec.URL), now)
	}
	lifecycle, headSHA := monitor.Status.Lifecycle, monitor.Status.HeadSHA
	if pull != nil {
		headChanged := monitor.Status.HeadSHA != "" && monitor.Status.HeadSHA != pull.HeadSHA
		lifecycle, headSHA = pullRequestLifecycle(pull), pull.HeadSHA
		if err := r.updateStatus(ctx, client.ObjectKeyFromObject(monitor), func(status *triggersv1alpha1.PullRequestMonitorStatus) {
			applyPullMetadata(status, pull, response)
			status.Lifecycle = lifecycle
			status.MergedAt = metav1.NewTime(pull.MergedAt)
			status.Mergeability = pullRequestMergeability(pull)
			status.PullObservedAt, status.PullError = metav1.NewTime(now), ""
			if headChanged {
				status.Checks, status.Statuses = triggersv1alpha1.PullRequestMonitorHeadRollup{}, triggersv1alpha1.PullRequestMonitorHeadRollup{}
			}
		}); err != nil {
			return ctrl.Result{}, err
		}
		monitor.Status.HeadSHA, monitor.Status.Lifecycle = pull.HeadSHA, lifecycle
	}
	if lifecycle == triggersv1alpha1.PullRequestLifecycleMerged || lifecycle == triggersv1alpha1.PullRequestLifecycleClosed {
		if err := r.updateStatus(ctx, client.ObjectKeyFromObject(monitor), func(status *triggersv1alpha1.PullRequestMonitorStatus) {
			status.LastPollTime = ptrTime(now)
			status.LastError = ""
			status.ConsecutiveErrors = 0
			status.RetryAfter = nil
			meta.SetStatusCondition(&status.Conditions, metav1.Condition{Type: triggersv1alpha1.ConditionPullRequestMonitorReady, Status: metav1.ConditionTrue, Reason: "LifecycleObserved", ObservedGeneration: monitor.Generation, LastTransitionTime: metav1.NewTime(now)})
		}); err != nil {
			return ctrl.Result{}, err
		}
		if lifecycle == triggersv1alpha1.PullRequestLifecycleMerged {
			return ctrl.Result{}, nil
		}
		// GitHub permits reopening a closed pull request, so keep its lifecycle observation alive.
		return ctrl.Result{RequeueAfter: jitter(monitorClosedInterval)}, nil
	}
	if headSHA == "" {
		return r.fail(ctx, monitor, "PullRequestNotObserved", fmt.Errorf("pull request head SHA is unavailable"), now)
	}

	if pull != nil && !monitor.Status.OpenedDispatched && monitor.Status.State != triggersv1alpha1.PullRequestMonitorStateInactive && feedbackDispatchEnabled(run, repository) {
		event := pullRequestEvent(monitor, pull, PREventOpened)
		handled, dispatchErr := r.dispatch(ctx, repository, event)
		if dispatchErr != nil {
			return r.fail(ctx, monitor, "DispatchOpened", dispatchErr, now)
		}
		if err := r.updateStatus(ctx, client.ObjectKeyFromObject(monitor), func(status *triggersv1alpha1.PullRequestMonitorStatus) {
			status.OpenedDispatched = handled
			if handled {
				status.State = monitorStateForRun(run, monitor)
			} else {
				status.State = triggersv1alpha1.PullRequestMonitorStateInactive
			}
		}); err != nil {
			return ctrl.Result{}, err
		}
		monitor.Status.OpenedDispatched = handled
		if !handled {
			monitor.Status.State = triggersv1alpha1.PullRequestMonitorStateInactive
		}
	}

	started = time.Now()
	checks, checksResponse, err := poller.ListCheckRuns(ctx, owner, repo, headSHA)
	observePoll("checks", pollResult(checksResponse, err), time.Since(started))
	r.observeResponse("checks", checksResponse)
	if err != nil {
		if statusErr := r.recordHeadRollup(ctx, monitor, true, polledHeadRollup{HeadSHA: headSHA}, err, now); statusErr != nil {
			return ctrl.Result{}, statusErr
		}
		return r.failPoll(ctx, monitor, "Checks", err, checksResponse, now)
	}
	if err := r.recordHeadRollup(ctx, monitor, true, checks, nil, now); err != nil {
		return ctrl.Result{}, err
	}

	started = time.Now()
	statuses, statusesResponse, err := poller.GetCommitStatus(ctx, owner, repo, headSHA)
	observePoll("statuses", pollResult(statusesResponse, err), time.Since(started))
	r.observeResponse("statuses", statusesResponse)
	if err != nil {
		if statusErr := r.recordHeadRollup(ctx, monitor, false, polledHeadRollup{HeadSHA: headSHA}, err, now); statusErr != nil {
			return ctrl.Result{}, statusErr
		}
		return r.failPoll(ctx, monitor, "Statuses", err, statusesResponse, now)
	}
	if err := r.recordHeadRollup(ctx, monitor, false, statuses, nil, now); err != nil {
		return ctrl.Result{}, err
	}

	discoveredAt := monitor.Spec.DiscoveredAt.Time
	if discoveredAt.IsZero() {
		discoveredAt = now
	}
	initial := discoveredAt.Add(-24 * time.Hour)
	if pull != nil && pull.CreatedAt.After(initial) {
		initial = pull.CreatedAt
	}
	reviewCursor := cursorOrInitial(monitor.Status.LastReviewCursor, initial)
	commentCursor := cursorOrInitial(monitor.Status.LastIssueCommentCursor, initial)

	started = time.Now()
	reviews, reviewResponse, err := poller.ListReviews(ctx, owner, repo, int(monitor.Spec.Number), reviewCursor.Timestamp.Time)
	observePoll("reviews", pollResult(reviewResponse, err), time.Since(started))
	r.observeResponse("reviews", reviewResponse)
	if err := r.recordReviewObservation(ctx, monitor, err, now); err != nil {
		return ctrl.Result{}, err
	}
	if err != nil {
		return r.failPoll(ctx, monitor, "Reviews", err, reviewResponse, now)
	}
	started = time.Now()
	reviewDecision, decisionResponse, err := poller.GetReviewDecision(ctx, owner, repo, int(monitor.Spec.Number), headSHA)
	observePoll("review-decision", pollResult(decisionResponse, err), time.Since(started))
	r.observeResponse("review-decision", decisionResponse)
	if err := r.recordReviewObservation(ctx, monitor, err, now); err != nil {
		return ctrl.Result{}, err
	}
	if err != nil {
		return r.failPoll(ctx, monitor, "ReviewDecision", err, decisionResponse, now)
	}
	started = time.Now()
	comments, commentResponse, err := poller.ListIssueComments(ctx, owner, repo, int(monitor.Spec.Number), commentCursor.Timestamp.Time.Add(-time.Nanosecond))
	observePoll("comments", pollResult(commentResponse, err), time.Since(started))
	r.observeResponse("comments", commentResponse)
	if err := r.recordCommentObservation(ctx, monitor, err, now); err != nil {
		return ctrl.Result{}, err
	}
	if err != nil {
		return r.failPoll(ctx, monitor, "Comments", err, commentResponse, now)
	}

	feedback := combinedFeedback(monitor, pull, reviews, comments, reviewCursor, commentCursor)
	for _, item := range feedback {
		handled := false
		var dispatchErr error
		if monitor.Status.State != triggersv1alpha1.PullRequestMonitorStateInactive && feedbackDispatchEnabled(run, repository) {
			handled, dispatchErr = r.dispatch(ctx, repository, item.event)
		}
		if dispatchErr != nil {
			return r.fail(ctx, monitor, "DispatchFeedback", dispatchErr, now)
		}
		if handled {
			observeFeedbackDispatched()
			if r.Recorder != nil {
				kind := "comment"
				if item.kind == feedbackReview {
					kind = "review"
				}
				r.Recorder.Eventf(monitor, corev1.EventTypeNormal, "FeedbackDispatched", "Dispatched GitHub %s %d from @%s", kind, item.id, item.event.SenderLogin)
			}
		} else {
			observeFeedbackIgnored()
		}
		key := client.ObjectKeyFromObject(monitor)
		if err := r.updateStatus(ctx, key, func(status *triggersv1alpha1.PullRequestMonitorStatus) {
			cursor := &triggersv1alpha1.GitHubObjectCursor{Timestamp: metav1.NewTime(item.at), ID: item.id}
			if item.kind == feedbackReview {
				status.LastReviewCursor = cursor
			} else {
				status.LastIssueCommentCursor = cursor
			}
		}); err != nil {
			return ctrl.Result{}, err
		}
	}

	nextPoll := jitter(intervalForLifecycle(lifecycle, monitorStateForRun(run, monitor)))
	rateLimited := false
	for _, observed := range []gitHubPollResponse{response, checksResponse, statusesResponse, reviewResponse, decisionResponse, commentResponse} {
		if observed.RateLimit > 0 && observed.RateRemaining == 0 && observed.RateReset.After(now) && observed.RateReset.Sub(now) > nextPoll {
			nextPoll = observed.RateReset.Sub(now)
			rateLimited = true
		}
	}
	if rateLimited && r.Recorder != nil {
		r.Recorder.Eventf(monitor, corev1.EventTypeWarning, "RateLimitDelayed", "GitHub rate limit delays polling for %s", nextPoll.Round(time.Second))
	}
	if err := r.updateStatus(ctx, client.ObjectKeyFromObject(monitor), func(status *triggersv1alpha1.PullRequestMonitorStatus) {
		if pull != nil {
			applyPullMetadata(status, pull, response)
		}
		if status.LastReviewCursor == nil {
			status.LastReviewCursor = reviewCursor
		}
		if status.LastIssueCommentCursor == nil {
			status.LastIssueCommentCursor = commentCursor
		}
		status.State = monitorStateForRun(run, monitor)
		status.ReviewDecision = reviewDecision
		status.LastPollTime = ptrTime(now)
		status.LastError = ""
		status.ConsecutiveErrors = 0
		status.RetryAfter = nil
		applyRate(status, response, checksResponse, statusesResponse, reviewResponse, decisionResponse, commentResponse)
		meta.SetStatusCondition(&status.Conditions, metav1.Condition{Type: triggersv1alpha1.ConditionPullRequestMonitorReady, Status: metav1.ConditionTrue, Reason: "Polling", ObservedGeneration: monitor.Generation, LastTransitionTime: metav1.NewTime(now)})
	}); err != nil {
		return ctrl.Result{}, err
	}
	return ctrl.Result{RequeueAfter: nextPoll}, nil
}

func (r *PullRequestMonitorReconciler) validatedImplementer(ctx context.Context, monitor *triggersv1alpha1.PullRequestMonitor) (*platformv1alpha1.AgentRun, error) {
	owner := metav1.GetControllerOf(monitor)
	if owner == nil || owner.APIVersion != platformv1alpha1.GroupVersion.String() || owner.Kind != "AgentRun" || owner.Name != monitor.Spec.ImplementerRef.Name || owner.UID == "" {
		return nil, fmt.Errorf("monitor controller owner is not the referenced AgentRun")
	}
	run := &platformv1alpha1.AgentRun{}
	if err := r.Get(ctx, client.ObjectKey{Namespace: monitor.Namespace, Name: monitor.Spec.ImplementerRef.Name}, run); err != nil {
		return nil, fmt.Errorf("getting implementer: %w", err)
	}
	if run.UID != owner.UID {
		return nil, fmt.Errorf("implementer UID %q does not match controller owner UID %q", run.UID, owner.UID)
	}
	if !runRecordsPullRequestURL(run, monitor.Spec.URL) {
		return nil, fmt.Errorf("implementer does not record pull request URL %q", monitor.Spec.URL)
	}
	if !runDeclaresRepository(run, monitor.Spec.Repository) {
		return nil, fmt.Errorf("implementer does not declare repository %q", monitor.Spec.Repository)
	}
	return run, nil
}

func (r *PullRequestMonitorReconciler) resolveAuth(ctx context.Context, monitor *triggersv1alpha1.PullRequestMonitor, run *platformv1alpha1.AgentRun) (*triggersv1alpha1.GitHubRepository, string, error) {
	if monitor.Spec.GitHubRepositoryRef != nil {
		gh := &triggersv1alpha1.GitHubRepository{}
		key := client.ObjectKey{Namespace: monitor.Namespace, Name: monitor.Spec.GitHubRepositoryRef.Name}
		err := r.Get(ctx, key, gh)
		if err == nil {
			if normalizeRepositoryName(gh.Spec.Owner+"/"+gh.Spec.Repo) != normalizeRepositoryName(monitor.Spec.Repository) {
				return nil, "", fmt.Errorf("explicit GitHubRepository %s/%s does not match %s", key.Namespace, key.Name, monitor.Spec.Repository)
			}
			token, err := resolveGitHubPollingToken(ctx, r.Client, gh, r.GitHubAppMinter)
			return gh, token, err
		}
		if !apierrors.IsNotFound(err) {
			return nil, "", fmt.Errorf("explicit GitHubRepository %s/%s: %w", key.Namespace, key.Name, err)
		}
		// The creation-time repository binding can outlive the referenced object.
		// Fall through to repository discovery and the implementer's token.
	}
	list := &triggersv1alpha1.GitHubRepositoryList{}
	if err := r.List(ctx, list, client.InNamespace(monitor.Namespace)); err != nil {
		return nil, "", err
	}
	sort.Slice(list.Items, func(i, j int) bool { return list.Items[i].Name < list.Items[j].Name })
	var match *triggersv1alpha1.GitHubRepository
	for i := range list.Items {
		gh := &list.Items[i]
		if normalizeRepositoryName(gh.Spec.Owner+"/"+gh.Spec.Repo) != normalizeRepositoryName(monitor.Spec.Repository) {
			continue
		}
		if match != nil {
			return nil, "", fmt.Errorf("multiple GitHubRepositories in namespace %s match %s", monitor.Namespace, monitor.Spec.Repository)
		}
		match = gh
	}
	if match != nil {
		token, err := resolveGitHubPollingToken(ctx, r.Client, match, r.GitHubAppMinter)
		return match, token, err
	}
	if run.Spec.Secrets == nil || strings.TrimSpace(run.Spec.Secrets.GitHubTokenSecret) == "" {
		return nil, "", fmt.Errorf("no matching GitHubRepository or implementer GitHub token Secret")
	}
	token, err := ReadSecretValue(ctx, r.Client, run.Namespace, run.Spec.Secrets.GitHubTokenSecret, "token")
	return nil, token, err
}

type feedbackKind int

const (
	feedbackReview feedbackKind = iota
	feedbackComment
)

type monitorFeedback struct {
	kind  feedbackKind
	at    time.Time
	id    int64
	event PullRequestEvent
}

func combinedFeedback(monitor *triggersv1alpha1.PullRequestMonitor, pull *polledPullRequest, reviews []polledPullRequestReview, comments []polledIssueComment, reviewCursor, commentCursor *triggersv1alpha1.GitHubObjectCursor) []monitorFeedback {
	result := make([]monitorFeedback, 0, len(reviews)+len(comments))
	for _, review := range reviews {
		if !afterCursor(review.SubmittedAt, review.ID, reviewCursor) {
			observeFeedbackIgnored()
			continue
		}
		event := pullRequestEvent(monitor, pull, PREventReviewSubmitted)
		event.SenderLogin, event.SenderAuthorAssociation = review.AuthorLogin, review.AuthorAssociation
		event.ReviewState, event.Body, event.SourceID, event.SourceCreatedAt = review.State, review.Body, review.ID, review.SubmittedAt
		result = append(result, monitorFeedback{kind: feedbackReview, at: review.SubmittedAt, id: review.ID, event: event})
	}
	for _, comment := range comments {
		if !afterCursor(comment.CreatedAt, comment.ID, commentCursor) {
			observeFeedbackIgnored()
			continue
		}
		event := pullRequestEvent(monitor, pull, PREventComment)
		event.SenderLogin, event.SenderAuthorAssociation = comment.AuthorLogin, comment.AuthorAssociation
		event.Body, event.SourceID, event.SourceCreatedAt = comment.Body, comment.ID, comment.CreatedAt
		result = append(result, monitorFeedback{kind: feedbackComment, at: comment.CreatedAt, id: comment.ID, event: event})
	}
	sort.SliceStable(result, func(i, j int) bool {
		if !result[i].at.Equal(result[j].at) {
			return result[i].at.Before(result[j].at)
		}
		if result[i].id != result[j].id {
			return result[i].id < result[j].id
		}
		return result[i].kind < result[j].kind
	})
	return result
}

func pullRequestEvent(monitor *triggersv1alpha1.PullRequestMonitor, pull *polledPullRequest, eventType PullRequestEventType) PullRequestEvent {
	event := PullRequestEvent{
		Type: eventType, Repository: monitor.Spec.Repository, Number: int(monitor.Spec.Number), URL: monitor.Spec.URL,
		Title: monitor.Status.Title, HeadRef: monitor.Status.HeadRef, BaseRef: monitor.Status.BaseRef, AuthorLogin: monitor.Status.AuthorLogin,
		TargetImplementerNamespace: monitor.Namespace, TargetImplementerName: monitor.Spec.ImplementerRef.Name,
	}
	if pull != nil {
		event.Title, event.HeadRef, event.BaseRef, event.AuthorLogin = pull.Title, pull.HeadRef, pull.BaseRef, pull.AuthorLogin
	}
	return event
}

func (r *PullRequestMonitorReconciler) dispatch(ctx context.Context, repository *triggersv1alpha1.GitHubRepository, event PullRequestEvent) (bool, error) {
	if r.Engine == nil {
		return false, fmt.Errorf("PR loop engine is required")
	}
	return r.Engine.HandlePullRequestEvent(ctx, repository, event)
}

func feedbackDispatchEnabled(run *platformv1alpha1.AgentRun, repository *triggersv1alpha1.GitHubRepository) bool {
	return !reviewLoopDisabledForRun(run, repository)
}

func monitorStateForRun(run *platformv1alpha1.AgentRun, monitor *triggersv1alpha1.PullRequestMonitor) triggersv1alpha1.PullRequestMonitorState {
	if monitor != nil {
		switch monitor.Status.State {
		case triggersv1alpha1.PullRequestMonitorStateApproved, triggersv1alpha1.PullRequestMonitorStateBlocked, triggersv1alpha1.PullRequestMonitorStateCancelled, triggersv1alpha1.PullRequestMonitorStateInactive:
			return monitor.Status.State
		}
	}
	if run.Status.Phase == platformv1alpha1.AgentRunPhaseCancelled {
		return triggersv1alpha1.PullRequestMonitorStateCancelled
	}
	loopKey := ""
	if monitor != nil {
		loopKey = prLoopKey(monitor.Spec.Repository, int(monitor.Spec.Number))
	}
	switch loopState(run, loopKey, PRLoopStateLabel) {
	case PRLoopStateResolving:
		return triggersv1alpha1.PullRequestMonitorStateResolving
	case PRLoopStateApproved:
		return triggersv1alpha1.PullRequestMonitorStateApproved
	case PRLoopStateBlocked:
		return triggersv1alpha1.PullRequestMonitorStateBlocked
	default:
		return triggersv1alpha1.PullRequestMonitorStateOpen
	}
}

func (r *PullRequestMonitorReconciler) fail(ctx context.Context, monitor *triggersv1alpha1.PullRequestMonitor, reason string, cause error, now time.Time) (ctrl.Result, error) {
	observeMonitorError(reason)
	delay := backoff(monitor.Status.ConsecutiveErrors + 1)
	err := r.updateStatus(ctx, client.ObjectKeyFromObject(monitor), func(status *triggersv1alpha1.PullRequestMonitorStatus) {
		status.LastError = cause.Error()
		status.ConsecutiveErrors++
		status.RetryAfter = ptrTime(now.Add(delay))
		meta.SetStatusCondition(&status.Conditions, metav1.Condition{Type: triggersv1alpha1.ConditionPullRequestMonitorReady, Status: metav1.ConditionFalse, Reason: reason, Message: cause.Error(), ObservedGeneration: monitor.Generation, LastTransitionTime: metav1.NewTime(now)})
	})
	if r.Recorder != nil {
		r.Recorder.Event(monitor, corev1.EventTypeWarning, reason, cause.Error())
	}
	if err != nil {
		return ctrl.Result{}, err
	}
	return ctrl.Result{RequeueAfter: delay}, nil
}

func (r *PullRequestMonitorReconciler) failPoll(ctx context.Context, monitor *triggersv1alpha1.PullRequestMonitor, operation string, cause error, response gitHubPollResponse, now time.Time) (ctrl.Result, error) {
	result, err := r.fail(ctx, monitor, operation+"Failed", cause, now)
	if err != nil {
		return result, err
	}
	delay := result.RequeueAfter
	if response.RetryAfter > delay {
		delay = response.RetryAfter
	}
	rateLimited := response.RateRemaining == 0 && response.RateLimit > 0 && response.RateReset.After(now)
	if rateLimited && response.RateReset.Sub(now) > delay {
		delay = response.RateReset.Sub(now)
	}
	if delay != result.RequeueAfter {
		err = r.updateStatus(ctx, client.ObjectKeyFromObject(monitor), func(status *triggersv1alpha1.PullRequestMonitorStatus) {
			status.RetryAfter = ptrTime(now.Add(delay))
			applyRate(status, response)
		})
		result.RequeueAfter = delay
	}
	if err == nil && rateLimited && r.Recorder != nil {
		r.Recorder.Eventf(monitor, corev1.EventTypeWarning, "RateLimitDelayed", "GitHub rate limit delays polling for %s", delay.Round(time.Second))
	}
	return result, err
}

func (r *PullRequestMonitorReconciler) updateStatus(ctx context.Context, key types.NamespacedName, mutate func(*triggersv1alpha1.PullRequestMonitorStatus)) error {
	return retry.RetryOnConflict(retry.DefaultRetry, func() error {
		fresh := &triggersv1alpha1.PullRequestMonitor{}
		if err := r.Get(ctx, key, fresh); err != nil {
			return err
		}
		mutate(&fresh.Status)
		return r.Status().Update(ctx, fresh)
	})
}

func (r *PullRequestMonitorReconciler) observeResponse(endpoint string, response gitHubPollResponse) {
	if response.RateLimit != 0 {
		observeRateRemaining(endpoint, response.RateRemaining)
	}
}

func pullRequestLifecycle(pull *polledPullRequest) triggersv1alpha1.PullRequestLifecycle {
	if pull.Merged {
		return triggersv1alpha1.PullRequestLifecycleMerged
	}
	if strings.EqualFold(pull.State, "closed") {
		return triggersv1alpha1.PullRequestLifecycleClosed
	}
	if pull.Draft {
		return triggersv1alpha1.PullRequestLifecycleDraft
	}
	return triggersv1alpha1.PullRequestLifecycleOpen
}

func pullRequestMergeability(pull *polledPullRequest) triggersv1alpha1.PullRequestMergeability {
	if !pull.MergeableKnown || strings.EqualFold(pull.MergeableState, "unknown") {
		return triggersv1alpha1.PullRequestMergeabilityUnknown
	}
	if pull.Mergeable {
		return triggersv1alpha1.PullRequestMergeabilityMergeable
	}
	return triggersv1alpha1.PullRequestMergeabilityConflicting
}

func aggregateReviewDecision(reviews []polledPullRequestReview) triggersv1alpha1.PullRequestReviewDecision {
	latest := map[string]polledPullRequestReview{}
	for _, review := range reviews {
		login := strings.ToLower(strings.TrimSpace(review.AuthorLogin))
		if login == "" || review.SubmittedAt.IsZero() {
			continue
		}
		current, ok := latest[login]
		if !ok || review.SubmittedAt.After(current.SubmittedAt) || review.SubmittedAt.Equal(current.SubmittedAt) && review.ID > current.ID {
			latest[login] = review
		}
	}
	if len(latest) == 0 {
		return triggersv1alpha1.PullRequestReviewDecisionReviewRequired
	}
	approved := false
	for _, review := range latest {
		switch strings.ToLower(review.State) {
		case string(triggersv1alpha1.PullRequestReviewDecisionChangesRequested):
			return triggersv1alpha1.PullRequestReviewDecisionChangesRequested
		case string(triggersv1alpha1.PullRequestReviewDecisionApproved):
			approved = true
		}
	}
	if approved {
		return triggersv1alpha1.PullRequestReviewDecisionApproved
	}
	return triggersv1alpha1.PullRequestReviewDecisionReviewRequired
}

func (r *PullRequestMonitorReconciler) recordHeadRollup(ctx context.Context, monitor *triggersv1alpha1.PullRequestMonitor, checks bool, rollup polledHeadRollup, cause error, now time.Time) error {
	return r.updateStatus(ctx, client.ObjectKeyFromObject(monitor), func(status *triggersv1alpha1.PullRequestMonitorStatus) {
		value := triggersv1alpha1.PullRequestMonitorHeadRollup{HeadSHA: rollup.HeadSHA, State: rollup.State, Count: int32(rollup.Count), ObservedAt: metav1.NewTime(now)}
		if cause != nil {
			value.Error = cause.Error()
		}
		if checks {
			status.Checks = value
		} else {
			status.Statuses = value
		}
	})
}

func (r *PullRequestMonitorReconciler) recordReviewObservation(ctx context.Context, monitor *triggersv1alpha1.PullRequestMonitor, cause error, now time.Time) error {
	return r.updateStatus(ctx, client.ObjectKeyFromObject(monitor), func(status *triggersv1alpha1.PullRequestMonitorStatus) {
		status.ReviewsObservedAt, status.ReviewsError = metav1.NewTime(now), ""
		if cause != nil {
			status.ReviewsError = cause.Error()
		}
	})
}

func (r *PullRequestMonitorReconciler) recordCommentObservation(ctx context.Context, monitor *triggersv1alpha1.PullRequestMonitor, cause error, now time.Time) error {
	return r.updateStatus(ctx, client.ObjectKeyFromObject(monitor), func(status *triggersv1alpha1.PullRequestMonitorStatus) {
		status.CommentsObservedAt, status.CommentsError = metav1.NewTime(now), ""
		if cause != nil {
			status.CommentsError = cause.Error()
		}
	})
}

func applyPullMetadata(status *triggersv1alpha1.PullRequestMonitorStatus, pull *polledPullRequest, response gitHubPollResponse) {
	status.Title, status.HeadRef, status.HeadSHA, status.BaseRef, status.AuthorLogin = pull.Title, pull.HeadRef, pull.HeadSHA, pull.BaseRef, pull.AuthorLogin
	if response.ETag != "" {
		status.ETags.Pull = response.ETag
	}
}

func applyRate(status *triggersv1alpha1.PullRequestMonitorStatus, responses ...gitHubPollResponse) {
	for _, response := range responses {
		if response.RateLimit != 0 {
			status.RateLimitRemaining = int32(response.RateRemaining)
		}
		if !response.RateReset.IsZero() {
			status.RateLimitReset = ptrTime(response.RateReset)
		}
	}
}

func cursorOrInitial(cursor *triggersv1alpha1.GitHubObjectCursor, initial time.Time) *triggersv1alpha1.GitHubObjectCursor {
	if cursor != nil {
		return cursor.DeepCopy()
	}
	return &triggersv1alpha1.GitHubObjectCursor{Timestamp: metav1.NewTime(initial)}
}

func afterCursor(timestamp time.Time, id int64, cursor *triggersv1alpha1.GitHubObjectCursor) bool {
	return timestamp.After(cursor.Timestamp.Time) || timestamp.Equal(cursor.Timestamp.Time) && id > cursor.ID
}

func ptrTime(value time.Time) *metav1.Time {
	result := metav1.NewTime(value)
	return &result
}

func pollResult(response gitHubPollResponse, err error) string {
	if err != nil {
		return "error"
	}
	if response.StatusCode == http.StatusNotModified {
		return "not_modified"
	}
	return "success"
}

func intervalForLifecycle(lifecycle triggersv1alpha1.PullRequestLifecycle, state triggersv1alpha1.PullRequestMonitorState) time.Duration {
	if lifecycle == triggersv1alpha1.PullRequestLifecycleClosed {
		return monitorClosedInterval
	}
	return intervalForState(state)
}

func intervalForState(state triggersv1alpha1.PullRequestMonitorState) time.Duration {
	switch state {
	case triggersv1alpha1.PullRequestMonitorStateResolving:
		return monitorResolvingInterval
	case triggersv1alpha1.PullRequestMonitorStateOpen, triggersv1alpha1.PullRequestMonitorStateApproved, triggersv1alpha1.PullRequestMonitorStateBlocked, triggersv1alpha1.PullRequestMonitorStateCancelled, triggersv1alpha1.PullRequestMonitorStateInactive:
		return monitorOpenInterval
	default:
		return monitorPendingInterval
	}
}

func jitter(base time.Duration) time.Duration {
	return time.Duration(float64(base) * (0.9 + rand.Float64()*0.2))
}

func backoff(errors int32) time.Duration {
	delay := monitorPendingInterval
	for i := int32(1); i < errors && delay < monitorMaxBackoff; i++ {
		delay *= 2
	}
	if delay > monitorMaxBackoff {
		return monitorMaxBackoff
	}
	return delay
}

func (r *PullRequestMonitorReconciler) SetupWithManager(mgr ctrl.Manager) error {
	return ctrl.NewControllerManagedBy(mgr).
		For(&triggersv1alpha1.PullRequestMonitor{}).
		Named("pull-request-monitor").
		WithEventFilter(predicate.GenerationChangedPredicate{}).
		WithOptions(controller.Options{MaxConcurrentReconciles: 4}).
		Complete(r)
}

package triggers

import (
	"sync"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	crmetrics "sigs.k8s.io/controller-runtime/pkg/metrics"
)

var (
	pullRequestMonitorActive = prometheus.NewGauge(prometheus.GaugeOpts{
		Namespace: "gratefulagents",
		Subsystem: "pull_request_monitor",
		Name:      "active",
		Help:      "Number of active pull request monitors.",
	})
	pullRequestMonitorPolls = prometheus.NewCounterVec(prometheus.CounterOpts{
		Namespace: "gratefulagents",
		Subsystem: "pull_request_monitor",
		Name:      "polls_total",
		Help:      "Number of GitHub polls by endpoint and result.",
	}, []string{"endpoint", "result"})
	pullRequestMonitorNotModified = prometheus.NewCounterVec(prometheus.CounterOpts{
		Namespace: "gratefulagents",
		Subsystem: "pull_request_monitor",
		Name:      "not_modified_total",
		Help:      "Number of GitHub poll responses with HTTP status 304.",
	}, []string{"endpoint"})
	pullRequestMonitorPollLatency = prometheus.NewHistogramVec(prometheus.HistogramOpts{
		Namespace: "gratefulagents",
		Subsystem: "pull_request_monitor",
		Name:      "poll_latency_seconds",
		Help:      "GitHub poll latency in seconds.",
		Buckets:   prometheus.DefBuckets,
	}, []string{"endpoint"})
	pullRequestMonitorFeedback = prometheus.NewCounterVec(prometheus.CounterOpts{
		Namespace: "gratefulagents",
		Subsystem: "pull_request_monitor",
		Name:      "feedback_total",
		Help:      "Number of feedback events dispatched or ignored.",
	}, []string{"result"})
	pullRequestMonitorErrors = prometheus.NewCounterVec(prometheus.CounterOpts{
		Namespace: "gratefulagents",
		Subsystem: "pull_request_monitor",
		Name:      "errors_total",
		Help:      "Number of pull request monitor errors by operation.",
	}, []string{"operation"})
	pullRequestMonitorRateRemaining = prometheus.NewGaugeVec(prometheus.GaugeOpts{
		Namespace: "gratefulagents",
		Subsystem: "pull_request_monitor",
		Name:      "rate_remaining",
		Help:      "Latest observed GitHub API rate-limit remaining value.",
	}, []string{"endpoint"})
	pullRequestMonitorTerminalStops = prometheus.NewCounterVec(prometheus.CounterOpts{
		Namespace: "gratefulagents",
		Subsystem: "pull_request_monitor",
		Name:      "terminal_stops_total",
		Help:      "Number of monitors stopped because the pull request reached a terminal state.",
	}, []string{"reason"})
	activeMonitorMu   sync.Mutex
	activeMonitorKeys = map[string]struct{}{}
)

func init() {
	crmetrics.Registry.MustRegister(
		pullRequestMonitorActive,
		pullRequestMonitorPolls,
		pullRequestMonitorNotModified,
		pullRequestMonitorPollLatency,
		pullRequestMonitorFeedback,
		pullRequestMonitorErrors,
		pullRequestMonitorRateRemaining,
		pullRequestMonitorTerminalStops,
	)
}

func observeMonitorStarted(key string) {
	activeMonitorMu.Lock()
	defer activeMonitorMu.Unlock()
	activeMonitorKeys[key] = struct{}{}
	pullRequestMonitorActive.Set(float64(len(activeMonitorKeys)))
}

func observeMonitorStopped(key string) {
	activeMonitorMu.Lock()
	defer activeMonitorMu.Unlock()
	delete(activeMonitorKeys, key)
	pullRequestMonitorActive.Set(float64(len(activeMonitorKeys)))
}

func observePoll(endpoint, result string, duration time.Duration) {
	pullRequestMonitorPolls.WithLabelValues(endpoint, result).Inc()
	pullRequestMonitorPollLatency.WithLabelValues(endpoint).Observe(duration.Seconds())
}

func observeNotModified(endpoint string) {
	pullRequestMonitorNotModified.WithLabelValues(endpoint).Inc()
}

func observeFeedbackDispatched() {
	pullRequestMonitorFeedback.WithLabelValues("dispatched").Inc()
}

func observeFeedbackIgnored() {
	pullRequestMonitorFeedback.WithLabelValues("ignored").Inc()
}

func observeMonitorError(operation string) {
	pullRequestMonitorErrors.WithLabelValues(operation).Inc()
}

func observeRateRemaining(endpoint string, remaining int) {
	pullRequestMonitorRateRemaining.WithLabelValues(endpoint).Set(float64(remaining))
}

func observeTerminalStop(reason string) {
	pullRequestMonitorTerminalStops.WithLabelValues(reason).Inc()
}

package triggers

// Project is a passive trigger CRD (no reconciler) but the scheme registers
// it so the informer cache watches it.  The controller-manager service account
// needs list/watch (cache), get (dashboard reads), update/patch (status writes
// from dashboard helpers), and create/delete (the dashboard auto-provisions a
// personal default chat Project per user).
// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=projects,verbs=get;list;watch;create;update;patch;delete
// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=projects/status,verbs=get;update;patch

// The dashboard (served from the controller-manager binary) manages Cron,
// GitHubRepository, LinearProject, and SecurityScan triggers through its write
// RPCs: create/update/delete for crons, GitHub repositories, and security
// scans (onboarding, settings, rollback of partially-created triggers) and
// update for Linear projects (run-defaults editor). The reconcilers' own
// markers only cover get/list/watch/update/patch, so grant the write verbs
// here.
// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=crons;githubrepositories;linearprojects;securityscans,verbs=get;list;watch;create;update;patch;delete

// The dashboard also manages the reusable security library resources
// (SecurityWorkflow, SecurityRanker, SecurityPostScript, SecurityPolicyPack,
// and SecurityProgram) through its List/Get/Create/Update/Delete RPCs. The
// library reconcilers' own markers only cover reads and status writes, so
// grant the write verbs here.
// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=securityworkflows;securityrankers;securitypostscripts;securitypolicypacks;securityprograms,verbs=get;list;watch;create;update;patch;delete

// The dashboard also manages Connection resources (shared GitHub/Slack/Linear
// credential references used by project triggers) through its
// Create/Update/DeleteConnection RPCs. The Project reconciler's own marker
// only covers get/list/watch, so grant the write verbs here.
// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=connections,verbs=get;list;watch;create;update;patch;delete

package triggers

import (
	"context"
	"fmt"
	"log"
	"sort"
	"strings"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
	"github.com/gratefulagents/gratefulagents/internal/auth"
	"github.com/gratefulagents/gratefulagents/internal/store"
	corev1 "k8s.io/api/core/v1"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/client-go/util/retry"
	ctrl "sigs.k8s.io/controller-runtime"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

const (
	GeneratedRuntimeMarkerMetadataKey = "triggers.gratefulagents.dev/generated-runtime"
	ProjectNameMetadataKey            = "triggers.gratefulagents.dev/project-name"
	ProjectUIDMetadataKey             = "triggers.gratefulagents.dev/project-uid"
	ProjectTriggerNameMetadataKey     = "triggers.gratefulagents.dev/project-trigger-name"
	ProjectTriggerTypeMetadataKey     = "triggers.gratefulagents.dev/project-trigger-type"
	// RuntimeTriggerNameAnnotation preserves the generated adapter identity used
	// for deduplication and concurrency while Trigger.Name exposes Project-local provenance.
	RuntimeTriggerNameAnnotation = "triggers.gratefulagents.dev/runtime-trigger-name"
)

type TriggerRunSpec struct {
	RunName            string
	Namespace          string
	TriggerKind        string
	TriggerName        string
	ExternalID         string
	ExternalIdentifier string
	ExternalURL        string
	SeedMessage        string
	// Revision optionally pins the run's primary repository checkout to a
	// specific commit, tag, or branch instead of the base branch head.
	Revision          string
	Defaults          triggersv1alpha1.AgentRunDefaults
	OwnerRef          client.Object
	Scheme            *runtime.Scheme
	Labels            map[string]string
	Annotations       map[string]string
	Context           *platformv1alpha1.AgentRunContext
	ModeRef           *platformv1alpha1.ModeRef
	GitHubTokenSecret string
	// Limits, when set, seeds the created run's spec.limits. Fields it
	// leaves unset are still defaulted from trigger policy (e.g.
	// defaults.timeout fills limits.maxRuntime only when unset).
	Limits *platformv1alpha1.AgentRunLimits
	// ToolPolicy, when set, narrows which tools the created run's worker
	// registers (spec.toolPolicy). It can only narrow, never widen.
	ToolPolicy *platformv1alpha1.AgentRunToolPolicy
	// OwnerID, when set, is recorded in the collaboration store as the run's
	// owner so that user can manage the run (stop, delete, share) from the
	// dashboard. Trigger-created runs without an owner are only manageable by
	// admins.
	OwnerID string
	// SlackTokensSecret optionally grants the run pod read-only Slack
	// credentials (bot/user tokens) for agent-side Slack read tools.
	SlackTokensSecret string

	SeedLogPrefix                  string
	SeedOnAlreadyExists            bool
	FetchExistingOnAlreadyExists   bool
	DetailedCredentialErrorContext bool
	// AuthorizePersisted validates the API-persisted object before credentials,
	// session messages, or other post-create side effects are applied. Callers
	// must fail closed when an existing predictable name cannot be proven theirs.
	AuthorizationReader client.Reader
	AuthorizePersisted  func(context.Context, *platformv1alpha1.AgentRun, bool) error
	AfterCreate         func(context.Context, *platformv1alpha1.AgentRun, bool) error
}

func BuildTriggerRun(spec TriggerRunSpec) *platformv1alpha1.AgentRun {
	d := spec.Defaults
	provider := triggersv1alpha1.NormalizeProvider(d.Provider)
	authMode := triggersv1alpha1.NormalizeAuthMode(string(d.AuthMode))
	model := strings.TrimSpace(d.Model)
	if model == "" {
		model = triggersv1alpha1.DefaultMainModelForProvider(provider)
	}
	reasoningLevel := d.ReasoningLevel
	if reasoningLevel == "" {
		reasoningLevel = platformv1alpha1.ReasoningMax
	}
	gitHubTokenSecret := spec.GitHubTokenSecret
	if gitHubTokenSecret == "" {
		gitHubTokenSecret = d.Secrets.GithubToken
	}
	triggerName := spec.TriggerName
	triggerType := ""
	runContext := spec.Context
	if projectName, generated := generatedProjectRuntime(spec.OwnerRef); generated {
		triggerName = metadataValue(spec.OwnerRef, ProjectTriggerNameMetadataKey)
		triggerType = strings.ToLower(metadataValue(spec.OwnerRef, ProjectTriggerTypeMetadataKey))
		runContext = &platformv1alpha1.AgentRunContext{ProjectRef: &platformv1alpha1.ProjectRef{Kind: "Project", Name: projectName}}
	}
	run := &platformv1alpha1.AgentRun{}
	run.Name = spec.RunName
	run.Namespace = spec.Namespace
	run.Finalizers = []string{platformv1alpha1.AgentRunCleanupFinalizer}
	run.Labels = copyStringMap(spec.Labels)
	run.Annotations = copyStringMap(spec.Annotations)
	if _, generated := generatedProjectRuntime(spec.OwnerRef); generated {
		if run.Annotations == nil {
			run.Annotations = map[string]string{}
		}
		run.Annotations[RuntimeTriggerNameAnnotation] = spec.TriggerName
	}
	if spec.AuthorizePersisted != nil {
		if run.Annotations == nil {
			run.Annotations = map[string]string{}
		}
		run.Annotations[platformv1alpha1.AuthorizationPendingAnnotation] = "true"
	}
	run.Spec = platformv1alpha1.AgentRunSpec{
		Trigger: platformv1alpha1.TriggerRef{
			Kind: spec.TriggerKind,
			Name: triggerName,
			Type: triggerType,
			ExternalRef: &platformv1alpha1.ExternalRef{
				ID:         spec.ExternalID,
				Identifier: spec.ExternalIdentifier,
				URL:        spec.ExternalURL,
			},
		},
		Repository: platformv1alpha1.RepositoryContext{
			URL:             d.RepoURL,
			BaseBranch:      d.BaseBranch,
			Revision:        spec.Revision,
			AdditionalRepos: append([]string(nil), d.AdditionalRepos...),
		},
		Context:        runContext,
		ExecutionMode:  d.ResolveExecutionMode(),
		WorkflowMode:   d.ResolveWorkflowMode(),
		Model:          prefixModelWithProvider(model, provider),
		AuthMode:       authMode,
		ReasoningLevel: reasoningLevel,
		OpenAIBaseURL:  triggersv1alpha1.ResolveOpenAIBaseURLWithAuth(provider, d.OpenAIBaseURL, authMode),
		Image:          d.Image,
		Secrets: &platformv1alpha1.AgentRunSecrets{
			ClaudeAPIKeySecret: d.Secrets.ClaudeApiKey,
			OpenAIOAuthSecret:  d.Secrets.OpenAIOAuthSecret,
			GitHubTokenSecret:  gitHubTokenSecret,
			SlackTokensSecret:  spec.SlackTokensSecret,
			ProviderKeys:       d.Secrets.ProviderKeys,
		},
	}
	if d.Team != nil {
		run.Spec.Team = d.Team.DeepCopy()
	}
	if spec.Limits != nil {
		run.Spec.Limits = spec.Limits.DeepCopy()
	}
	if spec.ToolPolicy != nil {
		run.Spec.ToolPolicy = spec.ToolPolicy.DeepCopy()
	}
	applyPolicyRefs(&run.Spec, d)
	if spec.ModeRef != nil {
		run.Spec.ModeRef = spec.ModeRef.DeepCopy()
	} else if d.ModeRef != nil {
		run.Spec.ModeRef = d.ModeRef.DeepCopy()
	}
	return run
}

func CreateTriggerRun(ctx context.Context, c client.Client, stateStore store.StateStore, spec TriggerRunSpec) (bool, *platformv1alpha1.AgentRun, error) {
	if err := validateTriggerRunDefaults(spec); err != nil {
		return false, nil, err
	}
	if err := resolveGeneratedProjectOwner(ctx, stateStore, &spec); err != nil {
		return false, nil, err
	}
	run := BuildTriggerRun(spec)
	if err := snapshotTriggerOwnerRoleModels(ctx, stateStore, run, spec); err != nil {
		return false, run, err
	}
	if spec.OwnerRef != nil && !isGeneratedProjectRuntime(spec.OwnerRef) {
		if err := ctrl.SetControllerReference(spec.OwnerRef, run, spec.Scheme); err != nil {
			return false, run, fmt.Errorf("setting owner reference on AgentRun: %w", err)
		}
	}
	created := false
	if err := c.Create(ctx, run); err != nil {
		if !apierrors.IsAlreadyExists(err) {
			return false, run, fmt.Errorf("creating AgentRun: %w", err)
		}
		if spec.FetchExistingOnAlreadyExists {
			if getErr := c.Get(ctx, client.ObjectKey{Namespace: run.Namespace, Name: run.Name}, run); getErr != nil {
				return false, run, fmt.Errorf("getting existing AgentRun: %w", getErr)
			}
		}
	} else {
		created = true
	}
	if spec.AuthorizePersisted != nil {
		if err := spec.AuthorizePersisted(ctx, run, created); err != nil {
			if created {
				_ = c.Delete(ctx, run)
			}
			return false, run, fmt.Errorf("authorizing persisted AgentRun: %w", err)
		}
	}
	if created {
		if err := retainRunInstructionConfigMap(ctx, c, spec.Scheme, run); err != nil {
			_ = c.Delete(ctx, run)
			return false, run, err
		}
		recordTriggerRunOwner(ctx, stateStore, run, spec)
	}
	if spec.AfterCreate != nil {
		if err := spec.AfterCreate(ctx, run, created); err != nil {
			return false, run, err
		}
	}
	if created || spec.SeedOnAlreadyExists {
		if err := seedTriggerRunSession(ctx, stateStore, run, spec, created); err != nil {
			return false, run, err
		}
	}
	if spec.AuthorizePersisted != nil {
		if err := releaseTriggerRunAuthorization(ctx, spec.AuthorizationReader, c, run); err != nil {
			return false, run, fmt.Errorf("releasing AgentRun authorization hold: %w", err)
		}
	}
	return created, run, nil
}

func releaseTriggerRunAuthorization(ctx context.Context, reader client.Reader, c client.Client, run *platformv1alpha1.AgentRun) error {
	if c == nil || run == nil || run.UID == "" {
		return fmt.Errorf("persisted AgentRun identity is required")
	}
	if reader == nil {
		reader = c
	}
	key := client.ObjectKeyFromObject(run)
	if err := retry.RetryOnConflict(retry.DefaultRetry, func() error {
		fresh := &platformv1alpha1.AgentRun{}
		if err := reader.Get(ctx, key, fresh); err != nil {
			return err
		}
		if fresh.UID != run.UID {
			return fmt.Errorf("AgentRun UID changed before authorization release")
		}
		if fresh.Annotations[platformv1alpha1.AuthorizationPendingAnnotation] != "true" {
			return nil
		}
		patch := client.MergeFromWithOptions(fresh.DeepCopy(), client.MergeFromWithOptimisticLock{})
		delete(fresh.Annotations, platformv1alpha1.AuthorizationPendingAnnotation)
		return c.Patch(ctx, fresh, patch)
	}); err != nil {
		return err
	}
	delete(run.Annotations, platformv1alpha1.AuthorizationPendingAnnotation)
	return nil
}

type userRoleModelPreferenceReader interface {
	ListUserRoleModelPreferences(context.Context, string) ([]*auth.UserRoleModelPreference, error)
}

func retainRunInstructionConfigMap(ctx context.Context, c client.Client, scheme *runtime.Scheme, run *platformv1alpha1.AgentRun) error {
	if c == nil || scheme == nil || run == nil {
		return nil
	}
	name := strings.TrimSpace(run.Annotations["platform.gratefulagents.dev/instructions-configmap-ref"])
	if name == "" {
		return nil
	}
	// The ConfigMap was created by the trigger moments before this call, so a
	// cached read here can race the informer and report NotFound even though
	// the object exists. Patch the owner reference blindly instead of
	// read-modify-write: the merge patch replaces metadata.ownerReferences
	// wholesale on the API server, which is exactly the intended transfer of
	// ownership to the run, without depending on cache freshness.
	configMap := &corev1.ConfigMap{ObjectMeta: metav1.ObjectMeta{Namespace: run.Namespace, Name: name}}
	base := configMap.DeepCopy()
	if err := ctrl.SetControllerReference(run, configMap, scheme); err != nil {
		return fmt.Errorf("setting AgentRun owner on instructions ConfigMap: %w", err)
	}
	if err := c.Patch(ctx, configMap, client.MergeFrom(base)); err != nil {
		return fmt.Errorf("retaining instructions ConfigMap for AgentRun: %w", err)
	}
	return nil
}

func resolveGeneratedProjectOwner(ctx context.Context, stateStore store.StateStore, spec *TriggerRunSpec) error {
	if stateStore == nil || spec == nil || strings.TrimSpace(spec.OwnerID) != "" {
		return nil
	}
	projectName, generated := generatedProjectRuntime(spec.OwnerRef)
	if !generated {
		return nil
	}
	owner, err := stateStore.GetResourceOwner(ctx, "project", projectName, spec.Namespace)
	if err != nil {
		return fmt.Errorf("resolve Project trigger owner: %w", err)
	}
	if owner != nil {
		spec.OwnerID = strings.TrimSpace(owner.OwnerID)
	}
	return nil
}

func snapshotTriggerOwnerRoleModels(ctx context.Context, stateStore store.StateStore, run *platformv1alpha1.AgentRun, spec TriggerRunSpec) error {
	if stateStore == nil || run == nil {
		return nil
	}
	ownerID := strings.TrimSpace(spec.OwnerID)
	if ownerID == "" {
		// Resource types must match the dashboard's ownership records (e.g.
		// SecurityScan owners are recorded under "securityscan").
		resourceTypes := map[string]string{"LinearProject": "linear_project", "GitHubRepository": "github_repository", "Cron": "cron", securityScanKind: "securityscan"}
		resourceType := resourceTypes[spec.TriggerKind]
		if resourceType == "" {
			return nil
		}
		owner, err := stateStore.GetResourceOwner(ctx, resourceType, spec.TriggerName, spec.Namespace)
		if err != nil {
			return fmt.Errorf("resolve trigger owner role models: %w", err)
		}
		if owner == nil {
			return nil
		}
		ownerID = strings.TrimSpace(owner.OwnerID)
	}
	reader, ok := stateStore.(userRoleModelPreferenceReader)
	if !ok || ownerID == "" {
		return nil
	}
	preferences, err := reader.ListUserRoleModelPreferences(ctx, ownerID)
	if err != nil {
		return fmt.Errorf("load trigger owner role models: %w", err)
	}
	byRole := map[string]*platformv1alpha1.AgentRunRoleModelOverride{}
	for _, preference := range preferences {
		if preference == nil || strings.TrimSpace(preference.RoleName) == "" {
			continue
		}
		override := byRole[preference.RoleName]
		if override == nil {
			override = &platformv1alpha1.AgentRunRoleModelOverride{Role: preference.RoleName}
			byRole[preference.RoleName] = override
		}
		if preference.UseParentModel {
			override.UseParentModel = true
			override.ModelsByProvider = nil
			continue
		}
		if override.UseParentModel || strings.TrimSpace(preference.Provider) == "" || strings.TrimSpace(preference.Model) == "" {
			continue
		}
		if override.ModelsByProvider == nil {
			override.ModelsByProvider = map[string]string{}
		}
		override.ModelsByProvider[preference.Provider] = preference.Model
	}
	roles := make([]string, 0, len(byRole))
	for role := range byRole {
		roles = append(roles, role)
	}
	sort.Strings(roles)
	for _, role := range roles {
		run.Spec.RoleModelOverrides = append(run.Spec.RoleModelOverrides, *byRole[role])
	}
	return nil
}

func generatedProjectRuntime(owner client.Object) (string, bool) {
	if !isGeneratedProjectRuntime(owner) {
		return "", false
	}
	return metadataValue(owner, ProjectNameMetadataKey), true
}

func isGeneratedProjectRuntime(owner client.Object) bool {
	return owner != nil &&
		metadataValue(owner, GeneratedRuntimeMarkerMetadataKey) != "" &&
		metadataValue(owner, ProjectNameMetadataKey) != "" &&
		metadataValue(owner, ProjectUIDMetadataKey) != "" &&
		metadataValue(owner, ProjectTriggerNameMetadataKey) != "" &&
		metadataValue(owner, ProjectTriggerTypeMetadataKey) != ""
}

func metadataValue(owner client.Object, key string) string {
	if value := strings.TrimSpace(owner.GetAnnotations()[key]); value != "" {
		return value
	}
	return strings.TrimSpace(owner.GetLabels()[key])
}

// RuntimeTriggerName returns the concrete adapter identity used by source
// controllers. Project-generated runs expose the declaration name in
// Trigger.Name and retain the adapter name in an internal annotation.
func RuntimeTriggerName(run *platformv1alpha1.AgentRun) string {
	if run == nil {
		return ""
	}
	if name := strings.TrimSpace(run.Annotations[RuntimeTriggerNameAnnotation]); name != "" {
		return name
	}
	return strings.TrimSpace(run.Spec.Trigger.Name)
}

func TriggerRunMatches(run *platformv1alpha1.AgentRun, kind, runtimeName string) bool {
	return run != nil && run.Spec.Trigger.MatchesKind(kind) && RuntimeTriggerName(run) == runtimeName
}

func validateTriggerRunDefaults(spec TriggerRunSpec) error {
	d := spec.Defaults
	provider := triggersv1alpha1.NormalizeProvider(d.Provider)
	authMode := triggersv1alpha1.NormalizeAuthMode(string(d.AuthMode))
	model := strings.TrimSpace(d.Model)
	if model == "" {
		model = triggersv1alpha1.DefaultMainModelForProvider(provider)
	}
	if model == "" {
		return fmt.Errorf("%s %s/%s spec.defaults.model is required for provider %s", spec.TriggerKind, spec.Namespace, spec.TriggerName, provider)
	}
	if triggersv1alpha1.IsOpenAICompatibleProvider(provider) {
		switch strings.ToLower(model) {
		case "small", "medium", "large":
			return fmt.Errorf("%s %s/%s spec.defaults.model must be an explicit model id; aliases (%s) are not allowed", spec.TriggerKind, spec.Namespace, spec.TriggerName, model)
		}
	}
	if err := triggersv1alpha1.ValidateProviderAuthMode(provider, authMode); err != nil {
		return fmt.Errorf("%s %s/%s auth configuration is invalid: %w", spec.TriggerKind, spec.Namespace, spec.TriggerName, err)
	}
	if triggersv1alpha1.RequiresOpenAIOAuthSecret(provider, authMode) && strings.TrimSpace(d.Secrets.OpenAIOAuthSecret) == "" {
		if spec.DetailedCredentialErrorContext {
			return fmt.Errorf("%s %s/%s requires spec.defaults.secrets.openaiOAuthSecret for provider=%s authMode=%s", spec.TriggerKind, spec.Namespace, spec.TriggerName, provider, authMode)
		}
		return fmt.Errorf("%s %s/%s requires spec.defaults.secrets.openaiOAuthSecret", spec.TriggerKind, spec.Namespace, spec.TriggerName)
	}
	if !triggersv1alpha1.OAuthSupportedForProvider(provider) && strings.TrimSpace(d.Secrets.OpenAIOAuthSecret) != "" {
		return fmt.Errorf("%s %s/%s spec.defaults.secrets.openaiOAuthSecret is only supported for OAuth-capable providers", spec.TriggerKind, spec.Namespace, spec.TriggerName)
	}
	if !triggersv1alpha1.RequiresOpenAIOAuthSecret(provider, authMode) && strings.TrimSpace(d.Secrets.ClaudeApiKey) == "" && len(d.Secrets.ProviderKeys) == 0 {
		if spec.DetailedCredentialErrorContext {
			return fmt.Errorf("%s %s/%s requires spec.defaults.secrets.claudeApiKey or providerKeys for provider=%s authMode=%s", spec.TriggerKind, spec.Namespace, spec.TriggerName, provider, authMode)
		}
		return fmt.Errorf("%s %s/%s requires spec.defaults.secrets.claudeApiKey or providerKeys", spec.TriggerKind, spec.Namespace, spec.TriggerName)
	}
	return nil
}

// agentRunResourceType is the collaboration-store resource type for AgentRuns,
// matching the dashboard's ownership and permission checks.
const agentRunResourceType = "agent_run"

// recordTriggerRunOwner best-effort records the triggering user as the run's
// owner in the collaboration store so the run is manageable (stop/delete) from
// the dashboard. A failure never blocks the run: it only degrades dashboard
// permissions, which admins can still exercise.
func recordTriggerRunOwner(ctx context.Context, stateStore store.StateStore, run *platformv1alpha1.AgentRun, spec TriggerRunSpec) {
	ownerID := strings.TrimSpace(spec.OwnerID)
	if stateStore == nil || ownerID == "" {
		return
	}
	prefix := spec.SeedLogPrefix
	if prefix == "" {
		prefix = strings.ToLower(spec.TriggerKind)
	}
	if err := stateStore.SetResourceOwner(ctx, agentRunResourceType, run.Name, run.Namespace, ownerID); err != nil {
		log.Printf("%s: failed to record owner for %s: %v", prefix, run.Name, err)
	}
}

func seedTriggerRunSession(ctx context.Context, stateStore store.StateStore, run *platformv1alpha1.AgentRun, spec TriggerRunSpec, created bool) error {
	if stateStore == nil {
		return nil
	}
	prefix := spec.SeedLogPrefix
	if prefix == "" {
		prefix = strings.ToLower(spec.TriggerKind)
	}
	sess, err := stateStore.CreateSession(ctx, run.Name, run.Namespace, "pending", "setup")
	if err != nil {
		return fmt.Errorf("%s: failed to create session for %s: %w", prefix, run.Name, err)
	}
	if !created {
		// The run already existed, so seeding is recovery for a crash between
		// run creation and the first seed. Only the exact trigger message proves
		// delivery; unrelated messages must not release the authorization hold.
		messages, err := stateStore.GetMessages(ctx, sess.ID)
		if err != nil {
			return fmt.Errorf("%s: failed to check existing seed for %s: %w", prefix, run.Name, err)
		}
		for _, message := range messages {
			if message.Role == "user" && message.Content == spec.SeedMessage {
				return nil
			}
		}
	}
	if _, err := stateStore.AppendMessage(ctx, sess.ID, "user", spec.SeedMessage, nil); err != nil {
		return fmt.Errorf("%s: failed to seed message for %s: %w", prefix, run.Name, err)
	}
	return nil
}

func copyStringMap(in map[string]string) map[string]string {
	if len(in) == 0 {
		return nil
	}
	out := make(map[string]string, len(in))
	for k, v := range in {
		out[k] = v
	}
	return out
}

