func validateSecurityScanTaskSkillRefs(
	ctx context.Context,
	c client.Reader,
	namespace string,
	defaults []platformv1alpha1.NamedRef,
	workflow []triggersv1alpha1.SecurityScanTask,
) error {
	seen := make(map[string]struct{}, len(defaults))
	validate := func(ref platformv1alpha1.NamedRef, source string) error {
		name := strings.TrimSpace(ref.Name)
		if _, ok := seen[name]; ok {
			return nil
		}
		seen[name] = struct{}{}
		skill := &platformv1alpha1.Skill{}
		if err := c.Get(ctx, client.ObjectKey{Namespace: namespace, Name: name}, skill); err != nil {
			if apierrors.IsNotFound(err) {
				return &securityScanRefError{
					reason:  securityScanReasonUnresolvedReference,
					message: fmt.Sprintf("Skill %q referenced by %s not found in namespace %q", name, source, namespace),
				}
			}
			return fmt.Errorf("resolving Skill %s/%s referenced by %s: %w", namespace, name, source, err)
		}
		if skill.Status.ObservedGeneration != skill.Generation ||
			!strings.EqualFold(strings.TrimSpace(skill.Status.Phase), "Ready") ||
			skill.Status.Resolved == nil ||
			strings.TrimSpace(skill.Status.Resolved.Instructions) == "" {
			return &securityScanRefError{
				reason:  securityScanReasonUnresolvedReference,
				message: fmt.Sprintf("Skill %q referenced by %s is not ready in namespace %q", name, source, namespace),
			}
		}
		return nil
	}
	for _, ref := range defaults {
		if err := validate(ref, "spec.defaults.skillRefs"); err != nil {
			return err
		}
	}
	for _, task := range workflow {
		for _, ref := range task.SkillRefs {
			if err := validate(ref, fmt.Sprintf("workflow task %q", task.Name)); err != nil {
				return err
			}
		}
	}
	return nil
}

// Ready=False reasons for reference problems.
const (
	securityScanReasonInvalidSpec         = "InvalidSpec"
	securityScanReasonUnresolvedReference = "UnresolvedReference"
	securityScanReasonCreateRunFailed     = "CreateRunFailed"
)

// securityScanRefError is a deterministic spec/reference failure that must
// surface as a specific Ready=False reason instead of the generic
// CreateRunFailed.
type securityScanRefError struct {
	reason  string
	message string
}

func (e *securityScanRefError) Error() string { return e.message }

// securityScanRunFailureReason maps a createScanRun error to the Ready
// condition reason reported on the scan.
func securityScanRunFailureReason(err error) string {
	var refErr *securityScanRefError
	if errors.As(err, &refErr) {
		return refErr.reason
	}
	return securityScanReasonCreateRunFailed
}

// securityScanInvalidSpecMessage returns a non-empty message when the scan
// spec is statically invalid: workflowRef and an inline workflow are mutually
// exclusive, event triggers and checks require a repository reference, and
// notification rules need a unique name plus at least one channel.
func securityScanInvalidSpecMessage(spec triggersv1alpha1.SecurityScanSpec) string {
	if (strings.TrimSpace(spec.RepoURL) == "") == (strings.TrimSpace(spec.TargetURL) == "") {
		return "exactly one of spec.repoURL or spec.targetURL must be set"
	}
	if strings.TrimSpace(spec.TargetURL) != "" {
		if err := triggersv1alpha1.ValidateSecurityScanTargetURL(spec.TargetURL); err != nil {
			return "spec.targetURL " + err.Error()
		}
		if t := spec.Triggers; t != nil && (t.OnPullRequest || t.OnPush || t.RepositoryRef != nil) {
			return "spec.triggers is only valid for repository scans"
		}
		if c := spec.Checks; c != nil && c.Enabled {
			return "spec.checks is only valid for repository scans"
		}
	}
	if spec.WorkflowRef != nil && len(spec.Workflow) > 0 {
		return "spec.workflowRef and spec.workflow are mutually exclusive: reference a SecurityWorkflow or define the workflow inline, not both"
	}
	if len(spec.Workflow) > 0 {
		if errs := triggersv1alpha1.ValidateSecurityWorkflowTasks(spec.Workflow); len(errs) != 0 {
			return "spec.workflow is invalid: " + errs[0].Error()
		}
	}
	if errs := triggersv1alpha1.ValidateSecurityScanBudgets("spec.budgets", spec.Budgets); len(errs) != 0 {
		return errs[0].Error()
	}
	if t := spec.Triggers; t != nil && (t.OnPullRequest || t.OnPush) {
		if t.RepositoryRef == nil || strings.TrimSpace(t.RepositoryRef.Name) == "" {
			return "spec.triggers.repositoryRef is required when onPullRequest or onPush is set: it names the GitHubRepository whose webhook deliveries trigger this scan"
		}
	}
	if c := spec.Checks; c != nil && c.Enabled {
		if spec.Triggers == nil || spec.Triggers.RepositoryRef == nil || strings.TrimSpace(spec.Triggers.RepositoryRef.Name) == "" {
			return "spec.checks.enabled requires spec.triggers.repositoryRef: the referenced GitHubRepository supplies the credentials that publish checks"
		}
	}
	seenRules := map[string]bool{}
	for i, rule := range spec.Notifications {
		name := strings.TrimSpace(rule.Name)
		if name == "" {
			return fmt.Sprintf("spec.notifications[%d].name is required", i)
		}
		if seenRules[name] {
			return fmt.Sprintf("spec.notifications[%d].name %q is duplicated: rule names key the persisted notification dedupe markers and must be unique", i, name)
		}
		seenRules[name] = true
		if rule.Slack == nil && rule.GitHubIssues == nil && rule.Linear == nil {
			return fmt.Sprintf("spec.notifications[%d] (%q) configures no channel: set slack, githubIssues, and/or linear", i, name)
		}
	}
	return ""
}

// resolvedSecurityScanSpec is a SecurityScan spec with every reusable
// resource reference resolved into inline content, plus the provenance
// snapshot of what was resolved.
type resolvedSecurityScanSpec struct {
	// spec has workflowRef replaced by the referenced tasks, the policy
	// pack's defaults and enforced floors applied, and
	// rankerRefs/postScriptRefs (including pack defaults) appended after the
	// inline entries.
	spec triggersv1alpha1.SecurityScanSpec
	// refs records generation and content hash per resolved resource, in
	// spec order (securityProgramRef, policyPackRef, workflowRef, rankerRefs,
	// postScriptRefs).
	refs []triggersv1alpha1.SecurityScanResolvedRef
	// program is the validated snapshot rendered into every run prompt.
	program *triggersv1alpha1.SecurityProgramSpec
	// workflowParams are the referenced SecurityWorkflow's declared
	// scan-time parameters; empty for inline workflows, whose {{params.*}}
	// references are free-form.
	workflowParams []triggersv1alpha1.SecurityWorkflowParameter
}

// resolveSecurityScanRefs resolves spec.securityProgramRef,
// spec.policyPackRef, spec.workflowRef, spec.rankerRefs, and
// spec.postScriptRefs against the scan's namespace at
// run-creation time. The resolved content is inlined into the returned spec
// so the run prompt is built from a snapshot: later edits to the referenced
// resources never change runs that were already created. The policy pack is
// applied BEFORE prompt construction (precedence: platform defaults < policy
// pack < scan configuration) and its enforced fields are checked here, so
// model output can never affect enforcement; a violating scan returns a
// *securityScanRefError with reason PolicyViolation and no run is created. A
// missing reference returns a *securityScanRefError with reason
// UnresolvedReference.
func resolveSecurityScanRefs(
	ctx context.Context, c client.Reader, scan *triggersv1alpha1.SecurityScan,
) (*resolvedSecurityScanSpec, error) {
	if msg := securityScanInvalidSpecMessage(scan.Spec); msg != "" {
		return nil, &securityScanRefError{reason: securityScanReasonInvalidSpec, message: msg}
	}

	resolved := &resolvedSecurityScanSpec{spec: *scan.Spec.DeepCopy()}
	resolved.spec.WorkflowRef = nil
	resolved.spec.SecurityProgramRef = nil
	resolved.spec.PolicyPackRef = nil
	resolved.spec.RankerRefs = nil
	resolved.spec.PostScriptRefs = nil

	if ref := scan.Spec.SecurityProgramRef; ref != nil {
		program := &triggersv1alpha1.SecurityProgram{}
		if err := getSecurityScanRef(ctx, c, scan.Namespace, ref.Name, "SecurityProgram", program); err != nil {
			return nil, err
		}
		if errs := triggersv1alpha1.ValidateSecurityProgramSpec(program.Spec); len(errs) != 0 {
			return nil, &securityScanRefError{
				reason:  securityScanReasonInvalidSpec,
				message: fmt.Sprintf("SecurityProgram %q is invalid: %s", program.Name, errs[0].Error()),
			}
		}
		digest := securitySpecHash(program.Spec)
		ready := meta.FindStatusCondition(program.Status.Conditions, triggersv1alpha1.ConditionSecurityLibraryReady)
		if program.Status.ObservedGeneration != program.Generation ||
			program.Status.ContentDigest != digest || ready == nil ||
			ready.Status != metav1.ConditionTrue || ready.ObservedGeneration != program.Generation {
			return nil, &securityScanRefError{
				reason:  securityScanReasonUnresolvedReference,
				message: fmt.Sprintf("SecurityProgram %q is not ready in namespace %q", program.Name, scan.Namespace),
			}
		}
		programSpec := program.Spec
		resolved.program = &programSpec
		resolved.refs = append(resolved.refs, resolvedSecurityRef("SecurityProgram", program.Name, program.Generation, program.Spec))
	}

	var pack *triggersv1alpha1.SecurityPolicyPack
	if ref := scan.Spec.PolicyPackRef; ref != nil {
		pack = &triggersv1alpha1.SecurityPolicyPack{}
		if err := getSecurityScanRef(ctx, c, scan.Namespace, ref.Name, "SecurityPolicyPack", pack); err != nil {
			return nil, err
		}
		// Enforcement fails closed: an invalid pack rejects the scan instead
		// of silently enforcing nothing.
		if errs := triggersv1alpha1.ValidateSecurityPolicyPackSpec(pack.Spec); len(errs) != 0 {
			return nil, &securityScanRefError{
				reason:  securityScanReasonPolicyViolation,
				message: fmt.Sprintf("SecurityPolicyPack %q is invalid: %s", pack.Name, errs[0].Error()),
			}
		}
		resolved.refs = append(resolved.refs, resolvedSecurityRef("SecurityPolicyPack", pack.Name, pack.Generation, pack.Spec))
	}

	workflowRef := scan.Spec.WorkflowRef
	if workflowRef == nil && len(scan.Spec.Workflow) == 0 {
		workflowRef = &triggersv1alpha1.SecurityResourceRef{Name: automaticSecurityScanWorkflowName(scan.Spec)}
	}
	if ref := workflowRef; ref != nil {
		workflow := &triggersv1alpha1.SecurityWorkflow{}
		if err := getSecurityScanRef(ctx, c, scan.Namespace, ref.Name, "SecurityWorkflow", workflow); err != nil {
			return nil, err
		}
		resolved.spec.Workflow = append([]triggersv1alpha1.SecurityScanTask(nil), workflow.Spec.Tasks...)
		if workflow.Spec.Parallelism > 0 {
			resolved.spec.Parallelism = workflow.Spec.Parallelism
		}
		resolved.workflowParams = append([]triggersv1alpha1.SecurityWorkflowParameter(nil), workflow.Spec.Parameters...)
		resolved.refs = append(resolved.refs, resolvedSecurityRef("SecurityWorkflow", workflow.Name, workflow.Generation, workflow.Spec))
	}

	rankerRefs := append([]triggersv1alpha1.SecurityResourceRef(nil), scan.Spec.RankerRefs...)
	postScriptRefs := append([]triggersv1alpha1.SecurityResourceRef(nil), scan.Spec.PostScriptRefs...)
	if pack != nil {
		// The pack is applied after workflow resolution so requiredCategories
		// checks the effective task list, and before ranker/post-script
		// resolution so pack defaults are resolved and snapshotted too.
		spec, violations := applySecurityPolicyPack(resolved.spec, pack)
		if len(violations) != 0 {
			return nil, &securityScanRefError{
				reason: securityScanReasonPolicyViolation,
				message: fmt.Sprintf("scan violates enforced SecurityPolicyPack %q: %s",
					pack.Name, strings.Join(violations, "; ")),
			}
		}
		rankerRefs = spec.RankerRefs
		postScriptRefs = spec.PostScriptRefs
		spec.RankerRefs = nil
		spec.PostScriptRefs = nil
		resolved.spec = spec
	}

	for _, ref := range rankerRefs {
		ranker := &triggersv1alpha1.SecurityRanker{}
		if err := getSecurityScanRef(ctx, c, scan.Namespace, ref.Name, "SecurityRanker", ranker); err != nil {
			return nil, err
		}
		resolved.spec.SeverityRankers = append(resolved.spec.SeverityRankers, triggersv1alpha1.SecurityScanRanker{
			Name:  ranker.Name,
			Rules: strings.Join(ranker.Spec.Rules, "\n"),
		})
		resolved.refs = append(resolved.refs, resolvedSecurityRef("SecurityRanker", ranker.Name, ranker.Generation, ranker.Spec))
	}

	if err := appendProgramSeverityRanker(ctx, c, scan.Namespace, resolved); err != nil {
		return nil, err
	}

	for _, ref := range postScriptRefs {
		script := &triggersv1alpha1.SecurityPostScript{}
		if err := getSecurityScanRef(ctx, c, scan.Namespace, ref.Name, "SecurityPostScript", script); err != nil {
			return nil, err
		}
		resolved.spec.PostScripts = append(resolved.spec.PostScripts, triggersv1alpha1.SecurityScanPostScript{
			Name:   script.Name,
			Prompt: script.Spec.Prompt,
			RunOn:  script.Spec.RunOn,
		})
		resolved.refs = append(resolved.refs, resolvedSecurityRef("SecurityPostScript", script.Name, script.Generation, script.Spec))
	}

	return resolved, nil
}

// securityProgramSeverityRankers maps a program's severity system to the
// shipped SecurityRanker that transcribes that platform's published severity
// table. Systems without a shipped transcription (custom, and the ones whose
// tables are not shipped yet) resolve to no ranker.
var securityProgramSeverityRankers = map[string]string{
	string(triggersv1alpha1.SeveritySystemImmunefiV23): "immunefi-v2-3",
	string(triggersv1alpha1.SeveritySystemCode4rena):   "code4rena",
	string(triggersv1alpha1.SeveritySystemSherlock):    "sherlock",
}

// appendProgramSeverityRanker appends the SecurityRanker transcribing the
// governing program's own severity table, so findings are rated in the system
// the program pays out on instead of a translated one. It runs after the
// explicit and pack-default rankers so an operator-chosen ranker of the same
// name wins and resolution stays idempotent. A ranker CR that is not
// installed in the scan's namespace is skipped silently: the program's
// severity system is a fact about the program, not a reference the scan
// author made.
func appendProgramSeverityRanker(
	ctx context.Context, c client.Reader, namespace string, resolved *resolvedSecurityScanSpec,
) error {
	if resolved.program == nil {
		return nil
	}
	name := securityProgramSeverityRankers[strings.TrimSpace(resolved.program.SeveritySystem)]
	if name == "" {
		return nil
	}
	for _, existing := range resolved.spec.SeverityRankers {
		if existing.Name == name {
			return nil
		}
	}
	ranker := &triggersv1alpha1.SecurityRanker{}
	if err := c.Get(ctx, client.ObjectKey{Namespace: namespace, Name: name}, ranker); err != nil {
		if apierrors.IsNotFound(err) {
			return nil
		}
		return fmt.Errorf("resolving SecurityRanker %s/%s for severity system %q: %w",
			namespace, name, resolved.program.SeveritySystem, err)
	}
	resolved.spec.SeverityRankers = append(resolved.spec.SeverityRankers, triggersv1alpha1.SecurityScanRanker{
		Name:  ranker.Name,
		Rules: strings.Join(ranker.Spec.Rules, "\n"),
	})
	resolved.refs = append(resolved.refs, resolvedSecurityRef("SecurityRanker", ranker.Name, ranker.Generation, ranker.Spec))
	return nil
}

//nolint:gocyclo // Routing intentionally keeps the complete precedence table together for auditability.
func automaticSecurityScanWorkflowName(spec triggersv1alpha1.SecurityScanSpec) string {
	if strings.TrimSpace(spec.TargetURL) != "" {
		return "web-recon-passive"
	}
	parts := []string{spec.RepoURL}
	parts = append(parts, spec.AdditionalRepos...)
	var focus string
	var languages []string
	if spec.Scope != nil {
		focus = spec.Scope.Focus
		parts = append(parts, focus)
		parts = append(parts, spec.Scope.IncludePaths...)
		parts = append(parts, spec.Scope.Languages...)
		languages = spec.Scope.Languages
	}

	evidence, tokens := securityScanRoutingEvidence(parts...)
	focusEvidence, focusTokens := securityScanRoutingEvidence(focus)
	has := func(values ...string) bool {
		for _, value := range values {
			if tokens[value] {
				return true
			}
		}
		return false
	}
	hasPhrase := func(values ...string) bool {
		for _, value := range values {
			if strings.Contains(" "+evidence+" ", " "+value+" ") {
				return true
			}
		}
		return false
	}

	cosmos := has("cosmos", "cosmwasm", "ibc", "cometbft", "tendermint") || hasPhrase("cosmos sdk")
	otherChain := has("evm", "ethereum", "solidity", "vyper", "solana", "substrate", "polkadot", "xcm",
		"aptos", "sui", "cairo", "starknet", "algorand", "bitcoin", "ton", "toncoin") ||
		hasPhrase("lightning network", "ton blockchain")
	if cosmos && !otherChain && focusTokens["abci"] && (focusTokens["halt"] || focusTokens["halting"] ||
		focusTokens["panic"] || focusTokens["nondeterminism"] || focusTokens["nondeterministic"] ||
		strings.Contains(" "+focusEvidence+" ", " non determinism ")) {
		return "cosmos-abci-halt-review"
	}

	nonEVMChain := cosmos ||
		has("solana", "substrate", "polkadot", "xcm", "aptos", "sui", "cairo", "starknet", "algorand", "bitcoin", "ton") ||
		hasPhrase("anchor toml", "anchor lang", "lightning network", "ton blockchain") ||
		has("lightningnetwork", "toncoin")
	for _, language := range languages {
		normalized, _ := securityScanRoutingEvidence(language)
		if normalized == "cairo" || normalized == "tact" {
			nonEVMChain = true
		}
	}

	evm := has("evm", "ethereum") || hasPhrase("go ethereum")
	evmContract := has("solidity", "vyper", "openzeppelin", "erc20", "erc721", "erc1155") ||
		hasPhrase("hardhat config", "foundry toml") ||
		(tokens["sol"] && (strings.Contains(evidence, " contracts ") || strings.HasSuffix(evidence, " contracts"))) ||
		(evm && (has("contract", "contracts", "hardhat", "foundry") || hasPhrase("smart contract", "smart contracts")))
	protocolComponent := has("consensus", "rollup", "sequencer", "validator") ||
		hasPhrase("peer to peer", "execution client", "consensus client", "cross chain", "multi chain") ||
		has("geth", "reth", "nethermind", "besu", "erigon")
	blockchainProtocol := nonEVMChain ||
		hasPhrase("cross chain", "multi chain") ||
		(evm && protocolComponent) ||
		(has("blockchain") && (has("client", "node", "protocol", "bridge") || protocolComponent)) ||
		(has("bridge", "rollup") && (evm || nonEVMChain || has("blockchain", "chain")))

	if blockchainProtocol || (evmContract && nonEVMChain) {
		return "blockchain-protocol-audit"
	}
	if evmContract {
		return "smart-contract-review"
	}
	return triggersv1alpha1.DefaultSecurityWorkflowName
}

func securityScanRoutingEvidence(parts ...string) (string, map[string]bool) {
	words := strings.FieldsFunc(strings.ToLower(strings.Join(parts, " ")), func(r rune) bool {
		return !unicode.IsLetter(r) && !unicode.IsDigit(r)
	})
	tokens := make(map[string]bool, len(words))
	for _, word := range words {
		tokens[word] = true
	}
	return strings.Join(words, " "), tokens
}

func getSecurityScanRef(ctx context.Context, c client.Reader, namespace, name, kind string, obj client.Object) error {
	if err := c.Get(ctx, client.ObjectKey{Namespace: namespace, Name: name}, obj); err != nil {
		if apierrors.IsNotFound(err) {
			return &securityScanRefError{
				reason:  securityScanReasonUnresolvedReference,
				message: fmt.Sprintf("%s %q not found in namespace %q", kind, name, namespace),
			}
		}
		return fmt.Errorf("resolving %s %s/%s: %w", kind, namespace, name, err)
	}
	return nil
}

func resolvedSecurityRef(kind, name string, generation int64, spec any) triggersv1alpha1.SecurityScanResolvedRef {
	return triggersv1alpha1.SecurityScanResolvedRef{
		Kind:       kind,
		Name:       name,
		Generation: generation,
		Hash:       securitySpecHash(spec),
	}
}

// securitySpecHash is a sha256 hex digest of the JSON encoding of a resolved
// resource spec; it pins run provenance to exact content.
func securitySpecHash(spec any) string {
	data, err := json.Marshal(spec)
	if err != nil {
		return ""
	}
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:])
}

// securityScanResolvedRefsJSON encodes the resolved-refs snapshot for the run
// annotation. Empty when the scan uses no references.
func securityScanResolvedRefsJSON(refs []triggersv1alpha1.SecurityScanResolvedRef) string {
	if len(refs) == 0 {
		return ""
	}
	data, err := json.Marshal(refs)
	if err != nil {
		return ""
	}
	return string(data)
}

package triggers

import (
	"context"
	"time"

	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
	"github.com/gratefulagents/gratefulagents/internal/store"
	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"sigs.k8s.io/controller-runtime/pkg/client"
	logf "sigs.k8s.io/controller-runtime/pkg/log"
)

const (
	// securityRetentionSweepInterval is how often a clean (no more work)
	// retention sweep re-runs per scan.
	securityRetentionSweepInterval = time.Hour

	// securityRetentionResumeDelay is the requeue used while a sweep reports
	// moreWork, so a large backlog drains one bounded batch at a time.
	securityRetentionResumeDelay = 30 * time.Second

	// securityRetentionBatchLimit bounds every purge statement of one sweep
	// batch, keeping each reconcile cheap.
	securityRetentionBatchLimit = 200
)

// securityRetentionPolicyFromPack converts the pack's retention block to the
// store policy.
func securityRetentionPolicyFromPack(r *triggersv1alpha1.SecurityPolicyPackRetention) store.SecurityRetentionPolicy {
	if r == nil {
		return store.SecurityRetentionPolicy{}
	}
	return store.SecurityRetentionPolicy{
		ScanDays:       r.ScanDays,
		FindingDays:    r.FindingDays,
		ReportDays:     r.ReportDays,
		EvidenceDays:   r.EvidenceDays,
		PoCDays:        r.PoCDays,
		AuditEventDays: r.AuditEventDays,
	}
}

// sweepSecurityRetention runs at most ONE bounded retention purge batch for
// the scan's policy pack retention configuration and records the outcome in
// status.retention plus a Kubernetes event when rows were purged. It runs
// only from the normal reconcile path — never from the deletion finalizer —
// so retention work can never delay or wedge scan deletion. Best-effort:
// store errors are recorded and retried, never failing the reconcile.
//
// The returned duration is a requeue hint: securityRetentionResumeDelay
// while the purge reports more work, otherwise the time until the next
// scheduled sweep. Zero means retention is not configured for this scan.
func (r *SecurityScanReconciler) sweepSecurityRetention(ctx context.Context, scan *triggersv1alpha1.SecurityScan) time.Duration {
	if r.Findings == nil {
		return 0
	}
	pack := r.scanPolicyPack(ctx, scan)
	if pack == nil || pack.Spec.Retention == nil {
		return 0
	}
	policy := securityRetentionPolicyFromPack(pack.Spec.Retention)
	if policy.IsZero() {
		return 0
	}

	now := r.now()
	if st := scan.Status.Retention; st != nil && !st.MoreWork && st.LastSweepTime != nil {
		if elapsed := now.Sub(st.LastSweepTime.Time); elapsed >= 0 && elapsed < securityRetentionSweepInterval {
			return securityRetentionSweepInterval - elapsed
		}
	}

	counts, moreWork, purgeErr := r.Findings.PurgeExpiredSecurityData(ctx, scan.Namespace, policy, securityRetentionBatchLimit)
	log := logf.FromContext(ctx)
	if purgeErr != nil {
		log.Error(purgeErr, "security retention sweep failed", "scan", scan.Name, "pack", pack.Name)
	}

	sweepTime := metav1.NewTime(now)
	if err := retrySecurityScanStatusUpdate(ctx, r.Client, client.ObjectKeyFromObject(scan), func(fresh *triggersv1alpha1.SecurityScan) {
		st := fresh.Status.Retention
		if st == nil {
			st = &triggersv1alpha1.SecurityScanRetentionStatus{}
		}
		st.LastSweepTime = &sweepTime
		st.MoreWork = moreWork
		st.LastError = ""
		if purgeErr != nil {
			st.LastError = purgeErr.Error()
		}
		st.ScansPurged += int64(counts.ScansDeleted)
		st.FindingsPurged += int64(counts.FindingsDeleted)
		st.ReportsPurged += int64(counts.ReportsDeleted)
		st.EvidenceRedacted += int64(counts.EvidenceRedacted)
		st.PoCRedacted += int64(counts.PoCsRedacted)
		st.AuditEventsPurged += int64(counts.AuditEventsDeleted)
		fresh.Status.Retention = st
	}); err != nil {
		log.Error(err, "failed to record retention sweep status", "scan", scan.Name)
	}

	if !counts.IsZero() && r.Recorder != nil {
		r.Recorder.Eventf(scan, nil, corev1.EventTypeNormal, "RetentionSweep", "RetentionSweep",
			"retention purge batch: %d scan rows, %d findings, %d reports, %d evidence redactions, %d PoC redactions, %d audit events (moreWork=%t)",
			counts.ScansDeleted, counts.FindingsDeleted, counts.ReportsDeleted,
			counts.EvidenceRedacted, counts.PoCsRedacted, counts.AuditEventsDeleted, moreWork)
	}

	switch {
	case purgeErr != nil:
		return time.Minute
	case moreWork:
		return securityRetentionResumeDelay
	default:
		return securityRetentionSweepInterval
	}
}

package triggers

import (
	"context"
	"fmt"
	"strconv"
	"strings"

	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
	appsv1 "k8s.io/api/apps/v1"
	corev1 "k8s.io/api/core/v1"
	rbacv1 "k8s.io/api/rbac/v1"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	"k8s.io/apimachinery/pkg/api/meta"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/apimachinery/pkg/types"
	ctrl "sigs.k8s.io/controller-runtime"
	"sigs.k8s.io/controller-runtime/pkg/client"
	"sigs.k8s.io/controller-runtime/pkg/controller"
	"sigs.k8s.io/controller-runtime/pkg/handler"
	logf "sigs.k8s.io/controller-runtime/pkg/log"
	"sigs.k8s.io/controller-runtime/pkg/reconcile"
)

const slackAgentKind = "SlackAgent"

// SlackAgentReconciler provisions, per SlackAgent, a long-lived connector
// Deployment (plus ServiceAccount + RBAC) that opens an outbound Socket Mode
// WebSocket and runs the agent loop in-process. The operator never holds the
// socket; it only reconciles the workload.
type SlackAgentReconciler struct {
	client.Client
	Scheme *runtime.Scheme
}

// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=slackagents,verbs=get;list;watch;create;update;patch;delete
// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=slackagents/status,verbs=get;update;patch
// +kubebuilder:rbac:groups=apps,resources=deployments,verbs=get;list;watch;create;update;patch;delete
// +kubebuilder:rbac:groups="",resources=serviceaccounts,verbs=get;list;watch;create
// +kubebuilder:rbac:groups=rbac.authorization.k8s.io,resources=roles;rolebindings,verbs=get;list;watch;create;update;patch
// +kubebuilder:rbac:groups="",resources=secrets,verbs=get;list;watch;create;update;delete

func (r *SlackAgentReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
	log := logf.FromContext(ctx)

	agent := &triggersv1alpha1.SlackAgent{}
	if err := r.Get(ctx, req.NamespacedName, agent); err != nil {
		return ctrl.Result{}, client.IgnoreNotFound(err)
	}

	if agent.UsesWorkspace() {
		return r.reconcileWorkspaceMember(ctx, req, agent)
	}

	tokensErr := r.validateTokensSecret(ctx, agent)
	if tokensErr != nil {
		if statusErr := r.updateStatus(ctx, req.NamespacedName, func(fresh *triggersv1alpha1.SlackAgent) {
			fresh.Status.LastError = tokensErr.Error()
			setSlackAgentCondition(fresh, triggersv1alpha1.ConditionSlackAgentTokenValid, metav1.ConditionFalse, "TokensMissing", tokensErr.Error())
			setSlackAgentCondition(fresh, triggersv1alpha1.ConditionSlackAgentReady, metav1.ConditionFalse, "TokensMissing", "Slack tokens are not available")
		}); statusErr != nil && !apierrors.IsNotFound(statusErr) {
			return ctrl.Result{}, fmt.Errorf("updating SlackAgent status: %w", statusErr)
		}
		// Missing tokens is a user-config problem; requeue is driven by Secret
		// changes, so don't return an error that would hot-loop.
		return ctrl.Result{}, nil
	}

	saName := slackResourceName(agent.Name)
	if err := r.ensureRBAC(ctx, agent, saName); err != nil {
		return ctrl.Result{}, fmt.Errorf("ensuring connector RBAC: %w", err)
	}

	if err := r.ensureInfraSecret(ctx, agent.Namespace); err != nil {
		return ctrl.Result{}, fmt.Errorf("syncing connector infra secret: %w", err)
	}

	deploymentName, err := r.ensureConnectorDeployment(ctx, agent, saName)
	if err != nil {
		return ctrl.Result{}, fmt.Errorf("ensuring connector Deployment: %w", err)
	}

	ready, replicas := r.deploymentAvailability(ctx, agent.Namespace, deploymentName)
	if statusErr := r.updateStatus(ctx, req.NamespacedName, func(fresh *triggersv1alpha1.SlackAgent) {
		fresh.Status.DeploymentName = deploymentName
		fresh.Status.LastError = ""
		setSlackAgentCondition(fresh, triggersv1alpha1.ConditionSlackAgentTokenValid, metav1.ConditionTrue, "TokensPresent", "Slack tokens are available")
		switch {
		case fresh.Spec.Suspend:
			setSlackAgentCondition(fresh, triggersv1alpha1.ConditionSlackAgentReady, metav1.ConditionFalse, "Suspended", "SlackAgent is suspended")
		case ready:
			setSlackAgentCondition(fresh, triggersv1alpha1.ConditionSlackAgentReady, metav1.ConditionTrue, "ConnectorReady", "Connector Deployment is available")
		default:
			setSlackAgentCondition(fresh, triggersv1alpha1.ConditionSlackAgentReady, metav1.ConditionFalse, "ConnectorPending", fmt.Sprintf("Connector has %d ready replicas", replicas))
		}
	}); statusErr != nil && !apierrors.IsNotFound(statusErr) {
		return ctrl.Result{}, fmt.Errorf("updating SlackAgent status: %w", statusErr)
	}

	log.V(1).Info("reconciled SlackAgent", "deployment", deploymentName, "ready", ready)
	return ctrl.Result{}, nil
}

// reconcileWorkspaceMember handles a SlackAgent bound to a shared
// SlackWorkspace: no dedicated Deployment is provisioned (the workspace's
// connector serves it), any stale dedicated Deployment from a mode switch is
// removed, and readiness mirrors the workspace's.
func (r *SlackAgentReconciler) reconcileWorkspaceMember(ctx context.Context, req ctrl.Request, agent *triggersv1alpha1.SlackAgent) (ctrl.Result, error) {
	// A mode switch (dedicated → workspace) leaves the old connector running;
	// delete it so two connectors never serve the same owner.
	staleName := slackResourceName(agent.Name)
	stale := &appsv1.Deployment{ObjectMeta: metav1.ObjectMeta{Name: staleName, Namespace: agent.Namespace}}
	if err := r.Delete(ctx, stale); err != nil && !apierrors.IsNotFound(err) {
		return ctrl.Result{}, fmt.Errorf("deleting stale dedicated connector Deployment: %w", err)
	}

	wsNamespace, wsName := agent.ResolvedWorkspaceRef()
	ws := &triggersv1alpha1.SlackWorkspace{}
	wsErr := r.Get(ctx, types.NamespacedName{Namespace: wsNamespace, Name: wsName}, ws)

	if statusErr := r.updateStatus(ctx, req.NamespacedName, func(fresh *triggersv1alpha1.SlackAgent) {
		fresh.Status.DeploymentName = ""
		setSlackAgentCondition(fresh, triggersv1alpha1.ConditionSlackAgentTokenValid, metav1.ConditionTrue, "DelegatedToWorkspace", "Tokens are managed by the referenced SlackWorkspace")
		switch {
		case wsErr != nil:
			fresh.Status.LastError = fmt.Sprintf("SlackWorkspace %s/%s not found", wsNamespace, wsName)
			setSlackAgentCondition(fresh, triggersv1alpha1.ConditionSlackAgentReady, metav1.ConditionFalse, "WorkspaceMissing", fresh.Status.LastError)
		case ws.Spec.Suspend:
			fresh.Status.LastError = ""
			setSlackAgentCondition(fresh, triggersv1alpha1.ConditionSlackAgentReady, metav1.ConditionFalse, "WorkspaceSuspended", "Referenced SlackWorkspace is suspended")
		case meta.IsStatusConditionTrue(ws.Status.Conditions, triggersv1alpha1.ConditionSlackWorkspaceReady):
			fresh.Status.LastError = ""
			fresh.Status.TeamID = ws.Status.TeamID
			fresh.Status.BotUserID = ws.Status.BotUserID
			setSlackAgentCondition(fresh, triggersv1alpha1.ConditionSlackAgentReady, metav1.ConditionTrue, "WorkspaceReady", "Served by the referenced SlackWorkspace connector")
		default:
			fresh.Status.LastError = ""
			setSlackAgentCondition(fresh, triggersv1alpha1.ConditionSlackAgentReady, metav1.ConditionFalse, "WorkspacePending", "Referenced SlackWorkspace connector is not ready")
		}
	}); statusErr != nil && !apierrors.IsNotFound(statusErr) {
		return ctrl.Result{}, fmt.Errorf("updating SlackAgent status: %w", statusErr)
	}
	return ctrl.Result{}, nil
}

// validateTokensSecret loads the Slack tokens Secret and validates that the
// minimum set (bot + app for Socket Mode) is present. Token values are consumed
// by the connector pod via secretKeyRef, so the controller only checks presence;
// the connector performs live auth.test.
func (r *SlackAgentReconciler) validateTokensSecret(ctx context.Context, agent *triggersv1alpha1.SlackAgent) error {
	secretName := strings.TrimSpace(agent.Spec.TokensSecret)
	if secretName == "" {
		return fmt.Errorf("spec.tokensSecret is required")
	}
	app, _ := ReadSecretValue(ctx, r.Client, agent.Namespace, secretName, triggersv1alpha1.SlackAppTokenKey)
	bot, _ := ReadSecretValue(ctx, r.Client, agent.Namespace, secretName, triggersv1alpha1.SlackBotTokenKey)
	if strings.TrimSpace(app) == "" {
		return fmt.Errorf("secret %q is missing key %q (app-level token for Socket Mode)", secretName, triggersv1alpha1.SlackAppTokenKey)
	}
	if strings.TrimSpace(bot) == "" {
		return fmt.Errorf("secret %q is missing key %q (bot token)", secretName, triggersv1alpha1.SlackBotTokenKey)
	}
	return nil
}

func (r *SlackAgentReconciler) ownerRef(agent *triggersv1alpha1.SlackAgent) metav1.OwnerReference {
	return metav1.OwnerReference{
		APIVersion:         triggersv1alpha1.GroupVersion.String(),
		Kind:               slackAgentKind,
		Name:               agent.Name,
		UID:                agent.UID,
		Controller:         new(true),
		BlockOwnerDeletion: new(true),
	}
}

// ensureRBAC provisions the connector's ServiceAccount + Role + RoleBinding so
// the connector pod can create and watch child AgentRuns and read the resources
// it needs, scoped to the agent's namespace.
func (r *SlackAgentReconciler) ensureRBAC(ctx context.Context, agent *triggersv1alpha1.SlackAgent, saName string) error {
	ownerRef := r.ownerRef(agent)

	sa := &corev1.ServiceAccount{ObjectMeta: metav1.ObjectMeta{Name: saName, Namespace: agent.Namespace, OwnerReferences: []metav1.OwnerReference{ownerRef}}}
	if err := r.Create(ctx, sa); err != nil && !apierrors.IsAlreadyExists(err) {
		return fmt.Errorf("creating ServiceAccount %s: %w", saName, err)
	}

	roleName := saName + "-role"
	role := &rbacv1.Role{
		ObjectMeta: metav1.ObjectMeta{Name: roleName, Namespace: agent.Namespace, OwnerReferences: []metav1.OwnerReference{ownerRef}},
		Rules:      slackConnectorRBACRules(),
	}
	if err := r.Create(ctx, role); err != nil {
		if !apierrors.IsAlreadyExists(err) {
			return fmt.Errorf("creating Role %s: %w", roleName, err)
		}
		existing := &rbacv1.Role{}
		if getErr := r.Get(ctx, client.ObjectKeyFromObject(role), existing); getErr != nil {
			return fmt.Errorf("getting existing Role %s: %w", roleName, getErr)
		}
		existing.Rules = role.Rules
		if updateErr := r.Update(ctx, existing); updateErr != nil {
			return fmt.Errorf("updating Role %s: %w", roleName, updateErr)
		}
	}

	rbName := saName + "-binding"
	rb := &rbacv1.RoleBinding{
		ObjectMeta: metav1.ObjectMeta{Name: rbName, Namespace: agent.Namespace, OwnerReferences: []metav1.OwnerReference{ownerRef}},
		RoleRef:    rbacv1.RoleRef{APIGroup: rbacv1.GroupName, Kind: "Role", Name: roleName},
		Subjects:   []rbacv1.Subject{{Kind: rbacv1.ServiceAccountKind, Name: saName, Namespace: agent.Namespace}},
	}
	if err := r.Create(ctx, rb); err != nil && !apierrors.IsAlreadyExists(err) {
		return fmt.Errorf("creating RoleBinding %s: %w", rbName, err)
	}
	return nil
}

// ensureInfraSecret syncs the operator's infra credentials into the agent
// namespace so the connector reads thread/draft state and its runs reach
// object storage.
func (r *SlackAgentReconciler) ensureInfraSecret(ctx context.Context, namespace string) error {
	return ensureSlackWorkerInfraSecret(ctx, r.Client, namespace)
}

func slackConnectorRBACRules() []rbacv1.PolicyRule {
	return []rbacv1.PolicyRule{
		{
			APIGroups: []string{"triggers.gratefulagents.dev"},
			Resources: []string{"slackagents"},
			Verbs:     []string{"get", "list", "watch"},
		},
		{
			APIGroups: []string{"platform.gratefulagents.dev"},
			Resources: []string{"agentruns"},
			Verbs:     []string{"create", "get", "list", "watch", "patch"},
		},
		{
			APIGroups: []string{"platform.gratefulagents.dev"},
			Resources: []string{"agentruns/status"},
			Verbs:     []string{"get", "patch", "update"},
		},
		{
			APIGroups: []string{""},
			Resources: []string{"secrets", "configmaps"},
			Verbs:     []string{"get", "list", "watch"},
		},
		{
			APIGroups: []string{""},
			Resources: []string{"events"},
			Verbs:     []string{"create"},
		},
	}
}

// ensureConnectorDeployment creates or updates the connector Deployment running
// `agent slack`. Replicas drop to zero while the SlackAgent is suspended.
func (r *SlackAgentReconciler) ensureConnectorDeployment(ctx context.Context, agent *triggersv1alpha1.SlackAgent, saName string) (string, error) {
	name := slackResourceName(agent.Name)
	replicas := int32(1)
	if agent.Spec.Suspend {
		replicas = 0
	}
	desired := buildSlackConnectorDeployment(
		name, agent.Namespace, "slack-connector",
		"triggers.gratefulagents.dev/slack-agent", agent.Name,
		r.ownerRef(agent), replicas, r.connectorPodSpec(agent, saName),
	)
	if err := applySlackConnectorDeployment(ctx, r.Client, desired); err != nil {
		return "", err
	}
	return name, nil
}

func (r *SlackAgentReconciler) connectorPodSpec(agent *triggersv1alpha1.SlackAgent, saName string) corev1.PodSpec {
	secretName := strings.TrimSpace(agent.Spec.TokensSecret)
	env := []corev1.EnvVar{
		{Name: "SLACK_AGENT_NAME", Value: agent.Name},
		{Name: "POD_NAMESPACE", ValueFrom: &corev1.EnvVarSource{FieldRef: &corev1.ObjectFieldSelector{FieldPath: "metadata.namespace"}}},
		{Name: "SLACK_HEALTH_ADDR", Value: ":8080"},
		slackSecretEnv("SLACK_BOT_TOKEN", secretName, triggersv1alpha1.SlackBotTokenKey),
		slackSecretEnv("SLACK_USER_TOKEN", secretName, triggersv1alpha1.SlackUserTokenKey),
		slackSecretEnv("SLACK_APP_TOKEN", secretName, triggersv1alpha1.SlackAppTokenKey),
		// Connector reaches Postgres for thread/draft state via the per-namespace
		// infra secret, mirroring worker pods.
		workerInfraSecretEnvRef("DATABASE_URL", "database-url"),
	}
	if uid := strings.TrimSpace(agent.Spec.SlackUserID); uid != "" {
		env = append(env, corev1.EnvVar{Name: "SLACK_USER_ID", Value: uid})
	}
	if teamID := strings.TrimSpace(agent.Annotations[projectSlackTeamIDAnnotation]); teamID != "" {
		env = append(env, corev1.EnvVar{Name: "SLACK_TEAM_ID", Value: teamID})
	}
	if commanders := strings.Join(agent.Spec.Commanders, ","); commanders != "" {
		env = append(env, corev1.EnvVar{Name: "SLACK_COMMANDERS", Value: commanders})
	}
	if m := agent.Spec.SessionIdleMinutes; m != nil && *m > 0 {
		env = append(env, corev1.EnvVar{Name: "SLACK_SESSION_IDLE_MINUTES", Value: strconv.FormatInt(int64(*m), 10)})
	}

	return slackConnectorPodSpec(saName, agent.Spec.Image, env)
}

func (r *SlackAgentReconciler) deploymentAvailability(ctx context.Context, namespace, name string) (bool, int32) {
	return slackDeploymentAvailability(ctx, r.Client, namespace, name)
}

func (r *SlackAgentReconciler) updateStatus(ctx context.Context, key types.NamespacedName, mutate func(*triggersv1alpha1.SlackAgent)) error {
	fresh := &triggersv1alpha1.SlackAgent{}
	if err := r.Get(ctx, key, fresh); err != nil {
		return err
	}
	mutate(fresh)
	return r.Status().Update(ctx, fresh)
}

func setSlackAgentCondition(agent *triggersv1alpha1.SlackAgent, condType string, status metav1.ConditionStatus, reason, message string) {
	meta.SetStatusCondition(&agent.Status.Conditions, metav1.Condition{
		Type:               condType,
		Status:             status,
		Reason:             reason,
		Message:            message,
		ObservedGeneration: agent.Generation,
	})
}

func (r *SlackAgentReconciler) SetupWithManager(mgr ctrl.Manager) error {
	return ctrl.NewControllerManagedBy(mgr).
		For(&triggersv1alpha1.SlackAgent{}).
		Owns(&appsv1.Deployment{}).
		Watches(&triggersv1alpha1.SlackWorkspace{}, handler.EnqueueRequestsFromMapFunc(r.mapWorkspaceToMembers)).
		Named("slackagent").
		WithOptions(controller.Options{MaxConcurrentReconciles: 1}).
		Complete(r)
}

// mapWorkspaceToMembers re-reconciles every member SlackAgent when its
// workspace changes so member readiness tracks the shared connector.
func (r *SlackAgentReconciler) mapWorkspaceToMembers(ctx context.Context, obj client.Object) []reconcile.Request {
	ws, ok := obj.(*triggersv1alpha1.SlackWorkspace)
	if !ok {
		return nil
	}
	agents := &triggersv1alpha1.SlackAgentList{}
	if err := r.List(ctx, agents); err != nil {
		return nil
	}
	var reqs []reconcile.Request
	for _, agent := range agents.Items {
		ns, name := agent.ResolvedWorkspaceRef()
		if ns == ws.Namespace && name == ws.Name {
			reqs = append(reqs, reconcile.Request{NamespacedName: types.NamespacedName{Namespace: agent.Namespace, Name: agent.Name}})
		}
	}
	return reqs
}

package triggers

import (
	"context"
	"fmt"
	"maps"
	"os"
	"strings"

	appsv1 "k8s.io/api/apps/v1"
	corev1 "k8s.io/api/core/v1"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/types"
	"k8s.io/apimachinery/pkg/util/intstr"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

// slackWorkerInfraSecretName mirrors the platform package's per-namespace infra
// Secret name. The connector consumes DATABASE_URL from it, like worker pods.
const slackWorkerInfraSecretName = "gratefulagents-worker-infra"

// slackResourcePrefix prefixes connector-owned resource names.
const slackResourcePrefix = "slack"

// slackResourceName converts a SlackAgent name into a valid DNS-1123 label
// prefixed with "slack-", used for the connector's Deployment, ServiceAccount,
// and RBAC objects so names are predictable and collision-free.
func slackResourceName(name string) string {
	combined := strings.ToLower(strings.TrimSpace(slackResourcePrefix + "-" + name))
	var b strings.Builder
	prevDash := false
	for _, r := range combined {
		switch {
		case r >= 'a' && r <= 'z':
			b.WriteRune(r)
			prevDash = false
		case r >= '0' && r <= '9':
			b.WriteRune(r)
			prevDash = false
		default:
			if !prevDash {
				b.WriteByte('-')
				prevDash = true
			}
		}
	}
	out := strings.Trim(b.String(), "-")
	if out == "" {
		out = slackResourcePrefix
	}
	if len(out) > 63 {
		out = strings.Trim(out[:63], "-")
	}
	if out == "" {
		out = slackResourcePrefix
	}
	return out
}

// slackSecretEnv builds an optional env var sourced from a key in the SlackAgent
// tokens Secret. Optional so a connector with only some tokens still starts (the
// connector validates required tokens itself).
func slackSecretEnv(envName, secretName, secretKey string) corev1.EnvVar {
	optional := true
	return corev1.EnvVar{
		Name: envName,
		ValueFrom: &corev1.EnvVarSource{
			SecretKeyRef: &corev1.SecretKeySelector{
				LocalObjectReference: corev1.LocalObjectReference{Name: secretName},
				Key:                  secretKey,
				Optional:             &optional,
			},
		},
	}
}

// workerInfraSecretEnvRef builds an optional env var sourced from the shared
// per-namespace worker infra Secret (e.g. DATABASE_URL).
func workerInfraSecretEnvRef(envName, secretKey string) corev1.EnvVar {
	optional := true
	return corev1.EnvVar{
		Name: envName,
		ValueFrom: &corev1.EnvVarSource{
			SecretKeyRef: &corev1.SecretKeySelector{
				LocalObjectReference: corev1.LocalObjectReference{Name: slackWorkerInfraSecretName},
				Key:                  secretKey,
				Optional:             &optional,
			},
		},
	}
}

func intstrFromInt(port int) intstr.IntOrString {
	return intstr.FromInt32(int32(port))
}

// ensureSlackWorkerInfraSecret syncs the operator's infra credentials
// (DATABASE_URL, S3 keys) into a namespace so connectors read thread/draft
// state and the AgentRuns they create can reach object storage. Mirrors the
// per-namespace worker infra Secret used by run pods.
func ensureSlackWorkerInfraSecret(ctx context.Context, c client.Client, namespace string) error {
	data := map[string][]byte{}
	for _, kv := range []struct{ key, env string }{
		{"database-url", "DATABASE_URL"},
		{"aws-access-key-id", "AWS_ACCESS_KEY_ID"},
		{"aws-secret-access-key", "AWS_SECRET_ACCESS_KEY"},
	} {
		if v := strings.TrimSpace(os.Getenv(kv.env)); v != "" {
			data[kv.key] = []byte(v)
		}
	}
	if len(data) == 0 {
		return nil
	}
	return upsertSecretData(ctx, c, namespace, slackWorkerInfraSecretName, nil, data)
}

// upsertSecretData creates the Secret or merges data into the existing one.
func upsertSecretData(ctx context.Context, c client.Client, namespace, name string, labels map[string]string, data map[string][]byte) error {
	secret := &corev1.Secret{
		ObjectMeta: metav1.ObjectMeta{Name: name, Namespace: namespace, Labels: labels},
		Data:       data,
	}
	if err := c.Create(ctx, secret); err != nil {
		if !apierrors.IsAlreadyExists(err) {
			return fmt.Errorf("creating Secret %s/%s: %w", namespace, name, err)
		}
		existing := &corev1.Secret{}
		if getErr := c.Get(ctx, client.ObjectKeyFromObject(secret), existing); getErr != nil {
			return fmt.Errorf("getting Secret %s/%s: %w", namespace, name, getErr)
		}
		if existing.Data == nil {
			existing.Data = map[string][]byte{}
		}
		maps.Copy(existing.Data, data)
		if updateErr := c.Update(ctx, existing); updateErr != nil {
			return fmt.Errorf("updating Secret %s/%s: %w", namespace, name, updateErr)
		}
	}
	return nil
}

// buildSlackConnectorDeployment shapes a connector Deployment with the shared
// selector/label/owner plumbing used by both connector kinds.
func buildSlackConnectorDeployment(
	name, namespace, component, selectorKey, selectorValue string,
	ownerRef metav1.OwnerReference, replicas int32, podSpec corev1.PodSpec,
) *appsv1.Deployment {
	labels := map[string]string{
		"app.kubernetes.io/name":      "gratefulagents",
		"app.kubernetes.io/component": component,
		selectorKey:                   selectorValue,
	}
	return &appsv1.Deployment{
		ObjectMeta: metav1.ObjectMeta{
			Name:            name,
			Namespace:       namespace,
			Labels:          labels,
			OwnerReferences: []metav1.OwnerReference{ownerRef},
		},
		Spec: appsv1.DeploymentSpec{
			Replicas: &replicas,
			Selector: &metav1.LabelSelector{MatchLabels: map[string]string{selectorKey: selectorValue}},
			Template: corev1.PodTemplateSpec{
				ObjectMeta: metav1.ObjectMeta{Labels: labels},
				Spec:       podSpec,
			},
		},
	}
}

// applySlackConnectorDeployment creates the Deployment or updates its labels,
// replicas, and pod template in place.
func applySlackConnectorDeployment(ctx context.Context, c client.Client, desired *appsv1.Deployment) error {
	existing := &appsv1.Deployment{}
	if err := c.Get(ctx, client.ObjectKeyFromObject(desired), existing); err != nil {
		if !apierrors.IsNotFound(err) {
			return fmt.Errorf("getting connector Deployment: %w", err)
		}
		if createErr := c.Create(ctx, desired); createErr != nil && !apierrors.IsAlreadyExists(createErr) {
			return fmt.Errorf("creating connector Deployment: %w", createErr)
		}
		return nil
	}
	existing.Labels = desired.Labels
	existing.Spec.Replicas = desired.Spec.Replicas
	existing.Spec.Template = desired.Spec.Template
	if err := c.Update(ctx, existing); err != nil {
		return fmt.Errorf("updating connector Deployment: %w", err)
	}
	return nil
}

// slackConnectorPodSpec assembles the shared connector pod shape: toolkit init
// container, `agent slack` entrypoint, health/readiness probes.
func slackConnectorPodSpec(saName, image string, env []corev1.EnvVar) corev1.PodSpec {
	probe := &corev1.Probe{
		ProbeHandler: corev1.ProbeHandler{
			HTTPGet: &corev1.HTTPGetAction{Path: "/healthz", Port: intstrFromInt(8080)},
		},
		InitialDelaySeconds: 5,
		PeriodSeconds:       15,
	}
	readiness := &corev1.Probe{
		ProbeHandler: corev1.ProbeHandler{
			HTTPGet: &corev1.HTTPGetAction{Path: "/readyz", Port: intstrFromInt(8080)},
		},
		InitialDelaySeconds: 5,
		PeriodSeconds:       10,
	}
	return corev1.PodSpec{
		ServiceAccountName: saName,
		InitContainers: []corev1.Container{{
			Name:            "inject-toolkit",
			Image:           firstNonEmptyString(os.Getenv("INJECTOR_IMAGE"), "gratefulagents-injector:latest"),
			ImagePullPolicy: corev1.PullIfNotPresent,
			VolumeMounts:    []corev1.VolumeMount{{Name: "gratefulagents-toolkit", MountPath: "/shared"}},
		}},
		Containers: []corev1.Container{{
			Name:            "connector",
			Image:           firstNonEmptyString(image, os.Getenv("WORKER_IMAGE"), "worker:latest"),
			ImagePullPolicy: corev1.PullIfNotPresent,
			Command:         []string{"/opt/gratefulagents/bin/agent", "slack"},
			Env:             env,
			Ports:           []corev1.ContainerPort{{Name: "health", ContainerPort: 8080}},
			LivenessProbe:   probe,
			ReadinessProbe:  readiness,
			VolumeMounts: []corev1.VolumeMount{
				{Name: "gratefulagents-toolkit", MountPath: "/opt/gratefulagents", SubPath: "gratefulagents", ReadOnly: true},
			},
		}},
		Volumes: []corev1.Volume{
			{Name: "gratefulagents-toolkit", VolumeSource: corev1.VolumeSource{EmptyDir: &corev1.EmptyDirVolumeSource{}}},
		},
	}
}

// slackDeploymentAvailability reports whether a connector Deployment has its
// desired replicas ready (false while suspended at zero replicas).
func slackDeploymentAvailability(ctx context.Context, c client.Client, namespace, name string) (bool, int32) {
	dep := &appsv1.Deployment{}
	if err := c.Get(ctx, types.NamespacedName{Namespace: namespace, Name: name}, dep); err != nil {
		return false, 0
	}
	desired := int32(1)
	if dep.Spec.Replicas != nil {
		desired = *dep.Spec.Replicas
	}
	if desired == 0 {
		return false, 0
	}
	return dep.Status.ReadyReplicas >= desired, dep.Status.ReadyReplicas
}

// slackWorkspaceResourceName names resources owned by a SlackWorkspace's
// connector, keeping them distinct from per-agent connector resources.
func slackWorkspaceResourceName(name string) string {
	return slackResourceName("ws-" + name)
}

// SlackWorkspaceBotSecretName is the per-member-namespace Secret carrying the
// shared workspace app's bot token (key: bot-token). The workspace controller
// syncs it into every member namespace so child AgentRuns can authenticate
// agent-side Slack read tools; the connector references it on the runs it
// creates. Exported because cmd/agent needs the same name.
func SlackWorkspaceBotSecretName(workspaceName string) string {
	return slackResourceName("ws-" + workspaceName + "-bot")
}

package triggers

import (
	"context"
	"fmt"
	"strings"

	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
	appsv1 "k8s.io/api/apps/v1"
	corev1 "k8s.io/api/core/v1"
	rbacv1 "k8s.io/api/rbac/v1"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	"k8s.io/apimachinery/pkg/api/meta"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/apimachinery/pkg/types"
	ctrl "sigs.k8s.io/controller-runtime"
	"sigs.k8s.io/controller-runtime/pkg/client"
	"sigs.k8s.io/controller-runtime/pkg/controller"
	"sigs.k8s.io/controller-runtime/pkg/handler"
	logf "sigs.k8s.io/controller-runtime/pkg/log"
	"sigs.k8s.io/controller-runtime/pkg/reconcile"
)

const slackWorkspaceKind = "SlackWorkspace"

// SlackWorkspaceReconciler provisions, per SlackWorkspace, ONE shared connector
// Deployment serving every member SlackAgent (spec.workspaceRef). Socket Mode
// load-balances an app's events across its open sockets, so a shared app must
// be consumed by a single process; the connector routes events to members by
// the sending Slack user. For each member namespace the reconciler grants the
// connector the standard per-namespace connector RBAC and syncs the shared bot
// token so member child runs can use Slack read tools.
type SlackWorkspaceReconciler struct {
	client.Client
	Scheme *runtime.Scheme
}

// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=slackworkspaces,verbs=get;list;watch;create;update;patch;delete
// +kubebuilder:rbac:groups=triggers.gratefulagents.dev,resources=slackworkspaces/status,verbs=get;update;patch
// +kubebuilder:rbac:groups=rbac.authorization.k8s.io,resources=clusterroles;clusterrolebindings,verbs=get;list;watch;create;update;patch

func (r *SlackWorkspaceReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
	log := logf.FromContext(ctx)

	ws := &triggersv1alpha1.SlackWorkspace{}
	if err := r.Get(ctx, req.NamespacedName, ws); err != nil {
		return ctrl.Result{}, client.IgnoreNotFound(err)
	}

	if tokensErr := r.validateTokensSecret(ctx, ws); tokensErr != nil {
		if statusErr := r.updateStatus(ctx, req.NamespacedName, func(fresh *triggersv1alpha1.SlackWorkspace) {
			fresh.Status.LastError = tokensErr.Error()
			setSlackWorkspaceCondition(fresh, triggersv1alpha1.ConditionSlackWorkspaceTokenValid, metav1.ConditionFalse, "TokensMissing", tokensErr.Error())
			setSlackWorkspaceCondition(fresh, triggersv1alpha1.ConditionSlackWorkspaceReady, metav1.ConditionFalse, "TokensMissing", "Slack tokens are not available")
		}); statusErr != nil && !apierrors.IsNotFound(statusErr) {
			return ctrl.Result{}, fmt.Errorf("updating SlackWorkspace status: %w", statusErr)
		}
		return ctrl.Result{}, nil
	}

	saName := slackWorkspaceResourceName(ws.Name)
	if err := r.ensureRBAC(ctx, ws, saName); err != nil {
		return ctrl.Result{}, fmt.Errorf("ensuring workspace connector RBAC: %w", err)
	}
	if err := r.ensureWorkspaceInfraSecret(ctx, ws.Namespace); err != nil {
		return ctrl.Result{}, fmt.Errorf("syncing connector infra secret: %w", err)
	}

	members, err := r.listMembers(ctx, ws)
	if err != nil {
		return ctrl.Result{}, fmt.Errorf("listing workspace members: %w", err)
	}
	if err := r.ensureMemberNamespaces(ctx, ws, saName, members); err != nil {
		return ctrl.Result{}, fmt.Errorf("provisioning member namespaces: %w", err)
	}

	deploymentName, err := r.ensureConnectorDeployment(ctx, ws, saName)
	if err != nil {
		return ctrl.Result{}, fmt.Errorf("ensuring workspace connector Deployment: %w", err)
	}

	ready, replicas := r.deploymentAvailability(ctx, ws.Namespace, deploymentName)
	if statusErr := r.updateStatus(ctx, req.NamespacedName, func(fresh *triggersv1alpha1.SlackWorkspace) {
		fresh.Status.DeploymentName = deploymentName
		fresh.Status.MemberCount = int32(len(members)) //nolint:gosec // member count is tiny
		fresh.Status.LastError = ""
		setSlackWorkspaceCondition(fresh, triggersv1alpha1.ConditionSlackWorkspaceTokenValid, metav1.ConditionTrue, "TokensPresent", "Slack tokens are available")
		switch {
		case fresh.Spec.Suspend:
			setSlackWorkspaceCondition(fresh, triggersv1alpha1.ConditionSlackWorkspaceReady, metav1.ConditionFalse, "Suspended", "SlackWorkspace is suspended")
		case ready:
			setSlackWorkspaceCondition(fresh, triggersv1alpha1.ConditionSlackWorkspaceReady, metav1.ConditionTrue, "ConnectorReady", "Connector Deployment is available")
		default:
			setSlackWorkspaceCondition(fresh, triggersv1alpha1.ConditionSlackWorkspaceReady, metav1.ConditionFalse, "ConnectorPending", fmt.Sprintf("Connector has %d ready replicas", replicas))
		}
	}); statusErr != nil && !apierrors.IsNotFound(statusErr) {
		return ctrl.Result{}, fmt.Errorf("updating SlackWorkspace status: %w", statusErr)
	}

	log.V(1).Info("reconciled SlackWorkspace", "deployment", deploymentName, "members", len(members), "ready", ready)
	return ctrl.Result{}, nil
}

// validateTokensSecret presence-checks the shared app + bot tokens; the
// connector performs live auth.test.
func (r *SlackWorkspaceReconciler) validateTokensSecret(ctx context.Context, ws *triggersv1alpha1.SlackWorkspace) error {
	secretName := strings.TrimSpace(ws.Spec.TokensSecret)
	if secretName == "" {
		return fmt.Errorf("spec.tokensSecret is required")
	}
	app, _ := ReadSecretValue(ctx, r.Client, ws.Namespace, secretName, triggersv1alpha1.SlackAppTokenKey)
	bot, _ := ReadSecretValue(ctx, r.Client, ws.Namespace, secretName, triggersv1alpha1.SlackBotTokenKey)
	if strings.TrimSpace(app) == "" {
		return fmt.Errorf("secret %q is missing key %q (app-level token for Socket Mode)", secretName, triggersv1alpha1.SlackAppTokenKey)
	}
	if strings.TrimSpace(bot) == "" {
		return fmt.Errorf("secret %q is missing key %q (bot token)", secretName, triggersv1alpha1.SlackBotTokenKey)
	}
	return nil
}

func (r *SlackWorkspaceReconciler) ownerRef(ws *triggersv1alpha1.SlackWorkspace) metav1.OwnerReference {
	return metav1.OwnerReference{
		APIVersion:         triggersv1alpha1.GroupVersion.String(),
		Kind:               slackWorkspaceKind,
		Name:               ws.Name,
		UID:                ws.UID,
		Controller:         new(true),
		BlockOwnerDeletion: new(true),
	}
}

// ensureRBAC provisions the connector's ServiceAccount + namespace Role/Binding
// (workspace namespace) and a ClusterRole/ClusterRoleBinding so the connector
// can discover member SlackAgents across namespaces. Member-namespace write
// access is granted per namespace by ensureMemberNamespaces.
func (r *SlackWorkspaceReconciler) ensureRBAC(ctx context.Context, ws *triggersv1alpha1.SlackWorkspace, saName string) error {
	ownerRef := r.ownerRef(ws)

	sa := &corev1.ServiceAccount{ObjectMeta: metav1.ObjectMeta{Name: saName, Namespace: ws.Namespace, OwnerReferences: []metav1.OwnerReference{ownerRef}}}
	if err := r.Create(ctx, sa); err != nil && !apierrors.IsAlreadyExists(err) {
		return fmt.Errorf("creating ServiceAccount %s: %w", saName, err)
	}

	if err := r.upsertRole(ctx, ws.Namespace, saName+"-role", &ownerRef, slackConnectorRBACRules()); err != nil {
		return err
	}
	if err := r.upsertRoleBinding(ctx, ws.Namespace, saName+"-binding", &ownerRef, saName, ws.Namespace, saName+"-role"); err != nil {
		return err
	}

	// Cluster-scoped read of SlackAgents: membership discovery must see every
	// namespace. Cluster-scoped resources cannot own-ref a namespaced CR, so
	// name them uniquely per workspace.
	crName := fmt.Sprintf("gratefulagents-slack-ws-%s-%s", ws.Namespace, ws.Name)
	cr := &rbacv1.ClusterRole{
		ObjectMeta: metav1.ObjectMeta{Name: crName},
		Rules: []rbacv1.PolicyRule{{
			APIGroups: []string{"triggers.gratefulagents.dev"},
			Resources: []string{"slackagents", "slackworkspaces"},
			Verbs:     []string{"get", "list", "watch"},
		}},
	}
	if err := r.Create(ctx, cr); err != nil {
		if !apierrors.IsAlreadyExists(err) {
			return fmt.Errorf("creating ClusterRole %s: %w", crName, err)
		}
		existing := &rbacv1.ClusterRole{}
		if getErr := r.Get(ctx, client.ObjectKeyFromObject(cr), existing); getErr != nil {
			return fmt.Errorf("getting ClusterRole %s: %w", crName, getErr)
		}
		existing.Rules = cr.Rules
		if updateErr := r.Update(ctx, existing); updateErr != nil {
			return fmt.Errorf("updating ClusterRole %s: %w", crName, updateErr)
		}
	}
	crb := &rbacv1.ClusterRoleBinding{
		ObjectMeta: metav1.ObjectMeta{Name: crName},
		RoleRef:    rbacv1.RoleRef{APIGroup: rbacv1.GroupName, Kind: "ClusterRole", Name: crName},
		Subjects:   []rbacv1.Subject{{Kind: rbacv1.ServiceAccountKind, Name: saName, Namespace: ws.Namespace}},
	}
	if err := r.Create(ctx, crb); err != nil && !apierrors.IsAlreadyExists(err) {
		return fmt.Errorf("creating ClusterRoleBinding %s: %w", crName, err)
	}
	return nil
}

func (r *SlackWorkspaceReconciler) upsertRole(ctx context.Context, namespace, name string, ownerRef *metav1.OwnerReference, rules []rbacv1.PolicyRule) error {
	role := &rbacv1.Role{ObjectMeta: metav1.ObjectMeta{Name: name, Namespace: namespace}, Rules: rules}
	if ownerRef != nil {
		role.OwnerReferences = []metav1.OwnerReference{*ownerRef}
	}
	if err := r.Create(ctx, role); err != nil {
		if !apierrors.IsAlreadyExists(err) {
			return fmt.Errorf("creating Role %s/%s: %w", namespace, name, err)
		}
		existing := &rbacv1.Role{}
		if getErr := r.Get(ctx, client.ObjectKeyFromObject(role), existing); getErr != nil {
			return fmt.Errorf("getting existing Role %s/%s: %w", namespace, name, getErr)
		}
		existing.Rules = rules
		if updateErr := r.Update(ctx, existing); updateErr != nil {
			return fmt.Errorf("updating Role %s/%s: %w", namespace, name, updateErr)
		}
	}
	return nil
}

func (r *SlackWorkspaceReconciler) upsertRoleBinding(ctx context.Context, namespace, name string, ownerRef *metav1.OwnerReference, saName, saNamespace, roleName string) error {
	rb := &rbacv1.RoleBinding{
		ObjectMeta: metav1.ObjectMeta{Name: name, Namespace: namespace},
		RoleRef:    rbacv1.RoleRef{APIGroup: rbacv1.GroupName, Kind: "Role", Name: roleName},
		Subjects:   []rbacv1.Subject{{Kind: rbacv1.ServiceAccountKind, Name: saName, Namespace: saNamespace}},
	}
	if ownerRef != nil {
		rb.OwnerReferences = []metav1.OwnerReference{*ownerRef}
	}
	if err := r.Create(ctx, rb); err != nil && !apierrors.IsAlreadyExists(err) {
		return fmt.Errorf("creating RoleBinding %s/%s: %w", namespace, name, err)
	}
	return nil
}

// listMembers returns the SlackAgents bound to this workspace.
func (r *SlackWorkspaceReconciler) listMembers(ctx context.Context, ws *triggersv1alpha1.SlackWorkspace) ([]triggersv1alpha1.SlackAgent, error) {
	agents := &triggersv1alpha1.SlackAgentList{}
	if err := r.List(ctx, agents); err != nil {
		return nil, err
	}
	var members []triggersv1alpha1.SlackAgent
	for _, agent := range agents.Items {
		ns, name := agent.ResolvedWorkspaceRef()
		if ns == ws.Namespace && name == ws.Name {
			members = append(members, agent)
		}
	}
	return members, nil
}

// ensureMemberNamespaces grants the workspace connector SA the standard
// connector permissions in each member namespace (create/watch runs, read
// secrets) and syncs the shared bot token + infra secret there so member child
// runs work exactly like dedicated-agent runs.
func (r *SlackWorkspaceReconciler) ensureMemberNamespaces(ctx context.Context, ws *triggersv1alpha1.SlackWorkspace, saName string, members []triggersv1alpha1.SlackAgent) error {
	botToken, _ := ReadSecretValue(ctx, r.Client, ws.Namespace, strings.TrimSpace(ws.Spec.TokensSecret), triggersv1alpha1.SlackBotTokenKey)

	done := map[string]bool{}
	for _, member := range members {
		ns := member.Namespace
		if done[ns] {
			continue
		}
		done[ns] = true

		roleName := slackWorkspaceResourceName(ws.Name) + "-member-role"
		if err := r.upsertRole(ctx, ns, roleName, nil, slackConnectorRBACRules()); err != nil {
			return err
		}
		if err := r.upsertRoleBinding(ctx, ns, slackWorkspaceResourceName(ws.Name)+"-member-binding", nil, saName, ws.Namespace, roleName); err != nil {
			return err
		}
		if err := r.ensureWorkspaceInfraSecret(ctx, ns); err != nil {
			return err
		}
		if strings.TrimSpace(botToken) != "" {
			if err := r.syncBotTokenSecret(ctx, ns, ws.Name, botToken); err != nil {
				return err
			}
		}
	}
	return nil
}

// syncBotTokenSecret mirrors the shared bot token (bot token only — never the
// app-level token) into a member namespace for agent-side Slack read tools.
func (r *SlackWorkspaceReconciler) syncBotTokenSecret(ctx context.Context, namespace, workspaceName, botToken string) error {
	return upsertSecretData(ctx, r.Client, namespace, SlackWorkspaceBotSecretName(workspaceName),
		nil, map[string][]byte{triggersv1alpha1.SlackBotTokenKey: []byte(botToken)})
}

// ensureWorkspaceInfraSecret mirrors the per-namespace worker infra Secret.
func (r *SlackWorkspaceReconciler) ensureWorkspaceInfraSecret(ctx context.Context, namespace string) error {
	return ensureSlackWorkerInfraSecret(ctx, r.Client, namespace)
}

// ensureConnectorDeployment creates or updates the shared connector Deployment
// running `agent slack` in workspace mode. Replicas stay at exactly 1: Socket
// Mode splits events across sockets, so scaling out would misroute messages.
func (r *SlackWorkspaceReconciler) ensureConnectorDeployment(ctx context.Context, ws *triggersv1alpha1.SlackWorkspace, saName string) (string, error) {
	name := slackWorkspaceResourceName(ws.Name)
	replicas := int32(1)
	if ws.Spec.Suspend {
		replicas = 0
	}
	desired := buildSlackConnectorDeployment(
		name, ws.Namespace, "slack-workspace-connector",
		"triggers.gratefulagents.dev/slack-workspace", ws.Name,
		r.ownerRef(ws), replicas, r.connectorPodSpec(ws, saName),
	)
	if err := applySlackConnectorDeployment(ctx, r.Client, desired); err != nil {
		return "", err
	}
	return name, nil
}

func (r *SlackWorkspaceReconciler) connectorPodSpec(ws *triggersv1alpha1.SlackWorkspace, saName string) corev1.PodSpec {
	secretName := strings.TrimSpace(ws.Spec.TokensSecret)
	env := []corev1.EnvVar{
		{Name: "SLACK_WORKSPACE_NAME", Value: ws.Name},
		{Name: "POD_NAMESPACE", ValueFrom: &corev1.EnvVarSource{FieldRef: &corev1.ObjectFieldSelector{FieldPath: "metadata.namespace"}}},
		{Name: "SLACK_HEALTH_ADDR", Value: ":8080"},
		slackSecretEnv("SLACK_BOT_TOKEN", secretName, triggersv1alpha1.SlackBotTokenKey),
		slackSecretEnv("SLACK_APP_TOKEN", secretName, triggersv1alpha1.SlackAppTokenKey),
		workerInfraSecretEnvRef("DATABASE_URL", "database-url"),
	}
	if teamID := strings.TrimSpace(ws.Spec.TeamID); teamID != "" {
		env = append(env, corev1.EnvVar{Name: "SLACK_TEAM_ID", Value: teamID})
	}
	return slackConnectorPodSpec(saName, ws.Spec.Image, env)
}

func (r *SlackWorkspaceReconciler) deploymentAvailability(ctx context.Context, namespace, name string) (bool, int32) {
	return slackDeploymentAvailability(ctx, r.Client, namespace, name)
}

func (r *SlackWorkspaceReconciler) updateStatus(ctx context.Context, key types.NamespacedName, mutate func(*triggersv1alpha1.SlackWorkspace)) error {
	fresh := &triggersv1alpha1.SlackWorkspace{}
	if err := r.Get(ctx, key, fresh); err != nil {
		return err
	}
	mutate(fresh)
	return r.Status().Update(ctx, fresh)
}

func setSlackWorkspaceCondition(ws *triggersv1alpha1.SlackWorkspace, condType string, status metav1.ConditionStatus, reason, message string) {
	meta.SetStatusCondition(&ws.Status.Conditions, metav1.Condition{
		Type:               condType,
		Status:             status,
		Reason:             reason,
		Message:            message,
		ObservedGeneration: ws.Generation,
	})
}

func (r *SlackWorkspaceReconciler) SetupWithManager(mgr ctrl.Manager) error {
	return ctrl.NewControllerManagedBy(mgr).
		For(&triggersv1alpha1.SlackWorkspace{}).
		Owns(&appsv1.Deployment{}).
		Watches(&triggersv1alpha1.SlackAgent{}, handler.EnqueueRequestsFromMapFunc(r.mapAgentToWorkspace)).
		Named("slackworkspace").
		WithOptions(controller.Options{MaxConcurrentReconciles: 1}).
		Complete(r)
}

// mapAgentToWorkspace re-reconciles the workspace a member (de)binds from so
// membership counts, RBAC, and secret syncs stay current.
func (r *SlackWorkspaceReconciler) mapAgentToWorkspace(_ context.Context, obj client.Object) []reconcile.Request {
	agent, ok := obj.(*triggersv1alpha1.SlackAgent)
	if !ok {
		return nil
	}
	ns, name := agent.ResolvedWorkspaceRef()
	if name == "" {
		return nil
	}
	return []reconcile.Request{{NamespacedName: types.NamespacedName{Namespace: ns, Name: name}}}
}

