import triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"

// IsUserAllowed checks whether a user is permitted to trigger an AgentRun.
// Deny list takes precedence over allow list. Empty auth means open access.
func IsUserAllowed(auth *triggersv1alpha1.TriggerAuth, userID string) bool {
	if auth == nil {
		return true
	}
	for _, denied := range auth.DenyUsers {
		if denied == userID {
			return false
		}
	}
	if len(auth.AllowedUsers) == 0 {
		return true
	}
	for _, allowed := range auth.AllowedUsers {
		if allowed == userID {
			return true
		}
	}
	return false
}

package triggers

import (
	"context"
	"fmt"
	"strings"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	corev1 "k8s.io/api/core/v1"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

const (
	gitHubRepositoryTriggerKind     = "GitHubRepository"
	cancelRequestedAnnotation       = "platform.gratefulagents.dev/cancel-requested"
	maxGitHubRepositoryProcessedIDs = 500
)

// ExistingTriggerIssueIDs returns the set of external IDs already created by
// AgentRuns with the given trigger kind and name. Used to avoid creating
// duplicate runs for the same issue.
func ExistingTriggerIssueIDs(ctx context.Context, c client.Client, namespace, triggerKind, triggerName string) (map[string]struct{}, error) {
	runs := &platformv1alpha1.AgentRunList{}
	if err := c.List(ctx, runs, client.InNamespace(namespace)); err != nil {
		return nil, fmt.Errorf("listing AgentRuns: %w", err)
	}
	ids := map[string]struct{}{}
	for i := range runs.Items {
		run := &runs.Items[i]
		if !TriggerRunMatches(run, triggerKind, triggerName) || run.Spec.Trigger.ExternalRef == nil {
			continue
		}
		if id := strings.TrimSpace(run.Spec.Trigger.ExternalRef.ID); id != "" {
			ids[id] = struct{}{}
		}
	}
	return ids, nil
}

func hasProcessedIssueID(ids []string, issueID string) bool {
	issueID = strings.TrimSpace(issueID)
	if issueID == "" {
		return false
	}
	for _, id := range ids {
		if strings.TrimSpace(id) == issueID {
			return true
		}
	}
	return false
}

func appendProcessedIssueIDs(existing []string, issueIDs ...string) []string {
	out := append([]string(nil), existing...)
	for _, issueID := range issueIDs {
		issueID = strings.TrimSpace(issueID)
		if issueID == "" || hasProcessedIssueID(out, issueID) {
			continue
		}
		out = append(out, issueID)
	}
	if len(out) > maxGitHubRepositoryProcessedIDs {
		out = out[len(out)-maxGitHubRepositoryProcessedIDs:]
	}
	return out
}

// ReadSecretValue reads a single key from a Kubernetes Secret.
func ReadSecretValue(ctx context.Context, c client.Client, namespace, secretName, key string) (string, error) {
	secret := &corev1.Secret{}
	if err := c.Get(ctx, client.ObjectKey{Namespace: namespace, Name: secretName}, secret); err != nil {
		return "", fmt.Errorf("getting secret %s: %w", secretName, err)
	}
	data, ok := secret.Data[key]
	if !ok {
		return "", fmt.Errorf("secret %s has no key %q", secretName, key)
	}
	return string(data), nil
}

// ReadSecretValueWithVersion reads a single key from a Kubernetes Secret and
// returns the secret's ResourceVersion alongside it.
func ReadSecretValueWithVersion(ctx context.Context, c client.Client, namespace, secretName, key string) (string, string, error) {
	secret := &corev1.Secret{}
	if err := c.Get(ctx, client.ObjectKey{Namespace: namespace, Name: secretName}, secret); err != nil {
		return "", "", fmt.Errorf("getting secret %s: %w", secretName, err)
	}
	data, ok := secret.Data[key]
	if !ok {
		return "", "", fmt.Errorf("secret %s has no key %q", secretName, key)
	}
	return string(data), secret.ResourceVersion, nil
}

package githubapp

import (
	"context"
	"fmt"
	"log"
	"strings"
	"time"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
	corev1 "k8s.io/api/core/v1"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	ctrl "sigs.k8s.io/controller-runtime"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

const appRefreshInterval = 10 * time.Minute

// Refresher periodically rotates per-run GitHub App installation token Secrets.
type Refresher struct {
	client client.Client
	minter InstallationTokenMinter
	scheme *runtime.Scheme
}

// NewRefresher creates a leader-only GitHub App token refresher.
func NewRefresher(c client.Client, minter InstallationTokenMinter, scheme *runtime.Scheme) *Refresher {
	if minter == nil {
		minter = NewKeyedMinter()
	}
	return &Refresher{client: c, minter: minter, scheme: scheme}
}

// NeedLeaderElection returns true so the manager only starts this on the leader.
func (r *Refresher) NeedLeaderElection() bool { return true }

// Start runs the refresh loop until the context is cancelled.
func (r *Refresher) Start(ctx context.Context) error {
	log.Println("[githubapp] token refresher started (leader-only)")
	r.refreshAll(ctx)
	ticker := time.NewTicker(appRefreshInterval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			log.Println("[githubapp] token refresher stopped")
			return nil
		case <-ticker.C:
			r.refreshAll(ctx)
		}
	}
}

func (r *Refresher) refreshAll(ctx context.Context) {
	repos := &triggersv1alpha1.GitHubRepositoryList{}
	if err := r.client.List(ctx, repos); err != nil {
		log.Printf("[githubapp] error listing GitHubRepository resources: %v", err)
		return
	}
	for i := range repos.Items {
		gh := &repos.Items[i]
		if gh.Spec.GitHubApp == nil {
			continue
		}
		if err := r.refreshRepositoryRuns(ctx, gh); err != nil {
			log.Printf("[githubapp] error refreshing tokens for GitHubRepository %s/%s: %v", gh.Namespace, gh.Name, err)
		}
	}
}

func (r *Refresher) refreshRepositoryRuns(ctx context.Context, gh *triggersv1alpha1.GitHubRepository) error {
	privateKeyPEM, err := readPrivateKeySecret(ctx, r.client, gh.Namespace, gh.Spec.GitHubApp.PrivateKeySecret)
	if err != nil {
		return err
	}
	runs := &platformv1alpha1.AgentRunList{}
	if err := r.client.List(ctx, runs, client.InNamespace(gh.Namespace)); err != nil {
		return fmt.Errorf("list AgentRuns: %w", err)
	}
	for i := range runs.Items {
		run := &runs.Items[i]
		if !isActiveGitHubAppRun(run, gh) {
			continue
		}
		if err := r.refreshRunSecret(ctx, gh, run, privateKeyPEM); err != nil {
			log.Printf("[githubapp] error refreshing run token %s/%s: %v", run.Namespace, run.Name, err)
		}
	}
	return nil
}

func (r *Refresher) refreshRunSecret(ctx context.Context, gh *triggersv1alpha1.GitHubRepository, run *platformv1alpha1.AgentRun, privateKeyPEM []byte) error {
	if run.Spec.Secrets == nil || strings.TrimSpace(run.Spec.Secrets.GitHubTokenSecret) == "" {
		return nil
	}
	// Preserve the reviewer downscope on refresh: a reviewer's rotated token
	// must never regain push permissions.
	var token string
	var err error
	if run.Labels[triggersv1alpha1.PRLoopRoleLabelKey] == triggersv1alpha1.PRLoopRoleReviewerValue {
		if scoped, ok := r.minter.(ScopedInstallationTokenMinter); ok {
			token, err = scoped.MintScopedInstallationToken(ctx, gh.Spec.GitHubApp.AppID, gh.Spec.GitHubApp.InstallationID, privateKeyPEM, ReviewerInstallationPermissions())
		} else {
			log.Printf("[githubapp] minter does not support scoped tokens — reviewer run %s/%s refreshed with full scope", run.Namespace, run.Name)
			token, err = r.minter.MintInstallationToken(ctx, gh.Spec.GitHubApp.AppID, gh.Spec.GitHubApp.InstallationID, privateKeyPEM)
		}
	} else {
		token, err = r.minter.MintInstallationToken(ctx, gh.Spec.GitHubApp.AppID, gh.Spec.GitHubApp.InstallationID, privateKeyPEM)
	}
	if err != nil {
		return err
	}
	secretName := strings.TrimSpace(run.Spec.Secrets.GitHubTokenSecret)
	secret := &corev1.Secret{}
	err = r.client.Get(ctx, client.ObjectKey{Namespace: run.Namespace, Name: secretName}, secret)
	if apierrors.IsNotFound(err) {
		secret = &corev1.Secret{ObjectMeta: metav1.ObjectMeta{Name: secretName, Namespace: run.Namespace}, Type: corev1.SecretTypeOpaque, Data: map[string][]byte{TokenSecretKey: []byte(token)}}
		if err := ctrl.SetControllerReference(run, secret, r.scheme); err != nil {
			return fmt.Errorf("set owner reference: %w", err)
		}
		return r.client.Create(ctx, secret)
	}
	if err != nil {
		return fmt.Errorf("get token Secret: %w", err)
	}
	if secret.Data == nil {
		secret.Data = map[string][]byte{}
	}
	secret.Data[TokenSecretKey] = []byte(token)
	secret.Type = corev1.SecretTypeOpaque
	if metav1.GetControllerOf(secret) == nil {
		if err := ctrl.SetControllerReference(run, secret, r.scheme); err != nil {
			return fmt.Errorf("set owner reference: %w", err)
		}
	}
	return r.client.Update(ctx, secret)
}

func isActiveGitHubAppRun(run *platformv1alpha1.AgentRun, gh *triggersv1alpha1.GitHubRepository) bool {
	if run == nil || gh == nil || run.Spec.Trigger.Kind != "GitHubRepository" {
		return false
	}
	triggerName := strings.TrimSpace(run.Annotations["triggers.gratefulagents.dev/runtime-trigger-name"])
	if triggerName == "" {
		triggerName = strings.TrimSpace(run.Spec.Trigger.Name)
	}
	if triggerName != gh.Name {
		return false
	}
	switch run.Status.Phase {
	case platformv1alpha1.AgentRunPhaseSucceeded, platformv1alpha1.AgentRunPhaseFailed, platformv1alpha1.AgentRunPhaseCancelled:
		return false
	default:
		return true
	}
}

func readPrivateKeySecret(ctx context.Context, c client.Client, namespace, name string) ([]byte, error) {
	name = strings.TrimSpace(name)
	if name == "" {
		return nil, fmt.Errorf("GitHub App private key secret name is required")
	}
	secret := &corev1.Secret{}
	if err := c.Get(ctx, client.ObjectKey{Namespace: namespace, Name: name}, secret); err != nil {
		return nil, fmt.Errorf("get GitHub App private key Secret %s/%s: %w", namespace, name, err)
	}
	data := secret.Data[PrivateKeySecretKey]
	if len(data) == 0 {
		return nil, fmt.Errorf("GitHub App private key Secret %s/%s missing %q", namespace, name, PrivateKeySecretKey)
	}
	return data, nil
}

package githubapp

import (
	"context"
	"crypto"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/base64"
	"encoding/json"
	"encoding/pem"
	"fmt"
	"net/http"
	"net/url"
	"strconv"
	"sync"
	"time"

	"github.com/google/go-github/v68/github"
)

const refreshSkew = 10 * time.Minute

const (
	// PrivateKeySecretKey is the Secret data key for GitHub App private keys.
	PrivateKeySecretKey = "private-key.pem"
	// TokenSecretKey is the Secret data key for installation tokens consumed by workers.
	TokenSecretKey = "token"
)

// InstallationTokenMinter mints GitHub App installation access tokens.
type InstallationTokenMinter interface {
	MintInstallationToken(ctx context.Context, appID, installationID int64, privateKeyPEM []byte) (string, error)
}

// ScopedInstallationTokenMinter is an optional capability for minting tokens
// downscoped to a specific permission set. Callers type-assert and fall back
// to full-scope minting when unimplemented.
type ScopedInstallationTokenMinter interface {
	MintScopedInstallationToken(ctx context.Context, appID, installationID int64, privateKeyPEM []byte, permissions *github.InstallationPermissions) (string, error)
}

// ReviewerInstallationPermissions returns the reduced permission set for PR
// reviewer runs: read code, write reviews — never push. This boundary holds
// even if the agent pod is fully compromised.
func ReviewerInstallationPermissions() *github.InstallationPermissions {
	return &github.InstallationPermissions{
		Contents:     github.Ptr("read"),
		Metadata:     github.Ptr("read"),
		Issues:       github.Ptr("read"),
		PullRequests: github.Ptr("write"),
	}
}

// PullRequestPollingInstallationPermissions returns the read-only permission
// set needed by the control-plane PR monitor. Polling credentials never need
// contents write or branch-push access.
func PullRequestPollingInstallationPermissions() *github.InstallationPermissions {
	return &github.InstallationPermissions{
		Metadata:     github.Ptr("read"),
		Issues:       github.Ptr("read"),
		PullRequests: github.Ptr("read"),
		Checks:       new("read"),
		Statuses:     new("read"),
	}
}

type tokenCacheKey struct {
	AppID          int64
	InstallationID int64
	// PermissionsKey fingerprints the requested permission set; empty means
	// the installation's full default permissions.
	PermissionsKey string
}

type cachedToken struct {
	Token     string
	ExpiresAt time.Time
}

// Minter mints and caches installation tokens for a single GitHub App private key.
type Minter struct {
	privateKey *rsa.PrivateKey
	httpClient *http.Client
	now        func() time.Time
	baseURL    *url.URL

	mu    sync.Mutex
	cache map[tokenCacheKey]cachedToken
}

// NewMinter creates a GitHub App installation token minter from a private key PEM.
func NewMinter(privateKeyPEM []byte, opts ...Option) (*Minter, error) {
	key, err := parsePrivateKey(privateKeyPEM)
	if err != nil {
		return nil, err
	}
	m := &Minter{
		privateKey: key,
		httpClient: &http.Client{Timeout: 20 * time.Second},
		now:        time.Now,
		cache:      make(map[tokenCacheKey]cachedToken),
	}
	for _, opt := range opts {
		opt(m)
	}
	return m, nil
}

// Option customizes a Minter.
type Option func(*Minter)

// WithHTTPClient sets the HTTP client used for GitHub API calls.
func WithHTTPClient(client *http.Client) Option {
	return func(m *Minter) {
		if client != nil {
			m.httpClient = client
		}
	}
}

// WithNow sets the clock used for JWT claims and token cache checks.
func WithNow(now func() time.Time) Option {
	return func(m *Minter) {
		if now != nil {
			m.now = now
		}
	}
}

// WithBaseURL sets an alternate GitHub API base URL, primarily for tests.
func WithBaseURL(raw string) Option {
	return func(m *Minter) {
		if raw == "" {
			return
		}
		u, err := url.Parse(raw)
		if err == nil {
			m.baseURL = u
		}
	}
}

// Mint mints or returns a cached installation access token.
func (m *Minter) Mint(ctx context.Context, appID, installationID int64) (string, error) {
	return m.MintScoped(ctx, appID, installationID, nil)
}

// MintScoped mints or returns a cached installation token, optionally
// downscoped to the given permission set. A nil permissions value requests
// the installation's full default permissions.
func (m *Minter) MintScoped(ctx context.Context, appID, installationID int64, permissions *github.InstallationPermissions) (string, error) {
	if appID <= 0 {
		return "", fmt.Errorf("appID must be greater than zero")
	}
	if installationID <= 0 {
		return "", fmt.Errorf("installationID must be greater than zero")
	}
	key := tokenCacheKey{AppID: appID, InstallationID: installationID, PermissionsKey: permissionsFingerprint(permissions)}
	now := m.now()

	m.mu.Lock()
	if cached := m.cache[key]; cached.Token != "" && now.Before(cached.ExpiresAt.Add(-refreshSkew)) {
		m.mu.Unlock()
		return cached.Token, nil
	}
	m.mu.Unlock()

	appJWT, err := m.signAppJWT(appID, now)
	if err != nil {
		return "", err
	}
	client := github.NewClient(m.httpClient).WithAuthToken(appJWT)
	if m.baseURL != nil {
		client.BaseURL = m.baseURL
	}
	var opts *github.InstallationTokenOptions
	if permissions != nil {
		opts = &github.InstallationTokenOptions{Permissions: permissions}
	}
	installationToken, _, err := client.Apps.CreateInstallationToken(ctx, installationID, opts)
	if err != nil {
		return "", fmt.Errorf("create GitHub App installation token: %w", err)
	}
	token := installationToken.GetToken()
	if token == "" {
		return "", fmt.Errorf("GitHub App installation token response missing token")
	}
	expiresAt := now.Add(time.Hour)
	if installationToken.ExpiresAt != nil && !installationToken.ExpiresAt.IsZero() {
		expiresAt = installationToken.ExpiresAt.Time
	}

	m.mu.Lock()
	m.cache[key] = cachedToken{Token: token, ExpiresAt: expiresAt}
	m.mu.Unlock()
	return token, nil
}

// permissionsFingerprint produces a stable cache-key fragment for a
// permission set so scoped and full tokens never share cache entries.
func permissionsFingerprint(p *github.InstallationPermissions) string {
	if p == nil {
		return ""
	}
	raw, err := json.Marshal(p)
	if err != nil {
		return "unmarshalable"
	}
	sum := sha256.Sum256(raw)
	return base64.RawURLEncoding.EncodeToString(sum[:8])
}

// AppJWT signs a short-lived JWT for GitHub App API calls.
func (m *Minter) AppJWT(appID int64) (string, error) {
	if appID <= 0 {
		return "", fmt.Errorf("appID must be greater than zero")
	}
	return m.signAppJWT(appID, m.now())
}

func (m *Minter) signAppJWT(appID int64, now time.Time) (string, error) {
	header := map[string]string{"alg": "RS256", "typ": "JWT"}
	payload := map[string]any{
		"iat": now.Add(-time.Minute).Unix(),
		"exp": now.Add(10 * time.Minute).Unix(),
		"iss": strconv.FormatInt(appID, 10),
	}
	return signJWT(header, payload, m.privateKey)
}

// KeyedMinter caches per-private-key minters and implements InstallationTokenMinter.
type KeyedMinter struct {
	opts  []Option
	mu    sync.Mutex
	byPEM map[[32]byte]*Minter
}

// NewKeyedMinter creates a multi-key installation token minter.
func NewKeyedMinter(opts ...Option) *KeyedMinter {
	return &KeyedMinter{opts: opts, byPEM: make(map[[32]byte]*Minter)}
}

// MintInstallationToken mints an installation token using privateKeyPEM.
func (k *KeyedMinter) MintInstallationToken(ctx context.Context, appID, installationID int64, privateKeyPEM []byte) (string, error) {
	m, err := k.minterForKey(privateKeyPEM)
	if err != nil {
		return "", err
	}
	return m.Mint(ctx, appID, installationID)
}

// MintScopedInstallationToken mints a permission-downscoped installation
// token using privateKeyPEM. Implements ScopedInstallationTokenMinter.
func (k *KeyedMinter) MintScopedInstallationToken(ctx context.Context, appID, installationID int64, privateKeyPEM []byte, permissions *github.InstallationPermissions) (string, error) {
	m, err := k.minterForKey(privateKeyPEM)
	if err != nil {
		return "", err
	}
	return m.MintScoped(ctx, appID, installationID, permissions)
}

// AppJWT signs a short-lived JWT using privateKeyPEM.
func (k *KeyedMinter) AppJWT(appID int64, privateKeyPEM []byte) (string, error) {
	m, err := k.minterForKey(privateKeyPEM)
	if err != nil {
		return "", err
	}
	return m.AppJWT(appID)
}

func (k *KeyedMinter) minterForKey(privateKeyPEM []byte) (*Minter, error) {
	hash := sha256.Sum256(privateKeyPEM)
	k.mu.Lock()
	m := k.byPEM[hash]
	k.mu.Unlock()
	if m == nil {
		var err error
		m, err = NewMinter(privateKeyPEM, k.opts...)
		if err != nil {
			return nil, err
		}
		k.mu.Lock()
		if existing := k.byPEM[hash]; existing != nil {
			m = existing
		} else {
			k.byPEM[hash] = m
		}
		k.mu.Unlock()
	}
	return m, nil
}

func parsePrivateKey(data []byte) (*rsa.PrivateKey, error) {
	block, _ := pem.Decode(data)
	if block == nil {
		return nil, fmt.Errorf("no PEM block found in GitHub App private key")
	}
	key, err := x509.ParsePKCS8PrivateKey(block.Bytes)
	if err != nil {
		pkcs1, pkcs1Err := x509.ParsePKCS1PrivateKey(block.Bytes)
		if pkcs1Err != nil {
			return nil, fmt.Errorf("parse GitHub App private key: %w", err)
		}
		return pkcs1, nil
	}
	rsaKey, ok := key.(*rsa.PrivateKey)
	if !ok {
		return nil, fmt.Errorf("GitHub App private key is not RSA")
	}
	return rsaKey, nil
}

func signJWT(header map[string]string, payload map[string]any, key *rsa.PrivateKey) (string, error) {
	headerJSON, err := json.Marshal(header)
	if err != nil {
		return "", err
	}
	payloadJSON, err := json.Marshal(payload)
	if err != nil {
		return "", err
	}
	signingInput := base64.RawURLEncoding.EncodeToString(headerJSON) + "." + base64.RawURLEncoding.EncodeToString(payloadJSON)
	hash := sha256.Sum256([]byte(signingInput))
	sig, err := rsa.SignPKCS1v15(rand.Reader, key, crypto.SHA256, hash[:])
	if err != nil {
		return "", err
	}
	return signingInput + "." + base64.RawURLEncoding.EncodeToString(sig), nil
}

package linear

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"time"
)

var linearGraphQLEndpoint = "https://api.linear.app/graphql"

// LinearClient provides operations against the Linear GraphQL API.
type LinearClient interface {
	// FetchIssuesByLabel returns issues in the given project that carry the specified label name.
	FetchIssuesByLabel(ctx context.Context, projectID, labelName string) ([]Issue, error)

	// GetLabelID returns the ID of the label with the given name within a team.
	GetLabelID(ctx context.Context, teamID, labelName string) (string, error)

	// AddLabel adds labelID to the issue identified by issueID.
	AddLabel(ctx context.Context, issueID, labelID string) error

	// RemoveLabel removes labelID from the issue identified by issueID.
	RemoveLabel(ctx context.Context, issueID, labelID string) error

	// AddComment posts a comment body on the given issue.
	AddComment(ctx context.Context, issueID, body string) error

	// CreateIssue creates a new issue in a team with optional project and label IDs.
	CreateIssue(ctx context.Context, input CreateIssueInput) (*CreatedIssue, error)
}

// httpLinearClient is the production implementation using net/http.
type httpLinearClient struct {
	apiKey     string
	httpClient *http.Client
}

// NewClient returns a LinearClient authenticated with the given API key.
func NewClient(apiKey string) LinearClient {
	return &httpLinearClient{
		apiKey:     apiKey,
		httpClient: &http.Client{Timeout: 30 * time.Second},
	}
}

// FetchIssuesByLabel returns issues in the project that have the given label.
func (c *httpLinearClient) FetchIssuesByLabel(ctx context.Context, projectID, labelName string) ([]Issue, error) {
	const query = `
query($projectId: ID!, $labelName: String!) {
  issues(
    filter: {
      project: { id: { eq: $projectId } }
      labels: { name: { eq: $labelName } }
      state: { type: { neq: "cancelled" } }
    }
    first: 50
  ) {
    nodes {
      id
      identifier
      title
      description
      labels { nodes { id name } }
    }
  }
}`
	var data issuesByProjectData
	if err := c.do(ctx, query, map[string]any{
		"projectId": projectID,
		"labelName": labelName,
	}, &data); err != nil {
		return nil, err
	}
	return data.Issues.Nodes, nil
}

// GetLabelID returns the ID of the label with the given name within a team.
func (c *httpLinearClient) GetLabelID(ctx context.Context, teamID, labelName string) (string, error) {
	const query = `
query($teamId: ID!, $name: String!) {
  issueLabels(filter: { team: { id: { eq: $teamId } }, name: { eq: $name } }) {
    nodes { id name }
  }
}`
	var data labelsData
	if err := c.do(ctx, query, map[string]any{
		"teamId": teamID,
		"name":   labelName,
	}, &data); err != nil {
		return "", err
	}
	if len(data.IssueLabels.Nodes) == 0 {
		return "", fmt.Errorf("linear label %q not found in team %s", labelName, teamID)
	}
	return data.IssueLabels.Nodes[0].ID, nil
}

// AddLabel adds the label to the issue via Linear's atomic label mutation.
func (c *httpLinearClient) AddLabel(ctx context.Context, issueID, labelID string) error {
	const mutation = `
mutation($issueId: String!, $labelId: String!) {
  issueAddLabel(id: $issueId, labelId: $labelId) {
    success
  }
}`
	var data issueAddLabelData
	if err := c.do(ctx, mutation, map[string]any{
		"issueId": issueID,
		"labelId": labelID,
	}, &data); err != nil {
		return err
	}
	if !data.IssueAddLabel.Success {
		return fmt.Errorf("issueAddLabel returned success=false")
	}
	return nil
}

// RemoveLabel removes the label from the issue via Linear's atomic label mutation.
func (c *httpLinearClient) RemoveLabel(ctx context.Context, issueID, labelID string) error {
	const mutation = `
mutation($issueId: String!, $labelId: String!) {
  issueRemoveLabel(id: $issueId, labelId: $labelId) {
    success
  }
}`
	var data issueRemoveLabelData
	if err := c.do(ctx, mutation, map[string]any{
		"issueId": issueID,
		"labelId": labelID,
	}, &data); err != nil {
		return err
	}
	if !data.IssueRemoveLabel.Success {
		return fmt.Errorf("issueRemoveLabel returned success=false")
	}
	return nil
}

// AddComment posts a Markdown comment on the issue.
func (c *httpLinearClient) AddComment(ctx context.Context, issueID, body string) error {
	const mutation = `
mutation($issueId: String!, $body: String!) {
  commentCreate(input: { issueId: $issueId, body: $body }) {
    success
  }
}`
	var data commentCreateData
	if err := c.do(ctx, mutation, map[string]any{
		"issueId": issueID,
		"body":    body,
	}, &data); err != nil {
		return err
	}
	if !data.CommentCreate.Success {
		return fmt.Errorf("commentCreate returned success=false")
	}
	return nil
}

// CreateIssue creates a new issue via the Linear GraphQL API.
func (c *httpLinearClient) CreateIssue(ctx context.Context, input CreateIssueInput) (*CreatedIssue, error) {
	const mutation = `
mutation($teamId: String!, $title: String, $description: String, $projectId: String, $labelIds: [String!]) {
  issueCreate(input: { teamId: $teamId, title: $title, description: $description, projectId: $projectId, labelIds: $labelIds }) {
    success
    issue { id identifier url }
  }
}`
	vars := map[string]any{
		"teamId": input.TeamID,
		"title":  input.Title,
	}
	if input.Description != "" {
		vars["description"] = input.Description
	}
	if input.ProjectID != "" {
		vars["projectId"] = input.ProjectID
	}
	if len(input.LabelIDs) > 0 {
		vars["labelIds"] = input.LabelIDs
	}

	var data issueCreateData
	if err := c.do(ctx, mutation, vars, &data); err != nil {
		return nil, err
	}
	if !data.IssueCreate.Success {
		return nil, fmt.Errorf("issueCreate returned success=false")
	}
	return &CreatedIssue{
		ID:         data.IssueCreate.Issue.ID,
		Identifier: data.IssueCreate.Issue.Identifier,
		URL:        data.IssueCreate.Issue.URL,
	}, nil
}

// currentLabelIDs returns the IDs of labels currently on the issue.
func (c *httpLinearClient) currentLabelIDs(ctx context.Context, issueID string) ([]string, error) {
	const query = `
query($id: String!) {
  issue(id: $id) {
    labels { nodes { id } }
  }
}`
	type issueData struct {
		Issue struct {
			Labels struct {
				Nodes []LabelNode `json:"nodes"`
			} `json:"labels"`
		} `json:"issue"`
	}
	var data issueData
	if err := c.do(ctx, query, map[string]any{"id": issueID}, &data); err != nil {
		return nil, err
	}
	ids := make([]string, 0, len(data.Issue.Labels.Nodes))
	for _, n := range data.Issue.Labels.Nodes {
		ids = append(ids, n.ID)
	}
	return ids, nil
}

// do executes a GraphQL request and unmarshals the data field into out.
func (c *httpLinearClient) do(ctx context.Context, query string, vars map[string]any, out any) error {
	body, err := json.Marshal(graphqlRequest{Query: query, Variables: vars})
	if err != nil {
		return fmt.Errorf("marshaling request: %w", err)
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodPost, linearGraphQLEndpoint, bytes.NewReader(body))
	if err != nil {
		return fmt.Errorf("building request: %w", err)
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Authorization", c.apiKey)

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return fmt.Errorf("linear API request: %w", err)
	}
	defer resp.Body.Close()

	raw, err := io.ReadAll(resp.Body)
	if err != nil {
		return fmt.Errorf("reading response: %w", err)
	}

	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("linear API returned HTTP %d: %s", resp.StatusCode, raw)
	}

	// Unmarshal into a typed envelope where Data is our target type.
	type envelope struct {
		Data   json.RawMessage `json:"data"`
		Errors []graphqlError  `json:"errors,omitempty"`
	}
	var env envelope
	if err := json.Unmarshal(raw, &env); err != nil {
		return fmt.Errorf("unmarshaling response: %w", err)
	}
	if len(env.Errors) > 0 {
		return fmt.Errorf("linear GraphQL error: %s", env.Errors[0].Message)
	}
	if err := json.Unmarshal(env.Data, out); err != nil {
		return fmt.Errorf("unmarshaling data: %w", err)
	}
	return nil
}

