	"minor":         SeverityLow,
	"info":          SeverityInfo,
	"informational": SeverityInfo,
	"note":          SeverityInfo,
	"none":          SeverityInfo,
}

var confidenceAliases = map[string]string{
	"confirmed": ConfidenceConfirmed,
	"certain":   ConfidenceConfirmed,
	"verified":  ConfidenceConfirmed,
	"high":      ConfidenceFirm,
	"firm":      ConfidenceFirm,
