var categoryAliases = map[string]string{
	"sql-injection":               "injection",
	"sqli":                        "injection",
	"command-injection":           "injection",
	"code-injection":              "injection",
	"template-injection":          "injection",
	"ldap-injection":              "injection",
	"authentication":              "authn",
	"auth":                        "authn",
