	"configuration":               "misconfiguration",
	"security-misconfiguration":   "misconfiguration",
	"business-logic":              "logic-flaw",
	"logic":                       "logic-flaw",
	"information-disclosure":      "info-leak",
	"info-disclosure":             "info-leak",
