var knownCategories = func() map[string]bool {
	m := make(map[string]bool, len(Categories))
	for _, c := range Categories {
		m[c] = true
	}
	return m
}()

func normalizeToken(s string) string {
	s = strings.ToLower(strings.TrimSpace(s))
	s = strings.Join(strings.Fields(s), "-")
	return strings.ReplaceAll(s, "_", "-")
}

func normalizeSeverity(s string) string {
	t := normalizeToken(s)
	if canon, ok := severityAliases[t]; ok {
		return canon
	}
	return t
}

func normalizeConfidence(s string) string {
	t := normalizeToken(s)
	if canon, ok := confidenceAliases[t]; ok {
		return canon
	}
	return t
}

func normalizeCategory(s string) string {
	t := normalizeToken(s)
	if canon, ok := categoryAliases[t]; ok {
		return canon
	}
	return t
}

func clampText(s string, max int) string {
	s = strings.TrimSpace(s)
	r := []rune(s)
	if len(r) <= max {
		return s
	}
	return string(r[:max])
}

func normalizePath(p, repository string) string {
	p = strings.TrimSpace(p)
	if p == "" {
		return ""
	}
	p = strings.ReplaceAll(p, "\\", "/")
	p = path.Clean(p)
	p = strings.TrimPrefix(p, "/")
	for strings.HasPrefix(p, "./") {
		p = p[2:]
	}
	if p == "." {
		return ""
	}
	if repository != "" {
		repoName := path.Base(strings.ReplaceAll(strings.TrimSpace(repository), "\\", "/"))
		repoName = strings.TrimSuffix(repoName, ".git")
		if repoName != "" && repoName != "." {
			if rest, ok := strings.CutPrefix(p, repoName+"/"); ok {
				p = rest
			}
		}
	}
	return p
}

func normalizeStringSet(in []string, transform func(string) string) []string {
	if len(in) == 0 {
		return nil
	}
	seen := make(map[string]bool, len(in))
	out := make([]string, 0, len(in))
	for _, s := range in {
		s = strings.TrimSpace(s)
		if transform != nil {
			s = transform(s)
		}
		if s == "" || seen[s] {
			continue
		}
		seen[s] = true
		out = append(out, s)
	}
	if len(out) == 0 {
		return nil
	}
	sort.Strings(out)
	return out
}

// normalizeReference keeps only well-formed http/https URLs. References are
// model-authored and rendered as clickable links in the dashboard, so other
// schemes (javascript:, data:, file:, ...) and malformed values are dropped.
func normalizeReference(s string) string {
	s = strings.TrimSpace(s)
	u, err := url.Parse(s)
	if err != nil {
		return ""
	}
	switch strings.ToLower(u.Scheme) {
	case "http", "https":
		if u.Host == "" {
			return ""
		}
		return s
	default:
		return ""
	}
}

// RedactedMarker replaces credential material found in model-authored text.
const RedactedMarker = "[REDACTED]"

// redactionPatterns match obvious credential material: PEM private key
// blocks and well-known provider token shapes. Deliberately conservative —
// no generic entropy heuristics — so ordinary code passes through unchanged.
var redactionPatterns = []*regexp.Regexp{
	regexp.MustCompile(`(?s)-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----.*?-----END [A-Z0-9 ]*PRIVATE KEY-----`),
	regexp.MustCompile(`AKIA[0-9A-Z]{16}`),                                              // AWS access key ID
	regexp.MustCompile(`gh[pousr]_[A-Za-z0-9]{20,}`),                                    // GitHub token
	regexp.MustCompile(`sk-[A-Za-z0-9]{20,}`),                                           // OpenAI-style secret key
	regexp.MustCompile(`xox[abprs]-[A-Za-z0-9-]{10,}`),                                  // Slack token
	regexp.MustCompile(`AIza[0-9A-Za-z_-]{35}`),                                         // Google API key
	regexp.MustCompile(`eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}`), // JWT
}

// redactSecrets replaces credential material in model-authored text with
// RedactedMarker. It is idempotent: no pattern matches the marker itself.
func redactSecrets(s string) string {
	for _, re := range redactionPatterns {
		s = re.ReplaceAllLiteralString(s, RedactedMarker)
	}
	return s
}

func normalizeCWE(s string) string {
	s = strings.ToUpper(strings.TrimSpace(s))
	s = strings.TrimPrefix(s, "CWE-")
	s = strings.TrimPrefix(s, "CWE")
	s = strings.TrimSpace(strings.TrimPrefix(s, "-"))
	if s == "" {
		return ""
	}
	return "CWE-" + s
}

// Normalize canonicalizes the finding in place: trims and clamps text,
// alias-maps severity/confidence/category, dedupes and sorts CWE, tags, and
// references (keeping only http/https reference URLs), redacts obvious
// credential material from prose and evidence snippets, normalizes file
// paths and line numbers, and recomputes the Fingerprint.
func (f *Finding) Normalize() {
	if f == nil {
		return
	}
	f.Title = clampText(f.Title, maxTitleLen)
	f.Category = normalizeCategory(f.Category)
	f.Severity = normalizeSeverity(f.Severity)
	f.Confidence = normalizeConfidence(f.Confidence)
	if f.Confidence == "" {
		f.Confidence = ConfidenceTentative
	}

	f.Repository = strings.TrimSpace(f.Repository)
	f.Revision = strings.TrimSpace(f.Revision)
	f.FilePath = normalizePath(f.FilePath, f.Repository)
	if f.StartLine < 0 {
		f.StartLine = 0
	}
	if f.EndLine < 0 {
		f.EndLine = 0
	}
	f.Symbol = strings.TrimSpace(f.Symbol)

	f.CWE = normalizeStringSet(f.CWE, normalizeCWE)

	f.Description = redactSecrets(clampText(f.Description, maxTextLen))
	f.Impact = redactSecrets(clampText(f.Impact, maxTextLen))
	f.AttackVector = redactSecrets(clampText(f.AttackVector, maxTextLen))
	f.Remediation = redactSecrets(clampText(f.Remediation, maxTextLen))

	if len(f.Evidence) == 0 {
		f.Evidence = nil
	}
	for i := range f.Evidence {
		e := &f.Evidence[i]
		e.FilePath = normalizePath(e.FilePath, f.Repository)
		if e.StartLine < 0 {
			e.StartLine = 0
		}
		if e.EndLine < 0 {
			e.EndLine = 0
		}
		e.Snippet = redactSecrets(clampText(e.Snippet, maxSnippetLen))
		e.Note = strings.TrimSpace(e.Note)
	}

	f.References = normalizeStringSet(f.References, normalizeReference)
	f.SourceAgent = strings.TrimSpace(f.SourceAgent)
	f.ScanStep = strings.TrimSpace(f.ScanStep)
	f.Tags = normalizeStringSet(f.Tags, func(s string) string { return strings.ToLower(s) })

	f.SourceKind = normalizeToken(f.SourceKind)
	f.Tool = strings.TrimSpace(f.Tool)
	f.ToolVersion = strings.TrimSpace(f.ToolVersion)
	f.RuleID = strings.TrimSpace(f.RuleID)
	f.CorrelatedFingerprints = normalizeStringSet(f.CorrelatedFingerprints, strings.ToLower)

	f.Fingerprint = Fingerprint(*f)
}

// Validate reports whether the finding has the required, well-known fields.
// It returns a single error aggregating every problem, or nil.
func (f Finding) Validate() error {
	var problems []string
	if strings.TrimSpace(f.Title) == "" {
		problems = append(problems, "title is required")
	}
	if strings.TrimSpace(f.Description) == "" {
		problems = append(problems, "description is required")
	}
	switch {
	case strings.TrimSpace(f.Category) == "":
		problems = append(problems, "category is required")
	case !knownCategories[f.Category]:
		problems = append(problems, fmt.Sprintf("unknown category %q (known: %s)", f.Category, strings.Join(Categories, ", ")))
	}
	switch {
	case strings.TrimSpace(f.Severity) == "":
		problems = append(problems, "severity is required")
	case SeverityRank(f.Severity) < 0:
		problems = append(problems, fmt.Sprintf("unknown severity %q (known: %s)", f.Severity, strings.Join(Severities, ", ")))
	}
	if f.Confidence != "" {
		switch f.Confidence {
		case ConfidenceConfirmed, ConfidenceFirm, ConfidenceTentative:
		default:
			problems = append(problems, fmt.Sprintf("unknown confidence %q (known: %s, %s, %s)", f.Confidence, ConfidenceConfirmed, ConfidenceFirm, ConfidenceTentative))
		}
	}
	switch normalizeToken(f.SourceKind) {
	case "", SourceKindAgent:
	case SourceKindScanner:
		if strings.TrimSpace(f.Tool) == "" {
			problems = append(problems, "tool is required for scanner findings")
		}
		if strings.TrimSpace(f.RuleID) == "" {
			problems = append(problems, "rule_id is required for scanner findings")
		}
	default:
		problems = append(problems, fmt.Sprintf("unknown source_kind %q (known: %s, %s)", f.SourceKind, SourceKindAgent, SourceKindScanner))
	}
	if len(problems) == 0 {
		return nil
	}
	return fmt.Errorf("invalid finding: %s", strings.Join(problems, "; "))
}

var stopwords = map[string]bool{
	"a": true, "an": true, "the": true, "of": true, "in": true, "on": true,
	"at": true, "to": true, "for": true, "is": true, "are": true, "was": true,
	"were": true, "be": true, "been": true, "by": true, "with": true,
	"via": true, "and": true, "or": true, "as": true, "from": true,
	"this": true, "that": true, "it": true, "its": true, "can": true,
	"may": true, "when": true, "which": true,
}

func tokenize(s string) []string {
	fields := strings.FieldsFunc(strings.ToLower(s), func(r rune) bool {
		return (r < 'a' || r > 'z') && (r < '0' || r > '9')
	})
	out := fields[:0]
	for _, t := range fields {
		if t == "" || stopwords[t] {
			continue
		}
		out = append(out, t)
	}
	return out
}

func sortedTokenSet(s string) []string {
	toks := tokenize(s)
	seen := make(map[string]bool, len(toks))
	out := toks[:0]
	for _, t := range toks {
		if seen[t] {
			continue
		}
		seen[t] = true
		out = append(out, t)
	}
	sort.Strings(out)
	return out
}

// Fingerprint computes a stable 16-hex-character identity for a finding.
//
// Agent findings hash repository, file path, category, CWEs, and normalized
// title tokens: whitespace, casing, and word order in the title do not
// change the result. Scanner findings (SourceKind == SourceKindScanner) use
// a deliberately different derivation — see scannerFingerprint — so an
// agent finding and a scanner finding can never share an identity and
// merging the two sources is always an explicit correlation act, never a
// key collision.
func Fingerprint(f Finding) string {
	if f.IsScannerFinding() {
		return scannerFingerprint(f)
	}
	cwes := normalizeStringSet(f.CWE, normalizeCWE)
	parts := []string{
		strings.ToLower(strings.TrimSpace(f.Repository)),
		normalizePath(f.FilePath, f.Repository),
		normalizeCategory(f.Category),
		strings.Join(cwes, ","),
		strings.Join(sortedTokenSet(f.Title), " "),
	}
	sum := sha256.Sum256([]byte(strings.Join(parts, "|")))
	return hex.EncodeToString(sum[:8])
}

var severityRanks = map[string]int{
	SeverityCritical: 4,
	SeverityHigh:     3,
	SeverityMedium:   2,
	SeverityLow:      1,
	SeverityInfo:     0,
}

// SeverityRank maps a severity to a numeric rank: critical=4 down to info=0.
// Unknown severities return -1.
func SeverityRank(s string) int {
	if r, ok := severityRanks[s]; ok {
		return r
	}
	if r, ok := severityRanks[normalizeSeverity(s)]; ok {
		return r
	}
	return -1
}

// SeverityAtLeast reports whether severity s is at least as severe as min.
// An unknown s is never at least anything; an unknown or empty min passes
// any known severity.
func SeverityAtLeast(s, min string) bool {
	rs := SeverityRank(s)
	return rs >= 0 && rs >= SeverityRank(min)
}

// Summarize counts findings by severity. The result always contains every
// known severity (possibly zero) plus the key "total".
func Summarize(findings []Finding) map[string]int {
	out := make(map[string]int, len(Severities)+1)
	for _, s := range Severities {
		out[s] = 0
	}
	for _, f := range findings {
		out[normalizeSeverity(f.Severity)]++
	}
	out["total"] = len(findings)
	return out
}

package security

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"slices"
	"sort"
	"strconv"
	"strings"
)

// ScannerRecord is the canonical normalized record a deterministic scanner
// tool (semgrep, gosec, trivy, bandit, ...) must be adapted into before
// ingestion. It is intentionally much flatter than Finding: deterministic
// tools report a rule match at a location, not a narrative, so the adapter
// contract only carries what such tools can actually attest to.
type ScannerRecord struct {
	// Tool is the scanner's name, e.g. "gosec". Required.
	Tool string `json:"tool"`
	// ToolVersion is the scanner's version, e.g. "2.18.2". Optional but
	// strongly recommended: it is preserved in the finding's provenance.
	ToolVersion string `json:"tool_version,omitempty"`
	// RuleID is the tool's rule identifier, e.g. "G401". Required; it is
	// part of the finding's deterministic fingerprint.
	RuleID string `json:"rule_id"`
	// RuleName is the tool's human-readable rule name. Optional; used as
	// the finding title when present.
	RuleName string `json:"rule_name,omitempty"`
	// Message is the tool's finding message. Required; becomes the finding
	// description (and the title when RuleName is empty).
	Message string `json:"message"`
	// Severity is the tool's severity in the tool's own vocabulary
	// (e.g. ERROR, WARNING, HIGH, moderate). Required; it must map onto the
	// platform scale (critical/high/medium/low/info).
	Severity string `json:"severity"`
	// Category optionally names the platform finding category (or an alias
	// of one). When absent it is derived from CWE, falling back to "other".
	Category string `json:"category,omitempty"`

	// FilePath is the repository-relative path of the matched file,
	// forward slashes. Required.
	FilePath string `json:"file_path"`
	// StartLine / EndLine bound the matched region (1-based, 0 = unknown).
	StartLine int `json:"start_line,omitempty"`
	EndLine   int `json:"end_line,omitempty"`
	// Symbol is the enclosing function/method/symbol when the tool reports
	// one; it anchors the fingerprint more stably than line numbers.
	Symbol string `json:"symbol,omitempty"`

	// CWE is the rule's CWE identifier, e.g. "CWE-798". Optional.
	CWE string `json:"cwe,omitempty"`
	// References are external URLs (rule docs, advisories). Optional.
	References []string `json:"references,omitempty"`
	// RawEvidence is the tool's verbatim matched snippet. Optional; stored
	// as finding evidence after secret redaction.
	RawEvidence string `json:"raw_evidence,omitempty"`
	// Extra carries tool-specific key/value metadata preserved verbatim
	// (subject to secret redaction) in the finding's raw payload.
	Extra map[string]string `json:"extra,omitempty"`
}

// Redacted returns a copy of the record with obvious credential material
// replaced by RedactedMarker in every free-text field, so the raw payload
// can be preserved verbatim-except-secrets.
func (r ScannerRecord) Redacted() ScannerRecord {
	r.RuleName = redactSecrets(r.RuleName)
	r.Message = redactSecrets(r.Message)
	r.RawEvidence = redactSecrets(r.RawEvidence)
	if len(r.References) > 0 {
		refs := make([]string, len(r.References))
		for i, ref := range r.References {
			refs[i] = redactSecrets(ref)
		}
		r.References = refs
	}
	if len(r.Extra) > 0 {
		extra := make(map[string]string, len(r.Extra))
		for k, v := range r.Extra {
			extra[k] = redactSecrets(v)
		}
		r.Extra = extra
	}
	return r
}

// scannerSeverityAliases maps severity vocabulary common to deterministic
// tools (SARIF levels, semgrep, gosec, trivy, npm audit, ...) onto the
// platform scale, before falling back to the shared severity aliases.
var scannerSeverityAliases = map[string]string{
	"error":      SeverityHigh, // SARIF / semgrep ERROR
	"err":        SeverityHigh,
	"warn":       SeverityMedium,
	"unknown":    SeverityInfo, // trivy UNKNOWN
	"negligible": SeverityInfo,
}

// mapScannerSeverity maps a tool severity into the platform scale. It
// returns "" when the value is not recognizably mappable.
func mapScannerSeverity(s string) string {
	t := normalizeToken(s)
	if canon, ok := scannerSeverityAliases[t]; ok {
		return canon
	}
	canon := normalizeSeverity(t)
	if SeverityRank(canon) >= 0 {
		return canon
	}
	return ""
}

// cweCategories maps well-known CWE identifiers onto platform categories so
// records without an explicit category still land somewhere meaningful.
var cweCategories = map[string]string{
	"CWE-77": "injection", "CWE-78": "injection", "CWE-89": "injection",
	"CWE-94": "injection", "CWE-95": "injection", "CWE-917": "injection",
	"CWE-79":  "xss",
	"CWE-22":  "path-traversal",
	"CWE-23":  "path-traversal",
	"CWE-259": "secrets", "CWE-321": "secrets", "CWE-522": "secrets", "CWE-798": "secrets",
	"CWE-295": "crypto", "CWE-326": "crypto", "CWE-327": "crypto",
	"CWE-328": "crypto", "CWE-338": "crypto",
	"CWE-918": "ssrf",
	"CWE-502": "deserialization",
	"CWE-362": "race-condition", "CWE-367": "race-condition",
	"CWE-400": "dos", "CWE-770": "dos",
	"CWE-119": "memory-safety", "CWE-125": "memory-safety", "CWE-416": "memory-safety",
	"CWE-476": "memory-safety", "CWE-787": "memory-safety",
	"CWE-200": "info-leak", "CWE-209": "info-leak", "CWE-532": "info-leak",
	"CWE-287": "authn", "CWE-306": "authn", "CWE-521": "authn",
	"CWE-284": "authz", "CWE-285": "authz", "CWE-639": "authz",
	"CWE-862": "authz", "CWE-863": "authz",
	"CWE-614": "misconfiguration", "CWE-1004": "misconfiguration",
	"CWE-829": "supply-chain", "CWE-1104": "supply-chain",
}

// scannerCategory resolves the record's platform category: an explicit
// (alias-mapped) category wins, then the CWE mapping, then "other".
func scannerCategory(rec ScannerRecord) string {
	if cat := normalizeCategory(rec.Category); knownCategories[cat] {
		return cat
	}
	if cat, ok := cweCategories[normalizeCWE(rec.CWE)]; ok {
		return cat
	}
	return "other"
}

// NormalizeScannerRecord validates a ScannerRecord against the adapter
// contract and converts it into a platform Finding.
//
// Required fields: tool, rule_id, message, severity (mappable onto the
// platform scale), and file_path. Violations are aggregated into a single
// error so a batch caller can report everything wrong with a record at
// once. The returned Finding went through the same Normalize path as agent
// findings (text clamping, alias mapping, secret redaction of prose and
// evidence) and carries scanner provenance: SourceKind =
// SourceKindScanner, the tool identity/version, and the rule id.
//
// Deterministic tools attest that a rule matched, not that the issue is
// exploitable, so Confidence is fixed at "firm": stronger than an agent's
// unverified "tentative" hypothesis, weaker than a "confirmed" PoC.
// Neither source is authoritative alone — agents are expected to validate
// and correlate scanner findings, not to trust or discard them wholesale.
func NormalizeScannerRecord(rec ScannerRecord, repository, revision string) (Finding, error) {
	var problems []string
	if strings.TrimSpace(rec.Tool) == "" {
		problems = append(problems, "tool is required")
	}
	if strings.TrimSpace(rec.RuleID) == "" {
		problems = append(problems, "rule_id is required")
	}
	if strings.TrimSpace(rec.Message) == "" {
		problems = append(problems, "message is required")
	}
	severity := ""
	if strings.TrimSpace(rec.Severity) == "" {
		problems = append(problems, "severity is required")
	} else if severity = mapScannerSeverity(rec.Severity); severity == "" {
		problems = append(problems, fmt.Sprintf("severity %q does not map onto the platform scale (%s)", rec.Severity, strings.Join(Severities, ", ")))
	}
	if strings.TrimSpace(rec.FilePath) == "" {
		problems = append(problems, "file_path is required")
	}
	if len(problems) > 0 {
		return Finding{}, fmt.Errorf("invalid scanner record: %s", strings.Join(problems, "; "))
	}

	title := strings.TrimSpace(rec.RuleName)
	if title == "" {
		title = strings.TrimSpace(rec.Message)
	}
	// The title derives from tool output that can quote matched secrets
	// (e.g. a secret scanner's message); redact it up front. Scanner
	// fingerprints never use the title, so this cannot change identity.
	title = redactSecrets(title)
	f := Finding{
		Title:       title,
		Category:    scannerCategory(rec),
		Severity:    severity,
		Confidence:  ConfidenceFirm,
		Repository:  repository,
		Revision:    revision,
		FilePath:    rec.FilePath,
		StartLine:   rec.StartLine,
		EndLine:     rec.EndLine,
		Symbol:      rec.Symbol,
		Description: rec.Message,
		References:  rec.References,
		SourceKind:  SourceKindScanner,
		Tool:        rec.Tool,
		ToolVersion: rec.ToolVersion,
		RuleID:      rec.RuleID,
	}
	if cwe := normalizeCWE(rec.CWE); cwe != "" {
		f.CWE = []string{cwe}
	}
	if strings.TrimSpace(rec.RawEvidence) != "" {
		f.Evidence = []Evidence{{
			FilePath:  rec.FilePath,
			StartLine: rec.StartLine,
			EndLine:   rec.EndLine,
			Snippet:   rec.RawEvidence,
			Note:      "verbatim scanner match",
		}}
	}
	f.Normalize()
	if err := f.Validate(); err != nil {
		return Finding{}, fmt.Errorf("invalid scanner record: %w", err)
	}
	return f, nil
}

// scannerFingerprint derives the identity of a deterministic scanner
// finding from (tool, rule id, repository, normalized path, symbol-or-line
// anchor).
//
// Why this derivation, and why it differs from agent fingerprints:
//   - Re-runs of the same tool converge: the hash uses only fields a
//     deterministic tool reproduces run over run, never the message text,
//     so a tool upgrade that rewords its message keeps the same identity.
//   - The symbol anchors the location when the tool reports one (stable
//     across unrelated line drift); otherwise the start line does.
//   - The input is domain-separated with a leading "scanner" component and
//     includes tool + rule id, which agent fingerprints never contain, so a
//     scanner finding can never collide with an agent finding describing
//     the same code. Merging the two sources is an explicit correlation
//     act (CorrelatedFingerprints), recorded on both rows with both
//     provenances intact — never an accident of a shared hash.
func scannerFingerprint(f Finding) string {
	anchor := strings.ToLower(strings.TrimSpace(f.Symbol))
	if anchor == "" && f.StartLine > 0 {
		anchor = "L" + strconv.Itoa(f.StartLine)
	}
	parts := []string{
		"scanner",
		strings.ToLower(strings.TrimSpace(f.Tool)),
		strings.TrimSpace(f.RuleID),
		strings.ToLower(strings.TrimSpace(f.Repository)),
		normalizePath(f.FilePath, f.Repository),
		anchor,
	}
	sum := sha256.Sum256([]byte(strings.Join(parts, "|")))
	return hex.EncodeToString(sum[:8])
}

// Correlation is one recorded link between an agent finding and a scanner
// finding that describe the same issue.
type Correlation struct {
	AgentFingerprint   string
	ScannerFingerprint string
	Reason             string
}

// correlationLineProximity is how many lines apart two findings in the same
// file may start and still be considered the same location.
const correlationLineProximity = 5

// correlatable reports whether an agent finding and a scanner finding
// describe the same issue: same repository and file, line ranges that
// overlap or start within correlationLineProximity lines, and either a
// shared CWE or the same category (the scanner rule's category mapping
// matching the agent's classification). It returns the matched reason.
func correlatable(agent, scanner Finding) (string, bool) {
	if agent.FilePath == "" || scanner.FilePath == "" {
		return "", false
	}
	if !strings.EqualFold(strings.TrimSpace(agent.Repository), strings.TrimSpace(scanner.Repository)) {
		return "", false
	}
	if normalizePath(agent.FilePath, agent.Repository) != normalizePath(scanner.FilePath, scanner.Repository) {
		return "", false
	}
	near := linesOverlap(agent.StartLine, agent.EndLine, scanner.StartLine, scanner.EndLine)
	if !near && agent.StartLine > 0 && scanner.StartLine > 0 {
		d := agent.StartLine - scanner.StartLine
		if d < 0 {
			d = -d
		}
		near = d <= correlationLineProximity
	}
	if !near {
		return "", false
	}
	switch {
	case sharesCWE(agent.CWE, scanner.CWE):
		return "same location and shared CWE", true
	case agent.Category != "" && agent.Category == scanner.Category:
		return "same location and matching category", true
	}
	return "", false
}

// Correlate finds agent↔scanner finding pairs that describe the same issue
// and are not yet cross-referenced on both sides. It never merges: each
// returned Correlation is meant to be recorded on BOTH findings
// (CorrelatedFingerprints), preserving each side's provenance — the agent
// finding keeps its confidence semantics, the scanner finding keeps its
// rule identity, and neither is treated as authoritative alone. Results are
// deterministic: sorted by agent then scanner fingerprint.
func Correlate(findings []Finding) []Correlation {
	var agents, scanners []Finding
	for _, f := range findings {
		if f.Fingerprint == "" {
			f.Fingerprint = Fingerprint(f)
		}
		if f.IsScannerFinding() {
			scanners = append(scanners, f)
		} else {
			agents = append(agents, f)
		}
	}
	var out []Correlation
	seen := make(map[string]bool)
	for _, a := range agents {
		for _, s := range scanners {
			reason, ok := correlatable(a, s)
			if !ok {
				continue
			}
			if containsString(a.CorrelatedFingerprints, s.Fingerprint) &&
				containsString(s.CorrelatedFingerprints, a.Fingerprint) {
				continue
			}
			key := a.Fingerprint + "|" + s.Fingerprint
			if seen[key] {
				continue
			}
			seen[key] = true
			out = append(out, Correlation{
				AgentFingerprint:   a.Fingerprint,
				ScannerFingerprint: s.Fingerprint,
				Reason:             reason,
			})
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].AgentFingerprint != out[j].AgentFingerprint {
			return out[i].AgentFingerprint < out[j].AgentFingerprint
		}
		return out[i].ScannerFingerprint < out[j].ScannerFingerprint
	})
	return out
}

// ApplyCorrelations records the correlations on both sides of each pair in
// the slice, in place: each finding's CorrelatedFingerprints gains the
// counterpart's fingerprint (set semantics, sorted). Nothing else about
// either finding changes.
func ApplyCorrelations(findings []Finding, correlations []Correlation) {
	if len(correlations) == 0 {
		return
	}
	add := make(map[string][]string, len(correlations)*2)
	for _, c := range correlations {
		add[c.AgentFingerprint] = append(add[c.AgentFingerprint], c.ScannerFingerprint)
		add[c.ScannerFingerprint] = append(add[c.ScannerFingerprint], c.AgentFingerprint)
	}
	for i := range findings {
		fp := findings[i].Fingerprint
		if fp == "" {
			fp = Fingerprint(findings[i])
		}
		others := add[fp]
		if len(others) == 0 {
			continue
		}
		findings[i].CorrelatedFingerprints = normalizeStringSet(
			append(findings[i].CorrelatedFingerprints, others...), strings.ToLower)
	}
}

func containsString(set []string, s string) bool {
	return slices.Contains(set, s)
}

package security

import (
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"
)

// RankWeights weighs the four scoring dimensions used by Rank.
type RankWeights struct {
	Severity       float64
	Confidence     float64
	Exploitability float64
	Exposure       float64
}

// DefaultRankWeights returns the standard scoring weights.
func DefaultRankWeights() RankWeights {
	return RankWeights{Severity: 0.5, Confidence: 0.2, Exploitability: 0.15, Exposure: 0.15}
}

// RankRules steers Rank. It is typically produced by ParseRankRules from
// operator-authored ranker text.
type RankRules struct {
	// Text is the prose left over after directive lines were parsed out; it
	// can be handed to a triage agent verbatim.
	Text              string
	Weights           RankWeights
	SeverityFloors    map[string]string
	SeverityCeilings  map[string]string
	ExcludeCategories []string
	MinSeverity       string
}

// ParseRankRules extracts directive lines from operator-authored ranker
// text. Recognized directives (one per line, case-insensitive):
//
//	severity-floor: <category>=<severity>
//	severity-ceiling: <category>=<severity>
//	exclude: <category>[,<category>...]
//	min-severity: <severity>
//	weight: <severity|confidence|exploitability|exposure>=<float>[,<name>=<float>...]
//
// Lines that are not valid directives are retained verbatim in Text.
func ParseRankRules(text string) RankRules {
	rules := RankRules{Weights: DefaultRankWeights()}
	var prose []string
	for line := range strings.SplitSeq(text, "\n") {
		trimmed := strings.TrimSpace(line)
		directive, rest, ok := strings.Cut(trimmed, ":")
		if !ok {
			prose = append(prose, line)
			continue
		}
		rest = strings.TrimSpace(rest)
		switch strings.ToLower(strings.TrimSpace(directive)) {
		case "severity-floor":
			if cat, sev, ok := parseCategorySeverity(rest); ok {
				if rules.SeverityFloors == nil {
					rules.SeverityFloors = map[string]string{}
				}
				rules.SeverityFloors[cat] = sev
				continue
			}
		case "severity-ceiling":
			if cat, sev, ok := parseCategorySeverity(rest); ok {
				if rules.SeverityCeilings == nil {
					rules.SeverityCeilings = map[string]string{}
				}
				rules.SeverityCeilings[cat] = sev
				continue
			}
		case "exclude":
			cats := parseCategoryList(rest)
			if len(cats) > 0 {
				rules.ExcludeCategories = append(rules.ExcludeCategories, cats...)
				continue
			}
		case "min-severity":
			sev := normalizeSeverity(rest)
			if SeverityRank(sev) >= 0 {
				rules.MinSeverity = sev
				continue
			}
		case "weight":
			if applyWeightDirective(&rules.Weights, rest) {
				continue
			}
		}
		prose = append(prose, line)
	}
	rules.ExcludeCategories = normalizeStringSet(rules.ExcludeCategories, nil)
	rules.Text = strings.TrimSpace(strings.Join(prose, "\n"))
	return rules
}

func parseCategorySeverity(s string) (category, severity string, ok bool) {
	cat, sev, found := strings.Cut(s, "=")
	if !found {
		return "", "", false
	}
	cat = normalizeCategory(cat)
	sev = normalizeSeverity(sev)
	if !knownCategories[cat] || SeverityRank(sev) < 0 {
		return "", "", false
	}
	return cat, sev, true
}

func parseCategoryList(s string) []string {
	var out []string
	for part := range strings.SplitSeq(s, ",") {
		cat := normalizeCategory(part)
		if knownCategories[cat] {
			out = append(out, cat)
		}
	}
	return out
}

func applyWeightDirective(w *RankWeights, s string) bool {
	applied := false
	for part := range strings.SplitSeq(s, ",") {
		name, val, found := strings.Cut(part, "=")
		if !found {
			continue
		}
		v, err := strconv.ParseFloat(strings.TrimSpace(val), 64)
		if err != nil || v < 0 {
			continue
		}
		switch strings.ToLower(strings.TrimSpace(name)) {
		case "severity":
			w.Severity = v
		case "confidence":
			w.Confidence = v
		case "exploitability":
			w.Exploitability = v
		case "exposure":
			w.Exposure = v
		default:
			continue
		}
		applied = true
	}
	return applied
}

// RankedFinding is a Finding with its priority score and the reasons behind it.
type RankedFinding struct {
	Finding Finding
	Score   float64
	Reasons []string
}

var severityScores = map[string]float64{
	SeverityCritical: 1.0,
	SeverityHigh:     0.8,
	SeverityMedium:   0.55,
	SeverityLow:      0.3,
	SeverityInfo:     0.1,
}

var confidenceScores = map[string]float64{
	ConfidenceConfirmed: 1.0,
	ConfidenceFirm:      0.7,
	ConfidenceTentative: 0.4,
}

var exploitabilityBoosts = []struct {
	keyword string
	boost   float64
}{
	{"unauthenticated", 0.2},
	{"pre-auth", 0.2},
	{"preauth", 0.2},
	{"rce", 0.2},
	{"remote code execution", 0.2},
	{"remote", 0.15},
	{"network", 0.1},
	{"internet", 0.1},
	{"public", 0.1},
}

var exploitabilityDampeners = []struct {
	keyword string
	damp    float64
}{
	{"local", 0.1},
	{"authenticated", 0.1},
	{"physical", 0.15},
}

func exploitability(f Finding) (float64, []string) {
	text := strings.ToLower(f.AttackVector + " " + strings.Join(f.Tags, " "))
	score := 0.4
	var matched []string
	for _, b := range exploitabilityBoosts {
		if strings.Contains(text, b.keyword) {
			score += b.boost
			matched = append(matched, b.keyword)
		}
	}
	for _, d := range exploitabilityDampeners {
		// "unauthenticated" must not trigger the "authenticated" dampener.
		if d.keyword == "authenticated" && strings.Contains(text, "unauthenticated") {
			continue
		}
		if strings.Contains(text, d.keyword) {
			score -= d.damp
		}
	}
	return clamp01(score), matched
}

var highExposureHints = []string{"handler", "api", "controller", "route", "cmd", "server", "endpoint", "public", "auth", "middleware"}
var lowExposureHints = []string{"test", "fixture", "docs", "doc", "example", "examples", "mock", "vendor", "testdata"}

func exposure(f Finding) (float64, string) {
	p := strings.ToLower(f.FilePath)
	if p == "" {
		return 0.5, ""
	}
	segments := strings.FieldsFunc(p, func(r rune) bool { return r == '/' || r == '_' || r == '.' || r == '-' })
	for _, hint := range lowExposureHints {
		for _, seg := range segments {
			if seg == hint || strings.HasSuffix(seg, hint) {
				return 0.2, hint
			}
		}
	}
	for _, hint := range highExposureHints {
		for _, seg := range segments {
			if strings.HasPrefix(seg, hint) {
				return 0.9, hint
			}
		}
	}
	return 0.5, ""
}

func clamp01(v float64) float64 {
	return math.Min(1, math.Max(0, v))
}

// Rank applies the rules (severity floors/ceilings, category excludes,
// minimum severity) and scores each surviving finding from 0 to 100 using
// the weighted combination of severity, confidence, exploitability
// heuristics, and file-path exposure heuristics. Results are sorted by
// score descending, then severity descending, then title ascending.
func Rank(findings []Finding, rules RankRules) []RankedFinding {
	weights := rules.Weights
	if weights == (RankWeights{}) {
		weights = DefaultRankWeights()
	}
	weightSum := weights.Severity + weights.Confidence + weights.Exploitability + weights.Exposure
	if weightSum <= 0 {
		weights = DefaultRankWeights()
		weightSum = weights.Severity + weights.Confidence + weights.Exploitability + weights.Exposure
	}

	excluded := make(map[string]bool, len(rules.ExcludeCategories))
	for _, c := range rules.ExcludeCategories {
		excluded[normalizeCategory(c)] = true
	}

	ranked := make([]RankedFinding, 0, len(findings))
	for _, f := range findings {
		if excluded[f.Category] {
			continue
		}
		var reasons []string
		if floor, ok := rules.SeverityFloors[f.Category]; ok && SeverityRank(f.Severity) >= 0 && SeverityRank(f.Severity) < SeverityRank(floor) {
			reasons = append(reasons, fmt.Sprintf("severity raised from %s to %s by floor for category %s", f.Severity, floor, f.Category))
			f.Severity = floor
		}
		if ceiling, ok := rules.SeverityCeilings[f.Category]; ok && SeverityRank(f.Severity) > SeverityRank(ceiling) && SeverityRank(ceiling) >= 0 {
			reasons = append(reasons, fmt.Sprintf("severity lowered from %s to %s by ceiling for category %s", f.Severity, ceiling, f.Category))
			f.Severity = ceiling
		}
		if rules.MinSeverity != "" && !SeverityAtLeast(f.Severity, rules.MinSeverity) {
			continue
		}

		sevScore := severityScores[f.Severity]
		confScore, ok := confidenceScores[f.Confidence]
		if !ok {
			confScore = confidenceScores[ConfidenceTentative]
		}
		explScore, explHits := exploitability(f)
		expoScore, expoHint := exposure(f)

		score := 100 * (weights.Severity*sevScore + weights.Confidence*confScore +
			weights.Exploitability*explScore + weights.Exposure*expoScore) / weightSum
		score = math.Round(score*10) / 10

		reasons = append(reasons, fmt.Sprintf("severity %s", orUnknown(f.Severity)))
		reasons = append(reasons, fmt.Sprintf("confidence %s", orUnknown(f.Confidence)))
		if len(explHits) > 0 {
			reasons = append(reasons, "exploitability boosted by: "+strings.Join(explHits, ", "))
		}
		switch {
		case expoScore > 0.5:
			reasons = append(reasons, fmt.Sprintf("high exposure: path %q suggests reachable code (%s)", f.FilePath, expoHint))
		case expoScore < 0.5:
			reasons = append(reasons, fmt.Sprintf("low exposure: path %q suggests non-production code (%s)", f.FilePath, expoHint))
		}

		ranked = append(ranked, RankedFinding{Finding: f, Score: score, Reasons: reasons})
	}

	sort.SliceStable(ranked, func(i, j int) bool {
		if ranked[i].Score != ranked[j].Score {
			return ranked[i].Score > ranked[j].Score
		}
		ri, rj := SeverityRank(ranked[i].Finding.Severity), SeverityRank(ranked[j].Finding.Severity)
		if ri != rj {
			return ri > rj
		}
		return ranked[i].Finding.Title < ranked[j].Finding.Title
	})
	return ranked
}

func orUnknown(s string) string {
	if s == "" {
		return "unknown"
	}
	return s
}

package security

import (
	"fmt"
	"strings"
	"time"
)

// Session artifact kinds under which scan reports are stored. Written by the
// agent's submit_security_scan_report tool and read back by the dashboard's
// GetSecurityScanReport RPC.
const (
	ReportArtifactKind = "security_report"
	SARIFArtifactKind  = "security_sarif"
)

// ReportInput carries everything needed to render a scan report.
type ReportInput struct {
	ScanName    string
	Namespace   string
	Repository  string
	Revision    string
	Summary     string
	StartedAt   time.Time
	CompletedAt time.Time
	Ranked      []RankedFinding
}

func reportFindings(in ReportInput) []Finding {
	findings := make([]Finding, 0, len(in.Ranked))
	for _, r := range in.Ranked {
		findings = append(findings, r.Finding)
	}
	return findings
}

// RenderMarkdown renders the scan report as human-readable markdown: header,
// scan metadata, a severity count table, and one section per finding.
func RenderMarkdown(in ReportInput) string {
	var b strings.Builder

	title := strings.TrimSpace(in.ScanName)
	if title == "" {
		title = "Security Scan"
	}
	fmt.Fprintf(&b, "# Security Scan Report: %s\n\n", title)

	meta := [][2]string{
		{"Namespace", in.Namespace},
		{"Repository", in.Repository},
		{"Revision", in.Revision},
	}
	if !in.StartedAt.IsZero() {
		meta = append(meta, [2]string{"Started", in.StartedAt.UTC().Format(time.RFC3339)})
	}
	if !in.CompletedAt.IsZero() {
		meta = append(meta, [2]string{"Completed", in.CompletedAt.UTC().Format(time.RFC3339)})
		if !in.StartedAt.IsZero() && in.CompletedAt.After(in.StartedAt) {
			meta = append(meta, [2]string{"Duration", in.CompletedAt.Sub(in.StartedAt).Round(time.Second).String()})
		}
	}
	for _, kv := range meta {
		if kv[1] != "" {
			fmt.Fprintf(&b, "- **%s:** %s\n", kv[0], kv[1])
		}
	}
	b.WriteString("\n")

	if s := strings.TrimSpace(in.Summary); s != "" {
		b.WriteString(s)
		b.WriteString("\n\n")
	}

	counts := Summarize(reportFindings(in))
	b.WriteString("## Summary\n\n")
	b.WriteString("| Severity | Count |\n| --- | --- |\n")
	for _, sev := range Severities {
		fmt.Fprintf(&b, "| %s | %d |\n", sev, counts[sev])
	}
	fmt.Fprintf(&b, "| **total** | **%d** |\n\n", counts["total"])

	if len(in.Ranked) == 0 {
		b.WriteString("No findings.\n")
		return b.String()
	}

	b.WriteString("## Findings\n\n")
	byFingerprint := make(map[string]Finding, len(in.Ranked))
	for _, r := range in.Ranked {
		byFingerprint[r.Finding.Fingerprint] = r.Finding
	}
	for i, r := range in.Ranked {
		f := r.Finding
		fmt.Fprintf(&b, "### %d. [%s] %s\n\n", i+1, strings.ToUpper(orUnknown(f.Severity)), f.Title)

		fmt.Fprintf(&b, "- **Severity:** %s\n", orUnknown(f.Severity))
		fmt.Fprintf(&b, "- **Confidence:** %s\n", orUnknown(f.Confidence))
		fmt.Fprintf(&b, "- **Category:** %s\n", orUnknown(f.Category))
		fmt.Fprintf(&b, "- **Source:** %s\n", findingSourceLabel(f))
		fmt.Fprintf(&b, "- **Score:** %.1f\n", r.Score)
		if loc := formatLocation(f.FilePath, f.StartLine, f.EndLine); loc != "" {
			fmt.Fprintf(&b, "- **Location:** `%s`\n", loc)
		}
		if f.Symbol != "" {
			fmt.Fprintf(&b, "- **Symbol:** `%s`\n", f.Symbol)
		}
		if len(f.CWE) > 0 {
			fmt.Fprintf(&b, "- **CWE:** %s\n", strings.Join(f.CWE, ", "))
		}
		if len(r.Reasons) > 0 {
			fmt.Fprintf(&b, "- **Ranking reasons:** %s\n", strings.Join(r.Reasons, "; "))
		}
		if len(f.CorrelatedFingerprints) > 0 {
			labels := make([]string, 0, len(f.CorrelatedFingerprints))
			for _, fp := range f.CorrelatedFingerprints {
				if other, ok := byFingerprint[fp]; ok {
					labels = append(labels, fmt.Sprintf("%s (fingerprint %s)", findingSourceLabel(other), fp))
				} else {
					labels = append(labels, fmt.Sprintf("fingerprint %s", fp))
				}
			}
			fmt.Fprintf(&b, "- **Correlated with:** %s\n", strings.Join(labels, "; "))
		}
		b.WriteString("\n")

		if f.Description != "" {
			b.WriteString(f.Description)
			b.WriteString("\n\n")
		}
		if f.Impact != "" {
			fmt.Fprintf(&b, "**Impact:** %s\n\n", f.Impact)
		}
		if f.AttackVector != "" {
			fmt.Fprintf(&b, "**Attack vector:** %s\n\n", f.AttackVector)
		}
		for _, e := range f.Evidence {
			label := formatLocation(e.FilePath, e.StartLine, e.EndLine)
			if label == "" {
				label = "evidence"
			}
			fmt.Fprintf(&b, "**Evidence** (`%s`)", label)
			if e.Note != "" {
				fmt.Fprintf(&b, " — %s", e.Note)
			}
			b.WriteString(":\n\n")
			if e.Snippet != "" {
				fmt.Fprintf(&b, "```\n%s\n```\n\n", e.Snippet)
			}
		}
		if f.Remediation != "" {
			fmt.Fprintf(&b, "**Remediation:** %s\n\n", f.Remediation)
		}
		if len(f.References) > 0 {
			b.WriteString("**References:**\n\n")
			for _, ref := range f.References {
				fmt.Fprintf(&b, "- %s\n", ref)
			}
			b.WriteString("\n")
		}
	}
	return b.String()
}

// findingSourceLabel renders the finding's source attribution: the tool
// name, version, and rule id for scanner findings, the reporting agent for
// agent findings.
func findingSourceLabel(f Finding) string {
	if f.IsScannerFinding() {
		label := "scanner " + orUnknown(f.Tool)
		if f.ToolVersion != "" {
			label += " " + f.ToolVersion
		}
		if f.RuleID != "" {
			label += ", rule " + f.RuleID
		}
		return label
	}
	if f.SourceAgent != "" {
		return "agent " + f.SourceAgent
	}
	return "agent"
}

func formatLocation(filePath string, startLine, endLine int) string {
	if filePath == "" {
		return ""
	}
	switch {
	case startLine > 0 && endLine > startLine:
		return fmt.Sprintf("%s:%d-%d", filePath, startLine, endLine)
	case startLine > 0:
		return fmt.Sprintf("%s:%d", filePath, startLine)
	}
	return filePath
}

package security

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"
)

const sarifToolName = "gratefulagents-security-scan"

type sarifLog struct {
	Schema  string     `json:"$schema"`
	Version string     `json:"version"`
	Runs    []sarifRun `json:"runs"`
}

type sarifRun struct {
	Tool    sarifTool     `json:"tool"`
	Results []sarifResult `json:"results"`
}

type sarifTool struct {
	Driver sarifDriver `json:"driver"`
}

type sarifDriver struct {
	Name           string      `json:"name"`
	Version        string      `json:"version,omitempty"`
	InformationURI string      `json:"informationUri,omitempty"`
	Rules          []sarifRule `json:"rules"`
}

type sarifRule struct {
	ID               string         `json:"id"`
	Name             string         `json:"name,omitempty"`
	ShortDescription sarifMessage   `json:"shortDescription"`
	Properties       sarifRuleProps `json:"properties,omitempty"`
}

type sarifRuleProps struct {
	Tags []string `json:"tags,omitempty"`
}

type sarifMessage struct {
	Text string `json:"text"`
}

type sarifResult struct {
	RuleID              string            `json:"ruleId"`
	RuleIndex           int               `json:"ruleIndex"`
	Level               string            `json:"level"`
	Message             sarifMessage      `json:"message"`
	Locations           []sarifLocation   `json:"locations,omitempty"`
	PartialFingerprints map[string]string `json:"partialFingerprints,omitempty"`
	Properties          map[string]any    `json:"properties,omitempty"`
}

type sarifLocation struct {
	PhysicalLocation sarifPhysicalLocation `json:"physicalLocation"`
}

type sarifPhysicalLocation struct {
	ArtifactLocation sarifArtifactLocation `json:"artifactLocation"`
	Region           *sarifRegion          `json:"region,omitempty"`
}

type sarifArtifactLocation struct {
	URI string `json:"uri"`
}

type sarifRegion struct {
	StartLine int `json:"startLine"`
	EndLine   int `json:"endLine,omitempty"`
}

func sarifLevel(severity string) string {
	switch severity {
	case SeverityCritical, SeverityHigh:
		return "error"
	case SeverityMedium:
		return "warning"
	default:
		return "note"
	}
}

// sarifResultFor renders the finding as a SARIF result under the given rule.
// The result carries the finding fingerprint under
// partialFingerprints["gratefulagentsFindingFingerprint/v1"] and source
// attribution under properties.
func sarifResultFor(r RankedFinding, ruleID string, ruleIndex int) sarifResult {
	f := r.Finding
	fingerprint := f.Fingerprint
	if fingerprint == "" {
		fingerprint = Fingerprint(f)
	}
	msg := strings.TrimSpace(f.Title)
	if msg == "" {
		msg = "(untitled finding)"
	}
	if d := strings.TrimSpace(f.Description); d != "" {
		msg += "\n\n" + d
	}
	res := sarifResult{
		RuleID:    ruleID,
		RuleIndex: ruleIndex,
		Level:     sarifLevel(f.Severity),
		Message:   sarifMessage{Text: msg},
		PartialFingerprints: map[string]string{
			"gratefulagentsFindingFingerprint/v1": fingerprint,
		},
		Properties: map[string]any{
			"severity":   f.Severity,
			"confidence": f.Confidence,
			"score":      r.Score,
		},
	}
	if f.IsScannerFinding() {
		res.Properties["sourceKind"] = SourceKindScanner
		res.Properties["tool"] = f.Tool
		if f.ToolVersion != "" {
			res.Properties["toolVersion"] = f.ToolVersion
		}
		res.Properties["ruleId"] = f.RuleID
	} else {
		res.Properties["sourceKind"] = SourceKindAgent
		if f.SourceAgent != "" {
			res.Properties["sourceAgent"] = f.SourceAgent
		}
	}
	if len(f.CorrelatedFingerprints) > 0 {
		res.Properties["correlatedFingerprints"] = append([]string(nil), f.CorrelatedFingerprints...)
	}
	if len(f.CWE) > 0 {
		res.Properties["cwe"] = append([]string(nil), f.CWE...)
	}
	if f.FilePath != "" {
		loc := sarifLocation{
			PhysicalLocation: sarifPhysicalLocation{
				ArtifactLocation: sarifArtifactLocation{URI: f.FilePath},
			},
		}
		if f.StartLine > 0 {
			region := &sarifRegion{StartLine: f.StartLine}
			if f.EndLine >= f.StartLine {
				region.EndLine = f.EndLine
			}
			loc.PhysicalLocation.Region = region
		}
		res.Locations = []sarifLocation{loc}
	}
	return res
}

// sarifAgentRun renders agent-authored findings as the gratefulagents run.
// Rules are derived from the finding categories (with CWE tags).
func sarifAgentRun(ranked []RankedFinding) sarifRun {
	ruleCWEs := map[string]map[string]bool{}
	for _, r := range ranked {
		cat := r.Finding.Category
		if cat == "" {
			cat = "other"
		}
		if ruleCWEs[cat] == nil {
			ruleCWEs[cat] = map[string]bool{}
		}
		for _, c := range r.Finding.CWE {
			if n := normalizeCWE(c); n != "" {
				ruleCWEs[cat][n] = true
			}
		}
	}
	ruleIDs := make([]string, 0, len(ruleCWEs))
	for id := range ruleCWEs {
		ruleIDs = append(ruleIDs, id)
	}
	sort.Strings(ruleIDs)

	rules := make([]sarifRule, 0, len(ruleIDs))
	ruleIndex := make(map[string]int, len(ruleIDs))
	for i, id := range ruleIDs {
		ruleIndex[id] = i
		tags := []string{"security", id}
		cwes := make([]string, 0, len(ruleCWEs[id]))
		for c := range ruleCWEs[id] {
			cwes = append(cwes, c)
		}
		sort.Strings(cwes)
		tags = append(tags, cwes...)
		rules = append(rules, sarifRule{
			ID:               id,
			Name:             id,
			ShortDescription: sarifMessage{Text: fmt.Sprintf("Security finding category: %s", id)},
			Properties:       sarifRuleProps{Tags: tags},
		})
	}

	results := make([]sarifResult, 0, len(ranked))
	for _, r := range ranked {
		cat := r.Finding.Category
		if cat == "" {
			cat = "other"
		}
		results = append(results, sarifResultFor(r, cat, ruleIndex[cat]))
	}
	return sarifRun{
		Tool:    sarifTool{Driver: sarifDriver{Name: sarifToolName, Rules: rules}},
		Results: results,
	}
}

// sarifScannerRun renders one deterministic tool's findings as that tool's
// own SARIF run: the driver is named after the tool (with its version) and
// the rules are the tool's real rule ids, so gratefulagents never claims to
// have produced another tool's rules.
func sarifScannerRun(tool string, ranked []RankedFinding) sarifRun {
	version := ""
	ruleTitle := map[string]string{}
	ruleTags := map[string]map[string]bool{}
	for _, r := range ranked {
		f := r.Finding
		if version == "" {
			version = f.ToolVersion
		}
		id := f.RuleID
		if _, ok := ruleTitle[id]; !ok {
			ruleTitle[id] = strings.TrimSpace(f.Title)
		}
		if ruleTags[id] == nil {
			ruleTags[id] = map[string]bool{}
		}
		if f.Category != "" {
			ruleTags[id][f.Category] = true
		}
		for _, c := range f.CWE {
			if n := normalizeCWE(c); n != "" {
				ruleTags[id][n] = true
			}
		}
	}
	ruleIDs := make([]string, 0, len(ruleTitle))
	for id := range ruleTitle {
		ruleIDs = append(ruleIDs, id)
	}
	sort.Strings(ruleIDs)

	rules := make([]sarifRule, 0, len(ruleIDs))
	ruleIndex := make(map[string]int, len(ruleIDs))
	for i, id := range ruleIDs {
		ruleIndex[id] = i
		tags := make([]string, 0, len(ruleTags[id])+1)
		tags = append(tags, "security")
		extra := make([]string, 0, len(ruleTags[id]))
		for t := range ruleTags[id] {
			extra = append(extra, t)
		}
		sort.Strings(extra)
		tags = append(tags, extra...)
		desc := ruleTitle[id]
		if desc == "" {
			desc = id
		}
		rules = append(rules, sarifRule{
			ID:               id,
			Name:             id,
			ShortDescription: sarifMessage{Text: desc},
			Properties:       sarifRuleProps{Tags: tags},
		})
	}

	results := make([]sarifResult, 0, len(ranked))
	for _, r := range ranked {
		results = append(results, sarifResultFor(r, r.Finding.RuleID, ruleIndex[r.Finding.RuleID]))
	}
	return sarifRun{
		Tool:    sarifTool{Driver: sarifDriver{Name: tool, Version: version, Rules: rules}},
		Results: results,
	}
}

// RenderSARIF renders the scan report as SARIF 2.1.0 JSON with one run per
// source: agent-authored findings under the gratefulagents driver, and one
// additional run per deterministic scanner tool under that tool's own
// driver name, version, and rule ids. Every result carries the finding
// fingerprint under partialFingerprints["gratefulagentsFindingFingerprint/v1"]
// plus source attribution (and correlated fingerprints) under properties.
func RenderSARIF(in ReportInput) ([]byte, error) {
	agent := make([]RankedFinding, 0, len(in.Ranked))
	scanners := map[string][]RankedFinding{}
	for _, r := range in.Ranked {
		if r.Finding.IsScannerFinding() {
			tool := strings.TrimSpace(r.Finding.Tool)
			if tool == "" {
				tool = "unknown-scanner"
			}
			scanners[tool] = append(scanners[tool], r)
			continue
		}
		agent = append(agent, r)
	}

	// The gratefulagents run always comes first (even when empty, so a
	// scan with no findings still renders one valid run); scanner runs
	// follow in deterministic tool-name order.
	runs := []sarifRun{sarifAgentRun(agent)}
	tools := make([]string, 0, len(scanners))
	for tool := range scanners {
		tools = append(tools, tool)
	}
	sort.Strings(tools)
	for _, tool := range tools {
		runs = append(runs, sarifScannerRun(tool, scanners[tool]))
	}

	log := sarifLog{
		Schema:  "https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json",
		Version: "2.1.0",
		Runs:    runs,
	}
	return json.MarshalIndent(log, "", "  ")
}

package security

import (
	"fmt"
	"strings"
)

// FindingJSONSchema is a JSON Schema (draft-07) describing a single Finding
// as emitted by a scanning agent, matching the Finding json tags.
const FindingJSONSchema = `{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "SecurityFinding",
  "description": "A single security finding produced by a scanning agent.",
  "type": "object",
  "additionalProperties": false,
  "required": ["title", "category", "severity", "description"],
  "properties": {
    "title": {
      "type": "string",
      "minLength": 1,
      "maxLength": 300,
      "description": "Short, specific summary of the issue."
    },
    "category": {
      "type": "string",
      "enum": ["injection", "authn", "authz", "secrets", "crypto", "ssrf", "xss", "deserialization", "path-traversal", "race-condition", "dos", "memory-safety", "supply-chain", "misconfiguration", "logic-flaw", "info-leak", "other"],
      "description": "Curated vulnerability category."
    },
    "severity": {
      "type": "string",
      "enum": ["critical", "high", "medium", "low", "info"],
      "description": "Impact severity of the issue."
    },
