package securitytoolpacks

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"maps"
	"net/url"
	"runtime"
	"slices"
	"strings"

	"github.com/gratefulagents/gratefulagents/internal/security"
)

var workflowStages = []string{
	"target_classification", "applicability_detection", "registry_selection",
	"sandboxed_execution", "raw_artifact_collection", "normalization_and_evidence_validation",
	"safe_replay_or_corroboration", "deduplication_and_reporting", "coverage_failure_summary",
}

type ExecutionRequest struct {
	Invocation Invocation
	Tool       Tool
	Config     RunConfig
}
type NativeResult struct {
	Output                       []byte
	Artifacts                    []Artifact
	ExitCode                     int
	TimedOut                     bool
	Environment                  map[string]string
	Examined, Skipped, Uncovered []string
	// Bounded is the scope an executor knows and the adapter cannot see:
	// campaign length, corpus provenance, harness identity. A bounded clean
	// run is only honest if it says what bounded it.
	Bounded *BoundedScope
	Err     error
}
type Sandbox interface {
	Execute(context.Context, ExecutionRequest) NativeResult
}
type Adapter interface {
	Normalize(tool Tool, target Target, native []byte, redactor Redactor) ([]securityRecord, error)
}

// securityRecord is an adapter record plus its asset identifier. The alias-like
// wrapper keeps adapters independent from persistence while ToScannerRecord
// still feeds the established scanner finding pipeline.
type securityRecord struct {
	Record    ScannerRecord
	Asset     string
	Examined  bool
	Skipped   bool
	Uncovered bool
}

// local aliases keep adapter signatures readable.
type ScannerRecord = struct {
	Tool        string            `json:"tool"`
	ToolVersion string            `json:"tool_version,omitempty"`
	RuleID      string            `json:"rule_id"`
	RuleName    string            `json:"rule_name,omitempty"`
	Message     string            `json:"message"`
	Severity    string            `json:"severity"`
	Category    string            `json:"category,omitempty"`
	FilePath    string            `json:"file_path"`
	StartLine   int               `json:"start_line,omitempty"`
	EndLine     int               `json:"end_line,omitempty"`
	Symbol      string            `json:"symbol,omitempty"`
	CWE         string            `json:"cwe,omitempty"`
	References  []string          `json:"references,omitempty"`
	RawEvidence string            `json:"raw_evidence,omitempty"`
	Extra       map[string]string `json:"extra,omitempty"`
}

// Runner enforces registry selection and resource metadata before delegating
// to a sandbox. Retry is intentionally left to the controller; callers may
// retry only when Tool.Idempotent or Tool.Resettable is true.
type Runner struct {
	registry *Registry
	sandbox  Sandbox
	adapters map[string]Adapter
}

func NewRunner(registry *Registry, sandbox Sandbox) *Runner {
	return &Runner{registry: registry, sandbox: sandbox, adapters: DefaultAdapters()}
}
func (r *Runner) WithAdapter(name string, adapter Adapter) *Runner {
	r.adapters[name] = adapter
	return r
}

func (r *Runner) Run(ctx context.Context, cfg RunConfig) Result {
	cfg = cloneRunConfig(cfg)
	res := Result{Stages: append([]string(nil), workflowStages...)}
	inv, tool, err := r.registry.BuildInvocation(cfg)
	if err != nil {
		var applicability *ApplicabilityError
		if errors.As(err, &applicability) {
			res.Status = StatusNotApplicable
		} else {
			res.Status = StatusError
		}
		res.Errors = []string{NewRedactor(cfg.Sensitive...).Text(err.Error())}
		return res
	}
	cfgJSON, err := canonicalJSON(cfg)
	if err != nil {
		res.Status = StatusError
		res.Errors = []string{err.Error()}
		return res
	}
	publicCfg := redactedRunConfig(cfg)
	publicJSON, _ := canonicalJSON(publicCfg)
	res.Replay = Replay{Target: publicCfg.Target, Tool: tool.Name, ToolVersion: tool.Version, ImageDigest: tool.ImageDigest, ToolArtifactDigest: tool.ToolArtifactDigest, WrapperDigest: tool.WrapperDigest, PlatformDigest: tool.PlatformDigests[runtime.GOARCH], Knowledge: cloneStringMap(tool.KnowledgeDigests), Configuration: publicJSON, ConfigurationID: sha256Digest(cfgJSON), Seed: cloneInt64(cfg.Seed), InputDigests: []string{cfg.Target.Digest}}
	if r.sandbox == nil {
		res.Status = StatusError
		res.Errors = []string{"no sandbox executor configured"}
		return res
	}
	native := r.sandbox.Execute(ctx, ExecutionRequest{Invocation: inv, Tool: cloneTool(tool), Config: cloneRunConfig(cfg)})
	res.Coverage = Coverage{Examined: sortedUnique(native.Examined), Skipped: sortedUnique(native.Skipped), Uncovered: sortedUnique(native.Uncovered)}
	if native.Bounded != nil {
		bounded := *native.Bounded
		res.Bounded = &bounded
	}
	res.Replay.Environment = stableEnvironment(native.Environment)
	res.Replay.SandboxDigest = native.Environment["sandbox_digest"]
	redactor := NewRedactor(cfg.Sensitive...)
	if int64(len(native.Output)) > tool.Budgets.MaxOutputSize {
		native.Err = fmt.Errorf("native output exceeds %d-byte budget", tool.Budgets.MaxOutputSize)
	}
	if len(native.Output) > 0 {
		res.Artifacts = []Artifact{{Name: "raw-output", MediaType: tool.OutputMediaType, Digest: sha256Digest(native.Output), Size: len(native.Output), Data: append([]byte(nil), native.Output...)}}
	}
	for _, artifact := range native.Artifacts {
		artifact.Data = append([]byte(nil), artifact.Data...)
		res.Artifacts = append(res.Artifacts, artifact)
	}
	if native.TimedOut || errors.Is(native.Err, context.DeadlineExceeded) {
		res.Status = StatusTimeout
		if native.Err != nil {
			res.Errors = []string{redactor.Text(native.Err.Error())}
		}
		return res
	}
	err = r.normalizeNative(tool, cfg.Target, native.Output, redactor, &res)
	stableRecords(res.Findings)
	if native.Err != nil {
		res.Errors = append(res.Errors, redactor.Text(native.Err.Error()))
	}
	finalizeStatus(&res, tool, cfg.Target, native, err)
	return res
}

func (r *Runner) normalizeNative(tool Tool, target Target, output []byte, redactor Redactor, res *Result) error {
	adapter, ok := r.adapters[tool.Adapter]
	if !ok {
		res.Errors = append(res.Errors, "normalization adapter not registered: "+tool.Adapter)
		return fmt.Errorf("adapter %s is not registered", tool.Adapter)
	}
	var adapted []securityRecord
	var err error
	// Empty line-oriented scanner output can be a valid clean result (for
	// example, nuclei found nothing). Structured report formats such as JUnit
	// must still be parsed: an empty file means the runner failed to produce
	// evidence, not that every test passed.
	if len(output) > 0 || tool.Adapter == "junit" {
		adapted, err = adapter.Normalize(cloneTool(tool), target, output, redactor)
	}
	if err != nil {
		res.Errors = append(res.Errors, "normalize: "+redactor.Text(err.Error()))
	}
	artifactDigest := ""
	if len(res.Artifacts) > 0 {
		artifactDigest = res.Artifacts[0].Digest
	}
	for _, item := range adapted {
		if item.Examined {
			res.Coverage.Examined = sortedUnique(append(res.Coverage.Examined, item.Asset))
			continue
		}
		if item.Skipped {
			res.Coverage.Skipped = sortedUnique(append(res.Coverage.Skipped, item.Asset))
			continue
		}
		if item.Uncovered {
			res.Coverage.Uncovered = sortedUnique(append(res.Coverage.Uncovered, item.Asset))
			continue
		}
		record := toPipelineRecord(item.Record)
		if record.Extra == nil {
			record.Extra = map[string]string{}
		}
		record.Extra["raw_artifact_digest"] = artifactDigest
		res.Findings = append(res.Findings, record)
	}
	return err
}

func finalizeStatus(res *Result, tool Tool, target Target, native NativeResult, normalizationErr error) {
	mapped, known := tool.ExitCodes[native.ExitCode]
	if known && mapped == StatusTimeout {
		res.Status = StatusTimeout
		return
	}
	inconsistent := known && mapped == StatusFindings && len(res.Findings) == 0
	if inconsistent {
		res.Errors = append(res.Errors, "exit code indicated findings but normalization produced none")
	}
	if known && isCleanExit(mapped) && len(res.Coverage.Examined) == 0 && len(res.Coverage.Skipped) == 0 && len(res.Coverage.Uncovered) == 0 {
		res.Coverage.Uncovered = []string{target.Locator}
	}
	hasFindings := len(res.Findings) > 0
	if !known {
		res.Errors = append(res.Errors, fmt.Sprintf("unmapped exit code %d", native.ExitCode))
		res.Status = statusForFailedRun(hasFindings)
		return
	}
	if mapped == StatusError || native.Err != nil || normalizationErr != nil || inconsistent {
		res.Status = statusForFailedRun(hasFindings)
		return
	}
	if len(res.Coverage.Skipped) > 0 || len(res.Coverage.Uncovered) > 0 || len(res.Errors) > 0 {
		res.Status = StatusPartial
		return
	}
	if hasFindings {
		res.Status = StatusFindings
		return
	}
	if isCleanExit(mapped) && len(res.Coverage.Examined) > 0 {
		// A clean run is a bounded negative result, never a statement that
		// the target is safe: it says only that this harness, over this
		// coverage, found nothing.
		res.Status = StatusNotFoundUnder
		if res.Bounded == nil {
			res.Bounded = &BoundedScope{}
		}
		if res.Bounded.Coverage == "" {
			res.Bounded.Coverage = summarizeCoverage(res.Coverage.Examined)
		}
		if res.Bounded.Environment == "" {
			res.Bounded.Environment = tool.Name + " " + tool.Version
		}
		if res.Bounded.Bounds == "" && res.Replay.Seed != nil {
			res.Bounded.Bounds = fmt.Sprintf("seed=%d", *res.Replay.Seed)
		}
		return
	}
	res.Status = StatusError
	res.Errors = append(res.Errors, "execution did not satisfy the bounded-negative criteria")
}

// summarizeCoverage renders what a bounded negative result covered without
// growing with the target: a suite with hundreds of assets would otherwise
// produce a coverage string the API server rejects, and a rejected status
// update loses the whole run.
func summarizeCoverage(examined []string) string {
	if len(examined) == 0 {
		return ""
	}
	var b strings.Builder
	shown := 0
	for _, asset := range examined {
		next := asset
		if shown > 0 {
			next = ", " + asset
		}
		if b.Len()+len(next) > maxCoverageSummaryBytes {
			break
		}
		b.WriteString(next)
		shown++
	}
	if shown == len(examined) {
		return fmt.Sprintf("%d examined: %s", len(examined), b.String())
	}
	if shown == 0 {
		return fmt.Sprintf("%d examined", len(examined))
	}
	return fmt.Sprintf("%d examined, first %d: %s", len(examined), shown, b.String())
}

// isCleanExit reports whether a mapped exit code means the tool ran to
// completion without reporting findings. The retired "pass" verdict is still
// honoured here because registered packs map exit code 0 to it.
func isCleanExit(status Status) bool {
	return status == StatusPass || status == StatusNotFoundUnder
}

func statusForFailedRun(hasFindings bool) Status {
	if hasFindings {
		return StatusPartial
	}
	return StatusError
}

func toPipelineRecord(r ScannerRecord) security.ScannerRecord {
	return security.ScannerRecord{Tool: r.Tool, ToolVersion: r.ToolVersion, RuleID: r.RuleID, RuleName: r.RuleName, Message: r.Message, Severity: r.Severity, Category: r.Category, FilePath: r.FilePath, StartLine: r.StartLine, EndLine: r.EndLine, Symbol: r.Symbol, CWE: r.CWE, References: append([]string(nil), r.References...), RawEvidence: r.RawEvidence, Extra: cloneStringMap(r.Extra)}
}

func cloneRunConfig(in RunConfig) RunConfig {
	out := in
	out.Arguments = cloneStringMap(in.Arguments)
	out.Scope = append([]string(nil), in.Scope...)
	out.Sensitive = append([]string(nil), in.Sensitive...)
	out.Seed = cloneInt64(in.Seed)
	return out
}

func cloneStringMap(in map[string]string) map[string]string {
	if in == nil {
		return nil
	}
	out := make(map[string]string, len(in))
	maps.Copy(out, in)
	return out
}

func cloneInt64(in *int64) *int64 {
	if in == nil {
		return nil
	}
	out := *in
	return &out
}

func sortedUnique(in []string) []string {
	m := map[string]bool{}
	for _, v := range in {
		if strings.TrimSpace(v) != "" {
			m[v] = true
		}
	}
	out := make([]string, 0, len(m))
	for v := range m {
		out = append(out, v)
	}
	slices.Sort(out)
	return out
}
func stableEnvironment(in map[string]string) map[string]string {
	out := map[string]string{}
	for _, k := range []string{"os", "arch", "kernel", "runtime", "compiler", "build", "assembly_digest"} {
		if v := in[k]; v != "" {
			out[k] = v
		}
	}
	return out
}

func redactedRunConfig(in RunConfig) RunConfig {
	out := cloneRunConfig(in)
	out.Arguments = make(map[string]string, len(in.Arguments))
	sensitive := map[string]bool{"authorization": true, "cookie": true, "token": true, "password": true, "secret": true, "private_key": true}
	for _, name := range in.Sensitive {
		sensitive[strings.ToLower(name)] = true
	}
	redactor := NewRedactor(in.Sensitive...)
	for k, v := range in.Arguments {
		if sensitive[strings.ToLower(k)] {
			out.Arguments[k] = "secret-ref:" + sha256Digest([]byte(v))
			continue
		}
		out.Arguments[k] = redactor.Text(v)
	}
	out.Target.Locator = redactedLocator(out.Target.Locator, redactor)
	for i := range out.Scope {
		out.Scope[i] = redactedLocator(out.Scope[i], redactor)
	}
	return out
}

func redactedLocator(locator string, redactor Redactor) string {
	locator = redactor.Text(locator)
	if u, err := url.Parse(locator); err == nil && u.IsAbs() {
		u.User = nil
		u.RawQuery = ""
		u.Fragment = ""
		return u.String()
	}
	return locator
}

// MarshalCanonical removes raw-artifact identity and bytes in addition to
// timestamps. Equivalent normalized outputs therefore compare independently
// of volatile native evidence while Replay still retains its protected digest.
func MarshalCanonical(result Result) ([]byte, error) {
	encoded, err := json.Marshal(result)
	if err != nil {
		return nil, err
	}
	var clone Result
	if err := json.Unmarshal(encoded, &clone); err != nil {
		return nil, err
	}
	result = clone
	result.Artifacts = nil
	for i := range result.Findings {
		if result.Findings[i].Extra == nil {
			continue
		}
		extra := make(map[string]string, len(result.Findings[i].Extra))
		for k, v := range result.Findings[i].Extra {
			if k != "raw_artifact_digest" {
				extra[k] = v
			}
		}
		result.Findings[i].Extra = extra
	}
	return json.Marshal(result)
}

package securitytoolpacks

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"syscall"
	"time"

	"github.com/gratefulagents/gratefulagents/internal/security"
	"github.com/pelletier/go-toml/v2"
)

// Rust is the largest client and program surface we can name as in scope —
// reth, lighthouse, zksync-era, the Solana programs — and until this pack it
// had no executable path at all.
//
// Two decisions define it:
//
//   - it runs the project's OWN fuzz/fuzz_targets. A harness we wrote would be
//     a model-authored artifact in the accept path, which is exactly what this
//     epic keeps out of it; the maintainers' targets are the ones their CI and
//     their reviewers already trust.
//   - the verdict is not parsed from libFuzzer's console output. The executor
//     synthesizes a record from what the run left on disk: the crash inputs in
//     fuzz/artifacts. A crash file is a reproducible input; a stderr banner is
//     a string that changes between releases.
const (
	maxRustCrashArtifacts   = 32
	maxRustCrashBytes       = 1 << 20
	maxRustCorpusArtifacts  = 64
	maxRustTotalArtifacts   = 64
	maxRustCorpusBytes      = 1 << 20
	maxRustCorpusEntryBytes = 64 << 10
	// rustFuzzArtifactDir is where cargo-fuzz writes crashing inputs.
	rustFuzzArtifactDir = "artifacts"
	rustFuzzDirName     = "fuzz"
)

// RustFuzzCampaignMetadataPath is reserved for control-plane-authored corpus
// provenance. Repositories may not supply this file themselves.
const RustFuzzCampaignMetadataPath = ".gratefulagents/rust-fuzz-campaign.json"

const rustFuzzCampaignMetadataVersion = "v1"

type rustFuzzCampaignMetadata struct {
	SchemaVersion  string `json:"schema_version"`
	RestoredInputs int    `json:"restored_inputs"`
}

func EncodeRustFuzzCampaignMetadata(restoredInputs int) ([]byte, error) {
	if restoredInputs < 0 {
		return nil, fmt.Errorf("restored input count must not be negative")
	}
	return json.Marshal(rustFuzzCampaignMetadata{SchemaVersion: rustFuzzCampaignMetadataVersion, RestoredInputs: restoredInputs})
}

func readRustFuzzCampaignMetadata(root string) (int, error) {
	raw, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(RustFuzzCampaignMetadataPath)))
	if os.IsNotExist(err) {
		return 0, nil
	}
	if err != nil {
		return 0, err
	}
	var metadata rustFuzzCampaignMetadata
	if err := json.Unmarshal(raw, &metadata); err != nil {
		return 0, fmt.Errorf("decode Rust fuzz campaign metadata: %w", err)
	}
	if metadata.SchemaVersion != rustFuzzCampaignMetadataVersion || metadata.RestoredInputs < 0 {
		return 0, fmt.Errorf("invalid Rust fuzz campaign metadata")
	}
	return metadata.RestoredInputs, nil
}

var rustFuzzTargetPattern = regexp.MustCompile(`^[a-z0-9][a-z0-9_-]{0,63}$`)

// The cargo-fuzz root is derived rather than pulled: the base image supplies
// the toolchain, and the build adds a dated nightly plus a pinned cargo-fuzz.
// Recording only the base digest would let two materially different fuzz
// executors claim the same identity in replay metadata, so the closure — base
// image, nightly date, cargo-fuzz version — is what gets hashed, and the image
// build writes the same value into the root's provenance marker.
const (
	rustFuzzBaseImageDigest = "sha256:c1e5f19e773b7878c3f7a805dd00a495e747acbdc76fb2337a4ebf0418896b33"
	rustFuzzNightly         = "nightly-2026-06-01"
	rustFuzzVersion         = "0.13.2"

	rustFuzzToolVersion = rustFuzzVersion + "+" + rustFuzzNightly

	// rustFuzzCrashExitCode is passed to libFuzzer explicitly rather than
	// relying on its default, so the exit-code contract in the registry and
	// the value the fuzzer actually uses cannot drift apart.
	rustFuzzCrashExitCode = "77"
)

// RustFuzzClosureIdentity is the exact string the image build hashes into the
// cargo-fuzz root's provenance marker.
func RustFuzzClosureIdentity() string {
	return "docker.io/library/rust@" + rustFuzzBaseImageDigest + "+rustup:" + rustFuzzNightly + "+cargo-fuzz:" + rustFuzzVersion
}

// RustFuzzClosureDigest is the identity of the whole derived executor.
func RustFuzzClosureDigest() string {
	return sha256Digest([]byte(RustFuzzClosureIdentity()))
}

// rustFuzzCrash is one crashing input the campaign produced.
type rustFuzzCrash struct {
	// Name is the artifact file name cargo-fuzz assigned, e.g.
	// crash-<sha1>. It is the argument that replays the crash.
	Name   string `json:"name"`
	Digest string `json:"digest"`
	Size   int    `json:"size"`
}

// rustFuzzReport is the executor-built record the adapter consumes. It states
// what ran, for how long, and what it produced, so a clean result carries its
// own bounds instead of implying safety.
type rustFuzzReport struct {
	FuzzTarget       string          `json:"fuzz_target"`
	MaxTotalTime     string          `json:"max_total_time"`
	Seed             string          `json:"seed,omitempty"`
	ExitCode         int             `json:"exit_code"`
	Crashes          []rustFuzzCrash `json:"crashes"`
	ReplayCommand    string          `json:"replay_command"`
	Workers          int             `json:"workers"`
	TraceCompares    bool            `json:"trace_compares"`
	HarnessDigest    string          `json:"harness_digest,omitempty"`
	ManifestDigest   string          `json:"manifest_digest,omitempty"`
	WallTime         string          `json:"wall_time,omitempty"`
	CorpusInputs     int             `json:"corpus_inputs"`
	CorpusRestored   int             `json:"corpus_restored"`
	CorpusOutputs    int             `json:"corpus_outputs"`
	CorpusNew        int             `json:"corpus_new"`
	CorpusRetained   int             `json:"corpus_retained"`
	CorpusProvenance string          `json:"corpus_provenance"`
	CorpusError      string          `json:"corpus_error,omitempty"`
	// ConsoleTail is a bounded tail of what the fuzzer printed. It is
	// evidence for a human, never the thing the verdict is derived from.
	ConsoleTail string `json:"console_tail,omitempty"`
}

// validateRustFuzzArguments keeps the target selection a single upstream fuzz
// target name rather than a flag payload.
func validateRustFuzzArguments(cfg RunConfig) error {
	if !rustFuzzTargetPattern.MatchString(cfg.Arguments["fuzz_target"]) {
		return fmt.Errorf("argument %q must name exactly one cargo-fuzz target", "fuzz_target")
	}
	if _, err := ParseFuzzCampaign(cfg.Arguments["max_total_time"]); err != nil {
		return fmt.Errorf("argument %q must be a campaign length between %s and %s", "max_total_time", minFuzzCampaign, maxFuzzCampaign)
	}
	workers, err := strconv.Atoi(cfg.Arguments["workers"])
	if err != nil || workers < 1 || workers > 2 {
		return fmt.Errorf("argument %q must be between 1 and 2", "workers")
	}
	if _, _, err := rustFuzzHarnessPath(cfg.Target.Locator, cfg.Arguments["fuzz_target"]); err != nil {
		return err
	}
	return nil
}

// rustFuzzHarnessPath resolves the selected Cargo bin instead of assuming its
// source file has the same name. cargo-fuzz permits an explicit [[bin]] path;
// whichever form is used must remain inside the staged fuzz project.
func rustFuzzHarnessPath(root, target string) (string, string, error) {
	fuzzDir := filepath.Join(root, rustFuzzDirName)
	manifestPath := filepath.Join(fuzzDir, "Cargo.toml")
	manifestInfo, err := os.Lstat(manifestPath)
	if err != nil || !manifestInfo.Mode().IsRegular() {
		return "", "", fmt.Errorf("fuzz/Cargo.toml must be a regular, non-symlink file")
	}
	raw, err := os.ReadFile(manifestPath)
	if err != nil {
		return "", "", fmt.Errorf("read fuzz/Cargo.toml: %w", err)
	}
	if len(raw) > 1<<20 {
		return "", "", fmt.Errorf("fuzz/Cargo.toml exceeds the 1 MiB validation limit")
	}
	var manifest struct {
		Bins []struct {
			Name string `toml:"name"`
			Path string `toml:"path"`
		} `toml:"bin"`
	}
	if err := toml.Unmarshal(raw, &manifest); err != nil {
		return "", "", fmt.Errorf("parse fuzz/Cargo.toml: %w", err)
	}
	matches := 0
	for _, candidate := range manifest.Bins {
		if candidate.Name == target {
			matches++
		}
	}
	if matches != 1 {
		return "", "", fmt.Errorf("cargo-fuzz target %q must be declared exactly once", target)
	}
	for _, candidate := range manifest.Bins {
		if candidate.Name != target {
			continue
		}
		relative := candidate.Path
		if relative == "" {
			return "", "", fmt.Errorf("cargo-fuzz target %q must declare an explicit harness path", target)
		}
		harness := filepath.Clean(filepath.Join(fuzzDir, filepath.FromSlash(relative)))
		rel, relErr := filepath.Rel(fuzzDir, harness)
		if relErr != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) || filepath.IsAbs(relative) {
			return "", "", fmt.Errorf("cargo-fuzz target %q resolves outside fuzz/", target)
		}
		resolved, resolveErr := filepath.EvalSymlinks(harness)
		resolvedRel, resolvedRelErr := filepath.Rel(fuzzDir, resolved)
		if resolveErr != nil || resolvedRelErr != nil || resolvedRel == ".." || strings.HasPrefix(resolvedRel, ".."+string(filepath.Separator)) {
			return "", "", fmt.Errorf("cargo-fuzz target %q harness escapes fuzz/ through a symlink", target)
		}
		info, statErr := os.Stat(resolved)
		if statErr != nil || !info.Mode().IsRegular() {
			return "", "", fmt.Errorf("cargo-fuzz target %q has no regular harness at %s", target, filepath.ToSlash(relative))
		}
		return resolved, manifestPath, nil
	}
	return "", "", fmt.Errorf("cargo-fuzz target %q is not declared as a fuzz/Cargo.toml [[bin]]", target)
}

func rustFuzzWorkers(cfg RunConfig) int {
	workers, _ := strconv.Atoi(cfg.Arguments["workers"])
	if workers < 1 {
		return 1
	}
	return workers
}

// rustFuzzCrashPaths lists the crash inputs for one target. cargo-fuzz keeps
// them under <project>/fuzz/artifacts/<target>/.
func rustFuzzCrashPaths(root, target string) ([]string, error) {
	directory := filepath.Join(root, rustFuzzDirName, rustFuzzArtifactDir, target)
	entries, err := os.ReadDir(directory)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	paths := make([]string, 0, len(entries))
	for _, entry := range entries {
		if strings.HasPrefix(entry.Name(), ".") {
			continue
		}
		info, infoErr := entry.Info()
		if infoErr != nil {
			return nil, infoErr
		}
		if !info.Mode().IsRegular() {
			return nil, fmt.Errorf("cargo-fuzz crash artifact %q is not a regular file", entry.Name())
		}
		paths = append(paths, filepath.Join(directory, entry.Name()))
	}
	sort.Strings(paths)
	return paths, nil
}

// collectRustFuzzRun turns what the campaign left on disk into the report and
// the reproducible artifacts. Only inputs that did not exist before the run are
// this campaign's, so a corpus carried in from an earlier one is never
// re-reported as a fresh crash.
func collectRustFuzzRun(root string, baseline map[string]bool, cfg RunConfig, exitCode int, console []byte) (rustFuzzReport, []Artifact, error) {
	target := cfg.Arguments["fuzz_target"]
	campaign, _ := ParseFuzzCampaign(cfg.Arguments["max_total_time"])
	report := rustFuzzReport{
		FuzzTarget: target, MaxTotalTime: campaign.String(), ExitCode: exitCode,
		Workers: rustFuzzWorkers(cfg), TraceCompares: true,
		ReplayCommand: fmt.Sprintf("cargo +%s fuzz run %s fuzz/artifacts/%s/<crash-input>", rustFuzzNightly, target, target),
		ConsoleTail:   boundedConsoleTail(console),
	}
	harnessPath, manifestPath, pathErr := rustFuzzHarnessPath(root, target)
	if pathErr != nil {
		return report, nil, pathErr
	}
	if data, err := os.ReadFile(harnessPath); err == nil {
		report.HarnessDigest = sha256Digest(data)
	}
	if data, err := os.ReadFile(manifestPath); err == nil {
		report.ManifestDigest = sha256Digest(data)
	}
	if cfg.Seed != nil {
		report.Seed = fmt.Sprintf("%d", *cfg.Seed)
	}
	paths, err := rustFuzzCrashPaths(root, target)
	if err != nil {
		return report, nil, err
	}
	artifacts := make([]Artifact, 0, len(paths))
	total := 0
	for _, path := range paths {
		if baseline[path] {
			continue
		}
		if len(artifacts) >= maxRustCrashArtifacts {
			return report, nil, fmt.Errorf("more than %d new cargo-fuzz crash artifacts", maxRustCrashArtifacts)
		}
		remaining := maxRustCrashBytes - total
		data, readErr := readRustFuzzRegularFile(filepath.Dir(path), filepath.Base(path), remaining)
		if readErr != nil {
			return report, nil, readErr
		}
		total += len(data)
		name := filepath.Base(path)
		report.Crashes = append(report.Crashes, rustFuzzCrash{Name: name, Digest: sha256Digest(data), Size: len(data)})
		artifacts = append(artifacts, Artifact{
			Name: "cargo-fuzz-crash/" + name, MediaType: "application/octet-stream",
			Digest: sha256Digest(data), Size: len(data), Data: data,
		})
	}
	return report, artifacts, nil
}

// boundedConsoleTail keeps the last few kilobytes of fuzzer output as human
// evidence without letting a chatty run blow the result document.
func boundedConsoleTail(console []byte) string {
	const maxTail = 4 << 10
	if len(console) <= maxTail {
		return strings.TrimSpace(string(console))
	}
	return "…" + strings.TrimSpace(string(console[len(console)-maxTail:]))
}

func readRustFuzzRegularFile(directory, name string, limit int) ([]byte, error) {
	if limit < 0 {
		return nil, fmt.Errorf("artifact byte budget exhausted")
	}
	root, err := os.OpenRoot(directory)
	if err != nil {
		return nil, err
	}
	defer func() { _ = root.Close() }()
	file, err := root.OpenFile(name, os.O_RDONLY|syscall.O_NONBLOCK|syscall.O_NOFOLLOW, 0)
	if err != nil {
		return nil, err
	}
	defer func() { _ = file.Close() }()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() || info.Size() < 0 || info.Size() > int64(limit) {
		return nil, fmt.Errorf("artifact %q is not a bounded regular file", name)
	}
	data, err := io.ReadAll(io.LimitReader(file, int64(limit)+1))
	if err != nil {
		return nil, err
	}
	if len(data) > limit {
		return nil, fmt.Errorf("artifact %q exceeds its byte budget", name)
	}
	return data, nil
}

func rustFuzzCorpusPaths(root, target string) (map[string]bool, error) {
	directory := filepath.Join(root, rustFuzzDirName, "corpus", target)
	entries, err := os.ReadDir(directory)
	if os.IsNotExist(err) {
		return map[string]bool{}, nil
	}
	if err != nil {
		return nil, err
	}
	paths := make(map[string]bool, len(entries))
	for _, entry := range entries {
		info, infoErr := entry.Info()
		if infoErr != nil {
			return nil, infoErr
		}
		if !info.Mode().IsRegular() {
			return nil, fmt.Errorf("cargo-fuzz corpus entry %q is not a regular file", entry.Name())
		}
		paths[filepath.Join(directory, entry.Name())] = true
	}
	return paths, nil
}

func collectRustFuzzCorpus(root, target string, baseline map[string]bool) ([]Artifact, map[string]bool, int, error) {
	after, err := rustFuzzCorpusPaths(root, target)
	if err != nil {
		return nil, nil, 0, err
	}
	paths := make([]string, 0, len(after))
	for path := range after {
		if !baseline[path] {
			paths = append(paths, path)
		}
	}
	sort.Strings(paths)
	discovered := len(paths)
	artifacts := make([]Artifact, 0, min(len(paths), maxRustCorpusArtifacts))
	total := 0
	for _, path := range paths {
		if len(artifacts) >= maxRustCorpusArtifacts {
			break
		}
		remaining := min(maxRustCorpusEntryBytes, maxRustCorpusBytes-total)
		if remaining <= 0 {
			break
		}
		data, readErr := readRustFuzzRegularFile(filepath.Dir(path), filepath.Base(path), remaining)
		if readErr != nil {
			// Oversized generated inputs are not evidence failures. They are
			// simply ineligible for the bounded durable corpus.
			continue
		}
		total += len(data)
		digest := sha256Digest(data)
		name := strings.TrimPrefix(digest, "sha256:")[:32]
		artifacts = append(artifacts, Artifact{Name: "cargo-fuzz-corpus/" + name, MediaType: "application/octet-stream", Digest: digest, Size: len(data), Data: data})
	}
	return artifacts, after, discovered, nil
}

type rustFuzzAdapter struct{}

// Normalize reports one finding per crashing input. The crash file is the
// evidence and the replay command is recorded with it, so the reader never has
// to trust a console banner.
func (rustFuzzAdapter) Normalize(tool Tool, target Target, native []byte, r Redactor) ([]securityRecord, error) {
	var report rustFuzzReport
	if err := json.Unmarshal(native, &report); err != nil {
		return nil, fmt.Errorf("cargo-fuzz report: %w", err)
	}
	if report.FuzzTarget == "" {
		return nil, fmt.Errorf("cargo-fuzz report names no fuzz target")
	}
	asset := target.Locator + ":" + report.FuzzTarget
	if len(report.Crashes) == 0 {
		return []securityRecord{{Asset: asset, Examined: true}}, nil
	}
	out := make([]securityRecord, 0, len(report.Crashes))
	for _, crash := range report.Crashes {
		message := fmt.Sprintf("cargo-fuzz target %s crashed on input %s (%d bytes) within %s", report.FuzzTarget, crash.Name, crash.Size, report.MaxTotalTime)
		evidence := message + "\nreplay: " + strings.Replace(report.ReplayCommand, "<crash-input>", crash.Name, 1)
		if report.ConsoleTail != "" {
			evidence += "\n" + report.ConsoleTail
		}
		out = append(out, securityRecord{Asset: asset, Record: fromPipelineRecord(security.ScannerRecord{
			Tool: tool.Name, ToolVersion: tool.Version, RuleID: "cargo-fuzz-crash", RuleName: "Rust fuzz target crashed",
			Message: r.Text(message), Severity: "high", Category: "fuzzing", FilePath: target.Locator, Symbol: report.FuzzTarget,
			RawEvidence: r.Text(evidence),
			Extra: map[string]string{
				"crash_input": crash.Name, "crash_digest": crash.Digest, "max_total_time": report.MaxTotalTime,
				"seed": report.Seed, "workers": strconv.Itoa(report.Workers), "trace_compares": strconv.FormatBool(report.TraceCompares),
				"harness_digest": report.HarnessDigest, "manifest_digest": report.ManifestDigest, "wall_time": report.WallTime,
			},
		})})
	}
	return out, nil
}

// rustFuzzBoundedScope states what a clean campaign was bounded by: which
// upstream harness ran, for how long, and against what corpus.
func rustFuzzBoundedScope(cfg RunConfig, harness string, wallTime time.Duration, corpusInputs, restored, corpusOutputs, newInputs int) *BoundedScope {
	campaign, _ := ParseFuzzCampaign(cfg.Arguments["max_total_time"])
	provenance := "cold"
	if restored > 0 {
		provenance = "restored"
	}
	committed := max(0, corpusInputs-restored)
	return &BoundedScope{
		Harness: harness,
		Corpus:  fmt.Sprintf("inputs in=%d (committed=%d, restored=%d), inputs out=%d, new inputs=%d, provenance=%s", corpusInputs, committed, restored, corpusOutputs, newInputs, provenance),
		Bounds:  fmt.Sprintf("max_total_time=%s, wall_time=%s, workers=%d, trace_compares=true", campaign, wallTime.Round(time.Millisecond), rustFuzzWorkers(cfg)),
	}
}

// rustFuzzCorpusSize counts the inputs the campaign started from.
func rustFuzzCorpusSize(root, target string) int {
	paths, _ := rustFuzzCorpusPaths(root, target)
	return len(paths)
}

// Package securitytoolpacks implements deterministic, typed wrappers for
// security tools. It deliberately separates execution, native artifacts, and
// normalization so normal CI can replay committed output without network access.
package securitytoolpacks

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"path/filepath"
	"regexp"
	"slices"
	"sort"
	"strings"
	"time"

	"github.com/gratefulagents/gratefulagents/internal/security"
)

type Domain string

const (
	DomainWeb        Domain = "web_api"
	DomainCrypto     Domain = "cryptography"
	DomainNetwork    Domain = "network_protocol"
	DomainBlockchain Domain = "blockchain_smart_contract"
)

type Status string

const (
	// StatusNotFoundUnder is the bounded negative result: this harness, with
	// this corpus, these seeds and these bounds, did not find the issue. It is
	// never evidence of safety, which is why it replaced the old "pass"
	// verdict; the accompanying BoundedScope records what was actually
	// covered.
	StatusNotFoundUnder Status = "not_found_under"
	// StatusPass is the retired verdict. It is still accepted when decoding
	// stored runs and manifests, and normalized to StatusNotFoundUnder,
	// because a clean bounded run never proved anything was safe.
	//
	// Deprecated: emit StatusNotFoundUnder instead.
	StatusPass          Status = "pass"
	StatusFindings      Status = "findings"
	StatusError         Status = "error"
	StatusTimeout       Status = "timeout"
	StatusPartial       Status = "partial"
	StatusNotApplicable Status = "not_applicable"
)

type Budgets struct {
	Timeout       time.Duration `json:"timeout"`
	CPU           int           `json:"cpu_millis"`
	Memory        int64         `json:"memory_bytes"`
	Requests      int           `json:"requests"`
	Concurrency   int           `json:"concurrency"`
	MaxOutputSize int64         `json:"max_output_bytes"`
}

type Requirements struct {
	Network   bool     `json:"network"`
	Privilege string   `json:"privilege"`
	Protocols []string `json:"protocols,omitempty"`
}

type Argument struct {
	Name     string   `json:"name"`
	Type     string   `json:"type"`
	Required bool     `json:"required,omitempty"`
	Enum     []string `json:"enum,omitempty"`
	Flag     string   `json:"flag,omitempty"`
	// Default is the reviewed value used when a run omits an optional
	// argument. It is part of the registry, not of the request, so an
	// omitted argument still resolves to a value the catalog declares and
	// the recorded configuration always states what actually ran.
	Default string `json:"default,omitempty"`
}

type Tool struct {
	Name               string            `json:"name"`
	Enabled            bool              `json:"enabled"`
	DisabledReason     string            `json:"disabled_reason,omitempty"`
	Domain             Domain            `json:"domain"`
	Version            string            `json:"version"`
	Image              string            `json:"image"`
	ImageDigest        string            `json:"image_digest"`
	ToolArtifactDigest string            `json:"tool_artifact_digest"`
	WrapperDigest      string            `json:"wrapper_digest"`
	PlatformDigests    map[string]string `json:"platform_digests,omitempty"`
	OCIRoot            string            `json:"oci_root,omitempty"`
	OCIExecutable      string            `json:"oci_executable,omitempty"`
	OCIOutputPath      string            `json:"oci_output_path,omitempty"`
	OCIPath            string            `json:"oci_path,omitempty"`
	OCIWritableTarget  bool              `json:"oci_writable_target,omitempty"`
	Invocation         []string          `json:"invocation"`
	Arguments          []Argument        `json:"arguments,omitempty"`
	TargetTypes        []string          `json:"target_types"`
	ArtifactTypes      []string          `json:"artifact_types,omitempty"`
	KnowledgeDigests   map[string]string `json:"knowledge_digests,omitempty"`
	Requirements       Requirements      `json:"requirements"`
	Budgets            Budgets           `json:"budgets"`
	SeedSupported      bool              `json:"seed_supported,omitempty"`
	ExitCodes          map[int]Status    `json:"exit_codes"`
	OutputMediaType    string            `json:"output_media_type"`
	Adapter            string            `json:"adapter"`
	RedactionRules     []string          `json:"redaction_rules"`
	Idempotent         bool              `json:"idempotent"`
	Resettable         bool              `json:"resettable,omitempty"`
}

type Manifest struct {
	SchemaVersion string `json:"schema_version"`
	Tools         []Tool `json:"tools"`
}

type Target struct {
	Type      string `json:"type"`
	Locator   string `json:"locator"`
	Revision  string `json:"revision"`
	Digest    string `json:"digest"`
	MediaType string `json:"media_type,omitempty"`
}

type RunConfig struct {
	Tool      string            `json:"tool"`
	Target    Target            `json:"target"`
	Arguments map[string]string `json:"arguments,omitempty"`
	Seed      *int64            `json:"seed,omitempty"`
	Scope     []string          `json:"scope,omitempty"`
	Sensitive []string          `json:"sensitive_fields,omitempty"`
}

type Coverage struct {
	Examined  []string `json:"examined"`
	Skipped   []string `json:"skipped"`
	Uncovered []string `json:"uncovered"`
}

type Artifact struct {
	Name        string `json:"name"`
	StorageName string `json:"storage_name,omitempty"`
	MediaType   string `json:"media_type"`
	Digest      string `json:"digest"`
	Size        int    `json:"size"`
	Data        []byte `json:"-"`
}

type Replay struct {
	Target             Target            `json:"target"`
	Tool               string            `json:"tool"`
	ToolVersion        string            `json:"tool_version"`
	ImageDigest        string            `json:"image_digest"`
	ToolArtifactDigest string            `json:"tool_artifact_digest"`
	WrapperDigest      string            `json:"wrapper_digest"`
	PlatformDigest     string            `json:"platform_digest,omitempty"`
	SandboxDigest      string            `json:"sandbox_digest,omitempty"`
	Knowledge          map[string]string `json:"knowledge_digests,omitempty"`
	Configuration      json.RawMessage   `json:"configuration"`
	ConfigurationID    string            `json:"configuration_digest"`
	Seed               *int64            `json:"seed,omitempty"`
	Environment        map[string]string `json:"environment,omitempty"`
	InputDigests       []string          `json:"input_digests"`
}

type Result struct {
	Status    Status                   `json:"status"`
	Findings  []security.ScannerRecord `json:"findings"`
	Artifacts []Artifact               `json:"artifacts"`
	Coverage  Coverage                 `json:"coverage"`
	Errors    []string                 `json:"errors"`
	Replay    Replay                   `json:"replay"`
	Stages    []string                 `json:"stages"`
	// Reproducibility records how this run can be reproduced. Real chain bugs
	// involve ordering, reorgs, retries and scheduler races, so demanding
	// byte-identical replay would reject a genuine race and accept a flake
	// after one lucky rerun.
	Reproducibility ReproducibilityClass `json:"reproducibility_class,omitempty"`
	// Trials records every attempt for a non-deterministic class, successes
	// included and excluded alike, so a trigger rate can be read rather than
	// guessed.
	Trials *TrialSummary `json:"trials,omitempty"`
	// Harness records whether the run could have failed at all.
	Harness *HarnessHealth `json:"harness_health,omitempty"`
	// Bounded records the scope a negative result is bounded by. It is
	// required to interpret StatusNotFoundUnder.
	Bounded *BoundedScope `json:"bounded_scope,omitempty"`
}

// maxCoverageSummaryBytes bounds the rendered coverage summary so it always
// fits the SecurityToolRun status field that carries it.
const maxCoverageSummaryBytes = 1024

// ReproducibilityClass states how a result can be reproduced. Confirmation
// must be reproducible under the correct class, not under a single universal
// definition of determinism.
type ReproducibilityClass string

const (
	// ReproducibilityDeterministic replays byte-identically from the record.
	ReproducibilityDeterministic ReproducibilityClass = "deterministic"
	// ReproducibilitySeeded replays from a recorded seed.
	ReproducibilitySeeded ReproducibilityClass = "seeded_replayable"
	// ReproducibilityScheduleDependent depends on scheduling, timing,
	// ordering, reorgs or environment; the causal trace is what reproduces.
	ReproducibilityScheduleDependent ReproducibilityClass = "schedule_or_environment_dependent"
	// ReproducibilityStatistical reproduces a distribution, not an outcome.
	ReproducibilityStatistical ReproducibilityClass = "statistical"
	// ReproducibilityObservational cannot be re-run; it was observed.
	ReproducibilityObservational ReproducibilityClass = "observational_only"
)

// ValidReproducibilityClass reports whether class is a known class. An empty
// class is allowed and means the run did not state one.
func ValidReproducibilityClass(class ReproducibilityClass) bool {
	switch class {
	case "", ReproducibilityDeterministic, ReproducibilitySeeded,
		ReproducibilityScheduleDependent, ReproducibilityStatistical, ReproducibilityObservational:
		return true
	}
	return false
}

// TrialSummary preserves every attempt behind a non-deterministic result.
type TrialSummary struct {
	Attempts int `json:"attempts"`
	// Successes is how many attempts reproduced the security-relevant
	// outcome. Zero attempts or zero successes is a reportable fact, not a
	// reason to omit the summary.
	Successes int `json:"successes"`
	// StoppingRule states why the campaign stopped, so a null result cannot
	// be read as exhaustive.
	StoppingRule string `json:"stopping_rule,omitempty"`
	// EquivalenceCriteria states what counted as the same outcome across
	// attempts, since byte-identical output is the wrong test here.
	EquivalenceCriteria string `json:"equivalence_criteria,omitempty"`
	// TraceDigest references the recorded scheduler, message or transaction
	// trace that carries the causal ordering.
	TraceDigest string `json:"trace_digest,omitempty"`
	Topology    string `json:"topology,omitempty"`
	ForkState   string `json:"fork_state,omitempty"`
}

// TriggerRate is the observed share of attempts that reproduced the outcome.
// It returns 0 when nothing was attempted.
func (t TrialSummary) TriggerRate() float64 {
	if t.Attempts <= 0 {
		return 0
	}
	return float64(t.Successes) / float64(t.Attempts)
}

// HarnessHealth answers the question a clean run cannot: could this run have
// failed at all? A harness that never reaches the target, never runs the
// control, or carries an assertion that cannot fail proves nothing.
type HarnessHealth struct {
	// EntryPointReached reports that the intended entry point executed.
	EntryPointReached bool `json:"entry_point_reached"`
	// TargetCodeExecuted reports that the real target code ran, as opposed to
	// a mock or a simplified model. A model must never be presented as a
	// target-code reproduction.
	TargetCodeExecuted bool `json:"target_code_executed"`
	// NegativeControlRan and NegativeControlPassed record the control: the
	// same harness against unmodified or non-attacker input.
	NegativeControlRan    bool `json:"negative_control_ran"`
	NegativeControlPassed bool `json:"negative_control_passed"`
	// OracleCanFail records that a mutation or a known calibration failure
	// made the assertion fail on purpose.
	OracleCanFail bool `json:"oracle_can_fail"`
	// MutationsKilled and MutationsTotal quantify the calibration.
	MutationsKilled int `json:"mutations_killed,omitempty"`
	MutationsTotal  int `json:"mutations_total,omitempty"`
	// CorpusRejectRate is the share of inputs the harness refused, which
	// exposes a harness that rejects almost everything it is given.
	CorpusRejectRate float64 `json:"corpus_reject_rate,omitempty"`
	// Notes records anything that qualifies the above.
	Notes string `json:"notes,omitempty"`
}

// ProvesTargetCodeExercised reports whether the health evidence supports a
// claim of target-code reproduction with a working oracle.
func (h HarnessHealth) ProvesTargetCodeExercised() bool {
	return h.EntryPointReached && h.TargetCodeExecuted && h.OracleCanFail
}

// BoundedScope is what a negative result is bounded by. Reading a clean run
// without it invites the "no findings means safe" mistake.
type BoundedScope struct {
	Harness     string   `json:"harness,omitempty"`
	Corpus      string   `json:"corpus,omitempty"`
	Seeds       []string `json:"seeds,omitempty"`
	Bounds      string   `json:"bounds,omitempty"`
	Environment string   `json:"environment,omitempty"`
	// Coverage summarizes semantic coverage - states, transitions, branches
	// or actors exercised - rather than lines.
	Coverage string `json:"coverage,omitempty"`
}

var digestPattern = regexp.MustCompile(`^sha256:[0-9a-f]{64}$`)

func sha256Digest(data []byte) string {
	s := sha256.Sum256(data)
	return "sha256:" + hex.EncodeToString(s[:])
}

func canonicalJSON(v any) ([]byte, error) {
	return json.Marshal(v)
}

func (m Manifest) Validate() error {
	if m.SchemaVersion != "security-tool-registry/v1" {
		return fmt.Errorf("unsupported schema_version %q", m.SchemaVersion)
	}
	seen := map[string]bool{}
	for i, t := range m.Tools {
		if t.Name == "" || t.Version == "" || seen[t.Name] {
			return fmt.Errorf("tools[%d]: name/version missing or duplicate", i)
		}
		seen[t.Name] = true
		if !t.Enabled {
			if strings.TrimSpace(t.DisabledReason) == "" {
				return fmt.Errorf("tool %s: disabled catalog entry requires a reason", t.Name)
			}
			continue
		}
		if t.DisabledReason != "" {
			return fmt.Errorf("tool %s: enabled tool must not have a disabled reason", t.Name)
		}
		if !digestPattern.MatchString(t.ImageDigest) {
			return fmt.Errorf("tool %s: image_digest must be immutable sha256", t.Name)
		}
		if !digestPattern.MatchString(t.ToolArtifactDigest) {
			return fmt.Errorf("tool %s: tool_artifact_digest must be immutable sha256", t.Name)
		}
		if !digestPattern.MatchString(t.WrapperDigest) {
			return fmt.Errorf("tool %s: wrapper_digest must be immutable sha256", t.Name)
		}
		if t.OCIRoot != "" {
			if filepath.Base(t.OCIRoot) != t.OCIRoot || !strings.HasPrefix(t.OCIExecutable, "/") || !strings.Contains(t.Image, "@"+t.ImageDigest) {
				return fmt.Errorf("tool %s: invalid pinned OCI root execution contract", t.Name)
			}
			for _, arch := range []string{"amd64", "arm64"} {
				if !digestPattern.MatchString(t.PlatformDigests[arch]) {
					return fmt.Errorf("tool %s: missing %s OCI manifest digest", t.Name, arch)
				}
			}
			if t.OCIPath != "" {
				for entry := range strings.SplitSeq(t.OCIPath, ":") {
					if !strings.HasPrefix(entry, "/") || filepath.Clean(entry) != entry {
						return fmt.Errorf("tool %s: invalid OCI PATH entry %q", t.Name, entry)
					}
				}
			}
		} else if t.OCIExecutable != "" || t.OCIOutputPath != "" || t.OCIPath != "" || t.OCIWritableTarget {
			return fmt.Errorf("tool %s: OCI fields require oci_root", t.Name)
		}
		for name, digest := range t.KnowledgeDigests {
			if !digestPattern.MatchString(digest) {
				return fmt.Errorf("tool %s: %s digest must be immutable sha256", t.Name, name)
			}
		}
		if slices.Contains([]string{"nuclei", "wycheproof", "rfc-nist-vectors", "suricata", "zeek"}, t.Name) && len(t.KnowledgeDigests) == 0 {
			return fmt.Errorf("tool %s: pinned knowledge bundle is required", t.Name)
		}
		if len(t.Invocation) == 0 || len(t.TargetTypes) == 0 || t.OutputMediaType == "" || t.Adapter == "" {
			return fmt.Errorf("tool %s: incomplete execution contract", t.Name)
		}
		if t.Budgets.Timeout <= 0 || t.Budgets.MaxOutputSize <= 0 || t.Budgets.Concurrency <= 0 {
			return fmt.Errorf("tool %s: invalid budgets", t.Name)
		}
		if len(t.ExitCodes) == 0 {
			return fmt.Errorf("tool %s: exit-code mapping is required", t.Name)
		}
		for code, status := range t.ExitCodes {
			if !slices.Contains([]Status{StatusPass, StatusNotFoundUnder, StatusFindings, StatusError, StatusTimeout}, status) {
				return fmt.Errorf("tool %s: exit code %d has invalid execution status %q", t.Name, code, status)
			}
		}
	}
	return nil
}

func stableRecords(records []security.ScannerRecord) {
	sort.Slice(records, func(i, j int) bool {
		a, b := records[i], records[j]
		ak := strings.Join([]string{a.Tool, a.RuleID, a.FilePath, fmt.Sprint(a.StartLine), a.Message}, "\x00")
		bk := strings.Join([]string{b.Tool, b.RuleID, b.FilePath, fmt.Sprint(b.StartLine), b.Message}, "\x00")
		if ak != bk {
			return ak < bk
		}
		aj, _ := canonicalJSON(a)
		bj, _ := canonicalJSON(b)
		return bytes.Compare(aj, bj) < 0
	})
}

