// SecurityFindingBlockingPolicyDisposition returns the policy disposition
// that blocks report packaging for executionID. Only an explicit final bounty
// acceptance supersedes its input checks; without one, independent scope and
// prior-art dimensions are resolved separately. Events must be newest first.
func SecurityFindingBlockingPolicyDisposition(events []SecurityFindingEvent, executionID string) string {
	for _, event := range events {
		decision, ok := securityFindingPolicyDecisionFromEvent(event, executionID)
		if !ok {
			continue
		}
		if decision.Check == "bounty" {
			if !ValidSecurityFindingPolicyDecision(decision.Check, decision.Disposition) {
				return "invalid_policy_decision"
			}
			if decision.Disposition == "accepted" {
				return ""
			}
			return decision.Disposition
		}
		if decision.Check == "" {
			// Legacy accepted/disproved outcomes were unique to the final gate.
			if decision.Disposition == "accepted" {
				return ""
			}
			if decision.Disposition == "disproved" || decision.Disposition == "not_ready" {
				return decision.Disposition
			}
		}
	}
	return securityFindingPreBountyPolicyBlock(events, executionID, true)
}

// SecurityFindingDefinitivePreBountyExclusion returns a durable scope or
// prior-art decision that makes final bounty evaluation unnecessary. Scope
// and prior-art are independent dimensions, so a newer decision in one does
// not erase an exclusion in the other. Within a dimension, the newest event
// wins. Inconclusive not_ready decisions deliberately do not block review.
// Events must be ordered newest first.
func SecurityFindingDefinitivePreBountyExclusion(events []SecurityFindingEvent, executionID string) string {
	return securityFindingPreBountyPolicyBlock(events, executionID, false)
}

func securityFindingPreBountyPolicyBlock(events []SecurityFindingEvent, executionID string, blockNotReady bool) string {
	var seenScope, seenPriorArt, seenReproduction bool
	for _, event := range events {
		decision, ok := securityFindingPolicyDecisionFromEvent(event, executionID)
		if !ok {
			continue
		}
		if decision.Disposition == "not_ready" && decision.Check == "" {
			if blockNotReady {
				return decision.Disposition
			}
			// A legacy inconclusive event has no dimension. Run the final gate
			// rather than letting an older, possibly superseded exclusion skip it.
			return ""
		}
		if decision.Check != "" && !ValidSecurityFindingPolicyDecision(decision.Check, decision.Disposition) {
			if blockNotReady {
				return "invalid_policy_decision"
			}
			return ""
		}
		switch decision.Check {
		case "scope":
			if seenScope {
				continue
			}
			seenScope = true
			if decision.Disposition == "scope_excluded" || blockNotReady && decision.Disposition == "not_ready" {
				return decision.Disposition
			}
		case "prior_art":
			if seenPriorArt {
				continue
			}
			seenPriorArt = true
			if decision.Disposition == "known_issue" || decision.Disposition == "bot_findable" || decision.Disposition == "fixed_release" || blockNotReady && decision.Disposition == "not_ready" {
				return decision.Disposition
			}
		case "reproduction":
			if seenReproduction {
				continue
			}
			seenReproduction = true
			// An environment that could not run the PoC is inconclusive: it
			// blocks packaging but is never a definitive exclusion.
			if blockNotReady && SecurityFindingPolicyDispositionRetryable(decision.Disposition) {
				return decision.Disposition
			}
		}
	}
	return ""
}

// ValidSecurityFindingPolicyDecision reports whether disposition is a valid
// outcome for check. Keeping this contract shared prevents malformed policy
// provenance from overriding an independent exclusion.
func ValidSecurityFindingPolicyDecision(check, disposition string) bool {
	switch check {
	case "scope":
		return disposition == "scope_eligible" || disposition == "scope_excluded" || disposition == "not_ready"
	case "prior_art":
		return disposition == "known_issue" || disposition == "bot_findable" || disposition == "fixed_release" || disposition == "novel" || disposition == "not_ready"
	case "bounty":
		return disposition == "accepted" || disposition == "disproved" || disposition == "scope_excluded" || disposition == "known_issue" || disposition == "bot_findable" || disposition == "not_ready" || disposition == SecurityFindingPolicyDispositionUnreproducibleEnv
	case "reproduction":
		return disposition == "reproduced" || disposition == "not_reproduced" || disposition == "not_ready" || disposition == SecurityFindingPolicyDispositionUnreproducibleEnv
	default:
		return false
	}
}

// SecurityFindingPolicyDispositionUnreproducibleEnv records that a post-script
// could not run the stored PoC because of the environment (build failure,
// missing toolchain, unconfigured fork endpoint). Like not_ready it blocks
// report packaging without changing the finding's technical status, and the
// controller retries the post-script.
const SecurityFindingPolicyDispositionUnreproducibleEnv = "unreproducible_env"

// SecurityFindingPolicyDispositionRetryable reports whether disposition is an
// inconclusive environment outcome the controller should retry rather than
// treat as a verdict.
func SecurityFindingPolicyDispositionRetryable(disposition string) bool {
	return disposition == "not_ready" || disposition == SecurityFindingPolicyDispositionUnreproducibleEnv
}

// SecurityFindingRetryablePolicyDisposition returns the newest policy
// disposition recorded by actor for executionID when it is an inconclusive
// environment outcome (see SecurityFindingPolicyDispositionRetryable), or ""
// when the actor's latest decision is a real verdict or it recorded none.
// Events must be ordered newest first.
func SecurityFindingRetryablePolicyDisposition(events []SecurityFindingEvent, executionID, actor string) string {
	for _, event := range events {
		if event.Actor != actor {
			continue
		}
		decision, ok := securityFindingPolicyDecisionFromEvent(event, executionID)
		if !ok {
			continue
		}
		if SecurityFindingPolicyDispositionRetryable(decision.Disposition) {
			return decision.Disposition
		}
		return ""
	}
	return ""
}

type securityFindingPolicyDecision struct {
	Disposition string
	Check       string
}

func securityFindingPolicyDecisionFromEvent(event SecurityFindingEvent, executionID string) (securityFindingPolicyDecision, bool) {
	if event.EventType != "policy_disposition" {
		return securityFindingPolicyDecision{}, false
	}
	var detail struct {
		ExecutionID string `json:"execution_id"`
		Disposition string `json:"policy_disposition"`
		Check       string `json:"policy_check"`
	}
	if json.Unmarshal(event.Detail, &detail) != nil || detail.ExecutionID != executionID {
		return securityFindingPolicyDecision{}, false
	}
	if detail.Check == "" {
		switch detail.Disposition {
		case "scope_excluded", "scope_eligible":
			detail.Check = "scope"
		case "known_issue", "bot_findable", "fixed_release", "novel":
			detail.Check = "prior_art"
		}
	}
	return securityFindingPolicyDecision{Disposition: detail.Disposition, Check: detail.Check}, true
}

const (
	SecurityFindingStatusOpen          = "open"
	SecurityFindingStatusTriaged       = "triaged"
	SecurityFindingStatusConfirmed     = "confirmed"
	SecurityFindingStatusFalsePositive = "false_positive"
	SecurityFindingStatusFixed         = "fixed"
	SecurityFindingStatusAcceptedRisk  = "accepted_risk"
	// SecurityFindingStatusActionable is a read-only list filter that groups
	// findings still requiring remediation: open, triaged, and confirmed. It
	// is not a persisted status and must not be accepted by status mutations.
	SecurityFindingStatusActionable = "actionable"
)

// SecurityFindingIsActionable reports whether a persisted status represents
// a real finding that still requires action.
func SecurityFindingIsActionable(status string) bool {
	switch status {
	case SecurityFindingStatusOpen, SecurityFindingStatusTriaged, SecurityFindingStatusConfirmed:
		return true
	}
	return false
}

// ValidSecurityFindingStatus reports whether s is a known finding status.
func ValidSecurityFindingStatus(s string) bool {
	switch s {
	case SecurityFindingStatusOpen,
		SecurityFindingStatusTriaged,
		SecurityFindingStatusConfirmed,
		SecurityFindingStatusFalsePositive,
		SecurityFindingStatusFixed,
		SecurityFindingStatusAcceptedRisk:
		return true
	}
	return false
}

// Baseline states classify a finding relative to the previous scan run.
// They are computed at write time: UpsertSecurityFinding classifies
// insertions and reobservations, and FinalizeSecurityScanBaseline marks
// findings absent from a completed run as resolved.
const (
	SecurityFindingBaselineNew       = "new"
	SecurityFindingBaselineRecurring = "recurring"
	SecurityFindingBaselineRegressed = "regressed"
	SecurityFindingBaselineResolved  = "resolved"
	SecurityFindingBaselineReopened  = "reopened"
)

// ValidSecurityFindingBaselineState reports whether s is a known baseline
// state.
func ValidSecurityFindingBaselineState(s string) bool {
	switch s {
	case SecurityFindingBaselineNew,
		SecurityFindingBaselineRecurring,
		SecurityFindingBaselineRegressed,
		SecurityFindingBaselineResolved,
		SecurityFindingBaselineReopened:
		return true
	}
	return false
}

// ValidateSecurityTicketURL rejects anything that is not an absolute
// http(s) URL so a stored ticket link can never smuggle another scheme into
// the UI.
func ValidateSecurityTicketURL(raw string) error {
	u, err := url.Parse(raw)
	if err != nil {
		return fmt.Errorf("invalid ticket URL: %w", err)
	}
	if (u.Scheme != "http" && u.Scheme != "https") || u.Host == "" {
		return errors.New("ticket URL must be an absolute http(s) URL")
	}
	return nil
}

