// research consumers do not need to implement an artifact capability they do not use.
type SecurityResearchArtifactStore interface {
	CreateSecurityResearchArtifact(context.Context, string, *SecurityResearchArtifact) (*SecurityResearchArtifact, bool, error)
	GetSecurityResearchArtifact(context.Context, string, uuid.UUID, string, uuid.UUID) (*SecurityResearchArtifact, error)
	ListSecurityResearchArtifacts(context.Context, string, SecurityResearchArtifactFilter) ([]SecurityResearchArtifact, error)
}

func ValidSecurityResearchArtifactKind(kind string) bool {
	switch kind {
	case SecurityResearchArtifactManifest, SecurityResearchArtifactTrace, SecurityResearchArtifactHarnessSummary, SecurityResearchArtifactBlocker:
		return true
	default:
		return false
	}
}

func ValidateSecurityTaskHandoff(value SecurityTaskHandoff) error {
	if value.Version != SecurityTaskHandoffVersion {
		return fmt.Errorf("handoff version must be %d", SecurityTaskHandoffVersion)
	}
	references := len(value.ArtifactIDs) + len(value.CandidateFingerprints) + len(value.BlockerIDs)
	seenArtifacts := make(map[uuid.UUID]struct{}, len(value.ArtifactIDs))
	for _, id := range value.ArtifactIDs {
		if id == uuid.Nil {
			return errors.New("artifact IDs must be UUIDs")
		}
		if _, exists := seenArtifacts[id]; exists {
			return errors.New("artifact IDs must be unique")
		}
		seenArtifacts[id] = struct{}{}
	}
	seenCandidates := make(map[string]struct{}, len(value.CandidateFingerprints))
	for _, fingerprint := range value.CandidateFingerprints {
		fingerprint = strings.TrimSpace(fingerprint)
		if fingerprint == "" || len(fingerprint) > 256 {
			return errors.New("candidate fingerprints must be non-empty and at most 256 bytes")
		}
		if _, exists := seenCandidates[fingerprint]; exists {
			return errors.New("candidate fingerprints must be unique")
		}
		seenCandidates[fingerprint] = struct{}{}
	}
	seenCoverage := map[uuid.UUID]struct{}{}
	for verdict, ids := range value.CoverageIDs {
		if !ValidSecurityCoverageVerdict(verdict) {
			return fmt.Errorf("invalid coverage verdict %q", verdict)
		}
		references += len(ids)
		for _, id := range ids {
			if id == uuid.Nil {
				return errors.New("coverage IDs must be UUIDs")
			}
			if _, exists := seenCoverage[id]; exists {
				return errors.New("coverage IDs must be unique across verdicts")
			}
			seenCoverage[id] = struct{}{}
		}
	}
	seenBlockers := map[uuid.UUID]struct{}{}
	for _, id := range value.BlockerIDs {
		if id == uuid.Nil {
			return errors.New("blocker IDs must be UUIDs")
		}
		if _, exists := seenBlockers[id]; exists {
			return errors.New("blocker IDs must be unique")
		}
		seenBlockers[id] = struct{}{}
	}
	if references > MaxSecurityTaskHandoffReferences {
		return fmt.Errorf("handoff references must not exceed %d", MaxSecurityTaskHandoffReferences)
	}
	encoded, err := json.Marshal(value)
	if err != nil || len(encoded) > MaxSecurityTaskHandoffBytes {
		return fmt.Errorf("handoff must not exceed %d bytes", MaxSecurityTaskHandoffBytes)
	}
	return nil
}

//nolint:gocyclo // Keeping the complete artifact validation contract in one function makes its bounds auditable.
func ValidateSecurityResearchArtifact(value *SecurityResearchArtifact) error {
	if value == nil {
		return errors.New("security research artifact is required")
	}
	if value.RevisionID == uuid.Nil || strings.TrimSpace(value.ExecutionID) == "" || strings.TrimSpace(value.TaskName) == "" || strings.TrimSpace(value.Actor) == "" {
		return errors.New("revision, execution, task, and actor are required")
	}
	if len(value.ExecutionID) > 256 || len(value.TaskName) > 256 || len(value.Actor) > 256 {
		return errors.New("execution, task, and actor must not exceed 256 bytes")
	}
	if !ValidSecurityResearchArtifactKind(strings.TrimSpace(value.Kind)) {
		return fmt.Errorf("invalid security research artifact kind %q", value.Kind)
	}
	if value.SchemaVersion != SecurityTaskHandoffVersion {
		return fmt.Errorf("schema_version must be %d", SecurityTaskHandoffVersion)
	}
	if key := strings.TrimSpace(value.IdempotencyKey); key == "" || len(key) > 256 {
		return errors.New("idempotency_key is required and must not exceed 256 bytes")
	}
	if len(value.Payload) == 0 || !json.Valid(value.Payload) {
		return errors.New("payload must be a valid JSON object")
	}
	var payload map[string]json.RawMessage
	if json.Unmarshal(value.Payload, &payload) != nil || payload == nil {
		return errors.New("payload must be a valid JSON object")
	}
	compactPayload, err := json.Marshal(payload)
	if err != nil || len(compactPayload) > MaxSecurityResearchArtifactPayloadBytes {
		return fmt.Errorf("payload must not exceed %d bytes", MaxSecurityResearchArtifactPayloadBytes)
	}

	references := len(value.CandidateFingerprints) + len(value.BlockerIDs)
	seenFingerprints := make(map[string]struct{}, len(value.CandidateFingerprints))
	for _, fingerprint := range value.CandidateFingerprints {
		if fingerprint = strings.TrimSpace(fingerprint); fingerprint == "" || len(fingerprint) > 256 {
			return errors.New("candidate fingerprints must be non-empty and at most 256 bytes")
		}
		if _, exists := seenFingerprints[fingerprint]; exists {
			return errors.New("candidate fingerprints must be unique")
		}
		seenFingerprints[fingerprint] = struct{}{}
	}
	seenCoverage := make(map[uuid.UUID]struct{})
	for verdict, ids := range value.CoverageIDs {
		if !ValidSecurityCoverageVerdict(verdict) {
			return fmt.Errorf("invalid coverage verdict %q", verdict)
		}
		references += len(ids)
		for _, id := range ids {
			if id == uuid.Nil {
				return errors.New("coverage IDs must be UUIDs")
			}
			if _, exists := seenCoverage[id]; exists {
				return errors.New("coverage IDs must be unique across verdicts")
			}
			seenCoverage[id] = struct{}{}
		}
	}
	seenBlockers := make(map[uuid.UUID]struct{}, len(value.BlockerIDs))
	for _, id := range value.BlockerIDs {
		if id == uuid.Nil {
			return errors.New("blocker IDs must be UUIDs")
		}
		if _, exists := seenBlockers[id]; exists {
			return errors.New("blocker IDs must be unique")
		}
		seenBlockers[id] = struct{}{}
	}
	if references > MaxSecurityResearchArtifactReferences {
		return fmt.Errorf("handoff references must not exceed %d", MaxSecurityResearchArtifactReferences)
	}
	if len(value.Conditions) > MaxSecurityResearchArtifactConditions {
		return fmt.Errorf("conditions must not exceed %d entries", MaxSecurityResearchArtifactConditions)
	}
	conditionsJSON, err := json.Marshal(value.Conditions)
	if err != nil || len(conditionsJSON) > MaxSecurityResearchConditionBytes {
		return fmt.Errorf("conditions must not exceed %d bytes", MaxSecurityResearchConditionBytes)
	}
	for key, raw := range value.Conditions {
		if strings.TrimSpace(key) == "" || len(key) > 64 {
			return errors.New("condition keys must be non-empty and at most 64 bytes")
		}
		var scalar any
		if len(raw) == 0 || json.Unmarshal(raw, &scalar) != nil {
			return fmt.Errorf("condition %q must be a JSON scalar", key)
		}
		switch typed := scalar.(type) {
		case nil, bool, float64:
		case string:
			if !utf8.ValidString(typed) || len(typed) > 256 {
				return fmt.Errorf("condition %q string must not exceed 256 bytes", key)
			}
		default:
			return fmt.Errorf("condition %q must be a JSON scalar", key)
		}
	}
	return nil
}

// Package store defines the state storage interface for agent sessions.
// It abstracts conversation history, activity events, and artifact persistence
// away from etcd/CRD status into a durable backend (Postgres + S3).
package store

import (
	"context"
	"encoding/json"
	"errors"
	"time"

	"github.com/google/uuid"
)

// Sentinel errors for conversation message cancellation. Implementations of
// StateStore return (possibly wrapped) these so callers can map them to
// user-facing failures.
var (
	// ErrMessageNotFound is returned when the referenced user message does
	// not exist in the session (or was already cancelled).
	ErrMessageNotFound = errors.New("message not found")
	// ErrMessageDelivered is returned when the agent loop already consumed
	// the message, so it can no longer be cancelled.
	ErrMessageDelivered = errors.New("message already delivered")
	// ErrMessageAlreadyExists is returned when an idempotency key in message
	// metadata already exists for the session. Callers may treat it as a
	// successful replay of the original append.
	ErrMessageAlreadyExists = errors.New("message already exists")
	// ErrSessionNotFound is returned when no durable session exists for the
	// referenced AgentRun, e.g. before its first runner episode created one.
	// Callers use it to distinguish "not provisioned yet" from store outages.
	ErrSessionNotFound = errors.New("session not found")
	// ErrSessionEnded is returned when a user message cannot be recorded
	// because the session reached a terminal phase concurrently.
	ErrSessionEnded = errors.New("session has ended")
)

// Session represents a persistent agent session tied to an AgentRun.
type Session struct {
	ID               uuid.UUID
	AgentRunName     string
	AgentRunNS       string
	Phase            string
	CurrentStep      string
	PendingQuestion  string
	PendingActions   json.RawMessage
	PendingInputType string
	PendingRequestID string
	Metadata         json.RawMessage
	CreatedAt        time.Time
	UpdatedAt        time.Time
}

// Message represents a single conversation turn.
type Message struct {
	ID               int64
	SessionID        uuid.UUID
	Role             string // "user", "assistant", "system"
	Content          string
	Metadata         json.RawMessage
	DeliveryState    string
	DeliverySequence int64
	ClaimedAt        *time.Time
	CreatedAt        time.Time
}

// ActivityEvent represents an agent activity log entry.
type ActivityEvent struct {
	ID        int64
	SessionID uuid.UUID
	EventType string
	Summary   string
	Detail    json.RawMessage
	CreatedAt time.Time
}

// Artifact represents a stored artifact (plan, diff, activity log, etc.).
type Artifact struct {
	ID          uuid.UUID
	SessionID   uuid.UUID
	Kind        string // "plan", "diff", "activity_log", "review"
	Content     string
	S3URL       string
	ContentHash string
	Metadata    json.RawMessage
	CreatedAt   time.Time
	UpdatedAt   time.Time
}

// SessionMetricsEntry holds parsed cost/token metrics for a session, keyed by AgentRun.
type SessionMetricsEntry struct {
	AgentRunName  string
	AgentRunNS    string
	CostUSD       float64
	InputTokens   int64
	OutputTokens  int64
	ToolCallCount int32
}

// AgentRunKey identifies an AgentRun by namespace and name.
type AgentRunKey struct {
	Namespace string
	Name      string
}

// SessionsByRunsLister is an optional store capability that loads the
// sessions for an explicit set of AgentRuns in one query. Fleet watch ticks
// use it to enrich only the runs that changed instead of loading every
// session in the namespace on every tick.
type SessionsByRunsLister interface {
	ListSessionsByRuns(ctx context.Context, keys []AgentRunKey) ([]Session, error)
}

// SessionMetricsByNamespaceLister is an optional store capability that
// returns per-run cost/token metrics scoped to one namespace ("" = all),
// reading only the metrics object out of each session's metadata.
type SessionMetricsByNamespaceLister interface {
	ListSessionMetricsByNamespace(ctx context.Context, namespace string) ([]SessionMetricsEntry, error)
}

// ActivityEventGetter is an optional store capability for a single
// primary-key activity event lookup scoped to a session. Returns
// ErrActivityEventNotFound when the event does not exist in that session.
type ActivityEventGetter interface {
	GetActivityEvent(ctx context.Context, sessionID uuid.UUID, eventID int64) (*ActivityEvent, error)
}

// ErrActivityEventNotFound is returned by ActivityEventGetter when the
// requested event does not belong to the session.
var ErrActivityEventNotFound = errors.New("activity event not found")

type ObservabilityQuery struct {
	Namespace     string
	Start         time.Time
	End           time.Time
	BucketSeconds int64
	AgentRunNames []string
}

type ObservabilityTotals struct {
	Runs, InputTokens, OutputTokens, ToolCalls, ToolErrors int64
	Subagents, SubagentFailures, LLMAttempts, LLMFailures  int64
	Compactions, TokensReclaimed                           int64
	GenerationInputTokens, GenerationOutputTokens          int64
	CostUSD, GenerationCostUSD                             float64
}

type ObservabilityBucket struct {
	Start  time.Time
	Totals ObservabilityTotals
}

type ObservabilityBreakdown struct {
	Name                                      string
	Count, Errors, InputTokens, OutputTokens  int64
	CostUSD, AverageDurationMS, P95DurationMS float64
}

type ObservabilityDataCompleteness struct {
	Sessions, SessionsWithMetrics, SessionsWithActivity int64
	MetricsComplete, ActivityComplete                   bool
}

type ObservabilityOverview struct {
	Totals       ObservabilityTotals
	Buckets      []ObservabilityBucket
	Tools        []ObservabilityBreakdown
	Subagents    []ObservabilityBreakdown
	Models       []ObservabilityBreakdown
	Completeness ObservabilityDataCompleteness
}

// SlackDraft is a proposed reply to an incoming Slack DM awaiting the owner's
// approval. After a decision it doubles as an audit record.
type SlackDraft struct {
	ID           uuid.UUID
	SlackAgent   string
	Namespace    string
	Kind         string // channel_reply ("triage" only in legacy rows from the removed inbox-monitoring feature)
	ChannelID    string
	ThreadTS     string
	TargetUser   string
	IncomingText string
	DraftText    string
	Status       string // pending | sent | dismissed
	CreatedAt    time.Time
	DecidedAt    *time.Time
}

// PendingInputResolution is a request-bound response to reserve atomically in
// the conversation before controller side effects are applied. Metadata must
// include a stable delivery_id; reserved messages remain hidden from agent
// polling until ReleasePendingInputResponse succeeds.
type PendingInputResolution struct {
	RequestID string
	Phase     string
	Role      string
	Content   string
	Metadata  json.RawMessage
}

// PendingInputResolver is the transactional extension used by trusted
// controllers to consume exactly one pending request without racing a user or
// a replacement request. It is separate from StateStore so lightweight stores
// that never resolve controller-managed input do not need to implement it.
type PendingInputResolver interface {
	ReservePendingInputResponse(ctx context.Context, sessionID uuid.UUID, resolution PendingInputResolution) (message *Message, reserved bool, err error)
	ReleasePendingInputResponse(ctx context.Context, sessionID uuid.UUID, messageID int64, deliveryID string) error
	CancelPendingInputResponse(ctx context.Context, sessionID uuid.UUID, messageID int64, deliveryID string) error
}

// PendingInputClearer conditionally consumes an exact request without touching
// a replacement. Interactive approval handlers use it after external effects
// have been committed.
type PendingInputClearer interface {
	ClearPendingInputIfID(ctx context.Context, sessionID uuid.UUID, requestID, phase string) (cleared bool, err error)
}

// PendingInputAnswer is a request-bound user answer. Unlike
// PendingInputResolution it has no hold phase: the answer message becomes
// visible to the agent loop in the same transaction that consumes the exact
// pending request, so there is no reserve/release window to recover from.
type PendingInputAnswer struct {
	RequestID string
	Phase     string
	Content   string
	Metadata  json.RawMessage
}

// PendingInputAnswerer atomically records one user answer for one exact
// pending input request. It fails closed: if the request nonce no longer
// matches (already answered, or replaced by a newer question) no message is
// inserted and answered is false. Interactive surfaces (dashboard) use this
// so two concurrent clients can never both answer the same request.
type PendingInputAnswerer interface {
	AnswerPendingInput(ctx context.Context, sessionID uuid.UUID, answer PendingInputAnswer) (message *Message, answered bool, err error)
}

// ActiveUserMessageAppender inserts a user message only while the session has
// not reached a terminal phase, closing the send-readiness TOCTOU between the
// dashboard's readiness snapshot and the append. Returns ErrSessionEnded when
// the session finished concurrently.
type ActiveUserMessageAppender interface {
	AppendUserMessageIfActive(ctx context.Context, sessionID uuid.UUID, content string, metadata json.RawMessage) (*Message, error)
}

// HeldInputRecoverer recovers reserved-but-never-released pending input
// responses (overseer crash between reserve and release). Expired holds are
// cancelled and, when no newer request exists, the consumed pending request is
// restored from the snapshot captured at reserve time so the question becomes
// answerable again instead of head-of-line blocking all later user messages.
type HeldInputRecoverer interface {
	RecoverExpiredHeldInputResponses(ctx context.Context, sessionID uuid.UUID, olderThan time.Duration) (recovered int, err error)
}

// DurableAssistantCommitter idempotently commits one assistant response per
// stable SDK run/pass key, including autonomous passes with no remaining claim.
type DurableAssistantCommitter interface {
	AppendAssistantForDurablePass(ctx context.Context, sessionID uuid.UUID, claimToken uuid.UUID, passKey, content string) (*Message, error)
}

// MessageClaimer provides PostgreSQL's durable claim protocol without forcing
// lightweight/test StateStore implementations to emulate database CAS.
type MessageClaimer interface {
	ClaimUserMessage(ctx context.Context, sessionID uuid.UUID, messageID int64, claimToken uuid.UUID) (message *Message, claimed bool, err error)
	AppendAssistantAndCompleteClaims(ctx context.Context, sessionID uuid.UUID, claimToken uuid.UUID, content string) (*Message, error)
	CompleteClaims(ctx context.Context, sessionID uuid.UUID, claimToken uuid.UUID) error
	RecoverClaimedUserMessages(ctx context.Context, sessionID uuid.UUID, activeClaimToken uuid.UUID) error
}

// MetadataSectionUpdater is an optional StateStore extension that applies a
// read-modify-write to one top-level session metadata key under a session row
// lock, so concurrent updates of the same section cannot lose each other's
// writes. mutate receives the current raw JSON value of the key (nil when
// absent) and returns the replacement value.
type MetadataSectionUpdater interface {
	UpdateSessionMetadataSection(ctx context.Context, id uuid.UUID, key string, mutate func(json.RawMessage) (json.RawMessage, error)) error
}

// SessionChangeSubscriber is an optional StateStore extension that delivers
// wake-up hints when a session (or any of its child rows) changes, backed by
// Postgres LISTEN/NOTIFY. Hints are lossy and carry no data: subscribers must
// keep polling and treat a wake-up purely as a reason to poll sooner. When
// the listener is unhealthy no hints arrive and pollers should use their fast
// interval.
type SessionChangeSubscriber interface {
	SubscribeSessionChanges(sessionID uuid.UUID) (wake <-chan struct{}, cancel func())
	SessionChangeListenerHealthy() bool
}

// MessageGetter is an optional store capability for a single primary-key
// message lookup scoped to a session. Returns ErrMessageNotFound when the
// message does not exist in that session.
type MessageGetter interface {
	GetMessage(ctx context.Context, sessionID uuid.UUID, messageID int64) (*Message, error)
}

// ActivityEventInput is one row for ActivityEventBatchWriter. A nil Detail is
// stored as an empty JSON object.
type ActivityEventInput struct {
	EventType string
	Summary   string
	Detail    json.RawMessage
}

// ActivityEventBatchWriter is an optional store capability that persists many
// activity events in one statement, so the per-session change counter is
// bumped once per batch instead of once per event. Returned IDs are in input
// order.
type ActivityEventBatchWriter interface {
	WriteActivityEvents(ctx context.Context, sessionID uuid.UUID, events []ActivityEventInput) ([]int64, error)
}

// InterruptStore persists interrupts as append-only rows so concurrent stop
// requests cannot overwrite one another.
type InterruptStore interface {
	AppendInterrupt(ctx context.Context, sessionID uuid.UUID, requestedBy string) (int64, time.Time, error)
	PeekInterrupt(ctx context.Context, sessionID uuid.UUID) (id int64, requestedAt time.Time, requestedBy string, ok bool, err error)
	ConsumeInterrupt(ctx context.Context, sessionID uuid.UUID) (id int64, requestedAt time.Time, requestedBy string, ok bool, err error)
}

// WakeIntentStore atomically deduplicates a resume message. The Kubernetes
// wake counter is reconciled to TargetWakeRequests, making retries safe after
// either side of the PostgreSQL/Kubernetes boundary fails.
type WakeIntentStore interface {
	ReserveWakeIntent(ctx context.Context, sessionID uuid.UUID, idempotencyKey, content string, targetWakeRequests int64) (message *Message, target int64, created bool, err error)
	MarkWakeIntentApplied(ctx context.Context, sessionID uuid.UUID, idempotencyKey string) error
}

// StateStore is the interface for all agent session state persistence.
// Implementations must be safe for concurrent use.
type StateStore interface {
	// Session lifecycle
	CreateSession(ctx context.Context, agentRunName, agentRunNS, phase, currentStep string) (*Session, error)
	GetSession(ctx context.Context, id uuid.UUID) (*Session, error)
	GetSessionByRun(ctx context.Context, agentRunName, agentRunNS string) (*Session, error)
	// ListSessionsByNamespace returns every session whose AgentRun lives in
	// the given namespace; an empty namespace returns all sessions. Used to
	// batch per-run session lookups when enriching run lists.
	ListSessionsByNamespace(ctx context.Context, namespace string) ([]Session, error)
	UpdatePhase(ctx context.Context, id uuid.UUID, phase, currentStep string) error
	SetPendingQuestion(ctx context.Context, id uuid.UUID, phase, question, inputType string) error
	ClearPendingQuestion(ctx context.Context, id uuid.UUID, phase string) error
	SetPendingAction(ctx context.Context, id uuid.UUID, phase, question string, actions json.RawMessage, inputType string) error
	ClearPendingAction(ctx context.Context, id uuid.UUID, phase string) error
	UpdateMetadata(ctx context.Context, id uuid.UUID, metadata json.RawMessage) error
	MergeSessionMetadata(ctx context.Context, id uuid.UUID, key string, value json.RawMessage) error
	ListAllSessionMetrics(ctx context.Context) ([]SessionMetricsEntry, error)
	// DeleteAgentRunData deletes every DB row that is scoped to the given
	// AgentRun. projectID scopes durable project-state rows when available.
	// Implementations should be idempotent so Kubernetes finalizers can safely
	// retry cleanup after partial failure.
	DeleteAgentRunData(ctx context.Context, agentRunName, agentRunNS, projectID string) error

	// Conversation
	// AppendMessage atomically returns ErrMessageAlreadyExists when the same
	// non-empty github_event_key metadata value already exists in the session.
	AppendMessage(ctx context.Context, sessionID uuid.UUID, role, content string, metadata json.RawMessage) (*Message, error)
	GetMessages(ctx context.Context, sessionID uuid.UUID) ([]Message, error)
	// GetMessagesIncludingCancelled includes cancelled user messages for queue-history surfaces.
	GetMessagesIncludingCancelled(ctx context.Context, sessionID uuid.UUID) ([]Message, error)
	GetMessagesSince(ctx context.Context, sessionID uuid.UUID, afterID int64) ([]Message, error)
	// PollNewUserMessages returns every user message that is still pending
	// delivery and not gated behind an overseer hold. There is deliberately
	// no cursor parameter: pending delivery_state is authoritative, and a
	// scalar cursor could hide a pending hole inserted before a later
	// assistant reply.
	PollNewUserMessages(ctx context.Context, sessionID uuid.UUID) ([]Message, error)
	// MarkMessagesDelivered records that the agent loop consumed the given
	// user messages, stamping delivered_at_unix into each message's metadata.
	MarkMessagesDelivered(ctx context.Context, sessionID uuid.UUID, messageIDs []int64) error
	// CancelUndeliveredUserMessage withdraws a queued/steering user message
	// before the agent loop consumes it, stamping cancelled_at_unix into its
	// metadata. Cancelled messages are excluded from delivery polls and from
	// the rendered conversation. Returns ErrMessageDelivered when the agent
	// already picked the message up and ErrMessageNotFound when no such user
	// message exists in the session.
	CancelUndeliveredUserMessage(ctx context.Context, sessionID uuid.UUID, messageID int64) error

	// Transcript snapshot: one bounded blob per session holding the agent's
	// serialized in-memory run transcript, upserted in place after each turn
	// so a restarted pod can replay full context. GetSessionTranscript
	// returns (nil, nil) when no snapshot exists.
	UpsertSessionTranscript(ctx context.Context, sessionID uuid.UUID, data []byte, itemCount int32) error
	GetSessionTranscript(ctx context.Context, sessionID uuid.UUID) ([]byte, error)
	DeleteSessionTranscript(ctx context.Context, sessionID uuid.UUID) error

	// Activity
	WriteActivityEvent(ctx context.Context, sessionID uuid.UUID, eventType, summary string, detail json.RawMessage) (*ActivityEvent, error)
	GetRecentActivity(ctx context.Context, sessionID uuid.UUID, limit int32) ([]ActivityEvent, error)
	GetAllActivity(ctx context.Context, sessionID uuid.UUID) ([]ActivityEvent, error)
	// GetActivityEventsSince returns activity events with ID greater than
	// afterID, in ascending ID order, for incremental log rebuilds.
	GetActivityEventsSince(ctx context.Context, sessionID uuid.UUID, afterID int64) ([]ActivityEvent, error)

	// GetSessionFingerprint returns a cheap opaque version string that changes
	// whenever the session row, its conversation, activity log, or plan
	// artifact change. Watchers compare fingerprints to skip re-enrichment.
	GetSessionFingerprint(ctx context.Context, sessionID uuid.UUID) (string, error)
	// GetSessionConversationFingerprint is like GetSessionFingerprint but
	// ignores activity-log writes: it changes only when the session row's
	// fields, the conversation, the plan artifact, or interrupts change.
	// Conversation watchers use it so tool-call logging does not force a
	// conversation frame rebuild.
	GetSessionConversationFingerprint(ctx context.Context, sessionID uuid.UUID) (string, error)

	// Artifacts
	UpsertArtifact(ctx context.Context, sessionID uuid.UUID, kind, content, s3URL, contentHash string, metadata json.RawMessage) (*Artifact, error)
	GetArtifact(ctx context.Context, sessionID uuid.UUID, kind string) (*Artifact, error)
	GetArtifacts(ctx context.Context, sessionID uuid.UUID) ([]Artifact, error)

	// Resource ownership
	SetResourceOwner(ctx context.Context, resourceType, resourceID, resourceNS, ownerID string) error
	GetResourceOwner(ctx context.Context, resourceType, resourceID, resourceNS string) (*ResourceOwnership, error)
	ListOwnedResources(ctx context.Context, ownerID, resourceType string) ([]ResourceOwnership, error)

	// Resource sharing
	ShareResource(ctx context.Context, share *ResourceShare) (*ResourceShare, error)
	RevokeShare(ctx context.Context, shareID string) error
	UpdateSharePermission(ctx context.Context, shareID, permission string) error
	ListSharesForResource(ctx context.Context, resourceType, resourceID, resourceNS string) ([]ResourceShare, error)
	ListSharedWithMe(ctx context.Context, userID, resourceType string) ([]ResourceShare, error)
	GetSharePermission(ctx context.Context, resourceType, resourceID, resourceNS, userID string) (*ResourceShare, error)

	// Notifications
	CreateNotification(ctx context.Context, n *Notification) error
	HasUnreadNotification(ctx context.Context, userID, notifType, resourceID, resourceNamespace string) (bool, error)
	ListNotifications(ctx context.Context, userID string, unreadOnly bool, limit int32) ([]Notification, error)
	MarkNotificationRead(ctx context.Context, notificationID string) error
	MarkAllNotificationsRead(ctx context.Context, userID string) error
	GetUnreadNotificationCount(ctx context.Context, userID string) (int32, error)

	// Lifecycle
	Close() error
}

package contentblob

import (
	"bytes"
	"context"
	"encoding/base64"
	"errors"
	"fmt"
	"hash/crc32"
	"io"
	"net/url"
	"os"
	"strings"

	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/credentials"
	"github.com/aws/aws-sdk-go-v2/service/s3"

	"github.com/gratefulagents/gratefulagents/internal/store"
)

type s3Client interface {
	PutObject(context.Context, *s3.PutObjectInput, ...func(*s3.Options)) (*s3.PutObjectOutput, error)
	GetObject(context.Context, *s3.GetObjectInput, ...func(*s3.Options)) (*s3.GetObjectOutput, error)
	DeleteObject(context.Context, *s3.DeleteObjectInput, ...func(*s3.Options)) (*s3.DeleteObjectOutput, error)
}

// S3 stores immutable project-content version bodies in the platform bucket.
type S3 struct {
	client s3Client
	bucket string
}

// NewS3FromEnv builds the project-content blob store from the same S3 settings
// used by run artifacts and workspace checkpoints.
func NewS3FromEnv() (*S3, error) {
	bucket := strings.TrimSpace(os.Getenv("S3_BUCKET"))
	if bucket == "" {
		return nil, fmt.Errorf("S3_BUCKET is required for project assets")
	}
	region := strings.TrimSpace(os.Getenv("S3_REGION"))
	if region == "" {
		region = "us-east-1"
	}
	cfg := aws.Config{Region: region}
	accessKeyID := strings.TrimSpace(os.Getenv("AWS_ACCESS_KEY_ID"))
	secretAccessKey := strings.TrimSpace(os.Getenv("AWS_SECRET_ACCESS_KEY"))
	if (accessKeyID == "") != (secretAccessKey == "") {
		return nil, fmt.Errorf("AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY must be set together for project assets")
	}
	if accessKeyID != "" {
		cfg.Credentials = credentials.NewStaticCredentialsProvider(accessKeyID, secretAccessKey, "")
	}

	endpoint := strings.TrimSpace(os.Getenv("S3_ENDPOINT"))
	if endpoint != "" {
		parsed, err := url.ParseRequestURI(endpoint)
		if err != nil || parsed.Scheme == "" || parsed.Host == "" {
			return nil, fmt.Errorf("S3_ENDPOINT must be an absolute URL")
		}
	}
	client := s3.NewFromConfig(cfg, func(options *s3.Options) {
		if endpoint != "" {
			options.BaseEndpoint = aws.String(endpoint)
			options.UsePathStyle = true
		}
	})
	return &S3{client: client, bucket: bucket}, nil
}

func (s *S3) Put(ctx context.Context, key string, content []byte, mediaType string) error {
	checksum := crc32.ChecksumIEEE(content)
	input := &s3.PutObjectInput{
		Bucket:        aws.String(s.bucket),
		Key:           aws.String(key),
		Body:          bytes.NewReader(content),
		ContentLength: aws.Int64(int64(len(content))),
		ChecksumCRC32: aws.String(base64.StdEncoding.EncodeToString([]byte{byte(checksum >> 24), byte(checksum >> 16), byte(checksum >> 8), byte(checksum)})),
	}
	if mediaType = strings.TrimSpace(mediaType); mediaType != "" {
		input.ContentType = aws.String(mediaType)
	}
	if _, err := s.client.PutObject(ctx, input); err != nil {
		return fmt.Errorf("putting project asset object %q in S3 bucket %q: %w", key, s.bucket, err)
	}
	return nil
}

func (s *S3) Get(ctx context.Context, key string) ([]byte, error) {
	output, err := s.client.GetObject(ctx, &s3.GetObjectInput{Bucket: aws.String(s.bucket), Key: aws.String(key)})
	if err != nil {
		if isNotFound(err) {
			return nil, store.ErrContentBlobNotFound
		}
		return nil, fmt.Errorf("getting project asset object %q from S3 bucket %q: %w", key, s.bucket, err)
	}
	if output.ContentLength != nil && *output.ContentLength > store.MaxProjectContentVersionBytes {
		_ = output.Body.Close()
		return nil, fmt.Errorf("project asset object %q exceeds the %d-byte limit", key, store.MaxProjectContentVersionBytes)
	}
	body, readErr := io.ReadAll(io.LimitReader(output.Body, store.MaxProjectContentVersionBytes+1))
	closeErr := output.Body.Close()
	if readErr != nil {
		return nil, fmt.Errorf("reading project asset object %q: %w", key, readErr)
	}
	if closeErr != nil {
		return nil, fmt.Errorf("closing project asset object %q: %w", key, closeErr)
	}
	if len(body) > store.MaxProjectContentVersionBytes {
		return nil, fmt.Errorf("project asset object %q exceeds the %d-byte limit", key, store.MaxProjectContentVersionBytes)
	}
	return body, nil
}

func (s *S3) Delete(ctx context.Context, key string) error {
	if _, err := s.client.DeleteObject(ctx, &s3.DeleteObjectInput{Bucket: aws.String(s.bucket), Key: aws.String(key)}); err != nil {
		return fmt.Errorf("deleting project asset object %q from S3 bucket %q: %w", key, s.bucket, err)
	}
	return nil
}

type apiError interface {
	error
	ErrorCode() string
}

func isNotFound(err error) bool {
	var apiErr apiError
	return errors.As(err, &apiErr) && (apiErr.ErrorCode() == "NoSuchKey" || apiErr.ErrorCode() == "NotFound")
}

var _ store.ProjectContentBlobStore = (*S3)(nil)

package postgres

import (
	"context"
	"encoding/json"
	"fmt"

	"github.com/google/uuid"

	"github.com/gratefulagents/gratefulagents/internal/store"
)

// WriteActivityEvents inserts a batch of activity events in one statement.
// Implements store.ActivityEventBatchWriter. One statement means the
// statement-level change_seq trigger (migration 056) fires once for the whole
// batch, so a burst of tool-call events costs one session-row update and one
// wake-up notification instead of one per event.
func (s *Store) WriteActivityEvents(ctx context.Context, sessionID uuid.UUID, events []store.ActivityEventInput) ([]int64, error) {
	if len(events) == 0 {
		return nil, nil
	}
	eventTypes := make([]string, len(events))
	summaries := make([]string, len(events))
	details := make([]string, len(events))
	for i, ev := range events {
		eventTypes[i] = ev.EventType
		summaries[i] = ev.Summary
		if len(ev.Detail) == 0 {
			details[i] = "{}"
		} else {
			if !json.Valid(ev.Detail) {
				return nil, fmt.Errorf("activity event %d: detail is not valid JSON", i)
			}
			details[i] = string(ev.Detail)
		}
	}

	// The detail column is jsonb; the payloads travel as text[] and are cast
	// per element so the batch does not depend on driver-side jsonb[] encoding.
	// unnest with ordinality keeps RETURNING in input order.
	rows, err := s.pool.Query(ctx, `
		INSERT INTO activity_events (session_id, event_type, summary, detail)
		SELECT $1, e.event_type, e.summary, e.detail::jsonb
		FROM unnest($2::text[], $3::text[], $4::text[])
		     WITH ORDINALITY AS e(event_type, summary, detail, ord)
		ORDER BY e.ord
		RETURNING id`,
		sessionID, eventTypes, summaries, details)
	if err != nil {
		return nil, fmt.Errorf("writing activity events: %w", err)
	}
	defer rows.Close()

	ids := make([]int64, 0, len(events))
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, fmt.Errorf("scanning activity event id: %w", err)
		}
		ids = append(ids, id)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("reading activity event ids: %w", err)
	}
	if len(ids) != len(events) {
		return nil, fmt.Errorf("writing activity events: inserted %d of %d rows", len(ids), len(events))
	}
	return ids, nil
}

package postgres

import (
	"context"
	"errors"
	"fmt"
	"strings"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"

	"github.com/gratefulagents/gratefulagents/internal/store"
)

const agentBugReportColumns = `id, namespace, run_name, session_id, category, tool_name,
	title, body, fingerprint, occurrences, status, status_note, status_actor,
	fix_run_name, fix_pr_url, first_seen_at, last_seen_at, created_at, updated_at`

func scanAgentBugReportRow(row pgx.Row) (*store.AgentBugReportRecord, bool, error) {
	var rec store.AgentBugReportRecord
	var created bool
	if err := row.Scan(&rec.ID, &rec.Namespace, &rec.RunName, &rec.SessionID,
		&rec.Category, &rec.ToolName, &rec.Title, &rec.Body, &rec.Fingerprint,
		&rec.Occurrences, &rec.Status, &rec.StatusNote, &rec.StatusActor,
		&rec.FixRunName, &rec.FixPRURL,
		&rec.FirstSeenAt, &rec.LastSeenAt, &rec.CreatedAt, &rec.UpdatedAt, &created); err != nil {
		return nil, false, err
	}
	return &rec, created, nil
}

// UpsertAgentBugReport inserts the report or merges a reoccurrence into the
// existing (namespace, fingerprint) row. See store.AgentBugReportStore.
func (s *Store) UpsertAgentBugReport(ctx context.Context, rec *store.AgentBugReportRecord) (*store.AgentBugReportRecord, bool, error) {
	if rec.Namespace == "" || rec.Fingerprint == "" {
		return nil, false, errors.New("namespace and fingerprint are required")
	}
	category := rec.Category
	if category == "" {
		category = store.AgentBugReportCategoryBug
	}
	if !store.ValidAgentBugReportCategory(category) {
		return nil, false, fmt.Errorf("invalid bug report category %q", category)
	}
	// (xmax = 0) distinguishes a fresh insert from a conflict-update.
	// Occurrences count distinct reporting runs, so a retry of report_bug
	// within the same run neither inflates the count nor reopens a report a
	// human just resolved: only a *different* run counts as a reoccurrence
	// and regresses a resolved report to open. Dismissed ("won't fix /
	// noise") stays dismissed either way.
	row := s.pool.QueryRow(ctx, `
		INSERT INTO agent_bug_reports (namespace, run_name, session_id, category,
			tool_name, title, body, fingerprint)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
		ON CONFLICT (namespace, fingerprint) DO UPDATE SET
			body = EXCLUDED.body,
			occurrences = CASE WHEN agent_bug_reports.run_name = EXCLUDED.run_name
				THEN agent_bug_reports.occurrences
				ELSE agent_bug_reports.occurrences + 1 END,
			status = CASE WHEN agent_bug_reports.status = 'resolved'
					AND agent_bug_reports.run_name <> EXCLUDED.run_name
				THEN 'open' ELSE agent_bug_reports.status END,
			run_name = EXCLUDED.run_name,
			session_id = EXCLUDED.session_id,
			last_seen_at = now(),
			updated_at = now()
		RETURNING `+agentBugReportColumns+`, (xmax = 0) AS created`,
		rec.Namespace, rec.RunName, rec.SessionID, category,
		rec.ToolName, rec.Title, rec.Body, rec.Fingerprint)
	out, created, err := scanAgentBugReportRow(row)
	if err != nil {
		return nil, false, fmt.Errorf("upserting agent bug report: %w", err)
	}
	return out, created, nil
}

// GetAgentBugReport returns one report, or (nil, nil) when it does not exist.
func (s *Store) GetAgentBugReport(ctx context.Context, namespace string, id uuid.UUID) (*store.AgentBugReportRecord, error) {
	if namespace == "" {
		return nil, errors.New("namespace is required")
	}
	row := s.pool.QueryRow(ctx, `
		SELECT `+agentBugReportColumns+`, false
		FROM agent_bug_reports
		WHERE namespace = $1 AND id = $2`, namespace, id)
	rec, _, err := scanAgentBugReportRow(row)
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("getting agent bug report: %w", err)
	}
	return rec, nil
}

// ListAgentBugReports lists reports matching the filter, most recently seen
// first.
func (s *Store) ListAgentBugReports(ctx context.Context, f store.AgentBugReportFilter) ([]store.AgentBugReportRecord, error) {
	if f.Namespace == "" {
		return nil, errors.New("namespace is required")
	}
	query := `SELECT ` + agentBugReportColumns + `, false FROM agent_bug_reports WHERE namespace = $1`
	args := []any{f.Namespace}
	if f.Status != "" {
		args = append(args, f.Status)
		query += fmt.Sprintf(" AND status = $%d", len(args))
	}
	if f.Category != "" {
		args = append(args, f.Category)
		query += fmt.Sprintf(" AND category = $%d", len(args))
	}
	query += " ORDER BY last_seen_at DESC, id"
	limit := f.Limit
	if limit <= 0 || limit > 500 {
		limit = 500
	}
	args = append(args, limit)
	query += fmt.Sprintf(" LIMIT $%d", len(args))

	rows, err := s.pool.Query(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("listing agent bug reports: %w", err)
	}
	defer rows.Close()
	var out []store.AgentBugReportRecord
	for rows.Next() {
		rec, _, err := scanAgentBugReportRow(rows)
		if err != nil {
			return nil, fmt.Errorf("scanning agent bug report: %w", err)
		}
		out = append(out, *rec)
	}
	return out, rows.Err()
}

// SetAgentBugReportStatus updates the triage status of one report.
func (s *Store) SetAgentBugReportStatus(ctx context.Context, namespace string, id uuid.UUID, status, actor, note string) error {
	if namespace == "" {
		return errors.New("namespace is required")
	}
	if !store.ValidAgentBugReportStatus(status) {
		return fmt.Errorf("invalid bug report status %q", status)
	}
	tag, err := s.pool.Exec(ctx, `
		UPDATE agent_bug_reports
		SET status = $3, status_actor = $4, status_note = $5, updated_at = now()
		WHERE namespace = $1 AND id = $2`,
		namespace, id, status, actor, note)
	if err != nil {
		return fmt.Errorf("updating agent bug report status: %w", err)
	}
	if tag.RowsAffected() == 0 {
		return store.ErrAgentBugReportNotFound
	}
	return nil
}

// SetAgentBugReportFix records automated-fix progress on one report. Nil
// pointer fields keep their current value; an empty Status leaves the triage
// status (and its actor/note) unchanged.
func (s *Store) SetAgentBugReportFix(ctx context.Context, namespace string, id uuid.UUID, fix store.AgentBugReportFixUpdate) error {
	if namespace == "" {
		return errors.New("namespace is required")
	}
	if fix.Status != "" && !store.ValidAgentBugReportStatus(fix.Status) {
		return fmt.Errorf("invalid bug report status %q", fix.Status)
	}
	sets := []string{"updated_at = now()"}
	args := []any{namespace, id}
	arg := func(v any) string {
		args = append(args, v)
		return fmt.Sprintf("$%d", len(args))
	}
	if fix.FixRunName != nil {
		sets = append(sets, "fix_run_name = "+arg(*fix.FixRunName))
	}
	if fix.FixPRURL != nil {
		sets = append(sets, "fix_pr_url = "+arg(*fix.FixPRURL))
	}
	if fix.Status != "" {
		sets = append(sets,
			"status = "+arg(fix.Status),
			"status_actor = "+arg(fix.StatusActor),
			"status_note = "+arg(fix.StatusNote))
	}
	tag, err := s.pool.Exec(ctx, `
		UPDATE agent_bug_reports
		SET `+strings.Join(sets, ", ")+`
		WHERE namespace = $1 AND id = $2`, args...)
	if err != nil {
		return fmt.Errorf("updating agent bug report fix: %w", err)
	}
	if tag.RowsAffected() == 0 {
		return store.ErrAgentBugReportNotFound
	}
	return nil
}

// GetAgentBugReportByFixRun returns the report whose current fix run is
// fixRunName, or (nil, nil) when none exists.
func (s *Store) GetAgentBugReportByFixRun(ctx context.Context, namespace, fixRunName string) (*store.AgentBugReportRecord, error) {
	if namespace == "" || fixRunName == "" {
		return nil, errors.New("namespace and fixRunName are required")
	}
	row := s.pool.QueryRow(ctx, `
		SELECT `+agentBugReportColumns+`, false
		FROM agent_bug_reports
		WHERE namespace = $1 AND fix_run_name = $2
		ORDER BY updated_at DESC
		LIMIT 1`, namespace, fixRunName)
	rec, _, err := scanAgentBugReportRow(row)
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("getting agent bug report by fix run: %w", err)
	}
	return rec, nil
}

package postgres

