// --- Resource Ownership ---

func (s *Store) SetResourceOwner(ctx context.Context, resourceType, resourceID, resourceNS, ownerID string) error {
	_, err := s.pool.Exec(ctx, `
		INSERT INTO resource_ownership (resource_type, resource_id, resource_namespace, owner_id)
		VALUES ($1, $2, $3, $4)
		ON CONFLICT (resource_type, resource_id, resource_namespace) DO UPDATE SET
			owner_id = EXCLUDED.owner_id`,
		resourceType, resourceID, resourceNS, ownerID)
	if err != nil {
		return fmt.Errorf("setting resource owner: %w", err)
	}
	return nil
}

func (s *Store) GetResourceOwner(ctx context.Context, resourceType, resourceID, resourceNS string) (*store.ResourceOwnership, error) {
	var o store.ResourceOwnership
	err := s.pool.QueryRow(ctx, `
		SELECT id, resource_type, resource_id, resource_namespace, owner_id, created_at
		FROM resource_ownership
		WHERE resource_type = $1 AND resource_id = $2 AND resource_namespace = $3`,
		resourceType, resourceID, resourceNS).
		Scan(&o.ID, &o.ResourceType, &o.ResourceID, &o.ResourceNamespace, &o.OwnerID, &o.CreatedAt)
	if errors.Is(err, pgx.ErrNoRows) {
		// No ownership recorded — distinct from a lookup failure so callers
		// can treat the resource as system/trigger-owned.
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("getting resource owner: %w", err)
	}
	return &o, nil
}

// ListResourceOwnersByType returns all ownership records for a resource type,
// used to bulk-resolve visibility when filtering lists.
func (s *Store) ListResourceOwnersByType(ctx context.Context, resourceType string) ([]store.ResourceOwnership, error) {
	rows, err := s.pool.Query(ctx, `
		SELECT id, resource_type, resource_id, resource_namespace, owner_id, created_at
		FROM resource_ownership
		WHERE resource_type = $1`,
		resourceType)
	if err != nil {
		return nil, fmt.Errorf("listing resource owners: %w", err)
	}
	defer rows.Close()
	var out []store.ResourceOwnership
	for rows.Next() {
		var o store.ResourceOwnership
		if err := rows.Scan(&o.ID, &o.ResourceType, &o.ResourceID, &o.ResourceNamespace, &o.OwnerID, &o.CreatedAt); err != nil {
			return nil, fmt.Errorf("scanning resource ownership: %w", err)
		}
		out = append(out, o)
	}
	return out, rows.Err()
}

func (s *Store) ListOwnedResources(ctx context.Context, ownerID, resourceType string) ([]store.ResourceOwnership, error) {
	rows, err := s.pool.Query(ctx, `
		SELECT id, resource_type, resource_id, resource_namespace, owner_id, created_at
		FROM resource_ownership
		WHERE owner_id = $1 AND resource_type = $2
		ORDER BY created_at DESC`,
		ownerID, resourceType)
	if err != nil {
		return nil, fmt.Errorf("listing owned resources: %w", err)
	}
	defer rows.Close()
	var out []store.ResourceOwnership
	for rows.Next() {
		var o store.ResourceOwnership
		if err := rows.Scan(&o.ID, &o.ResourceType, &o.ResourceID, &o.ResourceNamespace, &o.OwnerID, &o.CreatedAt); err != nil {
			return nil, fmt.Errorf("scanning resource ownership: %w", err)
		}
		out = append(out, o)
	}
	return out, rows.Err()
}

// --- Resource Sharing ---

func (s *Store) ShareResource(ctx context.Context, share *store.ResourceShare) (*store.ResourceShare, error) {
	var rs store.ResourceShare
	err := s.pool.QueryRow(ctx, `
		INSERT INTO resource_shares (resource_type, resource_id, resource_namespace, shared_with_user_id, shared_by_user_id, permission)
		VALUES ($1, $2, $3, $4, $5, $6)
		ON CONFLICT (resource_type, resource_id, resource_namespace, shared_with_user_id) DO UPDATE SET
			permission = EXCLUDED.permission,
			updated_at = now()
		RETURNING id, resource_type, resource_id, resource_namespace, shared_with_user_id, shared_by_user_id, permission, created_at, updated_at`,
		share.ResourceType, share.ResourceID, share.ResourceNamespace,
		share.SharedWithUserID, share.SharedByUserID, share.Permission).
		Scan(&rs.ID, &rs.ResourceType, &rs.ResourceID, &rs.ResourceNamespace,
			&rs.SharedWithUserID, &rs.SharedByUserID, &rs.Permission,
			&rs.CreatedAt, &rs.UpdatedAt)
	if err != nil {
		return nil, fmt.Errorf("sharing resource: %w", err)
	}
	return &rs, nil
}

func (s *Store) RevokeShare(ctx context.Context, shareID string) error {
	_, err := s.pool.Exec(ctx, `DELETE FROM resource_shares WHERE id = $1`, shareID)
	if err != nil {
		return fmt.Errorf("revoking share: %w", err)
	}
	return nil
}

// GetShareByID returns a single share by its ID, or an error when missing.
func (s *Store) GetShareByID(ctx context.Context, shareID string) (*store.ResourceShare, error) {
	var rs store.ResourceShare
	err := s.pool.QueryRow(ctx, `
		SELECT id, resource_type, resource_id, resource_namespace, shared_with_user_id, shared_by_user_id, permission, created_at, updated_at
		FROM resource_shares
		WHERE id = $1`, shareID).
		Scan(&rs.ID, &rs.ResourceType, &rs.ResourceID, &rs.ResourceNamespace,
			&rs.SharedWithUserID, &rs.SharedByUserID, &rs.Permission,
			&rs.CreatedAt, &rs.UpdatedAt)
	if err != nil {
		return nil, fmt.Errorf("getting share: %w", err)
	}
	return &rs, nil
}

func (s *Store) UpdateSharePermission(ctx context.Context, shareID, permission string) error {
	_, err := s.pool.Exec(ctx, `UPDATE resource_shares SET permission = $2, updated_at = now() WHERE id = $1`, shareID, permission)
	if err != nil {
		return fmt.Errorf("updating share permission: %w", err)
	}
	return nil
}

func (s *Store) ListSharesForResource(ctx context.Context, resourceType, resourceID, resourceNS string) ([]store.ResourceShare, error) {
	rows, err := s.pool.Query(ctx, `
		SELECT id, resource_type, resource_id, resource_namespace, shared_with_user_id, shared_by_user_id, permission, created_at, updated_at
		FROM resource_shares
		WHERE resource_type = $1 AND resource_id = $2 AND resource_namespace = $3
		ORDER BY created_at DESC`,
		resourceType, resourceID, resourceNS)
	if err != nil {
		return nil, fmt.Errorf("listing shares for resource: %w", err)
	}
	defer rows.Close()
	return collectShares(rows)
}

func (s *Store) ListSharedWithMe(ctx context.Context, userID, resourceType string) ([]store.ResourceShare, error) {
	query := `
		SELECT id, resource_type, resource_id, resource_namespace, shared_with_user_id, shared_by_user_id, permission, created_at, updated_at
		FROM resource_shares
		WHERE shared_with_user_id = $1`
	var args []interface{}
	args = append(args, userID)
	if resourceType != "" {
		query += ` AND resource_type = $2`
		args = append(args, resourceType)
	}
	query += ` ORDER BY created_at DESC`

	rows, err := s.pool.Query(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("listing shared with me: %w", err)
	}
	defer rows.Close()
	var out []store.ResourceShare
	for rows.Next() {
		var rs store.ResourceShare
		if err := rows.Scan(&rs.ID, &rs.ResourceType, &rs.ResourceID, &rs.ResourceNamespace,
			&rs.SharedWithUserID, &rs.SharedByUserID, &rs.Permission,
			&rs.CreatedAt, &rs.UpdatedAt); err != nil {
			return nil, fmt.Errorf("scanning resource share: %w", err)
		}
		out = append(out, rs)
	}
	return out, rows.Err()
}

func (s *Store) GetSharePermission(ctx context.Context, resourceType, resourceID, resourceNS, userID string) (*store.ResourceShare, error) {
	var rs store.ResourceShare
	err := s.pool.QueryRow(ctx, `
		SELECT id, resource_type, resource_id, resource_namespace, shared_with_user_id, shared_by_user_id, permission, created_at, updated_at
		FROM resource_shares
		WHERE resource_type = $1 AND resource_id = $2 AND resource_namespace = $3 AND shared_with_user_id = $4`,
		resourceType, resourceID, resourceNS, userID).
		Scan(&rs.ID, &rs.ResourceType, &rs.ResourceID, &rs.ResourceNamespace,
			&rs.SharedWithUserID, &rs.SharedByUserID, &rs.Permission,
			&rs.CreatedAt, &rs.UpdatedAt)
	if err != nil {
		return nil, fmt.Errorf("getting share permission: %w", err)
	}
	return &rs, nil
}

// --- Notifications ---

func (s *Store) CreateNotification(ctx context.Context, n *store.Notification) error {
	_, err := s.pool.Exec(ctx, `
		INSERT INTO notifications (user_id, type, title, body, resource_type, resource_id, resource_namespace, actor_id, actor_name)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)`,
		n.UserID, n.Type, n.Title, n.Body, n.ResourceType, n.ResourceID, n.ResourceNamespace, n.ActorID, n.ActorName)
	if err != nil {
		return fmt.Errorf("creating notification: %w", err)
	}
	return nil
}

func (s *Store) HasUnreadNotification(ctx context.Context, userID, notifType, resourceID, resourceNamespace string) (bool, error) {
	var exists bool
	err := s.pool.QueryRow(ctx, `
		SELECT EXISTS(
			SELECT 1 FROM notifications
			WHERE user_id = $1 AND type = $2 AND resource_id = $3 AND resource_namespace = $4 AND read = false
		)`, userID, notifType, resourceID, resourceNamespace).Scan(&exists)
	if err != nil {
		return false, fmt.Errorf("checking unread notification: %w", err)
	}
	return exists, nil
}

func (s *Store) ListNotifications(ctx context.Context, userID string, unreadOnly bool, limit int32) ([]store.Notification, error) {
	rows, err := s.pool.Query(ctx, `
		SELECT id, user_id, type, title, body, resource_type, resource_id, resource_namespace, actor_id, actor_name, read, created_at
		FROM notifications
		WHERE user_id = $1 AND ($2::boolean = false OR read = false)
		ORDER BY created_at DESC
		LIMIT $3`,
		userID, unreadOnly, limit)
	if err != nil {
		return nil, fmt.Errorf("listing notifications: %w", err)
	}
	defer rows.Close()
	var out []store.Notification
	for rows.Next() {
		var n store.Notification
		if err := rows.Scan(&n.ID, &n.UserID, &n.Type, &n.Title, &n.Body, &n.ResourceType, &n.ResourceID, &n.ResourceNamespace, &n.ActorID, &n.ActorName, &n.Read, &n.CreatedAt); err != nil {
			return nil, fmt.Errorf("scanning notification: %w", err)
		}
		out = append(out, n)
	}
	return out, rows.Err()
}

func (s *Store) MarkNotificationRead(ctx context.Context, notificationID string) error {
	_, err := s.pool.Exec(ctx, `UPDATE notifications SET read = true WHERE id = $1`, notificationID)
	if err != nil {
		return fmt.Errorf("marking notification read: %w", err)
	}
	return nil
}

// MarkNotificationReadForUser marks a notification read only when it belongs
// to the given user, preventing cross-user mutation by guessed IDs.
func (s *Store) MarkNotificationReadForUser(ctx context.Context, notificationID, userID string) error {
	_, err := s.pool.Exec(ctx, `UPDATE notifications SET read = true WHERE id = $1 AND user_id = $2`, notificationID, userID)
	if err != nil {
		return fmt.Errorf("marking notification read: %w", err)
	}
	return nil
}

func (s *Store) MarkAllNotificationsRead(ctx context.Context, userID string) error {
	_, err := s.pool.Exec(ctx, `UPDATE notifications SET read = true WHERE user_id = $1 AND read = false`, userID)
	if err != nil {
		return fmt.Errorf("marking all notifications read: %w", err)
	}
	return nil
}

func (s *Store) GetUnreadNotificationCount(ctx context.Context, userID string) (int32, error) {
	var count int32
	err := s.pool.QueryRow(ctx, `SELECT count(*)::int FROM notifications WHERE user_id = $1 AND read = false`, userID).Scan(&count)
	if err != nil {
		return 0, fmt.Errorf("getting unread notification count: %w", err)
	}
	return count, nil
}

// --- helpers ---

func collectShares(rows pgx.Rows) ([]store.ResourceShare, error) {
	var out []store.ResourceShare
	for rows.Next() {
		var rs store.ResourceShare
		if err := rows.Scan(&rs.ID, &rs.ResourceType, &rs.ResourceID, &rs.ResourceNamespace,
			&rs.SharedWithUserID, &rs.SharedByUserID, &rs.Permission,
			&rs.CreatedAt, &rs.UpdatedAt); err != nil {
			return nil, fmt.Errorf("scanning resource share: %w", err)
		}
		out = append(out, rs)
	}
	return out, rows.Err()
}

package postgres

import (
	"context"
	"errors"
	"log"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/google/uuid"
)

// sessionChangeChannel is the Postgres NOTIFY channel emitted by the
// migration-056 triggers whenever a session row (or one of its child tables)
// changes. Payload: the session UUID.
const sessionChangeChannel = "session_change"

// sessionChangeChannelPrefix prefixes the per-session channels emitted by the
// migration-059 notify trigger alongside the global channel.
const sessionChangeChannelPrefix = "session_change_"

const (
	// listenLivenessInterval bounds each WaitForNotification so a silently
	// dead TCP connection (NAT timeout, killed proxy) is detected by a Ping
	// instead of hanging the listener forever with healthy=true.
	listenLivenessInterval = 45 * time.Second
	listenPingTimeout      = 10 * time.Second
	// listenBackoffResetAfter: a connection that stayed up this long counts
	// as a recovery, so the next disconnect retries quickly again instead of
	// inheriting the escalated backoff from an earlier outage.
	listenBackoffResetAfter = 30 * time.Second
	listenMaxBackoff        = 30 * time.Second
)

// sessionChangeChannelFor returns the per-session NOTIFY channel name:
// "session_change_" + the UUID as 32 hex characters without dashes (47 chars,
// within Postgres' 63-char identifier limit).
func sessionChangeChannelFor(sessionID uuid.UUID) string {
	return sessionChangeChannelPrefix + strings.ReplaceAll(sessionID.String(), "-", "")
}

// sessionChangeBroker fans a single LISTEN connection out to in-process
// subscribers. Notifications are wake-up hints only: they carry no data and
// are lossy across reconnects, so subscribers must keep polling (at a relaxed
// interval) and treat the channel purely as a latency optimization.
type sessionChangeBroker struct {
	mu      sync.Mutex
	subs    map[uuid.UUID]map[int64]chan struct{}
	nextID  int64
	healthy atomic.Bool
}

func (b *sessionChangeBroker) subscribe(sessionID uuid.UUID) (<-chan struct{}, func()) {
	// Buffer one wake-up: a notification arriving while the watcher is busy
	// building a frame must not be lost, and more than one pending wake-up
	// is indistinguishable from one.
	ch := make(chan struct{}, 1)
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.subs == nil {
		b.subs = make(map[uuid.UUID]map[int64]chan struct{})
	}
	b.nextID++
	id := b.nextID
	if b.subs[sessionID] == nil {
		b.subs[sessionID] = make(map[int64]chan struct{})
	}
	b.subs[sessionID][id] = ch
	return ch, func() {
		b.mu.Lock()
		defer b.mu.Unlock()
		delete(b.subs[sessionID], id)
		if len(b.subs[sessionID]) == 0 {
			delete(b.subs, sessionID)
		}
	}
}

func (b *sessionChangeBroker) notify(sessionID uuid.UUID) {
	b.mu.Lock()
	defer b.mu.Unlock()
	for _, ch := range b.subs[sessionID] {
		select {
		case ch <- struct{}{}:
		default: // a wake-up is already pending
		}
	}
}

// SubscribeSessionChanges registers a wake-up hint channel for one session.
// Implements store.SessionChangeSubscriber. The channel receives (at least)
// one value after any committed change to the session; call cancel when the
// watcher ends. Wake-ups are delivered only while the listener is healthy —
// combine with SessionChangeListenerHealthy to pick the poll interval.
func (s *Store) SubscribeSessionChanges(sessionID uuid.UUID) (<-chan struct{}, func()) {
	return s.changes.subscribe(sessionID)
}

// SessionChangeListenerHealthy reports whether the LISTEN connection is
// currently established, i.e. whether wake-up hints are being delivered.
func (s *Store) SessionChangeListenerHealthy() bool {
	return s.changes.healthy.Load()
}

// StartSessionChangeListener starts the background LISTEN loop that feeds
// SubscribeSessionChanges for every session (the global session_change
// channel). It is optional: without it, subscribers simply never receive
// wake-ups and watchers fall back to their fast poll interval. The loop
// reconnects with backoff until ctx is cancelled.
func (s *Store) StartSessionChangeListener(ctx context.Context) {
	s.startListener(ctx, []string{sessionChangeChannel}, globalSessionChangeRouter)
}

// StartSessionChangeListenerFor is the agent-pod variant: it LISTENs only on
// the per-session channel for sessionID, so the pod is not woken by every
// other session in the fleet. Every notification on that channel is routed to
// subscribers of sessionID regardless of payload.
func (s *Store) StartSessionChangeListenerFor(ctx context.Context, sessionID uuid.UUID) {
	s.startListener(ctx, []string{sessionChangeChannelFor(sessionID)}, perSessionChangeRouter(sessionID))
}

// notificationRouter maps a raw notification to the session whose
// subscribers should be woken; ok=false drops it.
type notificationRouter func(channel, payload string) (id uuid.UUID, ok bool)

func globalSessionChangeRouter(channel, payload string) (uuid.UUID, bool) {
	if channel != sessionChangeChannel {
		return uuid.Nil, false
	}
	id, err := uuid.Parse(payload)
	return id, err == nil
}

func perSessionChangeRouter(sessionID uuid.UUID) notificationRouter {
	channel := sessionChangeChannelFor(sessionID)
	return func(ch, _ string) (uuid.UUID, bool) {
		return sessionID, ch == channel
	}
}

func (s *Store) startListener(ctx context.Context, channels []string, route notificationRouter) {
	go func() {
		backoff := time.Second
		for ctx.Err() == nil {
			listeningSince, err := s.runSessionChangeListener(ctx, channels, route)
			if ctx.Err() != nil {
				return
			}
			// Reset only after a connection that was actually LISTENing for a
			// while: a slow Acquire followed by a LISTEN failure must keep
			// backing off instead of hot-looping against an exhausted pool.
			if !listeningSince.IsZero() && time.Since(listeningSince) >= listenBackoffResetAfter {
				backoff = time.Second
			}
			log.Printf("WARN: session change listener disconnected (retrying in %s): %v", backoff, err)
			select {
			case <-ctx.Done():
				return
			case <-time.After(backoff):
			}
			if backoff < listenMaxBackoff {
				backoff *= 2
			}
		}
	}()
}

// runSessionChangeListener returns when the connection fails or ctx ends,
// together with the time LISTEN became active (zero when it never did).
func (s *Store) runSessionChangeListener(ctx context.Context, channels []string, route notificationRouter) (time.Time, error) {
	poolConn, err := s.pool.Acquire(ctx)
	if err != nil {
		return time.Time{}, err
	}
	// Hijack the connection: a connection with LISTEN state must never
	// return to the pool, where its notifications would leak into unrelated
	// queries.
	conn := poolConn.Hijack()
	defer func() {
		closeCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		_ = conn.Close(closeCtx)
	}()

	for _, channel := range channels {
		if _, err := conn.Exec(ctx, "LISTEN "+channel); err != nil {
			return time.Time{}, err
		}
	}
	listeningSince := time.Now()
	s.changes.healthy.Store(true)
	defer s.changes.healthy.Store(false)

	for {
		waitCtx, cancelWait := context.WithTimeout(ctx, listenLivenessInterval)
		notification, err := conn.WaitForNotification(waitCtx)
		cancelWait()
		if err != nil {
			if ctx.Err() != nil {
				return listeningSince, ctx.Err()
			}
			if !errors.Is(err, context.DeadlineExceeded) {
				return listeningSince, err
			}
			// Quiet period: verify the connection is still alive. A dead
			// socket surfaces here instead of hanging indefinitely.
			pingCtx, cancelPing := context.WithTimeout(ctx, listenPingTimeout)
			err = conn.Ping(pingCtx)
			cancelPing()
			if err != nil {
				return listeningSince, err
			}
			continue
		}
		sessionID, ok := route(notification.Channel, notification.Payload)
		if !ok {
			continue
		}
		s.changes.notify(sessionID)
	}
}

