// Migrate applies all pending migrations.
// Uses a simple version table to track applied migrations.
func Migrate(ctx context.Context, pool *pgxpool.Pool) error {
	conn, err := pool.Acquire(ctx)
	if err != nil {
		return fmt.Errorf("acquiring migration connection: %w", err)
	}
	defer conn.Release()

	const lockID int64 = 4143192210
	if _, err := conn.Exec(ctx, "SELECT pg_advisory_lock($1)", lockID); err != nil {
		return fmt.Errorf("acquiring migration advisory lock: %w", err)
	}
	defer func() {
		if _, err := conn.Exec(context.Background(), "SELECT pg_advisory_unlock($1)", lockID); err != nil && err != pgx.ErrNoRows {
			log.Printf("WARN: releasing migration advisory lock: %v", err)
		}
	}()

	if _, err := conn.Exec(ctx, `
		CREATE TABLE IF NOT EXISTS schema_migrations (
			version INT PRIMARY KEY,
			applied_at TIMESTAMPTZ NOT NULL DEFAULT now()
		)
	`); err != nil {
		return fmt.Errorf("creating schema_migrations table: %w", err)
	}

	migrations := orderedMigrations()

	for _, m := range migrations {
		var exists bool
		if err := conn.QueryRow(ctx, "SELECT EXISTS(SELECT 1 FROM schema_migrations WHERE version = $1)", m.version).Scan(&exists); err != nil {
			return fmt.Errorf("checking migration %d: %w", m.version, err)
		}
		if exists {
			continue
		}

		if noTxMigrations[m.version] {
			if err := applyNoTxMigration(ctx, conn, m.version, m.sql); err != nil {
				if m.optional {
					log.Printf("WARN: skipping optional migration %d: %v", m.version, err)
					continue
				}
				return err
			}
			continue
		}

		tx, err := conn.Begin(ctx)
		if err != nil {
			return fmt.Errorf("beginning transaction for migration %d: %w", m.version, err)
		}
		if _, err := tx.Exec(ctx, m.sql); err != nil {
			_ = tx.Rollback(ctx)
			if m.optional {
				log.Printf("WARN: skipping optional migration %d: %v", m.version, err)
				continue
			}
			return fmt.Errorf("applying migration %d: %w", m.version, err)
		}
		if _, err := tx.Exec(ctx, "INSERT INTO schema_migrations (version) VALUES ($1)", m.version); err != nil {
			_ = tx.Rollback(ctx)
			return fmt.Errorf("recording migration %d: %w", m.version, err)
		}
		if err := tx.Commit(ctx); err != nil {
			return fmt.Errorf("committing migration %d: %w", m.version, err)
		}
	}

	return nil
}

package postgres

import (
	"context"
	"encoding/json"
	"fmt"
	"math"
	"sort"
	"strings"
	"time"

	"github.com/google/uuid"
	agent "github.com/gratefulagents/sdk/pkg/agentsdk"
	sdkopenai "github.com/gratefulagents/sdk/pkg/agentsdk/providers/openai"

	"github.com/gratefulagents/gratefulagents/internal/store"
	"github.com/gratefulagents/gratefulagents/internal/usageaccounting"
)

type observabilitySession struct {
	id       uuid.UUID
	name     string
	created  time.Time
	metadata json.RawMessage
}

type observabilityEvent struct {
	id        int64
	sessionID uuid.UUID
	typ       string
	created   time.Time
	detail    json.RawMessage
}

// observabilityEventTypes are the only event types the aggregation reads.
// Filtering in SQL keeps chatty event types (assistant text, thinking deltas,
// tool output) from consuming the bounded event budget and silently dropping
// older metric events in busy ranges.
var observabilityEventTypes = []string{"tool_end", "subagent_status", "llm_attempt", "compact_boundary"}

// observabilityEventTypeList renders the metric event types as a SQL literal
// list. The predicate must be literal (not a bind parameter) and textually
// equivalent to migration 040's partial index predicate so the planner can
// use the index instead of scanning every chatty activity row in the window.
func observabilityEventTypeList() string {
	quoted := make([]string, len(observabilityEventTypes))
	for i, t := range observabilityEventTypes {
		quoted[i] = "'" + t + "'"
	}
	return strings.Join(quoted, ", ")
}

type breakdownAccumulator struct {
	value     store.ObservabilityBreakdown
	durations []float64
}

func (s *Store) GetObservabilityOverview(ctx context.Context, q store.ObservabilityQuery) (*store.ObservabilityOverview, error) {
	rows, err := s.pool.Query(ctx, `
SELECT id, agentrun_name, created_at, metadata
FROM agent_sessions
WHERE agentrun_ns = $1 AND created_at >= $2 AND created_at < $3
  AND agentrun_name = ANY($4::text[])
ORDER BY created_at, id`, q.Namespace, q.Start, q.End, q.AgentRunNames)
	if err != nil {
		return nil, err
	}
	var sessions []observabilitySession
	for rows.Next() {
		var row observabilitySession
		if err := rows.Scan(&row.id, &row.name, &row.created, &row.metadata); err != nil {
			rows.Close()
			return nil, err
		}
		sessions = append(sessions, row)
	}
	if err := rows.Err(); err != nil {
		rows.Close()
		return nil, err
	}
	rows.Close()

	// Metric events are streamed and folded into counters as they arrive: the
	// aggregator never retains the row set, so memory scales with the number
	// of distinct tool calls / attempts / subagent tasks in the range rather
	// than with the number of rows. A row cap here would silently amputate the
	// older part of the window — the headline spend would then report only the
	// most recent slice while claiming to cover the whole range.
	//
	// No ORDER BY: the reduction is order-independent (each lifecycle key
	// keeps its own earliest/latest row by (created_at, id)), so the planner
	// can stream straight from the partial index instead of sorting the whole
	// match set.
	types := observabilityEventTypeList()
	aggregator := newObservabilityAggregator(q, sessions)
	eventRows, err := s.pool.Query(ctx, `
SELECT e.id, e.session_id, e.event_type, e.created_at,
       e.detail - ARRAY['input_raw', 'output', 'message', 'subagent_prompt', 'subagent_result_text']::text[]
FROM activity_events e JOIN agent_sessions s ON s.id = e.session_id
WHERE s.agentrun_ns = $1
  AND e.created_at >= $2 AND e.created_at < $3
  AND s.agentrun_name = ANY($4::text[])
  AND (e.event_type IN (`+types+`) OR e.detail->>'type' IN (`+types+`))`,
		q.Namespace, q.Start, q.End, q.AgentRunNames)
	if err != nil {
		return nil, err
	}
	for eventRows.Next() {
		var event observabilityEvent
		if err := eventRows.Scan(&event.id, &event.sessionID, &event.typ, &event.created, &event.detail); err != nil {
			eventRows.Close()
			return nil, err
		}
		aggregator.add(event)
	}
	if err := eventRows.Err(); err != nil {
		eventRows.Close()
		return nil, err
	}
	eventRows.Close()
	overview := aggregator.finish()
	// The event query above is filtered to metric-relevant types, so derive
	// activity coverage from any event kind: a session that only produced
	// chatty events still has activity.
	var withActivity int64
	if err := s.pool.QueryRow(ctx, `
SELECT count(*) FROM agent_sessions s
WHERE s.agentrun_ns = $1 AND s.created_at >= $2 AND s.created_at < $3
  AND s.agentrun_name = ANY($4::text[])
  AND EXISTS (
    SELECT 1 FROM activity_events e
    WHERE e.session_id = s.id AND e.created_at >= $2 AND e.created_at < $3
  )`, q.Namespace, q.Start, q.End, q.AgentRunNames).Scan(&withActivity); err != nil {
		return nil, err
	}
	overview.Completeness.SessionsWithActivity = withActivity
	overview.Completeness.ActivityComplete = overview.Completeness.Sessions == withActivity
	return overview, nil
}

// aggregateObservability folds a materialized event slice; the store streams
// rows through the aggregator directly.
func aggregateObservability(q store.ObservabilityQuery, sessions []observabilitySession, events []observabilityEvent) *store.ObservabilityOverview {
	aggregator := newObservabilityAggregator(q, sessions)
	for _, event := range events {
		aggregator.add(event)
	}
	return aggregator.finish()
}

// observabilityAggregator folds metric events into overview counters as they
// stream out of Postgres. Only per-lifecycle-key state is retained, so memory
// scales with distinct tool calls / model attempts / subagent tasks instead of
// with the row count, and the whole selected range can be aggregated without a
// row cap that would silently drop its older half.
//
// The reduction is order-independent: each key remembers the (created_at, id)
// of the row it accepted and yields only to a strictly earlier row (tool
// calls, whose first terminal event is authoritative) or a strictly later row
// (model attempts and subagent tasks, whose latest lifecycle event wins). Rows
// may therefore arrive in any order, which lets the query skip an ORDER BY
// over the entire match set.
type observabilityAggregator struct {
	q                  store.ObservabilityQuery
	out                *store.ObservabilityOverview
	buckets            map[int64]*store.ObservabilityBucket
	snapshotSessionIDs map[uuid.UUID]struct{}
	activitySessions   map[uuid.UUID]struct{}
	tools              map[string]*observabilityToolState
	attempts           map[string]*observabilityAttemptState
	subagents          map[string]*observabilitySubagentState
}

// observabilityRowKey orders two rows of the same lifecycle key.
type observabilityRowKey struct {
	at time.Time
	id int64
}

func (k observabilityRowKey) before(other observabilityRowKey) bool {
	if !k.at.Equal(other.at) {
		return k.at.Before(other.at)
	}
	return k.id < other.id
}

type observabilityToolState struct {
	row      observabilityRowKey
	name     string
	isError  bool
	duration float64
}

type observabilityAttemptState struct {
	row       observabilityRowKey
	sessionID uuid.UUID
	model     string
	failed    bool
	cost      float64
	// repricedUSD is the portion of cost that was estimated at read time
	// because the producing run recorded no usable price. Run snapshots from
	// those runs are missing the same amount, so finish() folds it into the
	// snapshot cost totals as well.
	repricedUSD float64
	input       int64
	output      int64
	latency     float64
}

type observabilitySubagentState struct {
	row      observabilityRowKey
	name     string
	failed   bool
	cost     float64
	input    int64
	output   int64
	duration float64
}

func newObservabilityAggregator(q store.ObservabilityQuery, sessions []observabilitySession) *observabilityAggregator {
	a := &observabilityAggregator{
		q:                  q,
		out:                &store.ObservabilityOverview{},
		buckets:            map[int64]*store.ObservabilityBucket{},
		snapshotSessionIDs: make(map[uuid.UUID]struct{}, len(sessions)),
		activitySessions:   map[uuid.UUID]struct{}{},
		tools:              map[string]*observabilityToolState{},
		attempts:           map[string]*observabilityAttemptState{},
		subagents:          map[string]*observabilitySubagentState{},
	}
	a.out.Completeness.Sessions = int64(len(sessions))
	for at := q.Start; at.Before(q.End); at = at.Add(time.Duration(q.BucketSeconds) * time.Second) {
		a.bucket(at)
	}
	for _, session := range sessions {
		a.snapshotSessionIDs[session.id] = struct{}{}
		a.out.Totals.Runs++
		b := a.bucket(session.created)
		b.Totals.Runs++
		var metadata struct {
			Metrics *struct {
				CostUSD      float64 `json:"cost_usd"`
				InputTokens  int64   `json:"input_tokens"`
				OutputTokens int64   `json:"output_tokens"`
			} `json:"metrics"`
		}
		if json.Unmarshal(session.metadata, &metadata) == nil && metadata.Metrics != nil {
			a.out.Completeness.SessionsWithMetrics++
			a.out.Totals.CostUSD += metadata.Metrics.CostUSD
			a.out.Totals.InputTokens += metadata.Metrics.InputTokens
			a.out.Totals.OutputTokens += metadata.Metrics.OutputTokens
			b.Totals.CostUSD += metadata.Metrics.CostUSD
			b.Totals.InputTokens += metadata.Metrics.InputTokens
			b.Totals.OutputTokens += metadata.Metrics.OutputTokens
		}
	}
	a.out.Completeness.MetricsComplete = a.out.Completeness.Sessions == a.out.Completeness.SessionsWithMetrics
	return a
}

func (a *observabilityAggregator) bucket(at time.Time) *store.ObservabilityBucket {
	unix := a.q.Start.Unix() + (at.Unix()-a.q.Start.Unix())/a.q.BucketSeconds*a.q.BucketSeconds
	b := a.buckets[unix]
	if b == nil {
		b = &store.ObservabilityBucket{Start: time.Unix(unix, 0).UTC()}
		a.buckets[unix] = b
	}
	return b
}

func (a *observabilityAggregator) add(event observabilityEvent) {
	if _, ok := a.snapshotSessionIDs[event.sessionID]; ok {
		a.activitySessions[event.sessionID] = struct{}{}
	}
	var d map[string]any
	if json.Unmarshal(event.detail, &d) != nil {
		d = map[string]any{}
	}
	typ := event.typ
	if v := stringValue(d["type"]); v != "" {
		typ = v
	}
	row := observabilityRowKey{at: event.created, id: event.id}
	switch typ {
	case "tool_end":
		key := stringValue(d["tool_use_id"])
		if key == "" {
			// Events without a tool_use_id cannot be deduplicated; give each
			// its own key so none are collapsed into a single call.
			key = fmt.Sprintf("event-%d", event.id)
		}
		key = event.sessionID.String() + "/" + key
		name := stringValue(d["tool"])
		if name == "" {
			name = "unknown"
		}
		state := &observabilityToolState{row: row, name: name, isError: boolValue(d["is_error"]), duration: numberValue(d["tool_duration_ms"])}
		if current := a.tools[key]; current == nil || state.row.before(current.row) {
			a.tools[key] = state
		}
	case "subagent_status":
		task := stringValue(d["task_id"])
		status := strings.ToLower(stringValue(d["status"]))
		if task == "" || (status != "completed" && status != "failed" && status != "cancelled" && status != "stopped") {
			return
		}
		name := stringValue(d["subagent_type"])
		if name == "" {
			name = "unknown"
		}
		state := &observabilitySubagentState{
			row:  row,
			name: name,
			// Only genuine failures count against reliability; cancelled and
			// stopped tasks are user-initiated terminations, not errors.
			failed:   status == "failed",
			cost:     numberValue(d["subagent_cost_usd"]),
			input:    int64(numberValue(d["subagent_input_tokens"])),
			output:   int64(numberValue(d["subagent_output_tokens"])),
			duration: numberValue(d["subagent_duration_ms"]),
		}
		if current := a.subagents[event.sessionID.String()+"/"+task]; current == nil || current.row.before(state.row) {
			a.subagents[event.sessionID.String()+"/"+task] = state
		}
	case "llm_attempt":
		key := stringValue(d["tool_use_id"])
		if key == "" {
			key = fmt.Sprintf("event-%d", event.id)
		}
		key = event.sessionID.String() + "/" + key
		state := observabilityAttemptFromDetail(row, d)
		state.sessionID = event.sessionID
		if current := a.attempts[key]; current == nil || current.row.before(state.row) {
			a.attempts[key] = state
		}
	case "compact_boundary":
		b := a.bucket(event.created)
		a.out.Totals.Compactions++
		b.Totals.Compactions++
		reclaimed := int64(numberValue(d["tokens_before"]) - numberValue(d["tokens_after"]))
		reclaimed = max(reclaimed, 0)
		a.out.Totals.TokensReclaimed += reclaimed
		b.Totals.TokensReclaimed += reclaimed
	}
}

func observabilityAttemptFromDetail(row observabilityRowKey, d map[string]any) *observabilityAttemptState {
	status := stringValue(d["attempt_status"])
	if status == "" {
		status = stringValue(d["status"])
	}
	status = strings.ToLower(status)
	// A model failure is a provider/model error (failure_kind is set on
	// retrying/fallback/failed attempts) or an explicit error status, matching
	// the aliases GetRecentErrorActivity and isErrorContentEvent recognize.
	// User-initiated interruptions ("interrupted") are not failures.
	failed := stringValue(d["failure_kind"]) != ""
	switch status {
	case "failed", "retrying", "fallback", "error", "failure", "fatal":
		failed = true
	}
	provider := stringValue(d["provider"])
	name := stringValue(d["canonical_model"])
	if name == "" {
		name = stringValue(d["resolved_model"])
	}
	if name == "" {
		name = stringValue(d["model"])
	}
	if name == "" {
		name = "unknown"
	}
	if provider != "" && !strings.Contains(name, "/") {
		name = provider + "/" + name
	}
	inputTokens := int64(numberValue(firstValue(d, "input_tokens", "prompt_tokens")))
	outputTokens := int64(numberValue(firstValue(d, "output_tokens", "completion_tokens")))
	if !observabilityInputTokensIncludeCache(d, provider, name) {
		inputTokens += int64(numberValue(d["cache_read_input_tokens"])) + int64(numberValue(d["cache_creation_input_tokens"]))
	}
	cost := numberValue(d["cost_usd"])
	// Pricing is recorded when the attempt runs, but old SDKs did not know
	// every model alias. Keep an explicitly known (including legitimately
	// zero) or positive producer value; otherwise price OpenAI attempts from
	// their persisted token usage at read time. This makes pricing-table fixes
	// apply to historical observability without rewriting immutable activity
	// events.
	var repricedUSD float64
	if !boolValue(d["cost_known"]) && cost <= 0 && observabilityIsOpenAI(provider, name) {
		if estimated, known := sdkopenai.EstimateCost(name, agent.Usage{
			InputTokens:       inputTokens,
			OutputTokens:      outputTokens,
			CacheReadTokens:   int64(numberValue(d["cache_read_input_tokens"])),
			CacheCreateTokens: int64(numberValue(d["cache_creation_input_tokens"])),
		}); known {
			repricedUSD = estimated - cost
			cost = estimated
		}
	}
	return &observabilityAttemptState{
		row:         row,
		model:       name,
		failed:      failed,
		cost:        cost,
		repricedUSD: repricedUSD,
		input:       inputTokens,
		output:      outputTokens,
		latency:     numberValue(d["attempt_latency_ms"]),
	}
}

func observabilityIsOpenAI(provider, model string) bool {
	if strings.TrimSpace(provider) != "" {
		return usageaccounting.NormalizedIdentity(provider) == "openai"
	}
	return strings.HasPrefix(strings.ToLower(strings.TrimSpace(model)), "openai/")
}

// observabilityInputTokensIncludeCache reports whether an attempt's
// input_tokens already cover the cached prompt. The runner stamps the answer
// on the event; older events predate those flags, so fall back to the shared
// provider classification every usage reader uses (internal/usageaccounting).
// Assuming "already included" would silently erase the cached prompt — nearly
// the entire input of a warm Anthropic run.
func observabilityInputTokensIncludeCache(d map[string]any, provider, model string) bool {
	return usageaccounting.InputIncludesCache(
		boolValue(d["input_tokens_include_cache_known"]),
		boolValue(d["input_tokens_include_cache"]),
		provider, model,
	)
}

func (a *observabilityAggregator) finish() *store.ObservabilityOverview {
	tools := map[string]*breakdownAccumulator{}
	subagents := map[string]*breakdownAccumulator{}
	models := map[string]*breakdownAccumulator{}
	for _, state := range a.tools {
		b := a.bucket(state.row.at)
		acc := ensureBreakdown(tools, state.name)
		acc.value.Count++
		a.out.Totals.ToolCalls++
		b.Totals.ToolCalls++
		if state.isError {
			acc.value.Errors++
			a.out.Totals.ToolErrors++
			b.Totals.ToolErrors++
		}
		if state.duration > 0 {
			acc.durations = append(acc.durations, state.duration)
		}
	}
	for _, state := range a.attempts {
		b := a.bucket(state.row.at)
		a.out.Totals.LLMAttempts++
		b.Totals.LLMAttempts++
		if state.failed {
			a.out.Totals.LLMFailures++
			b.Totals.LLMFailures++
		}
		a.out.Totals.GenerationCostUSD += state.cost
		a.out.Totals.GenerationInputTokens += state.input
		a.out.Totals.GenerationOutputTokens += state.output
		b.Totals.GenerationCostUSD += state.cost
		b.Totals.GenerationInputTokens += state.input
		b.Totals.GenerationOutputTokens += state.output
		// An attempt priced at read time was recorded at $0 by its run, so the
		// run's immutable snapshot cost is missing the same amount. Fold the
		// correction into the snapshot totals too — but only for runs counted
		// in this range, so attempts spilling in from earlier sessions do not
		// inflate a cost their snapshot never contributed.
		if state.repricedUSD != 0 {
			if _, ok := a.snapshotSessionIDs[state.sessionID]; ok {
				a.out.Totals.CostUSD += state.repricedUSD
				b.Totals.CostUSD += state.repricedUSD
			}
		}
		acc := ensureBreakdown(models, state.model)
		acc.value.Count++
		if state.failed {
			acc.value.Errors++
		}
		acc.value.CostUSD += state.cost
		acc.value.InputTokens += state.input
		acc.value.OutputTokens += state.output
		if state.latency > 0 {
			acc.durations = append(acc.durations, state.latency)
		}
	}
	for _, state := range a.subagents {
		b := a.bucket(state.row.at)
		acc := ensureBreakdown(subagents, state.name)
		acc.value.Count++
		a.out.Totals.Subagents++
		b.Totals.Subagents++
		if state.failed {
			acc.value.Errors++
			a.out.Totals.SubagentFailures++
			b.Totals.SubagentFailures++
		}
		acc.value.CostUSD += state.cost
		acc.value.InputTokens += state.input
		acc.value.OutputTokens += state.output
		if state.duration > 0 {
			acc.durations = append(acc.durations, state.duration)
		}
	}
	a.out.Completeness.SessionsWithActivity = int64(len(a.activitySessions))
	a.out.Completeness.ActivityComplete = a.out.Completeness.Sessions == a.out.Completeness.SessionsWithActivity
	for _, b := range a.buckets {
		a.out.Buckets = append(a.out.Buckets, *b)
	}
	sort.Slice(a.out.Buckets, func(i, j int) bool { return a.out.Buckets[i].Start.Before(a.out.Buckets[j].Start) })
	a.out.Tools = finishBreakdowns(tools)
	a.out.Subagents = finishBreakdowns(subagents)
	a.out.Models = finishBreakdowns(models)
	return a.out
}

func ensureBreakdown(values map[string]*breakdownAccumulator, name string) *breakdownAccumulator {
	if values[name] == nil {
		values[name] = &breakdownAccumulator{value: store.ObservabilityBreakdown{Name: name}}
	}
	return values[name]
}

func finishBreakdowns(values map[string]*breakdownAccumulator) []store.ObservabilityBreakdown {
	out := make([]store.ObservabilityBreakdown, 0, len(values))
	for _, a := range values {
		sort.Float64s(a.durations)
		if len(a.durations) > 0 {
			var sum float64
			for _, d := range a.durations {
				sum += d
			}
			a.value.AverageDurationMS = sum / float64(len(a.durations))
			a.value.P95DurationMS = a.durations[int(math.Ceil(.95*float64(len(a.durations))))-1]
		}
		out = append(out, a.value)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Count != out[j].Count {
			return out[i].Count > out[j].Count
		}
		return out[i].Name < out[j].Name
	})
	return out
}

func stringValue(v any) string  { s, _ := v.(string); return strings.TrimSpace(s) }
func boolValue(v any) bool      { b, _ := v.(bool); return b }
func numberValue(v any) float64 { n, _ := v.(float64); return n }
func firstValue(d map[string]any, keys ...string) any {
	for _, k := range keys {
		if _, ok := d[k]; ok {
			return d[k]
		}
	}
	return nil
}

package postgres

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"

	"github.com/gratefulagents/gratefulagents/internal/store"
)

const contentColumns = `c.id, c.project_namespace, c.project_name, c.kind, c.path, c.media_type, c.current_version,
	c.metadata, c.provenance, c.scan_status, c.created_at, c.updated_at, c.deleted_at,
	COALESCE(v.size, 0), COALESCE(v.sha256, ''), COALESCE(v.creator, '')`

// contentSelect joins each item with its current version's metadata (never the
// bytes) so listings and lookups stay cheap regardless of file sizes. The join
// is LEFT because confirmed deletion purges version rows to recover quota
// while keeping the item row for auditing and include_deleted listings.
const contentSelect = `SELECT ` + contentColumns + ` FROM project_content c
	LEFT JOIN project_content_versions v ON v.content_id = c.id AND v.version = c.current_version`

// contentRowColumns lists the project_content columns available on INSERT and
// UPDATE ... RETURNING, where the current-version join is not available.
const contentRowColumns = `id, project_namespace, project_name, kind, path, media_type, current_version,
	metadata, provenance, scan_status, created_at, updated_at, deleted_at`

func (s *Store) ListContent(ctx context.Context, projectNamespace, projectName string, includeDeleted bool) ([]store.ProjectContent, error) {
	query := contentSelect + `
		WHERE c.project_namespace = $1 AND c.project_name = $2`
	if !includeDeleted {
		query += ` AND c.deleted_at IS NULL`
	}
	query += ` ORDER BY c.path`

	rows, err := s.pool.Query(ctx, query, projectNamespace, projectName)
	if err != nil {
		return nil, fmt.Errorf("listing project content: %w", err)
	}
	defer rows.Close()

	content := make([]store.ProjectContent, 0)
	for rows.Next() {
		item, err := scanContent(rows)
		if err != nil {
			return nil, err
		}
		content = append(content, item)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("listing project content: %w", err)
	}
	return content, nil
}

func (s *Store) GetContent(ctx context.Context, id uuid.UUID) (*store.ProjectContent, error) {
	item, err := getContent(ctx, s.pool, id, false)
	if err != nil {
		return nil, err
	}
	return &item, nil
}

func (s *Store) GetContentVersion(ctx context.Context, id uuid.UUID, version int) (*store.ProjectContentVersion, error) {
	query := `SELECT v.content_id, v.version, v.content, v.object_key, v.sha256, v.size, v.creator, v.metadata, v.created_at
		FROM project_content_versions v
		JOIN project_content c ON c.id = v.content_id
		WHERE v.content_id = $1 AND v.version = CASE WHEN $2 = 0 THEN c.current_version ELSE $2 END`
	item, err := scanContentVersion(s.pool.QueryRow(ctx, query, id, version))
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, store.ErrContentNotFound
	}
	if err != nil {
		return nil, fmt.Errorf("getting project content version: %w", err)
	}
	if err := s.loadProjectContentVersion(ctx, &item, true); err != nil {
		return nil, err
	}
	return &item, nil
}

func (s *Store) CreateContent(ctx context.Context, opts store.CreateContentOptions) (*store.ProjectContent, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, fmt.Errorf("beginning project content creation: %w", err)
	}
	defer tx.Rollback(ctx)

	item, err := insertContent(ctx, tx, opts)
	if err != nil {
		return nil, err
	}
	if err := s.insertContentVersion(ctx, tx, &item, 1, opts.Content, opts.Actor, item.Metadata); err != nil {
		return nil, err
	}
	stagedObjectKey := s.stagedProjectContentObjectKey(item.ID, 1, item.ContentHash)
	defer s.cleanupStagedProjectContentObject(&stagedObjectKey)
	if err := insertContentAudit(ctx, tx, item.ID, "create", opts.Actor, map[string]any{"version": 1}); err != nil {
		return nil, err
	}
	// A commit error is ambiguous: the transaction may have committed. Never
	// delete its object after crossing the commit boundary.
	stagedObjectKey = ""
	if err := tx.Commit(ctx); err != nil {
		return nil, fmt.Errorf("committing project content creation: %w", err)
	}
	stagedObjectKey = ""
	return &item, nil
}

func (s *Store) UpdateContent(ctx context.Context, id uuid.UUID, opts store.UpdateContentOptions) (*store.ProjectContent, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, fmt.Errorf("beginning project content update: %w", err)
	}
	defer tx.Rollback(ctx)

	item, err := getContent(ctx, tx, id, true)
	if err != nil {
		return nil, err
	}
	if item.CurrentVersion != opts.ExpectedVersion {
		return nil, store.ErrContentConflict
	}
	if opts.Content != nil && !opts.OverwriteConfirmed {
		return nil, store.ErrContentConfirmationRequired
	}
	if opts.Path != nil {
		item.Path = *opts.Path
	}
	if opts.MediaType != nil {
		item.MediaType = *opts.MediaType
	}
	if opts.Metadata != nil {
		item.Metadata = jsonOrEmpty(*opts.Metadata)
	}
	if opts.Provenance != nil {
		item.Provenance = jsonOrEmpty(*opts.Provenance)
	}
	if opts.ScanStatus != nil {
		item.ScanStatus = *opts.ScanStatus
	}
	if opts.Content != nil {
		item.CurrentVersion++
	}

	updated, err := updateContent(ctx, tx, item)
	if err != nil {
		return nil, err
	}
	stagedObjectKey := ""
	defer s.cleanupStagedProjectContentObject(&stagedObjectKey)
	if opts.Content != nil {
		if err := s.insertContentVersion(ctx, tx, &updated, updated.CurrentVersion, *opts.Content, opts.Actor, updated.Metadata); err != nil {
			return nil, err
		}
		stagedObjectKey = s.stagedProjectContentObjectKey(updated.ID, updated.CurrentVersion, updated.ContentHash)
	}
	details := map[string]any{"version": updated.CurrentVersion}
	if opts.Content != nil {
		details["content_changed"] = true
	}
	if err := insertContentAudit(ctx, tx, id, "update", opts.Actor, details); err != nil {
		return nil, err
	}
	stagedObjectKey = ""
	if err := tx.Commit(ctx); err != nil {
		return nil, fmt.Errorf("committing project content update: %w", err)
	}
	stagedObjectKey = ""
	return &updated, nil
}

func (s *Store) DuplicateContent(ctx context.Context, id uuid.UUID, opts store.DuplicateContentOptions) (*store.ProjectContent, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, fmt.Errorf("beginning project content duplication: %w", err)
	}
	defer tx.Rollback(ctx)

	source, err := getContent(ctx, tx, id, true)
	if err != nil {
		return nil, err
	}
	if source.CurrentVersion != opts.ExpectedVersion {
		return nil, store.ErrContentConflict
	}
	version, err := getContentVersion(ctx, tx, id, source.CurrentVersion)
	if err != nil {
		return nil, err
	}
	if err := s.loadProjectContentVersion(ctx, &version, false); err != nil {
		return nil, err
	}
	create := store.CreateContentOptions{
		ProjectNamespace: source.ProjectNamespace,
		ProjectName:      source.ProjectName,
		Kind:             source.Kind,
		Path:             opts.Path,
		MediaType:        source.MediaType,
		Content:          version.Content,
		Metadata:         source.Metadata,
		Provenance:       source.Provenance,
		ScanStatus:       source.ScanStatus,
		Actor:            opts.Actor,
	}
	if opts.ProjectNamespace != "" {
		create.ProjectNamespace = opts.ProjectNamespace
	}
	if opts.ProjectName != "" {
		create.ProjectName = opts.ProjectName
	}
	if opts.Kind != nil {
		create.Kind = *opts.Kind
	}
	if opts.MediaType != nil {
		create.MediaType = *opts.MediaType
	}
	if opts.Metadata != nil {
		create.Metadata = *opts.Metadata
	}
	if opts.Provenance != nil {
		create.Provenance = *opts.Provenance
	}
	if opts.ScanStatus != nil {
		create.ScanStatus = *opts.ScanStatus
	}

	item, err := insertContent(ctx, tx, create)
	if err != nil {
		return nil, err
	}
	if err := s.insertContentVersion(ctx, tx, &item, 1, version.Content, opts.Actor, item.Metadata); err != nil {
		return nil, err
	}
	stagedObjectKey := s.stagedProjectContentObjectKey(item.ID, 1, item.ContentHash)
	defer s.cleanupStagedProjectContentObject(&stagedObjectKey)
	if err := insertContentAudit(ctx, tx, item.ID, "duplicate", opts.Actor, map[string]any{"source_content_id": id.String(), "source_version": source.CurrentVersion}); err != nil {
		return nil, err
	}
	stagedObjectKey = ""
	if err := tx.Commit(ctx); err != nil {
		return nil, fmt.Errorf("committing project content duplication: %w", err)
	}
	stagedObjectKey = ""
	return &item, nil
}

func (s *Store) RestoreContent(ctx context.Context, id uuid.UUID, version int, opts store.RestoreContentOptions) (*store.ProjectContent, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, fmt.Errorf("beginning project content restoration: %w", err)
	}
	defer tx.Rollback(ctx)

	item, err := getContent(ctx, tx, id, true)
	if err != nil {
		return nil, err
	}
	if item.CurrentVersion != opts.ExpectedVersion {
		return nil, store.ErrContentConflict
	}
	restored, err := getContentVersion(ctx, tx, id, version)
	if err != nil {
		return nil, err
	}
	if err := s.loadProjectContentVersion(ctx, &restored, false); err != nil {
		return nil, err
	}
	item.CurrentVersion++
	updated, err := updateContent(ctx, tx, item)
	if err != nil {
		return nil, err
	}
	if err := s.insertContentVersion(ctx, tx, &updated, updated.CurrentVersion, restored.Content, opts.Actor, restored.Metadata); err != nil {
		return nil, err
	}
	stagedObjectKey := s.stagedProjectContentObjectKey(updated.ID, updated.CurrentVersion, updated.ContentHash)
	defer s.cleanupStagedProjectContentObject(&stagedObjectKey)
	if err := insertContentAudit(ctx, tx, id, "restore", opts.Actor, map[string]any{"version": updated.CurrentVersion, "restored_version": restored.Version}); err != nil {
		return nil, err
	}
	stagedObjectKey = ""
	if err := tx.Commit(ctx); err != nil {
		return nil, fmt.Errorf("committing project content restoration: %w", err)
	}
	stagedObjectKey = ""
	return &updated, nil
}

func (s *Store) SoftDeleteContent(ctx context.Context, id uuid.UUID, opts store.SoftDeleteContentOptions) error {
	if !opts.Confirmed {
		return store.ErrContentConfirmationRequired
	}
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return fmt.Errorf("beginning project content deletion: %w", err)
	}
	defer tx.Rollback(ctx)

	item, err := getContent(ctx, tx, id, true)
	if err != nil {
		return err
	}
	if item.CurrentVersion != opts.ExpectedVersion {
		return store.ErrContentConflict
	}
	var objectKeys []string
	if item.DeletedAt == nil {
		rows, queryErr := tx.Query(ctx, `SELECT object_key FROM project_content_versions WHERE content_id = $1 AND object_key <> ''`, id)
		if queryErr != nil {
			return fmt.Errorf("listing project content objects for deletion: %w", queryErr)
		}
		for rows.Next() {
			var key string
			if scanErr := rows.Scan(&key); scanErr != nil {
				rows.Close()
				return fmt.Errorf("reading project content object for deletion: %w", scanErr)
			}
			objectKeys = append(objectKeys, key)
		}
		rows.Close()
		if rows.Err() != nil {
			return fmt.Errorf("listing project content objects for deletion: %w", rows.Err())
		}
		if len(objectKeys) > 0 && s.contentBlobs == nil {
			return fmt.Errorf("cannot delete S3-backed project content without a configured blob store")
		}
		for _, key := range objectKeys {
			if _, err := tx.Exec(ctx, `INSERT INTO project_content_blob_deletions (object_key) VALUES ($1)
				ON CONFLICT (object_key) DO NOTHING`, key); err != nil {
				return fmt.Errorf("recording project content object deletion %q: %w", key, err)
			}
		}
	}
	if item.DeletedAt == nil {
		if _, err := tx.Exec(ctx, `UPDATE project_content SET deleted_at = now(), updated_at = now() WHERE id = $1`, id); err != nil {
			return fmt.Errorf("soft deleting project content: %w", err)
		}
		// Deletion is confirmed as permanent, so purge the version bytes to
		// recover the project storage quota. The item row survives for
		// auditing and include_deleted listings.
		if _, err := tx.Exec(ctx, `DELETE FROM project_content_versions WHERE content_id = $1`, id); err != nil {
			return fmt.Errorf("purging project content versions: %w", err)
		}
		if err := insertContentAudit(ctx, tx, id, "soft_delete", opts.Actor, map[string]any{"version": item.CurrentVersion, "versions_purged": true}); err != nil {
			return err
		}
	}
	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("committing project content deletion: %w", err)
	}
	for _, key := range objectKeys {
		if err := s.deletePendingProjectContentBlob(ctx, key); err != nil {
			// The durable outbox retains the key for the background reconciler.
			log.Printf("WARN: project content object %q remains pending deletion: %v", key, err)
		}
	}
	return nil
}

// ReconcileProjectContentBlobDeletions retries durable S3 deletion outbox
// entries. It is safe to call concurrently; object deletion is idempotent.
func (s *Store) ReconcileProjectContentBlobDeletions(ctx context.Context, limit int) error {
	if s.contentBlobs == nil {
		return nil
	}
	if limit <= 0 {
		limit = 100
	}
	rows, err := s.pool.Query(ctx, `SELECT object_key FROM project_content_blob_deletions
		WHERE next_attempt_at <= now() ORDER BY created_at LIMIT $1`, limit)
	if err != nil {
		return fmt.Errorf("listing pending project content blob deletions: %w", err)
	}
	var keys []string
	for rows.Next() {
		var key string
		if err := rows.Scan(&key); err != nil {
			rows.Close()
			return fmt.Errorf("reading pending project content blob deletion: %w", err)
		}
		keys = append(keys, key)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return fmt.Errorf("listing pending project content blob deletions: %w", err)
	}
	for _, key := range keys {
		if err := s.deletePendingProjectContentBlob(ctx, key); err != nil {
			log.Printf("WARN: retrying project content object deletion %q: %v", key, err)
		}
	}
	return nil
}

func (s *Store) deletePendingProjectContentBlob(ctx context.Context, key string) error {
	if s.contentBlobs == nil {
		return fmt.Errorf("project content blob store is not configured")
	}
	if err := s.contentBlobs.Delete(ctx, key); err != nil {
		_, recordErr := s.pool.Exec(ctx, `UPDATE project_content_blob_deletions
			SET attempts = attempts + 1, last_error = $2,
				next_attempt_at = now() + LEAST(attempts + 1, 60) * interval '1 minute'
			WHERE object_key = $1`, key, err.Error())
		if recordErr != nil {
			return fmt.Errorf("deleting S3 object: %v (also failed to record retry: %w)", err, recordErr)
		}
		return err
	}
	if _, err := s.pool.Exec(ctx, `DELETE FROM project_content_blob_deletions WHERE object_key = $1`, key); err != nil {
		return fmt.Errorf("clearing completed project content blob deletion %q: %w", key, err)
	}
	return nil
}

func (s *Store) RecordContentAudit(ctx context.Context, id uuid.UUID, action, actor string, details json.RawMessage) error {
	if len(details) == 0 {
		details = json.RawMessage(`{}`)
	}
	if _, err := s.pool.Exec(ctx, `INSERT INTO project_content_audits (content_id, action, actor, details) VALUES ($1, $2, $3, $4)`, id, action, actor, details); err != nil {
		return fmt.Errorf("recording project content access: %w", err)
	}
	return nil
}

func (s *Store) ListContentVersions(ctx context.Context, id uuid.UUID) ([]store.ProjectContentVersion, error) {
	rows, err := s.pool.Query(ctx, `SELECT content_id, version, ''::bytea, object_key, sha256, size, creator, metadata, created_at
		FROM project_content_versions WHERE content_id = $1 ORDER BY version DESC`, id)
	if err != nil {
		return nil, fmt.Errorf("listing project content versions: %w", err)
	}
	defer rows.Close()

	versions := make([]store.ProjectContentVersion, 0)
	for rows.Next() {
		version, err := scanContentVersion(rows)
		if err != nil {
			return nil, err
		}
		versions = append(versions, version)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("listing project content versions: %w", err)
	}
	if len(versions) == 0 {
		return nil, store.ErrContentNotFound
	}
	return versions, nil
}

type contentQuerier interface {
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}

type contentExecutor interface {
	contentQuerier
	Exec(ctx context.Context, sql string, arguments ...any) (pgconn.CommandTag, error)
}

func getContent(ctx context.Context, q contentQuerier, id uuid.UUID, forUpdate bool) (store.ProjectContent, error) {
	query := contentSelect + ` WHERE c.id = $1`
	if forUpdate {
		query += ` FOR UPDATE OF c`
	}
	item, err := scanContent(q.QueryRow(ctx, query, id))
	if errors.Is(err, pgx.ErrNoRows) {
		return store.ProjectContent{}, store.ErrContentNotFound
	}
	if err != nil {
		return store.ProjectContent{}, fmt.Errorf("getting project content: %w", err)
	}
	return item, nil
}

func getContentVersion(ctx context.Context, q contentQuerier, id uuid.UUID, version int) (store.ProjectContentVersion, error) {
	item, err := scanContentVersion(q.QueryRow(ctx, `SELECT content_id, version, content, object_key, sha256, size, creator, metadata, created_at
		FROM project_content_versions WHERE content_id = $1 AND version = $2`, id, version))
	if errors.Is(err, pgx.ErrNoRows) {
		return store.ProjectContentVersion{}, store.ErrContentNotFound
	}
	if err != nil {
		return store.ProjectContentVersion{}, fmt.Errorf("getting project content version: %w", err)
	}
	return item, nil
}

func insertContent(ctx context.Context, tx contentExecutor, opts store.CreateContentOptions) (store.ProjectContent, error) {
	item, err := scanContentRow(tx.QueryRow(ctx, `INSERT INTO project_content
		(project_namespace, project_name, kind, path, media_type, metadata, provenance, scan_status)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
		RETURNING `+contentRowColumns,
		opts.ProjectNamespace, opts.ProjectName, opts.Kind, opts.Path, opts.MediaType,
		jsonOrEmpty(opts.Metadata), jsonOrEmpty(opts.Provenance), opts.ScanStatus))
	if isContentPathConflict(err) {
		return store.ProjectContent{}, store.ErrContentConflict
	}
	if err != nil {
		return store.ProjectContent{}, fmt.Errorf("creating project content: %w", err)
	}
	return item, nil
}

func updateContent(ctx context.Context, tx contentExecutor, item store.ProjectContent) (store.ProjectContent, error) {
	updated, err := scanContentRow(tx.QueryRow(ctx, `UPDATE project_content
		SET path = $2, media_type = $3, current_version = $4, metadata = $5, provenance = $6, scan_status = $7, updated_at = now()
		WHERE id = $1 RETURNING `+contentRowColumns,
		item.ID, item.Path, item.MediaType, item.CurrentVersion, jsonOrEmpty(item.Metadata), jsonOrEmpty(item.Provenance), item.ScanStatus))
	if isContentPathConflict(err) {
		return store.ProjectContent{}, store.ErrContentConflict
	}
	if err != nil {
		return store.ProjectContent{}, fmt.Errorf("updating project content: %w", err)
	}
	// Carry over current-version metadata; callers overwrite it when a new
	// version is inserted in the same transaction.
	updated.SizeBytes, updated.ContentHash, updated.CreatedBy = item.SizeBytes, item.ContentHash, item.CreatedBy
	return updated, nil
}

func (s *Store) insertContentVersion(ctx context.Context, tx contentExecutor, item *store.ProjectContent, version int, content []byte, creator string, metadata json.RawMessage) error {
	if err := checkContentQuota(ctx, tx, item.ProjectNamespace, item.ProjectName, int64(len(content))); err != nil {
		return err
	}
	digest := sha256.Sum256(content)
	hash := hex.EncodeToString(digest[:])
	// Keep the BYTEA compatibility copy during the rolling S3 cutover. New
	// readers prefer object_key; old replicas and rollback binaries can still
	// serve the exact bytes until a later migration removes the compatibility
	// copy after the fleet and backfill have been verified.
	storedContent := content
	objectKey := ""
	if s.contentBlobs != nil {
		objectKey = projectContentObjectKey(item.ID, version, hash)
		if err := s.contentBlobs.Put(ctx, objectKey, content, item.MediaType); err != nil {
			return fmt.Errorf("storing project content version body: %w", err)
		}
	}
	_, err := tx.Exec(ctx, `INSERT INTO project_content_versions
		(content_id, version, content, object_key, sha256, size, creator, metadata)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8)`,
		item.ID, version, storedContent, objectKey, hash, int64(len(content)), creator, jsonOrEmpty(metadata))
	if err != nil {
		if objectKey != "" {
			s.cleanupStagedProjectContentObject(&objectKey)
		}
		return fmt.Errorf("creating project content version: %w", err)
	}
	item.SizeBytes, item.ContentHash, item.CreatedBy = int64(len(content)), hash, creator
	return nil
}

func projectContentObjectKey(id uuid.UUID, version int, hash string) string {
	return fmt.Sprintf("project-content/v1/%s/%d-%s", id.String(), version, hash)
}

func (s *Store) stagedProjectContentObjectKey(id uuid.UUID, version int, hash string) string {
	if s.contentBlobs == nil {
		return ""
	}
	return projectContentObjectKey(id, version, hash)
}

func (s *Store) cleanupStagedProjectContentObject(key *string) {
	if key == nil || *key == "" || s.contentBlobs == nil {
		return
	}
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := s.contentBlobs.Delete(ctx, *key); err != nil {
		if recordErr := s.recordProjectContentBlobDeletion(context.Background(), *key, err); recordErr != nil {
			log.Printf("WARN: cleaning up uncommitted project content object %q: %v (also failed to record retry: %v)", *key, err, recordErr)
		}
	}
}

func (s *Store) recordProjectContentBlobDeletion(ctx context.Context, key string, cause error) error {
	lastError := ""
	if cause != nil {
		lastError = cause.Error()
	}
	_, err := s.pool.Exec(ctx, `INSERT INTO project_content_blob_deletions (object_key, attempts, last_error)
		VALUES ($1, 1, $2)
		ON CONFLICT (object_key) DO UPDATE SET
			attempts = project_content_blob_deletions.attempts + 1,
			last_error = EXCLUDED.last_error,
			next_attempt_at = now() + interval '1 minute'`, key, lastError)
	return err
}

func (s *Store) loadProjectContentVersion(ctx context.Context, version *store.ProjectContentVersion, promoteLegacy bool) error {
	if version.ObjectKey == "" {
		if s.contentBlobs == nil || !promoteLegacy {
			return nil
		}
		key := projectContentObjectKey(version.ContentID, version.Version, version.SHA256)
		if err := s.contentBlobs.Put(ctx, key, version.Content, "application/octet-stream"); err != nil {
			// Legacy BYTEA content remains a valid, available fallback during an
			// S3 outage; promotion can be retried on the next read.
			log.Printf("WARN: lazy S3 promotion failed for project content %s version %d: %v", version.ContentID, version.Version, err)
			return nil
		}
		tag, err := s.pool.Exec(ctx, `UPDATE project_content_versions SET object_key = $3
			WHERE content_id = $1 AND version = $2 AND object_key = ''`, version.ContentID, version.Version, key)
		if err != nil {
			log.Printf("WARN: recording lazy S3 promotion for project content %s version %d: %v", version.ContentID, version.Version, err)
			return nil
		}
		if tag.RowsAffected() > 0 {
			version.ObjectKey = key
			return nil
		}
		// The row may have been deleted or concurrently promoted. Only remove
		// this upload after proving no surviving row references it.
		var recordedKey string
		queryErr := s.pool.QueryRow(ctx, `SELECT object_key FROM project_content_versions
			WHERE content_id = $1 AND version = $2`, version.ContentID, version.Version).Scan(&recordedKey)
		if (errors.Is(queryErr, pgx.ErrNoRows) || queryErr == nil && recordedKey != key) && s.contentBlobs != nil {
			if deleteErr := s.contentBlobs.Delete(ctx, key); deleteErr != nil {
				if recordErr := s.recordProjectContentBlobDeletion(context.Background(), key, deleteErr); recordErr != nil {
					log.Printf("WARN: cleaning unreferenced promoted project content object %q: %v (also failed to record retry: %v)", key, deleteErr, recordErr)
				}
			}
		}
		if queryErr == nil && recordedKey == key {
			version.ObjectKey = key
		}
		return nil
	}
	if s.contentBlobs == nil {
		return fmt.Errorf("project content body %q is in S3 but no blob store is configured", version.ObjectKey)
	}
	content, err := s.contentBlobs.Get(ctx, version.ObjectKey)
	if err != nil {
		return fmt.Errorf("loading project content version body: %w", err)
	}
	if int64(len(content)) != version.Size {
		return fmt.Errorf("project content body %q size mismatch: got %d, want %d", version.ObjectKey, len(content), version.Size)
	}
	digest := sha256.Sum256(content)
	if hash := hex.EncodeToString(digest[:]); hash != version.SHA256 {
		return fmt.Errorf("project content body %q hash mismatch", version.ObjectKey)
	}
	version.Content = content
	return nil
}

// checkContentQuota enforces the per-project cap on total stored bytes before
// a new version is written inside the caller's transaction.
func checkContentQuota(ctx context.Context, q contentQuerier, projectNamespace, projectName string, additional int64) error {
	var total int64
	err := q.QueryRow(ctx, `SELECT COALESCE(SUM(v.size), 0)
		FROM project_content_versions v
		JOIN project_content c ON c.id = v.content_id
		WHERE c.project_namespace = $1 AND c.project_name = $2 AND c.deleted_at IS NULL`, projectNamespace, projectName).Scan(&total)
	if err != nil {
		return fmt.Errorf("checking project content quota: %w", err)
	}
	if total+additional > store.MaxProjectContentTotalBytes {
		return store.ErrContentQuotaExceeded
	}
	return nil
}

func insertContentAudit(ctx context.Context, tx contentExecutor, id uuid.UUID, action, actor string, details any) error {
	data, err := json.Marshal(details)
	if err != nil {
		return fmt.Errorf("marshalling project content audit details: %w", err)
	}
