const setSecurityFindingStatusSQL = `
	UPDATE security_findings f SET
		status = $3,
		accepted_risk_expires_at = $4,
		triaged_at = CASE WHEN $3 <> 'open' THEN COALESCE(f.triaged_at, now()) ELSE f.triaged_at END
	FROM security_findings prev
	WHERE f.namespace = $1 AND f.id = $2 AND prev.id = f.id
	RETURNING prev.status`

func (s *Store) SetSecurityFindingStatus(ctx context.Context, namespace string, id uuid.UUID, status, actor, note string, opts store.SetSecurityFindingStatusOpts) error {
	if err := requireSecurityNamespace(namespace); err != nil {
		return err
	}
	if !store.ValidSecurityFindingStatus(status) {
		return fmt.Errorf("invalid security finding status %q", status)
	}
	if status == store.SecurityFindingStatusAcceptedRisk && !opts.HumanActor {
		return store.ErrSecurityFindingAcceptedRiskHumanOnly
	}
	acceptedRiskExpiresAt := opts.AcceptedRiskExpiresAt
	if acceptedRiskExpiresAt != nil && status != store.SecurityFindingStatusAcceptedRisk {
		return fmt.Errorf("accepted-risk expiry requires status %q, got %q", store.SecurityFindingStatusAcceptedRisk, status)
	}
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return fmt.Errorf("beginning status update: %w", err)
	}
	defer func() { _ = tx.Rollback(ctx) }()

	// A non-accepted_risk status always clears a stored expiry so a stale
	// deadline can never re-open a finding that was re-triaged.
	var expiry *time.Time
	if status == store.SecurityFindingStatusAcceptedRisk {
		expiry = acceptedRiskExpiresAt
	}
	var previous string
	err = tx.QueryRow(ctx, setSecurityFindingStatusSQL, namespace, id, status, expiry).Scan(&previous)
	if errors.Is(err, pgx.ErrNoRows) {
		return store.ErrSecurityFindingNotFound
	}
	if err != nil {
		return fmt.Errorf("updating security finding status: %w", err)
	}

	detailMap := map[string]string{"from": previous, "to": status}
	if expiry != nil {
		detailMap["accepted_risk_expires_at"] = expiry.UTC().Format(time.RFC3339)
	}
	detail, err := json.Marshal(detailMap)
	if err != nil {
		return fmt.Errorf("encoding status detail: %w", err)
	}
	eventType := securityFindingStatusEventType(previous, status)
	if _, err := tx.Exec(ctx, `
		INSERT INTO security_finding_events (finding_id, event_type, actor, note, detail)
		VALUES ($1, $2, $3, $4, $5)`, id, eventType, actor, note, detail); err != nil {
		return fmt.Errorf("recording status event: %w", err)
	}
	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("committing status update: %w", err)
	}
	return nil
}

func securityFindingStatusEventType(previous, next string) string {
	if previous == next {
		// Post-scan validation steps deliberately retain terminal states while
		// attaching fresh evidence in note. Calling those reviews a status
		// change produces misleading "confirmed -> confirmed" audit entries.
		return "status_reviewed"
	}
	return "status_changed"
}

func (s *Store) MarkSecurityFindingDuplicate(ctx context.Context, namespace string, findingID, canonicalID uuid.UUID, actor, note string) error {
	if err := requireSecurityNamespace(namespace); err != nil {
		return err
	}
	if findingID == canonicalID {
		return fmt.Errorf("a finding cannot be a duplicate of itself")
	}
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return fmt.Errorf("beginning duplicate update: %w", err)
	}
	defer func() { _ = tx.Rollback(ctx) }()

	var canonicalFingerprint string
	err = tx.QueryRow(ctx, `
		SELECT c.fingerprint
		FROM security_findings c
		JOIN security_findings f ON f.namespace = c.namespace AND f.scan_name = c.scan_name AND f.repository = c.repository
		WHERE c.namespace = $1 AND c.id = $2 AND f.id = $3 AND c.duplicate_of IS NULL`,
		namespace, canonicalID, findingID).Scan(&canonicalFingerprint)
	if errors.Is(err, pgx.ErrNoRows) {
		return store.ErrSecurityFindingNotFound
	}
	if err != nil {
		return fmt.Errorf("resolving canonical finding: %w", err)
	}
	tag, err := tx.Exec(ctx, `UPDATE security_findings SET duplicate_of = $3 WHERE namespace = $1 AND id = $2`, namespace, findingID, canonicalID)
	if err != nil {
		return fmt.Errorf("marking security finding duplicate: %w", err)
	}
	if tag.RowsAffected() == 0 {
		return store.ErrSecurityFindingNotFound
	}
	detail, err := json.Marshal(map[string]string{"canonical_id": canonicalID.String(), "canonical_fingerprint": canonicalFingerprint})
	if err != nil {
		return fmt.Errorf("encoding duplicate detail: %w", err)
	}
	if _, err := tx.Exec(ctx, `
		INSERT INTO security_finding_events (finding_id, event_type, actor, note, detail)
		VALUES ($1, 'marked_duplicate', $2, $3, $4)`, findingID, actor, note, detail); err != nil {
		return fmt.Errorf("recording duplicate event: %w", err)
	}
	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("committing duplicate update: %w", err)
	}
	return nil
}

