// --- Activity events (Postgres primary) ---

func (c *Client) WriteActivity(ctx context.Context, eventType, summary string, detail json.RawMessage) error {
	_, err := c.store.WriteActivityEvent(ctx, c.sessionID, eventType, summary, detail)
	return err
}

// --- Metrics (Postgres primary, CRD best-effort mirror) ---

func (c *Client) WriteMetrics(ctx context.Context, metrics SessionMetrics) error {
	encoded, err := json.Marshal(metrics)
	if err != nil {
		return fmt.Errorf("marshaling session metrics: %w", err)
	}
	if err := c.store.MergeSessionMetadata(ctx, c.sessionID, metadataKeyMetrics, encoded); err != nil {
		return fmt.Errorf("merging session metrics: %w", err)
	}
	return c.patchCRDStatus(ctx, func(run *platformv1alpha1.AgentRun) {
		run.Status.Metrics = &platformv1alpha1.AgentRunMetrics{
			CostUsd:       fmt.Sprintf("%.4f", metrics.CostUSD),
			InputTokens:   metrics.InputTokens,
			OutputTokens:  metrics.OutputTokens,
			ToolCallCount: metrics.ToolCallCount,
		}
		if run.Status.Phase == "" || run.Status.Phase == platformv1alpha1.AgentRunPhasePending || run.Status.Phase == platformv1alpha1.AgentRunPhaseAdmitted {
			run.Status.Phase = platformv1alpha1.AgentRunPhaseRunning
		}
		if run.Status.Queue == nil || run.Status.Queue.State == "" {
			run.Status.Queue = &platformv1alpha1.AgentRunQueueStatus{State: "Running"}
		}
	})
}

// WriteResult writes the final execution result. The artifact mirror is
// written before the terminal phase commits: if it fails, the caller can
// retry the whole call (every statement is idempotent) instead of ending up
// with a terminal session that permanently lost its artifact links.
func (c *Client) WriteResult(ctx context.Context, status, prURL, lastError, activityLogURL, diffURL string) error {
	if activityLogURL != "" || diffURL != "" {
		meta, err := json.Marshal(map[string]string{
			"activity_log_url": activityLogURL,
			"diff_url":         diffURL,
			"pr_url":           prURL,
		})
		if err != nil {
			return fmt.Errorf("encoding result artifact metadata: %w", err)
		}
		if _, err := c.store.UpsertArtifact(ctx, c.sessionID, "activity_log", "", activityLogURL, "", meta); err != nil {
			return fmt.Errorf("writing result artifact: %w", err)
		}
	}
	phase := "succeeded"
	if status == "failed" {
		phase = "failed"
	}
	if err := c.store.UpdatePhase(ctx, c.sessionID, phase, phase); err != nil {
		return err
	}
	return c.patchCRDStatus(ctx, func(run *platformv1alpha1.AgentRun) {
		run.Status.Artifacts = ensureRunArtifacts(run.Status.Artifacts)
		run.Status.Artifacts.ActivityLogURL = activityLogURL
		run.Status.Artifacts.DiffURL = diffURL
		run.Status.LastError = lastError
		if prURL != "" {
			run.Status.Artifacts.ReviewSummaryRef = &platformv1alpha1.ArtifactRef{
				Kind: "PullRequest",
				Name: prURL,
			}
		}
		// This publish is the authoritative end of the worker's execution:
		// stamp completedAt here so a transient controller-side terminal
		// transition earlier in the run (e.g. a sandbox read-after-create
		// race) cannot leave completedAt frozen at a time when the agent was
		// still working.
		now := metav1.Now()
		run.Status.CompletedAt = &now
		if status == "failed" {
			run.Status.Phase = platformv1alpha1.AgentRunPhaseFailed
			run.Status.CurrentStep = "failed"
			run.Status.Queue = &platformv1alpha1.AgentRunQueueStatus{State: "Failed", BlockedReason: lastError}
		} else {
			run.Status.Phase = platformv1alpha1.AgentRunPhaseSucceeded
			run.Status.CurrentStep = "review-complete"
			run.Status.Queue = &platformv1alpha1.AgentRunQueueStatus{State: "Succeeded"}
		}
	})
}

// --- Owner lookup & notifications ---

// lookupOwnerUserID resolves the owner of the agent_run from resource_ownership.
// Returns empty string if not found (best-effort).
func lookupOwnerUserID(ctx context.Context, ss store.StateStore, runName, runNS string) string {
	owner, err := ss.GetResourceOwner(ctx, "agent_run", runName, runNS)
	if err != nil || owner == nil {
		return ""
	}
	return owner.OwnerID
}

// maybeNotifyOwner creates an in-app notification for the run owner when the
// agent needs actionable user input.
func (c *Client) maybeNotifyOwner(ctx context.Context, inputType platformv1alpha1.UserInputRequestType, message string) {
	if c.ownerUserID == "" {
		return
	}
	title := notificationTitle(inputType)
	if title == "" {
		return // non-actionable type (idle, stopped)
	}
	// Skip if there's already an unread notification for this run.
	if exists, err := c.store.HasUnreadNotification(ctx, c.ownerUserID, "user_input_required", c.runName, c.runNS); err != nil {
		log.Printf("WARN: failed to check existing notification: %v", err)
	} else if exists {
		return
	}
	if err := c.store.CreateNotification(ctx, &store.Notification{
		UserID:            c.ownerUserID,
		Type:              "user_input_required",
		Title:             title,
		Body:              message,
		ResourceType:      "agent_run",
		ResourceID:        c.runName,
		ResourceNamespace: c.runNS,
	}); err != nil {
		log.Printf("WARN: failed to create input notification: %v", err)
	}
}

func notificationTitle(t platformv1alpha1.UserInputRequestType) string {
	switch t {
	case platformv1alpha1.UserInputQuestion:
		return "Agent has a question"
	case platformv1alpha1.UserInputApproval:
		return "Agent needs approval"
	case platformv1alpha1.UserInputPlanReview:
		return "Agent plan ready for review"
	case platformv1alpha1.UserInputTurnLimit:
		return "Agent reached turn limit"
	case platformv1alpha1.UserInputCircuitBreak:
		return "Agent circuit breaker triggered"
	default:
		return "" // idle, stopped — not actionable
	}
}

// --- CRD helpers ---

// toCRDPhase maps internal lowercase phase strings to CRD-validated enum values.
var phaseMap = map[string]platformv1alpha1.AgentRunPhase{
	"pending":         platformv1alpha1.AgentRunPhasePending,
	"admitted":        platformv1alpha1.AgentRunPhaseAdmitted,
	"waitingapproval": platformv1alpha1.AgentRunPhaseWaitingApproval,
	"provisioning":    platformv1alpha1.AgentRunPhaseProvisioning,
	"running":         platformv1alpha1.AgentRunPhaseRunning,
	"question":        platformv1alpha1.AgentRunPhaseQuestion,
	"blocked":         platformv1alpha1.AgentRunPhaseBlocked,
	"succeeded":       platformv1alpha1.AgentRunPhaseSucceeded,
	"failed":          platformv1alpha1.AgentRunPhaseFailed,
	"cancelled":       platformv1alpha1.AgentRunPhaseCancelled,
	"awaiting-user":   platformv1alpha1.AgentRunPhaseQuestion,
}

func toCRDPhase(phase string) platformv1alpha1.AgentRunPhase {
	if p, ok := phaseMap[strings.ToLower(phase)]; ok {
		return p
	}
	// If already a valid CRD phase (e.g. "Running"), use as-is.
	return platformv1alpha1.AgentRunPhase(phase)
}

func (c *Client) patchCRDStatus(ctx context.Context, mutate func(*platformv1alpha1.AgentRun)) error {
	if c.crd == nil {
		return nil
	}
	run := &platformv1alpha1.AgentRun{}
	if err := c.crd.Get(ctx, types.NamespacedName{Name: c.runName, Namespace: c.runNS}, run); err != nil {
		return nil // best-effort dual-write
	}
	patch := client.MergeFrom(run.DeepCopy())
	mutate(run)
	if err := c.crd.Status().Patch(ctx, run, patch); err != nil {
		log.Printf("WARN: CRD status dual-write failed: %v", err)
		return nil // don't fail on CRD write — Postgres is primary
	}
	return nil
}

func ensureRunArtifacts(in *platformv1alpha1.AgentRunArtifacts) *platformv1alpha1.AgentRunArtifacts {
	if in != nil {
		return in
	}
	return &platformv1alpha1.AgentRunArtifacts{}
}

package sessionclient

import (
	"encoding/base64"
	"fmt"
	"strings"
)

// maxImageBytes caps the decoded size of a single attached image to guard
// against oversized payloads reaching the model or the database.
const maxImageBytes = 20 * 1024 * 1024 // 20 MiB
const maxImagesPerMessage = 8

// ParseImageDataURL parses a data URL of the form
// "data:<media-type>;base64,<data>" into a MessageImage. It validates the
// base64 payload and enforces a size cap. Non-base64 or non-data URLs are
// rejected.
func ParseImageDataURL(dataURL string) (MessageImage, error) {
	raw := strings.TrimSpace(dataURL)
	if !strings.HasPrefix(raw, "data:") {
		return MessageImage{}, fmt.Errorf("not a data URL")
	}
	raw = strings.TrimPrefix(raw, "data:")
	comma := strings.IndexByte(raw, ',')
	if comma < 0 {
		return MessageImage{}, fmt.Errorf("malformed data URL: missing comma")
	}
	meta := raw[:comma]
	payload := raw[comma+1:]
	if !strings.Contains(meta, "base64") {
		return MessageImage{}, fmt.Errorf("only base64-encoded data URLs are supported")
	}
	mediaType := strings.TrimSpace(strings.Split(meta, ";")[0])
	if mediaType == "" {
		mediaType = "image/png"
	}
	if !strings.HasPrefix(mediaType, "image/") {
		return MessageImage{}, fmt.Errorf("unsupported media type %q", mediaType)
	}
	decoded, err := base64.StdEncoding.DecodeString(strings.TrimSpace(payload))
	if err != nil {
		return MessageImage{}, fmt.Errorf("invalid base64 image data: %w", err)
	}
	if len(decoded) == 0 {
		return MessageImage{}, fmt.Errorf("empty image data")
	}
	if len(decoded) > maxImageBytes {
		return MessageImage{}, fmt.Errorf("image exceeds %d byte limit", maxImageBytes)
	}
	return MessageImage{
		MediaType: mediaType,
		Data:      base64.StdEncoding.EncodeToString(decoded),
	}, nil
}

// ParseImageDataURLs parses a slice of data URLs, returning an error on the
// first malformed entry.
func ParseImageDataURLs(dataURLs []string) ([]MessageImage, error) {
	out := make([]MessageImage, 0, len(dataURLs))
	for _, u := range dataURLs {
		if strings.TrimSpace(u) == "" {
			continue
		}
		img, err := ParseImageDataURL(u)
		if err != nil {
			return nil, err
		}
		out = append(out, img)
		if len(out) > maxImagesPerMessage {
			return nil, fmt.Errorf("too many images: maximum %d per message", maxImagesPerMessage)
		}
	}
	return out, nil
}

// DataURL renders the image back into a "data:<media-type>;base64,<data>" URL.
func (m MessageImage) DataURL() string {
	mediaType := m.MediaType
	if mediaType == "" {
		mediaType = "image/png"
	}
	return fmt.Sprintf("data:%s;base64,%s", mediaType, m.Data)
}

package sessionclient

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/google/uuid"

	"github.com/gratefulagents/gratefulagents/internal/store"
)

// metadataKeyInterrupt is the session metadata section carrying a user's
// request to stop the run's in-flight turn. The dashboard writes it; the
// runner's per-turn watcher consumes it and cancels the turn context.
const metadataKeyInterrupt = "interrupt"

// InterruptRequest asks the runner to stop whatever the current turn is doing
// (model call, tools, sub-agents) without terminating the run. The session
// stays alive and the agent waits for the next user message.
type InterruptRequest struct {
	ID          int64     `json:"id,omitempty"`
	RequestedAt time.Time `json:"requested_at"`
	RequestedBy string    `json:"requested_by,omitempty"`
}

// RequestInterrupt records an interrupt request on the session so the runner
// can stop the in-flight turn. It is written by the dashboard on behalf of
// the user pressing the stop button.
func RequestInterrupt(ctx context.Context, ss store.StateStore, sessionID uuid.UUID, requestedBy string) error {
	if interrupts, ok := ss.(store.InterruptStore); ok {
		_, _, err := interrupts.AppendInterrupt(ctx, sessionID, requestedBy)
		return err
	}
	req := InterruptRequest{
		RequestedAt: time.Now().UTC(),
		RequestedBy: strings.TrimSpace(requestedBy),
	}
	encoded, err := json.Marshal(req)
	if err != nil {
		return fmt.Errorf("marshaling interrupt request: %w", err)
	}
	if err := ss.MergeSessionMetadata(ctx, sessionID, metadataKeyInterrupt, encoded); err != nil {
		return fmt.Errorf("merging session metadata %q: %w", metadataKeyInterrupt, err)
	}
	return nil
}

// PendingInterrupt returns the pending interrupt request, or nil when none is
// set.
func (c *Client) PendingInterrupt(ctx context.Context) (*InterruptRequest, error) {
	if interrupts, ok := c.store.(store.InterruptStore); ok {
		id, requestedAt, requestedBy, found, err := interrupts.PeekInterrupt(ctx, c.sessionID)
		if err != nil || !found {
			return nil, err
		}
		return &InterruptRequest{ID: id, RequestedAt: requestedAt, RequestedBy: requestedBy}, nil
	}
	metadata, err := c.readMetadataObject(ctx)
	if err != nil {
		return nil, err
	}
	return decodeInterruptRequest(metadata)
}

// ConsumeInterrupt claims the pending interrupt request: it returns the
// request (nil when none is pending) and clears it so it is honored exactly
// once. The runner is the single consumer, so read-then-clear is safe.
func (c *Client) ConsumeInterrupt(ctx context.Context) (*InterruptRequest, error) {
	if interrupts, ok := c.store.(store.InterruptStore); ok {
		id, requestedAt, requestedBy, found, err := interrupts.ConsumeInterrupt(ctx, c.sessionID)
		if err != nil || !found {
			return nil, err
		}
		return &InterruptRequest{ID: id, RequestedAt: requestedAt, RequestedBy: requestedBy}, nil
	}
	req, err := c.PendingInterrupt(ctx)
	if err != nil {
		return nil, err
	}
	if req == nil {
		return nil, nil
	}
	if err := c.ClearInterrupt(ctx); err != nil {
		return nil, err
	}
	return req, nil
}

// ClearInterrupt drops any pending interrupt request, e.g. a stale flag left
// over from a stop that raced the natural end of a turn.
func (c *Client) DrainInterruptsThrough(ctx context.Context, cutoff time.Time) (*InterruptRequest, error) {
	var applicable *InterruptRequest
	for {
		req, err := c.PendingInterrupt(ctx)
		if err != nil || req == nil || req.RequestedAt.After(cutoff) {
			return applicable, err
		}
		consumed, err := c.ConsumeInterrupt(ctx)
		if err != nil {
			return applicable, err
		}
		applicable = consumed
	}
}

func (c *Client) ClearInterrupt(ctx context.Context) error {
	if interrupts, ok := c.store.(store.InterruptStore); ok {
		for {
			_, _, _, found, err := interrupts.ConsumeInterrupt(ctx, c.sessionID)
			if err != nil || !found {
				return err
			}
		}
	}
	if err := c.store.MergeSessionMetadata(ctx, c.sessionID, metadataKeyInterrupt, json.RawMessage("null")); err != nil {
		return fmt.Errorf("clearing session metadata %q: %w", metadataKeyInterrupt, err)
	}
	return nil
}

func decodeInterruptRequest(metadata map[string]json.RawMessage) (*InterruptRequest, error) {
	raw := metadata[metadataKeyInterrupt]
	if len(raw) == 0 || string(raw) == "null" {
		return nil, nil
	}
	var req InterruptRequest
	if err := json.Unmarshal(raw, &req); err != nil {
		return nil, fmt.Errorf("decoding session metadata %q: %w", metadataKeyInterrupt, err)
	}
	if req.RequestedAt.IsZero() {
		return nil, nil
	}
	return &req, nil
}

package sessionclient

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/gratefulagents/gratefulagents/internal/store"
)

const (
	metadataKeyMetrics            = "metrics"
	metadataKeyWorkingState       = "working_state"
	metadataKeySubAgentCheckpoint = "subagent_checkpoint"

	maxRecentTurnSummaries = 6
)

// SessionMetrics stores durable token/cost metadata without clobbering other session state.
type SessionMetrics struct {
	CostUSD       float64 `json:"cost_usd,omitempty"`
	InputTokens   int64   `json:"input_tokens,omitempty"`
	OutputTokens  int64   `json:"output_tokens,omitempty"`
	ToolCallCount int32   `json:"tool_call_count,omitempty"`
	// ContextTokens is the prompt-side size of the main agent's most recent
	// generation — the run's current context usage. ContextTriggerTokens is the
	// estimated context size at which the run's history compaction kicks in for
	// the active model; ContextTargetTokens is what compaction shrinks the
	// history to. Zero when unknown/disabled. The dashboard renders these as
	// the run's context-usage bar.
	ContextTokens        int64 `json:"context_tokens,omitempty"`
	ContextTriggerTokens int64 `json:"context_trigger_tokens,omitempty"`
	ContextTargetTokens  int64 `json:"context_target_tokens,omitempty"`
}

// WorkingState stores the compact, durable state used to rebuild context across long runs.
type WorkingState struct {
	Goal                  string   `json:"goal,omitempty"`
	CurrentMode           string   `json:"current_mode,omitempty"`
	CurrentPhase          string   `json:"current_phase,omitempty"`
	LastUserMessage       string   `json:"last_user_message,omitempty"`
	LastAssistantSummary  string   `json:"last_assistant_summary,omitempty"`
	RecentTurnSummaries   []string `json:"recent_turn_summaries,omitempty"`
	HistoryFloorMessageID int64    `json:"history_floor_message_id,omitempty"`
	LastResponseID        string   `json:"last_response_id,omitempty"`
	// LastStoppedUserMessageID is the durable cursor floor for a turn the user
	// explicitly stopped. Replacement pods must not auto-run that same prompt;
	// only a genuinely newer user message may resume the session.
	LastStoppedUserMessageID int64 `json:"last_stopped_user_message_id,omitempty"`
	// DurableRun* coordinates one stable SDK Runner invocation across pod
	// replacement and autonomous passes for the same user message.
	DurableRunMessageID int64     `json:"durable_run_message_id,omitempty"`
	DurableRunPass      int64     `json:"durable_run_pass,omitempty"`
	DurableRunNextPass  int64     `json:"durable_run_next_pass,omitempty"`
	UpdatedAt           time.Time `json:"updated_at,omitempty"`
}

func (w *WorkingState) normalize() {
	w.Goal = strings.TrimSpace(w.Goal)
	w.CurrentMode = strings.TrimSpace(w.CurrentMode)
	w.CurrentPhase = strings.TrimSpace(w.CurrentPhase)
	w.LastUserMessage = strings.TrimSpace(w.LastUserMessage)
	w.LastAssistantSummary = strings.TrimSpace(w.LastAssistantSummary)
	w.LastResponseID = strings.TrimSpace(w.LastResponseID)

	normalized := make([]string, 0, len(w.RecentTurnSummaries))
	for _, summary := range w.RecentTurnSummaries {
		summary = strings.TrimSpace(summary)
		if summary == "" {
			continue
		}
		normalized = append(normalized, summary)
	}
	if len(normalized) > maxRecentTurnSummaries {
		normalized = normalized[len(normalized)-maxRecentTurnSummaries:]
	}
	w.RecentTurnSummaries = normalized
	w.UpdatedAt = time.Now().UTC()
}

// ReadWorkingState loads the durable working state from session metadata.
func (c *Client) ReadWorkingState(ctx context.Context) (WorkingState, error) {
	metadata, err := c.readMetadataObject(ctx)
	if err != nil {
		return WorkingState{}, err
	}
	var state WorkingState
	if err := decodeMetadataSection(metadata, metadataKeyWorkingState, &state); err != nil {
		return WorkingState{}, err
	}
	return state, nil
}

// UpdateWorkingState applies a mutation to the durable working state.
func (c *Client) UpdateWorkingState(ctx context.Context, mutate func(*WorkingState) error) error {
	return c.updateMetadataSection(ctx, metadataKeyWorkingState, func(raw json.RawMessage) (json.RawMessage, error) {
		var state WorkingState
		if len(raw) > 0 {
			if err := json.Unmarshal(raw, &state); err != nil {
				return nil, fmt.Errorf("decoding session metadata %q: %w", metadataKeyWorkingState, err)
			}
		}
		if err := mutate(&state); err != nil {
			return nil, err
		}
		state.normalize()

		encoded, err := json.Marshal(state)
		if err != nil {
			return nil, fmt.Errorf("marshaling working state: %w", err)
		}
		return encoded, nil
	})
}

// ReadSubAgentCheckpoint loads the host-defined async sub-agent scheduler
// checkpoint from durable session metadata. A nil result means no scheduler
// state has been persisted for this session yet. The session client treats the
// payload as opaque JSON so SDK checkpoint schema changes remain SDK-owned.
func (c *Client) ReadSubAgentCheckpoint(ctx context.Context) (json.RawMessage, error) {
	metadata, err := c.readMetadataObject(ctx)
	if err != nil {
		return nil, err
	}
	raw := metadata[metadataKeySubAgentCheckpoint]
	if len(raw) == 0 || string(raw) == "null" {
		return nil, nil
	}
	if !json.Valid(raw) {
		return nil, fmt.Errorf("decoding session metadata %q: invalid JSON", metadataKeySubAgentCheckpoint)
	}
	return append(json.RawMessage(nil), raw...), nil
}

// WriteSubAgentCheckpoint atomically replaces the durable scheduler checkpoint
// without clobbering working state, metrics, interrupts, or encryption keys.
func (c *Client) WriteSubAgentCheckpoint(ctx context.Context, checkpoint json.RawMessage) error {
	if len(checkpoint) == 0 {
		checkpoint = json.RawMessage("null")
	}
	if !json.Valid(checkpoint) {
		return fmt.Errorf("marshaling session metadata %q: invalid JSON", metadataKeySubAgentCheckpoint)
	}
	checkpoint = sanitizeCheckpointJSONForPostgres(checkpoint)
	if err := c.store.MergeSessionMetadata(ctx, c.sessionID, metadataKeySubAgentCheckpoint, checkpoint); err != nil {
		return fmt.Errorf("merging session metadata %q: %w", metadataKeySubAgentCheckpoint, err)
	}
	return nil
}

// sanitizeCheckpointJSONForPostgres replaces JSON's escaped NUL character with
// the Unicode replacement character. PostgreSQL jsonb rejects \u0000 because
// PostgreSQL text cannot represent NUL (SQLSTATE 22P05), while JSON permits it.
// Escaped backslashes are copied as a pair so a literal "\\u0000" is preserved.
func sanitizeCheckpointJSONForPostgres(checkpoint json.RawMessage) json.RawMessage {
	sanitized := make(json.RawMessage, 0, len(checkpoint))
	inString := false
	for i := 0; i < len(checkpoint); i++ {
		current := checkpoint[i]
		sanitized = append(sanitized, current)
		if !inString {
			if current == '"' {
				inString = true
			}
			continue
		}
		if current == '"' {
			inString = false
			continue
		}
		if current != '\\' || i+1 >= len(checkpoint) {
			continue
		}
		if i+5 < len(checkpoint) && checkpoint[i+1] == 'u' && string(checkpoint[i+2:i+6]) == "0000" {
			sanitized = append(sanitized, 'u', 'f', 'f', 'f', 'd')
			i += 5
			continue
		}
		// This escape cannot start another escape. Copy its second byte now so
		// an encoded literal backslash followed by "u0000" remains unchanged.
		i++
		sanitized = append(sanitized, checkpoint[i])
	}
	return sanitized
}

// ResetConversationWindow advances the durable history floor to the latest
// stored message so future prompt assembly ignores prior turns.
func (c *Client) ResetConversationWindow(ctx context.Context) error {
	messages, err := c.store.GetMessages(ctx, c.sessionID)
	if err != nil {
		return fmt.Errorf("loading messages: %w", err)
	}
	var floor int64
	if len(messages) > 0 {
		floor = messages[len(messages)-1].ID
	}
	return c.UpdateWorkingState(ctx, func(state *WorkingState) error {
		state.Goal = ""
		state.LastUserMessage = ""
		state.LastAssistantSummary = ""
		state.RecentTurnSummaries = nil
		state.LastResponseID = ""
		state.HistoryFloorMessageID = floor
		return nil
	})
}

func (c *Client) readMetadataObject(ctx context.Context) (map[string]json.RawMessage, error) {
	session, err := c.store.GetSession(ctx, c.sessionID)
	if err != nil {
		return nil, fmt.Errorf("loading session metadata: %w", err)
	}
	if len(session.Metadata) == 0 {
		return map[string]json.RawMessage{}, nil
	}

	var metadata map[string]json.RawMessage
	if err := json.Unmarshal(session.Metadata, &metadata); err != nil {
		return nil, fmt.Errorf("decoding session metadata: %w", err)
	}
	if metadata == nil {
		metadata = map[string]json.RawMessage{}
	}
	return metadata, nil
}

func (c *Client) updateMetadataSection(ctx context.Context, key string, mutate func(json.RawMessage) (json.RawMessage, error)) error {
	// Prefer the locked read-modify-write: it serializes concurrent updates
	// of the same section under the session row lock, so overlapping writers
	// (goroutines in one pod, or an old and a replacement pod) cannot lose
	// each other's writes.
	if updater, ok := c.store.(store.MetadataSectionUpdater); ok {
		if err := updater.UpdateSessionMetadataSection(ctx, c.sessionID, key, mutate); err != nil {
			return fmt.Errorf("updating session metadata %q: %w", key, err)
		}
		return nil
	}
	metadata, err := c.readMetadataObject(ctx)
	if err != nil {
		return err
	}
	encoded, err := mutate(metadata[key])
	if err != nil {
		return err
	}
	if err := c.store.MergeSessionMetadata(ctx, c.sessionID, key, encoded); err != nil {
		return fmt.Errorf("merging session metadata %q: %w", key, err)
	}
	return nil
}

func decodeMetadataSection[T any](metadata map[string]json.RawMessage, key string, out *T) error {
	raw := metadata[key]
	if len(raw) == 0 {
		return nil
	}
	if err := json.Unmarshal(raw, out); err != nil {
		return fmt.Errorf("decoding session metadata %q: %w", key, err)
	}
	return nil
}

package sessionclient

import (
	"context"
	"fmt"
)

// SaveTranscriptBlob upserts the session's serialized transcript snapshot.
// The blob is opaque to the store layer; the agent loop owns the encoding
// (versioned JSON + gzip, size-capped). Empty data clears the snapshot so a
// resume falls back to the durable conversation tail.
func (c *Client) SaveTranscriptBlob(ctx context.Context, data []byte, itemCount int) error {
	if len(data) == 0 {
		return c.ClearTranscriptBlob(ctx)
	}
	if err := c.store.UpsertSessionTranscript(ctx, c.sessionID, data, int32(itemCount)); err != nil {
		return fmt.Errorf("saving transcript snapshot: %w", err)
	}
	return nil
}

// LoadTranscriptBlob returns the stored transcript snapshot, or (nil, nil)
// when none exists.
func (c *Client) LoadTranscriptBlob(ctx context.Context) ([]byte, error) {
	data, err := c.store.GetSessionTranscript(ctx, c.sessionID)
	if err != nil {
		return nil, fmt.Errorf("loading transcript snapshot: %w", err)
	}
	return data, nil
}

// ClearTranscriptBlob deletes the stored transcript snapshot.
func (c *Client) ClearTranscriptBlob(ctx context.Context) error {
	if err := c.store.DeleteSessionTranscript(ctx, c.sessionID); err != nil {
		return fmt.Errorf("clearing transcript snapshot: %w", err)
	}
	return nil
}

package sessionclient

import (
	"bytes"
	"context"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"
)

const (
	maxVideoBytes      = 20 * 1024 * 1024
	maxVideoDuration   = 2 * time.Minute
	maxVideoDimension  = 4096
	maxVideoPixels     = 16_000_000
	maxFrameBytes      = 5 * 1024 * 1024
	maxFrameTotalBytes = 20 * 1024 * 1024
	maxVideoFrames     = 8
	ffprobeTimeout     = 5 * time.Second
	ffmpegTimeout      = 20 * time.Second
	maxProbeOutput     = 64 * 1024
	maxStderrOutput    = 16 * 1024
	maxPacketLineBytes = 1024
)

var (
	ErrInvalidVideoAttachment = errors.New("invalid video attachment")
	ErrVideoProcessingBusy    = errors.New("video processing capacity reached")
	videoProcessingSemaphore  = make(chan struct{}, 2)
)

var supportedVideoMediaTypes = map[string]bool{
	"video/mp4":       true,
	"video/quicktime": true,
	"video/webm":      true,
}

type videoProbe struct {
	Streams []videoStream `json:"streams"`
	Format  struct {
		Duration string `json:"duration"`
	} `json:"format"`
}

type videoStream struct {
	Index       int    `json:"index"`
	CodecType   string `json:"codec_type"`
	Width       int    `json:"width"`
	Height      int    `json:"height"`
	Duration    string `json:"duration"`
	Disposition struct {
		AttachedPicture int `json:"attached_pic"`
	} `json:"disposition"`
}

type limitedBuffer struct {
	bytes.Buffer
	limit     int
	truncated bool
}

func (b *limitedBuffer) Write(p []byte) (int, error) {
	remaining := b.limit - b.Len()
	if remaining <= 0 {
		if len(p) > 0 {
			b.truncated = true
		}
		return len(p), nil
	}
	if len(p) > remaining {
		_, _ = b.Buffer.Write(p[:remaining])
		b.truncated = true
		return len(p), nil
	}
	return b.Buffer.Write(p)
}

type packetDurationWriter struct {
	line    []byte
	minimum float64
	maximum float64
	found   bool
}

func (w *packetDurationWriter) Write(p []byte) (int, error) {
	for _, b := range p {
		if b == '\n' {
			w.recordLine()
			w.line = w.line[:0]
			continue
		}
		if len(w.line) == maxPacketLineBytes {
			return 0, fmt.Errorf("ffprobe packet line exceeds %d byte limit", maxPacketLineBytes)
		}
		w.line = append(w.line, b)
	}
	return len(p), nil
}

func (w *packetDurationWriter) finish() {
	if len(w.line) > 0 {
		w.recordLine()
		w.line = w.line[:0]
	}
}

func (w *packetDurationWriter) recordLine() {
	pts, duration, ok := strings.Cut(strings.TrimSpace(string(w.line)), ",")
	if !ok {
		return
	}
	packetPTS, err := strconv.ParseFloat(strings.TrimSpace(pts), 64)
	if err != nil || math.IsNaN(packetPTS) || math.IsInf(packetPTS, 0) {
		return
	}
	packetDuration, err := strconv.ParseFloat(strings.TrimSpace(duration), 64)
	if err != nil || math.IsNaN(packetDuration) || math.IsInf(packetDuration, 0) || packetDuration < 0 {
		packetDuration = 0
	}
	end := packetPTS + packetDuration
	if !w.found {
		w.minimum = packetPTS
		w.maximum = end
		w.found = true
		return
	}
	if packetPTS < w.minimum {
		w.minimum = packetPTS
	}
	if end > w.maximum {
		w.maximum = end
	}
}

// ParseVideoDataURLs extracts JPEG frames from one video data URL.
func ParseVideoDataURLs(ctx context.Context, dataURLs []string, maxFrames int) ([]MessageImage, error) {
	dataURL, err := singleVideoDataURL(dataURLs)
	if err != nil {
		return nil, err
	}
	if dataURL == "" {
		return nil, nil
	}
	if err := validateVideoFrameCount(maxFrames); err != nil {
		return nil, err
	}

	// Admit work before allocating the decoded payload. Requests beyond the two
	// active decoder slots fail fast instead of retaining large queued videos.
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	case videoProcessingSemaphore <- struct{}{}:
		defer func() { <-videoProcessingSemaphore }()
	default:
		return nil, ErrVideoProcessingBusy
	}

	video, err := parseVideoDataURL(dataURL)
	if err != nil {
		return nil, err
	}
	return extractVideoFrames(ctx, video, maxFrames)
}

func singleVideoDataURL(dataURLs []string) (string, error) {
	var dataURL string
	for _, value := range dataURLs {
		if strings.TrimSpace(value) == "" {
			continue
		}
		if dataURL != "" {
			return "", fmt.Errorf("%w: too many videos: maximum 1 per message", ErrInvalidVideoAttachment)
		}
		dataURL = value
	}
	return dataURL, nil
}

func validateVideoFrameCount(maxFrames int) error {
	if maxFrames < 1 || maxFrames > maxVideoFrames {
		return fmt.Errorf("%w: max frames must be between 1 and %d", ErrInvalidVideoAttachment, maxVideoFrames)
	}
	return nil
}

func extractVideoFrames(ctx context.Context, video []byte, maxFrames int) ([]MessageImage, error) {
	tempParent := os.Getenv("VIDEO_TMP_DIR")
	if tempParent == "" {
		tempParent = os.TempDir()
	}
	dir, err := os.MkdirTemp(tempParent, "sessionclient-video-*")
	if err != nil {
		return nil, fmt.Errorf("create video temp directory: %w", err)
	}
	defer func() { _ = os.RemoveAll(dir) }()

	inputPath := filepath.Join(dir, "input")
	if err := os.WriteFile(inputPath, video, 0o600); err != nil {
		return nil, fmt.Errorf("write video input: %w", err)
	}

	demuxer := videoDemuxer(video)
	stream, duration, err := probeVideo(ctx, demuxer, inputPath)
	if err != nil {
		return nil, err
	}

	outputPattern := filepath.Join(dir, "frame-%06d.jpg")
	filter := fmt.Sprintf("fps=%g,scale=1600:1600:force_original_aspect_ratio=decrease", float64(maxFrames)/duration)
	ffmpegCtx, cancelFFmpeg := context.WithTimeout(ctx, ffmpegTimeout)
	ffmpegOutput := &limitedBuffer{limit: maxProbeOutput}
	ffmpegErr := runVideoCommand(ffmpegCtx, "ffmpeg", ffmpegOutput, "-v", "error", "-nostdin", "-protocol_whitelist", "file,pipe", "-threads", "1", "-f", demuxer, "-i", inputPath, "-map", fmt.Sprintf("0:%d", stream.Index), "-filter_threads", "1", "-vf", filter, "-q:v", "4", "-frames:v", strconv.Itoa(maxFrames), outputPattern)
	ffmpegContextErr := ffmpegCtx.Err()
	cancelFFmpeg()
	if ffmpegErr != nil {
		return nil, videoCommandError(ffmpegContextErr, ffmpegErr, "ffmpeg", "ffmpeg frame extraction failed")
	}
	return readVideoFrames(dir, maxFrames)
}

func readVideoFrames(dir string, maxFrames int) ([]MessageImage, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("read video frames: %w", err)
	}
	framePaths := make([]string, 0, len(entries))
	for _, entry := range entries {
		if entry.Type().IsRegular() && strings.EqualFold(filepath.Ext(entry.Name()), ".jpg") {
			framePaths = append(framePaths, filepath.Join(dir, entry.Name()))
		}
	}
	sort.Strings(framePaths)

	frames := make([]MessageImage, 0, min(len(framePaths), maxFrames))
	var totalFrameBytes int64
	for _, path := range framePaths {
		if len(frames) == maxFrames {
			break
		}
		info, err := os.Stat(path)
		if err != nil {
			return nil, fmt.Errorf("stat video frame: %w", err)
		}
		if info.Size() == 0 {
			return nil, fmt.Errorf("%w: empty video frame", ErrInvalidVideoAttachment)
		}
		if info.Size() > maxFrameBytes {
			return nil, fmt.Errorf("%w: video frame exceeds %d byte limit", ErrInvalidVideoAttachment, maxFrameBytes)
		}
		totalFrameBytes += info.Size()
		if totalFrameBytes > maxFrameTotalBytes {
			return nil, fmt.Errorf("%w: video frames exceed %d byte total limit", ErrInvalidVideoAttachment, maxFrameTotalBytes)
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return nil, fmt.Errorf("read video frame: %w", err)
		}
		frames = append(frames, MessageImage{
			MediaType: "image/jpeg",
			Data:      base64.StdEncoding.EncodeToString(data),
		})
	}
	if len(frames) == 0 {
		return nil, fmt.Errorf("%w: ffmpeg produced no video frames", ErrInvalidVideoAttachment)
	}
	return frames, nil
}

func probeVideo(ctx context.Context, demuxer, inputPath string) (videoStream, float64, error) {
	probeCtx, cancelProbe := context.WithTimeout(ctx, ffprobeTimeout)
	probeOutput := &limitedBuffer{limit: maxProbeOutput}
	probeErr := runVideoCommand(probeCtx, "ffprobe", probeOutput, "-v", "error", "-protocol_whitelist", "file,pipe", "-f", demuxer, "-i", inputPath, "-show_entries", "stream=index,codec_type,width,height,duration:stream_disposition=attached_pic:format=duration", "-of", "json")
	probeContextErr := probeCtx.Err()
	cancelProbe()
	if probeErr != nil {
		return videoStream{}, 0, videoCommandError(probeContextErr, probeErr, "ffprobe", "ffprobe failed")
	}
	if probeOutput.truncated {
		return videoStream{}, 0, fmt.Errorf("%w: ffprobe output exceeds %d byte limit", ErrInvalidVideoAttachment, maxProbeOutput)
	}

	var probe videoProbe
	if err := json.Unmarshal(probeOutput.Bytes(), &probe); err != nil {
		return videoStream{}, 0, fmt.Errorf("%w: decode ffprobe output: %v", ErrInvalidVideoAttachment, err)
	}
	stream, err := selectedVideoStream(probe.Streams)
	if err != nil {
		return videoStream{}, 0, err
	}
	duration, err := probeDuration(ctx, demuxer, inputPath, probe.Format.Duration, stream)
	if err != nil {
		return videoStream{}, 0, err
	}
	return stream, duration, nil
}

func selectedVideoStream(streams []videoStream) (videoStream, error) {
	for _, stream := range streams {
		if stream.CodecType == "video" && stream.Disposition.AttachedPicture == 0 {
			if stream.Width <= 0 || stream.Height <= 0 || stream.Width > maxVideoDimension || stream.Height > maxVideoDimension || int64(stream.Width)*int64(stream.Height) > maxVideoPixels {
				return videoStream{}, fmt.Errorf("%w: invalid video dimensions %dx%d", ErrInvalidVideoAttachment, stream.Width, stream.Height)
			}
			return stream, nil
		}
	}
	return videoStream{}, fmt.Errorf("%w: video has no video stream", ErrInvalidVideoAttachment)
}

func probeDuration(ctx context.Context, demuxer, inputPath, formatDuration string, stream videoStream) (float64, error) {
	duration, available, err := parseProbeDuration(formatDuration)
	if err != nil {
		return 0, invalidVideoDuration(formatDuration)
	}
	if !available {
		duration, available, err = parseProbeDuration(stream.Duration)
		if err != nil {
			return 0, invalidVideoDuration(stream.Duration)
		}
	}
	if !available {
		duration, err = probePacketDuration(ctx, demuxer, inputPath, stream.Index)
		if err != nil {
			return 0, err
		}
	}
	if !validVideoDuration(duration) {
		return 0, invalidVideoDuration(formatDuration)
	}
	return duration, nil
}

func parseProbeDuration(value string) (float64, bool, error) {
	value = strings.TrimSpace(value)
	if value == "" || strings.EqualFold(value, "N/A") {
		return 0, false, nil
	}
	duration, err := strconv.ParseFloat(value, 64)
	if err != nil {
		return 0, true, err
	}
	return duration, true, nil
}

func probePacketDuration(ctx context.Context, demuxer, inputPath string, streamIndex int) (float64, error) {
	probeCtx, cancelProbe := context.WithTimeout(ctx, ffprobeTimeout)
	packets := &packetDurationWriter{}
	probeErr := runVideoCommand(probeCtx, "ffprobe", packets, "-v", "error", "-protocol_whitelist", "file,pipe", "-f", demuxer, "-i", inputPath, "-select_streams", strconv.Itoa(streamIndex), "-show_entries", "packet=pts_time,duration_time", "-of", "csv=p=0")
	probeContextErr := probeCtx.Err()
	cancelProbe()
	if probeErr != nil {
		return 0, videoCommandError(probeContextErr, probeErr, "ffprobe", "ffprobe failed")
	}
	packets.finish()
	if !packets.found {
		return 0, invalidVideoDuration("")
	}
	return packets.maximum - packets.minimum, nil
}

func validVideoDuration(duration float64) bool {
	return !math.IsNaN(duration) && !math.IsInf(duration, 0) && duration > 0 && duration <= maxVideoDuration.Seconds()
}

func invalidVideoDuration(value string) error {
	return fmt.Errorf("%w: invalid video duration %q", ErrInvalidVideoAttachment, value)
}

func videoCommandError(contextErr, commandErr error, name, failure string) error {
	if contextErr != nil {
		return contextErr
	}
	if errors.Is(commandErr, exec.ErrNotFound) {
		return fmt.Errorf("run %s: %w", name, commandErr)
	}
	return fmt.Errorf("%w: %s", ErrInvalidVideoAttachment, failure)
}

func runVideoCommand(ctx context.Context, name string, stdout io.Writer, args ...string) error {
	cmd := exec.CommandContext(ctx, name, args...)
	cmd.Env = []string{"LANG=C", "PATH=" + os.Getenv("PATH")}
	cmd.Stdout = stdout
	cmd.Stderr = &limitedBuffer{limit: maxStderrOutput}
	return cmd.Run()
}

func parseVideoDataURL(dataURL string) ([]byte, error) {
	raw := strings.TrimSpace(dataURL)
	if !strings.HasPrefix(raw, "data:") {
		return nil, fmt.Errorf("%w: not a data URL", ErrInvalidVideoAttachment)
	}
	raw = strings.TrimPrefix(raw, "data:")
	metaValue, payload, ok := strings.Cut(raw, ",")
	if !ok {
		return nil, fmt.Errorf("%w: malformed data URL: missing comma", ErrInvalidVideoAttachment)
	}
	meta := strings.Split(metaValue, ";")
	mediaType := strings.ToLower(strings.TrimSpace(meta[0]))
	if !supportedVideoMediaTypes[mediaType] {
		return nil, fmt.Errorf("%w: unsupported media type %q", ErrInvalidVideoAttachment, mediaType)
	}
	base64Encoded := false
	for _, part := range meta[1:] {
		if strings.EqualFold(strings.TrimSpace(part), "base64") {
			base64Encoded = true
			break
		}
	}
	if !base64Encoded {
		return nil, fmt.Errorf("%w: only base64-encoded data URLs are supported", ErrInvalidVideoAttachment)
	}
	payload = strings.TrimSpace(payload)
	if payload == "" {
		return nil, fmt.Errorf("%w: empty video data", ErrInvalidVideoAttachment)
	}
	if len(payload) > base64.StdEncoding.EncodedLen(maxVideoBytes) {
		return nil, fmt.Errorf("%w: video exceeds %d byte limit", ErrInvalidVideoAttachment, maxVideoBytes)
	}
	decoded, err := base64.StdEncoding.DecodeString(payload)
	if err != nil {
		return nil, fmt.Errorf("%w: invalid base64 video data: %v", ErrInvalidVideoAttachment, err)
	}
	if len(decoded) > maxVideoBytes {
		return nil, fmt.Errorf("%w: video exceeds %d byte limit", ErrInvalidVideoAttachment, maxVideoBytes)
	}
	if len(decoded) == 0 {
		return nil, fmt.Errorf("%w: empty video data", ErrInvalidVideoAttachment)
	}
	if !validVideoMagic(mediaType, decoded) {
		return nil, fmt.Errorf("%w: invalid %s video signature", ErrInvalidVideoAttachment, mediaType)
	}
	return decoded, nil
}

func validVideoMagic(mediaType string, video []byte) bool {
	switch mediaType {
	case "video/mp4", "video/quicktime":
		return len(video) >= 12 && string(video[4:8]) == "ftyp"
	case "video/webm":
		return len(video) >= 4 && bytes.Equal(video[:4], []byte{0x1a, 0x45, 0xdf, 0xa3})
	default:
		return false
	}
}

func videoDemuxer(video []byte) string {
	if len(video) >= 4 && bytes.Equal(video[:4], []byte{0x1a, 0x45, 0xdf, 0xa3}) {
		return "matroska"
	}
	return "mov"
}

package tools

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"sync"
	"unicode/utf8"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

// maxTeammateMaterialLen bounds the material (plan/diff/etc.) forwarded to a
// teammate persona so a runaway paste cannot blow up the persona prompt.
const maxTeammateMaterialLen = 24 * 1024

// SoulResolver resolves a teammate handle (e.g. "alice", "agent_alice", "@alice")
// to that user's saved SOUL persona. found is false when there is no such user
// or they have not written a SOUL yet (a non-error condition the tool reports
// back to the model). canonicalName is the resolved username used for framing.
type SoulResolver interface {
	ResolveSoul(ctx context.Context, name string) (canonicalName, content string, found bool, err error)
}

// PersonaRunner runs a one-shot, tool-less persona turn: soul is injected as the
// persona's instructions and prompt is the consult message. It returns the
// persona's reply text. Wired in by the agent runtime, which owns the model
// provider and runner.
type PersonaRunner func(ctx context.Context, soul, prompt string) (string, error)

// RegisterAskTeammateTool registers the ask_teammate tool, which lets the agent
// consult a teammate's persona (their SOUL) for that teammate's likely
// perspective on a question, approach, plan, or diff. The persona runner is
// injected later via SetPersonaRunner once the runtime (and its model provider)
// is built. Returns the tool so the caller can wire the runner; returns nil when
// no resolver is provided.
func RegisterAskTeammateTool(registry *Registry, resolver SoulResolver) *AskTeammateTool {
	if registry == nil || resolver == nil {
		return nil
	}
	t := &AskTeammateTool{resolver: resolver}
	registry.Register(t)
	return t
}

// AskTeammateTool consults a teammate's SOUL persona on demand.
type AskTeammateTool struct {
	resolver SoulResolver

	mu      sync.RWMutex
	persona PersonaRunner
}

// SetPersonaRunner wires the function that executes the persona turn. Until it
// is set, the tool reports that teammate consultation is unavailable.
func (t *AskTeammateTool) SetPersonaRunner(fn PersonaRunner) {
	t.mu.Lock()
	defer t.mu.Unlock()
	t.persona = fn
}

func (t *AskTeammateTool) personaRunner() PersonaRunner {
	t.mu.RLock()
	defer t.mu.RUnlock()
	return t.persona
}

type askTeammateInput struct {
	Name     string `json:"name"`
	Question string `json:"question"`
	Material string `json:"material"`
}

func (t *AskTeammateTool) Name() string { return "ask_teammate" }

func (t *AskTeammateTool) Description() string {
	return "Consult a teammate's persona (their personal SOUL) to get how that " +
		"specific colleague would likely react. Use this when the user wants a " +
		"teammate's perspective — e.g. \"ask agent_alice what she'd think of this\" " +
		"or \"what would Bob say about this plan?\". Works for a question, an " +
		"approach/decision, a whole plan, or a diff. Put the colleague's handle in " +
		"`name` (with or without an `agent_`/`@` prefix), the ask in `question`, and " +
		"the artifact under review (plan, design, or diff) in `material`. Returns " +
		"that teammate's perspective in their own voice; it is advisory, not an action."
}

func (t *AskTeammateTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{
		"type": "object",
		"properties": {
			"name": {
				"type": "string",
				"description": "The teammate's handle/username to consult (e.g. \"alice\", \"agent_alice\", or \"@alice\")."
			},
			"question": {
				"type": "string",
				"description": "What you want the teammate's perspective on (e.g. \"Would you approve this plan?\", \"Any concerns with this approach?\")."
			},
			"material": {
				"type": "string",
				"description": "Optional artifact under review for the teammate to react to: a plan, design, approach, or diff snippet."
			}
		},
		"required": ["name", "question"]
	}`)
}

func (t *AskTeammateTool) IsReadOnly() bool                      { return true }
func (t *AskTeammateTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }
func (t *AskTeammateTool) NeedsApproval() bool                   { return false }
func (t *AskTeammateTool) TimeoutSeconds() int                   { return 120 }

func (t *AskTeammateTool) Execute(ctx context.Context, input json.RawMessage, _ string) (Result, error) {
	var in askTeammateInput
	if err := json.Unmarshal(input, &in); err != nil {
		return Result{Content: fmt.Sprintf("invalid input: %v", err), IsError: true}, nil
	}
	name := normalizeTeammateName(in.Name)
	question := strings.TrimSpace(in.Question)
	material := strings.TrimSpace(in.Material)
	if name == "" {
		return Result{Content: "name is required (the teammate to consult)", IsError: true}, nil
	}
	if question == "" {
		return Result{Content: "question is required (what to ask the teammate)", IsError: true}, nil
	}
	if len(material) > maxTeammateMaterialLen {
		material = truncateRunes(material, maxTeammateMaterialLen) + "\n\n[...truncated...]"
	}

	run := t.personaRunner()
	if run == nil {
		return Result{Content: "teammate consultation is unavailable in this run", IsError: true}, nil
	}

	canonical, soul, found, err := t.resolver.ResolveSoul(ctx, name)
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to look up teammate %q: %v", name, err), IsError: true}, nil
	}
	if !found {
		return Result{Content: fmt.Sprintf(
			"No teammate persona found for %q. They may not exist or may not have written a SOUL yet. "+
				"Ask the user to confirm the teammate's handle.", name)}, nil
	}
	soul = strings.TrimSpace(soul)
	if soul == "" {
		return Result{Content: fmt.Sprintf("Teammate %q has not written a SOUL yet, so there is no persona to consult.", canonical)}, nil
	}
	if canonical == "" {
		canonical = name
	}

	reply, err := run(ctx, soul, buildTeammatePrompt(canonical, question, material))
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to consult teammate %q: %v", canonical, err), IsError: true}, nil
	}
	reply = strings.TrimSpace(reply)
	if reply == "" {
		reply = "(the teammate persona returned no response)"
	}
	return Result{Content: fmt.Sprintf("%s's perspective:\n\n%s", canonical, reply)}, nil
}

// normalizeTeammateName strips an optional agent_/@ handle prefix and trims the
// teammate name so "agent_alice", "@alice", and "alice" all resolve alike.
func normalizeTeammateName(raw string) string {
	name := strings.TrimSpace(raw)
	name = strings.TrimPrefix(name, "@")
	for _, prefix := range []string{"agent_", "agent-"} {
		if len(name) > len(prefix) && strings.EqualFold(name[:len(prefix)], prefix) {
			name = name[len(prefix):]
			break
		}
	}
	return strings.TrimSpace(name)
}

// truncateRunes returns s limited to at most maxBytes bytes without splitting a
// UTF-8 sequence, so the forwarded material never becomes invalid UTF-8.
func truncateRunes(s string, maxBytes int) string {
	if len(s) <= maxBytes {
		return s
	}
	cut := maxBytes
	for cut > 0 && !utf8.RuneStart(s[cut]) {
		cut--
	}
	return s[:cut]
}

// buildTeammatePrompt frames the consult message sent to the teammate persona.
func buildTeammatePrompt(name, question, material string) string {
	var b strings.Builder
	fmt.Fprintf(&b, "A colleague's coding agent is consulting you, %s, for your perspective. "+
		"Answer in the first person, in your own voice, as the persona described in your instructions.\n\n", name)
	b.WriteString("Their question:\n")
	b.WriteString(question)
	if material != "" {
		b.WriteString("\n\nMaterial they want your take on:\n")
		b.WriteString(material)
	}
	return b.String()
}

