// GitCommitTool creates a commit with mandatory GitHub App co-author credit.
type GitCommitTool struct {
	Runner sdkgit.CommandRunner
}

func (t *GitCommitTool) Name() string { return "git_commit" }

func (t *GitCommitTool) Description() string {
	return "Create a git commit after optionally staging files. The gratefulagents GitHub App Co-authored-by trailer is added automatically if missing."
}

func (t *GitCommitTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{
		"type": "object",
		"required": ["message"],
		"properties": {
			"message": {
				"type": "string",
				"description": "Commit message subject and optional body. The run's configured commit-attribution policy is applied automatically."
			},
			"repo_path": {
				"type": "string",
				"description": "Workspace-relative path to the git repository, for example repos/<alias>. Defaults to the workspace root."
			},
			"all": {
				"type": "boolean",
				"description": "Stage all changes with git add -A before committing. Defaults to false."
			},
			"paths": {
				"type": "array",
				"items": { "type": "string" },
				"description": "Specific repo-relative paths to stage before committing. Cannot be combined with all=true."
			},
			"no_verify": {
				"type": "boolean",
				"description": "Pass --no-verify to git commit. Defaults to false."
			}
		}
	}`)
}

func (t *GitCommitTool) IsReadOnly() bool { return false }
func (t *GitCommitTool) IsEnabled(ctx *agentsdk.RunContext) bool {
	return ctx == nil || ctx.ToolAccessLevel != agentsdk.ToolAccessLevelReadOnly
}
func (t *GitCommitTool) NeedsApproval() bool { return false }
func (t *GitCommitTool) TimeoutSeconds() int { return 0 }

type gitCommitInput struct {
	Message  string   `json:"message"`
	RepoPath string   `json:"repo_path"`
	All      bool     `json:"all"`
	Paths    []string `json:"paths"`
	NoVerify bool     `json:"no_verify"`
}

type gitCommitOutput struct {
	Status        string `json:"status"`
	CommitSHA     string `json:"commit_sha,omitempty"`
	CoAuthorAdded bool   `json:"co_author_added"`
	Error         string `json:"error,omitempty"`
}

func (t *GitCommitTool) Execute(ctx context.Context, input json.RawMessage, workDir string) (agentsdk.ToolResult, error) {
	var in gitCommitInput
	if err := json.Unmarshal(input, &in); err != nil {
		return gitCommitError("Invalid input: " + err.Error())
	}
	message := strings.TrimSpace(in.Message)
	if message == "" {
		return gitCommitError("message is required")
	}
	if in.All && len(in.Paths) > 0 {
		return gitCommitError("all=true cannot be combined with paths")
	}

	repoDir, err := resolveLocalGitRepositoryWorkDir(workDir, in.RepoPath)
	if err != nil {
		return gitCommitError("repo_path rejected: " + err.Error())
	}

	runner := t.runner()
	if in.All {
		if out, err := runner.RunGit(ctx, repoDir, "add", "-A"); err != nil {
			return gitCommitError(fmt.Sprintf("git add failed: %v\n%s", err, out))
		}
	} else if len(in.Paths) > 0 {
		args := []string{"add", "--"}
		for _, p := range in.Paths {
			path := strings.TrimSpace(p)
			if err := validateGitCommitPath(path); err != nil {
				return gitCommitError(err.Error())
			}
			args = append(args, path)
		}
		if out, err := runner.RunGit(ctx, repoDir, args...); err != nil {
			return gitCommitError(fmt.Sprintf("git add failed: %v\n%s", err, out))
		}
	}

	commitMessage, added := ensureRequiredCoAuthor(message)
	args := []string{"commit"}
	if in.NoVerify {
		args = append(args, "--no-verify")
	}
	args = append(args, "-m", commitMessage)
	if out, err := runner.RunGit(ctx, repoDir, args...); err != nil {
		return gitCommitError(fmt.Sprintf("git commit failed: %v\n%s", err, out))
	}

	sha, err := runner.RunGit(ctx, repoDir, "rev-parse", "HEAD")
	if err != nil {
		return gitCommitError("git rev-parse failed after commit: " + err.Error())
	}
	return gitCommitSuccess(gitCommitOutput{
		Status:        "committed",
		CommitSHA:     strings.TrimSpace(sha),
		CoAuthorAdded: added,
	})
}

func (t *GitCommitTool) runner() sdkgit.CommandRunner {
	if t.Runner != nil {
		return t.Runner
	}
	return localGitCommandRunner{}
}

type coAuthoringGitRunner struct {
	inner sdkgit.CommandRunner
}

func newCoAuthoringGitRunner(inner sdkgit.CommandRunner) sdkgit.CommandRunner {
	return coAuthoringGitRunner{inner: inner}
}

func (r coAuthoringGitRunner) RunGit(ctx context.Context, workDir string, args ...string) (string, error) {
	return r.runner().RunGit(ctx, workDir, addRequiredCoAuthorToCommitArgs(args)...)
}

func (r coAuthoringGitRunner) RunGH(ctx context.Context, workDir string, args ...string) (string, error) {
	return r.runner().RunGH(ctx, workDir, args...)
}

func (r coAuthoringGitRunner) runner() sdkgit.CommandRunner {
	if r.inner != nil {
		return r.inner
	}
	return localGitCommandRunner{}
}

type localGitCommandRunner struct{}

func (localGitCommandRunner) RunGit(ctx context.Context, workDir string, args ...string) (string, error) {
	cmdCtx, cancel := context.WithTimeout(ctx, gitCommandTimeout)
	defer cancel()
	cmd := exec.CommandContext(cmdCtx, "git", args...)
	cmd.Dir = workDir
	out, err := cmd.CombinedOutput()
	return string(out), err
}

func (localGitCommandRunner) RunGH(ctx context.Context, workDir string, args ...string) (string, error) {
	cmdCtx, cancel := context.WithTimeout(ctx, gitCommandTimeout)
	defer cancel()
	cmd := exec.CommandContext(cmdCtx, "gh", args...)
	cmd.Dir = workDir
	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	if err != nil {
		return stdout.String() + stderr.String(), err
	}
	return stdout.String(), nil
}

func addRequiredCoAuthorToCommitArgs(args []string) []string {
	if len(args) == 0 || args[0] != "commit" {
		return args
	}
	for i := 1; i < len(args); i++ {
		arg := args[i]
		if arg == "-m" || arg == "--message" {
			if i+1 < len(args) && messageHasRequiredCoAuthor(args[i+1]) {
				return args
			}
			i++
			continue
		}
		if strings.HasPrefix(arg, "--message=") && messageHasRequiredCoAuthor(strings.TrimPrefix(arg, "--message=")) {
			return args
		}
	}
	out := append([]string(nil), args...)
	return append(out, "-m", requiredCoAuthorTrailer)
}

func ensureRequiredCoAuthor(message string) (string, bool) {
	message = strings.TrimSpace(strings.ReplaceAll(message, "\r\n", "\n"))
	message = strings.ReplaceAll(message, "\r", "\n")
	if messageHasRequiredCoAuthor(message) {
		return message, false
	}
	return message + "\n\n" + requiredCoAuthorTrailer, true
}

func messageHasRequiredCoAuthor(message string) bool {
	for _, line := range strings.Split(message, "\n") {
		line = strings.TrimSpace(line)
		if strings.EqualFold(line, requiredCoAuthorTrailer) {
			return true
		}
	}
	return false
}

func resolveLocalGitRepositoryWorkDir(workDir, repoPath string) (string, error) {
	workDir = strings.TrimSpace(workDir)
	if workDir == "" {
		return "", fmt.Errorf("workspace root is required")
	}
	workspaceRoot, err := filepath.Abs(workDir)
	if err != nil {
		return "", err
	}
	if evaluated, err := filepath.EvalSymlinks(workspaceRoot); err == nil {
		workspaceRoot = evaluated
	}

	repoPath = strings.TrimSpace(repoPath)
	if repoPath == "" || repoPath == "." {
		if !isLocalGitRepository(workspaceRoot) {
			return "", fmt.Errorf("workspace root is not a git repository")
		}
		return workspaceRoot, nil
	}
	if filepath.IsAbs(repoPath) {
		return "", fmt.Errorf("repo_path must be workspace-relative")
	}
	clean := filepath.Clean(repoPath)
	if clean == "." || clean == string(filepath.Separator) {
		return workspaceRoot, nil
	}
	if clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("repo_path resolves outside the workspace")
	}
	resolved := filepath.Join(workspaceRoot, clean)
	if evaluated, err := filepath.EvalSymlinks(resolved); err == nil {
		resolved = evaluated
	}
	rel, err := filepath.Rel(workspaceRoot, resolved)
	if err != nil {
		return "", err
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("repo_path resolves outside the workspace")
	}
	if !isLocalGitRepository(resolved) {
		return "", fmt.Errorf("%s is not a git repository", repoPath)
	}
	return resolved, nil
}

func validateGitCommitPath(path string) error {
	if path == "" {
		return fmt.Errorf("paths must not contain empty entries")
	}
	if filepath.IsAbs(path) {
		return fmt.Errorf("paths must be repo-relative")
	}
	clean := filepath.Clean(path)
	if clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
		return fmt.Errorf("paths must not resolve outside the repository")
	}
	return nil
}

func isLocalGitRepository(dir string) bool {
	info, err := os.Stat(filepath.Join(dir, ".git"))
	if err != nil {
		return false
	}
	return info.IsDir() || info.Mode().IsRegular()
}

func gitCommitSuccess(out gitCommitOutput) (agentsdk.ToolResult, error) {
	b, _ := json.Marshal(out)
	return agentsdk.ToolResult{Content: string(b)}, nil
}

func gitCommitError(msg string) (agentsdk.ToolResult, error) {
	out := gitCommitOutput{Status: "error", Error: msg}
	b, _ := json.Marshal(out)
	return agentsdk.ToolResult{Content: string(b), IsError: true}, nil
}

package tools

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
	sdkgit "github.com/gratefulagents/sdk/pkg/agentsdk/tools/git"
)

// RegisterGitPushTool registers a push tool that refuses to push protected
// branches (main/master/remote default).
func RegisterGitPushTool(registry *Registry) {
	if registry == nil {
		return
	}
	registry.Register(NewGitPushTool(nil))
}

// NewGitPushTool constructs git_push. The runner is injectable for tests.
func NewGitPushTool(runner sdkgit.CommandRunner) *GitPushTool {
	return &GitPushTool{Runner: runner}
}

// GitPushTool pushes the current branch of a workspace repository to origin.
type GitPushTool struct {
	Runner sdkgit.CommandRunner
}

func (t *GitPushTool) Name() string { return "git_push" }

func (t *GitPushTool) Description() string {
	return "Push the current branch of a workspace repository to origin. Refuses to push protected branches (main/master/default). Use repo_path for attached repositories under repos/<alias>."
}

func (t *GitPushTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{
		"type": "object",
		"properties": {
			"repo_path": {
				"type": "string",
				"description": "Workspace-relative path to the git repository, for example repos/<alias>. Defaults to the workspace root."
			}
		}
	}`)
}

func (t *GitPushTool) IsReadOnly() bool      { return false }
func (t *GitPushTool) WritesGitRemote() bool { return true }
func (t *GitPushTool) IsEnabled(ctx *agentsdk.RunContext) bool {
	return ctx == nil || ctx.ToolAccessLevel != agentsdk.ToolAccessLevelReadOnly
}
func (t *GitPushTool) NeedsApproval() bool { return false }
func (t *GitPushTool) TimeoutSeconds() int { return 0 }

type gitPushInput struct {
	RepoPath string `json:"repo_path"`
}

type gitPushOutput struct {
	Status string `json:"status"`
	Branch string `json:"branch,omitempty"`
	Error  string `json:"error,omitempty"`
}

func (t *GitPushTool) Execute(ctx context.Context, input json.RawMessage, workDir string) (agentsdk.ToolResult, error) {
	var in gitPushInput
	if err := json.Unmarshal(input, &in); err != nil {
		return gitPushError("Invalid input: " + err.Error())
	}

	repoDir, err := resolveLocalGitRepositoryWorkDir(workDir, in.RepoPath)
	if err != nil {
		return gitPushError("repo_path rejected: " + err.Error())
	}

	runner := t.runner()
	branch, err := pushableBranch(ctx, runner, repoDir)
	if err != nil {
		return gitPushError(err.Error())
	}

	if out, err := runner.RunGit(ctx, repoDir, "push", "--no-verify", "-u", "origin", "HEAD"); err != nil {
		return gitPushError(fmt.Sprintf("git push failed: %v\n%s", err, out))
	}
	return gitPushSuccess(gitPushOutput{Status: "pushed", Branch: branch})
}

func (t *GitPushTool) runner() sdkgit.CommandRunner {
	if t.Runner != nil {
		return t.Runner
	}
	return localGitCommandRunner{}
}

// pushableBranch returns the current branch in repoDir, or an error if the
// branch is protected (main/master/remote default), detached, or cannot be
// determined.
func pushableBranch(ctx context.Context, runner sdkgit.CommandRunner, repoDir string) (string, error) {
	out, err := runner.RunGit(ctx, repoDir, "rev-parse", "--abbrev-ref", "HEAD")
	if err != nil {
		return "", fmt.Errorf("cannot determine current branch: %v\n%s", err, out)
	}
	branch := strings.TrimSpace(out)
	if branch == "" {
		return "", fmt.Errorf("cannot determine current branch")
	}
	if branch == "HEAD" {
		return "", fmt.Errorf("refusing to push: HEAD is detached")
	}
	if branch == "main" || branch == "master" {
		return "", fmt.Errorf("refusing to push protected branch %q", branch)
	}
	if defOut, err := runner.RunGit(ctx, repoDir, "symbolic-ref", "--short", "refs/remotes/origin/HEAD"); err == nil {
		defaultBranch := strings.TrimPrefix(strings.TrimSpace(defOut), "origin/")
		if defaultBranch != "" && branch == defaultBranch {
			return "", fmt.Errorf("refusing to push default branch %q", branch)
		}
	}
	return branch, nil
}

// branchGuardedGitRunner wraps a git runner and blocks push commands when the
// current branch in the target workDir is protected, detached, or unknown.
type branchGuardedGitRunner struct {
	inner sdkgit.CommandRunner
}

func newBranchGuardedGitRunner(inner sdkgit.CommandRunner) sdkgit.CommandRunner {
	return branchGuardedGitRunner{inner: inner}
}

func (r branchGuardedGitRunner) RunGit(ctx context.Context, workDir string, args ...string) (string, error) {
	if len(args) > 0 && args[0] == "push" {
		if _, err := pushableBranch(ctx, r.runner(), workDir); err != nil {
			return "", err
		}
	}
	return r.runner().RunGit(ctx, workDir, args...)
}

func (r branchGuardedGitRunner) RunGH(ctx context.Context, workDir string, args ...string) (string, error) {
	return r.runner().RunGH(ctx, workDir, args...)
}

func (r branchGuardedGitRunner) runner() sdkgit.CommandRunner {
	if r.inner != nil {
		return r.inner
	}
	return localGitCommandRunner{}
}

func gitPushSuccess(out gitPushOutput) (agentsdk.ToolResult, error) {
	b, _ := json.Marshal(out)
	return agentsdk.ToolResult{Content: string(b)}, nil
}

func gitPushError(msg string) (agentsdk.ToolResult, error) {
	out := gitPushOutput{Status: "error", Error: msg}
	b, _ := json.Marshal(out)
	return agentsdk.ToolResult{Content: string(b), IsError: true}, nil
}

package tools

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
	sdkgit "github.com/gratefulagents/sdk/pkg/agentsdk/tools/git"
)

// RegisterGitSyncTools registers the branch-synchronization tools agents need
// for PR upkeep beyond commit/push: inspecting working-tree state, pulling the
// latest remote changes for the current branch, merging the base branch to
// resolve PR merge conflicts, and aborting a conflicted merge.
func RegisterGitSyncTools(registry *Registry) {
	if registry == nil {
		return
	}
	registry.Register(NewGitStatusTool(nil))
	registry.Register(NewGitPullTool(nil))
	registry.Register(NewGitMergeTool(nil))
	registry.Register(NewGitMergeAbortTool(nil))
}

const gitSyncRepoPathDescription = "Workspace-relative path to the git repository, for example repos/<alias>. Defaults to the workspace root."

// mergeConflictGuidance tells the agent how to finish or abandon a conflicted
// merge using the tools it already has.
const mergeConflictGuidance = "Merge left conflicts in the working tree. Open each conflicted file, resolve the <<<<<<</=======/>>>>>>> markers, then run git_commit (with all=true or the resolved paths) to create the merge commit, and git_push. To abandon the merge instead, run git_merge_abort."

type gitSyncOutput struct {
	Status          string   `json:"status"`
	Branch          string   `json:"branch,omitempty"`
	MergedFrom      string   `json:"merged_from,omitempty"`
	CommitSHA       string   `json:"commit_sha,omitempty"`
	ConflictedFiles []string `json:"conflicted_files,omitempty"`
	Guidance        string   `json:"guidance,omitempty"`
	Output          string   `json:"output,omitempty"`
	Error           string   `json:"error,omitempty"`
}

func gitSyncSuccess(out gitSyncOutput) (agentsdk.ToolResult, error) {
	b, _ := json.Marshal(out)
	return agentsdk.ToolResult{Content: string(b)}, nil
}

func gitSyncError(msg string) (agentsdk.ToolResult, error) {
	b, _ := json.Marshal(gitSyncOutput{Status: "error", Error: msg})
	return agentsdk.ToolResult{Content: string(b), IsError: true}, nil
}

func gitSyncRunner(runner sdkgit.CommandRunner) sdkgit.CommandRunner {
	if runner != nil {
		return runner
	}
	return localGitCommandRunner{}
}

// currentNonDetachedBranch returns the checked-out branch, rejecting detached
// HEAD states where pull/merge would leave commits nowhere useful.
func currentNonDetachedBranch(ctx context.Context, runner sdkgit.CommandRunner, repoDir string) (string, error) {
	out, err := runner.RunGit(ctx, repoDir, "rev-parse", "--abbrev-ref", "HEAD")
	if err != nil {
		return "", fmt.Errorf("cannot determine current branch: %v\n%s", err, out)
	}
	branch := strings.TrimSpace(out)
	if branch == "" {
		return "", fmt.Errorf("cannot determine current branch")
	}
	if branch == "HEAD" {
		return "", fmt.Errorf("HEAD is detached; check out a branch first")
	}
	return branch, nil
}

// gitRefExists reports whether a ref (e.g. MERGE_HEAD, refs/heads/x) resolves.
func gitRefExists(ctx context.Context, runner sdkgit.CommandRunner, repoDir, ref string) bool {
	out, err := runner.RunGit(ctx, repoDir, "rev-parse", "-q", "--verify", ref)
	return err == nil && strings.TrimSpace(out) != ""
}

// listConflictedFiles returns paths that are unmerged in the index.
func listConflictedFiles(ctx context.Context, runner sdkgit.CommandRunner, repoDir string) []string {
	out, err := runner.RunGit(ctx, repoDir, "diff", "--name-only", "--diff-filter=U")
	if err != nil {
		return nil
	}
	var files []string
	for _, line := range strings.Split(out, "\n") {
		if line = strings.TrimSpace(line); line != "" {
			files = append(files, line)
		}
	}
	return files
}

// fetchRemoteBranch force-updates the remote-tracking ref for branch so a
// following merge sees the latest origin state even in single-branch clones.
func fetchRemoteBranch(ctx context.Context, runner sdkgit.CommandRunner, repoDir, branch string) (string, error) {
	return runner.RunGit(ctx, repoDir, "fetch", "origin",
		"+refs/heads/"+branch+":refs/remotes/origin/"+branch)
}

func isMissingRemoteRefError(output string) bool {
	return strings.Contains(output, "couldn't find remote ref")
}

// mergeRefIntoCurrentBranch merges ref into the checked-out branch. Its merge
// commit message always credits the gratefulagents GitHub App as a co-author.
// On conflicts the merge is left in progress and a structured result is returned.
func mergeRefIntoCurrentBranch(ctx context.Context, runner sdkgit.CommandRunner, repoDir, branch, ref string) (agentsdk.ToolResult, error) {
	message, _ := ensureRequiredCoAuthor(fmt.Sprintf("Merge %s into %s", ref, branch))
	mergeOut, err := runner.RunGit(ctx, repoDir, "merge", "--no-edit", "-m", message, ref)
	if err != nil {
		if files := listConflictedFiles(ctx, runner, repoDir); len(files) > 0 {
			return gitSyncSuccess(gitSyncOutput{
				Status:          "conflicts",
				Branch:          branch,
				MergedFrom:      ref,
				ConflictedFiles: files,
				Guidance:        mergeConflictGuidance,
				Output:          strings.TrimSpace(mergeOut),
			})
		}
		msg := fmt.Sprintf("git merge failed: %v\n%s", err, mergeOut)
		if strings.Contains(mergeOut, "would be overwritten") {
			msg += "\nCommit your local changes first (git_commit), then retry."
		}
		return gitSyncError(msg)
	}

	status := "merged"
	if strings.Contains(mergeOut, "Already up to date") {
		status = "up_to_date"
	}
	sha, _ := runner.RunGit(ctx, repoDir, "rev-parse", "HEAD")
	return gitSyncSuccess(gitSyncOutput{
		Status:     status,
		Branch:     branch,
		MergedFrom: ref,
		CommitSHA:  strings.TrimSpace(sha),
		Output:     strings.TrimSpace(mergeOut),
	})
}

// ---------------------------------------------------------------------------
// git_pull

// NewGitPullTool constructs git_pull. The runner is injectable for tests.
func NewGitPullTool(runner sdkgit.CommandRunner) *GitPullTool {
	return &GitPullTool{Runner: runner}
}

// GitPullTool fetches and merges the latest origin state of the current branch.
type GitPullTool struct {
	Runner sdkgit.CommandRunner
}

func (t *GitPullTool) Name() string { return "git_pull" }

func (t *GitPullTool) Description() string {
	return "Fetch and merge the latest origin commits for the current branch (e.g. when the remote PR branch gained commits from a reviewer or another session). Merge only — never rebases or force-pushes. On conflicts it reports the conflicted files so you can resolve them, git_commit, and git_push."
}

func (t *GitPullTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{
		"type": "object",
		"properties": {
			"repo_path": {
				"type": "string",
				"description": "` + gitSyncRepoPathDescription + `"
			}
		}
	}`)
}

func (t *GitPullTool) IsReadOnly() bool { return false }
func (t *GitPullTool) IsEnabled(ctx *agentsdk.RunContext) bool {
	return ctx == nil || ctx.ToolAccessLevel != agentsdk.ToolAccessLevelReadOnly
}
func (t *GitPullTool) NeedsApproval() bool { return false }
func (t *GitPullTool) TimeoutSeconds() int { return 0 }

type gitPullInput struct {
	RepoPath string `json:"repo_path"`
}

func (t *GitPullTool) Execute(ctx context.Context, input json.RawMessage, workDir string) (agentsdk.ToolResult, error) {
	var in gitPullInput
	if err := json.Unmarshal(input, &in); err != nil {
		return gitSyncError("Invalid input: " + err.Error())
	}
	repoDir, err := resolveLocalGitRepositoryWorkDir(workDir, in.RepoPath)
	if err != nil {
		return gitSyncError("repo_path rejected: " + err.Error())
	}

	runner := gitSyncRunner(t.Runner)
	branch, err := currentNonDetachedBranch(ctx, runner, repoDir)
	if err != nil {
		return gitSyncError(err.Error())
	}

	if out, err := fetchRemoteBranch(ctx, runner, repoDir, branch); err != nil {
		if isMissingRemoteRefError(out) {
			return gitSyncSuccess(gitSyncOutput{
				Status: "no_remote_branch",
				Branch: branch,
				Output: fmt.Sprintf("origin has no branch %q; nothing to pull", branch),
			})
		}
		return gitSyncError(fmt.Sprintf("git fetch failed: %v\n%s", err, out))
	}

	return mergeRefIntoCurrentBranch(ctx, runner, repoDir, branch, "origin/"+branch)
}

// ---------------------------------------------------------------------------
// git_merge

// NewGitMergeTool constructs git_merge. The runner is injectable for tests.
func NewGitMergeTool(runner sdkgit.CommandRunner) *GitMergeTool {
	return &GitMergeTool{Runner: runner}
}

// GitMergeTool merges another branch (typically the PR base) into the current
// branch, the safe way to clear "this branch has conflicts" on a PR without
// rewriting history.
type GitMergeTool struct {
	Runner sdkgit.CommandRunner
}

func (t *GitMergeTool) Name() string { return "git_merge" }

func (t *GitMergeTool) Description() string {
	return "Merge another branch (typically the PR base branch, e.g. main) into the current branch — the way to fix a PR that has merge conflicts with its base. Fetches origin/<branch> first, falling back to the local branch. On conflicts it reports the conflicted files: resolve the markers, then git_commit to complete the merge and git_push."
}

func (t *GitMergeTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{
		"type": "object",
		"required": ["branch"],
		"properties": {
			"branch": {
				"type": "string",
				"description": "Branch to merge into the current branch, e.g. main or origin/main."
			},
			"repo_path": {
				"type": "string",
				"description": "` + gitSyncRepoPathDescription + `"
			}
		}
	}`)
}

func (t *GitMergeTool) IsReadOnly() bool { return false }
func (t *GitMergeTool) IsEnabled(ctx *agentsdk.RunContext) bool {
	return ctx == nil || ctx.ToolAccessLevel != agentsdk.ToolAccessLevelReadOnly
}
func (t *GitMergeTool) NeedsApproval() bool { return false }
func (t *GitMergeTool) TimeoutSeconds() int { return 0 }

type gitMergeInput struct {
	Branch   string `json:"branch"`
	RepoPath string `json:"repo_path"`
}

func (t *GitMergeTool) Execute(ctx context.Context, input json.RawMessage, workDir string) (agentsdk.ToolResult, error) {
	var in gitMergeInput
	if err := json.Unmarshal(input, &in); err != nil {
		return gitSyncError("Invalid input: " + err.Error())
	}
	name := strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(in.Branch), "origin/"))
	if name == "" {
		return gitSyncError("branch is required")
	}
	repoDir, err := resolveLocalGitRepositoryWorkDir(workDir, in.RepoPath)
	if err != nil {
		return gitSyncError("repo_path rejected: " + err.Error())
	}

	runner := gitSyncRunner(t.Runner)
	branch, err := currentNonDetachedBranch(ctx, runner, repoDir)
	if err != nil {
		return gitSyncError(err.Error())
	}

	ref := "origin/" + name
	if out, err := fetchRemoteBranch(ctx, runner, repoDir, name); err != nil {
		if !isMissingRemoteRefError(out) {
			return gitSyncError(fmt.Sprintf("git fetch failed: %v\n%s", err, out))
		}
		if !gitRefExists(ctx, runner, repoDir, "refs/heads/"+name) {
			return gitSyncError(fmt.Sprintf("branch %q not found on origin or locally", name))
		}
		ref = name
	}

	return mergeRefIntoCurrentBranch(ctx, runner, repoDir, branch, ref)
}

