const defaultGitHubLabelColor = "BFD4F2"

type githubLabel struct {
	Name string `json:"name"`
}

// ensureGitHubLabels creates any requested labels that do not already exist in
// the selected repository. GitHub label names are case-insensitive.
func ensureGitHubLabels(ctx context.Context, runner prReviewRunner, workDir string, labels []string) error {
	labels = nonBlankUniqueFold(labels)
	if len(labels) == 0 {
		return nil
	}

	out, err := runner.RunGH(ctx, workDir, "label", "list", "--limit", "1000", "--json", "name")
	if err != nil {
		return fmt.Errorf("list repository labels: %w\n%s", err, out)
	}
	var existing []githubLabel
	if err := json.Unmarshal([]byte(out), &existing); err != nil {
		return fmt.Errorf("parse repository labels: %w", err)
	}
	existingNames := make(map[string]struct{}, len(existing))
	for _, label := range existing {
		existingNames[strings.ToLower(strings.TrimSpace(label.Name))] = struct{}{}
	}

	for _, label := range labels {
		key := strings.ToLower(label)
		if _, ok := existingNames[key]; ok {
			continue
		}
		createOut, createErr := runner.RunGH(ctx, workDir, "label", "create", "--color", defaultGitHubLabelColor, "--", label)
		if createErr != nil && !strings.Contains(strings.ToLower(createOut), "already exists") {
			return fmt.Errorf("create repository label %q: %w\n%s", label, createErr, createOut)
		}
		existingNames[key] = struct{}{}
	}
	return nil
}

func nonBlankUniqueFold(values []string) []string {
	seen := make(map[string]struct{}, len(values))
	result := make([]string, 0, len(values))
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value == "" {
			continue
		}
		key := strings.ToLower(value)
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		result = append(result, value)
	}
	return result
}

package tools

import (
	"encoding/json"
	"fmt"
	"math"
	"reflect"
	"unicode/utf8"
)

// minimalJSONSchema is a dependency-free validator for the JSON Schema subset
// used by task output schemas. Supported keywords:
//
//   - type: one of object, array, string, number, integer, boolean, null
//   - properties (object)
//   - required (object)
//   - items (single schema, arrays)
//   - enum and const
//   - additionalProperties (boolean form only)
//   - minimum/maximum, minLength/maxLength, and minItems/maxItems
//   - allOf, anyOf, oneOf, not, and if/then/else
//
// All other keywords (and non-boolean additionalProperties, type unions,
// $ref, pattern, format, ...) are ignored:
// values pass validation for keywords this validator does not understand.
type minimalJSONSchema struct {
	raw map[string]any
}

// parseMinimalJSONSchema parses schemaJSON into a validator. The document
// must be a JSON object.
func parseMinimalJSONSchema(schemaJSON string) (*minimalJSONSchema, error) {
	var raw any
	if err := json.Unmarshal([]byte(schemaJSON), &raw); err != nil {
		return nil, fmt.Errorf("schema is not valid JSON: %w", err)
	}
	obj, ok := raw.(map[string]any)
	if !ok {
		return nil, fmt.Errorf("schema must be a JSON object, got %s", jsonTypeName(raw))
	}
	return &minimalJSONSchema{raw: obj}, nil
}

// Validate checks a decoded JSON value (the encoding/json interface{}
// representation) against the schema and returns the first violation found.
func (s *minimalJSONSchema) Validate(value any) error {
	return validateJSONSubset(s.raw, value, "$")
}

func validateJSONSubset(schema map[string]any, value any, path string) error {
	if constant, ok := schema["const"]; ok && !reflect.DeepEqual(constant, value) {
		return fmt.Errorf("%s: value does not equal the schema const", path)
	}
	if err := validateJSONComposition(schema, value, path); err != nil {
		return err
	}
	if typ, ok := schema["type"].(string); ok {
		if err := checkJSONType(typ, value, path); err != nil {
			return err
		}
	}
	if enum, ok := schema["enum"].([]any); ok {
		matched := false
		for _, candidate := range enum {
			if reflect.DeepEqual(candidate, value) {
				matched = true
				break
			}
		}
		if !matched {
			return fmt.Errorf("%s: value is not one of the enum values", path)
		}
	}
	if number, ok := value.(float64); ok {
		if minimum, exists := schema["minimum"].(float64); exists && number < minimum {
			return fmt.Errorf("%s: value must be at least %v", path, minimum)
		}
		if maximum, exists := schema["maximum"].(float64); exists && number > maximum {
			return fmt.Errorf("%s: value must be at most %v", path, maximum)
		}
	}
	if stringValue, ok := value.(string); ok {
		length := float64(utf8.RuneCountInString(stringValue))
		if minimum, exists := schema["minLength"].(float64); exists && length < minimum {
			return fmt.Errorf("%s: value must contain at least %v characters", path, minimum)
		}
		if maximum, exists := schema["maxLength"].(float64); exists && length > maximum {
			return fmt.Errorf("%s: value must contain at most %v characters", path, maximum)
		}
	}
	if obj, ok := value.(map[string]any); ok {
		if required, ok := schema["required"].([]any); ok {
			for _, entry := range required {
				name, ok := entry.(string)
				if !ok {
					continue
				}
				if _, present := obj[name]; !present {
					return fmt.Errorf("%s: missing required property %q", path, name)
				}
			}
		}
		properties, _ := schema["properties"].(map[string]any)
		for name, propValue := range obj {
			propSchema, hasSchema := properties[name].(map[string]any)
			if hasSchema {
				if err := validateJSONSubset(propSchema, propValue, path+"."+name); err != nil {
					return err
				}
				continue
			}
			if additional, ok := schema["additionalProperties"].(bool); ok && !additional {
				return fmt.Errorf("%s: additional property %q is not allowed", path, name)
			}
		}
	}
	if arr, ok := value.([]any); ok {
		length := float64(len(arr))
		if minimum, exists := schema["minItems"].(float64); exists && length < minimum {
			return fmt.Errorf("%s: value must contain at least %v items", path, minimum)
		}
		if maximum, exists := schema["maxItems"].(float64); exists && length > maximum {
			return fmt.Errorf("%s: value must contain at most %v items", path, maximum)
		}
		if items, ok := schema["items"].(map[string]any); ok {
			for i, element := range arr {
				if err := validateJSONSubset(items, element, fmt.Sprintf("%s[%d]", path, i)); err != nil {
					return err
				}
			}
		}
	}
	return nil
}

func validateJSONComposition(schema map[string]any, value any, path string) error {
	if branches, ok := schema["allOf"].([]any); ok {
		for index, raw := range branches {
			branch, ok := raw.(map[string]any)
			if !ok {
				continue
			}
			if err := validateJSONSubset(branch, value, path); err != nil {
				return fmt.Errorf("%s: allOf[%d]: %w", path, index, err)
			}
		}
	}
	for _, keyword := range []string{"anyOf", "oneOf"} {
		branches, ok := schema[keyword].([]any)
		if !ok {
			continue
		}
		matches := 0
		for _, raw := range branches {
			branch, ok := raw.(map[string]any)
			if ok && validateJSONSubset(branch, value, path) == nil {
				matches++
			}
		}
		if keyword == "anyOf" && matches == 0 {
			return fmt.Errorf("%s: value must satisfy at least one anyOf branch", path)
		}
		if keyword == "oneOf" && matches != 1 {
			return fmt.Errorf("%s: value must satisfy exactly one oneOf branch (matched %d)", path, matches)
		}
	}
	if disallowed, ok := schema["not"].(map[string]any); ok && validateJSONSubset(disallowed, value, path) == nil {
		return fmt.Errorf("%s: value satisfies a disallowed schema", path)
	}
	if condition, ok := schema["if"].(map[string]any); ok {
		keyword := "else"
		if validateJSONSubset(condition, value, path) == nil {
			keyword = "then"
		}
		if branch, ok := schema[keyword].(map[string]any); ok {
			if err := validateJSONSubset(branch, value, path); err != nil {
				return fmt.Errorf("%s: %s: %w", path, keyword, err)
			}
		}
	}
	return nil
}

func checkJSONType(typ string, value any, path string) error {
	ok := false
	switch typ {
	case "object":
		_, ok = value.(map[string]any)
	case "array":
		_, ok = value.([]any)
	case "string":
		_, ok = value.(string)
	case "number":
		_, ok = value.(float64)
	case "integer":
		if n, isNumber := value.(float64); isNumber {
			ok = n == math.Trunc(n)
		}
	case "boolean":
		_, ok = value.(bool)
	case "null":
		ok = value == nil
	default:
		// Unknown type names are ignored like any other unsupported keyword.
		return nil
	}
	if !ok {
		return fmt.Errorf("%s: expected %s, got %s", path, typ, jsonTypeName(value))
	}
	return nil
}

func jsonTypeName(value any) string {
	switch value.(type) {
	case map[string]any:
		return "object"
	case []any:
		return "array"
	case string:
		return "string"
	case float64:
		return "number"
	case bool:
		return "boolean"
	case nil:
		return "null"
	}
	return "unknown"
}

package tools

import (
	"context"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"sync"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	"github.com/gratefulagents/sdk/pkg/agentsdk"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

const (
	maxSkillDescriptionLength = 240
	skillNameField            = "name"
)

// RegisterLoadSkillTool registers progressive skill loading for the skills
// enabled on a run. Skill summaries are advertised in the tool description;
// full instructions enter model context only when the model calls load_skill.
//
// implicit names are tool-companion skills (for example the computer-use
// guide when the computer_use tool is registered). They are offered without
// being listed in spec.skillRefs, but only when the Skill resource exists in
// the run's namespace, so an uninstalled companion never appears in the menu.
func RegisterLoadSkillTool(ctx context.Context, registry *Registry, k8sClient client.Client, run *platformv1alpha1.AgentRun, implicit ...string) *LoadSkillTool {
	if registry == nil || k8sClient == nil || run == nil {
		return nil
	}

	allowed := make(map[string]struct{}, len(run.Spec.SkillRefs))
	for _, ref := range run.Spec.SkillRefs {
		if name := strings.TrimSpace(ref.Name); name != "" {
			allowed[name] = struct{}{}
		}
	}
	summaries := make(map[string]string, len(allowed)+len(implicit))
	for _, name := range implicit {
		name = strings.TrimSpace(name)
		if name == "" {
			continue
		}
		if _, ok := allowed[name]; ok {
			continue
		}
		skill := &platformv1alpha1.Skill{}
		if err := k8sClient.Get(ctx, client.ObjectKey{Namespace: run.Namespace, Name: name}, skill); err != nil {
			continue
		}
		allowed[name] = struct{}{}
		summaries[name] = skillDescription(skill)
	}
	if len(allowed) == 0 {
		return nil
	}

	names := make([]string, 0, len(allowed))
	for name := range allowed {
		names = append(names, name)
	}
	sort.Strings(names)

	for _, name := range names {
		if _, ok := summaries[name]; ok {
			continue
		}
		skill := &platformv1alpha1.Skill{}
		if err := k8sClient.Get(ctx, client.ObjectKey{Namespace: run.Namespace, Name: name}, skill); err == nil {
			summaries[name] = skillDescription(skill)
		}
	}

	tool := &LoadSkillTool{
		k8sClient: k8sClient,
		namespace: run.Namespace,
		allowed:   allowed,
		names:     names,
		summaries: summaries,
		loaded:    make(map[string]string),
	}
	registry.Register(tool)
	return tool
}

// LoadSkillTool loads one enabled skill's complete instructions on demand.
type LoadSkillTool struct {
	k8sClient client.Client
	namespace string
	allowed   map[string]struct{}
	names     []string
	summaries map[string]string

	mu     sync.RWMutex
	loaded map[string]string
}

type loadSkillInput struct {
	Name string `json:"name"`
}

func (t *LoadSkillTool) Name() string { return "load_skill" }

func (t *LoadSkillTool) Description() string {
	var b strings.Builder
	b.WriteString("Load an enabled skill's full instructions into the current context. Use this when a skill is relevant to the user's task; skills are not loaded until you call this tool. Available skills:")
	for _, name := range t.names {
		b.WriteString("\n- ")
		b.WriteString(name)
		if description := strings.TrimSpace(t.summaries[name]); description != "" {
			b.WriteString(": ")
			b.WriteString(description)
		}
	}

	return b.String()
}

// LoadedInstructions returns the guidance explicitly loaded through the tool.
// The agent runtime reads this for each model turn and appends it to trusted
// agent instructions, so skill content is neither eager nor treated as an
// untrusted tool-output instruction block.
func (t *LoadSkillTool) LoadedInstructions() string {
	t.mu.RLock()
	defer t.mu.RUnlock()

	var b strings.Builder
	for _, name := range t.names {
		if instructions := t.loaded[name]; instructions != "" {
			if b.Len() == 0 {
				b.WriteString("# Loaded skill guidance")
			}
			b.WriteString("\n\n## Skill: ")
			b.WriteString(name)
			b.WriteString("\n")
			b.WriteString(instructions)
		}
	}
	return b.String()
}

func (t *LoadSkillTool) InputSchema() json.RawMessage {
	schema := map[string]any{
		"type": "object",
		"properties": map[string]any{
			skillNameField: map[string]any{
				"type":        "string",
				"description": "The enabled skill to load.",
				"enum":        t.names,
			},
		},
		"required":             []string{skillNameField},
		"additionalProperties": false,
	}
	encoded, _ := json.Marshal(schema)
	return encoded
}

func (t *LoadSkillTool) IsReadOnly() bool                      { return true }
func (t *LoadSkillTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }
func (t *LoadSkillTool) NeedsApproval() bool                   { return false }
func (t *LoadSkillTool) TimeoutSeconds() int                   { return 30 }

func (t *LoadSkillTool) Execute(ctx context.Context, input json.RawMessage, _ string) (Result, error) {
	var in loadSkillInput
	if err := json.Unmarshal(input, &in); err != nil {
		return Result{Content: fmt.Sprintf("invalid input: %v", err), IsError: true}, nil
	}
	name := strings.TrimSpace(in.Name)
	if _, ok := t.allowed[name]; !ok {
		return Result{Content: fmt.Sprintf("skill %q is not enabled for this run", name), IsError: true}, nil
	}

	skill := &platformv1alpha1.Skill{}
	if err := t.k8sClient.Get(ctx, client.ObjectKey{Namespace: t.namespace, Name: name}, skill); err != nil {
		return Result{Content: fmt.Sprintf("failed to load skill %q: %v", name, err), IsError: true}, nil
	}
	instructions := skillInstructions(skill)
	if instructions == "" {
		return Result{Content: fmt.Sprintf("skill %q has no resolved instructions yet", name), IsError: true}, nil
	}

	t.mu.Lock()
	t.loaded[name] = skillInstructionsWithProvenance(skill, instructions)
	t.mu.Unlock()
	return Result{Content: fmt.Sprintf("Skill %q loaded into the current context.", name)}, nil
}

func skillDescription(skill *platformv1alpha1.Skill) string {
	if skill == nil {
		return ""
	}
	description := strings.TrimSpace(skill.Spec.Description)
	if description == "" && skill.Status.Resolved != nil {
		if resolved := strings.TrimSpace(skill.Status.Resolved.Description); resolved != "" {
			description = resolved
		}
	}
	runes := []rune(description)
	if len(runes) > maxSkillDescriptionLength {
		description = string(runes[:maxSkillDescriptionLength]) + "…"
	}
	return description
}

func skillInstructionsWithProvenance(skill *platformv1alpha1.Skill, instructions string) string {
	if skill == nil || skill.Spec.Source.Git == nil {
		return instructions
	}
	git := skill.Spec.Source.Git
	var b strings.Builder
	b.WriteString("Upstream source: ")
	b.WriteString(git.URL)
	if git.Ref != "" {
		b.WriteString(" @ ")
		b.WriteString(git.Ref)
	}
	if git.Path != "" {
		b.WriteString(" (path: ")
		b.WriteString(git.Path)
		b.WriteString(")")
	}
	if attribution := strings.TrimSpace(skill.Spec.Description); attribution != "" {
		b.WriteString("\nCatalog attribution and license: ")
		b.WriteString(attribution)
	}
	b.WriteString("\n\n")
	b.WriteString(instructions)
	return b.String()
}

func skillInstructions(skill *platformv1alpha1.Skill) string {
	if skill == nil || strings.EqualFold(strings.TrimSpace(skill.Status.Phase), "Invalid") {
		return ""
	}
	if skill.Status.Resolved != nil {
		if instructions := strings.TrimSpace(skill.Status.Resolved.Instructions); instructions != "" {
			return instructions
		}
	}
	if skill.Spec.Source.Inline != nil {
		return strings.TrimSpace(skill.Spec.Source.Inline.Instructions)
	}
	return ""
}

