func (t *waitForRepoEventsTool) Name() string { return "wait_for_repo_events" }
func (t *waitForRepoEventsTool) Description() string {
	return "Watch the maintained repository. Without a cursor it explicitly returns the current snapshot. When cursor_handle is returned, subsequent semantic waits should pass cursor \"latest\", which resolves trusted run-and-repository-bound state server-side; Legacy and DualRead responses instead require their returned cursor. Encoded semantic v2 cursors remain accepted temporarily for compatibility and diagnostics. A closed event does not prove merge; inspect the PR before finalization."
}
func (t *waitForRepoEventsTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{"type":"object","properties":{"timeout_seconds":{"type":"integer","minimum":30,"maximum":21600},"cursor":{"type":"string"}}}`)
}
func (t *waitForRepoEventsTool) IsReadOnly() bool                      { return true }
func (t *waitForRepoEventsTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }
func (t *waitForRepoEventsTool) NeedsApproval() bool                   { return false }
func (t *waitForRepoEventsTool) TimeoutSeconds() int                   { return 21660 }

func (t *waitForRepoEventsTool) Execute(ctx context.Context, input json.RawMessage, workDir string) (Result, error) {
	repository, err := t.repository(ctx)
	if err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	mode := triggersv1alpha1.MaintainerWorkItemCutoverController
	if repository.Spec.Maintainer != nil && repository.Spec.Maintainer.WorkItemCutover != "" {
		mode = repository.Spec.Maintainer.WorkItemCutover
	}
	if mode == triggersv1alpha1.MaintainerWorkItemCutoverController {
		return t.executeSemanticWorkItemWait(ctx, input)
	}
	result, executeErr := t.executeLegacy(ctx, input, workDir)
	if mode != triggersv1alpha1.MaintainerWorkItemCutoverDualRead || executeErr != nil || result.IsError {
		return result, executeErr
	}
	// DualRead is deliberately rollbackable: legacy remains authoritative while
	// normalized legacy and controller-owned semantic projections are compared.
	wd, resolveErr := resolveLocalGitRepositoryWorkDir(workDir, "")
	var mismatches []string
	if resolveErr == nil {
		legacy, snapshotErr := t.repoEventsSnapshot(ctx, wd, true)
		if snapshotErr != nil {
			resolveErr = snapshotErr
		} else {
			mismatches = maintainerSemanticParityMismatches(legacy)
		}
	}
	var payload map[string]any
	if err := json.Unmarshal([]byte(result.Content), &payload); err == nil {
		payload["migration_mode"] = string(mode)
		payload["semantic_parity"] = resolveErr == nil && len(mismatches) == 0
		if resolveErr != nil {
			payload["semantic_parity_error"] = resolveErr.Error()
		} else if len(mismatches) > 0 {
			payload["semantic_parity_mismatches"] = mismatches
		}
		if encoded, err := json.Marshal(payload); err == nil {
			result.Content = string(encoded)
		}
	}
	return result, executeErr
}

func maintainerSemanticParityMismatches(snapshot maintainerRepoEventsSnapshot) []string {
	legacyIssues := map[int32]string{}
	for _, issue := range snapshot.issues {
		issueLabels := append([]string(nil), issue.Labels...)
		sort.Strings(issueLabels)
		legacyIssues[int32(issue.Number)] = issue.Title + "|" + strings.Join(issueLabels, ",")
	}
	semanticIssues := map[int32]string{}
	semanticRuns := map[string]string{}
	semanticPRs := map[string]string{}
	for _, item := range snapshot.workItems {
		if observation := item.IssueObservation; item.ObservationFresh && observation != nil && observation.State == triggersv1alpha1.MaintainerIssueStateOpen {
			observationLabels := append([]string(nil), observation.Labels...)
			sort.Strings(observationLabels)
			semanticIssues[observation.Number] = observation.Title + "|" + strings.Join(observationLabels, ",")
		}
		for _, run := range item.AgentRuns {
			semanticRuns[run.Name] = run.Phase
		}
		for _, pr := range item.PullRequests {
			semanticPRs[pr.URL] = pr.HeadSHA + "|" + string(pr.State) + "|" + strconv.FormatBool(pr.Draft) + "|" + pr.ReviewDecision
		}
	}
	legacyRuns := map[string]string{}
	for name, run := range snapshot.fleet {
		legacyRuns[name] = string(run.Phase)
	}
	legacyPRs := map[string]string{}
	for prURL, pr := range snapshot.pullRequests {
		legacyPRs[prURL] = pr.HeadSHA + "|" + strings.ToLower(pr.State) + "|" + strconv.FormatBool(pr.Draft) + "|" + pr.ReviewDecision
	}
	var mismatches []string
	if !maps.Equal(legacyIssues, semanticIssues) {
		mismatches = append(mismatches, "open issue observations differ")
	}
	if !maps.Equal(legacyRuns, semanticRuns) {
		mismatches = append(mismatches, "fleet run projections differ")
	}
	if !maps.Equal(legacyPRs, semanticPRs) {
		mismatches = append(mismatches, "pull request projections differ")
	}
	return mismatches
}

//nolint:gocyclo // Legacy polling remains intact only as the rollback/parity baseline during cutover.
func (t *waitForRepoEventsTool) executeLegacy(ctx context.Context, input json.RawMessage, workDir string) (Result, error) {
	var in waitForRepoEventsInput
	if err := json.Unmarshal(input, &in); err != nil {
		return Result{Content: fmt.Sprintf("invalid input: %v", err), IsError: true}, nil
	}
	timeout := in.TimeoutSeconds
	if timeout == 0 {
		timeout = defaultRepoEventsTimeout
	}
	if timeout < minRepoEventsTimeout || timeout > maxRepoEventsTimeout {
		return Result{Content: "timeout_seconds must be between 30 and 21600", IsError: true}, nil
	}
	if _, err := t.currentRun(ctx); err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	wd, err := resolveLocalGitRepositoryWorkDir(workDir, "")
	if err != nil {
		return Result{Content: fmt.Sprintf("workspace repository unavailable: %v", err), IsError: true}, nil
	}
	var previous maintainerRepoEventsSnapshot
	cursorProvided := strings.TrimSpace(in.Cursor) != ""
	if cursorProvided {
		cursor, err := decodeMaintainerRepoEventsCursor(in.Cursor)
		if err != nil {
			return Result{Content: fmt.Sprintf("invalid cursor: %v", err), IsError: true}, nil
		}
		previous = snapshotFromMaintainerRepoEventsCursor(cursor)
	}

	current, err := t.repoEventsSnapshot(ctx, wd, true)
	if err != nil {
		if !cursorProvided {
			return Result{Content: err.Error(), IsError: true}, nil
		}
		// A transient fleet-listing failure must not abort a long wait when a
		// cursor already carries the last acknowledged state. Degrade like a
		// backlog or pull-request polling failure: keep the acknowledged
		// signatures, surface fleet_error, and let the tickers re-establish
		// live state.
		current = previous
		current.fleetError = err.Error()
	}
	if cursorProvided && current.workItemError != "" {
		current.workItemSignatures = previous.workItemSignatures
		current.workItems = previous.workItems
	}
	if !cursorProvided {
		// First call of an episode: return the current backlog and fleet state
		// immediately instead of arming a delta wait. A "wait for change from
		// now" snapshot silently swallows everything that happened moments
		// before it — e.g. a fleet run this maintainer just promoted to
		// Succeeded — leaving the maintainer blocked for the full timeout with
		// free capacity and an open backlog. The maintainer must reason from
		// current reality first, then wait with the returned cursor.
		return t.repoEventsResult(maintainerRepoEventsSnapshot{}, current, true, false, time.Time{}, false)
	}
	if repoEventsChanged(previous, current) {
		return t.repoEventsResult(previous, current, true, false, time.Time{}, true)
	}

	started := time.Now()
	deadline := time.NewTimer(time.Duration(timeout) * time.Second)
	defer deadline.Stop()
	backlogTicker := time.NewTicker(t.effectiveBacklogPollInterval())
	defer backlogTicker.Stop()
	fleetTicker := time.NewTicker(t.effectiveFleetPollInterval())
	defer fleetTicker.Stop()
	pullRequestTicker := time.NewTicker(t.effectivePullRequestPollInterval())
	defer pullRequestTicker.Stop()
	latest := current
	workItems, workItemWatcher, workItemErr := t.workItemSnapshotAndWatch(ctx)
	var workItemEvents <-chan watch.Event
	if workItemErr != nil {
		return Result{Content: fmt.Sprintf("failed to establish MaintainerWorkItem watch: %v", workItemErr), IsError: true}, nil
	} else {
		latest.workItemSignatures = workItems.workItemSignatures
		latest.workItems = workItems.workItems
		latest.workItemResourceVersion = workItems.workItemResourceVersion
		latest.workItemError = ""
		if workItemWatcher != nil {
			defer workItemWatcher.Stop()
			workItemEvents = workItemWatcher.ResultChan()
		}
	}
	if repoEventsChanged(previous, latest) {
		return t.repoEventsResult(previous, latest, true, false, started, cursorProvided)
	}
	for {
		select {
		case <-ctx.Done():
			return Result{Content: fmt.Sprintf("wait cancelled: %v", ctx.Err()), IsError: true}, nil
		case <-deadline.C:
			return t.repoEventsResult(previous, latest, false, true, started, cursorProvided)
		case _, ok := <-workItemEvents:
			if !ok {
				workItemEvents = nil
				continue
			}
			workItems, workItemErr := t.workItemEventsSnapshot(ctx)
			if workItemErr != nil {
				latest.workItemError = workItemErr.Error()
			} else {
				latest.workItemSignatures = workItems.workItemSignatures
				latest.workItems = workItems.workItems
				latest.workItemResourceVersion = workItems.workItemResourceVersion
				latest.workItemError = ""
			}
			if repoEventsChanged(previous, latest) {
				return t.repoEventsResult(previous, latest, true, false, started, cursorProvided)
			}
		case <-backlogTicker.C:
			backlog, backlogErr := t.backlogSnapshot(ctx, wd)
			if backlogErr != nil {
				latest.backlogError = backlogErr.Error()
			} else {
				latest.backlogFingerprint = backlog.backlogFingerprint
				latest.issueSignatures = backlog.issueSignatures
				latest.issues = backlog.issues
				latest.backlogAvailable = true
				latest.backlogError = ""
			}
			if repoEventsChanged(previous, latest) {
				return t.repoEventsResult(previous, latest, true, false, started, cursorProvided)
			}
		case <-fleetTicker.C:
			fleet, fleetErr := t.fleetEventsSnapshot(ctx)
			if fleetErr != nil {
				latest.fleetError = fleetErr.Error()
			} else {
				latest.fleetSignatures = fleet.fleetSignatures
				latest.fleet = fleet.fleet
				latest.fleetError = ""
			}
			workItems, workItemErr := t.workItemEventsSnapshot(ctx)
			if workItemErr != nil {
				latest.workItemError = workItemErr.Error()
			} else {
				latest.workItemSignatures = workItems.workItemSignatures
				latest.workItems = workItems.workItems
				latest.workItemResourceVersion = workItems.workItemResourceVersion
				latest.workItemError = ""
			}
			if repoEventsChanged(previous, latest) {
				return t.repoEventsResult(previous, latest, true, false, started, cursorProvided)
			}
		case <-pullRequestTicker.C:
			if latest.fleetError != "" {
				// The attached-PR set derives from live fleet state. Polling
				// with the stale or empty fleet map carried through a fleet
				// failure would drop every tracked PR signature and misreport
				// the PRs as removed; wait for the fleet ticker to recover.
				continue
			}
			pullRequests, pullRequestErr := t.pullRequestEventsSnapshot(ctx, wd, latest.fleet)
			if pullRequestErr != nil {
				latest.pullRequestError = pullRequestErr.Error()
			} else {
				latest.pullRequestSignatures = pullRequests.pullRequestSignatures
				latest.pullRequests = pullRequests.pullRequests
				latest.pullRequestError = pullRequests.pullRequestError
			}
			if repoEventsChanged(previous, latest) {
				return t.repoEventsResult(previous, latest, true, false, started, cursorProvided)
			}
		}
	}
}

func (t *waitForRepoEventsTool) effectiveBacklogPollInterval() time.Duration {
	if t.backlogPollInterval > 0 {
		return t.backlogPollInterval
	}
	return defaultBacklogPollInterval
}

func (t *waitForRepoEventsTool) effectiveFleetPollInterval() time.Duration {
	if t.fleetPollInterval > 0 {
		return t.fleetPollInterval
	}
	return defaultFleetEventsPollInterval
}

func (t *waitForRepoEventsTool) effectivePullRequestPollInterval() time.Duration {
	if t.pullRequestPollInterval > 0 {
		return t.pullRequestPollInterval
	}
	return defaultPullRequestEventsPollInterval
}

func (t *waitForRepoEventsTool) repoEventsSnapshot(ctx context.Context, workDir string, includeBacklog bool) (maintainerRepoEventsSnapshot, error) {
	fleet, err := t.fleetEventsSnapshot(ctx)
	if err != nil {
		return maintainerRepoEventsSnapshot{}, err
	}
	pullRequests, pullRequestErr := t.pullRequestEventsSnapshot(ctx, workDir, fleet.fleet)
	if pullRequestErr != nil {
		fleet.pullRequestError = pullRequestErr.Error()
	} else {
		fleet.pullRequestSignatures = pullRequests.pullRequestSignatures
		fleet.pullRequests = pullRequests.pullRequests
		fleet.pullRequestError = pullRequests.pullRequestError
	}
	workItems, workItemErr := t.workItemEventsSnapshot(ctx)
	if workItemErr != nil {
		fleet.workItemError = workItemErr.Error()
	} else {
		fleet.workItemSignatures = workItems.workItemSignatures
		fleet.workItems = workItems.workItems
		fleet.workItemResourceVersion = workItems.workItemResourceVersion
	}
	if !includeBacklog {
		return fleet, nil
	}
	backlog, err := t.backlogSnapshot(ctx, workDir)
	if err != nil {
		fleet.backlogError = err.Error()
		return fleet, nil
	}
	fleet.backlogFingerprint = backlog.backlogFingerprint
	fleet.issueSignatures = backlog.issueSignatures
	fleet.issues = backlog.issues
	fleet.backlogAvailable = true
	return fleet, nil
}

func (t *waitForRepoEventsTool) backlogSnapshot(ctx context.Context, workDir string) (maintainerRepoEventsSnapshot, error) {
	runner := t.runner
	if runner == nil {
		runner = prReviewExecRunner{}
	}
	out, err := runner.RunGH(ctx, workDir, "issue", "list", "--state", "open", "--json", "number,title,labels,updatedAt,url", "--limit", "200")
	if err != nil {
		return maintainerRepoEventsSnapshot{}, fmt.Errorf("gh issue list failed: %w: %s", err, strings.TrimSpace(out))
	}
	var issues []maintainerBacklogIssue
	if err := json.Unmarshal([]byte(out), &issues); err != nil {
		return maintainerRepoEventsSnapshot{}, fmt.Errorf("parse gh issue list output: %w", err)
	}
	return maintainerBacklogSnapshot(issues), nil
}

func maintainerBacklogSnapshot(issues []maintainerBacklogIssue) maintainerRepoEventsSnapshot {
	entries := make([]string, 0, len(issues))
	signatures := make(map[string]string, len(issues))
	output := make([]maintainerRepoEventIssue, 0, len(issues))
	for _, issue := range issues {
		labels := maintainerIssueLabels(issue.Labels)
		entry := strconv.Itoa(issue.Number) + "|" + issue.UpdatedAt + "|" + strings.Join(labels, ",")
		entries = append(entries, entry)
		signatures[strconv.Itoa(issue.Number)] = maintainerRepoEventSignature(entry)
		output = append(output, maintainerRepoEventIssue{Number: issue.Number, Title: issue.Title, URL: issue.URL, UpdatedAt: issue.UpdatedAt, Labels: labels})
	}
	sort.Strings(entries)
	sort.Slice(output, func(i, j int) bool { return output[i].Number < output[j].Number })
	fingerprint := sha256.Sum256([]byte(strings.Join(entries, "\n")))
	return maintainerRepoEventsSnapshot{
		backlogFingerprint: hex.EncodeToString(fingerprint[:]), issueSignatures: signatures, issues: output, backlogAvailable: true,
		fleetSignatures: map[string]string{}, fleet: map[string]maintainerRepoFleetEvent{},
	}
}

func maintainerIssueLabels(labels []maintainerBacklogLabel) []string {
	names := make([]string, 0, len(labels))
	for _, label := range labels {
		if name := strings.TrimSpace(label.Name); name != "" {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	return names
}

func (t *waitForRepoEventsTool) fleetEventsSnapshot(ctx context.Context) (maintainerRepoEventsSnapshot, error) {
	fleet, err := t.fleetRuns(ctx)
	if err != nil {
		return maintainerRepoEventsSnapshot{}, fmt.Errorf("failed to list fleet AgentRuns: %w", err)
	}
	signatures := make(map[string]string, len(fleet))
	events := make(map[string]maintainerRepoFleetEvent, len(fleet))
	for i := range fleet {
		run := &fleet[i]
		session, err := t.stateStore.GetSessionByRun(ctx, run.Name, run.Namespace)
		if err != nil {
			return maintainerRepoEventsSnapshot{}, fmt.Errorf("failed to resolve session for fleet AgentRun %q: %w", run.Name, err)
		}
		urls := waitPullRequestURLs(run)
		if urls == nil {
			urls = []string{}
		}
		blockedReason := maintainerBlockedReason(run)
		pendingInput := orchestration.PendingUserInputForSession(session) != nil
		loopState := run.Labels[maintainerPRLoopStateLabel]
		loopRound := run.Annotations[maintainerPRLoopRoundAnnotation]
		episode := maintainerEpisodeState(run)
		signature := string(run.Status.Phase) + "|" + episode + "|" + strings.Join(urls, "\x00") + "|" + blockedReason + "|" + strconv.FormatBool(pendingInput) + "|" + loopState + "|" + loopRound
		signatures[run.Name] = maintainerRepoEventSignature(signature)
		events[run.Name] = maintainerRepoFleetEvent{Name: run.Name, Phase: run.Status.Phase, Episode: episode, PullRequestURLs: urls, BlockedReason: blockedReason, PendingInput: pendingInput, PRLoopState: loopState, PRLoopRound: loopRound}
	}
	return maintainerRepoEventsSnapshot{fleetSignatures: signatures, fleet: events, pullRequestSignatures: map[string]string{}, pullRequests: map[string]maintainerRepoPullRequestEvent{}}, nil
}

func (t *waitForRepoEventsTool) workItemListOptions(resourceVersion string) *client.ListOptions {
	options := &client.ListOptions{
		Namespace:     t.repositoryNamespace,
		LabelSelector: labels.SelectorFromSet(labels.Set{triggersv1alpha1.MaintainerWorkItemRepositoryLabelKey: t.repositoryName}),
	}
	if resourceVersion != "" {
		options.Raw = &metav1.ListOptions{ResourceVersion: resourceVersion, LabelSelector: options.LabelSelector.String()}
	}
	return options
}

func (t *waitForRepoEventsTool) workItemEventsSnapshot(ctx context.Context) (maintainerRepoEventsSnapshot, error) {
	var items triggersv1alpha1.MaintainerWorkItemList
	options := t.workItemListOptions("")
	if err := t.k8sClient.List(ctx, &items, options); err != nil {
		return maintainerRepoEventsSnapshot{}, fmt.Errorf("failed to list repository MaintainerWorkItems: %w", err)
	}

	signatures := make(map[string]string, len(items.Items))
	events := make(map[string]maintainerRepoWorkItemEvent, len(items.Items))
	for i := range items.Items {
		item := &items.Items[i]
		if item.Spec.RepositoryRef.Name != t.repositoryName {
			continue
		}
		intent, err := json.Marshal(item.Spec)
		if err != nil {
			return maintainerRepoEventsSnapshot{}, fmt.Errorf("marshal MaintainerWorkItem %q intent: %w", item.Name, err)
		}
		signatures[item.Name] = maintainerRepoEventSignature(strconv.FormatInt(item.Status.ProjectionSequence, 10) + "|" + item.ResourceVersion + "|" + string(intent))
		events[item.Name] = maintainerWorkItemEvent(item)
	}
	return maintainerRepoEventsSnapshot{workItemSignatures: signatures, workItems: events, workItemResourceVersion: items.ResourceVersion}, nil
}

func maintainerWorkItemEvent(item *triggersv1alpha1.MaintainerWorkItem) maintainerRepoWorkItemEvent {
	return maintainerRepoWorkItemEvent{
		Name: item.Name, IssueNumber: item.Spec.IssueNumber, Disposition: item.Spec.Disposition, Phase: item.Status.Phase,
		ProjectionSequence: item.Status.ProjectionSequence, ResourceVersion: item.ResourceVersion,
		ObservationFresh: maintainerWorkItemObservationFresh(item), IssueObservation: item.Status.IssueObservation.DeepCopy(),
		AgentRuns:           append([]triggersv1alpha1.MaintainerWorkItemAgentRunProjection(nil), item.Status.AgentRuns...),
		PullRequests:        append([]triggersv1alpha1.MaintainerWorkItemPullRequestProjection(nil), item.Status.PullRequests...),
		VerifiedMerges:      append([]triggersv1alpha1.MaintainerVerifiedPullRequestMerge(nil), item.Status.VerifiedMerges...),
		DeliveryAttestation: item.Status.DeliveryAttestation.DeepCopy(),
		LatestCommand:       item.Status.LatestCommand.DeepCopy(),
		Children:            append([]triggersv1alpha1.MaintainerWorkItemChildProjection(nil), item.Status.Children...),
		Dependencies:        append([]triggersv1alpha1.MaintainerWorkItemDependencyProjection(nil), item.Status.Dependencies...),
		Readiness:           item.Status.Readiness.DeepCopy(), PendingDecision: item.Status.PendingDecision.DeepCopy(),
	}
}

// workItemSnapshotAndWatch establishes the watch from the resource version of
// the returned list. An update committed between the list and Watch call is
// therefore replayed by the API server instead of falling into a waiter gap.
func (t *waitForRepoEventsTool) workItemSnapshotAndWatch(ctx context.Context) (maintainerRepoEventsSnapshot, watch.Interface, error) {
	snapshot, err := t.workItemEventsSnapshot(ctx)
	if err != nil {
		return maintainerRepoEventsSnapshot{}, nil, err
	}
	watchClient, ok := t.k8sClient.(client.WithWatch)
	if !ok {
		return snapshot, nil, fmt.Errorf("kubernetes client does not support MaintainerWorkItem watches")
	}
	if t.beforeWorkItemWatch != nil {
		t.beforeWorkItemWatch()
	}
	watcher, err := watchClient.Watch(ctx, &triggersv1alpha1.MaintainerWorkItemList{}, t.workItemListOptions(snapshot.workItemResourceVersion))
	if err != nil {
		return snapshot, nil, fmt.Errorf("watch repository MaintainerWorkItems from resourceVersion %q: %w", snapshot.workItemResourceVersion, err)
	}
	return snapshot, watcher, nil
}

func maintainerWorkItemObservationFresh(item *triggersv1alpha1.MaintainerWorkItem) bool {
	for _, condition := range item.Status.Conditions {
		if condition.Type == triggersv1alpha1.ConditionMaintainerWorkItemObservationFresh && condition.Status == metav1.ConditionTrue {
			return true
		}
	}
	return false
}

const (
	maintainerRollupSuccess = "success"
	maintainerRollupPending = "pending"
)

const maintainerPullRequestReviewDecisionQuery = "query($owner:String!,$repo:String!,$number:Int!){repository(owner:$owner,name:$repo){pullRequest(number:$number){reviewDecision}}}"

func (t *waitForRepoEventsTool) pullRequestEventsSnapshot(ctx context.Context, workDir string, fleet map[string]maintainerRepoFleetEvent) (maintainerRepoEventsSnapshot, error) {
	type target struct {
		url               string
		owner, repository string
		number            int
	}
	targetsByRepository := map[string][]target{}
	events := map[string]maintainerRepoPullRequestEvent{}
	errorsByURL := map[string]string{}
	monitorByURL := map[string]*triggersv1alpha1.PullRequestMonitor{}
	var monitors triggersv1alpha1.PullRequestMonitorList
	if t.k8sClient != nil {
		if err := t.k8sClient.List(ctx, &monitors, client.InNamespace(t.repositoryNamespace)); err == nil {
			for i := range monitors.Items {
				monitor := &monitors.Items[i]
				monitorByURL[strings.ToLower(monitor.Spec.URL)] = monitor
			}
		}
	}
	for _, fleetEvent := range fleet {
		for _, rawURL := range fleetEvent.PullRequestURLs {
			owner, repository, number, err := parseMaintainerPullRequestURL(rawURL)
			if err != nil {
				value := strings.TrimSpace(rawURL)
				errorsByURL[value] = err.Error()
				continue
			}
			value := fmt.Sprintf("https://github.com/%s/%s/pull/%d", owner, repository, number)
			if monitor := monitorByURL[strings.ToLower(value)]; maintainerMonitorEquivalentAndFresh(monitor, time.Now()) {
				events[value] = maintainerEventFromMonitor(monitor)
				continue
			}
			key := strings.ToLower(owner + "/" + repository)
			targetsByRepository[key] = append(targetsByRepository[key], target{url: value, owner: owner, repository: repository, number: number})
		}
	}

	runner := t.runner
	if runner == nil {
		runner = prReviewExecRunner{}
	}
	for _, targets := range targetsByRepository {
		sort.Slice(targets, func(i, j int) bool { return targets[i].number < targets[j].number })
		open, err := maintainerOpenPullRequestNumbers(ctx, runner, workDir, targets[0].owner, targets[0].repository)
		if err != nil {
			for _, item := range targets {
				errorsByURL[item.url] = err.Error()
			}
			continue
		}
		for _, item := range targets {
			if _, exists := open[item.number]; !exists {
				events[item.url] = maintainerRepoPullRequestEvent{URL: item.url, State: "closed"}
				continue
			}
			event, err := t.pullRequestEvent(ctx, workDir, item.url)
			if err != nil {
				errorsByURL[item.url] = err.Error()
				continue
			}
			events[item.url] = event
		}
	}

	snapshot := maintainerRepoEventsSnapshot{
		pullRequestSignatures: make(map[string]string, len(events)+len(errorsByURL)),
		pullRequests:          make(map[string]maintainerRepoPullRequestEvent, len(events)+len(errorsByURL)),
	}
	for value, message := range errorsByURL {
		events[value] = maintainerRepoPullRequestEvent{URL: value, Error: truncateUTF8(message, 1024)}
	}
	values := make([]string, 0, len(events))
	for value := range events {
		values = append(values, value)
	}
	sort.Strings(values)
	messages := make([]string, 0, len(errorsByURL))
	for _, value := range values {
		event := events[value]
		encoded, err := json.Marshal(event)
		if err != nil {
			return maintainerRepoEventsSnapshot{}, err
		}
		snapshot.pullRequestSignatures[value] = maintainerRepoEventSignature(string(encoded))
		snapshot.pullRequests[value] = event
		if event.Error != "" {
			messages = append(messages, value+": "+event.Error)
		}
	}
	snapshot.pullRequestError = strings.Join(messages, "; ")
	return snapshot, nil
}

func maintainerMonitorEquivalentAndFresh(monitor *triggersv1alpha1.PullRequestMonitor, now time.Time) bool {
	const freshness = 5 * time.Minute
	if monitor == nil || monitor.Status.Lifecycle == "" || monitor.Status.PullObservedAt.IsZero() || monitor.Status.PullError != "" {
		return false
	}
	// Merge is irreversible; a successfully observed merged lifecycle remains
	// authoritative after active polling stops.
	if monitor.Status.Lifecycle == triggersv1alpha1.PullRequestLifecycleMerged {
		return true
	}
	if monitor.Status.LastError != "" || now.Sub(monitor.Status.PullObservedAt.Time) > freshness {
		return false
	}
	if monitor.Status.Lifecycle == triggersv1alpha1.PullRequestLifecycleClosed {
		return true
	}
	return monitor.Status.HeadSHA != "" && monitor.Status.ReviewDecision != "" && monitor.Status.ReviewsError == "" && !monitor.Status.ReviewsObservedAt.IsZero() && now.Sub(monitor.Status.ReviewsObservedAt.Time) <= freshness &&
		monitor.Status.Checks.HeadSHA == monitor.Status.HeadSHA && monitor.Status.Statuses.HeadSHA == monitor.Status.HeadSHA &&
		!monitor.Status.Checks.ObservedAt.IsZero() && !monitor.Status.Statuses.ObservedAt.IsZero() && now.Sub(monitor.Status.Checks.ObservedAt.Time) <= freshness && now.Sub(monitor.Status.Statuses.ObservedAt.Time) <= freshness &&
		monitor.Status.Checks.Error == "" && monitor.Status.Statuses.Error == ""
}

func maintainerEventFromMonitor(monitor *triggersv1alpha1.PullRequestMonitor) maintainerRepoPullRequestEvent {
	event := maintainerRepoPullRequestEvent{URL: monitor.Spec.URL, HeadSHA: monitor.Status.HeadSHA, State: string(monitor.Status.Lifecycle), Draft: monitor.Status.Lifecycle == triggersv1alpha1.PullRequestLifecycleDraft, ReviewDecision: strings.ToUpper(string(monitor.Status.ReviewDecision)), MergeState: string(monitor.Status.Mergeability)}
	switch monitor.Status.Mergeability {
	case triggersv1alpha1.PullRequestMergeabilityMergeable:
		value := true
		event.Mergeable = &value
	case triggersv1alpha1.PullRequestMergeabilityConflicting:
		value := false
		event.Mergeable = &value
	}
	rollups := []triggersv1alpha1.PullRequestMonitorHeadRollup{monitor.Status.Checks, monitor.Status.Statuses}
	for _, rollup := range rollups {
		count := int(rollup.Count)
		event.Checks.Total += count
		switch strings.ToLower(rollup.State) {
		case maintainerRollupSuccess:
			event.Checks.Passed += count
		case "failure":
			event.Checks.Failed += count
		case maintainerRollupPending:
			if count == 0 {
				count = 1
				event.Checks.Total++
			}
			event.Checks.Pending += count
		}
	}
	if event.State == string(triggersv1alpha1.PullRequestLifecycleDraft) {
		event.State = "open"
	}
	return event
}

func maintainerOpenPullRequestNumbers(ctx context.Context, runner prReviewRunner, workDir, owner, repository string) (map[int]struct{}, error) {
	out, err := runner.RunGH(ctx, workDir, "api", "repos/"+owner+"/"+repository+"/pulls?state=open&per_page=100", "--paginate")
	if err != nil {
		return nil, fmt.Errorf("gh api open pull requests failed: %w: %s", err, strings.TrimSpace(out))
	}
	open := map[int]struct{}{}
	decoder := json.NewDecoder(strings.NewReader(out))
	for decoder.More() {
		var page []struct {
			Number int `json:"number"`
		}
		if err := decoder.Decode(&page); err != nil {
			return nil, fmt.Errorf("parse gh api open pull requests output: %w", err)
		}
		for _, pullRequest := range page {
			if pullRequest.Number > 0 {
				open[pullRequest.Number] = struct{}{}
			}
		}
	}
	return open, nil
}

func (t *waitForRepoEventsTool) pullRequestEvent(ctx context.Context, workDir, pullRequestURL string) (maintainerRepoPullRequestEvent, error) {
	owner, repository, number, err := parseMaintainerPullRequestURL(pullRequestURL)
	if err != nil {
		return maintainerRepoPullRequestEvent{}, err
	}
	runner := t.runner
	if runner == nil {
		runner = prReviewExecRunner{}
	}
	endpoint := "repos/" + owner + "/" + repository + "/pulls/" + strconv.Itoa(number)
	pullRequestOut, err := runner.RunGH(ctx, workDir, "api", endpoint)
	if err != nil {
		return maintainerRepoPullRequestEvent{}, fmt.Errorf("gh api pull request failed: %w: %s", err, strings.TrimSpace(pullRequestOut))
	}
	var pullRequest struct {
		Head struct {
			SHA string `json:"sha"`
		} `json:"head"`
		State          string `json:"state"`
		Draft          bool   `json:"draft"`
		Mergeable      *bool  `json:"mergeable"`
		MergeableState string `json:"mergeable_state"`
	}
	if err := json.Unmarshal([]byte(pullRequestOut), &pullRequest); err != nil {
		return maintainerRepoPullRequestEvent{}, fmt.Errorf("parse gh api pull request output: %w", err)
	}
	if pullRequest.Head.SHA == "" {
		return maintainerRepoPullRequestEvent{}, fmt.Errorf("gh api pull request returned no head SHA")
	}

	reviewOut, err := runner.RunGH(ctx, workDir, "api", "graphql", "-f", "query="+maintainerPullRequestReviewDecisionQuery, "-f", "owner="+owner, "-f", "repo="+repository, "-F", "number="+strconv.Itoa(number))
	if err != nil {
		return maintainerRepoPullRequestEvent{}, fmt.Errorf("gh api pull request review decision failed: %w: %s", err, strings.TrimSpace(reviewOut))
	}
	var review struct {
		Data struct {
			Repository struct {
				PullRequest struct {
					ReviewDecision string `json:"reviewDecision"`
				} `json:"pullRequest"`
			} `json:"repository"`
		} `json:"data"`
	}
	if err := json.Unmarshal([]byte(reviewOut), &review); err != nil {
		return maintainerRepoPullRequestEvent{}, fmt.Errorf("parse gh api pull request review decision output: %w", err)
	}

	checksOut, err := runner.RunGH(ctx, workDir, "api", "repos/"+owner+"/"+repository+"/commits/"+pullRequest.Head.SHA+"/check-runs", "--paginate")
	if err != nil {
		return maintainerRepoPullRequestEvent{}, fmt.Errorf("gh api check-runs failed: %w: %s", err, strings.TrimSpace(checksOut))
	}
	checks, err := parseCheckRunPages(checksOut)
	if err != nil {
		return maintainerRepoPullRequestEvent{}, fmt.Errorf("parse check-runs output: %w", err)
	}

	statusOut, err := runner.RunGH(ctx, workDir, "api", "repos/"+owner+"/"+repository+"/commits/"+pullRequest.Head.SHA+"/status")
	if err != nil {
		return maintainerRepoPullRequestEvent{}, fmt.Errorf("gh api commit status failed: %w: %s", err, strings.TrimSpace(statusOut))
	}
	var status struct {
		Statuses []pullRequestCommitStatus `json:"statuses"`
	}
	if err := json.Unmarshal([]byte(statusOut), &status); err != nil {
		return maintainerRepoPullRequestEvent{}, fmt.Errorf("parse gh api commit status output: %w", err)
	}

	return maintainerRepoPullRequestEvent{
		URL:            pullRequestURL,
		HeadSHA:        pullRequest.Head.SHA,
		State:          pullRequest.State,
		Draft:          pullRequest.Draft,
		ReviewDecision: review.Data.Repository.PullRequest.ReviewDecision,
		Mergeable:      pullRequest.Mergeable,
		MergeState:     pullRequest.MergeableState,
		Checks:         maintainerPullRequestChecksSummary(checks, status.Statuses),
	}, nil
}

func parseMaintainerPullRequestURL(value string) (owner, repository string, number int, err error) {
	parsed, err := url.Parse(strings.TrimSpace(value))
	if err != nil || parsed == nil {
		return "", "", 0, fmt.Errorf("invalid pull request URL")
	}
	host := strings.ToLower(parsed.Hostname())
	if !strings.EqualFold(parsed.Scheme, "https") || (host != "github.com" && host != "www.github.com") || parsed.User != nil || parsed.Port() != "" {
		return "", "", 0, fmt.Errorf("pull request URL must be an HTTPS github.com URL without userinfo or a port")
	}
	parts := strings.Split(strings.Trim(parsed.EscapedPath(), "/"), "/")
	if len(parts) < 4 || parts[0] == "" || parts[1] == "" || !strings.EqualFold(parts[2], "pull") {
		return "", "", 0, fmt.Errorf("invalid pull request URL")
	}
	owner, err = url.PathUnescape(parts[0])
	if err != nil || owner == "" || strings.Contains(owner, "/") {
		return "", "", 0, fmt.Errorf("invalid pull request owner")
	}
	repository, err = url.PathUnescape(parts[1])
	if err != nil || repository == "" || strings.Contains(repository, "/") {
		return "", "", 0, fmt.Errorf("invalid pull request repository")
	}
	number64, err := strconv.ParseInt(parts[3], 10, 32)
	if err != nil || number64 <= 0 {
		return "", "", 0, fmt.Errorf("invalid pull request number")
	}
	return strings.ToLower(owner), strings.ToLower(repository), int(number64), nil
}

func maintainerPullRequestChecksSummary(checks []pullRequestCheckRun, statuses []pullRequestCommitStatus) pullRequestChecksSummary {
	summary := pullRequestChecksSummary{Total: len(checks) + len(statuses)}
	for _, check := range checks {
		if check.Status != "completed" {
			summary.Pending++
			continue
		}
		switch check.Conclusion {
		case "success", "neutral", "skipped":
			summary.Passed++
		default:
			summary.Failed++
		}
	}
	for _, status := range statuses {
		switch status.State {
		case maintainerRollupSuccess:
			summary.Passed++
		case maintainerRollupPending:
			summary.Pending++
		default:
			summary.Failed++
		}
	}
	return summary
}

func maintainerRepoEventSignature(value string) string {
	sum := sha256.Sum256([]byte(value))
	return base64.RawStdEncoding.EncodeToString(sum[:])
}

func repoEventsChanged(previous, current maintainerRepoEventsSnapshot) bool {
	if current.backlogAvailable && (!previous.backlogAvailable || previous.backlogFingerprint != current.backlogFingerprint) {
		return true
	}
	return !maintainerRepoEventSignaturesEqual(previous.fleetSignatures, current.fleetSignatures) ||
		!maintainerRepoEventSignaturesEqual(previous.pullRequestSignatures, current.pullRequestSignatures) ||
		!maintainerRepoEventSignaturesEqual(previous.workItemSignatures, current.workItemSignatures)
}

func maintainerRepoEventSignaturesEqual(left, right map[string]string) bool {
	if len(left) != len(right) {
		return false
	}
	for name, signature := range left {
		if right[name] != signature {
			return false
		}
	}
	return true
}

func (t *waitForRepoEventsTool) repoEventsResult(previous, current maintainerRepoEventsSnapshot, changed, timedOut bool, started time.Time, cursorKnown bool) (Result, error) {
	if current.backlogAvailable == false && previous.backlogAvailable {
		current.backlogFingerprint = previous.backlogFingerprint
		current.issueSignatures = previous.issueSignatures
		current.issues = previous.issues
	}
	changedIssues := changedRepoEventIssues(previous, current)
	fleetChanges := changedRepoFleetEvents(previous, current)
	pullRequestChanges := changedRepoPullRequestEvents(previous, current)
	workItemChanges := changedRepoWorkItemEvents(previous, current)
	if !changed {
		changedIssues = []maintainerRepoEventIssue{}
		fleetChanges = []maintainerRepoFleetEvent{}
		pullRequestChanges = []maintainerRepoPullRequestEvent{}
		workItemChanges = []maintainerRepoWorkItemEvent{}
	} else if !cursorKnown {
		changedIssues = append([]maintainerRepoEventIssue(nil), current.issues...)
	}

	// The cursor must acknowledge only the deltas actually emitted in this
	// result. Encoding every current signature while trimming the emitted
	// list (cap or byte budget) would mark suppressed issues and fleet runs
	// as already seen, permanently hiding them until they change again. With
	// an emitted-only cursor the next call detects the remaining difference
	// immediately and pages through the rest.
	for {
		cursor, err := encodeMaintainerRepoEventsCursor(repoEventsCursorForEmitted(previous, current, changedIssues, fleetChanges, pullRequestChanges, workItemChanges))
		if err != nil {
			return Result{}, err
		}
		out := waitForRepoEventsOutput{
			Changed: changed, TimedOut: timedOut, BacklogChanged: current.backlogAvailable && (!previous.backlogAvailable || previous.backlogFingerprint != current.backlogFingerprint),
			ChangedIssues: changedIssues, FleetChanges: fleetChanges, PullRequestChanges: pullRequestChanges, WorkItemChanges: workItemChanges, Cursor: cursor,
			BacklogError: truncateUTF8(current.backlogError, 1024), FleetError: truncateUTF8(current.fleetError, 1024), PullRequestError: truncateUTF8(current.pullRequestError, 1024), WorkItemError: truncateUTF8(current.workItemError, 1024),
		}
		if !started.IsZero() {
			out.ElapsedSeconds = int(time.Since(started).Seconds())
		}
		encoded, err := json.Marshal(out)
		if err != nil {
			return Result{}, err
		}
		if len(encoded) <= maintainerRepoEventsResultLimit || (len(changedIssues) == 0 && len(fleetChanges) == 0 && len(pullRequestChanges) == 0 && len(workItemChanges) == 0) {
			return Result{Content: string(encoded)}, nil
		}
		if len(changedIssues) > 0 {
			changedIssues = changedIssues[:len(changedIssues)-1]
			continue
		}
		if len(fleetChanges) > 0 {
			fleetChanges = fleetChanges[:len(fleetChanges)-1]
			continue
		}
		if len(pullRequestChanges) > 0 {
			pullRequestChanges = pullRequestChanges[:len(pullRequestChanges)-1]
			continue
		}
		workItemChanges = workItemChanges[:len(workItemChanges)-1]
	}
}

// repoEventsCursorForEmitted advances the previous cursor by only the emitted
// deltas: emitted issues, fleet runs, pull requests, and work items adopt their current
// signatures, removed entries are dropped, and everything else keeps the
// previously seen signature so it still registers as a pending change. The
// backlog fingerprint matches the live snapshot only when nothing was
// suppressed; otherwise a fingerprint derived from the acknowledged
// signatures keeps the cursor distinct from the live state so the next call
// returns immediately.
func repoEventsCursorForEmitted(previous, current maintainerRepoEventsSnapshot, emittedIssues []maintainerRepoEventIssue, emittedFleet []maintainerRepoFleetEvent, emittedPullRequests []maintainerRepoPullRequestEvent, emittedWorkItems []maintainerRepoWorkItemEvent) maintainerRepoEventsCursor {
	issueSignatures := map[string]string{}
	for number, signature := range previous.issueSignatures {
		// Keep removed-but-not-yet-emitted issues pending so a trimmed
		// removal event still surfaces on the next call instead of being
		// silently acknowledged.
		issueSignatures[number] = signature
	}
	for _, issue := range emittedIssues {
		number := strconv.Itoa(issue.Number)
		if signature, exists := current.issueSignatures[number]; exists {
			issueSignatures[number] = signature
		} else {
			delete(issueSignatures, number)
		}
	}
	backlogFingerprint := current.backlogFingerprint
	if !maintainerRepoEventSignaturesEqual(issueSignatures, current.issueSignatures) {
		backlogFingerprint = repoEventsSignatureFingerprint(issueSignatures)
	}

	fleetSignatures := map[string]string{}
	for name, signature := range previous.fleetSignatures {
		fleetSignatures[name] = signature
	}
	for _, event := range emittedFleet {
		if signature, exists := current.fleetSignatures[event.Name]; exists {
			fleetSignatures[event.Name] = signature
		} else {
			delete(fleetSignatures, event.Name)
		}
	}

	pullRequestSignatures := map[string]string{}
	for value, signature := range previous.pullRequestSignatures {
		pullRequestSignatures[value] = signature
	}
	for _, event := range emittedPullRequests {
		if signature, exists := current.pullRequestSignatures[event.URL]; exists {
			pullRequestSignatures[event.URL] = signature
		} else {
			delete(pullRequestSignatures, event.URL)
		}
	}

	workItemSignatures := map[string]string{}
	maps.Copy(workItemSignatures, previous.workItemSignatures)
	for _, event := range emittedWorkItems {
		if signature, exists := current.workItemSignatures[event.Name]; exists {
			workItemSignatures[event.Name] = signature
		} else {
			delete(workItemSignatures, event.Name)
		}
	}
	return maintainerRepoEventsCursor{
		BacklogFingerprint:    backlogFingerprint,
		IssueSignatures:       issueSignatures,
		FleetSignatures:       fleetSignatures,
		PullRequestSignatures: pullRequestSignatures,
		WorkItemSignatures:    workItemSignatures,
	}
}

func repoEventsSignatureFingerprint(signatures map[string]string) string {
	entries := make([]string, 0, len(signatures))
	for number, signature := range signatures {
		entries = append(entries, number+"|"+signature)
	}
	sort.Strings(entries)
	fingerprint := sha256.Sum256([]byte("acknowledged:" + strings.Join(entries, "\n")))
	return hex.EncodeToString(fingerprint[:])
}

func changedRepoEventIssues(previous, current maintainerRepoEventsSnapshot) []maintainerRepoEventIssue {
	if !current.backlogAvailable || previous.issueSignatures == nil {
		return []maintainerRepoEventIssue{}
	}
	issues := make([]maintainerRepoEventIssue, 0)
	for _, issue := range current.issues {
		if previous.issueSignatures[strconv.Itoa(issue.Number)] != current.issueSignatures[strconv.Itoa(issue.Number)] {
			issues = append(issues, issue)
		}
	}
	// Issues that left the open backlog (closed, converted, or transferred)
	// are emitted as explicit removal events, mirroring fleet and pull-request
	// removals, so the maintainer knows which issue disappeared instead of
	// observing only a backlog fingerprint change.
	for number := range previous.issueSignatures {
		if _, exists := current.issueSignatures[number]; exists {
			continue
		}
		value, err := strconv.Atoi(number)
		if err != nil {
			continue
		}
		issues = append(issues, maintainerRepoEventIssue{Number: value, Labels: []string{}, Removed: true})
	}
	sort.Slice(issues, func(i, j int) bool { return issues[i].Number < issues[j].Number })
	return issues
}

func changedRepoFleetEvents(previous, current maintainerRepoEventsSnapshot) []maintainerRepoFleetEvent {
	names := make([]string, 0)
	for name, signature := range current.fleetSignatures {
		if previous.fleetSignatures[name] != signature {
			names = append(names, name)
		}
	}
	for name := range previous.fleetSignatures {
		if _, exists := current.fleetSignatures[name]; !exists {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	events := make([]maintainerRepoFleetEvent, 0, len(names))
	for _, name := range names {
		if event, exists := current.fleet[name]; exists {
			events = append(events, event)
			continue
		}
		events = append(events, maintainerRepoFleetEvent{Name: name, PullRequestURLs: []string{}})
	}
	return events
}

func changedRepoPullRequestEvents(previous, current maintainerRepoEventsSnapshot) []maintainerRepoPullRequestEvent {
	values := make([]string, 0)
	for value, signature := range current.pullRequestSignatures {
		if previous.pullRequestSignatures[value] != signature {
			values = append(values, value)
		}
	}
	for value := range previous.pullRequestSignatures {
		if _, exists := current.pullRequestSignatures[value]; !exists {
			values = append(values, value)
		}
	}
	sort.Strings(values)
	events := make([]maintainerRepoPullRequestEvent, 0, len(values))
	for _, value := range values {
		if event, exists := current.pullRequests[value]; exists {
			events = append(events, event)
			continue
		}
		events = append(events, maintainerRepoPullRequestEvent{URL: value, Removed: true})
	}
	return events
}

func changedRepoWorkItemEvents(previous, current maintainerRepoEventsSnapshot) []maintainerRepoWorkItemEvent {
	names := make([]string, 0)
	for name, signature := range current.workItemSignatures {
		if previous.workItemSignatures[name] != signature {
			names = append(names, name)
		}
	}
	for name := range previous.workItemSignatures {
		if _, exists := current.workItemSignatures[name]; !exists {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	events := make([]maintainerRepoWorkItemEvent, 0, len(names))
	for _, name := range names {
		if event, exists := current.workItems[name]; exists {
			events = append(events, event)
			continue
		}
		events = append(events, maintainerRepoWorkItemEvent{Name: name, Removed: true})
	}
	return events
}

func encodeMaintainerRepoEventsCursor(cursor maintainerRepoEventsCursor) (string, error) {
	if cursor.IssueSignatures == nil {
		cursor.IssueSignatures = map[string]string{}
	}
	if cursor.FleetSignatures == nil {
		cursor.FleetSignatures = map[string]string{}
	}
	if cursor.PullRequestSignatures == nil {
		cursor.PullRequestSignatures = map[string]string{}
	}
	if cursor.WorkItemSignatures == nil {
		cursor.WorkItemSignatures = map[string]string{}
	}
	encoded, err := json.Marshal(cursor)
	if err != nil {
		return "", err
	}
	return base64.RawStdEncoding.EncodeToString(encoded), nil
}

func decodeMaintainerRepoEventsCursor(value string) (maintainerRepoEventsCursor, error) {
	decoded, err := base64.RawStdEncoding.DecodeString(strings.TrimSpace(value))
	if err != nil {
		return maintainerRepoEventsCursor{}, err
	}
	var cursor maintainerRepoEventsCursor
	if err := json.Unmarshal(decoded, &cursor); err != nil {
		return maintainerRepoEventsCursor{}, err
	}
	if cursor.IssueSignatures == nil || cursor.FleetSignatures == nil {
		return maintainerRepoEventsCursor{}, fmt.Errorf("snapshot signatures are required")
	}
	if cursor.PullRequestSignatures == nil {
		cursor.PullRequestSignatures = map[string]string{}
	}
	if cursor.WorkItemSignatures == nil {
		cursor.WorkItemSignatures = map[string]string{}
	}
	return cursor, nil
}

func snapshotFromMaintainerRepoEventsCursor(cursor maintainerRepoEventsCursor) maintainerRepoEventsSnapshot {
	return maintainerRepoEventsSnapshot{
		backlogFingerprint: cursor.BacklogFingerprint, issueSignatures: cursor.IssueSignatures, backlogAvailable: cursor.BacklogFingerprint != "",
		fleetSignatures: cursor.FleetSignatures, fleet: map[string]maintainerRepoFleetEvent{},
		pullRequestSignatures: cursor.PullRequestSignatures, pullRequests: map[string]maintainerRepoPullRequestEvent{},
		workItemSignatures: cursor.WorkItemSignatures, workItems: map[string]maintainerRepoWorkItemEvent{},
	}
}

package tools

import (
	"context"
	"crypto/rand"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"time"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	triggersv1alpha1 "github.com/gratefulagents/gratefulagents/api/triggers/v1alpha1"
	corev1 "k8s.io/api/core/v1"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	"k8s.io/apimachinery/pkg/types"
	"k8s.io/apimachinery/pkg/watch"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

const (
	maintainerSemanticCursorDataKey  = "state.json"
	maintainerSemanticLatestHandle   = "latest"
	maintainerSemanticOpaquePrefix   = "mh2_"
	maintainerSemanticHandleLifetime = 30 * 24 * time.Hour

	maintainerSemanticWatchReconnectAttempts = 5
	maintainerSemanticWatchReconnectBackoff  = 200 * time.Millisecond
)

type maintainerSemanticCursor struct {
	Version    int              `json:"version"`
	Sequences  map[string]int64 `json:"projection_sequences"`
	Identities map[string]int32 `json:"work_item_identities,omitempty"`
}

// maintainerSemanticCursorState is stored compactly in an AgentRun-owned
// Secret. Each work-item name appears once so large repositories remain well
// below Kubernetes' object-size limit.
type maintainerSemanticCursorState struct {
	Version       int                             `json:"v"`
	RunUID        types.UID                       `json:"r"`
	RepositoryUID types.UID                       `json:"p"`
	Handle        string                          `json:"h"`
	ExpiresAt     time.Time                       `json:"e"`
	Entries       []maintainerSemanticCursorEntry `json:"i"`
}

type maintainerSemanticCursorEntry struct {
	Name        string `json:"n"`
	Sequence    int64  `json:"s"`
	IssueNumber int32  `json:"i"`
}

type maintainerSemanticWaitOutput struct {
	Changed           bool                          `json:"changed"`
	TimedOut          bool                          `json:"timed_out"`
	ElapsedSeconds    int                           `json:"elapsed_seconds"`
	MigrationMode     string                        `json:"migration_mode"`
	WorkItems         []maintainerRepoWorkItemEvent `json:"work_item_changes"`
	ReconnectRequired bool                          `json:"reconnect_required,omitempty"`
	WatchError        string                        `json:"watch_error,omitempty"`
	CursorHandle      string                        `json:"cursor_handle"`
}

// executeSemanticWorkItemWait implements waiter v2. The durable source of truth
// is each MaintainerWorkItem's controller-owned ProjectionSequence; the cursor
// only acknowledges those persisted sequences and contains no model-computed
// signatures. A list and watch from the list resourceVersion closes the race.
func (t *waitForRepoEventsTool) executeSemanticWorkItemWait(ctx context.Context, input json.RawMessage) (Result, error) {
	var in waitForRepoEventsInput
	if err := json.Unmarshal(input, &in); err != nil {
		return Result{Content: fmt.Sprintf("invalid input: %v", err), IsError: true}, nil
	}
	timeout := in.TimeoutSeconds
	if timeout == 0 {
		timeout = defaultRepoEventsTimeout
	}
	if timeout < minRepoEventsTimeout || timeout > maxRepoEventsTimeout {
		return Result{Content: "timeout_seconds must be between 30 and 21600", IsError: true}, nil
	}
	repository, err := t.repository(ctx)
	if err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	run, err := t.currentRunForRepository(ctx, repository)
	if err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	checkpoint, err := t.semanticCursorCheckpoint(ctx, run.UID, repository.UID)
	if err != nil {
		return Result{Content: "failed to read semantic cursor checkpoint: " + err.Error(), IsError: true}, nil
	}
	cursorValue := strings.TrimSpace(in.Cursor)
	cursorProvided := cursorValue != ""
	previous, err := resolveSemanticWaitCursor(checkpoint, run, repository.UID, cursorValue, time.Now())
	if err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	expectedState := ""
	if checkpoint != nil {
		expectedState = checkpoint.ResourceVersion
	}
	snapshot, watcher, err := t.workItemSnapshotAndWatch(ctx)
	if err != nil {
		return Result{Content: "failed to establish semantic work-item snapshot/watch: " + err.Error(), IsError: true}, nil
	}
	defer func() { watcher.Stop() }()
	if err := validateSemanticWorkItemIdentities(t.repositoryName, snapshot.workItems); err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	if err := validateSemanticCursorIdentities(t.repositoryName, previous, snapshot.workItems); err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	current := semanticSequences(snapshot.workItems)
	identities := semanticIdentities(snapshot.workItems)
	changes := semanticSnapshotChanges(previous.Sequences, snapshot.workItems, !cursorProvided)
	if len(changes) > 0 || !cursorProvided {
		return t.semanticWaitResult(ctx, run.UID, repository.UID, expectedState, changes, current, identities, true, false, time.Time{})
	}
	started := time.Now()
	waitCtx, cancelWait := context.WithDeadline(ctx, started.Add(time.Duration(timeout)*time.Second))
	defer cancelWait()
	for {
		select {
		case <-waitCtx.Done():
			if ctx.Err() != nil {
				return Result{}, ctx.Err()
			}
			return t.semanticWaitResult(ctx, run.UID, repository.UID, expectedState, nil, current, identities, false, true, started)
		case event, ok := <-watcher.ResultChan():
			if !ok || event.Type == watch.Error {
				watchError := "semantic work-item watch closed"
				if ok {
					watchError = "semantic work-item watch reported an error"
				}
				watcher.Stop()
				fresh, reconnected, err := t.reconnectWorkItemSnapshotAndWatch(waitCtx)
				if err != nil {
					if ctx.Err() != nil {
						return Result{}, ctx.Err()
					}
					if waitCtx.Err() != nil {
						return t.semanticWaitResult(ctx, run.UID, repository.UID, expectedState, nil, current, identities, false, true, started)
					}
					return t.semanticWatchReconnectResult(ctx, run.UID, repository.UID, expectedState, current, identities, started, watchError+": "+err.Error())
				}
				watcher = reconnected
				if err := validateSemanticWorkItemIdentities(t.repositoryName, fresh.workItems); err != nil {
					return Result{Content: err.Error(), IsError: true}, nil
				}
				changes := semanticSnapshotChanges(current, fresh.workItems, false)
				current = semanticSequences(fresh.workItems)
				identities = semanticIdentities(fresh.workItems)
				if len(changes) > 0 {
					return t.semanticWaitResult(ctx, run.UID, repository.UID, expectedState, changes, current, identities, true, false, started)
				}
				continue
			}
			item, ok := event.Object.(*triggersv1alpha1.MaintainerWorkItem)
			if !ok || item.Spec.RepositoryRef.Name != t.repositoryName {
				continue
			}
			if item.Name != triggersv1alpha1.MaintainerWorkItemName(t.repositoryName, item.Spec.IssueNumber) {
				return Result{Content: fmt.Sprintf("non-canonical cursor identity: work item %q", item.Name), IsError: true}, nil
			}
			if event.Type == watch.Deleted {
				if _, known := current[item.Name]; !known {
					continue
				}
				delete(current, item.Name)
				delete(identities, item.Name)
				change := maintainerWorkItemEvent(item)
				change.Removed = true
				return t.semanticWaitResult(ctx, run.UID, repository.UID, expectedState, []maintainerRepoWorkItemEvent{change}, current, identities, true, false, started)
			}
			if sequence, known := current[item.Name]; known && sequence == item.Status.ProjectionSequence {
				continue
			}
			current[item.Name] = item.Status.ProjectionSequence
			identities[item.Name] = item.Spec.IssueNumber
			return t.semanticWaitResult(ctx, run.UID, repository.UID, expectedState, []maintainerRepoWorkItemEvent{maintainerWorkItemEvent(item)}, current, identities, true, false, started)
		}
	}
}

// reconnectWorkItemSnapshotAndWatch re-lists and re-watches after the API
// server closed the watch. Idle closes are routine, so they are absorbed here
// instead of surfacing as a reconnect_required turn for the model.
func (t *waitForRepoEventsTool) reconnectWorkItemSnapshotAndWatch(ctx context.Context) (maintainerRepoEventsSnapshot, watch.Interface, error) {
	var lastErr error
	for attempt := range maintainerSemanticWatchReconnectAttempts {
		if attempt > 0 {
			select {
			case <-ctx.Done():
				return maintainerRepoEventsSnapshot{}, nil, ctx.Err()
			case <-time.After(time.Duration(attempt) * maintainerSemanticWatchReconnectBackoff):
			}
		}
		snapshot, watcher, err := t.workItemSnapshotAndWatch(ctx)
		if err == nil {
			return snapshot, watcher, nil
		}
		lastErr = err
	}
	return maintainerRepoEventsSnapshot{}, nil, fmt.Errorf("reconnect failed after %d attempts: %w", maintainerSemanticWatchReconnectAttempts, lastErr)
}

func semanticSequences(items map[string]maintainerRepoWorkItemEvent) map[string]int64 {
	sequences := make(map[string]int64, len(items))
	for name, item := range items {
		sequences[name] = item.ProjectionSequence
	}
	return sequences
}

func semanticIdentities(items map[string]maintainerRepoWorkItemEvent) map[string]int32 {
	identities := make(map[string]int32, len(items))
	for name, item := range items {
		identities[name] = item.IssueNumber
	}
	return identities
}

func semanticSnapshotChanges(previous map[string]int64, current map[string]maintainerRepoWorkItemEvent, includeAll bool) []maintainerRepoWorkItemEvent {
	changes := make([]maintainerRepoWorkItemEvent, 0)
	for name, item := range current {
		sequence, known := previous[name]
		if includeAll || !known || sequence != item.ProjectionSequence {
			changes = append(changes, item)
		}
	}
	for name, sequence := range previous {
		if _, known := current[name]; known {
			continue
		}
		changes = append(changes, maintainerRepoWorkItemEvent{Name: name, ProjectionSequence: sequence, Removed: true})
	}
	sort.Slice(changes, func(i, j int) bool { return changes[i].Name < changes[j].Name })
	return changes
}

func (t *waitForRepoEventsTool) semanticWatchReconnectResult(ctx context.Context, runUID, repositoryUID types.UID, expectedState string, sequences map[string]int64, identities map[string]int32, started time.Time, watchError string) (Result, error) {
	result, err := t.semanticWaitResult(ctx, runUID, repositoryUID, expectedState, nil, sequences, identities, false, false, started)
	if err != nil || result.IsError {
		return result, err
	}
	var output maintainerSemanticWaitOutput
	if err := json.Unmarshal([]byte(result.Content), &output); err != nil {
		return Result{}, err
	}
	output.ReconnectRequired = true
	output.WatchError = watchError
	encoded, err := json.Marshal(output)
	if err != nil {
		return Result{}, err
	}
	return Result{Content: string(encoded)}, nil
}

func (t *waitForRepoEventsTool) semanticWaitResult(ctx context.Context, runUID, repositoryUID types.UID, expectedState string, changes []maintainerRepoWorkItemEvent, sequences map[string]int64, identities map[string]int32, changed, timedOut bool, started time.Time) (Result, error) {
	semanticCursor := maintainerSemanticCursor{Version: 2, Sequences: sequences, Identities: identities}
	if err := t.persistMaintainerSemanticCursorState(ctx, runUID, repositoryUID, expectedState, semanticCursor); err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	elapsed := 0
	if !started.IsZero() {
		elapsed = int(time.Since(started).Seconds())
	}
	output := maintainerSemanticWaitOutput{Changed: changed, TimedOut: timedOut, ElapsedSeconds: elapsed, MigrationMode: string(triggersv1alpha1.MaintainerWorkItemCutoverController), WorkItems: changes, CursorHandle: maintainerSemanticLatestHandle}
	encoded, err := json.Marshal(output)
	if err != nil {
		return Result{}, err
	}
	return Result{Content: string(encoded)}, nil
}

func resolveSemanticWaitCursor(checkpoint *corev1.Secret, run *platformv1alpha1.AgentRun, repositoryUID types.UID, value string, now time.Time) (maintainerSemanticCursor, error) {
	if value == "" {
		return maintainerSemanticCursor{Version: 2, Sequences: map[string]int64{}}, nil
	}
	if value == maintainerSemanticLatestHandle || strings.HasPrefix(value, maintainerSemanticOpaquePrefix) {
		state, err := resolveMaintainerSemanticCursorState(checkpoint, run, repositoryUID, value, now)
		if err != nil {
			return maintainerSemanticCursor{}, err
		}
		return state.semanticCursor(), nil
	}
	cursor, err := decodeMaintainerSemanticCursor(value)
	if err != nil {
		return maintainerSemanticCursor{}, fmt.Errorf("invalid semantic cursor: %w", err)
	}
	// Compatibility cursors may initialize latest, but must not overwrite a
	// malformed, expired, or cross-boundary checkpoint.
	if checkpoint != nil && len(checkpoint.Data[maintainerSemanticCursorDataKey]) > 0 {
		if _, err := resolveMaintainerSemanticCursorState(checkpoint, run, repositoryUID, maintainerSemanticLatestHandle, now); err != nil {
			return maintainerSemanticCursor{}, err
		}
	}
	return cursor, nil
}

func (t *waitForRepoEventsTool) semanticCursorCheckpoint(ctx context.Context, runUID, repositoryUID types.UID) (*corev1.Secret, error) {
	secret := &corev1.Secret{}
	key := client.ObjectKey{Namespace: t.currentRunNamespace, Name: triggersv1alpha1.MaintainerSemanticCursorSecretName(runUID, repositoryUID)}
	if err := t.k8sClient.Get(ctx, key, secret); err != nil {
		if apierrors.IsNotFound(err) {
			return nil, nil
		}
		return nil, err
	}
	if !semanticCursorSecretOwnedByRun(secret, runUID) {
		return nil, fmt.Errorf("cross-boundary semantic cursor checkpoint ownership")
	}
	return secret, nil
}

func semanticCursorSecretOwnedByRun(secret *corev1.Secret, runUID types.UID) bool {
	if secret == nil {
		return false
	}
	for _, owner := range secret.OwnerReferences {
		if owner.APIVersion == platformv1alpha1.GroupVersion.String() && owner.Kind == "AgentRun" && owner.UID == runUID {
			return true
		}
	}
	return false
}

func resolveMaintainerSemanticCursorState(secret *corev1.Secret, run *platformv1alpha1.AgentRun, repositoryUID types.UID, handle string, now time.Time) (maintainerSemanticCursorState, error) {
	if secret == nil || len(secret.Data[maintainerSemanticCursorDataKey]) == 0 {
		return maintainerSemanticCursorState{}, fmt.Errorf("unknown semantic cursor handle: no latest cursor is established; call once without cursor")
	}
	if run == nil || !semanticCursorSecretOwnedByRun(secret, run.UID) {
		return maintainerSemanticCursorState{}, fmt.Errorf("cross-boundary semantic cursor handle")
	}
	var state maintainerSemanticCursorState
	if err := json.Unmarshal(secret.Data[maintainerSemanticCursorDataKey], &state); err != nil || state.Version != 1 {
		return maintainerSemanticCursorState{}, fmt.Errorf("malformed stored semantic cursor state")
	}
	if err := validateMaintainerSemanticCursorState(state); err != nil {
		return maintainerSemanticCursorState{}, err
	}
	if state.RunUID != run.UID || state.RepositoryUID != repositoryUID {
		return maintainerSemanticCursorState{}, fmt.Errorf("cross-boundary semantic cursor handle")
	}
	if !state.ExpiresAt.After(now) {
		return maintainerSemanticCursorState{}, fmt.Errorf("expired semantic cursor handle; call once without cursor")
	}
	if handle != maintainerSemanticLatestHandle {
		if err := validateMaintainerSemanticHandle(handle); err != nil {
			return maintainerSemanticCursorState{}, err
		}
		if handle != state.Handle {
			return maintainerSemanticCursorState{}, fmt.Errorf("stale semantic cursor handle; use %q", maintainerSemanticLatestHandle)
		}
	}
	return state, nil
}

func validateMaintainerSemanticCursorState(state maintainerSemanticCursorState) error {
	if err := validateMaintainerSemanticHandle(state.Handle); err != nil {
		return fmt.Errorf("malformed stored semantic cursor state")
	}
	seen := make(map[string]struct{}, len(state.Entries))
	for _, entry := range state.Entries {
		if strings.TrimSpace(entry.Name) == "" || entry.Sequence < 0 || entry.IssueNumber <= 0 {
			return fmt.Errorf("malformed stored semantic cursor state")
		}
		if _, exists := seen[entry.Name]; exists {
			return fmt.Errorf("malformed stored semantic cursor state")
		}
		seen[entry.Name] = struct{}{}
	}
	return nil
}

func validateMaintainerSemanticHandle(handle string) error {
	if !strings.HasPrefix(handle, maintainerSemanticOpaquePrefix) {
		return fmt.Errorf("unknown semantic cursor handle")
	}
	raw, err := base64.RawURLEncoding.DecodeString(strings.TrimPrefix(handle, maintainerSemanticOpaquePrefix))
	if err != nil || len(raw) != 16 {
		return fmt.Errorf("malformed semantic cursor handle")
	}
	return nil
}

func (state maintainerSemanticCursorState) semanticCursor() maintainerSemanticCursor {
	cursor := maintainerSemanticCursor{Version: 2, Sequences: make(map[string]int64, len(state.Entries)), Identities: make(map[string]int32, len(state.Entries))}
	for _, entry := range state.Entries {
		cursor.Sequences[entry.Name] = entry.Sequence
		cursor.Identities[entry.Name] = entry.IssueNumber
	}
	return cursor
}

func newMaintainerSemanticCursorState(runUID, repositoryUID types.UID, handle string, expiresAt time.Time, cursor maintainerSemanticCursor) maintainerSemanticCursorState {
	names := make([]string, 0, len(cursor.Sequences))
	for name := range cursor.Sequences {
		names = append(names, name)
	}
	sort.Strings(names)
	entries := make([]maintainerSemanticCursorEntry, 0, len(names))
	for _, name := range names {
		entries = append(entries, maintainerSemanticCursorEntry{Name: name, Sequence: cursor.Sequences[name], IssueNumber: cursor.Identities[name]})
	}
	return maintainerSemanticCursorState{Version: 1, RunUID: runUID, RepositoryUID: repositoryUID, Handle: handle, ExpiresAt: expiresAt, Entries: entries}
}

func (t *waitForRepoEventsTool) persistMaintainerSemanticCursorState(ctx context.Context, runUID, repositoryUID types.UID, expectedState string, cursor maintainerSemanticCursor) error {
	handleBytes := make([]byte, 16)
	if _, err := rand.Read(handleBytes); err != nil {
		return fmt.Errorf("failed to create semantic cursor handle: %w", err)
	}
	handle := maintainerSemanticOpaquePrefix + base64.RawURLEncoding.EncodeToString(handleBytes)
	state := newMaintainerSemanticCursorState(runUID, repositoryUID, handle, time.Now().Add(maintainerSemanticHandleLifetime), cursor)
	encoded, err := json.Marshal(state)
	if err != nil {
		return fmt.Errorf("failed to encode semantic cursor state: %w", err)
	}
	run, err := t.verifySemanticCursorBoundary(ctx, runUID, repositoryUID)
	if err != nil {
		return err
	}
	return t.writeSemanticCursorCheckpoint(ctx, run, repositoryUID, expectedState, encoded)
}

func (t *waitForRepoEventsTool) verifySemanticCursorBoundary(ctx context.Context, runUID, repositoryUID types.UID) (*platformv1alpha1.AgentRun, error) {
	repository, err := t.repository(ctx)
	if err != nil {
		return nil, err
	}
	if repository.UID != repositoryUID {
		return nil, fmt.Errorf("cross-boundary semantic cursor state: maintained repository UID changed")
	}
	run, err := t.currentRunForRepository(ctx, repository)
	if err != nil {
		return nil, err
	}
	if run.UID != runUID {
		return nil, fmt.Errorf("cross-boundary semantic cursor state: maintainer AgentRun UID changed")
	}
	return run, nil
}

func (t *waitForRepoEventsTool) writeSemanticCursorCheckpoint(ctx context.Context, run *platformv1alpha1.AgentRun, repositoryUID types.UID, expectedState string, encoded []byte) error {
	checkpoint, err := t.semanticCursorCheckpoint(ctx, run.UID, repositoryUID)
	if err != nil {
		return fmt.Errorf("failed to read latest semantic cursor checkpoint: %w", err)
	}
	if checkpoint == nil {
		return fmt.Errorf("semantic cursor checkpoint is not provisioned for this maintainer run")
	}
	if expectedState == "" || checkpoint.ResourceVersion != expectedState {
		return fmt.Errorf("stale semantic cursor handle: another wait already advanced latest")
	}
	checkpoint.Data = map[string][]byte{maintainerSemanticCursorDataKey: encoded}
	if err := t.k8sClient.Update(ctx, checkpoint); err != nil {
		if apierrors.IsConflict(err) {
			return fmt.Errorf("stale semantic cursor handle: another wait already advanced latest")
		}
		return fmt.Errorf("failed to update semantic cursor checkpoint: %w", err)
	}
	return nil
}

func validateSemanticWorkItemIdentities(repositoryName string, items map[string]maintainerRepoWorkItemEvent) error {
	for name, item := range items {
		if name != triggersv1alpha1.MaintainerWorkItemName(repositoryName, item.IssueNumber) {
			return fmt.Errorf("non-canonical cursor identity: work item %q", name)
		}
	}
	return nil
}

func validateSemanticCursorIdentities(repositoryName string, cursor maintainerSemanticCursor, current map[string]maintainerRepoWorkItemEvent) error {
	for name := range cursor.Sequences {
		if _, ok := current[name]; ok {
			continue
		}
		if issueNumber, ok := cursor.Identities[name]; ok {
			if issueNumber > 0 && triggersv1alpha1.MaintainerWorkItemName(repositoryName, issueNumber) == name {
				continue
			}
			return fmt.Errorf("non-canonical cursor identity: %q", name)
		}
		if !legacySemanticCursorIdentityCanonical(repositoryName, name) {
			return fmt.Errorf("non-canonical cursor identity: %q", name)
		}
	}
	return nil
}

func legacySemanticCursorIdentityCanonical(repositoryName, name string) bool {
	const hashLength = 10
	separator := strings.LastIndexByte(name, '-')
	if !strings.HasPrefix(name, "mwi-") || len(name) > 63 || separator <= 4 || len(name)-separator-1 != hashLength || !lowerHex(name[separator+1:]) {
		return false
	}
	for part := range strings.SplitSeq(name[:separator], "-") {
		issueNumber, err := strconv.ParseInt(part, 10, 32)
		if err == nil && issueNumber > 0 && triggersv1alpha1.MaintainerWorkItemName(repositoryName, int32(issueNumber)) == name {
			return true
		}
	}
	probe := triggersv1alpha1.MaintainerWorkItemName(repositoryName, 1)
	probeSeparator := strings.LastIndexByte(probe, '-')
	probeBase := probe[:probeSeparator]
	candidateBase := name[:separator]
	if candidateBase == probeBase {
		return true
	}
	if !strings.HasSuffix(probeBase, "-1") {
		return false
	}
	repositoryBase := strings.TrimSuffix(probeBase, "-1")
	if candidateBase == repositoryBase {
		return true
	}
	partialIssue := strings.TrimPrefix(candidateBase, repositoryBase+"-")
	return partialIssue != candidateBase && partialIssue != "" && decimalDigits(partialIssue)
}

func lowerHex(value string) bool {
	for _, char := range value {
		if (char < '0' || char > '9') && (char < 'a' || char > 'f') {
			return false
		}
	}
	return true
}

func decimalDigits(value string) bool {
	for _, char := range value {
		if char < '0' || char > '9' {
			return false
		}
	}
	return true
}

func encodeMaintainerSemanticCursor(cursor maintainerSemanticCursor) (string, error) {
	if cursor.Sequences == nil {
		cursor.Sequences = map[string]int64{}
	}
	encoded, err := json.Marshal(cursor)
	if err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(encoded), nil
}

func decodeMaintainerSemanticCursor(value string) (maintainerSemanticCursor, error) {
	raw, err := base64.RawURLEncoding.DecodeString(strings.TrimSpace(value))
	if err != nil {
		return maintainerSemanticCursor{}, err
	}
	var cursor maintainerSemanticCursor
	if err := json.Unmarshal(raw, &cursor); err != nil {
		return maintainerSemanticCursor{}, err
	}
	if cursor.Version != 2 || cursor.Sequences == nil {
		return maintainerSemanticCursor{}, fmt.Errorf("unsupported waiter cursor version")
	}
	for name, sequence := range cursor.Sequences {
		if strings.TrimSpace(name) == "" || sequence < 0 {
			return maintainerSemanticCursor{}, fmt.Errorf("invalid projection sequence cursor")
		}
	}
	return cursor, nil
}

