const (
	maintainerLegacyDispatchToolName = "dispatch_issue"
	maintainerLegacyMergeToolName    = "merge_pull_request"
	maintainerLegacyRunToolName      = "mark_run_succeeded"
	maintainerLegacyCloseToolName    = "close_github_issue"
)

// MaintainerLegacyMutationToolNames returns the live-cutover-controlled tool
// candidates retained for rollback without restarting the standing run.
func MaintainerLegacyMutationToolNames() []string {
	return []string{maintainerLegacyDispatchToolName, maintainerLegacyMergeToolName, maintainerLegacyRunToolName, maintainerLegacyCloseToolName}
}

func RegisterMaintainerTools(registry *Registry, stateStore store.StateStore, k8sClient client.Client, currentRunName, currentRunNamespace, currentRunUID, repositoryName, repositoryNamespace string) {
	if registry == nil || stateStore == nil || k8sClient == nil || strings.TrimSpace(currentRunName) == "" || strings.TrimSpace(currentRunNamespace) == "" || strings.TrimSpace(currentRunUID) == "" || strings.TrimSpace(repositoryName) == "" || strings.TrimSpace(repositoryNamespace) == "" {
		return
	}
	base := maintainerToolBase{
		stateStore: stateStore, k8sClient: k8sClient,
		currentRunName: currentRunName, currentRunNamespace: currentRunNamespace, currentRunUID: types.UID(currentRunUID),
		repositoryName: repositoryName, repositoryNamespace: repositoryNamespace,
	}
	if closeTool := registry.Get(maintainerLegacyCloseToolName); closeTool != nil {
		registry.Register(&maintainerCutoverGuardedTool{Tool: closeTool, base: base})
	}
	for _, name := range []string{"create_github_issue", "add_github_issue_comment"} {
		if issueTool := registry.Get(name); issueTool != nil {
			registry.Register(&maintainerRepositoryScopedTool{Tool: issueTool, base: base})
		}
	}
	registry.Register(&getFleetRunsTool{maintainerToolBase: base})
	registry.Register(&getFleetRunActivityTool{maintainerToolBase: base})
	registry.Register(&waitForRunsTool{maintainerToolBase: base, pollInterval: 10 * time.Second})
	registry.Register(&waitForRepoEventsTool{maintainerToolBase: base, runner: prReviewExecRunner{}, backlogPollInterval: defaultBacklogPollInterval, fleetPollInterval: defaultFleetEventsPollInterval})
	registry.Register(&triageIssueTool{maintainerToolBase: base})
	registry.Register(&breakdownIssueTool{maintainerToolBase: base})
	registry.Register(&breakdownIssueTool{maintainerToolBase: base, toolName: "set_work_item_graph"})
	registry.Register(&requestDecisionTool{maintainerToolBase: base})
	registry.Register(&dispatchWorkItemTool{maintainerToolBase: base})
	registry.Register(&requestMergeTool{maintainerToolBase: base})
	registry.Register(&finalizeWorkItemTool{maintainerToolBase: base})
	registry.Register(&dispatchIssueTool{maintainerToolBase: base, runner: prReviewExecRunner{}})
	registry.Register(&mergePullRequestTool{maintainerToolBase: base, runner: prReviewExecRunner{}})
	registry.Register(&wakeAgentRunTool{maintainerToolBase: base})
	registry.Register(&stopAgentRunTurnTool{maintainerToolBase: base})
	registry.Register(&reportPlatformBugTool{maintainerToolBase: base, runner: prReviewExecRunner{}})
	registry.Register(&getRunMessagesTool{maintainerToolBase: base})
	registry.Register(&cancelRunMessageTool{maintainerToolBase: base})
	registry.Register(&editRunMessageTool{maintainerToolBase: base})
	registry.Register(&getRunTranscriptTool{maintainerToolBase: base})
	registry.Register(&submitMaintainerReportTool{maintainerToolBase: base})
	registry.Register(&extendRunTimeoutTool{maintainerToolBase: base})
	registry.Register(&markRunSucceededTool{maintainerToolBase: base})
}

type maintainerCutoverGuardedTool struct {
	Tool
	base maintainerToolBase
}

func (t *maintainerCutoverGuardedTool) Execute(ctx context.Context, input json.RawMessage, workDir string) (Result, error) {
	if err := t.base.requireLegacyMutationAuthority(ctx); err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	return t.Tool.Execute(ctx, input, workDir)
}

// maintainerRepositoryScopedTool prevents generic issue mutators from becoming
// an alternate cross-repository publication path around report_platform_bug.
// The maintained checkout is always the workspace root; additional repositories
// are mounted under a non-root repo_path.
type maintainerRepositoryScopedTool struct {
	Tool
	base maintainerToolBase
}

func (t *maintainerRepositoryScopedTool) Description() string {
	return t.Tool.Description() + " Maintainer sessions may target only the maintained repository workspace root; cross-repository issue mutation is denied."
}

func (t *maintainerRepositoryScopedTool) Execute(ctx context.Context, input json.RawMessage, workDir string) (Result, error) {
	if _, err := t.base.currentRun(ctx); err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	var target struct {
		RepoPath string `json:"repo_path"`
	}
	if err := json.Unmarshal(input, &target); err != nil {
		return Result{Content: fmt.Sprintf("invalid input: %v", err), IsError: true}, nil
	}
	if repoPath := strings.TrimSpace(target.RepoPath); repoPath != "" && filepath.Clean(repoPath) != "." {
		return Result{Content: "cross-repository issue mutation is denied for maintainer sessions; use report_platform_bug, which requires explicit administrator approval", IsError: true}, nil
	}
	return t.Tool.Execute(ctx, input, workDir)
}

type fleetRunOutput struct {
	Name  string                         `json:"name"`
	Phase platformv1alpha1.AgentRunPhase `json:"phase"`
	// Episode reports whether the run is progressing on its own ("Active") or
	// has finished its current execution episode / is waiting on external
	// input ("Finished"). Phase alone never proves activity: a Running run
	// with a Finished episode is idle-but-wakeable and will not produce more
	// work until woken.
	Episode         string                          `json:"episode"`
	Mode            string                          `json:"mode"`
	Role            string                          `json:"role,omitempty"`
	IssueRef        *platformv1alpha1.ExternalRef   `json:"issue_ref,omitempty"`
	CreatedAt       time.Time                       `json:"created_at,omitempty"`
	StartedAt       *metav1.Time                    `json:"started_at,omitempty"`
	CompletedAt     *metav1.Time                    `json:"completed_at,omitempty"`
	PullRequestURLs []string                        `json:"pull_request_urls,omitempty"`
	CostUSD         string                          `json:"cost_usd,omitempty"`
	QueueState      string                          `json:"queue_state,omitempty"`
	BlockedReason   string                          `json:"blocked_reason,omitempty"`
	PRLoopState     string                          `json:"pr_loop_state,omitempty"`
	ReviewRound     string                          `json:"review_round,omitempty"`
	PendingInput    *orchestration.PendingUserInput `json:"pending_input,omitempty"`
}

type fleetCapsOutput struct {
	ActiveDispatches        int   `json:"active_dispatches"`
	MaxConcurrentDispatches int32 `json:"max_concurrent_dispatches"`
	LedgerDispatches        int   `json:"ledger_dispatches"`
	MaxDispatchesPerDay     int32 `json:"max_dispatches_per_day"`
}

type getFleetRunsOutput struct {
	Runs                      []fleetRunOutput `json:"runs"`
	Caps                      fleetCapsOutput  `json:"caps"`
	DispatchMode              string           `json:"dispatch_mode"`
	PlatformBugReportsAllowed bool             `json:"platform_bug_reports_allowed"`
	// MergeAllowed reports whether the repository grants the maintainer
	// permission to merge attached pull requests via request_merge. When true,
	// merging ready pull requests is the maintainer's responsibility.
	MergeAllowed bool `json:"merge_allowed"`
	// FullControl reports whether the repository grants the maintainer full
	// control (merge without human approval when GitHub gates pass).
	FullControl bool `json:"full_control"`
}

type getFleetRunsTool struct{ maintainerToolBase }

func (t *getFleetRunsTool) Name() string { return "get_fleet_runs" }
func (t *getFleetRunsTool) Description() string {
	return "List the maintained repository's controller-owned dispatch mode, capacity caps, merge permissions (merge_allowed/full_control), and dispatched implementer/reviewer runs with lifecycle, artifacts, queue state, and pending input. Each run reports episode \"Active\" or \"Finished\": phase never proves activity — a Running run with episode Finished has ended its execution episode, is only idle-but-wakeable, and will not produce more work until woken."
}
func (t *getFleetRunsTool) InputSchema() json.RawMessage {
	// Keep an explicit empty properties object: bare {"type":"object"} trips a
	// serialization gap in older SDK builds where the Anthropic tool converter
	// drops input_schema entirely (API 400 "input_schema: Field required").
	return json.RawMessage(`{"type":"object","properties":{}}`)
}
func (t *getFleetRunsTool) IsReadOnly() bool                      { return true }
func (t *getFleetRunsTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }
func (t *getFleetRunsTool) NeedsApproval() bool                   { return false }
func (t *getFleetRunsTool) TimeoutSeconds() int                   { return 0 }

func (t *getFleetRunsTool) Execute(ctx context.Context, _ json.RawMessage, _ string) (Result, error) {
	if _, err := t.currentRun(ctx); err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	repository, err := t.repository(ctx)
	if err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	fleet, err := t.fleetRuns(ctx)
	if err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	dispatchMode, err := maintainerDispatchMode(repository)
	if err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	allowPlatformReports := repository.Spec.Maintainer != nil && repository.Spec.Maintainer.AllowPlatformBugReports
	fullControl := repository.Spec.Maintainer != nil && repository.Spec.Maintainer.FullControl
	mergeAllowed := fullControl || (repository.Spec.Maintainer != nil && repository.Spec.Maintainer.AllowPullRequestMerge)
	out := getFleetRunsOutput{Runs: make([]fleetRunOutput, 0, len(fleet)), DispatchMode: dispatchMode, PlatformBugReportsAllowed: allowPlatformReports, MergeAllowed: mergeAllowed, FullControl: fullControl}
	for i := range fleet {
		run := &fleet[i]
		entry, err := t.describeFleetRun(ctx, run)
		if err != nil {
			return Result{Content: err.Error(), IsError: true}, nil
		}
		out.Runs = append(out.Runs, entry)
	}
	maxConcurrent, maxDaily := maintainerDispatchCaps(repository)
	dispatchesToday := 0
	if repository.Status.Maintainer != nil {
		dispatchesToday = int(repository.Status.Maintainer.DispatchesToday)
	}
	for i := range fleet {
		if !maintainerIsReviewer(&fleet[i]) && !maintainerTerminal(fleet[i].Status.Phase) {
			out.Caps.ActiveDispatches++
		}
	}
	out.Caps.MaxConcurrentDispatches = maxConcurrent
	out.Caps.LedgerDispatches = dispatchesToday
	out.Caps.MaxDispatchesPerDay = maxDaily
	encoded, err := json.Marshal(out)
	if err != nil {
		return Result{}, err
	}
	return Result{Content: string(encoded)}, nil
}

func (t *getFleetRunsTool) describeFleetRun(ctx context.Context, run *platformv1alpha1.AgentRun) (fleetRunOutput, error) {
	entry := fleetRunOutput{Name: run.Name, Phase: run.Status.Phase, Episode: maintainerEpisodeState(run), Mode: run.Status.ModeName, CreatedAt: run.CreationTimestamp.Time}
	if run.Spec.Trigger.ExternalRef != nil {
		ref := *run.Spec.Trigger.ExternalRef
		entry.IssueRef = &ref
	}
	entry.StartedAt, entry.CompletedAt = run.Status.StartedAt, run.Status.CompletedAt
	if maintainerIsReviewer(run) {
		entry.Role = "reviewer"
	} else {
		entry.Role = "implementer"
	}
	entry.PRLoopState = run.Labels[maintainerPRLoopStateLabel]
	entry.ReviewRound = run.Annotations[maintainerPRLoopRoundAnnotation]
	if run.Status.Artifacts != nil {
		entry.PullRequestURLs = append(entry.PullRequestURLs, run.Status.Artifacts.PullRequestURLs...)
		if len(entry.PullRequestURLs) == 0 && run.Status.Artifacts.PullRequestURL != "" {
			entry.PullRequestURLs = []string{run.Status.Artifacts.PullRequestURL}
		}
	}
	if run.Status.Metrics != nil {
		entry.CostUSD = run.Status.Metrics.CostUsd
	}
	if run.Status.Queue != nil {
		entry.QueueState = run.Status.Queue.State
		entry.BlockedReason = run.Status.Queue.BlockedReason
	}
	session, err := t.stateStore.GetSessionByRun(ctx, run.Name, run.Namespace)
	if err != nil {
		return fleetRunOutput{}, fmt.Errorf("failed to resolve session for fleet AgentRun %q: %w", run.Name, err)
	}
	entry.PendingInput = orchestration.PendingUserInputForSession(session)
	return entry, nil
}

type getFleetRunActivityTool struct{ maintainerToolBase }

type getFleetRunActivityInput struct {
	RunName        string `json:"run_name"`
	MessageCursor  int64  `json:"message_cursor,omitempty"`
	ActivityCursor int64  `json:"activity_cursor,omitempty"`
	Limit          int    `json:"limit,omitempty"`
}

func (t *getFleetRunActivityTool) Name() string { return "get_run_activity" }
func (t *getFleetRunActivityTool) Description() string {
	return "Read cursor-paged messages and activity for one authorized fleet AgentRun."
}
func (t *getFleetRunActivityTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{"type":"object","properties":{"run_name":{"type":"string"},"message_cursor":{"type":"integer","minimum":0},"activity_cursor":{"type":"integer","minimum":0},"limit":{"type":"integer","minimum":1,"maximum":200}},"required":["run_name"]}`)
}
func (t *getFleetRunActivityTool) IsReadOnly() bool                      { return true }
func (t *getFleetRunActivityTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }
func (t *getFleetRunActivityTool) NeedsApproval() bool                   { return false }
func (t *getFleetRunActivityTool) TimeoutSeconds() int                   { return 0 }

func (t *getFleetRunActivityTool) Execute(ctx context.Context, input json.RawMessage, _ string) (Result, error) {
	var in getFleetRunActivityInput
	if err := json.Unmarshal(input, &in); err != nil {
		return Result{Content: fmt.Sprintf("invalid input: %v", err), IsError: true}, nil
	}
	if strings.TrimSpace(in.RunName) == "" || in.MessageCursor < 0 || in.ActivityCursor < 0 || in.Limit < 0 {
		return Result{Content: "run_name is required; cursors must be non-negative and limit must be positive", IsError: true}, nil
	}
	if _, err := t.currentRun(ctx); err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	run, err := t.fleetRun(ctx, strings.TrimSpace(in.RunName))
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to verify fleet AgentRun: %v", err), IsError: true}, nil
	}
	session, err := t.stateStore.GetSessionByRun(ctx, run.Name, run.Namespace)
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to resolve fleet session: %v", err), IsError: true}, nil
	}
	if session == nil {
		return Result{Content: "fleet session not found", IsError: true}, nil
	}
	inputRequest := orchestration.PendingUserInputForSession(session)
	pendingMCP, err := mcppolicy.PendingRequest(run)
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to decode fleet MCP request: %v", err), IsError: true}, nil
	}
	if pendingMCP != nil {
		inputRequest = orchestration.BindPendingUserInputContext(inputRequest, pendingMCP.ID)
	}
	messages, err := t.stateStore.GetMessagesSince(ctx, session.ID, in.MessageCursor)
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to read fleet messages: %v", err), IsError: true}, nil
	}
	events, err := t.stateStore.GetActivityEventsSince(ctx, session.ID, in.ActivityCursor)
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to read fleet activity: %v", err), IsError: true}, nil
	}
	limit := in.Limit
	if limit == 0 {
		limit = 50
	}
	if limit > 200 {
		limit = 200
	}
	out := supervisedActivityOutput{
		State:    supervisedRunState{Phase: run.Status.Phase, Mode: run.Status.ModeName, ModeRevision: run.Status.ModeRevision, UserInputRequest: inputRequest},
		Messages: make([]supervisedMessage, 0, min(limit, len(messages))), Activity: make([]supervisedEvent, 0, min(limit, len(events))),
		NextMessageCursor: in.MessageCursor, NextActivityCursor: in.ActivityCursor,
	}
	messageBudget := supervisedActivityStreamBudget
	for _, message := range messages[:min(limit, len(messages))] {
		content := truncateUTF8(message.Content, 4000)
		cost := len(content) + len(message.Role) + 96
		if len(out.Messages) > 0 && cost > messageBudget {
			break
		}
		if cost > messageBudget {
			content = truncateUTF8(content, max(0, messageBudget-96))
			cost = len(content) + len(message.Role) + 96
		}
		out.Messages = append(out.Messages, supervisedMessage{ID: message.ID, Role: message.Role, Content: content, CreatedAt: message.CreatedAt})
		out.NextMessageCursor = message.ID
		messageBudget -= min(cost, messageBudget)
	}
	activityBudget := supervisedActivityStreamBudget
	for _, event := range events[:min(limit, len(events))] {
		summary := truncateUTF8(event.Summary, 2000)
		detail := event.Detail
		if len(detail) > 4000 {
			detail = json.RawMessage(`{"truncated":true}`)
		}
		cost := len(summary) + len(detail) + len(event.EventType) + 112
		if len(out.Activity) > 0 && cost > activityBudget {
			break
		}
		if cost > activityBudget {
			summary = truncateUTF8(summary, max(0, activityBudget-len(detail)-112))
			cost = len(summary) + len(detail) + len(event.EventType) + 112
		}
		out.Activity = append(out.Activity, supervisedEvent{ID: event.ID, EventType: event.EventType, Summary: summary, Detail: detail, CreatedAt: event.CreatedAt})
		out.NextActivityCursor = event.ID
		activityBudget -= min(cost, activityBudget)
	}
	out.HasMore = len(out.Messages) < len(messages) || len(out.Activity) < len(events)
	encoded, err := json.Marshal(out)
	if err != nil {
		return Result{}, err
	}
	return Result{Content: string(encoded)}, nil
}

package tools

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	"github.com/gratefulagents/gratefulagents/internal/store/sessionclient"
	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

type stopAgentRunTurnTool struct{ maintainerToolBase }

type stopAgentRunTurnInput struct {
	RunName string `json:"run_name"`
	Reason  string `json:"reason"`
}

func (t *stopAgentRunTurnTool) Name() string { return "stop_agent_run_turn" }
func (t *stopAgentRunTurnTool) Description() string {
	return "Explicitly stop the current turn of an authorized running implementer without cancelling the AgentRun. This is independent of steer/queue delivery; send a new steering or queued message separately when the run should continue."
}
func (t *stopAgentRunTurnTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{"type":"object","properties":{"run_name":{"type":"string","minLength":1},"reason":{"type":"string","minLength":1,"maxLength":1000}},"required":["run_name","reason"]}`)
}
func (t *stopAgentRunTurnTool) IsReadOnly() bool                      { return false }
func (t *stopAgentRunTurnTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }
func (t *stopAgentRunTurnTool) NeedsApproval() bool                   { return false }
func (t *stopAgentRunTurnTool) TimeoutSeconds() int                   { return 0 }

func (t *stopAgentRunTurnTool) Execute(ctx context.Context, input json.RawMessage, _ string) (Result, error) {
	var in stopAgentRunTurnInput
	if err := json.Unmarshal(input, &in); err != nil {
		return Result{Content: fmt.Sprintf("invalid input: %v", err), IsError: true}, nil
	}
	name, reason := strings.TrimSpace(in.RunName), strings.TrimSpace(in.Reason)
	if name == "" || reason == "" {
		return Result{Content: "run_name and reason are required", IsError: true}, nil
	}
	if len([]rune(reason)) > 1000 {
		return Result{Content: "reason must be at most 1000 characters", IsError: true}, nil
	}
	if _, err := t.currentRun(ctx); err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	run, err := t.fleetRun(ctx, name)
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to verify fleet AgentRun: %v", err), IsError: true}, nil
	}
	if maintainerIsReviewer(run) {
		return Result{Content: "reviewer fleet runs cannot be stopped by the maintainer", IsError: true}, nil
	}
	repository, err := t.repository(ctx)
	if err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	if run.Status.Phase != platformv1alpha1.AgentRunPhaseRunning {
		return Result{Content: fmt.Sprintf("AgentRun %q is not running; current phase is %s", name, run.Status.Phase), IsError: true}, nil
	}
	session, err := t.stateStore.GetSessionByRun(ctx, run.Name, run.Namespace)
	if err != nil || session == nil {
		return Result{Content: fmt.Sprintf("failed to resolve active fleet session: %v", err), IsError: true}, nil
	}
	// Close the authorization race immediately before persisting the interrupt.
	caller, err := t.currentRun(ctx)
	if err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	run, err = t.fleetRun(ctx, name)
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to reverify fleet AgentRun: %v", err), IsError: true}, nil
	}
	repository, err = t.repository(ctx)
	if err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	if !maintainerFleetRunOwnedByRepository(caller, repository) {
		return Result{Content: "calling maintainer is no longer owned by the maintained repository UID", IsError: true}, nil
	}
	if run.Status.Phase != platformv1alpha1.AgentRunPhaseRunning || maintainerIsReviewer(run) || !t.isFleetRunForRepository(ctx, run, repository) {
		return Result{Content: "target AgentRun is no longer an authorized running implementer", IsError: true}, nil
	}
	requestedBy := "maintainer:" + t.currentRunName
	if err := sessionclient.RequestInterrupt(ctx, t.stateStore, session.ID, requestedBy); err != nil {
		return Result{Content: fmt.Sprintf("failed to request turn stop: %v", err), IsError: true}, nil
	}
	detail, _ := json.Marshal(map[string]string{"reason": reason, "requested_by": requestedBy})
	_, _ = t.stateStore.WriteActivityEvent(ctx, session.ID, "interrupt_requested", "Maintainer requested that the current turn stop: "+reason, detail)
	return Result{Content: fmt.Sprintf("Stop requested for the current turn of AgentRun %q; the run remains resumable.", name)}, nil
}

package tools

import (
	"context"
	"encoding/json"
	"fmt"
	"strconv"
	"strings"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

type mergePullRequestTool struct {
	maintainerToolBase
	runner prReviewRunner
}

type mergePullRequestInput struct {
	PRNumber    int    `json:"pr_number"`
	MergeMethod string `json:"merge_method,omitempty"`
}

type mergePullRequestView struct {
	State          string `json:"state"`
	IsDraft        bool   `json:"isDraft"`
	Mergeable      string `json:"mergeable"`
	ReviewDecision string `json:"reviewDecision"`
	URL            string `json:"url"`
	HeadRefName    string `json:"headRefName"`
	HeadRefOid     string `json:"headRefOid"`
}

func (t *mergePullRequestTool) Name() string { return "merge_pull_request" }
func (t *mergePullRequestTool) Description() string {
	return "Dangerously merge one approved, non-draft pull request only after confirming mergeability, current-head CI success, and repository policy; then re-read GitHub to distinguish a completed merge from a queued merge request."
}
func (t *mergePullRequestTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{"type":"object","properties":{"pr_number":{"type":"integer","minimum":1},"merge_method":{"type":"string","enum":["squash","merge","rebase"]}},"required":["pr_number"]}`)
}
func (t *mergePullRequestTool) IsReadOnly() bool                      { return false }
func (t *mergePullRequestTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }
func (t *mergePullRequestTool) NeedsApproval() bool                   { return false }
func (t *mergePullRequestTool) TimeoutSeconds() int                   { return 0 }

func (t *mergePullRequestTool) Execute(ctx context.Context, input json.RawMessage, workDir string) (Result, error) {
	if err := t.requireLegacyMutationAuthority(ctx); err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	var in mergePullRequestInput
	if err := json.Unmarshal(input, &in); err != nil {
		return Result{Content: fmt.Sprintf("invalid input: %v", err), IsError: true}, nil
	}
	if in.PRNumber <= 0 {
		return Result{Content: "pr_number must be greater than zero", IsError: true}, nil
	}
	method := strings.ToLower(strings.TrimSpace(in.MergeMethod))
	if method == "" {
		method = "squash"
	}
	if method != "squash" && method != "merge" && method != "rebase" {
		return Result{Content: `merge_method must be "squash", "merge", or "rebase"`, IsError: true}, nil
	}
	if _, err := t.currentRun(ctx); err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	repository, err := t.repository(ctx)
	if err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	if repository.Spec.Maintainer == nil || !repository.Spec.Maintainer.AllowPullRequestMerge {
		return Result{Content: "merge_pull_request is not enabled for this repository (spec.maintainer.allowPullRequestMerge); merging stays human", IsError: true}, nil
	}
	wd, err := resolveLocalGitRepositoryWorkDir(workDir, "")
	if err != nil {
		return Result{Content: fmt.Sprintf("workspace repository unavailable: %v", err), IsError: true}, nil
	}
	runner := t.runner
	if runner == nil {
		runner = prReviewExecRunner{}
	}
	number := strconv.Itoa(in.PRNumber)
	out, err := runner.RunGH(ctx, wd, "pr", "view", number, "--json", "state,isDraft,mergeable,reviewDecision,url,headRefName,headRefOid")
	if err != nil {
		return Result{Content: fmt.Sprintf("gh pr view failed: %v\n%s", err, out), IsError: true}, nil
	}
	var view mergePullRequestView
	if err := json.Unmarshal([]byte(out), &view); err != nil {
		return Result{Content: fmt.Sprintf("parse gh pr view output: %v", err), IsError: true}, nil
	}
	linked, err := t.pullRequestBelongsToFleet(ctx, view.URL)
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to verify pull request linkage: %v", err), IsError: true}, nil
	}
	if !linked {
		return Result{Content: fmt.Sprintf("pull request #%d is not attached to an authorized maintainer fleet run", in.PRNumber), IsError: true}, nil
	}
	if view.State != "OPEN" {
		return Result{Content: fmt.Sprintf("pull request #%d is not open (state: %s)", in.PRNumber, view.State), IsError: true}, nil
	}
	if view.IsDraft {
		return Result{Content: fmt.Sprintf("pull request #%d is a draft", in.PRNumber), IsError: true}, nil
	}
	if strings.TrimSpace(view.ReviewDecision) == "" {
		// GitHub computes reviewDecision only when the base branch requires
		// pull-request reviews. Without that protection an approving review
		// cannot be verified, so the gate fails closed with the reason.
		return Result{Content: fmt.Sprintf("pull request #%d has no computed review decision: the base branch does not require pull-request reviews, so approval cannot be verified. Enable required reviews via branch protection or a ruleset, or leave merging to humans.", in.PRNumber), IsError: true}, nil
	}
	if view.ReviewDecision != "APPROVED" {
		return Result{Content: fmt.Sprintf("pull request #%d is not approved (review decision: %s)", in.PRNumber, view.ReviewDecision), IsError: true}, nil
	}
	if view.Mergeable != "MERGEABLE" {
		return Result{Content: fmt.Sprintf("pull request #%d mergeability is not confirmed (state: %s)", in.PRNumber, view.Mergeable), IsError: true}, nil
	}
	if strings.TrimSpace(view.HeadRefOid) == "" {
		return Result{Content: fmt.Sprintf("pull request #%d has no head commit SHA", in.PRNumber), IsError: true}, nil
	}
	checksOut, err := runner.RunGH(ctx, wd, "api", "repos/{owner}/{repo}/commits/"+view.HeadRefOid+"/check-runs", "--paginate")
	if err != nil {
		return Result{Content: fmt.Sprintf("gh api check-runs failed: %v\n%s", err, checksOut), IsError: true}, nil
	}
	checks, err := parseCheckRunPages(checksOut)
	if err != nil {
		return Result{Content: fmt.Sprintf("parse check-runs output: %v", err), IsError: true}, nil
	}
	statusOut, err := runner.RunGH(ctx, wd, "api", "repos/{owner}/{repo}/commits/"+view.HeadRefOid+"/status")
	if err != nil {
		return Result{Content: fmt.Sprintf("gh api commit status failed: %v\n%s", err, statusOut), IsError: true}, nil
	}
	var combinedStatus struct {
		Statuses []pullRequestCommitStatus `json:"statuses"`
	}
	if err := json.Unmarshal([]byte(statusOut), &combinedStatus); err != nil {
		return Result{Content: fmt.Sprintf("parse commit status output: %v", err), IsError: true}, nil
	}
	checksSummary := maintainerPullRequestChecksSummary(checks, combinedStatus.Statuses)
	if checksSummary.Pending > 0 {
		return Result{Content: fmt.Sprintf("pull request #%d still has %d pending checks or commit statuses", in.PRNumber, checksSummary.Pending), IsError: true}, nil
	}
	if checksSummary.Failed > 0 {
		return Result{Content: fmt.Sprintf("pull request #%d has %d failing checks or commit statuses", in.PRNumber, checksSummary.Failed), IsError: true}, nil
	}
	out, err = runner.RunGH(ctx, wd, "pr", "merge", number, "--"+method, "--match-head-commit", view.HeadRefOid)
	if err != nil {
		return Result{Content: fmt.Sprintf("gh pr merge failed: %v\n%s", err, out), IsError: true}, nil
	}
	postOut, err := runner.RunGH(ctx, wd, "pr", "view", number, "--json", "state,mergedAt,url,headRefOid")
	if err != nil {
		return Result{Content: fmt.Sprintf("merge command completed, but post-merge verification failed: %v\n%s", err, postOut), IsError: true}, nil
	}
	var post struct {
		State      string `json:"state"`
		MergedAt   string `json:"mergedAt"`
		URL        string `json:"url"`
		HeadRefOid string `json:"headRefOid"`
	}
	if err := json.Unmarshal([]byte(postOut), &post); err != nil {
		return Result{Content: fmt.Sprintf("parse post-merge pull request output: %v", err), IsError: true}, nil
	}
	if post.State != "MERGED" || strings.TrimSpace(post.MergedAt) == "" {
		return Result{Content: fmt.Sprintf("Merge request for %s was accepted but GitHub has not reported it merged yet (state: %s). Keep the work item active and wait for a pull-request event before finalizing the run or issue.", view.URL, post.State)}, nil
	}
	if post.HeadRefOid != view.HeadRefOid {
		return Result{Content: fmt.Sprintf("pull request %s merged an unexpected head SHA (verified %s, merged %s); do not finalize automatically", view.URL, view.HeadRefOid, post.HeadRefOid), IsError: true}, nil
	}
	return Result{Content: fmt.Sprintf("Verified pull request %s merged at %s with %s after checking %d checks and commit statuses. Finalize only after confirming the accepted issue scope is delivered.", post.URL, post.MergedAt, method, checksSummary.Total)}, nil
}

func (t *mergePullRequestTool) pullRequestBelongsToFleet(ctx context.Context, rawURL string) (bool, error) {
	owner, repository, number, err := parseMaintainerPullRequestURL(rawURL)
	if err != nil {
		return false, err
	}
	fleet, err := t.fleetRuns(ctx)
	if err != nil {
		return false, err
	}
	for i := range fleet {
		for _, candidate := range waitPullRequestURLs(&fleet[i]) {
			candidateOwner, candidateRepository, candidateNumber, err := parseMaintainerPullRequestURL(candidate)
			if err != nil {
				continue
			}
			if owner == candidateOwner && repository == candidateRepository && number == candidateNumber {
				return true, nil
			}
		}
	}
	return false, nil
}

