	ResourceVersion    string `json:"resource_version"`
	ProjectionSequence int64  `json:"projection_sequence"`
}

type triageIssueOutput struct {
	CommandName string                                            `json:"command_name"`
	Phase       triggersv1alpha1.MaintainerWorkItemCommandPhase   `json:"phase"`
	Replayed    bool                                              `json:"replayed"`
	PayloadHash string                                            `json:"payload_hash"`
	WorkItem    triageIssueWorkItemOutput                         `json:"work_item"`
	Result      *triggersv1alpha1.MaintainerWorkItemCommandResult `json:"result,omitempty"`
	Applied     bool                                              `json:"applied"`
	Message     string                                            `json:"message,omitempty"`
	// AwaitingController is set when the controller had not recorded a
	// terminal phase within the bounded await; Hint tells the model how to
	// observe the outcome.
	AwaitingController bool   `json:"awaiting_controller,omitempty"`
	Hint               string `json:"hint,omitempty"`
}

func (t *triageIssueTool) Name() string { return "triage_issue" }
func (t *triageIssueTool) Description() string {
	return "Submit an immutable, idempotent triage command for one maintained repository issue. The receipt awaits the controller and normally returns the terminal phase (Succeeded/Rejected/Failed); only when awaiting_controller is set must you wait for latest_command.phase before treating triage as applied."
}
func (t *triageIssueTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{"type":"object","properties":{"issue_number":{"type":"integer","minimum":1},"disposition":{"type":"string","enum":["NotActionable","Bounded","Decomposable","Discovery","Escalated"]},"evidence_summary":{"type":"string","minLength":1},"accepted_scope":{"type":"object","properties":{"statement":{"type":"string"},"acceptance_criteria":{"type":"array","items":{"type":"string"}}}},"close_reason":{"type":"string","enum":["not_planned","completed"]},"idempotency_key":{"type":"string","minLength":1,"maxLength":128,"pattern":"^[A-Za-z0-9][A-Za-z0-9._:-]*$"},"expected_projection_sequence":{"type":"integer","minimum":0},"expected_resource_version":{"type":"string","minLength":1}},"required":["issue_number","disposition","evidence_summary","accepted_scope","idempotency_key","expected_projection_sequence"]}`)
}
func (t *triageIssueTool) IsReadOnly() bool                      { return false }
func (t *triageIssueTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }
func (t *triageIssueTool) NeedsApproval() bool                   { return false }
func (t *triageIssueTool) TimeoutSeconds() int                   { return 0 }

func (t *triageIssueTool) Execute(ctx context.Context, input json.RawMessage, _ string) (Result, error) {
	var in triageIssueInput
	if err := json.Unmarshal(input, &in); err != nil {
		return triageIssueError("invalid input: %v", err)
	}
	if err := validateTriageIssueInput(in); err != nil {
		return triageIssueError("%v", err)
	}

	current, err := t.currentRun(ctx)
	if err != nil {
		return triageIssueError("%v", err)
	}
	repository, err := t.repository(ctx)
	if err != nil {
		return triageIssueError("%v", err)
	}

	workItemName := maintainerWorkItemName(repository.Name, in.IssueNumber)
	workItem := &triggersv1alpha1.MaintainerWorkItem{}
	if err := t.k8sClient.Get(ctx, client.ObjectKey{Name: workItemName, Namespace: repository.Namespace}, workItem); err != nil {
		return triageIssueError("failed to get maintainer work item %q: %v", workItemName, err)
	}
	if workItem.Spec.RepositoryRef.Name != repository.Name || workItem.Spec.IssueNumber != in.IssueNumber {
		return triageIssueError("maintainer work item %q does not belong to repository %q issue #%d", workItem.Name, repository.Name, in.IssueNumber)
	}

	triage := &triggersv1alpha1.MaintainerTriageCommand{
		IssueNumber:     in.IssueNumber,
		Disposition:     in.Disposition,
		EvidenceSummary: in.EvidenceSummary,
		AcceptedScope: triggersv1alpha1.MaintainerAcceptedScope{
			Statement:          in.AcceptedScope.Statement,
			AcceptanceCriteria: append([]string(nil), in.AcceptedScope.AcceptanceCriteria...),
		},
		CloseReason: in.CloseReason,
	}
	// The controller enforces projection-sequence preconditions; the resource
	// version is advisory and defaults to the currently observed one.
	resourceVersion := strings.TrimSpace(in.ExpectedResourceVersion)
	if resourceVersion == "" {
		resourceVersion = workItem.ResourceVersion
	}
	preconditions := triggersv1alpha1.MaintainerWorkItemCommandPreconditions{
		WorkItemName:       workItem.Name,
		WorkItemUID:        workItem.UID,
		ProjectionSequence: *in.ExpectedProjectionSequence,
		ResourceVersion:    resourceVersion,
	}
	payloadHash := triageIssuePayloadHash(triage, preconditions)
	capability := &corev1.Secret{}
	capabilityName := triggersv1alpha1.MaintainerCommandCapabilitySecretName(current.Name)
	if err := t.k8sClient.Get(ctx, client.ObjectKey{Namespace: current.Namespace, Name: capabilityName}, capability); err != nil {
		return triageIssueError("failed to read maintainer command capability: %v", err)
	}
	if !metav1.IsControlledBy(capability, current) {
		return triageIssueError("maintainer command capability is not owned by the current AgentRun")
	}
	if string(capability.Data[triggersv1alpha1.MaintainerCommandCapabilityRepositoryNameKey]) != repository.Name || string(capability.Data[triggersv1alpha1.MaintainerCommandCapabilityRepositoryUIDKey]) != string(repository.UID) {
		return triageIssueError("maintainer command capability is bound to a different GitHubRepository")
	}
	capabilityKey := capability.Data[triggersv1alpha1.MaintainerCommandCapabilitySecretKey]
	if len(capabilityKey) < 32 {
		return triageIssueError("maintainer command capability is invalid")
	}
	proof := triggersv1alpha1.MaintainerWorkItemCommandProof(capabilityKey, repository.Name, repository.UID, in.IdempotencyKey, payloadHash, current.Name, current.UID)
	command := &triggersv1alpha1.MaintainerWorkItemCommand{
		ObjectMeta: metav1.ObjectMeta{
			Name:      MaintainerWorkItemCommandName(repository.Name, in.IdempotencyKey),
			Namespace: repository.Namespace,
			Labels: map[string]string{
				triggersv1alpha1.MaintainerWorkItemRepositoryLabelKey:  repository.Name,
				triggersv1alpha1.MaintainerWorkItemIssueNumberLabelKey: strconv.Itoa(int(in.IssueNumber)),
			},
			OwnerReferences: []metav1.OwnerReference{*metav1.NewControllerRef(repository, triggersv1alpha1.GroupVersion.WithKind("GitHubRepository"))},
		},
		Spec: triggersv1alpha1.MaintainerWorkItemCommandSpec{
			RepositoryRef:  workItem.Spec.RepositoryRef,
			IdempotencyKey: in.IdempotencyKey,
			PayloadHash:    payloadHash,
			Issuer: &triggersv1alpha1.MaintainerWorkItemCommandIssuer{
				RunName: current.Name,
				UID:     current.UID,
				Proof:   proof,
			},
			Preconditions: preconditions,
			Type:          triggersv1alpha1.MaintainerWorkItemCommandTypeTriageIssue,
			Triage:        triage,
		},
	}
	if err := t.k8sClient.Create(ctx, command); err != nil {
		if !apierrors.IsAlreadyExists(err) {
			return triageIssueError("failed to create triage command: %v", err)
		}
		existing := &triggersv1alpha1.MaintainerWorkItemCommand{}
		if err := t.k8sClient.Get(ctx, client.ObjectKeyFromObject(command), existing); err != nil {
			return triageIssueError("failed to get existing triage command: %v", err)
		}
		if existing.Spec.IdempotencyKey != in.IdempotencyKey || existing.Spec.PayloadHash != payloadHash || existing.Spec.Issuer == nil || existing.Spec.Issuer.UID != current.UID || existing.Spec.Issuer.Proof != proof || existing.Spec.RepositoryRef.Name != workItem.Spec.RepositoryRef.Name {
			return triageIssueError("idempotency payload mismatch for triage command %q", command.Name)
		}
		return t.commandReceipt(ctx, existing, workItem, true)
	}
	return t.commandReceipt(ctx, command, workItem, false)
}

func validateTriageIssueInput(in triageIssueInput) error {
	if in.IssueNumber < 1 {
		return fmt.Errorf("issue_number must be greater than zero")
	}
	switch in.Disposition {
	case triggersv1alpha1.MaintainerWorkItemDispositionNotActionable,
		triggersv1alpha1.MaintainerWorkItemDispositionBounded,
		triggersv1alpha1.MaintainerWorkItemDispositionDecomposable,
		triggersv1alpha1.MaintainerWorkItemDispositionDiscovery,
		triggersv1alpha1.MaintainerWorkItemDispositionEscalated:
	default:
		return fmt.Errorf("disposition must be an accepted MaintainerWorkItemDisposition")
	}
	if strings.TrimSpace(in.EvidenceSummary) == "" {
		return fmt.Errorf("evidence_summary is required")
	}
	if in.AcceptedScope == nil {
		return fmt.Errorf("accepted_scope is required")
	}
	if strings.TrimSpace(in.IdempotencyKey) == "" || len(in.IdempotencyKey) > 128 || !maintainerIdempotencyValid.MatchString(in.IdempotencyKey) {
		return fmt.Errorf("idempotency_key must be a valid non-empty command idempotency key")
	}
	if in.ExpectedProjectionSequence == nil || *in.ExpectedProjectionSequence < 0 {
		return fmt.Errorf("expected_projection_sequence is required and must be non-negative")
	}
	if in.Disposition == triggersv1alpha1.MaintainerWorkItemDispositionNotActionable {
		if in.CloseReason == nil {
			return fmt.Errorf("close_reason is required when disposition is NotActionable")
		}
	} else if in.CloseReason != nil {
		return fmt.Errorf("close_reason is only allowed when disposition is NotActionable")
	}
	if in.CloseReason != nil && *in.CloseReason != triggersv1alpha1.MaintainerWorkItemCloseReasonNotPlanned && *in.CloseReason != triggersv1alpha1.MaintainerWorkItemCloseReasonCompleted {
		return fmt.Errorf("close_reason must be an accepted MaintainerWorkItemCloseReason")
	}
	return nil
}

func triageIssuePayloadHash(triage *triggersv1alpha1.MaintainerTriageCommand, preconditions triggersv1alpha1.MaintainerWorkItemCommandPreconditions) string {
	return triggersv1alpha1.MaintainerWorkItemCommandPayloadHash(triggersv1alpha1.MaintainerWorkItemCommandTypeTriageIssue, triage, preconditions)
}

func triageIssueError(format string, args ...any) (Result, error) {
	return Result{Content: fmt.Sprintf(format, args...), IsError: true}, nil
}

func maintainerWorkItemName(repositoryName string, issueNumber int32) string {
	return triggersv1alpha1.MaintainerWorkItemName(repositoryName, issueNumber)
}

// MaintainerWorkItemCommandName returns the deterministic DNS-safe command name.
func MaintainerWorkItemCommandName(repositoryName, idempotencyKey string) string {
	return triggersv1alpha1.MaintainerWorkItemCommandName(repositoryName, idempotencyKey)
}

package tools

import (
	"context"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"time"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	"github.com/gratefulagents/gratefulagents/internal/orchestration"
	"github.com/gratefulagents/gratefulagents/internal/store"
	"github.com/gratefulagents/sdk/pkg/agentsdk"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
)

const (
	waitConditionPRCreated         = "pr_created"
	waitConditionAwaitingUserInput = "awaiting_user_input"
	waitConditionIdle              = "idle"
	waitConditionTerminal          = "terminal"
	waitConditionBlocked           = "blocked"
)

type waitForRunsTool struct {
	maintainerToolBase
	pollInterval time.Duration
}

type waitForRunsInput struct {
	RunNames       []string `json:"run_names,omitempty"`
	Until          []string `json:"until,omitempty"`
	Match          string   `json:"match,omitempty"`
	TimeoutSeconds int      `json:"timeout_seconds,omitempty"`
}

type waitRunSnapshot struct {
	Name             string                          `json:"name"`
	Phase            platformv1alpha1.AgentRunPhase  `json:"phase,omitempty"`
	ConditionsMet    []string                        `json:"conditions_met"`
	PullRequestURLs  []string                        `json:"pull_request_urls,omitempty"`
	PendingInput     *orchestration.PendingUserInput `json:"pending_input,omitempty"`
	BlockedReason    string                          `json:"blocked_reason,omitempty"`
	NotFoundYet      bool                            `json:"not_found_yet,omitempty"`
	PRAlreadyPresent bool                            `json:"pr_already_present,omitempty"`
}

type waitForRunsOutput struct {
	Satisfied      bool              `json:"satisfied"`
	TimedOut       bool              `json:"timed_out"`
	ElapsedSeconds int               `json:"elapsed_seconds"`
	Runs           []waitRunSnapshot `json:"runs"`
}

func (t *waitForRunsTool) Name() string { return "wait_for_runs" }
func (t *waitForRunsTool) Description() string {
	return "Block while authorized fleet runs reach pull-request, user-input, idle, blocked, or terminal states; newly dispatched named runs may appear after waiting begins."
}
func (t *waitForRunsTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{"type":"object","properties":{"run_names":{"type":"array","items":{"type":"string"}},"until":{"type":"array","items":{"type":"string","enum":["pr_created","awaiting_user_input","idle","terminal","blocked"]}},"match":{"type":"string","enum":["any","all"]},"timeout_seconds":{"type":"integer","minimum":1,"maximum":1800}}}`)
}
func (t *waitForRunsTool) IsReadOnly() bool                      { return true }
func (t *waitForRunsTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }
func (t *waitForRunsTool) NeedsApproval() bool                   { return false }
func (t *waitForRunsTool) TimeoutSeconds() int                   { return 1860 }

func (t *waitForRunsTool) Execute(ctx context.Context, input json.RawMessage, _ string) (Result, error) {
	var in waitForRunsInput
	if err := json.Unmarshal(input, &in); err != nil {
		return Result{Content: fmt.Sprintf("invalid input: %v", err), IsError: true}, nil
	}
	until, err := normalizeWaitConditions(in.Until)
	if err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	match := strings.ToLower(strings.TrimSpace(in.Match))
	if match == "" {
		match = "any"
	}
	if match != "any" && match != "all" {
		return Result{Content: `match must be "any" or "all"`, IsError: true}, nil
	}
	timeout := in.TimeoutSeconds
	if timeout == 0 {
		timeout = 600
	}
	if timeout < 1 || timeout > 1800 {
		return Result{Content: "timeout_seconds must be between 1 and 1800", IsError: true}, nil
	}
	if _, err := t.currentRun(ctx); err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	names := normalizedRunNames(in.RunNames)
	if len(names) == 0 {
		fleet, err := t.fleetRuns(ctx)
		if err != nil {
			return Result{Content: err.Error(), IsError: true}, nil
		}
		for i := range fleet {
			if !maintainerTerminal(fleet[i].Status.Phase) {
				names = append(names, fleet[i].Name)
			}
		}
	}
	baseline := make(map[string]bool, len(names))
	for _, name := range names {
		run, err := t.fleetRun(ctx, name)
		if err == nil {
			baseline[name] = len(waitPullRequestURLs(run)) > 0
			continue
		}
		if !apierrors.IsNotFound(err) {
			return Result{Content: fmt.Sprintf("failed to verify fleet AgentRun %q: %v", name, err), IsError: true}, nil
		}
	}
	started := time.Now()
	interval := t.pollInterval
	if interval <= 0 {
		interval = 10 * time.Second
	}
	for {
		snapshots, satisfied, err := t.waitSnapshots(ctx, names, until, match, baseline)
		if err != nil {
			return Result{Content: err.Error(), IsError: true}, nil
		}
		elapsed := int(time.Since(started).Seconds())
		if satisfied {
			return marshalWaitResult(waitForRunsOutput{Satisfied: true, ElapsedSeconds: elapsed, Runs: snapshots})
		}
		remaining := time.Until(started.Add(time.Duration(timeout) * time.Second))
		if remaining <= 0 {
			return marshalWaitResult(waitForRunsOutput{TimedOut: true, ElapsedSeconds: elapsed, Runs: snapshots})
		}
		if remaining < interval {
			interval = remaining
		}
		select {
		case <-ctx.Done():
			return Result{Content: fmt.Sprintf("wait cancelled: %v", ctx.Err()), IsError: true}, nil
		case <-time.After(interval):
		}
	}
}

func marshalWaitResult(out waitForRunsOutput) (Result, error) {
	encoded, err := json.Marshal(out)
	if err != nil {
		return Result{}, err
	}
	return Result{Content: string(encoded)}, nil
}

func normalizeWaitConditions(conditions []string) (map[string]struct{}, error) {
	if len(conditions) == 0 {
		return map[string]struct{}{waitConditionTerminal: {}}, nil
	}
	out := make(map[string]struct{}, len(conditions))
	for _, condition := range conditions {
		condition = strings.ToLower(strings.TrimSpace(condition))
		switch condition {
		case waitConditionPRCreated, waitConditionAwaitingUserInput, waitConditionIdle, waitConditionTerminal, waitConditionBlocked:
			out[condition] = struct{}{}
		default:
			return nil, fmt.Errorf("until contains unsupported condition %q", condition)
		}
	}
	return out, nil
}

func normalizedRunNames(names []string) []string {
	seen := make(map[string]struct{}, len(names))
	out := make([]string, 0, len(names))
	for _, name := range names {
		name = strings.TrimSpace(name)
		if name == "" {
			continue
		}
		if _, exists := seen[name]; !exists {
			seen[name] = struct{}{}
			out = append(out, name)
		}
	}
	sort.Strings(out)
	return out
}

func (t *waitForRunsTool) waitSnapshots(ctx context.Context, names []string, until map[string]struct{}, match string, baseline map[string]bool) ([]waitRunSnapshot, bool, error) {
	snapshots := make([]waitRunSnapshot, 0, len(names))
	matched := 0
	for _, name := range names {
		run, err := t.fleetRun(ctx, name)
		if apierrors.IsNotFound(err) {
			snapshots = append(snapshots, waitRunSnapshot{Name: name, ConditionsMet: []string{}, NotFoundYet: true})
			continue
		}
		if err != nil {
			return nil, false, fmt.Errorf("failed to verify fleet AgentRun %q: %w", name, err)
		}
		session, err := t.stateStore.GetSessionByRun(ctx, run.Name, run.Namespace)
		if err != nil {
			return nil, false, fmt.Errorf("failed to resolve session for fleet AgentRun %q: %w", name, err)
		}
		met := conditionsMet(run, session, baseline)
		selected := false
		for _, condition := range met {
			if _, ok := until[condition]; ok {
				selected = true
				break
			}
		}
		if selected {
			matched++
		}
		snapshots = append(snapshots, waitRunSnapshot{
			Name: name, Phase: run.Status.Phase, ConditionsMet: met, PullRequestURLs: waitPullRequestURLs(run),
			PendingInput: orchestration.PendingUserInputForSession(session), BlockedReason: maintainerBlockedReason(run),
			PRAlreadyPresent: baseline[name] && len(waitPullRequestURLs(run)) > 0,
		})
	}
	if len(names) == 0 {
		return snapshots, true, nil
	}
	return snapshots, (match == "any" && matched > 0) || (match == "all" && matched == len(names)), nil
}

func conditionsMet(run *platformv1alpha1.AgentRun, session *store.Session, baseline map[string]bool) []string {
	if run == nil {
		return []string{}
	}
	met := make([]string, 0, 5)
	prURLs := waitPullRequestURLs(run)
	if len(prURLs) > 0 || baseline[run.Name] {
		met = append(met, waitConditionPRCreated)
	}
	pending := orchestration.PendingUserInputForSession(session) != nil
	awaitingInput := run.Status.Phase == platformv1alpha1.AgentRunPhaseQuestion || pending
	if awaitingInput {
		met = append(met, waitConditionAwaitingUserInput)
	}
	blocked := run.Status.Phase == platformv1alpha1.AgentRunPhaseBlocked || maintainerBlockedReason(run) != ""
	if blocked {
		met = append(met, waitConditionBlocked)
	}
	terminal := maintainerTerminal(run.Status.Phase)
	if terminal {
		met = append(met, waitConditionTerminal)
	}
	if terminal || blocked || awaitingInput || run.Status.Phase == platformv1alpha1.AgentRunPhasePaused {
		met = append(met, waitConditionIdle)
	}
	return met
}

func waitPullRequestURLs(run *platformv1alpha1.AgentRun) []string {
	if run == nil || run.Status.Artifacts == nil {
		return nil
	}
	urls := append([]string(nil), run.Status.Artifacts.PullRequestURLs...)
	if len(urls) == 0 && run.Status.Artifacts.PullRequestURL != "" {
		urls = append(urls, run.Status.Artifacts.PullRequestURL)
	}
	return urls
}

package tools

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"unicode/utf8"

	platformv1alpha1 "github.com/gratefulagents/gratefulagents/api/platform/v1alpha1"
	"github.com/gratefulagents/sdk/pkg/agentsdk"
	"k8s.io/client-go/util/retry"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

type wakeAgentRunTool struct{ maintainerToolBase }

type wakeAgentRunInput struct {
	RunName      string `json:"run_name"`
	Message      string `json:"message"`
	DeliveryMode string `json:"delivery_mode,omitempty"`
}

type wakeAgentRunOutput struct {
	MessageID     int64  `json:"message_id"`
	DeliveryMode  string `json:"delivery_mode"`
	WakeRequested bool   `json:"wake_requested"`
}

func (t *wakeAgentRunTool) Name() string { return "wake_agent_run" }
func (t *wakeAgentRunTool) Description() string {
	return "Send maintainer context to an authorized implementer fleet run. delivery_mode=steer (default) injects it at the earliest safe in-flight boundary without stopping the turn; delivery_mode=queue waits for the next turn boundary. Use stop_agent_run_turn separately only when the turn itself must end. Returns the durable message id for edit/cancel."
}
func (t *wakeAgentRunTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{"type":"object","properties":{"run_name":{"type":"string"},"message":{"type":"string","maxLength":4000},"delivery_mode":{"type":"string","enum":["steer","queue"],"default":"steer"}},"required":["run_name","message"]}`)
}
func (t *wakeAgentRunTool) IsReadOnly() bool                      { return false }
func (t *wakeAgentRunTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }
func (t *wakeAgentRunTool) NeedsApproval() bool                   { return false }
func (t *wakeAgentRunTool) TimeoutSeconds() int                   { return 0 }

func (t *wakeAgentRunTool) Execute(ctx context.Context, input json.RawMessage, _ string) (Result, error) {
	var in wakeAgentRunInput
	if err := json.Unmarshal(input, &in); err != nil {
		return Result{Content: fmt.Sprintf("invalid input: %v", err), IsError: true}, nil
	}
	name, message := strings.TrimSpace(in.RunName), strings.TrimSpace(in.Message)
	if name == "" || message == "" {
		return Result{Content: "run_name and message are required", IsError: true}, nil
	}
	deliveryMode := strings.ToLower(strings.TrimSpace(in.DeliveryMode))
	if deliveryMode == "" {
		deliveryMode = "steer"
	}
	if deliveryMode != "steer" && deliveryMode != "queue" {
		return Result{Content: "delivery_mode must be steer or queue", IsError: true}, nil
	}
	if utf8.RuneCountInString(message) > 4000 {
		return Result{Content: "message must be at most 4000 characters", IsError: true}, nil
	}
	if _, err := t.currentRun(ctx); err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	run, err := t.fleetRun(ctx, name)
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to verify fleet AgentRun: %v", err), IsError: true}, nil
	}
	if maintainerIsReviewer(run) {
		return Result{Content: "reviewer fleet runs cannot be woken by the maintainer", IsError: true}, nil
	}
	if run.Status.Phase == platformv1alpha1.AgentRunPhaseCancelled {
		return Result{Content: "cancelled AgentRuns cannot be woken", IsError: true}, nil
	}
	session, err := t.stateStore.GetSessionByRun(ctx, run.Name, run.Namespace)
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to resolve fleet session: %v", err), IsError: true}, nil
	}
	if session == nil {
		return Result{Content: "fleet session not found", IsError: true}, nil
	}
	if _, err := t.currentRun(ctx); err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	run, err = t.fleetRun(ctx, name)
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to reverify fleet AgentRun: %v", err), IsError: true}, nil
	}
	if maintainerIsReviewer(run) {
		return Result{Content: "reviewer fleet runs cannot be woken by the maintainer", IsError: true}, nil
	}
	if run.Status.Phase == platformv1alpha1.AgentRunPhaseCancelled {
		return Result{Content: "cancelled AgentRuns cannot be woken", IsError: true}, nil
	}
	storedMode := "immediate"
	if deliveryMode == "queue" {
		storedMode = "enqueue"
	}
	metadata, err := json.Marshal(map[string]string{"mode": storedMode, "source": "maintainer", "maintainer_run": t.currentRunName})
	if err != nil {
		return Result{}, err
	}
	delivered, err := t.stateStore.AppendMessage(ctx, session.ID, "user", "[maintainer] "+message, metadata)
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to deliver maintainer message: %v", err), IsError: true}, nil
	}
	if run.Status.Phase == platformv1alpha1.AgentRunPhaseRunning {
		return wakeAgentRunResult(delivered.ID, deliveryMode, false)
	}
	key := client.ObjectKey{Name: run.Name, Namespace: run.Namespace}
	if err := retry.RetryOnConflict(retry.DefaultRetry, func() error {
		fresh := &platformv1alpha1.AgentRun{}
		if err := t.k8sClient.Get(ctx, key, fresh); err != nil {
			return err
		}
		if !t.isFleetRunForCurrentRepository(ctx, fresh) || maintainerIsReviewer(fresh) {
			return fmt.Errorf("AgentRun %q is no longer an authorized implementer fleet run", name)
		}
		if fresh.Status.Phase == platformv1alpha1.AgentRunPhaseCancelled {
			return fmt.Errorf("cancelled AgentRuns cannot be woken")
		}
		if fresh.Status.Phase == platformv1alpha1.AgentRunPhaseRunning {
			return nil
		}
		patch := client.MergeFromWithOptions(fresh.DeepCopy(), client.MergeFromWithOptimisticLock{})
		fresh.Spec.WakeRequests++
		return t.k8sClient.Patch(ctx, fresh, patch)
	}); err != nil {
		return Result{Content: fmt.Sprintf("maintainer message delivered but wake request failed: %v", err), IsError: true}, nil
	}
	return wakeAgentRunResult(delivered.ID, deliveryMode, true)
}

func wakeAgentRunResult(messageID int64, deliveryMode string, wakeRequested bool) (Result, error) {
	encoded, err := json.Marshal(wakeAgentRunOutput{MessageID: messageID, DeliveryMode: deliveryMode, WakeRequested: wakeRequested})
	if err != nil {
		return Result{}, err
	}
	return Result{Content: string(encoded)}, nil
}

