	return json.RawMessage(`{
		"type": "object",
		"properties": {
			"pr_number": {"type": "integer", "description": "Pull request number in the repository at repo_path."},
			"repo_path": {"type": "string", "description": "` + repoPathSchemaDescription + `"}
		},
		"required": ["pr_number"]
	}`)
}
