	return "Download the log for a GitHub Actions check run. Use a check run ID returned by get_pull_request_checks to diagnose a failing CI job."
}
func (t *getGitHubCheckLogsTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{
		"type": "object",
		"properties": {
			"check_run_id": {"type": "integer", "description": "GitHub Actions check run/job ID, as returned in the id field from get_pull_request_checks."},
			"tail_lines": {"type": "integer", "description": "Number of lines to return from the end of the log (default 1000, maximum 5000)."},
			"repo_path": {"type": "string", "description": "` + repoPathSchemaDescription + `"}
		},
		"required": ["check_run_id"]
	}`)
}
func (t *getGitHubCheckLogsTool) IsReadOnly() bool                      { return true }
func (t *getGitHubCheckLogsTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }
func (t *getGitHubCheckLogsTool) NeedsApproval() bool                   { return false }
func (t *getGitHubCheckLogsTool) TimeoutSeconds() int                   { return 0 }

type getGitHubCheckLogsInput struct {
	CheckRunID int64  `json:"check_run_id"`
	TailLines  int    `json:"tail_lines"`
	RepoPath   string `json:"repo_path"`
}

func (t *getGitHubCheckLogsTool) Execute(ctx context.Context, input json.RawMessage, workDir string) (Result, error) {
	var in getGitHubCheckLogsInput
	if err := json.Unmarshal(input, &in); err != nil {
		return prReviewError("Invalid input: " + err.Error())
	}
	if in.CheckRunID <= 0 {
		return prReviewError("check_run_id must be positive")
	}
	if in.TailLines < 0 || in.TailLines > maxGitHubCheckLogLines {
		return prReviewError(fmt.Sprintf("tail_lines must be between 0 and %d", maxGitHubCheckLogLines))
	}
	if in.TailLines == 0 {
		in.TailLines = defaultGitHubCheckLogLines
	}

	wd, err := t.resolveWorkDir(workDir, in.RepoPath)
	if err != nil {
		return prReviewError("repo_path rejected: " + err.Error())
	}
	runner, ok := t.effectiveRunner().(githubCheckLogRunner)
	if !ok {
		return prReviewError("GitHub check log streaming is unavailable")
	}
	logs, totalLines, truncated, diagnostic, err := runner.RunGHLogTail(ctx, wd, in.TailLines, maxGitHubCheckLogBytes, "run", "view", "--log", "--job", strconv.FormatInt(in.CheckRunID, 10))
	if err != nil {
		return prReviewError(fmt.Sprintf("gh run view job log failed: %s\n%s", err, diagnostic))
	}

	return prReviewSuccess(map[string]any{
		"check_run_id": in.CheckRunID,
		"logs":         logs,
		"total_lines":  totalLines,
		"truncated":    truncated,
	})
}

type logTailWriter struct {
	lineLimit     int
	byteLimit     int
	lines         [][]byte
	current       []byte
	stored        int
	totalLines    int
	truncated     bool
	endedLine     bool
	currentActive bool
	sawData       bool
}

func newLogTailWriter(lineLimit, byteLimit int) *logTailWriter {
	return &logTailWriter{lineLimit: lineLimit, byteLimit: byteLimit}
}

func (w *logTailWriter) Write(p []byte) (int, error) {
	originalLen := len(p)
	if originalLen > 0 {
		w.sawData = true
	}
	for len(p) > 0 {
		newline := bytes.IndexByte(p, '\n')
		if newline < 0 {
			w.appendCurrent(p)
			w.endedLine = false
			break
		}
		w.appendCurrent(p[:newline])
		w.finishLine()
		p = p[newline+1:]
	}
	return originalLen, nil
}

func (w *logTailWriter) activateCurrent() {
	if w.currentActive {
		return
	}
	if len(w.lines) > 0 {
		w.stored++
	}
	w.currentActive = true
	for len(w.lines)+1 > w.lineLimit {
		w.dropOldestLine()
	}
}

func (w *logTailWriter) appendCurrent(p []byte) {
	if len(p) == 0 {
		return
	}
	w.activateCurrent()
	if len(p) >= w.byteLimit {
		w.current = append(w.current[:0], p[len(p)-w.byteLimit:]...)
		w.lines = nil
		w.stored = len(w.current)
		w.truncated = true
		return
	}
	w.current = append(w.current, p...)
	w.stored += len(p)
	w.trimBytes()
}

func (w *logTailWriter) finishLine() {
	w.activateCurrent()
	w.totalLines++
	w.lines = append(w.lines, w.current)
	w.current = nil
	w.currentActive = false
	w.endedLine = true
	for len(w.lines) > w.lineLimit {
		w.dropOldestLine()
	}
	w.trimBytes()
}

func (w *logTailWriter) trimBytes() {
	for w.stored > w.byteLimit && (len(w.lines) > 1 || len(w.lines) == 1 && w.currentActive) {
		w.dropOldestLine()
	}
	if w.stored <= w.byteLimit {
		return
	}
	drop := w.stored - w.byteLimit
	if len(w.lines) == 1 {
		w.lines[0] = append([]byte(nil), w.lines[0][drop:]...)
	} else {
		w.current = append([]byte(nil), w.current[drop:]...)
	}
	w.stored = w.byteLimit
	w.truncated = true
}

func (w *logTailWriter) dropOldestLine() {
	if len(w.lines) == 0 {
		return
	}
	w.stored -= len(w.lines[0])
	w.lines[0] = nil
	w.lines = w.lines[1:]
	if len(w.lines) > 0 || w.currentActive {
		w.stored--
	}
	w.truncated = true
}

func (w *logTailWriter) Result() (string, int, bool) {
	if !w.sawData {
		return "", 0, false
	}
	totalLines := w.totalLines
	parts := w.lines
	if !w.endedLine {
		totalLines++
		parts = append(append([][]byte(nil), parts...), w.current)
	}
	return string(bytes.Join(parts, []byte{'\n'})), totalLines, w.truncated
}

package tools

import (
	"context"
	"encoding/json"
	"io"
	"sort"
	"strings"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
	"github.com/gratefulagents/sdk/pkg/agentsdk/policy"
	sdktools "github.com/gratefulagents/sdk/pkg/agentsdk/tools"
	sdkvision "github.com/gratefulagents/sdk/pkg/agentsdk/tools/vision"
	sdkweb "github.com/gratefulagents/sdk/pkg/agentsdk/tools/web"
)

// Result from tool execution.
type Result = agentsdk.ToolResult

// Tool defines a single tool that can be called by the model.
type Tool = agentsdk.Tool

// ToolDef is a serializable tool definition for the API.
type ToolDef struct {
	Name        string          `json:"name"`
	Description string          `json:"description"`
	InputSchema json.RawMessage `json:"input_schema"`
}

// Registry holds all available tools.
type Registry struct {
	tools                map[string]Tool
	permissionMode       policy.PermissionMode
	signals              bool
	allowMutating        map[string]struct{}
	contextualCandidates map[string]struct{}
	nameFilterAllowed    map[string]struct{}
	nameFilterDenied     map[string]struct{}
	gitRemoteWrites      policy.GitRemoteWrites
	browser              bool
	browserScreenshotDir string
	interactiveTerminal  bool
	asyncShell           bool
	vision               bool
	visionAnalyze        sdkvision.AnalyzeFn
	closers              []io.Closer
}

// RegistryOption configures the registry.
type RegistryOption func(*Registry)

// WithReadOnlyTools restricts the registry to only read-only tools.
func WithReadOnlyTools() RegistryOption {
	return WithPermissionMode(policy.PermissionModeReadOnly)
}

// WithPermissionMode configures the registry's mutability mode.
func WithPermissionMode(mode policy.PermissionMode) RegistryOption {
	return func(r *Registry) { r.permissionMode = policy.NormalizePermissionMode(string(mode)) }
}

// WithGitRemoteWrites configures whether tools and shell commands may mutate
// Git remotes. Disabled mode still permits workspace edits and local commits.
func WithGitRemoteWrites(mode policy.GitRemoteWrites) RegistryOption {
	return func(r *Registry) { r.gitRemoteWrites = policy.NormalizeGitRemoteWrites(mode) }
}

// WithSignalTools enables the AskUserQuestion signal tool.
func WithSignalTools() RegistryOption {
	return func(r *Registry) { r.signals = true }
}

// WithBrowserTools enables the headless browser tool in the registry.
func WithBrowserTools() RegistryOption {
	return func(r *Registry) { r.browser = true }
}

// WithBrowserScreenshotDir configures the host-managed ephemeral directory for
// screenshots whose calls omit output_path. Explicit paths remain relative to
// the registry workspace.
func WithBrowserScreenshotDir(dir string) RegistryOption {
	return func(r *Registry) { r.browserScreenshotDir = strings.TrimSpace(dir) }
}

// WithInteractiveTerminal enables the persistent PTY terminal tool for
// interactive programs (Unix only; requires a write permission mode).
func WithInteractiveTerminal() RegistryOption {
	return func(r *Registry) { r.interactiveTerminal = true }
}

// WithAsyncShellTools registers the SDK's background shell jobs
// (BashStart/BashPoll/BashKill) so long builds and campaigns can outlive the
// Bash tool's per-call timeout. The SDK only registers them in write-capable
// permission modes.
func WithAsyncShellTools() RegistryOption {
	return func(r *Registry) { r.asyncShell = true }
}

// WithVisionTools enables the image analysis tool in the registry. A nil
// analyzer registers the tool shell so the SDK runtime can attach the selected
// provider's vision implementation while building the agent.
func WithVisionTools(analyzeFn func(ctx context.Context, imageData []byte, mimeType, prompt string) (string, error)) RegistryOption {
	return func(r *Registry) {
		r.vision = true
		r.visionAnalyze = sdkvision.AnalyzeFn(analyzeFn)
	}
}

// WithAllowedMutatingTools allows specific non-read-only tools to remain
// available even when the registry permission mode is read-only.
func WithAllowedMutatingTools(names ...string) RegistryOption {
	return func(r *Registry) {
		if r.allowMutating == nil {
			r.allowMutating = make(map[string]struct{}, len(names))
		}
		for _, name := range names {
			if name == "" {
				continue
			}
			r.allowMutating[name] = struct{}{}
		}
	}
}

// WithToolNameFilter narrows the registry by tool name: denied tools are
// dropped, and when the allow list is non-empty every tool not on it is
// dropped too (deny wins over allow). The filter is applied on top of the
// existing permission/mode filtering and can only remove tools, never
// re-enable a tool that mode or profile policy already excluded. Control-flow
// tools (see isRegistryControlFlowTool: finish, save_plan, get_plan,
// RequestMCPBreakGlass) are exempt because the run cannot complete without
// them. Empty and unknown names are ignored.
func WithToolNameFilter(allowed, denied []string) RegistryOption {
	return func(r *Registry) {
		for _, name := range allowed {
			name = strings.TrimSpace(name)
			if name == "" {
				continue
			}
			if r.nameFilterAllowed == nil {
				r.nameFilterAllowed = make(map[string]struct{}, len(allowed))
			}
			r.nameFilterAllowed[name] = struct{}{}
		}
		for _, name := range denied {
			name = strings.TrimSpace(name)
			if name == "" {
				continue
			}
			if r.nameFilterDenied == nil {
				r.nameFilterDenied = make(map[string]struct{}, len(denied))
			}
			r.nameFilterDenied[name] = struct{}{}
		}
	}
}

// SplitToolNameList parses a comma-separated tool name list (the
// AGENTRUN_ALLOWED_TOOLS / AGENTRUN_DENIED_TOOLS env var format), trimming
// whitespace and dropping empty entries and duplicates.
func SplitToolNameList(raw string) []string {
	seen := make(map[string]struct{})
	var names []string
	for part := range strings.SplitSeq(raw, ",") {
		name := strings.TrimSpace(part)
		if name == "" {
			continue
		}
		if _, dup := seen[name]; dup {
			continue
		}
		seen[name] = struct{}{}
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

// WithContextualMutatingToolCandidates retains a narrow set of mutating tool
// candidates in read-only registries. Callers must apply live per-run policy
// and each candidate must enforce contextual authorization during Execute.
func WithContextualMutatingToolCandidates(names ...string) RegistryOption {
	return func(r *Registry) {
		if r.contextualCandidates == nil {
			r.contextualCandidates = make(map[string]struct{}, len(names))
		}
		for _, name := range names {
			if name != "" {
				r.contextualCandidates[name] = struct{}{}
			}
		}
	}
}

// NewRegistry creates a registry with all default tools.
func NewRegistry(workDir string, opts ...RegistryOption) *Registry {
	r := &Registry{
		tools:           make(map[string]Tool),
		permissionMode:  policy.PermissionModeWorkspaceWrite,
		gitRemoteWrites: policy.GitRemoteWritesEnabled,
	}
	for _, opt := range opts {
		opt(r)
	}

	sdkOpts := []sdktools.RegistryOption{
		sdktools.WithPermissionMode(r.permissionMode),
		sdktools.WithGitRemoteWrites(r.gitRemoteWrites),
		// Think scratchpad (SDK v0.0.9): read-only reasoning log between actions.
		sdktools.WithThinkTool(),
	}
	if r.signals {
		sdkOpts = append(sdkOpts, sdktools.WithSignalTools())
	}
	if r.browser {
		// Chromium cannot safely confine redirects, DNS changes, and page
		// subresources to public-only destinations. Enabling Browser is the
		// explicit opt-in to its unrestricted/private networking requirement;
		// the RuntimeProfile egress policy remains the outer boundary.
		sdkOpts = append(sdkOpts,
			sdktools.WithBrowserTools(),
			sdktools.WithBrowserScreenshotDir(r.browserScreenshotDir),
			sdktools.WithPrivateNetworkURLs(true),
		)
	}
	if r.interactiveTerminal {
		sdkOpts = append(sdkOpts, sdktools.WithInteractiveTerminal())
	}
	if r.asyncShell {
		sdkOpts = append(sdkOpts, sdktools.WithAsyncShellTools())
	}
	if r.vision {
		sdkOpts = append(sdkOpts, sdktools.WithVisionTools(r.visionAnalyze))
	}
	if len(r.allowMutating) > 0 {
		names := make([]string, 0, len(r.allowMutating))
		for name := range r.allowMutating {
			names = append(names, name)
		}
		sdkOpts = append(sdkOpts, sdktools.WithAllowedMutatingTools(names...))
	}

	sdkRegistry := sdktools.NewRegistry(workDir, sdkOpts...)
	for _, tool := range sdkRegistry.Tools() {
		// The SDK uses one private-network gate to register Browser, WebFetch,
		// and vision. Browser needs that gate because Chromium cannot enforce
		// destination-by-destination checks, but the URL-based tools can and
		// should retain their public-only default.
		switch typed := tool.(type) {
		case *sdkweb.FetchTool:
			typed.AllowPrivateNetworkURLs = false
		case *sdkvision.Tool:
			typed.AllowPrivateNetworkURLs = false
		}
		r.Register(tool)
	}
	r.closers = sdkRegistry.Closers()

	return r
}

// Closers returns resources (e.g. the PTY terminal manager) that should be
// closed when the agent shuts down.
func (r *Registry) Closers() []io.Closer {
	if r == nil {
		return nil
	}
	return r.closers
}

// Register adds a tool to the registry.
func (r *Registry) Register(t Tool) {
	if t == nil {
		return
	}
	if r.gitRemoteWrites == policy.GitRemoteWritesDisabled && isGitRemoteWriteTool(t) {
		return
	}
	// Control-flow tools are always registered regardless of permission mode.
	// They are needed for phase transitions, finishing, mode switching, etc.
	if !t.IsReadOnly() && !isRegistryControlFlowTool(t.Name()) && !r.permissionMode.AllowsWriteTools() {
		_, allowed := r.allowMutating[t.Name()]
		_, contextualCandidate := r.contextualCandidates[t.Name()]
		if !allowed && !contextualCandidate {
			return
		}
	}
	// Run-level tool name policy (spec.toolPolicy): narrow-only, applied after
	// every other filter so it can drop tools but never restore one. Deny wins
	// over allow; control-flow tools are exempt so the run can still finish.
	if !isRegistryControlFlowTool(t.Name()) {
		if _, denied := r.nameFilterDenied[t.Name()]; denied {
			return
		}
		if len(r.nameFilterAllowed) > 0 {
			if _, ok := r.nameFilterAllowed[t.Name()]; !ok {
				return
			}
		}
	}
	r.tools[t.Name()] = t
}

// Remove unregisters a tool after contextual authorization has narrowed the
// effective mode (for example, controller-cutover maintainer delivery).
func (r *Registry) Remove(name string) {
	if r == nil {
		return
	}
	delete(r.tools, name)
}

// isRegistryControlFlowTool returns true for tools that must always be
// registered regardless of permission mode. These are orchestration tools
// (not data-mutating) that the agent needs to function at all.
func isRegistryControlFlowTool(name string) bool {
	switch name {
	case "finish", "save_plan", "get_plan", "RequestMCPBreakGlass":
		return true
	}
	return false
}

func isGitRemoteWriteTool(tool Tool) bool {
	return sdktools.WritesGitRemote(tool)
}

// Get returns a tool by name, or nil if not found.
func (r *Registry) Get(name string) Tool {
	return r.tools[name]
}

// GetToolDefinitions returns tool definitions for the Anthropic API.
func (r *Registry) GetToolDefinitions() []ToolDef {
	defs := make([]ToolDef, 0, len(r.tools))
	for _, t := range r.tools {
		defs = append(defs, ToolDef{
			Name:        t.Name(),
			Description: t.Description(),
			InputSchema: t.InputSchema(),
		})
	}
	// Sort for stable prompt caching.
	sort.Slice(defs, func(i, j int) bool {
		return defs[i].Name < defs[j].Name
	})
	return defs
}

// Names returns all registered tool names, sorted.
func (r *Registry) Names() []string {
	names := make([]string, 0, len(r.tools))
	for name := range r.tools {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

// Tools returns all registered SDK tools sorted by name.
func (r *Registry) Tools() []agentsdk.Tool {
	names := r.Names()
	out := make([]agentsdk.Tool, 0, len(names))
	for _, name := range names {
		if tool := r.Get(name); tool != nil {
			out = append(out, tool)
		}
	}
	return out
}

// ToolSummaries returns a formatted string of tool names and descriptions,
// excluding basic tools (bash, read, write, edit) whose behavior is self-evident.
// This is included in the system prompt so the agent knows what tools are available
// and what each one does — critical when conversation resets across mode transitions.
func (r *Registry) ToolSummaries() string {
	skipTools := map[string]bool{
		"bash": true, "read": true, "write": true, "edit": true,
		"list_directory": true,
	}
	type entry struct {
		name string
		desc string
	}
	var entries []entry
	for name, tool := range r.tools {
		if skipTools[name] {
			continue
		}
		desc := tool.Description()
		if desc == "" {
			continue
		}
		// Truncate long descriptions.
		if len(desc) > 200 {
			desc = desc[:197] + "..."
		}
		entries = append(entries, entry{name, desc})
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].name < entries[j].name })
	var lines []string
	for _, e := range entries {
		lines = append(lines, "- **"+e.name+"**: "+e.desc)
	}
	if len(lines) == 0 {
		return ""
	}
	return strings.Join(lines, "\n")
}

// PermissionMode returns the resolved registry permission mode.
func (r *Registry) PermissionMode() policy.PermissionMode {
	if r == nil {
		return policy.PermissionModeWorkspaceWrite
	}
	return policy.NormalizePermissionMode(string(r.permissionMode))
}

