func (t *getSecurityPoCTool) Execute(ctx context.Context, _ json.RawMessage, _ string) (Result, error) {
	finding, err := boundSecurityFinding(ctx, t.state)
	if err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
