}

func (t *getSecurityFindingTool) Name() string { return "get_security_finding" }

func (t *getSecurityFindingTool) Description() string {
	return "Get one security finding from the current scan by fingerprint or id, including its full " +
		"description, evidence, attack path, impact, remediation, provenance, status, and audit events. Read-only."
}

func (t *getSecurityFindingTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{
		"type": "object",
		"properties": {
			"fingerprint": {"type": "string", "description": "Fingerprint returned by report_security_finding or list_security_findings"},
			"id": {"type": "string", "description": "Finding UUID, as an alternative to fingerprint"}
		},
		"oneOf": [
			{"required": ["fingerprint"]},
			{"required": ["id"]}
		]
	}`)
}

func (t *getSecurityFindingTool) IsReadOnly() bool                      { return true }
func (t *getSecurityFindingTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }
func (t *getSecurityFindingTool) NeedsApproval() bool                   { return false }
func (t *getSecurityFindingTool) TimeoutSeconds() int                   { return 0 }

func (t *getSecurityFindingTool) Execute(ctx context.Context, input json.RawMessage, _ string) (Result, error) {
	var in getSecurityFindingInput
	if err := json.Unmarshal(input, &in); err != nil {
		return Result{Content: fmt.Sprintf("invalid input: %v", err), IsError: true}, nil
	}
	rec, err := t.state.resolveFinding(ctx, strings.TrimSpace(in.ID), strings.TrimSpace(in.Fingerprint))
	if err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}

	events, err := t.state.listFindingEvents(ctx, rec.ID, 1000)
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to list finding audit events: %v", err), IsError: true}, nil
	}
	out := getSecurityFindingOutput{
		ID:          rec.ID.String(),
		Status:      rec.Status,
		Occurrences: rec.Occurrences,
		Finding:     securityFindingFromRecord(*rec),
		Events:      make([]getSecurityFindingEventOutput, 0, len(events)),
	}
	for _, event := range events {
		out.Events = append(out.Events, getSecurityFindingEventOutput{
			Type: event.EventType, Actor: event.Actor, Note: event.Note,
			Detail: event.Detail, CreatedAt: event.CreatedAt,
		})
	}
	encoded, err := json.MarshalIndent(out, "", "  ")
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to encode finding: %v", err), IsError: true}, nil
	}
	return Result{Content: string(encoded)}, nil
}

// --- update_security_finding ---

type updateSecurityFindingTool struct {
	state *securityScanState
}

type updateSecurityFindingInput struct {
	ID                string `json:"id"`
	Fingerprint       string `json:"fingerprint"`
	Status            string `json:"status"`
	DuplicateOf       string `json:"duplicate_of"`
	PolicyCheck       string `json:"policy_check"`
	PolicyDisposition string `json:"policy_disposition"`
	Note              string `json:"note"`
}

var securityPolicyDispositions = map[string]bool{
	"accepted": true, "disproved": true, "scope_excluded": true,
	"scope_eligible": true, "known_issue": true, "bot_findable": true,
	"fixed_release": true, "novel": true, "not_ready": true,
	"reproduced": true, "not_reproduced": true,
	store.SecurityFindingPolicyDispositionUnreproducibleEnv: true,
}

var securityPolicyChecks = map[string]bool{
	"scope": true, "prior_art": true, "bounty": true, "reproduction": true,
}

func (t *updateSecurityFindingTool) Name() string { return "update_security_finding" }

func (t *updateSecurityFindingTool) Description() string {
	return "Set the status of a security finding recorded by this scan with an audit note: " +
		"confirmed (you built a PoC or proved exploitability), false_positive (you disproved " +
		"it), triaged, fixed, or open. accepted_risk is a human decision recorded from the " +
		"dashboard and cannot be set here. When the stored PoC could not run because of the " +
		"environment (build failure, missing toolchain, unconfigured fork endpoint), keep the " +
		"status triaged and record policy_check reproduction with policy_disposition " +
		"unreproducible_env. Identify the finding by the fingerprint " +
		"returned from report_security_finding / list_security_findings (or its id). Only " +
		"findings belonging to this scan can be updated; the audit trail records this run as " +
		"the actor. When the finding describes the same root cause as another finding in this " +
		"scan (e.g. found by a parallel task), pass duplicate_of with the canonical finding's " +
		"fingerprint or id instead of marking it false_positive: false_positive means the issue " +
		"was disproved, and misusing it corrupts false-positive statistics. Only updates " +
		"platform scan state; safe on read-only scan runs."
}

func (t *updateSecurityFindingTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{
		"type": "object",
		"properties": {
			"fingerprint": {"type": "string", "description": "Fingerprint of the finding to update"},
			"id": {"type": "string", "description": "Finding UUID, as an alternative to fingerprint"},
			"status": {"type": "string", "enum": ["open", "triaged", "confirmed", "false_positive", "fixed"], "description": "New status; accepted_risk is reserved for human reviewers"},
			"duplicate_of": {"type": "string", "description": "Fingerprint or UUID of the canonical finding in this scan that this finding duplicates (same root cause). Use this instead of status false_positive for duplicates; the canonical finding must not itself be a duplicate"},
			"policy_check": {"type": "string", "enum": ["scope", "prior_art", "bounty", "reproduction"], "description": "Policy check that produced policy_disposition; required with a disposition so independent decisions can be resolved safely"},
			"policy_disposition": {"type": "string", "enum": ["accepted", "disproved", "scope_excluded", "scope_eligible", "known_issue", "bot_findable", "fixed_release", "novel", "not_ready", "reproduced", "not_reproduced", "unreproducible_env"], "description": "Optional machine-readable program-policy outcome, independent of technical status. unreproducible_env (checks bounty and reproduction) means the environment prevented running the PoC; the finding stays actionable and the step is retried"},
			"note": {"type": "string", "description": "Why the status changed, e.g. the PoC that confirmed it or the reasoning that disproved it"}
		},
		"required": ["note"],
		"anyOf": [{"required": ["status"]}, {"required": ["duplicate_of"]}]
	}`)
}

func (t *updateSecurityFindingTool) IsReadOnly() bool                      { return true }
func (t *updateSecurityFindingTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }
func (t *updateSecurityFindingTool) NeedsApproval() bool                   { return false }
func (t *updateSecurityFindingTool) TimeoutSeconds() int                   { return 0 }

func (t *updateSecurityFindingTool) Execute(ctx context.Context, input json.RawMessage, _ string) (Result, error) {
	var in updateSecurityFindingInput
	if err := json.Unmarshal(input, &in); err != nil {
		return Result{Content: fmt.Sprintf("invalid input: %v", err), IsError: true}, nil
	}
	status := strings.ToLower(strings.TrimSpace(in.Status))
	duplicateOf := strings.TrimSpace(in.DuplicateOf)
	if status == "" && duplicateOf == "" {
		return Result{Content: "either status or duplicate_of is required", IsError: true}, nil
	}
	if status == store.SecurityFindingStatusAcceptedRisk {
		return Result{Content: "accepted_risk is a human decision recorded from the dashboard; keep the finding triaged and explain in note", IsError: true}, nil
	}
	if status != "" && !store.ValidSecurityFindingStatus(status) {
		return Result{Content: fmt.Sprintf("invalid status %q (valid: %s, %s, %s, %s, %s)",
			in.Status,
			store.SecurityFindingStatusOpen, store.SecurityFindingStatusTriaged,
			store.SecurityFindingStatusConfirmed, store.SecurityFindingStatusFalsePositive,
			store.SecurityFindingStatusFixed), IsError: true}, nil
	}
	note := strings.TrimSpace(in.Note)
	if note == "" {
		return Result{Content: "note is required: explain why the status changed", IsError: true}, nil
	}
	rec, err := t.state.resolveFinding(ctx, strings.TrimSpace(in.ID), strings.TrimSpace(in.Fingerprint))
	if err != nil {
		return Result{Content: err.Error(), IsError: true}, nil
	}
	if status != "" && t.state.scanCtx.PostScriptFingerprint != "" &&
		(rec.Status == store.SecurityFindingStatusFalsePositive || rec.Status == store.SecurityFindingStatusAcceptedRisk || rec.Status == store.SecurityFindingStatusFixed) && status != rec.Status {
		return Result{Content: fmt.Sprintf("terminal finding status %s is preserved during finding post-processing", rec.Status), IsError: true}, nil
	}
	var canonical *store.SecurityFindingRecord
	if duplicateOf != "" {
		canonical, err = t.state.resolveDuplicateCanonical(ctx, rec, duplicateOf)
		if err != nil {
			return Result{Content: err.Error(), IsError: true}, nil
		}
	}
	disposition := strings.ToLower(strings.TrimSpace(in.PolicyDisposition))
	if disposition != "" {
		if !securityPolicyDispositions[disposition] {
			return Result{Content: fmt.Sprintf("invalid policy_disposition %q", in.PolicyDisposition), IsError: true}, nil
		}
		check := strings.ToLower(strings.TrimSpace(in.PolicyCheck))
		if !securityPolicyChecks[check] {
			return Result{Content: "policy_check must be scope, prior_art, bounty, or reproduction when policy_disposition is set", IsError: true}, nil
		}
		if !store.ValidSecurityFindingPolicyDecision(check, disposition) {
			return Result{Content: fmt.Sprintf("policy_disposition %q is not valid for policy_check %q", disposition, check), IsError: true}, nil
		}
		policyStore, ok := t.state.findingStore.(store.SecurityFindingPolicyStore)
		if !ok {
			return Result{Content: "finding store does not support durable policy dispositions", IsError: true}, nil
		}
		if _, err := policyStore.RecordSecurityFindingPolicyDisposition(ctx, rec.Namespace, rec.ID, t.state.scanCtx.RunName, t.state.scanCtx.ExecutionID, check, disposition, note); err != nil {
			return Result{Content: fmt.Sprintf("failed to record policy disposition: %v", err), IsError: true}, nil
		}
	}
	result := fmt.Sprintf("Finding %s", rec.ID)
	if status != "" {
		if err := t.state.setFindingStatus(ctx, rec.ID, status, note); err != nil {
			if errors.Is(err, store.ErrSecurityFindingNotFound) {
				return Result{Content: fmt.Sprintf("no finding with id %s in this scan (use list_security_findings to see recorded findings)", rec.ID), IsError: true}, nil
			}
			return Result{Content: fmt.Sprintf("failed to update finding: %v", err), IsError: true}, nil
		}
		result += fmt.Sprintf(" status set to %s.", status)
	}
	if canonical != nil {
		if err := t.state.markFindingDuplicate(ctx, rec.ID, canonical.ID, note); err != nil {
			return Result{Content: fmt.Sprintf("failed to mark finding duplicate: %v", err), IsError: true}, nil
		}
		if status == "" {
			result += fmt.Sprintf(" marked duplicate of %s (%s).", canonical.Fingerprint, canonical.ID)
		} else {
			result += fmt.Sprintf(" Marked duplicate of %s (%s).", canonical.Fingerprint, canonical.ID)
		}
	}
	if disposition != "" {
		result += " Policy disposition recorded as " + disposition + "."
	}
	return Result{Content: result}, nil
}

// resolveDuplicateCanonical resolves the canonical finding for a duplicate
// mark: it must be a different finding of this scan that is not itself a
// duplicate, so duplicate chains cannot form.
func (s *securityScanState) resolveDuplicateCanonical(ctx context.Context, rec *store.SecurityFindingRecord, ref string) (*store.SecurityFindingRecord, error) {
	var canonical *store.SecurityFindingRecord
	var err error
	if _, parseErr := uuid.Parse(ref); parseErr == nil {
		canonical, err = s.resolveFinding(ctx, ref, "")
	} else {
		canonical, err = s.resolveFinding(ctx, "", ref)
	}
	if err != nil {
		return nil, fmt.Errorf("duplicate_of: %v", err)
	}
	if canonical.ID == rec.ID {
		return nil, fmt.Errorf("duplicate_of: finding %s cannot be a duplicate of itself", rec.ID)
	}
	if canonical.DuplicateOf != nil {
		return nil, fmt.Errorf("duplicate_of: canonical finding %s is itself a duplicate of %s; point at that finding instead", canonical.Fingerprint, *canonical.DuplicateOf)
	}
	if rec.DuplicateOf != nil && *rec.DuplicateOf != canonical.ID {
		return nil, fmt.Errorf("finding %s is already a duplicate of %s", rec.ID, *rec.DuplicateOf)
	}
	return canonical, nil
}

// markFindingDuplicate links a finding to its canonical sibling and records a
// marked_duplicate event; the audit actor is always this run's name.
func (s *securityScanState) markFindingDuplicate(ctx context.Context, id, canonicalID uuid.UUID, note string) error {
	actor := s.scanCtx.RunName
	if s.findingStore != nil {
		dupStore, ok := s.findingStore.(store.SecurityFindingDuplicateStore)
		if !ok {
			return fmt.Errorf("finding store does not support duplicate marks")
		}
		return dupStore.MarkSecurityFindingDuplicate(ctx, s.scanCtx.Namespace, id, canonicalID, actor, note)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	var canonicalFingerprint string
	for _, rec := range s.mem {
		if rec.ID == canonicalID {
			canonicalFingerprint = rec.Fingerprint
		}
	}
	for _, rec := range s.mem {
		if rec.ID != id {
			continue
		}
		canonical := canonicalID
		rec.DuplicateOf = &canonical
		detail, _ := json.Marshal(map[string]string{"canonical_id": canonicalID.String(), "canonical_fingerprint": canonicalFingerprint})
		s.memEvents = append(s.memEvents, store.SecurityFindingEvent{
			FindingID: id,
			EventType: "marked_duplicate",
			Actor:     actor,
			Note:      note,
			Detail:    detail,
			CreatedAt: time.Now().UTC(),
		})
		return nil
	}
	return store.ErrSecurityFindingNotFound
}

// --- ingest_scanner_results ---

type ingestScannerResultsTool struct {
	state *securityScanState
}

// Batch bounds for one ingest_scanner_results call: a hard record cap and a
// hard payload-size cap so a scanner dump cannot balloon a single tool call.
const (
	maxScannerBatchRecords = 500
	maxScannerBatchBytes   = 4 << 20 // 4 MiB
)

type ingestScannerResultsInput struct {
	Records []security.ScannerRecord `json:"records"`
}

// scannerFindingRaw builds the finding's raw JSON payload: the normalized
// finding plus the original scanner record preserved verbatim except for
// secret redaction. securityFindingFromRecord ignores the extra key.
type scannerFindingRaw struct {
	security.Finding
	ScannerRecord security.ScannerRecord `json:"scanner_record"`
}

func (t *ingestScannerResultsTool) Name() string { return "ingest_scanner_results" }

func (t *ingestScannerResultsTool) Description() string {
	return fmt.Sprintf("Ingest a batch of results from a deterministic scanner tool (semgrep, gosec, "+
		"trivy, ...) you ran in the workspace, normalized into the scanner record contract. "+
		"At most %d records (and %d bytes of input) per call; split larger outputs into "+
		"multiple calls. The whole batch is rejected with per-record errors when any record "+
		"is invalid. Accepted records are normalized, secret-redacted, persisted with "+
		"scanner provenance (tool, version, rule id), deduplicated by deterministic "+
		"fingerprint so re-running the same tool converges, and automatically correlated "+
		"with agent findings at the same location — correlation cross-references both "+
		"findings without merging them, so use it to prioritize validation rather than "+
		"trusting either source alone. The scanned repository and revision are stamped from "+
		"the scan configuration. Only records platform scan state; safe on read-only scan runs.",
		maxScannerBatchRecords, maxScannerBatchBytes)
}

func (t *ingestScannerResultsTool) InputSchema() json.RawMessage {
	return json.RawMessage(fmt.Sprintf(`{
		"type": "object",
		"properties": {
			"records": {
				"type": "array",
				"minItems": 1,
				"maxItems": %d,
				"description": "Scanner results normalized into the canonical scanner record contract",
				"items": {
					"type": "object",
					"additionalProperties": false,
					"required": ["tool", "rule_id", "message", "severity", "file_path"],
					"properties": {
						"tool": {"type": "string", "description": "Scanner name, e.g. gosec"},
						"tool_version": {"type": "string", "description": "Scanner version, e.g. 2.18.2"},
						"rule_id": {"type": "string", "description": "The tool's rule identifier, e.g. G401"},
						"rule_name": {"type": "string", "description": "Human-readable rule name"},
						"message": {"type": "string", "description": "The tool's finding message"},
						"severity": {"type": "string", "description": "The tool's severity (ERROR, WARNING, HIGH, moderate, ...); mapped onto critical/high/medium/low/info"},
						"category": {"type": "string", "description": "Optional platform category; derived from cwe when omitted"},
						"file_path": {"type": "string", "description": "Repository-relative path, forward slashes"},
						"start_line": {"type": "integer", "minimum": 0, "description": "First matched line (1-based, 0 = unknown)"},
						"end_line": {"type": "integer", "minimum": 0, "description": "Last matched line (1-based, 0 = unknown)"},
						"symbol": {"type": "string", "description": "Enclosing function/method/symbol when the tool reports one"},
						"cwe": {"type": "string", "description": "CWE identifier, e.g. CWE-798"},
						"references": {"type": "array", "items": {"type": "string"}, "description": "Rule documentation / advisory URLs"},
						"raw_evidence": {"type": "string", "description": "Verbatim matched snippet (secret-redacted before storage)"},
						"extra": {"type": "object", "additionalProperties": {"type": "string"}, "description": "Tool-specific metadata preserved in the raw payload"}
					}
				}
			}
		},
		"required": ["records"]
	}`, maxScannerBatchRecords))
}

func (t *ingestScannerResultsTool) IsReadOnly() bool                      { return true }
func (t *ingestScannerResultsTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }
func (t *ingestScannerResultsTool) NeedsApproval() bool                   { return false }
func (t *ingestScannerResultsTool) TimeoutSeconds() int                   { return 0 }

func (t *ingestScannerResultsTool) Execute(ctx context.Context, input json.RawMessage, _ string) (Result, error) {
	if len(input) > maxScannerBatchBytes {
		return Result{Content: fmt.Sprintf("input is %d bytes, exceeding the %d byte batch limit; split the scanner output into smaller batches", len(input), maxScannerBatchBytes), IsError: true}, nil
	}
	var in ingestScannerResultsInput
	dec := json.NewDecoder(bytes.NewReader(input))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&in); err != nil {
		return Result{Content: fmt.Sprintf("invalid input: %v (see the tool schema for the scanner record contract)", err), IsError: true}, nil
	}
	if len(in.Records) == 0 {
		return Result{Content: "records is required: supply at least one scanner record", IsError: true}, nil
	}
	if len(in.Records) > maxScannerBatchRecords {
		return Result{Content: fmt.Sprintf("%d records exceed the %d record batch limit; split the scanner output into smaller batches", len(in.Records), maxScannerBatchRecords), IsError: true}, nil
	}

	scanCtx := t.state.scanCtx
	findings := make([]security.Finding, len(in.Records))
	var problems []string
	for i, rec := range in.Records {
		// Repository and revision are stamped from the scan context (they
		// are part of the finding identity), exactly like agent findings.
		f, err := security.NormalizeScannerRecord(rec, scanCtx.Repository, scanCtx.Revision)
		if err != nil {
			problems = append(problems, fmt.Sprintf("records[%d]: %v", i, err))
			continue
		}
		f.SourceAgent = scanCtx.RunName
		findings[i] = f
	}
	if len(problems) > 0 {
		return Result{Content: fmt.Sprintf("batch rejected, no records ingested; fix these records and resubmit:\n%s", strings.Join(problems, "\n")), IsError: true}, nil
	}

	scanID, err := t.state.ensureScan(ctx)
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to open the scan record: %v", err), IsError: true}, nil
	}
	created, merged, stoppedAt, err := ingestNormalizedScannerFindings(ctx, t.state, scanID, findings, in.Records)
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to persist scanner finding (records[%d]): %v", stoppedAt, err), IsError: true}, nil
	}
	tools := map[string]bool{}
	for _, f := range findings {
		tools[f.Tool] = true
	}

	correlated, err := t.state.correlateScanFindings(ctx)
	if err != nil {
		return Result{Content: fmt.Sprintf("scanner findings ingested (%d new, %d merged) but correlation failed: %v", created, merged, err), IsError: true}, nil
	}

	toolNames := make([]string, 0, len(tools))
	for name := range tools {
		toolNames = append(toolNames, name)
	}
	sort.Strings(toolNames)
	var b strings.Builder
	fmt.Fprintf(&b, "Ingested %d scanner record(s) from %s: %d new finding(s), %d merged into existing findings by fingerprint.",
		len(in.Records), strings.Join(toolNames, ", "), created, merged)
	if correlated > 0 {
		fmt.Fprintf(&b, "\n%d new agent↔scanner correlation(s) recorded; use list_security_findings and validate correlated findings first.", correlated)
	}
	return Result{Content: b.String()}, nil
}

// ingestNormalizedScannerFindings persists normalized scanner findings,
// preserving each original record (minus secrets) in the raw payload. It
// stops at the first failure and returns the index it stopped at.
func ingestNormalizedScannerFindings(ctx context.Context, state *securityScanState, scanID uuid.UUID, findings []security.Finding, records []security.ScannerRecord) (created, merged, stoppedAt int, err error) {
	for i, f := range findings {
		rec := securityFindingRecord(f, state.scanCtx, state.sessionIDPtr())
		rec.ScanID = scanID
		if raw, marshalErr := json.Marshal(scannerFindingRaw{Finding: f, ScannerRecord: records[i].Redacted()}); marshalErr == nil {
			rec.Raw = raw
		}
		_, isNew, upsertErr := state.upsertFinding(ctx, rec)
		if upsertErr != nil {
			return created, merged, i, upsertErr
		}
		if isNew {
			created++
		} else {
			merged++
		}
	}
	return created, merged, len(findings), nil
}

// --- submit_security_scan_report ---

type submitSecurityScanReportTool struct {
	state *securityScanState
}

type submitSecurityScanReportInput struct {
	Summary     string `json:"summary"`
	RankerRules string `json:"ranker_rules"`
	MinSeverity string `json:"min_severity"`
}

func (t *submitSecurityScanReportTool) Name() string { return "submit_security_scan_report" }

func (t *submitSecurityScanReportTool) Description() string {
	return "Finalize this security scan: deduplicate and rank all recorded findings, render " +
		"the markdown report and SARIF output as session artifacts, and mark the scan " +
		"completed with a severity breakdown. The scan's configured minimum severity and " +
		"dedupe policy are always enforced, and findings that are no longer actionable — " +
		"triaged as false positive, accepted risk, or fixed, collapsed as duplicates, or " +
		"suppressed by policy — are left out of the report and SARIF (their stored rows " +
		"are kept). Call this exactly " +
		"once, after every finding " +
		"has been reported and triaged; calling it again returns the existing result " +
		"unless the findings changed. Only writes platform scan state (no workspace, " +
		"repository, or network mutation), so it is available on read-only scan runs."
}

func (t *submitSecurityScanReportTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{
		"type": "object",
		"properties": {
			"summary": {"type": "string", "description": "One-paragraph executive summary of the scan outcome"},
			"ranker_rules": {"type": "string", "description": "Optional ranker rules text (severity-floor:, severity-ceiling:, exclude:, min-severity:, weight: directives plus prose)"},
			"min_severity": {"type": "string", "enum": ["critical", "high", "medium", "low", "info"], "description": "Drop findings below this severity from the report; the scan's configured minimum severity still applies when stricter"}
		},
		"required": ["summary"]
	}`)
}

func (t *submitSecurityScanReportTool) IsReadOnly() bool                      { return true }
func (t *submitSecurityScanReportTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }
func (t *submitSecurityScanReportTool) NeedsApproval() bool                   { return false }
func (t *submitSecurityScanReportTool) TimeoutSeconds() int                   { return 0 }

// securityCountsEqual reports whether two summary maps hold the same counts,
// treating missing keys as zero.
func securityCountsEqual(a, b map[string]int32) bool {
	for k, v := range a {
		if b[k] != v {
			return false
		}
	}
	for k, v := range b {
		if a[k] != v {
			return false
		}
	}
	return true
}

func securitySeverityBreakdown(b *strings.Builder, counts map[string]int32) {
	b.WriteString("Severity breakdown:\n")
	for _, sev := range security.Severities {
		fmt.Fprintf(b, "  %-8s %d\n", sev, counts[sev])
	}
	fmt.Fprintf(b, "  total    %d\n", counts["total"])
}

// submitScanPolicy resolves the effective ranking rules and the human-readable
// policy note for a report submission. Scan policy from the SecurityScan CRD
// (via run annotations) always applies: the dedupe threshold comes from the
// scan, and the effective minimum severity is the stricter of the scan's and
// the model's.
func submitScanPolicy(in submitSecurityScanReportInput, scanCtx SecurityScanContext, dedupeDesc string) (security.RankRules, string) {
	rules := security.ParseRankRules(in.RankerRules)
	minSource := "ranker rules"
	if modelMin := strings.ToLower(strings.TrimSpace(in.MinSeverity)); modelMin != "" {
		rules.MinSeverity = modelMin
		minSource = "tool input"
	}
	if scanCtx.MinSeverity != "" && security.SeverityRank(scanCtx.MinSeverity) > security.SeverityRank(rules.MinSeverity) {
		rules.MinSeverity = scanCtx.MinSeverity
		minSource = "scan policy"
	}
	minDesc := "no minimum severity"
	if rules.MinSeverity != "" {
		minDesc = fmt.Sprintf("minimum severity %s from %s", rules.MinSeverity, minSource)
	}
	return rules, fmt.Sprintf("Policy applied: %s; %s.", minDesc, dedupeDesc)
}

// Exclusion reasons reported in the submit policy note, in the order they
// are rendered.
var securityReportExclusionReasons = []string{
	store.SecurityFindingStatusFalsePositive,
	store.SecurityFindingStatusAcceptedRisk,
	store.SecurityFindingStatusFixed,
	"duplicate",
	"suppressed",
}

var securityReportExclusionLabels = map[string]string{
	store.SecurityFindingStatusFalsePositive: "%d finding(s) triaged as false positives",
	store.SecurityFindingStatusAcceptedRisk:  "%d finding(s) triaged as accepted risk",
	store.SecurityFindingStatusFixed:         "%d finding(s) triaged as fixed",
	"duplicate":                              "%d finding(s) collapsed as duplicates",
	"suppressed":                             "%d governed-suppressed finding(s)",
}

// securityReportExclusionReason returns why a stored finding must not reach
// the report, or "" when it is report-eligible.
func securityReportExclusionReason(rec store.SecurityFindingRecord) string {
	switch {
	case rec.DuplicateOf != nil:
		return "duplicate"
	case rec.SuppressedBy != "":
		return "suppressed"
	case rec.Status == store.SecurityFindingStatusFalsePositive,
		rec.Status == store.SecurityFindingStatusAcceptedRisk,
		rec.Status == store.SecurityFindingStatusFixed:
		return rec.Status
	}
	return ""
}

// securityExclusionNote renders the per-reason exclusion counts for the
// policy note, so the operator can tell a quiet report from a triaged one.
func securityExclusionNote(excluded map[string]int) string {
	var parts []string
	for _, reason := range securityReportExclusionReasons {
		if n := excluded[reason]; n > 0 {
			parts = append(parts, fmt.Sprintf(securityReportExclusionLabels[reason], n))
		}
	}
	if len(parts) == 0 {
		return ""
	}
	return strings.Join(parts, ", ") + " were excluded from the report"
}

// dedupeSubmittedFindings collapses findings per the scan's dedupe policy and
// returns the canonical findings, the cluster count, and a policy description.
func dedupeSubmittedFindings(findings []security.Finding, scanCtx SecurityScanContext) ([]security.Finding, int, string) {
	if scanCtx.DedupePermille == 0 {
		return findings, len(findings), "dedupe disabled by scan policy"
	}
	threshold := float64(0)
	desc := "default dedupe threshold"
	if scanCtx.DedupePermille > 0 {
		threshold = float64(scanCtx.DedupePermille) / 1000
		desc = fmt.Sprintf("dedupe threshold %.3f from scan policy", threshold)
	}
	clusters := security.Dedupe(findings, threshold)
	canonical := make([]security.Finding, 0, len(clusters))
	for _, c := range clusters {
		canonical = append(canonical, c.Canonical)
	}
	return canonical, len(clusters), desc
}

// alreadyFinalizedResult renders the response for a repeat submit whose
// findings are unchanged since the scan was completed.
func alreadyFinalizedResult(scanName, priorSummary, policyNote string, counts map[string]int32) Result {
	var b strings.Builder
	fmt.Fprintf(&b, "Security scan %q was already finalized and the findings are unchanged; keeping the existing report and completion time.\n", scanName)
	fmt.Fprintf(&b, "Existing summary: %s\n", priorSummary)
	securitySeverityBreakdown(&b, counts)
	b.WriteString(policyNote)
	return Result{Content: b.String()}
}

// loadPriorScanState fetches the prior scan record and current finding counts
// from the persistent store, returning a non-nil done Result when the scan was
// already finalized with unchanged findings.
func (t *submitSecurityScanReportTool) loadPriorScanState(ctx context.Context, policyNote string) (priorScan *store.SecurityScanRecord, counts map[string]int32, done *Result, err error) {
	scanCtx := t.state.scanCtx
	if _, err := t.state.ensureScan(ctx); err != nil {
		return nil, nil, nil, fmt.Errorf("failed to open the scan record: %v", err)
	}
	priorScan, err = t.state.findingStore.GetSecurityScan(ctx, scanCtx.Namespace, scanCtx.RecordKey())
	if err != nil {
		return nil, nil, nil, fmt.Errorf("failed to load scan record: %v", err)
	}
	counts, err = t.state.findingStore.SummarizeSecurityFindingsScoped(ctx, t.state.scopeSummary(false))
	if err != nil {
		return nil, nil, nil, fmt.Errorf("failed to summarize findings: %v", err)
	}
	if priorScan != nil && priorScan.Status == "completed" && securityCountsEqual(counts, priorScan.Counts) {
		res := alreadyFinalizedResult(scanCtx.ScanName, priorScan.Summary, policyNote, priorScan.Counts)
		return priorScan, counts, &res, nil
	}
	return priorScan, counts, nil, nil
}

func (t *submitSecurityScanReportTool) Execute(ctx context.Context, input json.RawMessage, _ string) (Result, error) {
	var in submitSecurityScanReportInput
	if err := json.Unmarshal(input, &in); err != nil {
		return Result{Content: fmt.Sprintf("invalid input: %v", err), IsError: true}, nil
	}
	summary := strings.TrimSpace(in.Summary)
	if summary == "" {
		return Result{Content: "summary is required", IsError: true}, nil
	}

	scanCtx := t.state.scanCtx
	filter := t.state.scopeFilter()
	filter.IncludeDuplicates = true
	filter.Suppressed = store.SecuritySuppressedInclude
	records, truncated, err := t.state.listAllFindings(ctx, filter)
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to load findings: %v", err), IsError: true}, nil
	}
	findings := make([]security.Finding, 0, len(records))
	excluded := map[string]int{}
	for _, rec := range records {
		// Report-ineligible findings are never deleted (the store keeps
		// every row and its audit trail), but they must not be correlated,
		// deduped, ranked, or rendered: a disproved, accepted, or
		// already-fixed finding, a row collapsed into another as a
		// duplicate, and a governed-suppressed row all describe risk the
		// operator has already decided about, so re-surfacing them in the
		// report would defeat triage and suppression policy alike.
		if reason := securityReportExclusionReason(rec); reason != "" {
			excluded[reason]++
			continue
		}
		findings = append(findings, securityFindingFromRecord(rec))
	}

	// Correlate agent and scanner findings one final time so anything
	// reported after the last ingest batch is cross-referenced (on both
	// stored rows and in the rendered report) before dedupe and ranking.
	if correlations := security.Correlate(findings); len(correlations) > 0 {
		for _, c := range correlations {
			if _, err := t.state.recordCorrelation(ctx, scanCtx.Repository, c.AgentFingerprint, c.ScannerFingerprint, c.Reason); err != nil {
				return Result{Content: fmt.Sprintf("failed to record finding correlation: %v", err), IsError: true}, nil
			}
		}
		security.ApplyCorrelations(findings, correlations)
	}

	canonical, clusterCount, dedupeDesc := dedupeSubmittedFindings(findings, scanCtx)
	if note := securityExclusionNote(excluded); note != "" {
		dedupeDesc = dedupeDesc + "; " + note
	}
	if truncated {
		dedupeDesc = dedupeDesc + fmt.Sprintf("; truncated to the %d highest-scoring findings of this execution — lower-scoring findings are stored but absent from this report and its SARIF artifact", securityFindingScopeMax)
	}
	rules, policyNote := submitScanPolicy(in, scanCtx, dedupeDesc)

	ranked := security.Rank(canonical, rules)

	now := time.Now().UTC()
	reportInput := security.ReportInput{
		ScanName:    scanCtx.ScanName,
		Namespace:   scanCtx.Namespace,
		Repository:  scanCtx.Repository,
		Revision:    scanCtx.Revision,
		Summary:     summary,
		CompletedAt: now,
		Ranked:      ranked,
	}

	// Second submit with unchanged findings: keep the existing completed
	// scan record (and its completed_at) instead of silently re-stamping it.
	//
	// The persisted counts deliberately stay whole-scan (every stored,
	// non-duplicate row, including false positives) rather than mirroring
	// the filtered report: findings are marked, never erased, and the
	// counts carry both total and open_<severity> keys. Consumers that must
	// ignore triaged-away findings already read the open keys — the
	// controller's failOnSeverity evaluation and the GitHub check summary,
	// which lists only status=open findings — so filtering the report does
	// not change any number those surfaces show. Rewriting the stored totals
	// here would instead break the unchanged-findings comparison above,
	// which compares them against SummarizeSecurityFindings output.
	var priorScan *store.SecurityScanRecord
	var counts map[string]int32
	if t.state.findingStore != nil {
		var done *Result
		priorScan, counts, done, err = t.loadPriorScanState(ctx, policyNote)
		if err != nil {
			return Result{Content: err.Error(), IsError: true}, nil
		}
		if done != nil {
			return *done, nil
		}
		if priorScan != nil && priorScan.StartedAt != nil {
			reportInput.StartedAt = *priorScan.StartedAt
		}
	} else {
		t.state.mu.Lock()
		counts = t.state.summarizeMemLocked()
		alreadyDone := t.state.memCompleted && securityCountsEqual(counts, t.state.memCounts)
		priorSummary := t.state.memSummary
		t.state.mu.Unlock()
		if alreadyDone {
			return alreadyFinalizedResult(scanCtx.ScanName, priorSummary, policyNote, counts), nil
		}
	}

	markdown := security.RenderMarkdown(reportInput)
	sarif, err := security.RenderSARIF(reportInput)
	if err != nil {
		return Result{Content: fmt.Sprintf("failed to render SARIF: %v", err), IsError: true}, nil
	}

	var artifactNote string
	if t.state.stateStore != nil {
		if _, err := t.state.stateStore.UpsertArtifact(ctx, scanCtx.SessionID, SecurityReportArtifactKind, markdown, "", "", nil); err != nil {
			return Result{Content: fmt.Sprintf("failed to save markdown report artifact: %v", err), IsError: true}, nil
		}
		if _, err := t.state.stateStore.UpsertArtifact(ctx, scanCtx.SessionID, SecuritySARIFArtifactKind, string(sarif), "", "", nil); err != nil {
			return Result{Content: fmt.Sprintf("failed to save SARIF artifact: %v", err), IsError: true}, nil
		}
		artifactNote = fmt.Sprintf("Report artifacts saved (%s, %s).", SecurityReportArtifactKind, SecuritySARIFArtifactKind)
	} else {
		artifactNote = "No artifact store available; report artifacts were not persisted."
	}

	if t.state.findingStore != nil {
		scan := priorScan
		if scan == nil {
			scan = &store.SecurityScanRecord{
				Namespace:  scanCtx.Namespace,
				ScanName:   scanCtx.ScanName,
				RunName:    scanCtx.RecordKey(),
				SessionID:  t.state.sessionIDPtr(),
				Repository: scanCtx.Repository,
				Revision:   scanCtx.Revision,
			}
		}
		scan.Status = "completed"
		scan.Summary = summary
		scan.Counts = counts
		scan.CompletedAt = &now
		// The record's session locates the report/SARIF artifacts. On a
		// shared execution record the row was opened by an earlier sibling
		// task run, so point it at the submitting (sink) run's session —
		// that is where these artifacts were just stored.
		if sess := t.state.sessionIDPtr(); sess != nil {
			scan.SessionID = sess
		}
		if _, err := t.state.findingStore.UpsertSecurityScan(ctx, scan); err != nil {
			return Result{Content: fmt.Sprintf("failed to update scan record: %v", err), IsError: true}, nil
		}
	} else {
		t.state.mu.Lock()
		t.state.memCompleted = true
		t.state.memSummary = summary
		t.state.memCounts = counts
		t.state.mu.Unlock()
	}

	var b strings.Builder
	fmt.Fprintf(&b, "Security scan %q finalized: %d finding(s) recorded, %d after dedupe, %d in the report.\n",
		scanCtx.ScanName, len(records), clusterCount, len(ranked))
	b.WriteString(policyNote + "\n")
	securitySeverityBreakdown(&b, counts)
	b.WriteString(artifactNote)
	if t.state.findingStore == nil {
		b.WriteString("\nIn-memory mode (no Postgres): findings, counts, and status events are scoped to this process and not persisted across runs; counts cover stored (fingerprint-merged) non-duplicate findings, matching the Postgres counting.")
	}
	return Result{Content: b.String()}, nil
}

package tools

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path"
	"path/filepath"
	"slices"
	"sort"
	"strings"

	"github.com/gratefulagents/gratefulagents/internal/securitytoolpacks"
)

// Fuzzing only compounds if the corpus outlives the run. Go keeps its seed
// corpus in `testdata/fuzz/<Target>` and the executor promotes what a campaign
// generated into that directory, so the inputs come back as artifacts. This
// file is the other half: the corpus is stored under a campaign identity that
// is independent of any single scan, restored into the workspace before the
// next campaign is staged, and re-persisted afterwards.
//
// Everything here is bounded on purpose. An unbounded corpus is a slow way to
// exhaust object storage, and a corpus restored from an untrusted path is a
// way to write outside the workspace, so entries are capped and every restored
// path is re-derived rather than trusted.
const (
	fuzzCorpusSchemaVersion    = "v2"
	fuzzCorpusLegacyVersion    = "v1"
	maxFuzzCorpusEntries       = 64
	maxFuzzCorpusBytes         = 1 << 20
	maxFuzzCorpusEntryBytes    = 64 << 10
	maxFuzzCorpusDocumentBytes = 2 << 20
	fuzzCorpusArtifactRoot     = "go-fuzz-corpus/"
)

type fuzzCorpusEntry struct {
	Path   string `json:"path"`
	Digest string `json:"digest"`
	Data   []byte `json:"data"`
}

type fuzzCorpusDocument struct {
	SchemaVersion  string            `json:"schema_version"`
	Campaign       string            `json:"campaign"`
	InputFormat    string            `json:"input_format,omitempty"`
	ProducerTool   string            `json:"producer_tool,omitempty"`
	TargetRevision string            `json:"target_revision,omitempty"`
	TargetDigest   string            `json:"target_digest,omitempty"`
	SnapshotDigest string            `json:"snapshot_digest,omitempty"`
	ParentDigest   string            `json:"parent_digest,omitempty"`
	Entries        []fuzzCorpusEntry `json:"entries"`
}

func canonicalFuzzCorpusEntries(entries []fuzzCorpusEntry) ([]fuzzCorpusEntry, error) {
	if len(entries) > maxFuzzCorpusEntries {
		return nil, fmt.Errorf("fuzz corpus has more than %d entries", maxFuzzCorpusEntries)
	}
	canonical := make([]fuzzCorpusEntry, 0, len(entries))
	seen := map[string]bool{}
	total := 0
	for _, entry := range entries {
		if len(entry.Data) == 0 || len(entry.Data) > maxFuzzCorpusEntryBytes || total+len(entry.Data) > maxFuzzCorpusBytes {
			return nil, fmt.Errorf("fuzz corpus entry exceeds storage bounds")
		}
		sum := sha256.Sum256(entry.Data)
		digest := "sha256:" + hex.EncodeToString(sum[:])
		if seen[digest] {
			continue
		}
		seen[digest] = true
		total += len(entry.Data)
		canonical = append(canonical, fuzzCorpusEntry{Path: fuzzCorpusEntryName(entry.Data), Digest: digest, Data: entry.Data})
	}
	return canonical, nil
}

func fuzzCorpusSnapshotDigest(document fuzzCorpusDocument) (string, error) {
	document.SnapshotDigest = ""
	encoded, err := json.Marshal(document)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(encoded)
	return "sha256:" + hex.EncodeToString(sum[:]), nil
}

func decodeFuzzCorpusDocument(raw []byte, campaign string, requireLineage bool) (fuzzCorpusDocument, error) {
	if len(raw) == 0 || len(raw) > maxFuzzCorpusDocumentBytes {
		return fuzzCorpusDocument{}, fmt.Errorf("fuzz corpus document exceeds storage bounds")
	}
	var document fuzzCorpusDocument
	if err := json.Unmarshal(raw, &document); err != nil {
		return fuzzCorpusDocument{}, err
	}
	if document.SchemaVersion != fuzzCorpusSchemaVersion && document.SchemaVersion != fuzzCorpusLegacyVersion {
		return fuzzCorpusDocument{}, fmt.Errorf("unsupported fuzz corpus schema %q", document.SchemaVersion)
	}
	if campaign != "" && document.Campaign != campaign {
		return fuzzCorpusDocument{}, fmt.Errorf("fuzz corpus campaign mismatch")
	}
	entries, err := canonicalFuzzCorpusEntries(document.Entries)
	if err != nil {
		return fuzzCorpusDocument{}, err
	}
	if document.SchemaVersion == fuzzCorpusSchemaVersion {
		if len(entries) != len(document.Entries) {
			return fuzzCorpusDocument{}, fmt.Errorf("fuzz corpus contains duplicate entries")
		}
		for i := range entries {
			if document.Entries[i].Digest != entries[i].Digest || document.Entries[i].Path != entries[i].Path {
				return fuzzCorpusDocument{}, fmt.Errorf("fuzz corpus entry integrity mismatch")
			}
		}
		if requireLineage && (document.InputFormat != "bytes" || document.ProducerTool == "" || document.TargetRevision == "" || document.TargetDigest == "") {
			return fuzzCorpusDocument{}, fmt.Errorf("rust fuzz corpus lineage is incomplete")
		}
		want, err := fuzzCorpusSnapshotDigest(document)
		if err != nil || document.SnapshotDigest != want {
			return fuzzCorpusDocument{}, fmt.Errorf("fuzz corpus snapshot digest mismatch")
		}
	} else if requireLineage {
		return fuzzCorpusDocument{}, fmt.Errorf("legacy Rust fuzz corpus has no authenticated lineage")
	}
	document.Entries = entries
	return document, nil
}

// fuzzCampaignIdentity names the campaign a corpus belongs to. It is derived
// from the repository, staged target root, package, and exact fuzz target,
// never from the scan or run, so re-running the same target continues the
// campaign without contaminating a sibling project in the same repository.
func fuzzCampaignIdentity(repository, targetRoot, pkg, target string) string {
	sum := sha256.Sum256([]byte(strings.Join([]string{repository, targetRoot, pkg, target}, "\x00")))
	return hex.EncodeToString(sum[:])[:32]
}

func fuzzCampaignTargetRoot(locator string) string {
	return path.Clean(filepath.ToSlash(strings.TrimSpace(locator)))
}

func fuzzCorpusObjectKey(namespace, tool, campaign string) string {
	return path.Join("security-tool-corpus", namespace, tool, campaign+".json")
}

// fuzzCorpusForArchive resolves a persisted corpus into the archive entries a
// campaign should start from. It deliberately returns content instead of
// writing files: restoring into the user's checkout would leave untracked
// inputs behind, and a cleanup step that runs "usually" is not a guarantee.
// A missing or unreadable corpus is not an error either — a campaign that has
// never run simply starts cold, and saying so is more useful than failing.
func fuzzCorpusForArchive(ctx context.Context, blobs SecurityToolRunBlobStore, key, packageRelative, target string) map[string][]byte {
	if blobs == nil || target == "" {
		return nil
	}
	raw, err := blobs.Get(ctx, key)
	if err != nil || len(raw) == 0 {
		return nil
	}
	document, err := decodeFuzzCorpusDocument(raw, "", false)
	if err != nil {
		return nil
	}
	directory := path.Join(packageRelative, "testdata", "fuzz", target)
	return fuzzCorpusEntriesForDirectory(document.Entries, directory)
}

func fuzzCorpusEntriesForDirectory(entries []fuzzCorpusEntry, directory string) map[string][]byte {
	out := make(map[string][]byte, len(entries))
	total := 0
	for _, entry := range entries {
		if len(out) >= maxFuzzCorpusEntries || len(entry.Data) == 0 || len(entry.Data) > maxFuzzCorpusEntryBytes {
			continue
		}
		if total+len(entry.Data) > maxFuzzCorpusBytes {
			break
		}
		total += len(entry.Data)
		// The stored path is never trusted: the entry name is re-derived from
		// the content, so a hostile corpus document cannot escape this directory.
		out[path.Join(directory, fuzzCorpusEntryName(entry.Data))] = entry.Data
	}
	return out
}

func fuzzCorpusEntryName(data []byte) string {
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:])[:32]
}

// persistFuzzCorpus merges the inputs a campaign produced into the stored
// corpus. Entries are deduplicated by digest and the document stays bounded,
// so a long-running campaign cannot grow the object without limit; the oldest
// entries are the ones dropped, because the newest inputs are the ones the
// fuzzer most recently found interesting.
type fuzzCorpusLineage struct {
	InputFormat    string
	ProducerTool   string
	TargetRevision string
	TargetDigest   string
}

func persistFuzzCorpus(ctx context.Context, blobs SecurityToolRunBlobStore, key, campaign string, fresh []fuzzCorpusEntry) (int, error) {
	return persistFuzzCorpusWithLineage(ctx, blobs, key, campaign, fuzzCorpusLineage{}, fresh)
}

func persistFuzzCorpusWithLineage(ctx context.Context, blobs SecurityToolRunBlobStore, key, campaign string, lineage fuzzCorpusLineage, fresh []fuzzCorpusEntry) (int, error) {
	if blobs == nil {
		return 0, nil
	}
	document := fuzzCorpusDocument{SchemaVersion: fuzzCorpusSchemaVersion, Campaign: campaign, InputFormat: lineage.InputFormat, ProducerTool: lineage.ProducerTool, TargetRevision: lineage.TargetRevision, TargetDigest: lineage.TargetDigest}
	if raw, getErr := blobs.Get(ctx, key); getErr == nil && len(raw) > 0 {
		stored, decodeErr := decodeFuzzCorpusDocument(raw, campaign, false)
		if decodeErr != nil {
			return 0, fmt.Errorf("decode stored fuzz corpus: %w", decodeErr)
		}
		document.Entries = stored.Entries
		if stored.SchemaVersion == fuzzCorpusSchemaVersion {
			document.ParentDigest = stored.SnapshotDigest
		}
	}
	known := map[string]bool{}
	for _, entry := range document.Entries {
		known[entry.Digest] = true
	}
	added := 0
	for _, entry := range fresh {
		if len(entry.Data) == 0 || len(entry.Data) > maxFuzzCorpusEntryBytes {
			continue
		}
		sum := sha256.Sum256(entry.Data)
		digest := "sha256:" + hex.EncodeToString(sum[:])
		if known[digest] {
			continue
		}
		known[digest] = true
		document.Entries = append(document.Entries, fuzzCorpusEntry{Path: fuzzCorpusEntryName(entry.Data), Digest: digest, Data: entry.Data})
		added++
	}
	if added == 0 {
		return 0, nil
	}
	document.Entries = boundFuzzCorpus(document.Entries)
	canonical, err := canonicalFuzzCorpusEntries(document.Entries)
	if err != nil {
		return 0, err
	}
	document.Entries = canonical
	document.SnapshotDigest, err = fuzzCorpusSnapshotDigest(document)
	if err != nil {
		return 0, err
	}
	encoded, err := json.Marshal(document)
	if err != nil {
		return 0, err
	}
	if err := blobs.Put(ctx, key, encoded, "application/json"); err != nil {
		return 0, err
	}
	return added, nil
}

// boundFuzzCorpus keeps the newest entries within both the count and the byte
// budget.
func boundFuzzCorpus(entries []fuzzCorpusEntry) []fuzzCorpusEntry {
	if len(entries) > maxFuzzCorpusEntries {
		entries = entries[len(entries)-maxFuzzCorpusEntries:]
	}
	total := 0
	for i, entry := range slices.Backward(entries) {
		total += len(entry.Data)
		if total > maxFuzzCorpusBytes {
			return entries[i+1:]
		}
	}
	return entries
}

// goFuzzCorpusArtifacts turns the run's returned artifacts into corpus
// entries. Only artifacts the Go pack itself produced are considered, and each
// is re-hashed from its bytes rather than trusted.
func goFuzzCorpusArtifacts(ctx context.Context, blobs SecurityToolRunBlobStore, artifacts []runSecurityToolArtifact) []fuzzCorpusEntry {
	if blobs == nil {
		return nil
	}
	entries := make([]fuzzCorpusEntry, 0, len(artifacts))
	for _, artifact := range artifacts {
		if !strings.HasPrefix(artifact.Name, fuzzCorpusArtifactRoot) || artifact.ObjectKey == "" {
			continue
		}
		data, err := blobs.Get(ctx, artifact.ObjectKey)
		if err != nil || len(data) == 0 || len(data) > maxFuzzCorpusEntryBytes {
			continue
		}
		sum := sha256.Sum256(data)
		entries = append(entries, fuzzCorpusEntry{
			Path:   strings.TrimPrefix(artifact.Name, fuzzCorpusArtifactRoot),
			Digest: "sha256:" + hex.EncodeToString(sum[:]),
			Data:   data,
		})
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].Digest < entries[j].Digest })
	return entries
}

// goFuzzCampaignNote is what the agent is told about corpus provenance, so a
// clean result is never read as "nothing is there" when it was simply a cold
// first campaign.
func goFuzzCampaignNote(restored, persisted int) string {
	if restored == 0 {
		return fmt.Sprintf("fuzz corpus: cold start, persisted %d new input(s) for the next campaign", persisted)
	}
	return fmt.Sprintf("fuzz corpus: restored %d seed input(s), persisted %d new input(s) for the next campaign", restored, persisted)
}

// goFuzzCorpusForArchive resolves this campaign's persisted corpus into archive
// entries, keyed by their path inside the staged target.
func (t *runSecurityToolTool) goFuzzCorpusForArchive(ctx context.Context, in runSecurityToolInput, local string) map[string][]byte {
	if in.Tool != "go-fuzz-tests" {
		return nil
	}
	pkg, target := in.Arguments["package"], securitytoolpacks.GoFuzzTargetName(in.Arguments["fuzz"])
	if pkg == "" || target == "" {
		return nil
	}
	packageDir := securitytoolpacks.GoFuzzPackageDir(local, pkg)
	relative, err := filepath.Rel(local, packageDir)
	if err != nil || relative == "." || strings.HasPrefix(relative, "..") {
		relative = ""
	}
	campaign := fuzzCampaignIdentity(t.state.scanCtx.Repository, fuzzCampaignTargetRoot(in.Target.Locator), pkg, target)
	key := fuzzCorpusObjectKey(t.deps.Namespace, in.Tool, campaign)
	return fuzzCorpusForArchive(ctx, t.deps.Blobs, key, filepath.ToSlash(relative), target)
}

// countInjectedGoFuzzInputs excludes persisted entries that are already
// checked into the target and therefore will not be injected into its archive.
func countInjectedGoFuzzInputs(local string, injected map[string][]byte) int {
	count := 0
	for name := range injected {
		if _, err := os.Lstat(filepath.Join(local, filepath.FromSlash(name))); os.IsNotExist(err) {
			count++
		}
	}
	return count
}

// addGoFuzzCampaignMetadata carries the trusted restore count into the
// executor. Its path is reserved so target content cannot forge provenance.
func addGoFuzzCampaignMetadata(local string, restored int, injected map[string][]byte) (map[string][]byte, error) {
	reserved := filepath.Join(local, filepath.FromSlash(securitytoolpacks.GoFuzzCampaignMetadataPath))
	if _, err := os.Lstat(reserved); err == nil {
		return nil, fmt.Errorf("target contains reserved campaign metadata path %s", securitytoolpacks.GoFuzzCampaignMetadataPath)
	} else if !os.IsNotExist(err) {
		return nil, fmt.Errorf("inspect reserved campaign metadata path: %w", err)
	}
	metadata, err := securitytoolpacks.EncodeGoFuzzCampaignMetadata(restored)
	if err != nil {
		return nil, err
	}
	if injected == nil {
		injected = map[string][]byte{}
	}
	injected[securitytoolpacks.GoFuzzCampaignMetadataPath] = metadata
	return injected, nil
}

// persistGoFuzzCorpus stores what this campaign produced so the next one
// starts from it, and returns the note describing corpus provenance.
func (t *runSecurityToolTool) persistGoFuzzCorpus(ctx context.Context, in runSecurityToolInput, restored int, artifacts []runSecurityToolArtifact) string {
	if in.Tool != "go-fuzz-tests" {
		return ""
	}
	pkg, target := in.Arguments["package"], securitytoolpacks.GoFuzzTargetName(in.Arguments["fuzz"])
	if pkg == "" || target == "" {
		return ""
	}
	campaign := fuzzCampaignIdentity(t.state.scanCtx.Repository, fuzzCampaignTargetRoot(in.Target.Locator), pkg, target)
	key := fuzzCorpusObjectKey(t.deps.Namespace, in.Tool, campaign)
	persisted, err := persistFuzzCorpus(ctx, t.deps.Blobs, key, campaign, goFuzzCorpusArtifacts(ctx, t.deps.Blobs, artifacts))
	if err != nil {
		return "fuzz corpus could not be persisted: " + err.Error()
	}
	return goFuzzCampaignNote(restored, persisted)
}

const rustFuzzCorpusFamily = "rust-libfuzzer-v1"

func rustFuzzCampaignNote(restored, persisted int) string {
	if restored == 0 {
		return fmt.Sprintf("Rust fuzz corpus: cold start, persisted %d new input(s) for the next compatible campaign", persisted)
	}
	return fmt.Sprintf("Rust fuzz corpus: restored %d input(s), persisted %d new input(s) for the next compatible campaign", restored, persisted)
}

func (t *runSecurityToolTool) rustFuzzCorpusCoordinates(in runSecurityToolInput) (string, string) {
	target := in.Arguments["fuzz_target"]
	campaign := fuzzCampaignIdentity(t.state.scanCtx.Repository, fuzzCampaignTargetRoot(in.Target.Locator), rustFuzzCorpusFamily, target)
	return campaign, fuzzCorpusObjectKey(t.deps.Namespace, rustFuzzCorpusFamily, campaign)
}

func (t *runSecurityToolTool) rustFuzzCorpusForArchive(ctx context.Context, in runSecurityToolInput) map[string][]byte {
	if in.Tool != "cargo-fuzz" || in.Arguments["fuzz_target"] == "" || t.deps.Blobs == nil {
		return nil
	}
	campaign, key := t.rustFuzzCorpusCoordinates(in)
	raw, err := t.deps.Blobs.Get(ctx, key)
	if err != nil || len(raw) == 0 {
		return nil
	}
	document, err := decodeFuzzCorpusDocument(raw, campaign, true)
	if err != nil {
		return nil
	}
	return fuzzCorpusEntriesForDirectory(document.Entries, path.Join("fuzz", "corpus", in.Arguments["fuzz_target"]))
}

func addRustFuzzCampaignMetadata(local string, restored int, injected map[string][]byte) (map[string][]byte, error) {
	reserved := filepath.Join(local, filepath.FromSlash(securitytoolpacks.RustFuzzCampaignMetadataPath))
	if _, err := os.Lstat(reserved); err == nil {
		return nil, fmt.Errorf("target contains reserved campaign metadata path %s", securitytoolpacks.RustFuzzCampaignMetadataPath)
	} else if !os.IsNotExist(err) {
		return nil, fmt.Errorf("inspect reserved campaign metadata path: %w", err)
	}
	metadata, err := securitytoolpacks.EncodeRustFuzzCampaignMetadata(restored)
	if err != nil {
		return nil, err
	}
	if injected == nil {
		injected = map[string][]byte{}
	}
	injected[securitytoolpacks.RustFuzzCampaignMetadataPath] = metadata
	return injected, nil
}

func rustFuzzCorpusArtifacts(ctx context.Context, blobs SecurityToolRunBlobStore, artifacts []runSecurityToolArtifact) ([]fuzzCorpusEntry, error) {
	if blobs == nil {
		return nil, nil
	}
	crashes := map[string]bool{}
	for _, artifact := range artifacts {
		if strings.HasPrefix(artifact.Name, "cargo-fuzz-crash/") {
			crashes[artifact.Digest] = true
		}
	}
	entries := make([]fuzzCorpusEntry, 0, min(len(artifacts), maxFuzzCorpusEntries))
	seenKeys := map[string]bool{}
	total := int64(0)
	for _, artifact := range artifacts {
		if !strings.HasPrefix(artifact.Name, "cargo-fuzz-corpus/") || artifact.ObjectKey == "" {
			continue
		}
		if len(entries) >= maxFuzzCorpusEntries || seenKeys[artifact.ObjectKey] {
			continue
		}
		seenKeys[artifact.ObjectKey] = true
		if artifact.MediaType != "application/octet-stream" || artifact.Size <= 0 || artifact.Size > maxFuzzCorpusEntryBytes || total+artifact.Size > maxFuzzCorpusBytes {
			return nil, fmt.Errorf("cargo-fuzz corpus artifact %q violates storage bounds", artifact.Name)
		}
		data, err := blobs.Get(ctx, artifact.ObjectKey)
		if err != nil {
			return nil, err
		}
		if int64(len(data)) != artifact.Size {
			return nil, fmt.Errorf("cargo-fuzz corpus artifact %q size mismatch", artifact.Name)
		}
		sum := sha256.Sum256(data)
		digest := "sha256:" + hex.EncodeToString(sum[:])
		canonicalName := "cargo-fuzz-corpus/" + strings.TrimPrefix(digest, "sha256:")[:32]
		if digest != artifact.Digest || artifact.Name != canonicalName {
			return nil, fmt.Errorf("cargo-fuzz corpus artifact %q failed integrity validation", artifact.Name)
		}
		if crashes[digest] {
			continue
		}
		total += artifact.Size
		entries = append(entries, fuzzCorpusEntry{Path: canonicalName, Digest: digest, Data: data})
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].Digest < entries[j].Digest })
	return entries, nil
}

func (t *runSecurityToolTool) persistRustFuzzCorpus(ctx context.Context, in runSecurityToolInput, targetRevision, targetDigest string, restored int, artifacts []runSecurityToolArtifact) string {
	if in.Tool != "cargo-fuzz" || in.Arguments["fuzz_target"] == "" {
		return ""
	}
	entries, err := rustFuzzCorpusArtifacts(ctx, t.deps.Blobs, artifacts)
	if err != nil {
		return "Rust fuzz corpus could not be verified: " + err.Error()
	}
	campaign, key := t.rustFuzzCorpusCoordinates(in)
	lineage := fuzzCorpusLineage{InputFormat: "bytes", ProducerTool: in.Tool, TargetRevision: targetRevision, TargetDigest: targetDigest}
	persisted, err := persistFuzzCorpusWithLineage(ctx, t.deps.Blobs, key, campaign, lineage, entries)
	if err != nil {
		return "Rust fuzz corpus could not be persisted: " + err.Error()
	}
	return rustFuzzCampaignNote(restored, persisted)
}

